// مولّدة آلياً بواسطة scripts/split-history.mjs — لا تُعدَّل يدوياً.
export default [{"id":4199,"title":"ثويني بن عبد الله شيخ المنتفق يستولي على البصرة .","date":["العام الهجري :1201","العام الميلادي :1786"],"text":"سار ثويني بن عبد الله شيخ المنتفق من نجدٍ إلى البصرة فدخَلَها وحبس متسَلِّمَها من قِبَل الدولة العثمانية, فلما استقَرَّ فيها طلب من رؤساء البصرة وأعيانِهم أن يكتبوا للسلطان العثماني أن يجعَلَه أميرًا عليهم ويرسلوا كتابًا بطلبهم مع مفتي البصرة، فلما عرض المفتي على السلطانِ ما جاء به أطلع السلطانُ وزراءَه على الطلب فقالوا له: هذا أعرابيٌّ متغَلِّبٌ، فغَضِبَ السلطانُ وكاد يفتِكُ بالمفتي."},{"id":4200,"title":"الاحتلال الإنجليزي للملايو .","date":["العام الهجري :1201","العام الميلادي :1786"],"text":"بدأت المصالحُ الإنجليزية في الملايو من الناحية التجارية، وكان سلطان صولو قد أعطى الإنجليزَ منطقةً في شمالي جزيرة بورنيو (أندونيسيا) لتقيمَ عليها تجارتَها، فعملت الشركة البريطانية المعروفة بشركة الهند الشرقية البريطانية لإقامةِ قاعدةٍ لها في الملايو، وتمكَّنت من ذلك بسهولة, واشترت ميناء سنغافورة أيضًا، ثم أخذ الاستعمارُ البريطاني بالتوسُّعِ منذ عام 1291هـ في الملايو، وتكرَّس على شكلِ معاهداتٍ مع سلاطينِ الولايات، حتى أصبحت تستطيعُ أن تجمَعَ الإماراتِ وتقَسِّمَها كما تشاء. توطَّدَ استعمار البريطانيين على جزيرة الملايو كافة عام 1306هـ، وهكذا خضعت ماليزيا للاستعمار البريطاني، وكان لضَعفِ سلاطينها أكبَرُ الأثرِ في ذلك."},{"id":4201,"title":"شيخ قبيلة قحطان يبايع الشيخ محمد بن عبد الوهاب على نصرة الدعوة .","date":["العام الهجري :1201","العام الميلادي :1786"],"text":"وفد هادي بن قرملة شيخُ عموم قبيلة قحطان في نجدٍ على الشيخِ والإمام عبد العزيزِ في الدرعية، وبايع على دين الله ورسولِه والسمع والطاعة, وصدق معهم وجاهدَ بعُربانه وبذلَ نفسَه في نصرةِ الدعوةِ وأهلِها."},{"id":4202,"title":"ثويني بن عبد الله شيخ المنتفق يغزو القصيم .","date":["العام الهجري :1201","الشهر القمري : محرم","العام الميلادي :1786"],"text":"بعد قَبولِ الإمام عبد العزيز سعدونَ بنَ عريعر في الدرعية، سار ثويني بن عبد الله شيخ المنتفق ومعه العساكرُ العظيمة من المنتفق وأهل الهجر وجميع أهل الزبير وعربان شمر وطي ومعه من العَدَد والعُدَّة ما يفوق الحصرَ، يريد غزوَ القصيم، فوصل التنومة وهي من قرى القصيم ونازلها بجموعِه وحاصَرَها وضربها بالمدافِعِ، لكِنَّه لم يتمكن من دخولهِا إلا بمكيدةٍ عن طريق عثمان آل حمد من أهل الزلفي، فدخلها عليهم خديعةً، ثم أخذ التنومة عنوةً واستأصل أهلَها قتلًا ونهبًا, ثم ارتحل منها وقصد بُريدة ونزل بها وحصل بينه وبين أهلِها شيءٌ من القتال وأثناء الحصارِ بلغه أنَّه وقع في أوطانه اختلافٌ وخلل، فاضطر أن يرجِعَ إلى بلده, وكان عبد المحسن بن سرداح رئيسُ بني خالد قد خرج بعربانِه من بني خالد يريدُ القصيم نصرةً لثويني، فلما بلغ الدهناءَ بلَغَه رجوعُ ثويني فرجع من حيث جاء وتفَرَّقت كَلِمتُهم ولم يتمَّ لهم ما أرادوا."},{"id":4203,"title":"طرد ثويني شيخ المنتفق من البصرة بعد هزيمته من قبل صاحب بغداد .","date":["العام الهجري :1202","العام الميلادي :1787"],"text":"لما تحقَّق سليمان باشا صاحب بغداد ما أحدثَه ثويني شيخ المنتفق في البصرة مِن تولِّي حكمِها بعد  طَردِ متسَلِّمها، سار بعساكره إلى البصرة، فالتقى مع ثويني الذي جمع عُربانَ المنتفق وأهل الزبير بالقرب من سوق الشيوخ خارجَ البصرة، فاقتتلوا قتالًا شديدًا انهزم فيه ثويني هزيمةً شنيعةً فَرَّ على إثرها بمن بقي معه من جنوده إلى الجهراء، ثم رحل إلى الصمان ديار بني خالد، وتولى حمود بن ثامر رئاسةَ المنتفق، وعَيَّن سليمان باشا أغا مصطفى على البصرة."},{"id":4204,"title":"أخذُ البيعة بولاية العهد للأمير سعود بن عبد العزيز .","date":["العام الهجري :1202","العام الميلادي :1787"],"text":"أمر الشيخُ محمد بن عبد الوهاب جميعَ أهل نجدٍ أن يبايعوا الأميرَ سعود بن عبد العزيز بعد أبيه، وذلك بإذن الإمام عبد العزيز، فبايعه أهلُ نجد جميعًا."},{"id":4205,"title":"قدوم وفد من وادي الدواسر للدرعية بعد انتشار الدعوة فيهم .","date":["العام الهجري :1202","العام الميلادي :1787"],"text":"بعد أن بايع ربيع بن زيد وأخوه بدن الشيخَ محمدًا والإمام عبد العزيز عام 1199, وعادا إلى الوادي بدأا بالدعوة للتوحيد ونبْذِ مظاهر الشرك والبدع، فنفر منهما أهلُ الوادي ودخلا معهم في حربٍ طويلة استعان فيها أهل الوادي بصاحبِ نجران المكرمي ليقضوا على ربيع بن زيد وأتباعه ودعوته، لكِنْ دون جدوى, وقد حصل ربيعٌ على مالٍ وسلاح من الإمام عبد العزيز في حربِه لِقَومِه حتى تمكَّن من أهل الوادي، فأرسلوا إلى ربيع يطلبونَ منه أن يبايعوه على الدِّينِ والسَّمع والطاعة، ثم وفد بهم إلى الشيخِ  محمد والإمام عبد العزيز ليبايعوهما على السمع والطاعة والالتزام بشرائع الدين, فأكرمهم الأميرُ غايةَ الإكرام وطلبوا معلِّمًا لهم يعلِّمُهم التوحيدَ، فأرسل معهم الشيخُ عبدَ الله بن فاضل, بعد ستة أشهُرٍ نقض الرجبان والوداعون العهد فأرسل عبد العزيز لهم سليمان بن عفيصان فدهمهم في بلادِهم، فطلبوا الأمانَ والقدوم على عبد العزيز، فقَدِموا عليه في الدرعية، فبايعوه وشرط عليهم ألفي ريال نكالًا وألفَ بندقٍ فسلَّموها له."},{"id":4206,"title":"غزو ابن عفيصان قطر والأحساء .","date":["العام الهجري :1202","العام الميلادي :1787"],"text":"غزا سُليمان بن عفيصان إلى جهة الشرق، فأغار على أهل قطر فأصاب كثيرًا مِن آل أبي رميح وأخذ منهم كثيرًا من الخيل والغنم والسلاح, ثم سار إلى الأحساءِ, فأغار على الجشة إحدى قرى الأحساء، فأصاب منهم رجالًا."},{"id":4207,"title":"وفاة الشريف سرور بن مساعد أمير مكة .","date":["العام الهجري :1202","الشهر القمري : ربيع الآخر","العام الميلادي :1788"],"text":"هو الشَّريفُ سرورُ بنُ مساعد بن سعيد بن سعد بن زيد بن محسن بن حسين بن حسن بن أبي نُمي، الذي طار صيتُه في الآفاقِ وبلغ من المجدِ والسعيِ في أعمال الخيرِ وتأمين السُّبُل ما لم يبلُغْ إليه أحدٌ من آبائه، ولقد كانت أحاديثُ الوافدين للحجِّ إلى بيت الله الحرام تخبِرُ عنه بأخبار تسُرُّ القلوبَ وتشَنِّف الأسماعَ وترَوِّح الطباعَ، وكان عظيمَ السَّطوة شديدَ الصَّولة قامعًا للفساد راعيًا لمصالح العباد، كثيرَ الغزو لمَرَدة الأعراب الذين يتخطَّفون الناس في الطرقات، وتوفي في يوم 18 ربيع الثاني، وعمره 35 سنة، ومدَّة ولايته 15 سنة وخمسة أشهر وثمانية أيَّام، وصُلِّي عليه عند الكعبة ودُفن بالمعلَّاة. وقام مقامَه بعد وفاته أخوه عبد المعين، ثمَّ رغِبَ عن الأمرِ لأخيه غالب بعد أيامٍ يسيرةٍ مِن ولايته."},{"id":4208,"title":"إعلان الإمبراطور النمساوي جوزيف الثاني الحرب على الدولة العثمانية .","date":["العام الهجري :1202","الشهر القمري : جمادى الأولى","العام الميلادي :1788"],"text":"أعلن الإمبراطورُ النمساوي جوزيف الثاني الحربَ على الدولة العثمانية؛ وذلك تأييدًا منه لحليفتِه روسيا التي كانت تحارب العثمانيين منذ 5 أشهر حول جزيرة القرم."},{"id":4209,"title":"انتصار الجيش العثماني على الجيش النمساوي في معركة \"شبش\" .","date":["العام الهجري :1202","الشهر القمري : ذي الحجة","العام الميلادي :1788"],"text":"انتصر الجيشُ العثماني بقيادة السلطانِ عبد الحميد الأول على الجيشِ النمساوي الذي يقودُه الإمبراطور جوزيف الثاني، وذلك في معركة \"شبش\" داخِلَ حدود النمسا. قامت مجموعةٌ مِن كشَّافة الجيش النمساوي بالتقَدُّم؛ لاستطلاعِ موقِفِ الجيش العثماني. وفي طريقِهم وجدوا تجمُّعًا للغجرِ حيث يباعُ الخمرُ، فجَلَسوا وسَكِروا حتي الثمالة. بعد قليلٍ جاءت مجموعةٌ مِن المشاة النمساويين للانضمامِ للمجموعةِ الأولى فرفَضوا انضمامَهم لهم واتَّخذوا وضعَ الدِّفاعِ, ثمَّ عمَّت حالةٌ من الفوضى وصلت إلى المعسكَرِ، وحدث قتالٌ بينهم. كلُّ طرفٍ منهم يظُنُّ أنَّ الطرفَ الآخِرَ هم الأتراكُ، فوقعت حربٌ شديدةٌ بينهم، قُتِلَ منهم أعدادٌ كبيرة، قيل بلغ عددُ القتلى 10 آلاف قتيل, فلما وصل الجيشُ العثماني بقيادة السلطان عبد الحميد الأوَّلِ ومعه الصدرُ الأعظمُ قوجا يوسف باشا تمكَّنَ مِن أسرِ 50 ألفَ نمساوي في هذه المعركةِ التي تعتبر أكبَرَ انتصارٍ حَقَّقه السلطانُ في عهدِه، والذي توفِّيَ بالسكتة القلبية في طريقِ عودتِه قبل وصولِه إسطنبول."},{"id":4210,"title":"فشل تحالف روسي نمساوي لطرد الأتراك من أوروبا .","date":["العام الهجري :1203","العام الميلادي :1788"],"text":"على الرغمِ من اعتراف الدولة العثمانية بضم القرم لروسيا سنة 1186 إلَّا أنَّ قصْدَ روسيا ومساعديها انتشابُ القِتالِ؛ ليحظى كل منهم بأمنيتِه؛ لذلك عَمِلوا على إثارة خاطر الدولة العثمانية وإيقاعِها في الحربِ، فأخذوا في تحصين ميناء سباستوبول وأقاموا ترسانةً عظيمةً في ميناء كرزن، وأنشؤوا عمارةً بحرية من الطراز الأول في البحرِ الأسود وأرسلوا جواسيسَهم إلى بلاد اليونان وولايتي الفلاخ من البغدان؛ لتهييجِ النصارى على الدولةِ العثمانية، ثم توصَّلت كاترين الثانية إلى إدخال هرقل ملك الكرج تحت حمايتِها مُقدمةً لفتحِ بلادِه نهائيًّا وأخيرًا في سنة 1787م. ساحت كاترين في البلاد الجنوبية وبلاد القرم بأبَّهةٍ واحتفالٍ زائد، وأقام لها القائِدُ بوتمكين أقواسَ نصرٍ كُتِب عليها طريقُ بيزنطة، فعَلِمت الدولةُ العثمانية من كلِّ هذه الأحوالِ أنَّها تقصِدُ محاربتَها ثانيًا، وتأكَّد لها هذا العزمُ لَمَّا تقابلت كاترين في سياحتِها هذه مع ملك بولونيا وإمبراطور النمسا؛ ولذلك أرادت الدولةُ العثمانية هي المبادرةَ بإعلان الحربِ قبلَ تمامِ استعدادِ أعدائِها؛ ولإيجادِ سَبَبٍ له أرسلت بلاغًا إلى سفير روسيا بالأستانة المسيو جولغا كوف في صيف سنة 1787م تطلب منه تسليمَ موروكرداتو حاكِمِ الفلاخ الذي كان عصى الدولة والتجأ إلى روسيا، والتنازلَ عن حماية بلاد الكرج بما أنَّها تحت سيادة الدولةِ، وعزْلَ بعضِ قناصِلِها المهيِّجين للأهالي، وقبولَ قناصِلَ للدولة في موانئ البحر الأسود، وأن يكون لها الحَقُّ في تفتيش مراكِبِ روسيا التجارية التي تمرُّ مِن بوغاز الأستانة للتحقيقِ مِن أنَّها لا تحمِلُ سِلاحًا أو ذخائِرَ حربية, فرفض السفيرُ هذه الطلباتِ إلَّا بإذن دولته، فأعلن الباب العالي الحربَ عليها فورًا، وسجن سفيرَها في أغسطس سنة 1787م, ولما كان الجنرال بوتمكين لم يتِمَّ معداتِ الحربِ وقعَ في حيص بيص، وكتب إلى كاترين يخبرُها بعدمِ صلاحية البقاء في القرمِ ناصِحًا لها بإخلائِها في أقربِ وقتٍ، لا سيما وأنَّ مَلِكَ السويد جوستاف الثالث أراد انتهازَ هذه الفرصة لاسترجاعِ ما فقدَتْه دولتُه من المقاطعات والبلادِ التي أخذَتْها منها روسيا، لكِنْ لم تَثنِ هذه الحوادِثُ هِمَّةَ هذه الإمبراطورة التي أعانتها الأيامُ، بل كتبت للجنرال بوتمكين بعدمِ انتظار العثمانيين، والسيرِ بكلِّ شجاعةٍ وإقدامٍ على مدينتي بندر وأوزي، فصدع بأمرِها وسار نحو أوزي فحاصرها مدةً، ثم دخلها عَنوةً في 30 ربيع الآخر سنة 1203 هـ 19 نوفمبر سنة 1788م وفي هذه الاثناء كانت النمسا أعلنت الحرب على الدولة العثمانية مساعدة لروسيا، وحاول إمبراطورها يوسف الثاني الاستيلاءَ على مدينة بلغراد، فعاد بالخيبة إلى مدينة تمسوار؛ حيث اقتفى أثرَه الجيشُ العثماني وانتصر عليه نصرًا مُبينًا؛ ولذلك ترك الإمبراطور قيادةَ جيوشِه إلى القائد لودن."},{"id":4211,"title":"احتلال الجيش الروسي قلعة \"أوزي\" إحدى القلاع العثمانية .","date":["العام الهجري :1203","الشهر القمري : ربيع الأول","العام الميلادي :1788"],"text":"احتلَّ الجيشُ الروسي قلعة \"أوزي\" في أوكرانيا، أهَمَّ القلاعِ العثمانية على البحر الأسود، وارتكب الروسُ فيها مجزرةً رهيبةً راح ضحيَّتَها 25 ألف تركي مِن الرجال والنساء والأطفال، بعد أن قاموا بتعذيبِهم بشِدَّةٍ, وكان لخبرِ سقوطِ أوزي بيَدِ الروس وذبحِ أهلِها المدنيين بالسيفِ أكبَرُ الأثَرِ على السلطان عبد الحميد الأول؛ حيث أُصيب على إثر الخبَرِ بنزيفٍ في المخِّ توفِّيَ بعده."},{"id":4212,"title":"وفاة السلطان العثماني عبد الحميد الأول وقيام السلطان سليم الثالث بعده .","date":["العام الهجري :1203","الشهر القمري : رجب","العام الميلادي :1789"],"text":"هو السلطانُ العثماني عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث، ولِدَ سنة 1137هـ تولى الحكمَ عام 1187هـ/1773م بعد وفاة أخيه مصطفى الثالث، وكان محجوزًا في قصرِه مدَّةَ حكم أخيه مصطفى الثالث، استطاعت روسيا في عهدِه أن تحقِّقَ نصرًا على العثمانيين في معاهدة كيتشوك كاينارجي، وطلب الصدرُ الأعظمُ الصلحَ والمفاوضة، وتمَّ ذلك في مدينة قاينارجة في بلغاريا على البحر الأسود عام 1187هـ. في هذه الظروفِ الحَرِجة توفِّي السلطان عبد الحميد الأول، ووهنت عزيمةُ الجند ودخل اليأسُ قلوبَهم، واستغَلَّ الأعداء ما حدث وتضافرت جهودُهم لإضعافِ العثمانيين، وتمكَّنوا من النصر؛ ففي 31 تموز و22 أيلول عام 1789م استولى الروس على مدينة بندر الحصينة واحتلُّوا معظم الفلاخ والبغدان وبسارابيا، ودخل النمساويون بلغراد وبلاد الصرب التي رُدَّت بعد ذلك للعثمانيين بمقتضى معاهدة زشتوي. توفِّيَ السلطان عبد الحميد الأول متأثرًا بنزيفٍ في المخِّ بعد سماعه خبرَ سقوطِ قلعة أوزي بيد الروسِ وذبح أهلها بطريقةٍ بشعة، دام في الحُكمِ خمسة عشر عامًا وعدة أشهر، وتولى بعده ابنُ أخيه سليم الثالث بن مصطفى الثالث، ويعتبرُ هذا السلطانُ هو أولَ سلاطين عصر الانحطاط، ثمَّ استمَرَّت السلطنةُ في سلالة السلطان عبد الحميد الأول إلى نهايةِ الدولة."},{"id":4213,"title":"منح الدولة العثمانية مبلغ مليار آقجه، للسويد طبقا لمعاهدة \"بيقوز\" .","date":["العام الهجري :1203","الشهر القمري : شوال","العام الميلادي :1789"],"text":"منحت الدولة العثمانية مبلغ مليار آقجه (العملة العثمانية) للسويد طبقًا لمعاهدة \"بيقوز\"؛ وذلك نظيرًا للدور الذي لعبته السويد في تثبيتِ قسمٍ مِن الجيش الروسي على الحدودِ مع السويد إبَّان الحرب العثمانية - الروسية."},{"id":4214,"title":"معركة \"فوشكاني\" وانتصار الجيش العثماني على الجيش الروسي والألماني .","date":["العام الهجري :1203","الشهر القمري : ذي القعدة","العام الميلادي :1789"],"text":"انتصر الوزيرُ والقائد العثماني \"كمانكش مصطفى باشا\" بقوَّاته البالغة 30000 جندي على جيش الاتحاد الروسي الألماني في معركة \"فوشكاني\" الواقعة قربَ فرع للطونة بين الأفلاقِ والبغدان"},{"id":4215,"title":"استيلاء الروس والنمساويين على بعض المناطق التابعة للعثمانيين .","date":["العام الهجري :1204","العام الميلادي :1789"],"text":"تولَّى السلطانُ سليم الثالث وما زالت الحربُ دائرةً بين الدولة العثمانية والروس، فأعطى السلطانُ وقتَه وجهده لقتالهم، غيرَ أنَّ جنده قد ضَعُفَت همَّتهم، في المقابِلِ اتحدت الجيوش الروسية والنمساوية ضِدَّ الدولة العثمانية، فتمكَّنت روسيا من الاستيلاء على الأفلاق والبغدان وبساربيا، كما استطاعت النمسا احتلالَ بلاد الصرب ودخلت بلغراد أيضًا، غيرَ أن هذا الاتفاق الروسي النمساوي لم يدُمْ طويلًا؛ إذ انصرف إمبراطور النمسا ليوبولد الثاني الذي خلَّف جوزيف الثاني إلى الثورة الفرنسية، وما حدث من نتائج من قَتلِ الملك لويس السادس عشر ملك فرنسا، فخاف مَلِكُ النمسا أن تمتَدَّ الثورة إلى بلاده، فحرص على مصالحة الدولة العثمانية؛ ونتيجةً لذلك أعيدَ للدولة العثمانية بلادُ الصرب وبلغراد."},{"id":4216,"title":"سقوط بَرد على حريملاء .","date":["العام الهجري :1204","العام الميلادي :1789"],"text":"نزل على حريملاء بَردٌ في الشتاء على غير العادة، فقتَلَ ما وقع عليه من البهائمِ والطيور، وخسف السطوحَ والأواني حتى النحاسَ، وأهلك الأشجارَ وكسَّرها، وأهلك جميعَ زروعِهم، فجأروا إلى الله سبحانه، فرَحِمَهم ودفع عنهم."},{"id":4217,"title":"رسالة الشيخ محمد بن عبد الوهاب لعلماء بلد الله الحرام  .","date":["العام الهجري :1204","العام الميلادي :1789"],"text":"أرسل الشريفُ غالِبُ بن مساعد شريفُ مكةَ إلى الإمام عبد العزيز بن محمد  كتابًا يطلُبُ فيه أن يرسِلَ إنسانًا عارِفًا حتى يعرِّفَه بحقيقة ما يدعو إليه وما هم عليه, فأرسل إليه القاضي عبد العزيز بن عبد الله الحصين، وكتب معه الشيخ محمد بن عبد الوهاب كتابًا ورد فيه: \"بسم الله الرحمن الرحيم، من محمد بن عبد الوهاب إلى العلماء الأعلام في بلد الله الحرام، نصر الله بهم دينَ سيِّد الأنام، وعليه أفضل الصلاة والسلام، وتابعي الأئمة الأعلام، سلامٌ عليكم ورحمة الله وبركاته، وبعد.. جرى علينا من الفتنةِ ما بلغكم وبلغ غيَركم، وسبَبُه هدم بنيان في أرضِنا على قبور الصالحين، ومع هذا نهيناهم عن دعوةِ الصالحين وأمَرْناهم بإخلاص الدعاء لله, فلمَّا أظهَرْنا هذه المسألةَ مع ما ذكَرْنا من هدمِ البنيانِ على القبورِ، كبُرَ على العامة, وعاضَدَهم بعضُ من يدعي العلم؛ لأسباب لا تخفى على مثلكم، أعظمُها اتِّباع الهوى مع أسباب أخرى, فأشاعوا عنا أنَّا نسُبُّ الصالحين، وأنا لسنا على جادَّة العلماء, ورفعوا الأمرَ إلى المشرق والمغرب فأشاعوا عنَّا أشياء يُستحيا مِن ذِكرِها, وإنا أخبرناكم بما نحن عليه بسبَبِ أنَّ مِثلَكم ما يروج عليه الكذب، فنحن وله الحمد متَّبعون لا مبتدعون، وعلى مذهب الإمام أحمد,.. وفي ولاية الشريف أحمد بن سعيد وصل إليكم الشيخ عبد العزيز بن عبد الله الحصين، وأشرفتُم على ما عندنا بعد ما أحضروا كتُبَ الحنابلة التي عندنا عمدة، كالتحفة والنهاية عند الشافعية, فلما طلب منا الشريفُ غالب أعزَّه الله ونصره، امتثلنا وهو إليكم واصل، فإن كانت المسألة إجماعًا فلا كلام، وإن كانت مسألةً اجتهادية فمعلومكم أنَّه لا إنكارَ في مسائل الاجتهادِ، فمن عَمِلَ بمذهبه في محلِّ ولايتِه لا يُنكَرُ عليه, وأنا أُشهد الله وملائكتَه وأُشهِدُكم أنِّي متَّبِعٌ لأهل العلم، والسلام عيكم ورحمة الله وبركاته\" فقدم عبد العزيز الحصين مكَّةَ فأكرمه الشريف غالب، واجتمع به مراتٍ، وعرض عليه رسالة الشيخ، فعرف ما بها من الحقِّ فأذعن وأقر بذلك، وطلب من عبد العزيز حضورَ العلماء للمناظرة في التوحيدِ، فأبوا وقالوا: هؤلاء يريدون أن يقطعوا جوايزك.. التي من أجدادِك ويملكون بلادَك، فارتعش قلبه وطار."},{"id":4218,"title":"موقعة غريميل بين جيش الأمير سعود بن عبد العزيز وقوات بني خالد .","date":["العام الهجري :1204","العام الميلادي :1789"],"text":"جرت موقعةُ غريميل (وهو جبل صغير تحته ماء، قربَ الأحساء) حيث التقت قواتُ الدرعية بقيادةِ الأمير سعود بن عبد العزيز، مع قواتِ بني خالد بقيادةِ عبد المحسن بن سرداح وابن أخته دويحس بن عريعر، وبعد نزال استمَرَّ ثلاثة أيام، انهزم جيش بني خالد وهرب عبد المحسن إلى المنتفق، وغَنِمَ جيشُ سعود غنائِمَ كثيرة، واستعمل الأمير سعود زيدَ بن عريعر أميرًا على بني خالد."},{"id":4219,"title":"وفاة الملك محمد الثالث ملك العلويين بالمغرب وقيام ابنه يزيد الأول .","date":["العام الهجري :1204","الشهر القمري : رجب","العام الميلادي :1790"],"text":"هو الملك محمد الثالث بن عبد الله بن إسماعيل ملك العلويين في المغرب الأقصى، وكانت عاصمتُه مراكش، ولد بمكناس سنة 1134. تولى الحكم سنة1171 في ظروف صعبة بعد اضطراباتٍ، وقد تميَّزَ بالعقل والرزانة وبُعدِ النظر، اجتهَدَ في المحافظة على بلادِه ووَحدتِها وتأمينِ الشواطئ المغربية من العدوان الأوروبي، وحرَّر مازاغان من يد البرتغاليين، وانتصر على الجيش الفرنسي في معركة العرائش سنة1179, وكان أول حاكمٍ يعترف باستقلالِ وسيادة الولايات المتحدة الأمريكية, ورفَضَ ربطَ علاقات دبلوماسية مع روسيا؛ بسبب محاربتها للدولة العثمانية، وبعث بالعديدِ مِن السفراء لاسترجاعِ المخطوطات العربية من إسبانيا, وداخليًّا كان دائمَ التنقُّل بين جهات مملكته الواسعة؛ ليطمئِنَّ على أحوال البلاد, وشَهِدَ عهدُه أوجَ الازدهار السياسي والعسكري والاقتصادي والثقافي للمغرب الأقصى. تمرد وثار عليه عدةَ مراتٍ ابنُه وولي عهده يزيد، فنفاه في مشرق البلاد. توفِّيَ محمد الثالث في طريقِه إلى ابن عمه الذي خرج عن طاعتِه، فلما توفِّيَ تنازع أبناؤه الأربعة على خلافتِه، وهم هشام، ويزيد، وسليمان، ومَسلمة، حتى تمكَّن يزيد الأول أن يَخلُف أباه في الحُكم."},{"id":4220,"title":"الشريف غالب يغزو أعالي نجد .","date":["العام الهجري :1205","العام الميلادي :1790"],"text":"سيَّرَ شريف مكة الشريف غالبُ عساكِرَه بقيادة أخيه عبد العزيز إلى أعالي نجد لمحاربة أهلِها في قوة هائلة في العددِ والعُدَّة، نحو عشرة آلاف، ومعهم 20 مدفعًا وأمَرَهم أن يقصدوا الدرعية ومنازلَتَها فضلًا عن غيرِها من بلدانِ نجدٍ التابعة للدرعية, فلمَّا رأى أعداءُ الدعوة في نجدٍ هذه القوة أيقَنوا بنهاية دولة الدرعية ودعوة الشيخِ، خاصَّةً أنها جاءت من شريفِ مكَّةَ؛ ولذلك نقض عددٌ من العربان وأهالي بعض بلدان نجدٍ بيعَتَهم وعهدَهم مع الشيخ والأمير، وراسل الشريف عبد العزيز أناسًا من أهل بلدان نجدٍ، منهم حسين الدويش رئيس مطير وعربانه، وكثير من قحطان، فأقبلت تلك العساكِرُ والجنود  معهم كثيرٌ مِن بوادي الحجاز وعربان شمر ومطير وغيرهم، وامتلأ منهم السهلُ والجبَلُ، وصار في قلوبِ المسلمين منهم وجَلٌ, فنزلوا على قصر بسَّام في السر وحاصروه أيامًا وضربوه بالمدافِعِ ولم ينالوا منه شيئًا، على الرغم أنَّ عدد من فيه لا يتجاوز30 رجلًا، وبناء القصر كان ضعيفًا! فرحل عنه الشريفُ عبد العزيز مع جموعِه ونزل في أرض السر أربعة أشهر، ثم عزم على العودة إلى قصر بسام، وحلَفَ ألا يدَعَه حتى يهدِمَه ويقتُلَ من فيه، فعمل السلالم ودهموا بها الجدرانَ فلم يحصلوا على طائلٍ, وقُتِلَ من قومِه عِدَّة رجال. كان الإمامُ عبد العزيز لما أقبلت تلك الجموعُ استنفَرَ أهالي بلدان نجد التابعين له مع ابنه الأمير سعود، فنزل سعود رمحين النفود بالقربِ مِن بلدة أشيقر، وأقام فيها يخيفُ جنود الشريف، وهذه الواقعة هي أوَّلُ لقاء عسكري بين أشرافِ الحجازِ والدرعية، كان المبادِرُ بالقتال فيها هو شريفَ مكةَ."},{"id":4221,"title":"وفاة الإمام العلامة مرتضى الزبيدي صاحب تاج العروس .","date":["العام الهجري :1205","العام الميلادي :1790"],"text":"هو الإمامُ الفاضلُ العلَّامة، الفقيهُ المحَدِّث اللُّغوي النحوي الأصولي: محمد بن محمد بن عبد الرزاق الحسيني، الملقب بمرتضى الزبيدي، أصلُه من واسط العراقِ، ولد بالهند سنة 1145, ونشأ في زَبيد، وتوفِّي في مصر، كان عالِمًا بالأدب والأنساب والحديثِ، قرأ على الشيخ عبد الرحمن العيدروس مختصر السعد بمكة، ولازمه ملازمةً كليةً وألبسه الخرقةَ وأجازه بمروياته ومسموعاته، وهو الذي شوَّقه إلى دخولِ مِصرَ بما وصفه له من علمائِها وأمرائها وأدبائِها وما فيها من المشاهِدِ الكرام، فاشتاقت نفسُه لرؤياها، ثمَّ ورد الزبيديُّ إلى مصر في تاسع صفر سنة 1169، وسكن بخان الصاغة، وفي مصر شرع في شرحِ القاموس حتى أتمَّه في عدة سنين في نحو أربعة عشر مجلَّدًا، وسمَّاه تاج العروس، ولَمَّا أكمله أولم وليمةً حافلةً جمع فيها طلاب العلم وأشياخ الوقت بغيط المعدية، وذلك في سنة 1181، وأطلعهم عليه واغتَبَطوا به وشَهِدوا بفضله وسَعةِ اطلاعه ورسوخِه في علم اللغة، وكتَبوا عليه تقاريظهم نظمًا ونثرًا، وله مصنَّفات عديدة، منها: إتحاف السادة المتقين بشرح إحياء علوم الدين، وعقود الجواهر المنيفة في الفقه الحنفي، ولقط اللآلئ المتناثرة في الأحاديث المتواترة، وغيرها من المصنفات."},{"id":4222,"title":"الشريف غالب يحاصر قرية قصر الشعراء .","date":["العام الهجري :1205","العام الميلادي :1790"],"text":"لَمَّا أخفقت حملة الشريف عبد العزيز في تحقيقِ أيِّ نصر على دولة الدرعية، جهَّز الشريف غالب بن مساعد شريف مكة جنودًا عظيمةً من مكة وغيرها ومعه سبعة مدافِعَ، فقصد هو بنفسِه أخاه عبد العزيز، ثم رحل الشريف غالب وأخوه عبد العزيز بجنودِهما الهائلة، ونزلوا قصر الشعراء، وهي قرية معروفة بأعالي نجدٍ، وحاصروها وضربوها بالمدافِعِ، وكادوا لها بأنواعِ القتالِ، وساقوا عليها الأبطالَ، وأقام الشريفُ غالب يحاصِرُها أكثَرَ من شهر، فرحل منها على فشَلٍ، وقُتل من قومه أكثَرُ من 50 رجلًا ورجع منها إلى أوطانِه، وتفرَّقت عنه جموعُه وعُربانه, ثم أرسل الأميرُ سعود خلفَهم محمد بن معيقل بقوَّةٍ معه يتبعُ أثر الشريف غالب ويُغيرُ عليه من الخَلفِ، فأغار على فريقٍ مِن قحطان وحصل جلادٌ بينهم وغَنِموا منهم إبلًا كثيرةً وخمسة عشر من الخيل الأصايل."},{"id":4223,"title":"الدولة العثمانية توقع معاهدة زيشتوفي مع ألمانيا .","date":["العام الهجري :1205","الشهر القمري : ذي الحجة","العام الميلادي :1791"],"text":"وقَّعت الدولة العثمانية معاهدة \"زيشتوفي\" مع ألمانيا؛ لإنهاء الحرب بينهما، وتكوَّنت هذه المعاهدة من أربع عشرة مادة، وكانت مدتُها ثلاث سنوات، وانسحب الألمانُ من بلغراد ورومانيا بناءً على هذه المعاهدة بعد احتلالٍ دام سنة وعشرة أشهر، وكانت تلك آخِرَ حرب بين الجيوش الألمانية والجيوش العثمانية في التاريخِ."},{"id":4224,"title":"وقعة العدوة بين الشريف غالب والأمير سعود بن عبد العزيز .","date":["العام الهجري :1205","الشهر القمري : ذي الحجة","العام الميلادي :1791"],"text":"لَمَّا رجع الشريف بعد حملتِه غيرِ الموفَّقة على قصر الشعراء في أعالي نجد، انفرد عن كثير من البوادي وأكثرهم من مطير وقبائل شمر ورئيسهم مسعود الملقَّب حصان إبليس، وانحازوا إلى ماء معروف بالعدوة لشمر قُربَ حائل، فنهض لهم الأمير سعود بن عبد العزيز واستنفر أهلَ نجد البادي والحاضر، فسار بجنوده حتى نازلهم في تلك الناحية ووقع بينهم قتالٌ شديد، فانهزمت تلك البوادي وقُتِل منهم قتلى كثير من بينهم قائدُهم حصان إبليس، وغنم الأمير سعود منهم غنائِمَ عظيمةً، فلما انهزم هؤلاء البوادي وأُخِذت أموالهم استنفروا من يليهم من قبائلِهم ممَّن لم يحضر الوقعة، وأرسلوا إلى سعود يدعونه للمنازلة، فأقبلوا إليه وهو يقسم الغنائم في العدوة، فثبت لهم سعود وجنودُه وأوقدوا فيهم وفي إبِلِهم بالبارودِ والرصاص، فلما أراد مُقَدَّمهم مسلط بن مطلق الحربا أن يطأ بفرسِه بساطَ سعود ليفيَ بنَذرِه، اختطفه جنودُ سعود وأردوه قتيلًا، فانهزمت البوادي لا يلوي أحدٌ على أحدٍ، وتركوا إبِلَهم مقرونةً بالحبال فغَنِمَها سعود وجميعَ ما معهم من الغنم والمتاع، ثم أخذوا في مطاردتهم يومين يأخذون الأموال ويقتلون الرجال."},{"id":4225,"title":"وفاة الملك يزيد الأول بن محمد الثالث ملك العلويين بالمغرب .","date":["العام الهجري :1206","العام الميلادي :1791"],"text":"هو يزيدُ الأول بن محمد الثالث ملك العلويين في المغرب الأقصى، الفرع الحسني الذي كان يقاتِلُ أخاه هشامًا الذي بايعه قبائِلُ الحوز في سبتة, فلما توفي يزيد الأول تولَّى أخوه هشام الملك خَلَفًا له."},{"id":4226,"title":"وفاة الأمير عبد المحسن بن سرداح رئيس بني خالد .","date":["العام الهجري :1206","العام الميلادي :1791"],"text":"هو الأميرُ عبد المحسن بن سرداح، رئيس بني خالد، توفِّيَ بعد وقعة غريميل سنة 1204 هرب عبد المحسن إلى المنتفق وتولى بني خالد زيدُ بن عريعر، ثمَّ إن زيدًا وإخوته أرسلوا إلى عبد المحسن ووعدوه بالأمان ومَنَّوه حتى جاء إلى الأحساءِ فقَتَلوه في مجلِسِهم."},{"id":4227,"title":"إصلاحات السلطان سليم الثالث الداخلية .","date":["العام الهجري :1206","العام الميلادي :1791"],"text":"كان السلطانُ سليم الثالث منذ أن تولَّى السلطنةَ سنة 1203هـ يدرِكُ أنَّ البلادَ بحاجة إلى إصلاحاتٍ داخليةٍ في كافةِ المجالات لا سيَّما الحربية؛ حيث إنَّ ضَعفَ سلطات استانبول سبَّب استئثار بعض الولاة بولاياتِهم وامتناعِهم عن دفعِ الأموال المتَّفَق عليها للخزينةِ السلطانية، وبعد هدوء القتالِ على الجبهات الخارجية انصرف السلطانُ سليم للإصلاحات الداخلية، فبدأ بتعيين أحدِ الشبَّان، وهو كوشك حسين باشا قبودانا عاما، وقد كان ملمًّا ودارسًا لأحوال أوروبا، فبذل جهدَه بإخلاص لتنقية الطرقِ التجارية البحرية من القراصنة، وأصلح الثغورَ وأنشأ القلاعَ عليها، وبنى عدَّةَ مراكِبَ حربية على أحدثِ الأنماط الفرنسية والإنجليزية، وجلب العديدَ من المهندسين الأوروبيين المهَرة لِصَبِّ معظم قوالب المدفعية في طوبخانات الدولة، كما قام السلطانُ بإنشاء سفارات دائمة لدى دول أوروبا الكبرى، واستغلَّ انشغال الأوروبيين بمحاربة حكومةِ الثورة الفرنسية لتحديثِ الدولة العثمانية وجيشِه، فاستقدمَ العديدَ مِن الخبراء والضباط الفرنسيين لتدريبِ وتحسين العساكر العثمانيَّة، وعَمِل كوشك على إصلاحِ مدارس البحرية والمدفعية (الطوبجية)، وجهَّز مكتبة لمدرسة المدفعية وضع فيها أحدث ما سُطرَ عن فنِّ الحرب والرياضيات، وترجم كتُبَ المهندس الفرنسي فوبان عن فنون الاستحكامات, كما عَمِل سليم الثالثِ على وَضعِ خطةٍ جادَّةٍ لتوسيع رقعةِ التعليم في الدولة، فافتتح العديدَ مِن المدارس والمعاهد، وكان لهذه التحديثات ردود فعل سلبية جدًّا من الانكشارية؛ ممَّا دفعهم للثورة على السلطان سليم وعزله سنة 1222هـ."},{"id":4228,"title":"إجراء أول تجربة ناجحة على استخدام الغواصة في الدولة العثمانية .","date":["العام الهجري :1206","الشهر القمري : محرم","العام الميلادي :1791"],"text":"أُجريت أول تجربة ناجحة على استخدامِ الغواصة في الدولة العثمانية، وذلك في عهد السلطان أحمد الثالث، تُطلِقُ طوربيدًا من تحت الماء، وأطلِقَ على هذه الغواصة اسمَ \"تحت الماء\" وقد أشرف على صناعتها كبيرُ مهندسي السفن إبراهيم أفندي رئيس مهندسي مصنع السفن الإمبراطوري آنذاك, ثم أُدخلت هذه الغواصة ضِمنَ الأسطول الحربي العثماني."},{"id":4229,"title":"استعادة العثمانيين السيطرة على ميناء ومدينة وهران الجزائرية من الأسبان .","date":["العام الهجري :1206","الشهر القمري : ربيع الآخر","العام الميلادي :1791"],"text":"استعاد العثمانيون السيطرةَ على ميناء ومدينة وهران الجزائرية من الأسبان، وذلك بعد ما سيطر الأسبان عليها 59 عامًا، وكانوا قد نجحوا في انتزاعها من العثمانيين سنة 1144هـ تقريبًا."},{"id":4230,"title":"روسيا تتوسع عسكريًّا على حساب الأتراك العثمانيين ومعاهدة ياش .","date":["العام الهجري :1206","الشهر القمري : جمادى الأولى","العام الميلادي :1792"],"text":"رجعت النمسا عن تحالُفِها مع الروس ضِدَّ العثمانيين وعقدت صلحًا معهم وأعادت ما كانت أخذَته من العثمانيين، أما روسيا فقد استمَرَّت بالحرب واستولت على بعض المدنِ، فارتكبت من الجرائِمِ ما لا يوصف، ثم توسَّطت إنكلترا وهولندا للصلحِ بين الطرفين خوفًا على مصالحِهم، فكانت معاهدةُ ياش, أخذت بموجِبِها روسيا بلادَ القرم نهائيًّا، وبسارابيا وجزءًا من بلاد الشراكسة، والمنطقة الواقعة بين نهري بوغ ودنيسر، وأصبح هذا النهر الأخير فاصلًا بين الدولتين، كما تنازلت الدولةُ العثمانية عن مدينة أوزي. ويُذكَر أنَّ أهمَّ بنود هذه المعاهدة تبادُلُ أسرى الحرب، والسماحُ للرعايا الذين يعيشون خارِجَ دولتِهم بسبب الأزمات السياسية بالعودة إلى بلدانِهم الأصلية أو البقاء حسب رغباتهم. تتنازلُ الدولة العثمانية لروسيا عن ميناءِ أزوف وبلادِ القرم وشبهِ جزيرة طمان، وبلاد القويان وبساربيا، والأقاليم الواقعة بين نهري بجد والدينستر، ويكون النهرُ الأخير حدًّا فاصلًا بين الدولتين. تُرجِع روسيا للدولة العثمانية مناطِقَ: البغدان وأكرمان وكيلي وإسماعيل مقابِلَ أن تقوم الدولةُ بإعفاء رعايا البغدان من الضرائبِ، وعدم مطالبة روسيا بتعويضاتِ حرب أو ما شابه ذلك. يمنع الباب العالي رعايا دولته من الغارات على محافظتي تفليس وكاتالينا الروسيتين، وعلى السفن الروسية في البحر المتوسط، وعليه القيامُ بدفع تعويضات لأي أضرار تحدثُ بعد ذلك من قِبَل رعايا الدولة العثمانية."},{"id":4231,"title":"غزو الأمير سعود القطيف ومحاصرته لسيهات .","date":["العام الهجري :1206","الشهر القمري : جمادى الأولى","العام الميلادي :1792"],"text":"تحرَّك الأميرُ سعود بقواتِه غازيًا القطيفَ، وقام بمحاصرة سيهات وأخذها عَنوةً، ثم احتَلَّ بلدة عنك، ثم سار إلى القديح وأخذها عَنوةً، ثم أخذ العوامية وحاصَرَ الفرضة؛ لأن أهلَ القطيف هربوا إليها فصالَحَهم بثلاثة آلاف زر، وأزال جميعَ ما في القطيف من الأوثان والمتعبدات والكنائس، وأمر سعودٌ بحرق كُتُبِهم القبيحة بعد ما جمعوا منها حملًا."},{"id":4232,"title":"وفاة الإمام المجدد محمد بن عبد الوهاب .","date":["العام الهجري :1206","الشهر القمري : شوال","العام الميلادي :1792"],"text":"هو شيخُ الإسلامِ الإمامُ المجَدِّد محمد بن عبد الوهاب ابنُ الفقيه العالم سليمان بن علي بن محمد بن أحمد بن راشد التميمي النجدي، ولِدَ في العُيينة بنجد سنة 1115ونشأ فيها، تربَّى في حجر أبيه الفقيه الحنبلي، ثم انتقل للحَجِّ والدراسة في الحجازِ، ثمَّ درس في البصرة وبغداد والأحساء، تأثَّرَ بكتب شيخ الإسلام ابن تيمية ودعوتِه، وخاصَّةً فكرة محاربة البدع والمعتقدات الشركية التي كانت منتشرةً بكثرةٍ في نجد وغيرها, وقد ساعده على تحقيقِ محاربةِ البِدَع والشركيات تحالُفُه مع محمد بن سعود، فكان مجدِّدًا للدعوة السَّلفية في نجد، يصِفُ ابنُ بشرٍ شَيئًا من سيرة الشيخ فيقول: \"كان- رحمه الله- كثيرَ الذكر لله، قلَّما يفتُرُ لسانُه من قول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر. وكان إذا جلس الناس ينتظرونَه يعلَمون إقباله إليهم قبل أن يَرَوه من كثرة لهجِه بالتسبيح والتحميد والتهليل والتكبير، وكان عطاؤه عطاءَ مَن وَثق بالله عن الفَقرِ، بحيث يهَبُ الزكاة والغنيمة في مكانٍ واحدٍ ولا يقومُ ومعه منها شيءٌ، ويتحمَّلُ الدَّين الكثير لأضيافِه وسائليه والوافدين عليه, وعليه الهَيبةُ العظيمة التي ما سَمِعْنا بها اتَّفَقت لغيره من الرؤساءِ وغيرِهم، وهذا شيءٌ وضعه الله له في القلوبِ، وإلا فما علمنا أحدًا ألين وأخفَضَ منه جانبًا لطالب العلم أو سائل حاجة أو مقتَبِس فائدة، وكان له مجالِسُ عديدة في التدريس كلَّ يومٍ وكُلَّ وقت: في التوحيد والتفسير، والفقه وغيره، وانتفع الناسُ بعلمِه، وكان من بيت علمٍ في آبائه وأعمامِه وبني أعمامه، واتصلَ العلمُ في بنيه وبني بنيه. كان سليمانُ بن علي جدُّه عالمَ نجد في زمانِه، وله اليد الطولى في العلمِ، وانتهت إليه الرئاسةُ فيه في نجدٍ، وضُرِبَت له آباط الإبل، وصَنَّف وأفتى.... أما والده عبد الوهاب فكان عالِمًا فقيهًا قاضيًا في بلد العُيينة، ثم في بلد حريملاء... وأما أخوه سليمان بن عبد الوهاب، فله معرفةٌ في الفقهِ، وكان قاضيًا في بلد حريملاء.... وأما محمد: فهو شَيخُ الإسلامِ والبحرُ الهُمام الذي عَمَّت بركةُ علمه الأنام، فنصر السُّنَّة وعَظُمت به من اللهِ المِنَّة بعد أن كان الإسلام غريبًا، فقام بهذا الدين ولم يكن في البلد إلا اسمُه, فانتشر في الآفاقِ، وكُلُّ أمرٍ أخَذَ منه حظَّه وقَسمَه، وبعث العمَّالَ لقبض الزكواتِ وخَرْص الثمار من البادي والحاضر بعد أن كانوا قبل سنوات يُسَمَّون عند الناس مُكاسًا وعُشَّارًا, ونُشرت راية الجهاد بعد أن كانت فِتَنًا وقتالًا, وعرف التوحيدَ الصغيرُ والكبيرُ بعد أن كان لا يعرفُه إلا الخواصُّ, واجتمع الناسُ على الصلوات والدروس والسؤال عن معنى لا إله إلا الله, وفِقْه معناه، والسؤال عن أركان الإسلام، وشروط الصلاة وأركانها وواجباتها، ومعاني قراءتها وأذكارها, فتعلم ذلك الصغيرُ والكبير والقارئ والأمي بعد أن كان لا يعرِفُه إلا الخصائص, وانتفع بعلمه أهل الآفاق؛ لأنهم يسألون عما يأمُرُ به الشيخُ وينهى عنه, فيقال لهم يأمرُ بالتوحيد وينهى عن الشرك, ويقال لهم: إنَّ أهل نجد يمقتونكم بالإشراكِ مع الله في عبادتِه... فانتهى أناسٌ كثير من أهل الآفاق بسبب ما سمعوه من أوامِرِه ونواهيه, وهدَمَ المسلمون ببركةِ عِلمِه جميعَ القباب والمشاهِد التي بُنِيت على القبور وغيرِها من جميع المواضِعِ المضاهية لأوثان المشركينَ في الأقطارِ مِن الحَرَمين واليمن وتهامة وعمان والأحساء ونجد، وغير ذلك من البلاد.. ثم قال ابن بشر بعد أن سرد جملة من آثاره وفضائله رحمه الله: ولو بسطتُ القول فيها واستقصيتُها لاتسع لأسفارٍ، ولكن هذه قطرة من بعض فضائله على وجه الاختصارِ، وكفى بفضلِه شرفًا ما حصل بسببه من إزالة البِدَع واجتماع المسلمين وإقامة الجَماعات والجُمَع وتجديد الدين بعد دروسِه، وقلع أصولِ الشِّرك بعد غروسِه, وكان- رحمه الله- هو الذي يجهِّز الجيوشَ ويبعَثُ السرايا على يد محمد بن سعود، ويكاتِبُ أهل البلدان ويكاتبونَه، والوفود إليهما والضيوفُ عنده, وصدورُ الأوامر من عندِه حتى أذعن أهلُ نجد وتابعوا على العمَلِ بالحَقِّ والأمر بالمعروف والنهي عن المنكرِ، وبايعوا فعَمَرت نجد بعد خرابِها وصَلَحت بعد فسادِها, واجتمعت بعد افتراقِها، وحُقِنت الدماء بعد إهراقِها، ونال الفخرَ والفضل والمُلك مَن نصَرَه وآواه \" ومن أبرز مشايخ الإمام المجدِّد الذين نهل منهم عِلمَه: والده عبد الوهاب، والشيخ محمد حياة السندي المدني، والشيخ عبد الله بن سيف النجدي. وأبناءُ الشيخ الأربعة عُلماء وقضاة، جمعوا أنواع العلومِ الشرعية، وهم: حسين، وعبد الله، وعلي، وإبراهيم. لهم مجالسُ علم من أهل الدرعية ومِن أهل الآفاقِ: اليمن وعمان ونواحي نجد, وأبناء هؤلاء الأربعة عُلماء وقضاة, وقد اشتهر الشيخُ بمؤلَّفاته التي يُبَيِّن فيها التوحيدَ الصافيَ، ومنها: كتاب التوحيد، وكشف الشبهات، والأصول الثلاثة، والرد على الرافضة، ومختصر السيرة النبوية، ومختصر زاد المعاد، والقواعد الأربعة، وغيرها من الكتب. توفِّيَ الشيخ محمد في العُيينة بالقرب من الرياض عن عمر 92 سنة, وكان قد بدأه المرضُ في شوال من هذه السنة، وتوفي يوم الاثنين آخر شهر شوال- رحمه الله تعالى."},{"id":4233,"title":"وفاة الأمير أحمد بن محمد آل خليفة مؤسس البحرين .","date":["العام الهجري :1206","الشهر القمري : ذي الحجة","العام الميلادي :1792"],"text":"هو الأميرُ أحمد بن محمد آل خليفة، الملقَّب بالفاتِحِ؛ لأنَّه يعتبَرُ المؤسِّسَ لإمارة البحرين والمثَبِّت الحقيقيَّ لحكم آل خليفة في الجزيرة البحرينية وشبه الجزيرة القطرية، وهو عتبي عنزي أسدي، من آلِ خليفةٍ، ولِدَ بالكويت في النصف الأول من القرن الثامن عشر، انتقل مع والده على رأس الأسرة إلى قطر عام (1175هـ/1762م) حيث أسَّسوا الزبارة كانت إقامته بالزبارة (على الساحل المقابل للبحرين) مع أخيه شيخ الزبارة خليفة بن محمد، الذي كان ذهب للحَجِّ فناب عنه أخوه أحمد، فنشبت حينها فتنةٌ بين أهل البحرين وبين أهل الزبارة التي انتهت بانتصارِ أهلِ الزبارة، وبالتالي دخل أحمد البحرين، واستولى عليها سنة 1197، وجاء الخبَرُ بوفاة أخيه خليفة في مكة، فأصبح أحمد هو الآمِرَ الفعليَّ، فحكم البحرين واعتُبِرَ مؤسِّسَها، وبقي متنقلًا بين البحرين والزبارة مقويًا شأنَه فيهما إلى أن توفي في هذه السنةِ، ودُفِن في المنامة، فخَلَفه بعده ابنُه سليمان."},{"id":4234,"title":"وفاة الملك هشام بن محمد الثالث ملك العلويين بالمغرب .","date":["العام الهجري :1207","العام الميلادي :1792"],"text":"هو المَلِكُ  هشام بن محمد الثالث ملك العلويين في المغرب الأقصى الفرع الحسني، بعد أن تولى بعد مَقتَلِ أخيه يزيد، لكِنَّه لم يلبث طويلًا حتى توفي في هذا العام متأثرًا بوباء أصابه، فخلَفَه أخوه سليمان."},{"id":4235,"title":"خضوع منطقة جبل شمر لدولة الدرعية .","date":["العام الهجري :1207","العام الميلادي :1792"],"text":"أدرك الإمامُ عبد العزيز بن محمد بن سعود، الذي نجحت جيوشُه في القضاءِ على ثوراتِ الخرج والقصيم أهميةَ منطقة جبل شمر لتأمين حدود دولتِه من الشمال، وأدرك أيضًا أهميتَها الاقتصادية؛ حيث تزدهِرُ فيها الزراعة، بالإضافة إلى علاقتِها التجارية بالعراقِ والبلاد المجاورة؛ لذا عزم على إخضاعِ أُمرائها آل علي لنفوذِ دولةِ الدرعية، فأرسل إليها الحَمَلاتِ تِباعًا، حملةً تلو حملة، واستمَرَّت تلك العملياتُ العسكرية إلى أن خضعت المنطقةُ لدولة الدرعية."},{"id":4236,"title":"وقعة الشيط بين بني خالد والأمير سعود .","date":["العام الهجري :1207","العام الميلادي :1792"],"text":"لَمَّا تولى براك بن عبد المحسن أمرَ بني خالد نهض بجميعِ بني خالد للغزوِ، فورد اللصافة الماء المعروف، فأغار على عُربان سبيع وغيرهم, وأخذ منهم إبلًا كثيرة، فلما بلغ الأمير سعود خبَرُ بني خالد استشار من معه في النفير أو الحضير، فأشار عليه العُربان بالنفير طمعًا في الغنيمة، فتكلم حجيلان بن حمد فقال: هؤلاء مقصِدُهم الغنيمة ونحن مقصِدُنا عزُّ الإسلام والمسلمين، فانهض بالمسلمين في ساقةِ هذه الشَّوكةِ، فإن أظفرك اللهُ بهم لم يقُمْ لبني خالد قائمةٌ حتى الحسا بيدك، وأعطاك الله من الأموال ما هو خير ممَّا في محلتهم، وهؤلاء الجنود رؤساءُ بني خالد ورجالُ شوكتهم, فنهض سعود بجيشِه وورد ماء اللصافة، فوجد آثار بني خالد صادِرة منها، فبعث العيون يقتفون آثارهم حتى أقبلوا كأنَّها قِطَع الليل، فنهض لهم سعود بجيشِه فرسانًا ورُكبانًا، فلم يثبتوا لهم ساعةً واحدةً حتى انهزموا لا يلوي أحدٌ على أحدٍ، ولا والدٌ على ولد, فتبعهم جيشُ سعود في ساقَتِهم يقتلون ويغنَمون، واستأصلوا تلك الجموعَ قتلًا ونهبًا، وانهزم براك ومعه شرذمة قليلة إلى المنتفق, وهلك من بني خالد في هذه الوقعة بين القَتلِ والظمأ خلق كثير، قيل إنهم أكثر من ألف رجل, وأخذ سعودٌ جميع ركابهم وخيلهم وأذوادهم وأمتاعهم، وجميع ما معهم، ولم يقم بعد هذه الواقعة لبني خالد قائمةٌ."},{"id":4237,"title":"أهل الأحساء يبايعون الأمير سعود ثم ينقضون العهد .","date":["العام الهجري :1207","العام الميلادي :1792"],"text":"لَمَّا بلغ أهلَ الأحساء هزيمةُ بني خالد في الشيط، وقع الرعب في قلوبهم وخافوا خوفًا عظيمًا، ثم سار الأمير سعود بجنوده ناحيةَ الأحساء فنزل الردينية الماء المعروف في الطف فأقام أيامًا وأتته المكاتبات مع رسل أهل الأحساء يدعونه إليهم ليبايعوه، فارتحل منها وسار إلى الأحساء ونزل عينَ النجم خارج البلدِ، فخرج إليه أهلُها وبايعوه على دين الله ورسولِه والسمع والطاعة, ثم دخل جيشُ سعود الأحساءَ فهَدَموا جميع ما فيه من القباب والمشاهِدِ التي على القبور، والمواضِعَ الشركية, ثم أقام سعود قريبًا من شهر رتَّب أئمة المساجِدِ وأمَرَهم بالمواظبة على الصلواتِ وإقامة الجُمَع والجماعات، ونادى بإبطال جميعِ المعاملات الرِّبوية وما خالف الشَّرعَ، ورتب الدروسَ وجعل فيهم علماءَ مِن قَومِه يعلِّمونهم التوحيد, وكان أهلُ الأحساء قد أبطنوا الغدرَ ونَقْضَ العهد، وقَتْلَ العلماء المعَلِّمة وأميرَهم وصاحِبَ بيت المال، وكانوا نحوًا من 30 رجلًا, فأجمعوا على ذلك فقتلوا أميرَهم محمد بن حملي، وقتلوا البقية وجرُّوهم في الأسواقِ، وفعلوا بهم أفعالًا قبيحةً, واستولى  زيدُ بن عريعر على الأحساءِ."},{"id":4238,"title":"وفاة الأمير سليمان بن عفيصان أمير الخرج .","date":["العام الهجري :1207","العام الميلادي :1792"],"text":"هو الأميرُ سليمان بن عفيصان أميرُ الخرج، وهو من أبرز قادةِ دولة الدرعية. كان ذا جرأةٍ وشجاعة, وكان كثيرًا ما يستعمله الإمامُ عبد العزيز في قيادة السرايا, وهو والد القائد إبراهيم بن عفيصان الذي تولى إمارة الخرج بعد والِدِه سليمان وخلَفَه في قيادة الجيوشِ."},{"id":4239,"title":"غزو إبراهيم ابن عفيصان قطر .","date":["العام الهجري :1207","الشهر القمري : ذي الحجة","العام الميلادي :1793"],"text":"غزا إبراهيمُ بنُ سُليمان بن عفيصان قطر، وهو أوَّلُ قائدٍ تابِعٍ لدولة الدرعية يقومُ بغزوها، واستطاع إخضاعَ مُعظَم قراها: فريحة والحويلة واليوسفية والرويضة وغيرها، وكتب إلى الدرعية يطلب السماحَ له بمهاجمة الزبارة، فجاءته الموافقةُ مِن الإمام عبد العزيز بن محمد، وحاصر إبراهيمُ فيها العتوب (آل خليفة وجماعتهم) وشدَّد هجماتِه عليها حتى استولى على قلعتِها، فاضطر العتوب إلى الرحيلِ وساروا إلى البحرين بوساطة البحر مُقتَنِعين بأنَّ رحيلَهم هذا ما هو إلا رحيلٌ مؤقَّتٌ يدوم لفترة قصيرةٍ هي فترةُ بقاء قوات الدرعية في قطر؛ ظنًّا منهم أنَّ حُكمَ الدرعية فيها لن يتعَدَّ كَونَه حملةً عابرة تنسحِبُ قواتُ الدرعية بعدها، وعندها يعود العتوب إليها مرةً ثانية، وهكذا دخل أتباعُ دعوة المجدِّد قطر، فأصبحت جزءًا من الدولة السعودية الأولى التي أخذَت تَنشُرُ فيها مبادئَ دعوةِ الشيخ محمد بن عبد الوهاب."},{"id":4240,"title":"قيادة إبراهيم بن عفيصان أول حملة من الدرعية على الكويت .","date":["العام الهجري :1208","العام الميلادي :1793"],"text":"أدركت دولةُ الدرعية أهميَّةَ الكويت التي تعَدُّ ميناءً لتموين نجدٍ، فقام القائدُ إبراهيم بن عفيصان بحملةٍ عسكرية، ويبدو أنَّ من أسباب الحملةِ أيضًا إيواءَ الكويت لزعماء بني خالد الفارِّين من دولة الدرعية، وقد غنم إبراهيمُ في هذه الحملة غنائِمَ كثيرةً، لكنه لم يتمكَّنْ من إخضاع الكويت لسيادةِ دولةِ الدرعية."},{"id":4241,"title":"غزو سعود الأحساء ونهاية حكم آل حميد فيها .","date":["العام الهجري :1208","العام الميلادي :1793"],"text":"سار الأميرُ سعود بن عبد العزيز بجيوشِه من جميع نواحي نجدٍ وعُربانها، وقصَدَ الأحساءَ، وكان أهلُ الأحساءِ بعد نقضِهم العهدَ أتى إليهم زيدُ بن عريعر واستولى عليهم واستوطنَ البلَدَ هو وإخوانُه وذووه، فأقبل إليهم سعود  بجنوده وفرسانه، ومعهم براك بن عبد المحسن بن سرداح آل حميد مهاجر، ونزل سعودٌ بجنوده على قرية الشقيق المعروفة في الأحساء، فحاصرها يومين وأخذها عَنوةً، واستولى عليها وهرب أهلُها، تم اجتمع أهل قرى شمال الأحساءِ في قرية القرين، فسار إليها سعود فنزلها وحاصرها أشدَّ الحصار وحاصر أهل بلد المطيرفي فصالحوه على نصفِ أموالهم، وسار سعود بجنوده إلى المبرز، فخرج عليهم زيدُ بن عريعر بما عنده من الخيلِ، فحصل بينهم قتالٌ، قُتِلَ مِن قومِ زيد غديرُ بن عمر، وحمود بن غرمول، وانهزم زيد ومن معه إلى البلدِ، ثم بعد أيام. سارت الجموعُ إلى المبرز فكمنوا لهم فجرت وقعةُ المحيرس قُتِلَ فيها من أهل المبرز مقتلةٌ عظيمة، قيل: إن القتلى ينيفون عن المائة رجل، وسارت الجنودُ إلى البطالية، فوقع فيها قتالٌ فانهزم أهلُها وقُتِلَ منهم عددٌ كثير، وأخذ سعود ما فيها من الأمتعةِ والطعام والحيوان والأموال، ثم ساروا إلى بلدانِ الشرق فحصل فيها قتالٌ وجِلادٌ، وارتجف أهل الشرق، ثم إنَّ براك بن عبد المحسن أتى إلى سعود وقال: إن أهل الأحساء يريدون المبايعة والدخول في الإسلامِ، ولكِنْ لا يقدرون على الجلوسِ بين يديك خوفًا وفَرَقًا وهيبةً، فقال: سعود لا بُدَّ من إقبالهم عندي، فشفَعَ براك برؤساء المسلمين على سعودٍ يرحَلُ عنهم، وقال لسعود: إذا رحلت عنهم أخرجوا عنهم زيدَ بن عريعر وأتباعه، ووفَدوا عليك وبايعوك فرحل سعود قافلًا إلى الدرعية، وركب براك إلى أهلِ الأحساءِ، فلما وصل إليهم نابذوه ونقضوا ما بينهم وبينه، وقاتَلوه واستمَرُّوا على أمرهم، فأرسل إليه فريق السياسب وأدخلوه المبرز، وكان أولاد عريعر في الجفر والجشة، فحصل بينهم وبين السياسب وأتباعهم قتالٌ شديد، فهرب أولادُ عريعر من الأحساء، وقصدوا البصرة والزبير وسكنوا فيه، واستولى على الأحساء من جهة الإمام عبد العزيز براكُ بن عبد المحسن وبايعوه على السمع والطاعة, وكتب إليه عبد العزيز أنه يجلي من الأحساءِ رؤساء الفتن: محمد بن فيروز، وأحمد بن حبيل، ومحمد بن سعدون، فأخرجهم براك منها، ودخل أهلُ الأحساء في طاعة براك، وصار أميرًا نائبًا للإمامِ عبد العزيز سامعًا مُطيعًا. وبزوال ولاية زيدِ بن عريعر عن الأحساء زالت ولاية آل حميد عن الأحساء ونواحيها؛ لأن ولاية براك هذه كانت للإمامِ عبد العزيز بن محمد بن سعود وتابعةً لدولة الدرعية."},{"id":4242,"title":"قيام دولة القاجار في طهران بقيادة محمد حسن خان .","date":["العام الهجري :1209","العام الميلادي :1794"],"text":"وبعد وفاة كريم خان الكردي حاكم دولة الزنديين في إيران، انتفضَ على الحُكم زكي خان فقام في وجهه القاجار بقيادة آغا محمد، فبعث إليهم جيشًا إلى أصفهان بقيادةِ علي مراد خان الذي لم يلبثْ أن انقلب ضِدَّه واغتِيلَ زكي خان، وانطلق القاجار بقيادةِ زعيمِهم آغا محمد، ودخَلوا أصفهان غيرَ أنهم في البداية هُزموا أمام البختيار، ثمَّ إنَّ لطف الله خان الكردي استسلم للقاجار فقتلوه, وأبادوا أسرةَ الزندي، وهكذا انتهى الزنديون وقبلَهم الأفشار وتفرَّد القاجار بالحُكمِ متَّخِذين طهران عاصمةً لهم، وكان أوَّلَ أمرائهم آغا محمد حسن قاجار، الذي سار إلى تفليس في عام 1210هـ واحتلَّها كما احتلَّ أيضًا أريفان عاصمة أرمينيا."},{"id":4243,"title":"غزو الأمير سعود بن عبد العزيز تربة بالحجاز .","date":["العام الهجري :1209","الشهر القمري : ذي القعدة","العام الميلادي :1795"],"text":"سار الأمير سعود بن عبد العزيز بجنوده قاصدًا الحجاز ونازل أهلَ تربة بلد البقوم المعروفة، فحاصر أهلَها حصارًا شديدًا وقطع كثيرًا من نخيلها ووقع بينهما قتلى، ثم صالحه أهلُ البلد."},{"id":4244,"title":"الأزهر يثور ضد المماليك الترك في مصر .","date":["العام الهجري :1209","الشهر القمري : ذي الحجة","العام الميلادي :1795"],"text":"قام أهل بلبيس بالحضور إلى الشيخ وشكَوا إليه محمد بيك الألفي وظُلم أتباعه، فذهب الشيخ الشرقاوي للأزهر وجمع المشايخ وقفَّلوا أبواب الجامع، وذلك بعدما خطب مراد بيك وإبراهيم بيك، وفعلوا مثل ذلك اليوم الثاني، وأمروا الناسَ بغلق الأسواق والحوانيت، ثمَّ ركبوا مع جمعٍ كبير من العامَّةِ إلى بيت الشيخ السادات، وازدحم الناسُ فحضر الدفتردار أيوب بيك، فقالوا له إنَّ مرادهم هو رفعُ الظلم والجَور، وتطبيقُ العدل وإقامة الشرع وإبطال الحوادث والمكوس المبتدعة، فقال: الدفتردار: إن ذلك لا يمكِنُ لأنَّه يضيِّقُ على معيشة المماليك، فقيل له: هذا ليس بعذرٍ عند الله ولا عند الناسِ، ولا داعي للإكثارِ مِن النفقات وشراء المماليك، ثم عاد المشايخ إلى الأزهر ومعهم أهل الأطراف وباتوا في المسجد، وأرسل إبراهيم بيك يشجعهم وأرسل إلى أيوب بيك يخوِّفه عاقبة الأمر، فأجاب إلى جميع ما ذكروه إلَّا شيئين: ديوان بولاق، وطلب المنكسر من الجامكية، وما عدا ذلك من المكوس والحوادث والظلم فيُرفع، ثم اجتمع الأمراءُ وأرسلوا إلى المشايخ، فحضر الشيخ الشرقاوي والبكري والنقيب والسادات، ودار الكلام بينهم والتزموا بما شرطه العلماءُ عليهم وانعقد الصلحُ على أن يدفعوا سبعمائة وخمسين كيسًا موزعة وأن يرسِلوا غلال الحرمين ويَصرِفوا غلالَ الشون وأموال الرزق، ويُبطلوا المظالم المحدَثة والتفاريدَ والمكوس ما عدا بولاق، وأن يكفُّوا أتباعهم عن مدِّ أيديهم إلى أموالِ الناس وأن يسيروا في الناس سيرةً حسنة، وكتب حجَّةً بذلك وفرمن عليها الباشا، وختم عليها إبراهيم بيك وأيوب بيك، وانجَلَت الفتنة، ولكنَّ الحالَ لم يدُمْ أكثر من شهر حتى عاد ما كان على ما كان وزيادة."},{"id":4245,"title":"عساكر الشريف غالب يغزون نجد .","date":["العام الهجري :1210","العام الميلادي :1795"],"text":"جمعَ الشريفُ غالب بن مساعد عساكِرَ كثيرةً، واستعمل عليها الشريفَ فهيد، فقصدوا قحطان وهم على ماسل الماء المعروف في عالية نجد، فتقاتلوا أشدَّ القتال، وانهزم ابن قرملة ومن معه من بني قحطان، فقُتل منهم 30 رجلًا، وأُخِذ منهم نحو 3000 من الإبل، ولَمَّا انهزموا ذهبوا مُشاةً في الصحراء ومعهم الأطفال والنساء وكادوا أن يهلِكوا من العطَشِ."},{"id":4246,"title":"غزو إبراهيم بن عفيصان عمان .","date":["العام الهجري :1210","العام الميلادي :1795"],"text":"لَمَّا وصل نفوذُ دولة الدرعية إلى منطقةِ الأحساء بدأ قادةُ الدولة يتطلَّعون إلى نشرِ مبادئ الدعوة في عمان، فأمر الإمامُ عبد العزيز بن محمد قائدَه مطلق المطيري بغزو عمان الصير؛ حيث تقطُنُ قبيلة بني ياس، إلا أنَّه لم يوفَّقْ في الاستيلاء على المنطقة، فعندها رأى الإمامُ عبد العزيز أن يكِلَ الأمر إلى قائده إبراهيم بن عفيصان الذي قاد معظَمَ الحملات السابقة في شرق الجزيرة، فقاد جيشًا كبيرًا إلى منطقة عمان الصير ضِدَّ بني ياس، وقاتلهم حتى طلبوا الأمانَ مِن الدرعية، ثم تبِعَتهم قبيلةُ نعيم التي تقطُنُ في البريمي، وتقَدَّم إبراهيم بن عفيصان إلى واحةِ البريمي وبنى فيها قصرَ الصبارة في منتصَفِ الطريق الواصل بين البريمي وحماسا؛ ليكون قاعدةً لقوات الدرعية في المنطقةِ."},{"id":4247,"title":"هزيمة عساكر الشريف غالب في معركة الجمانية .","date":["العام الهجري :1210","العام الميلادي :1795"],"text":"جمع الشريفُ غالب صاحِبُ مكَّةَ جموعًا كثيرةً مِن باديتِه وحاضرته، واستعمل عليهم أميرًا الشريفَ ناصر بن يحيى، وسار من مكة، فلما بلغ خبرُهم الإمامَ عبد العزيز بن محمد بن سعود، أمر محمد بن حمود بن ربيعان ومن تبعه من عُربان عتيبة, وفيصل الدويش ومن تبعه من مطير, وربيع بن زيد أميرَ جميع الدواسر الحاضرة والبادية، وأمر أيضًا عربان السهول وعربان سبيع وعربان العجان وغيرهم من بوادي نجد؛ أمرهم جميعًا أن ينزلوا على هادي بن قرملة رئيس قحطان وعُربانه، فاجتمعت تلك البوادي والجنودُ قُرب الجمانية: الماء المعروف عند جبل النير في عالية نجد، وتلك العُربان يشربون من مياه قريبةٍ منها، ثمَّ إن الشريف ناصر سار بالجموع والعساكرِ العظيمةِ ومعهم مِدفَعٌ، ونزلوا على ماء الجمانية، واجتمع عليه كثيرٌ من عربان الحجاز بأموالها وعيالها، فالتقت الجنودُ على ماء الجمانية، والتحم القتال بين الفريقين واقتتلوا أشدَّ القتال، وكثُرَ القتلى في الفريقين، فقتل من الجميع نحو 100 رجل, فحمل هادى بن قرملة بمن معه على جنودِ الشريف ناصر، فولَّوا منهزمين على أعقابِهم، فلَحِقَهم أولئك البوادي والجنود يقتُلون ويَغنَمون، فقُتِلَ منهم نحوُ ثلاثمائة رجل, وغَنِمَ منهم إبلًا وأموالًا كثيرة, وخيمةَ الشريف ومِدفَعَه، وانهزم الشريف ومن معه إلى أوطانِهم، وتفَرَّقت عُربانه، وعُزِلت الأخماس وأرسلوها إلى الإمام عبد العزيز. وكان الإمامُ عبد العزيز قد بعث محمَّدَ بن معيقل ردءًا لابن قرملة وعونًا له, فانفضَّ الأمر وانقضى عند مجيئه, فحثَّ ابن معيقل السيرَ في أثر الشريف ناصر وعُربانه، وأدرك بني هاجر وهم على الماء المعروف بالقنصلية قرب بلد تربة، فشَنَّ عليهم الغارةَ وقاتلهم، فانهزموا وقَتَل منهم 40 رجلًا، وأخَذَ جميعَ أموالِهم."},{"id":4248,"title":"الولايات المتحدة توقع معاهدة مع العثمانيين تدفع على إثرها الجزية .","date":["العام الهجري :1210","الشهر القمري : صفر","العام الميلادي :1795"],"text":"في أواخرِ القرن الثامن عشر الميلادي بدأت السفنُ الأمريكية بعد أن استقلَّت أمريكا عن إنجلترا سنة 1190هـ ترفعُ أعلامَها لأولِ مرَّةٍ سنة 1197هـ وتجوب البحارَ والمحيطات. وقد تعرَّض البحَّارة الجزائريون لسفن الولايات المتحدة، فاستولوا على إحدى سفنِها في مياه قادش، وذلك في رمضان 1199هـ ثم ما لَبِثوا أن استولوا على إحدى عشرة سفينةً أخرى تخصُّ الولايات المتحدة الأمريكية وساقوها إلى السواحِلِ الجزائرية. ولَمَّا كانت الولايات المتحدة عاجزةً عن استرداد سُفُنِها بالقوَّةِ العسكرية، وكانت تحتاجُ إلى سنوات طويلة لبناء أسطولٍ بحري يستطيعُ أن يواجه الأسطولَ العثماني اضطرَّت إلى الصُّلحِ وتوقيعِ معاهدة مع الجزائر في 21 صفر من هذا العام, وقد تضَمَّنت هذه المعاهدة 22 مادة مكتوبةً باللغة التركية، وهذه الوثيقةُ هي المعاهدة الوحيدة التي كُتِبت بلغة غير الإنجليزيةِ ووقَّعَت عليها الولايات المتحدة الأمريكية خلال تاريخِها الذي يتجاوزُ قرنين من الزمان، وفي الوقتِ نفسِه هي المعاهَدة الوحيدة التي تعهَّدت فيها الولايات المتحدة بدفعِ ضريبةٍ سنوية، وبمقتضاها استردَّت الولايات المتحدة أَسراها، وضَمِنَت عدم تعرض البحَّارة الجزائريين لسُفُنِها."},{"id":4249,"title":"وقوع غزوة الرقيقة وخضوع الأحساء لنفوذ دولة الدرعية .","date":["العام الهجري :1210","الشهر القمري : ذي القعدة","العام الميلادي :1796"],"text":"بعد طلَبِ برَّاك بن عبد المحسن الأمانَ لأهل الأحساء من الإمام عبد العزيز بن محمد، أُجيب إلى طلبِه، وانسحب جيشُ الأمير سعود من الأحساءِ بعد مبايعة أهلِها على السمع والطاعة، وبعد ذلك بسنواتٍ ثار أهل الأحساء بتحريضٍ مِن براك بن عبد المحسن نفسِه، ولكنْ قضى على ثورتهم إبراهيمُ بن عفيصان، ثمَّ وصول قوات كبيرة بقيادة الأميرِ سعود بن عبد العزيز الذي أخضع الأحساءَ لحكم دولة الدرعيةِ، وضرب عليهم ألوفًا من الدراهم وقبَضَها منهم؛ وذلك لأجلِ ما تكرَّر منهم من نقضِ العهد ومنابذة الدولةِ، وجَرِّهم الأعداء, وقَتَل منهم عِدَّةَ رجال مجتمعين على الفسوقِ ويفعلون كل ما أرادوه بأهوائِهم، ولا يتجاسرُ أحدٌ أن يأمُرَهم وينهاهم، فكثُرَ لذلك تعدِّيهم واعتداؤهم على أهلِ الأحساءِ، فأفنى الأميرُ سعود مُعظَمَهم, وسُمِّيت هذه الغزوة بغزوة الرقيقة (وهي محلة بالهفوف) وذلك في أواخرِ هذه السنة، وعاد إلى الدرعيَّة ومعه عدد من رؤساء أهل الأحساءِ، منهم علي بن حمد آل عمران مبارك، وحمد العدساني، ورجال كثيرٌ، وأسكنهم الدرعية، وولَّى على المنطقة أميرًا من عامَّةِ أهلها يُدعى ناجم بن دهينيم، وكان من نتائجِ استيلاء الأمير سعود على الأحساء وصولُ حدود دولة الدرعية إلى الخليجِ العربي، وامتلاكُها موانئَ بحرية، وتحقيقُ ثروة من المحاصيل الزراعية والمواد الغذائية التي تنتِجُها مزارِعُ الأحساء الواسعة، وانتشار الدعوة الإصلاحية بين سكَّان الأحساء."},{"id":4250,"title":"وفاة آغا محمد خان قاجار حاكم إيران وتولي فتح علي شاه زعامة القاجاريين .","date":["العام الهجري :1211","العام الميلادي :1796"],"text":"هو آغا محمد خان بن محمد حسن خان القاجاري بن فتح علي خان بن شاه قلي خان، حاكم إيران. من مواليد 27 محرم 1155 في استر آباد وهو مؤسِّس الدولة القاجارية الشيعية في إيران- ومعنى آغا أي مَخصِي- وقيل: إنَّ محمد خان زند، هو الذي أخصى آغا محمد خان؛ لأنَّه تزوَّج من بنت أخيه علي خان زند بدون عقدٍ، وقيل إنَّ خِصاءَ آغا محمد خان كان على يد عادل شاه خليفة نادر شاه. أطاح آغا محمد خان بحُكم خلفاء كريم خان زند، ثم وصل إلى الحُكمِ وجعل طهرانَ عاصِمةً له، وكان حادَّ الطبع عنيفًا، واستطاع أن يوحِّدَ إيران بحملاته وهجومِه المتكَرِّر على أطرافها, ثم هجم على جورجيا وانتصر على أهلِها واستباحهم قتلًا وأسرًا واسترقَّ 15 ألفًا من بناتهم وأبنائهم, ثم باعهم كرقيق لأغنياء طِهران, ثمَّ تُوِّج مَلِكًا على إيران في سنة 1208 هـ ثمَّ اتَّجه آغا محمد بعد تتويجِه بعساكره إلى خراسان وقتل شاهرخ بن نادر شاه أفشار، والذي كان رجلًا طاعنًا في السن وكفيفًا؛ وذلك انتقامًا لقتل فتح علي خان رئيس القاجار، ولأجل الحُصولِ على المجوهرات التي جلبها نادرٌ من الهند، فعذَّبه عذابًا شديدًا مات على إثره بعد أن عرف منه مكانَ جواهرِ نادر شاه, وعزم الهجومَ على بخارى والإطاحة بحكَّامِها الذين كان ولاؤهم للرِوس، ودخل مرو وأجبر أوزبكان على الانسحاب منها، وجعل بخارى تحت الوصاية الإيرانية، ثم أمر بتعقُّب نادر قلي شاهرخ أفشار حتى قبضه حاكمُ بلخ الذي دفع 5000 قطعة ذهبية ليقبِضَ عليه. كان سببُ مقتل أغا محمد أنَّ خادمَين مِن خَدَمِه تخاصما فحَنق عليهما جدًّا حتى أمر بقتلِهما وأمهلهما لليوم التالي، ومع ذلك بَقِيا في خدمته، فرأيا أنهما لا يتخلَّصان من القتلِ إلَّا بقتلِه، فلما جنَّ الليل رافقهما خادمٌ ثالث ودخلوا على الأغا، وقتلوه وهو نائم بعد أن حكم إيران نحًوا من عشرين سنة، فخلَفَه ابنُ أخيه فتح علي شاه."},{"id":4251,"title":"ولاية ثويني بن عبد الله للمنتفق .","date":["العام الهجري :1211","العام الميلادي :1796"],"text":"في هذه السنة عزل سليمان باشا صاحَبَ العراقِ حمودَ بن ثامر عن ولاية المنتفق، وولَّى عليهم ثويني بن عبد الله، وكان ثويني قد قصد البصرةَ ونزل سفوان الماء المعروف قربَ البصرة، فاجتمع إليه قبائِلُ من عُربان المنتفق, فسار إليه حمود بن ثامر بمن تَبِعه من المنتفق وأهل الزبير وغيرهم, فنازله وحصل بينهما قتالٌ شديد انهزم ثويني فأخذ حمود ومن تبعه محلَّه ومتاعه وخيامه، وقُتِل من رجالِه عِدَّةُ قتلى, فهرب ثويني بعدها إلى الدورق بلاد كعب، وذلك في سنة 1204هـ, ثم خرج من الدورق وقصد بني خالد واستنصرهم واستنجدهم، وكان رئيسُهم يومئذ زيدَ بن عريعر، فلم يجِدْ فيهم نفعًا، فسار الى الدرعيَّة وألفى عبد العزيز فأكرمَه غاية الإكرام وأعطاه خيلًا وإبلًا ودراهمَ، ثم رجع إلى الكويت، وقصد العراقَ فرمى بنفسِه على سلمان باشا فعفا عنه، وأقام عنده مدَّةً يحاولُه أن يوليه على المنتفق، ويسير إلى نجد ليخربَها ويقتُل أهلها، فوقع ذلك في ظنِّ صاحب العراق، وسعى في ذلك كثيرُ الجالين من أهل نجد في الزبير والبحرين والكويت وغيره، وكاتبوا باشا بغداد وحرَّضوه وزيَّنوا له ذلك, وكاتبه كثيرٌ من الرؤساء والعلماء لا سيَّما محمد بن فيروز؛ فإنه الذي يحكم ذلك ويبذُلُ جُهدَه، وذكروا لباشا بغداد أنَّه لا ينجع في هذا الأمر الخطير والخطب الكبير إلا ثويني، وكتبوا له كثيرًا من الكَذِب والزور والبهتان في أتباعِ الدَّعوةِ، ولم يدْرِ الباشا أنَّ هذا التدبير لقصدِ أنفُسِهم، وقال له ثويني: أنا الذي أخربُ ديارهم، وأسلبُ أعمارَهم، فأمره الباشا بالمسير وسار معه عساكِرُ كثيرة من عسكر الباشا، ومِن عقَيل بغداد وآل بعيج والزقاريط وغيرهم، وجعله واليًا على المنتفق، وعزل حمودَ بنَ ثامر."},{"id":4252,"title":"سيل موصة في نجد .","date":["العام الهجري :1211","العام الميلادي :1796"],"text":"نزل سيلٌ عظيم أشفق منه كثيرٌ من أهل البلدان، وغرق منه حلةُ بلد الدلم ومحاها، ولم يبقَ مِن بيوتها  إلا القليل. وذهب لهم أموالٌ كثيرة من الطعام والأمتعة وغيرها, ونزل على بلدِ حريملاء بردٌ لم يُعرَف له نظير وخسَف السطوحَ وقتَلَ بهائمَ، وكسَّر عُسبان النخل والأشجار، وهَدَّم الجدران، حتى أشرفوا على الهلاك، ثم جاء في الصيف سيلٌ عظيم أشفق منه أهل البلدان، وهدم بعضَ حوطة بني تميم، وذهب بزروعٍ كثيرة محصورة، وجاء في وادي حنيفة سيلٌ عظيم هدم في الدرعية بيوتًا وارتفع على الدكاكين، وهدمَ في العُيينة بيوتًا كثيرةً، وسمَّى أهلُ الدرعية هذا السيل موصة."},{"id":4253,"title":"الدولة العثمانية تعقد معاهدة استانبول مع روسيا .","date":["العام الهجري :1211","الشهر القمري : محرم","العام الميلادي :1796"],"text":"عقدت الدولةُ العثمانيةُ مُعاهدة استانبول مع روسيا بعد مفاوضات استمرَّت خمسة أشهر، وتضَمَّنت المعاهدة أربعةَ عشر بندًا، منها أن يكونَ ذَهابُ وإياب السفير الروسي إلى استانبول عن طريقِ البر، وليس عن طريقِ البحرِ؛ لأنَّ البحر الأسود بحرٌ عُثماني مُغلَق."},{"id":4254,"title":"علماء نجد يناظرون علماء الحرم .","date":["العام الهجري :1211","الشهر القمري : رجب","العام الميلادي :1797"],"text":"طلب الشريفُ غالب بن مساعد شريفُ مكة من الإمام عبد العزيز بن محمد أن يبعثَ إليه عالِمًا ليناظِرَ علماء الحرم الشريف في شيءٍ من أمور الدين، فبعثَ إليه الإمامُ عبد العزيز الشيخَ حمد بن ناصر بن معمر على رأسِ ركبٍ من العلماء، فلمَّا وصلوا إلى الحرم الشريف أناخوا رواحِلَهم أمام قصرِ الشريف غالب فاستقبلَهم بالحفاوة والإكرام، وأنزلهم منزلًا محترمًا يليقُ بهم، فلما طافوا وسعَوا للعمرة ونحروا الجَزورَ التي أرسلها معهم الأمير سعودُ بن عبد العزيز هدْيًا للحرم، واستراحوا أربعة أيام من عناء السَّفر- جمعَ الشريفُ غالب علماءَ الحرم الشريف من أربابِ مذاهِبِ الأئمة الأربعة ما عدا الحنابلة، فوقع بين علماء الحرم ومقَدَّمِهم يومئذ في الكلام الشيخ عبد الملك القلعي الحنفي، وبين الشيخ حمد بن ناصر بن معمر في مناظرةٍ عظيمة في مجالِسَ عديدة بحضرةِ والي مكة الشريف غالب، وبمشهدٍ عظيمٍ من أهل مكة، فظهر عليهم الشيخ حمد بن ناصر بن معمر بالحجَّة وقهَرهم بالحقِّ، فسَلَّموا له وأذعنوا، وقد سألهم ثلاثَ مسائِلَ: الأولى: ما قولُكم فيمن دعا نبيًّا أو وليًّا، واستغاث به في تفريجِ الكرباتِ كقوله: يا رسول الله، أو يا ابن عبَّاس، أو يا محجوب، أو غيرهم من الأولياء الصَّالحين؟. والثانية: من قال لا إلهَ إلا الله، محمدٌ رسُول الله، ولم يصَلِّ ولم يزَكِّ، هل يكون مؤمِنًا؟. والثالثة: هل يجوز البناءُ على القبور؟ فعكس علماءُ الحرم هذه الأسئلةَ على الشيخ حمد، وطلبوا منه الإجابةَ عليها، فأجاب عنها بما يشفي الغليلَ، وأصَّلَ الإجابةَ وحرَّرها لهم في رسالةٍ سَمَّاها علماء الدرعية \"الفواكهُ العِذاب في الردِّ على من لم يُحَكِّم السُّنَّة والكتاب\" وهي رسالةٌ جليلةُ القدرِ عظيمةُ الفائدةِ."},{"id":4255,"title":"عتيبة وعربان الحجاز يبايعون الإمام عبد العزيز .","date":["العام الهجري :1212","العام الميلادي :1797"],"text":"أرسل حمود بن ربيعان ومَن تَبِعَه من عتيبة وعُربان الحجاز إلى الإمام عبد العزيز وطلبوا منه البيعةَ على دينِ الله ورسولِه والسَّمعِ والطاعة، وأداءِ الزكاة وألَّا يعترِضوا سُبُلَ المسلمين، وبَذَلوا دراهِمَ معلومةً نكالًا، فأجابَهم عبد العزيز إلى ذلك، وأخذ على كل بيتٍ عِدَّةَ دراهِمَ معلومة، فلمَّا بلغ الشريف غالب ذلك الخبَرُ، أفزعه وأهمَّه، فجهَّز العساكِرَ مِن مكَّةَ وما حولها، فخرج بنفسِه وقصد هادي بن قرملة أتباعه من قحطان وغيرهم، فنازلهم وحصل بينهم بعضُ القتال، فأخذ هادي جملةً مِن أثقاله، ثم نزل الشريفُ على الماء المعروف بالقنصلية قرب بلد تربة، ونزل هادي بن قرملة بلدَ رنية، فسار الشَّريفُ إليه فيها، فنازلهم ووقع بينهم قتالٌ شديد قُتِلَ بين الجميعِ عِدَّةُ رِجالٍ."},{"id":4256,"title":"الحملة الفرنسية بقيادة نابليون بونابرت على مصر .","date":["العام الهجري :1212","العام الميلادي :1797"],"text":"أمرت الجمهوريةُ الفرنسيَّةُ بونابرت بالمسيرِ إلى مصر لفتحِها بغير إعلانِ حربٍ على الدولة العليَّة، وأوصَتْه بكتمانِ الأمر حتى لا تعلَمَ به إنكلترا فتسعى في إحباطِه، وكان القصدُ من الحملة منعَ مرور تجارة الإنجليز من مصرَ إلى الهند, كانت تلك الحملةُ صدًى للثورة الفرنسية المتأثِّرة بأفكارِها الثوريَّة الماسونية اليهودية، ورَفْع شعاراتها (الحرية, العدل, المساواة). فجهَّز جيشًا من 36 ألف مقاتل وعشرة آلاف بحري، وأضاف إلى جيشه 122 عالِمًا على اختلافِ العلوم والمعارف لدراسةِ القُطر المصري والبحث عما يلزم لإصلاحِه واستغلاله, وكان هذا العددُ من العلماء يزيدُ عن أضعاف العدد الذي اعتاد بونابرت أن يصحَبَه في حملاته الأوروبية، وقد تأثَّر فكرُ هؤلاء العلماء في الغالب بالدَّورِ الفرنسي الذي يسعى لإصلاحِ الكنيسة الكاثوليكية، ويعادي حركاتِ الإصلاح البروتستانتية، كما أنَّهم قد تأثَّروا بأفكار روسو وفولتير ومونتسكيو: أبرز مفكِّري الثورة الفرنسية والمعروفين بانتمائِهم للمحافل الماسونية اليهودية، مِن خلال ما رفعوه من شعاراتِ (الحرية، الإخاء، المساواة)، وكانت أهداف الحملةِ خليطًا من أهدافٍ اقتصادية وتوسعيَّة وسياسية ودينية، أو بالأحرى غزو عسكري فكري. في 19 مايو سنة 1798 رحل بونابرت بهذا الجيش بدون أن يُعلِم أحدًا بوجهتِه، فوصل جزيرة مالطة واحتلها بعد أن دافعَ عنها رهبان القديس يوحنا، وفي 17 محرم سنة 1213. وصل بونابرت مدينة الإسكندرية فدخلها عَنوةً، ثم ترك بها القائِدَ كليبر وسار هو للقاهرةِ، فقابله مراد بيك بشرذمة من المماليكِ عند مدينة شبراخيت بالبحيرة في 29 محرم، فهزمه بونابرت وواصل السير حتى وصل إلى مدينة إنبابة مقابل القاهرة، وحصلت بينه وبين إبراهيم بيك ومراد بيك من أمراء المماليك واقعةُ الأهرام الشهيرة في 7 صفر التي أظهر فيها المماليكُ من الشجاعة ما أدهش الفرنسيين، لكنهم تقهقروا أمام المدافِعِ الفرنسية، فدخل بونابرت وجيوشُه مدينة القاهرة، وأصدرت الحملة نداءً إلى الشعبِ بالاستكانة والتعاون، زاعمةً أن نابليون قد اعتنق الإسلامَ وأصبح صديقًا وحاميًا للإسلامِ، وأنَّه لم يأتِ لفتح مصر، بل إنَّه حليفٌ للباب العالي، أتى لتوطيد سُلطتِه ومحاربة المماليك العاصين لأوامِرِ الخليفة العثماني, ووجَّه نابليون بونابرت رسالةً إلى الشعب المصري يحثُّهم فيها على الطاعة وعدمِ المعصية، وأنَّه إنما جاء ليخَلِّصَهم من ظلم المماليك, ثم وجَّه بونابرت فرقةً احتلت مدينة القصير على البحر الأحمر، فصارت مصر في قبضة نابليون، لكِنْ لم يلبث أن وصلَه خبر واقعة أبي قير البحرية التي دمَّرَ فيها نلسن أمير البحر الإنجليزي جميعَ المراكِبِ والسفنِ الحربية الفرنسية, وقطَعَ الإنجليزُ في البحر المتوسط المواصلاتِ بينه وبين فرنسا, ولَمَّا علمت الدولة العلية باحتلال الفرنسيين لمصرَ، أخذت في الاستعدادِ لمحاربتِهم، لا سيما وأنَّها كانت مطمئنةً مِن جهة النمسا وروسيا اللتين كانتا مشتغلتين بمحاربةِ فرنسا خوفًا من امتداد مبادئها الحرَّة إلى بلادهما، ومن جهة أخرى عرض الإنجليزُ على الدولة العثمانية مساعدتَها على إخراج فرنسا من مصرَ، لا رغبةً في حفظ أملاكِ الدولة بل خوفًا على طريق الهند من أن يكونَ في قبضة دولة قوية كفرنسا, فقَبِلت الدولة العلية مساعدتَها، وكذلك عَرَضت عليها روسيا إمدادَها بمراكبها الحربية. أعلنت الدولةُ العثمانية الحربَ رسميًّا على فرنسا في 21 ربيع الأول سنة 1213هـ / 2 سبتمبر 1798م  واجتمعت الجيوشُ بمدينة دمشق وجزيرة رودس لإرسالها إلى مصرَ, وفي 22 أغسطس غادر نابليون بونابرت قائدُ الحملة الفرنسية الإسكندريةَ قاصدًا فرنسا خفيةً مع بعض قوَّادِه حتى لا يضبِطَه الإنجليز بعد أن بلَغَه خبر تغلُّب النمسا على فرنسا ووقوع الفوضى في داخل فرنسا، فأراد بونابرت الرجوعَ إليها لاستمالةِ الخواطر إليه وتأليفِ حِزبٍ يعضِّدُه في الوصولِ إلى غرضِه، وهو أن يعيَّن رئيسًا للجمهورية الفرنسية, فغادر مصرَ تاركا القائد كليبر وكيلًا عنه، ويقال: إنه أذِنَ له بإخلاءِ مصر لو رأى تغلُّب القوى الخارجية عليه؛ لعدم إمكان مساعدته بالمال أو الرجالِ نظرًا لوجود السفن الإنجليزية في البحر الأبيض طولًا وعرضًا. بقي الجيشُ الفرنسي بمصر بدون مراكِبَ تحميه من الإنجليز والعثمانيين؛ ولذلك اتَّفَق كليبر مع الباب العالي والأميرال سدني سميث على أن تنسَحِبَ العساكر الفرنسية بسلاحِها ومدافعِها وترجع فرنسا على مراكب إنجليزية، لكن الإنجليز لم يقبلوا بهذا الاتفاقِ إلَّا إذا ألقى الفرنسيون سلاحَهم بين أيادي الإنجليز، فاغتاظ كليبر لذلك وسار لمحاربةِ الجيش التركي الذي أتى إلى مصرَ تحت قيادة الوزير يوسف باشا لتسلُّمِها من الفرنسيين، فتقابل الجيشان عند المطرية في 23 شوال 1214هـ وبعد قتالٍ عنيفٍ انتصر كليبر وعاد إلى القاهرة فوجدها في قبضةِ إبراهيم بيك أحد الأمراء المصريين، وكان دخلها حالَ اشتغال الفرنسيين بالحرب، فأطلق كليبر القنابِلَ على القاهرة وخرب منها جزءًا عظيمًا، واستمَرَّت الحرب في شوارعها نحو عشرة أيام، وبعد ذلك ساد الأمنُ بالقاهرة, وفي 21 محرم سنة 1215هـ / 14 يونيه سنة 1800م قَتَل شخصٌ اسمه سليمان الحلبي القائِدَ كليبر, وبعد كليبر عُيِّن مكانه الجنرال مينو، وكان قد أظهر أنه اعتنق الدين الاسلاميَّ وتسمى عبد الله مينو. لَمَّا علم الإنجليز والعثمانيون بموت كليبر وخروج بونابرت من مصر، أنزلوا بأبي قير 30 ألف مقاتل, وتمكَّنوا من هزيمة القائد الفرنسي مينو الذي عاد إلى الإسكندرية وتحصَّن بها, ثم سار الإنجليز والأتراك إلى القاهرة، وحصروا من بَقِيَ فيها من الفرنسيين حتى أخلوا القاهرة في 28 صفر سنة 1216هـ, وخرجو منها بجميع أسلحتهم ومدافعهم. أما القائدُ مينو فبقي محصورًا في الإسكندرية ولم يقبَلْ بالتسليم إلا في 22 ربيع الآخر سنة 1216هـ / 1 سبتمبر سنة 1801م فخرج منها إلى بلادِه على مراكب الإنجليز، وبذلك انتهت الحملة الفرنسية، ورجعت البلاد إلى حُكمِ الدولة العثمانية بعد أن وطئَ هامتَها الأجنبيُّ, وارتكب الفرنسيُّون فيها فظائع شنيعة، فكم من القُرى أُحرِقَت، وكم من الدُّورِ والأموال قد سُرِقت، وكم من أعراضِ النساء الحرائر انتُهِكت, وكم من الأُسَرِ قد شُرِّدت على يد فرنسا زعيمةِ الحرية والإخاءِ والمساواةِ والإنسانية؟!"},{"id":4257,"title":"أمير القصيم يغير على عربان الشرارات بالشام .","date":["العام الهجري :1212","العام الميلادي :1797"],"text":"غزا حجيلان بن حمد أميرُ ناحية القصيم وغيرِهم، وقصَدوا أرضَ الشام وأغاروا على عُربان الشَّرارات فانهزموا فقُتِل منهم نحوُ مائة وعشرين رجلًا, وأخذوا جميعَ محلَّتِهم وأمتاعِهم وأزوادِهم, وأخذوا من الإبلِ خَمسةَ آلاف بعير وأغنامًا كثيرة, وعُزِلت الأخماسُ فأخذها عمَّالُ عبد العزيز, وقسَّم حجيلان باقيَها في ذلك الجيشِ، غنيمةُ الراجِلِ سَهمٌ والفارِسِ سهمانِ."},{"id":4258,"title":"رؤساء البقوم وأهل تربة يبايعون الإمام عبد العزيز .","date":["العام الهجري :1212","العام الميلادي :1797"],"text":"وفد رؤساءُ البقوم وأهل تربة على الإمامِ عبد العزيز وبايعوه على دينِ لله ورسولِه، وعلى السَّمعِ والطَّاعةِ."},{"id":4259,"title":"هزيمة الشريف غالب عند بلد الخرمة .","date":["العام الهجري :1212","العام الميلادي :1797"],"text":"لمَّا بلغ الإمامَ عبد العزيز غزوُ الشريف غالب رنية وبيشة، وعدوانُه على قحطان ونزولُه بلد الخرمة (من محافظات منطقة مكة المكرمة) القريبة من تربة. أرسل إلى هادي بن قرملة ومَن لديه من قبائل قحطان، وربيع بن زيد أميرِ الوادي ومن معه من الدواسرِ، وإلى قبائل من أخلاطِ القبائل البوادي، وجيشٍ مِن الحضَرِ، وأمرهم أن يجتمعوا ويكونوا في وجهِ الشريف غالب، فدهموه في منزلِه على الخرمة فانهزم عسكرُه لا يلوي أحدٌ على أحدٍ، وتركوا خيامَهم ومحَلَّهم وجميع أموالهم، وتَبِعَهم العربان في ساقتِهم يقتلون ويغنمون، ومن نجا من القتل هلك ظمأً وضياعًا، فكانت وقعةً عظيمة ومقتلةً كبيرة في عسكر الشريف من العُربان والقبائل والمصريين والمغاربة, وقيل بلغ عددُ القتلى منهم 2400 قتيل, وأُخذ جميعُ ما معهم من الخيام والذخائر والمتاع, والأثاث والأمتعة التي أخذوها من قحطان قبل هذه الوقعةِ, وغَنِموا من خزائن الشريف غالب 18 ألف مشخصٍ (عملة ذهبية تُستخدم في حينها) وانصرف الشريفُ غالب وشريدُ قَومِه مكسورين، ولم تقُمْ له بعدَ هذه الوقعة العظيمةِ قائمةٌ."},{"id":4260,"title":"هزيمة أهل العراق في وقعة سحبة ومقتل ثويني بن عبد الله رئيس المنتفق .","date":["العام الهجري :1212","الشهر القمري : محرم","العام الميلادي :1797"],"text":"لَمَّا عيَّن سليمان باشا صاحب العراق ثويني بن عبد الله رئيسًا للمنتفق وقَدِمَ ثويني البصرةَ، فرح به أهلُ البصرة وما حولها من الأوطان فرحًا شديدًا, وقالوا: هذا الذي سيأخذُ الثأر ويخربُ تلك الديار- التابعة لدولة الدرعيَّة- وأتته منهم القصائِدُ يحضُّونه ويحَرِّضونه ويعجِّلونه بالمسير, وعَمِلَ محمد بن فيروز قصيدةً في التحريض على أتباعِ الدرعية. استنفر ثويني رعاياه وحشد عُربان المنتفق وأهل الزبير والبصرة وجميع عُربان الظفير وبني خالد، بقيادة برَّاك بن عبد المحسن، ونزل مع جموعِه الجهراء 3 أشهر يحشدُ مزيدًا من البوادي والعساكر والمدافِعِ وآلاتِ الحربِ والرَّصاص والبارود والطعام، فاجتمع له ما يعجزُ عنه الحصرُ، وأركب عساكِرَه في السفنِ مِن البصرةِ، وقصد الأحساءَ في قوةٍ هائلة, فلما بلغ الإمام عبد العزيز ذلك أمَّر على أهل الخرج والفرع ووادي الدواسر والأفلاج والوشم وسدير وجبل شمر، فاجتمعوا واستعمَلَ عليهم أميرًا هو محمد بن معيقل، فساروا ونزلوا قريةَ الماء المعروف في الطف من ديار بني خالد، وأمر الإمام عبدُ العزيز عُربانَ مطير وسبيع والعجمان وقحطان والسهول وعُربان نجد أن يحتَشِدوا بأموالهم وأهليهم ويقصدون ديار بني خالد، ثم أمر على ابنِه الأمير سعود أن يسيرَ بقوة من أهل الدرعية وبلاد العارضِ، ونزل سعود بالتنهات الروضة المعروفة عند الدهناء، ثم نزل حفر العتك فأقام عليه شهرًا. أما ثويني فنزل بالطف ثم رحل منه إلى الشباك الماء المعروف في ديرة بني خالد، وبينما ثويني ينصب خيمتَه عدا عليه عبدٌ اسمُه طعيس فطعنه طعنةً أدت إلى قتله في ساعتِها، فلما قُتل ثويني وقع التخاذُلُ والفشلُ في جنودِه والعساكرِ التي جمعها، فارتحلوا منهزمين لا يلوي أحدٌ على أحد، فتبعهم حسن بن مشاري بمن معه يقتُلون ويغنمون إلى قربِ الكويت وحازوا منهم أموالًا عظيمةً من الإبل والغنم والأزواد والأمتاع وجميع المدافِعِ والقنابر،  فلمَّا بلغ الأمير سعود مقتلُ ثويني، أقبل من مكانه إليهم وقسَّم الغنائم وعزَل أخماسَها, ثم سار ونزل شمال الأحساءِ، فخرج إليه أهلُها وبايعوه على دين الله والسَّمع والطاعة."},{"id":4261,"title":"وفاة ثويني بن عبد الله رئيس المنتفق  .","date":["العام الهجري :1212","الشهر القمري : محرم","العام الميلادي :1797"],"text":"هو الأميرُ ثويني بن عبد الله بن محمد بن مانع آل شبيب السعدون، من فرع آل شبيب رئيس المنتفق، خَلَف والدَه في رئاسة المنتفق في العراق سنة 1175هـ وهو صغير السن، واستفرد بزعامة المنتفق بعد مقتلِ ابنِ عمِّه ثامر بن سعدون بن محمد بن مانع سنة 1193هـ / 1779م. احتلَّ البصرة سنة 1202ه فحكمها مستقلًّا ثلاث سنوات، التجأ ثويني إلى الدرعية مستنصرًا بحاكِمِها الإمامِ عبد العزيز ليستعيدَ رئاسته للمنتفق، فقدَّم له الإمام العونَ والمدد، ثم حاول غزوَ الدرعيةِ مرَّتين، وقُتِل اثناء الحملة الثانية على يد أحدِ غِلمانِه"},{"id":4262,"title":"الأمير سعود بن عبد العزيز يسير إلى سوق الشيوخ بالبصرة .","date":["العام الهجري :1212","الشهر القمري : رمضان","العام الميلادي :1798"],"text":"سار الأميرُ سعودُ بن عبد العزيز من جميعِ نواحي نجدٍ وعُربانها وقَصَد الشمال، وأغار على سوقِ الشيوخ المعروفِ عند البصرة، وقُتِل منهم قتلى كثيرة وهرب أناسٌ وغَرِقوا بالشطِّ، ثم قصد جهةَ السماوة فأتاه عيونُه وأخبروه بعُربان كثير مجتمعينَ في الأبيض الماء المعروف قرب السَّماوة, فنازلهم على مائِهم ذلك, وكانت تلك العُربان كثيرةٌ مِن عُربان شمر ورئيسُهم مطلق بـن محمد الجربا الفارس المشهور، ومعه عِدَّةٌ من الظفير، وعُربان آل بعيج والزقاريط وغيرهم, ونازلهم سعود وحصل بينهم قِتالٌ شديدٌ حتى حمل عليهم سعودٌ ومن معه فدهموهم في منازِلِهم وبيوتِهم، فقُتِل عِدَّةٌ مِن فرسان شمر وآل ظفير، وقُتِل مطلق الجربا قائِدُهم، فانهزمت القبائِلُ التي معه، وغَنِم سعود أكثَرَ محلَّتِهم وإبلِهم وأمتاعِهم."},{"id":4263,"title":"الشريف غالب بن مساعد يغزو رنية وبيشة ويغير على قحطان .","date":["العام الهجري :1212","الشهر القمري : ذي القعدة","العام الميلادي :1798"],"text":"سار الشَّريفُ غالب بن مساعد شريفُ مكَّةَ بالعساكِرِ العظيمة من الباديةِ والحاضرة وأهلِ مِصرَ والمغاربة؛ سار في عددٍ عظيمٍ وعُدَّة وكمية هائلة من المدافِعِ والآلاتِ وتوجَّه إلى بلد رنية ونازل أهلَها وحاصَرَها، ودمَّرَ فيها نخيلًا وزروعًا ووقع بينه وبين أهلِها قِتالٌ شديدٌ قُتِل فيه من عسكرِ الشريف غالبٍ عدَّةُ قتلى، وأقام محاصِرَها عشرين يومًا، ثم ارتحل منها إلى بيشة، ونازل أهلَها وحصل بينهم قتالٌ، وكان له في البلد بطانةٌ فمالوا معه فظَفِرَ بها ودخلوا في طاعتِه وأقام عليها أيامًا، وكان قبل حصارِه بلد رنية وبيشة أغار على قبائِلِ قحطان وأخذ عليهم إبلًا كثيرة وأمتعةً، وقتل عِدَّةَ قتلى منهم. يقول الشوكاني عن قتال الشريف غالب لدولة نجد: \"كثيرًا ما يجمع الشريف غالب الجيوشَ ثم يغزو أرضَ نجد فيصِلُ أطرافَها فيَبلُغُنا أنه يقوم لحَربِه طائفةٌ يسيرةٌ من أطراف البلاد فيهزمونه ويعود إلى مكةَ، وآخِرُ ما وقع منه ذلك سنة 1212 فإنه جمع جيشًا كثيرًا وغزا نجدًا وأوقع ببعض البلاد الراجعةِ إلى سُلطانِ نجد المذكور، فلم يشعُرْ إلا وقد دهَمَه جيشٌ لا طاقةَ له به، أرسله صاحِبُ نجدٍ، فهزمه واستولى على غالب جيشِه قتلًا وأسرًا، بل جاءت الأخبارُ بأنَّه لم يسلَمْ مِن جيش الشريفِ إلَّا طائفةٌ يسيرة، وقُتِل جماعة من أشراف مكةَ في المعركة، وتمَّت الهزيمة إلى مكة، ولو ترك الشريفُ ذلك واشتغل بغيرِه، لكان أولى له؛ فإنَّ من حارب مَن لا يقوى لحَربِه جَرَّ إليه البلوى، فإنَّ صاحِبَ نجد تبلُغُ عنه قوةٌ عظيمة لا يقوم لمثلها الشريف؛ فقد سَمِعنا أنه قد استولى على بلاد الحَسا والقطيفِ وبلاد الدواسر وغالب بلاد الحجاز، ومن دخل تحت حوزتِه أقام الصَّلاةَ والزكاةَ والصيامَ وسائِرَ شعائر الإسلامِ، ودخل في طاعتِه مِن عرب الشام الساكنين ما بين الحجازِ وصعدة غالبُهم، إمَّا رغبةً وإمَّا رهبةً، وصاروا مقيمين لفرائِضِ الدين بعد أن كانوا لا يعرفونَ مِن الإسلام شيئًا ولا يقومون بشيءٍ مِن واجباتِه إلَّا مجرَّد التكلُّم بلفظ الشهادتين على ما في لفظِهم بها من عِوَجٍ، وبالجملة فكانوا جاهليةً جَهلاءَ كما تواترت بذلك الأخبارُ إلينا، ثم صاروا الآن يصلُّون الصلواتِ لأوقاتِها ويأتون بسائِرِ الأركانِ الإسلاميَّةِ على أبلَغِ صِفاتِها\""},{"id":4264,"title":"قيادة مناع أبي رجلين الحملة الثانية على الكويت .","date":["العام الهجري :1212","الشهر القمري : ذي القعدة","العام الميلادي :1798"],"text":"قاد مناع أبو رجلين الحملةَ الثانيةَ على الكويت بعد حملةِ إبراهيمَ بنِ عفيصان، وكان النصرُ حليفَ قوات دولة الدرعيَّة، واضطُرَّ آل صباح إثرَ هذه الحملة إلى أن يُحيطوا الكويت بسورٍ منيع حتى تستطيعَ صَدَّ العمليات العسكرية الموجَّهة ضِدَّها."},{"id":4265,"title":"الشريف غالب يصالح الإمام عبد العزيز ويبايعه ويأذن له بالحج .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"لم يلبَث الشريفُ غالب شريفُ مكَّةَ بعد هزيمتِه في الخرمة (من محافظات منطقة مكة المكرمة) أنْ صالحَ الإمامَ عبد العزيز وبايعه وأذِنَ له ولأتباعِه بالحَجِّ."},{"id":4266,"title":"كتاب بونابرت للشعب المصري .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"يقول الجبرتي: \"كانت الفرنسيسُ حين دخولهم بالإسكندرية كتبوا مرسومًا وطبَعوه وأرسلوا منه نُسخًا إلى البلاد التي يَقدَمون عليها؛ تطمينًا لهم، ووصل هذا المكتوبُ مع جملةٍ مِن الأُسارى الذين وجدوهم بمالطة وحضروا صُحبتَهم، وحضرَ منهم جملةٌ إلى بولاق، وذلك قبل وُصولِ الفرنسيس بيومٍ أو بيومين، ومعهم منه عِدَّةُ نُسَخ، ومنهم مغاربة وفيهم جواسيس وهم على شَكلِهم من كفَّار مالطة ويعرفون باللغات, وصورةُ ذلك المكتوب: \"بسم الله الرحمن الرحيم، لا إله إلا اللهُ لا ولد له ولا شريكَ له في مُلكِه، من طرف الفرنساوية المبني على أساس الحرية والتسوية، السير عسكر الكبير أمير الجيوش الفرنساوية بونابارته يعرف أهالي مصرَ جميعَهم أنَّ من زمان مديد الصناجق الذين يتسلَّطون في البلاد المصرية يتعاملون بالذل والاحتقار في حقِّ الملة الفرنساوية؛ يظلمون تجارَها بأنواع الإيذاء والتعدي، فحضر الآن ساعةَ عقوبتهم وأخَّرنا من مدة عصور طويلة هذه الزمرة المماليك المجلوبين من بلاد الأزابكة والجراكسة يُفسِدون في الإقليم الحسن الأحسَنِ الذي لا يوجدُ في كُرة الأرض كلِّها، فأمَّا رب العالمين القادِرُ على كل شيء فإنه قد حكمَ على انقضاء دولتهم، يا أيها المصريون، قد قيل لكم إنَّني ما نزلت بهذا الطرفِ إلَّا بقصد إزالة دينكم، فذلك كَذِبٌ صريحٌ، فلا تصَدِّقوه، وقولوا للمفترين إنَّني ما قَدِمت إليكم إلَّا لأخَلِّص حَقَّكم من يد الظالمين، وإنني أكثَرُ من المماليك أعبد الله سبحانه وتعالى وأحترِمُ نبيه والقرآن العظيم، وقولوا أيضًا لهم إنَّ جميع الناس متساوون عند الله، وإنَّ الشيء الذي يفرقُهم عن بعضِهم هو العقلُ والفضائِلُ والعلوم فقط، وبين المماليك والعقل والفضائل تضاربٌ، فماذا يميزُهم عن غيرِهم حتى يستوجِبوا أن يتمَلَّكوا مصر وحدَهم ويختَصُّوا بكل شيءٍ أحسَن فيها من الجواري الحِسان والخيل العتاق والمساكِن المفرحة، فإن كانت الأرضُ المصرية التزامًا للمماليك فليُرونا الحُجَّة التي كتبها الله لهم، ولكنَّ رب العالمين رؤوفٌ وعادل وحليم، ولكنْ بعونه تعالى من الآن فصاعدًا لا ييأس أحد من أهالي مصر عن الدخول في المناصب السامية وعن اكتساب المراتب العالية؛ فالعلماء والفضلاء والعقلاء بينهم سيدبِّرون الأمور، وبذلك يصلُحُ حال الأمَّة كُلِّها، وسابقًا كان في الأراضي المصرية المدنُ العظيمة والخلجان الواسعة والمتجر المتكاثر، وما أزال ذلك كلَّه إلا الظلمُ والطمع من المماليك، أيها المشايخُ والقضاة والأئمة والجربجية وأعيان البلد، قولوا لأمَّتِكم إن الفرنساوية هم أيضًا مسلمون مخلصون، وإثبات ذلك أنهم قد نزلوا في رومية الكبرى وخرَّبوا فيها كرسيَّ الباب الذي كان دائمًا يحثُّ النصارى على محاربة الإسلام، ثم قصدوا جزيرة مالطة وطردوا منها الكواللرية الذين كانوا يزعُمون أن الله تعالى يطلب منهم مقاتلةَ المسلمين، ومع ذلك الفرنساوية في كلِّ وقت من الأوقات صاروا محبِّين مخلصين لحضرة السلطان العثماني وأعداءِ أعدائِه، أدام الله مُلكَه، ومع ذلك إنَّ المماليك امتنعوا من إطاعة السلطان غيرَ ممتثلين لأمره، فما أطاعوا أصلًا إلَّا لطمع أنفسهم، طوبى ثم طوبى لأهالي مصر الذين يتَّفقون معنا بلا تأخير، فيَصلُح حالهم وتعلو مراتبُهم، طوبى أيضًا للذين يقعُدون في مساكنِهم غيرَ مائلين لأحدٍ مِن الفريقين المتحاربين، فإذا عرفونا بالأكثر تسارعوا إلينا بكل قلبٍ، لكنَّ الويل ثم الويل للذين يعتمدون على المماليك في محاربتِنا فلا يجدون بعد ذلك طريقًا إلى الخلاص، ولا يبقى منهم أثر\"."},{"id":4267,"title":"فشل الحملة الفرنسية في إخضاع الشام وفلسطين .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"لَمَّا اجتمعت الدولُ الثلاثُ العثمانيون والإنجليز والروس على حرب نابليون بونابرت في مصرَ، تأكَّد لديه أهميةُ مفاجأتهم باحتلالِ بلاد الشام، وأنَّ من يحتل مصر لا يكون آمنًا فيها إلَّا إذا احتَلَّ بلاد الشام, فعزم على احتلالها قبل وصولِ القوات العثمانية والإنجليزية إليها, فخرج من مصرَ ومعه ثلاثة عشر ألف مقاتل، قاصدًا بلاد الشام من طريقِ العريشِ، فاحتَلَّها ثم أخذ غزة والرملة ويافا, ثمَّ رحل من يافا لعكَّا."},{"id":4268,"title":"نابليون يجلب معه أول مطبعة لمصر أنشأها في بولاق بالقاهرة .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"ظلَّت الكتابةُ في مصرَ تعتَمِدُ على النَّسخِ اليدوي حتى نهايةِ القرن الثامن عشر، فلم يعرِفْ وادي النيل المطابعَ إلَّا مع قدوم نابليون بونابرت لمصر، الذي جلب معه من الفاتيكان أوَّلَ مطبعة أنشأها في بولاق بالقاهرة، وكان قد حَمَل معه ثلاث مطابع مجَهَّزة بحروف عربية ويونانية وفرنسية، وكان الهدفُ الأساسي لهذه المطابع هو طباعةَ المنشورات والأوامر، وكانت تقومُ بعملها في عُرض البحر، حتى دخلت الحملةُ القاهرة، فنُقِلت إليها، وعُرِفَت بالمطبعة الأهلية، وتوقَّفت هذه المطبعة بانتهاءِ الحملة الفرنسية عام 1801م."},{"id":4269,"title":"ثورة القاهرة الأولى ضد الفرنسيين وقيادة الأزهر لها .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"كان بونابرت وقت اندلاع المعركة خارجَ القاهرة، فعاد إليها مسرعًا ونصب المدافِعَ على تلال المقطَّم لتعاون مدافع القلعة في إطلاق القنابل على حي الأزهر، مركز حركة الجهاد وشُعلته المتأجِّجة. ففي اليوم الثاني للثورة (22 أكتوبر) حين شرع الثوارُ في مهاجمة مقر القيادة الفرنسية العامة بحي الأزبكية، كان الجنود الفرنسيون يهاجِمون الجامع الأزهر، ثم دخلوه وهم راكبون الخيول وسَلَبوا ما كان فيه من الودائِعِ وألقَوا الكتب والمصاحفَ على الأرض وداسوها بأرجلهم ونعالهم! وظل الجنود الفرنسيون يحتلون الأزهر حتى ذهب وفدٌ من مشايخه إلى بونابرت يطلبون منه الجلاءَ عنه، فكان ذلك نهاية للثورة التي استمَرَّت ثلاثة أيام (21-23 أكتوبر) وانتقم الفرنسيون من المسلمين في القاهرة وضواحيها أبشَعَ انتقام، فنَهَبوا ديار حي الأزهر والأحياء المجاورة، وأعدموا صغار المشايخِ الذين حرَّضوا على الثورة وصادروا ممتلكاتهم، وأحاطوا القاهرةَ وضواحيها بالحصون والقلاع والمعاقل، وهدموا في سبيل ذلك الشيءُ الكثير من المنازل والقصور."},{"id":4270,"title":"السلطان سليم الثالث يعلن الجهاد ضد الفرنسيين الذين احتلوا مصر .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"كان الهجومُ الفرنسي على مصر يُعتبَرُ أوَّلَ هجوم صليبي على ولايةٍ عربية من ولايات الدولة العثمانية في التاريخِ الحديث، وعلى الفورِ أعلن السلطانُ سليم الثالث الجهادَ على الفرنسيين الصليبيين واستجاب لدعوته المسلمون في الحجاز والشام وشمال أفريقيا, فمن الحجاز خرجت جموعٌ من المسلمين بقيادة محمد الكيلاني، وتكوَّنت من مسلمي الوجه القبلي في مصر وخاصة عرب الهوَّارة، وأهالي النوبة، وقوَّات مراد بك جبهةٌ حربيةٌ إسلامية في مواجهة جبهة حربية نصرانية كانت تتألفُ من القوات الفرنسية النهرية والبرية، والفيالق القبطية بقيادة المعلم \"يعقوب يوحنا\" في الجيش الفرنسي، وبرغم كلِّ وسائل التودُّد، فقد أبدى المصريون عدم تقبُّلِهم للفرنسيين."},{"id":4271,"title":"حصار الفرنسيين لعكا .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"بعد أن احتلَّ الفرنسيون يافا اتَّجَهوا إلى عكَّا بلد أحمد الجزَّار، فحاصروها وهاجموها مرارًا على مدى ستين يومًا، لكنهم لم يتمكَّنوا من فتحِها بسبَبِ مناعة حُصونِها, ووصولِ المدد إليها تباعًا من طريق البحر, واستيلاءِ الأميرال الإنجليزي سدني سميث على مدافِعِ الحصار التي أرسلها بونابرت من مصر لإطلاقها على أسوار عكَّا، ولتيَقُّظِ أحمد باشا الجزَّار قائدِ حاميتها، وإفسادِه الألغام التي زرعها الفرنسيون, وشِدَّةِ وطأة وباءِ الملاريا ثمَّ الطاعون الذي فتك بالفرنسيين فتكًا ذريعًا. ولَمَّا بلغ نابليون تحركُ جيش دمشق العثماني لإنقاذ مدينة عكَّا، أرسل كليبر مع فرقة من الجيش لمحاربتِه ومنعه من الوصول إليها. أمام هذه التحديات لعملياتِ بونابرت في بلاد الشام وتيقُّنِه عدم نجاحه فيها، اضطر بونابرت إلى رفع الحصار عن عكا والتراجع إلى مصر, ولكي يسرِّع من تحرك الجيشِ، أمر بأن يُدَسَّ السمُّ لكُلِّ جندي فرنسي مُصابٍ بالمرض؛ كي لا يكون هناك ما يُلكئ المسير!"},{"id":4272,"title":"الإنجليز يهزمون الفرنسيين في أبي قير .","date":["العام الهجري :1213","العام الميلادي :1798"],"text":"كانت بريطانيا تتابِعُ الأطماعَ الفرنسية في مصر وغيرها بدقَّةٍ متناهية، وعندما تحرَّكت الحملةُ الفرنسيةُ ووصلت إلى مصر، أرسلت أسطولًا بقيادة الأميرال نلسون لتعقُّبِ الحملة الفرنسية، وفاجأ نلسون الأسطولَ الفرنسيَّ وهو رابضٌ في خليجِ أبي قير بعد أن أنزل قواتِ الحملةِ في الإسكندرية، واشتبك معه في معركة أدَّت إلى إغراقِ المراكب الفرنسية في أوَّلِ أغسطس 1718م، وقد كانت إنكلترا عَرَضت المساعدة على العثمانيين؛ خوفًا على مصالحِها البحرية في الهندِ."},{"id":4273,"title":"دخول الفرنسيين الإسكندرية .","date":["العام الهجري :1213","الشهر القمري : صفر","العام الميلادي :1798"],"text":"كان أوَّل ما حضر إلى الإسكندرية في أوَّلِ هذه السنة مراكِب للإنجليز زعموا أنَّهم جاؤوا ليحمُوا الثغر من الفرنسيين، فإنَّهم في طريقهم لاحتلال مصر, ولكنَّ أهل الإسكندرية ظنُّوا أن هذه مخادعة وقالوا: هذه بلاد السلطان، لا سبيل للإنجليز ولا للفرنسيين عليها، فرحل الإنجليزُ، ومع ذلك لم يفعل أمراءُ البلد شيئًا، أما أهل الإسكندرية فجمعوا العُربان وتهيَّأ الناسُ لِمثل هذا الحدَثِ، ثم وصلت مراكبُ الفرنسيين وطلبوا القنصل وبعض أهالي البلد، فلما نزلوا إليهم عوَّقوهم، فلما دخل الليل طلعوا إلى البر ومعهم آلاتُ الحرب والعساكر، ولم يفجأ أهلَ الثغر صباحًا إلا وهم كالجراد المنتَشِر، فلم يستطع أهل الثغر ومن انضم إليهم من العُربان فِعلَ شيء أمامهم، فانهزموا إلى البيوت والحيطان، فطلبوا الأمانَ فأمَّنوهم وطلبوا جمعَ السلاح من الأهالي، ثم سار الفرنسيون إلى البر الغربي ووصلوا دمنهور ورشيد، وكان نابليون نشرَ في أنحاء مصر مع الرسُلِ قبل وصوله إلى كُلِّ بلد أنه ما جاء إلى مصر إلى ليخَلِّصَهم من ظلم المماليك والأتراك، وأنَّه يحترم الدينَ والنبيَّ صلَّى الله عليه وسلم والقرآنَ، ثمَّ في شهر صفر التقى العسكر المصريُّ مع الفرنسيين، فلم تكن ساعة إلا وانهزم مراد بيك ومن معه، وكان هذا في البحرِ، ثم ارتحل الناسُ إلى بولاق لعمل المتاريس، ثم وصل الفرنسيون إلى بر مصر، وسكن بونابرت ببيت محمد بيك الألفي بالأزبكية، ثم ملكوا مدينةَ بلبيس بغير مقاومة ولا قتال، ثم عَمِلوا ديوانًا من ستة أنفار من النصارى القبط وستة تجار من المسلمين للنظر في قضايا التجَّار والعامة."},{"id":4274,"title":"دخول الجنود الفرنسيين مدينة القاهرة واقتحام الجامع الأزهر .","date":["العام الهجري :1213","الشهر القمري : ربيع الأول","العام الميلادي :1798"],"text":"فتح الجنودُ الفرنسيون في مصرَ بعضَ البيوت المغلَقة لأمراء المماليك واستولوا على ما فيها، ثم تركوها لطائفةِ الجعيدية يستأصلونَ ما فيها، وقد توافد الفرنسيون بعدها على القاهرةِ وسَكَنوا بيوتها. فتجمَّع أهل مصر (القاهرة) وجمعوا السلاحَ والفرسان وتجمَّعوا في الأزهر وعملوا المتاريسَ ثم وصلت طائفةٌ من الفرنسيين من ناحية المناخلية، فاستطاعوا إجلاءَها من المقاتلين المصريين، فخاف الناس وأرجفوا حتى بلغ إلى نهبِ بيوت النصارى من الشاميين والروم، وأمَّا الفرنسيون فأحضروا آلاتِ الحرب على تلالِ الرقية والقلعة، وبقي الرميُ متتابعًا بين الجهتين، ثم ضرب الفرنسيون بالمدافع وتقَصَّدوا الجامع الأزهر بالضرب، وتهدَّمت كثيرٌ من البيوت، ولَمَّا تفاقم الأمر ذهب بعض المشايخ إلى كبير الفرنسيين، فعاتبهم على التأخير ولكنه رفع الرميَ عنهم، ثم دخل الفرنسيون المدينةَ كالسيل المنهَمِر ولا ممانِعَ لهم، ودخلوا الجامع الأزهر وهم راكبون على الخيولِ وبينهم المشاة، وربطوا خيولهم بقبلتِه وكسروا القناديل والخزَّانات وداسوا المصاحِفَ بأقدامِهم، ورموا بالكتب على الأرض وداسوها كذلك، وزادوا الأمرَ بأن تغوَّطوا وبالوا وشَرِبوا الخمر فيه، ونهبوا الديارَ بحجَّة التفتيش!!"},{"id":4275,"title":"قتل محمد كريم حاكم الإسكندرية لمقاومته الفرنسيين .","date":["العام الهجري :1213","الشهر القمري : ربيع الأول","العام الميلادي :1798"],"text":"لَمَّا نزل الفرنسيون بالإسكندرية أخذوا محمد كريم الذي كان بيده أمرُ الديوان والجمارك ومصادرات التجار خصوصًا من الإفرنج في الإسكندرية، فحبسوه وطالبوه بالمال وضيَّقوا عليه في المركب، ولَما حضروا إلى مصر وطلعوا إلى قصر مراد بيك، وفيها اطَّلعوا على أخبار محمد كريم وتعَرَّفوا على اجتهاده في حربِهم وتهوين أمرِهم وتنقيصِهم، فاشتد غيظُهم عليه فأرسلوا وأحضروه إلى مصر وحبَسوه، ولم تنفع الشفاعات فيه أبدًا، ثم إنهم طالبوه بقَدرٍ معين من المال كبير يَعجِز عنه وأمهلوه اثنتي عشرة ساعة فقط لإحضاره وإلَّا كان حتفُه، فسأل الناس والمشايخ، وكان يقول: اشتروني يا مسلمين! ولكن كان كلٌّ مشغول بنفسه يترقَّبُ ما يحُلُّ به، فانقضت المهلة ولَمَّا يجمعْ ما طلب منه، فأركبوه على حمار يتقدَّمهم طبل يضربون عليه حتى وصلوا به إلى الرميلة وكتَّفوه وربطوه مشبوحًا وضربوا عليه بالبنادق كعادتهم في القتل، ثم قطعوا رأسَه ورفعوه على نبوت وطافوا به يقولون: هذا جزاء من يخالف الفرنسيين، ثم إنَّ أتباعه أخذوا رأسَه ودفنوه مع جثته، وكان ذلك في يوم الخميس الخامس عشر من ربيع الأول لهذا العام!!"},{"id":4276,"title":"حملة علي كيخيا على الأحساء .","date":["العام الهجري :1213","الشهر القمري : رمضان","العام الميلادي :1799"],"text":"سيَّر سلمان باشا والي العراق العساكِرَ الكثيرة من العراق والأكراد والمحمرة، ومعهم من البوادي عُربان المنتفق مع رئيسِهم حمود بن ثامر، وعُربان آل بعيج، والزقاريط وآل قشعم، وجميع بوادي العراق، وعربان شمر والظفير، وسار معه أهل الزبير وما يليهم، وجعل على قيادةِ الحملة وزيره علي كيخيا، واتفق له قوةٌ هائلة من المدافع والقنابر وآلات الحروب، واجتمع معه جموع كثيرة، حتى قيل إنَّ الخيل الذي يعلَّقُ عليها ثمانية عشر ألف, فسار علي كيخيا بجميع تلك الجموع وقصد الأحساءَ، فلما نزل فيها تابعَه أهلُ المبرز والهفوف وقرى الشرق وجميع نواحيه، ونقضوا العهدَ مع دولة الدرعيَّة, وامتنع على حملةِ علي كيخيا قصر الصاهود بالمبرز وحصْن الهفوف، فزحف بجنوده على قصرِ الصاهود وحاصره شهرين، وبذل كُلَّ الأسباب لفتحِ بسوق الأبطال والرمي المتواصِلِ بالمدافع والقنابر، وحفر حفرًا في السورِ ملأها بالبارود، ثمَّ ثوَّرها عليهم دون طائلٍ حتى وقع فيهم الفشلُ، ولم يكن في داخل هذا القصر إلَّا 100 رجل أكثَرُهم من نجد مع سليمان بن محمد بن ماجد الناصر من أهل ثادق، وكان يتصف بالشجاعة فثبت هو ومن معه ولم يعطُوا الدنيَّةَ لعدُوِّهم حتى بطَلَ كَيدُهم ووقع في قلوبِ الكيخيا وعساكره الملَلُ والتخاذل, فارتحلوا راجعين وتركوا الأحساءَ، وانهزم معهم أهلُ الأحساء الخائنون الذين نقضوا العهد، وتركوا محالَّهم وأمتعتَهم وأموالهم، وقيل: لَمَّا أراد الكيخيا ومن معه الارتحال جمعوا سلالِمَهم وزحَّافات الخشب والجذوع التي أعدوها لحفر الحفر والجدران، وشيئًا من خيامهم ومتعهم وطعامهم وأشعلوا فيه النيران. أما الذين امتنعوا على الكيخيا في قصر الهفوف فرئيسُهم إبراهيم بن عفيصان لم يقع عليهم حصارٌ، ولكن حاولوا مرارًا عديدة لفتحِه ولم يحصلوا على طائلٍ, وكان الأميرُ سعود قد سار بأهل نجدٍ من البادي والحاضر وقصد الأحساءَ، فلما عَلِمَ برجوع الكيخيا رحل من مكانِه, ونزل على ثاج الماء المعروف في ديار بني خالد، فجمع اللهُ بينه وبين الكيخيا على غير ميعادٍ، فنزل الكيخيا الشباك ماء قريب من ماء ثاج, فجرى بينهم محاولة خيل وطراد، وأقاموا على ذلك أيامًا، ثم ألقيَ في قَلبِ الكيخيا وجنودِه الرعبُ ووقع فيهم الفشَلُ وطلبوا الصلح، وأنَّ كُلًّا من الفريقين يرحل على عافية وحقن دماء. وصالحهم سعود على ذلك وارتحلوا إلى أوطانِهم، ثم رحل سعودٌ ونزل الأحساء ورتَّب حصونَه وثغوره، وأقام فيه قريبًا من الشهرين، واستعمل فيه أميرًا سليمان بن محمد بن ماجد الناصر، ثم رحل سعود إلى وطنِه قافلًا."},{"id":4277,"title":"ركب من أهل نجد يحجون ويعودون سالمين .","date":["العام الهجري :1213","الشهر القمري : ذي الحجة","العام الميلادي :1799"],"text":"حجَّ ركبٌ من أهل نجدٍ في هذا العام، فيهم عليٌّ ابنُ الشيخ محمد بن عبد الوهاب وأخوه إبراهيم، وإبراهيمُ بن سدحان رئيس بلد شقراء، ورفقة معهم من أهل الوشم وأهل القصيم، وقَضَوا حجَّهم ورجعوا سالمين، وذلك أنَّ الشريف بعد وقعة الخرمة (من محافظات منطقة مكة المكرمة) سنة 1212 أرسل إلى الإمام عبد العزيز وطلب الصلحَ والمهادنة، فأجابه إلى ذلك وأذِنَ لأهل نجد بالحَجِّ بعد أن كانوا ممنوعين منه منذ عقودٍ."},{"id":4278,"title":"انتصار نابليون على الأتراك في أبي قير .","date":["العام الهجري :1214","العام الميلادي :1799"],"text":"بعد عودةِ القوات الفرنسية من الشامِ إلى مصر انتصَرَ بونابرت في معركة أبو قير البريَّة على قوَّة عثمانية اتخَذَت طريقَها في رودس إلى مصر، وكان من أهمِّ نتائج هذه الموقعة حصولُ بونابرت من القائِدِ العثماني مصطفى باشا الذي وقع في الأسرِ على معلوماتٍ تفيد بأن حربًا عامَّةً في أوروبا قد اندلعت ضِدَّ فرنسا."},{"id":4279,"title":"اتفاق العريش لإجلاء الفرنسيين عن مصر .","date":["العام الهجري :1214","العام الميلادي :1799"],"text":"بعد رحيلِ نابليون بونابرت إلى فرنسا أقبلَ كليبر على تصريفِ الأمورِ بكُلِّ همَّةٍ، فأعَدَّ تنظيمَ الحكومةِ وقَسَّم القُطرَ المصريَّ إلى ثمانية أقاليم إدارية، وبادر بالكتابةِ إلى الصدر الأعظم ينفي رغبةَ فرنسا في انتزاعِ مِصرَ مِن تركيا، ويذكُرُ الأسبابَ التي جعلت فرنسا تُرسِلُ حَملتَها إلى مصرَ، وهي محاولةُ إلقاء الرُّعبِ في قلوبِ الإنجليز، وتهديدُ ممتلكاتهم في الهندِ، وإرغامُهم على قَبولِ الصلح مع فرنسا، بالإضافةِ إلى الانتقامِ ممَّا لحِقَ بالفرنسيين من أذًى على أيدي المماليك، وتخليصِ مِصرَ مِن سيطرة البكوات وإرجاعِها إلى تركيا، ثمَّ طلبَ كليبر من الصدر الأعظم فتحَ باب المفاوضات من أجلِ جلاء الفرنسيين عن مصر، وقد جرت هذه المفاوضاتُ بالفعل في مدينة العريش، وأسفَرَت عمَّا يسمَّى باتفاقية العريش (24 يناير 1800م) التي نصَّت على: جلاء الفرنسيين عن مصر بكامِلِ أسلحتِهم وعَتادِهم، وعودتهم إلى فرنسا. هدنةٌ ثلاثةَ شهور قد تطولُ مدتها إذا لزم الأمر، ويتم خلالَها نقلُ الحملة. الحصولُ من الباب العالي أو حلفائه- أي الإنجليز وروسيا- على بلادِه على أن تتعهَّدَ تركيا وحلفاؤُها بعدم التعرُّضِ لهذا الجيش بأيِّ أذًى. غيرَ أن الحكومة البريطانية عندما بلغَتْها أنباءُ مفاوضات العريش كانت قد اتخَذَت موقفًا من شأنِه تعطيلُ اتفاقية العريش عن إبرامِها؛ إذ كانت تخشى من أن يعودَ جيشُ فرنسا المحاصَر في مصر إلى ميادين القتالِ في أوروبا، فترجَحَ كِفَّةُ الجيوش الفرنسية ويختَلَّ ميزان الموقِفِ العسكري في القارة. ولَمَّا كان من المعتقد في ضوء رسائِلِ الضباط والجنود الفرنسيين إلى ذويهم في فرنسا- والتي وقعت في أيدي رجالِ البحرية البريطانية- أنَّ الحملةَ الفرنسيَّةَ تمضي ببطء داخِلَ الأراضي المصرية؛ فقد فضَّلت حكومة لندن أن يبقى الفرنسيون في مصرَ أو يُسَلِّموا أنفُسَهم كأسرى حرب؛ ولذلك أصدرت في 15 ديسمبر 1799م أوامِرَ صريحة إلى اللورد سدني سميث القائِدِ العام للأسطول البريطاني في البحر المتوسط برَفضِ أي اتفاق أو معاهدة بشأن الجلاءِ عن مصر، طالما كان هذا الاتفاقُ لا ينصُّ على ضرورة أن يسلِّمَ الفرنسيون أنفسهم كأسرى حرب تسليمًا مُطلقًا دون قيدٍ أو شرط، فأعَدَّ سدني سميث رسالةً بهذا المعنى إلى كليبر وصَلَتْه في أوائل مارس 1800م."},{"id":4280,"title":"بريطانيا توقع اتفاقية تعاون مع إمام مسقط .","date":["العام الهجري :1214","العام الميلادي :1799"],"text":"لما قام نابليون بونابرت بغزو مصر استغَلَّت بريطانيا الظروفَ لوضع العراقيل أمامَ الفرنسيين للحِفاظِ على مركزها في الهندِ، وقد تولى ولزلي الحاكمُ البريطاني في الهند هذه المهمَّةَ؛ إذ بعث ميرزا مهدي علي خان المقيم البريطاني في بوشهر إلى مسقط لعقدِ معاهدة مع سلطان بن أحمد تهدف إلى إبعادِ مسقط عن الفرنسيين؛ حيث تعتبر مسقط مفتاحَ باب الخليج العربي، ولِمَنع بقاء العلاقات العمانية الفرنسية، ووُقِّعَت المعاهدة ولكنها لم تضع حدًّا لتردد مسقط في سياستها مع فرنسا؛ لذا عادت وأكَّدت المعاهدة بعد سنتين ونصَّت على إقامة مائة موظف إنجليزي نيابة عن الشركة في ميناء مسقط بشكلٍ دائمٍ، ويكون وكيلًا تجاريًّا عن طريقه جميعُ المعاملات بين الدولتين."},{"id":4281,"title":"نابليون يدعو يهود العالم لأجل القتال معه لإعادة القدس القديمة .","date":["العام الهجري :1214","الشهر القمري : ربيع الأول","العام الميلادي :1799"],"text":"رأى القائِدُ الفرنسي نابليون بونابرت أنَّ السيطرةَ على فلسطين ضرورةٌ حيوية لحمايةِ وتأمين مصالحِ الإمبراطورية الفرنسية، فهي من جِهةٍ تأخُذُ لفرنسا نصيبَها من تركة الخلافةِ العثمانية التي كانت تُحتَضَر آنذاك، ومن جهةٍ أخرى تمكِّنُه من الفوز في السباقِ مع منافِستِه بريطانيا، كما تحَقِّقُ له حلمَه الكبيرَ في السيطرة على مصرَ التي كان يعتبِرُها أهمَّ بلد في العالم. وكان نابليون أولَ زعيم أوروبي يعرِضُ على اليهود إقامةَ وطنٍ لهم في فلسطين إذا ما ساعَدوه في حملتِه على مصرَ وفلسطين، بحيثُ تقام لهم دولة يهودية تكونُ تابعةً للنفوذ الفرنسي. ولقد وَجَّه نابليون إلى اليهود-ليُوظِّفَهم في مشروعِه الاستعماري- رسالةً يستَحِثُّهم فيها على الانضمام إليه، ويَعدُهم فيها ويمَنِّيهم. وقد اتَّضح أنَّ هذا البيانَ الذي ادُّعيَ أنَّه صادِرٌ عن قيادة نابليون في القُدسِ لم يكن أكثَرَ مِن زَهوٍ حربي؛ لأن نابليون لم يقترب بفرقتِه قَطُّ من القدس، بل تقهقرت من فلسطينَ إلى مصر بحرًا بعد هزيمتِه في عكَّا، ولم يكن هناك أيُّ أمل في أن يفيَ بوعده الذي قطعَه في بيانه. لكن هذا لا يعني أنَّ البيان كان التفاتةً خالية من المعنى، فهو: \"يعَدُّ بمثابةِ اعتراف دولي بوجودٍ قوميٍّ لليهود، واعتقاد ببعث أمةٍ يهودية في فلسطين، فملايينُ اليهود المشتَّتين في أوروبا يجب أن يُجمَّعوا في نهاية المطاف في دولةٍ يهودية في فلسطين تخدمُ المصالحَ الاستعماريَّةَ الفرنسيَّةَ\"!"},{"id":4282,"title":"اشتعال ثورة القاهرة الثانية ضد الحملة الفرنسية .","date":["العام الهجري :1214","الشهر القمري : شوال","العام الميلادي :1800"],"text":"اشتعلت ثورةُ القاهرة الثانية ضِدَّ الحملة الفرنسية، وامتَدَّت إلى سائر أحياء العاصمة على مدى ثلاثة وثلاثين يومًا، واشترك في هذه الثورة كلٌّ من العثمانيين والأمراء المماليك مع أفراد الشعب المصري، وانتهت باتفاق كليبر قائد الحملة الفرنسية في ذاك الوقتِ ومراد بك أحد زعماء المماليك على الصلحِ فيما بينهما، على أن يكونا حُلفاءً لبعضهما ضِدَّ أي قوى أخرى، وهنا أمدَّ مراد بك الفرنسيين بالحطَبِ والسلاح وساعدهم على إخماد ثورة القاهرة التي جَرَت فيها دماء المصريين جريًا؛ حيث أُحْرِقت البيوتُ على من فيها وامتلأت الشوارعُ بالقتلى، وبعدها فرض كليبر الغراماتِ على أهالي القاهرة والتي بلغت 12 مليونَ فرنك فرنسي!"},{"id":4283,"title":"الأمير سعود بن عبد العزيز يحج حجته الأولى .","date":["العام الهجري :1214","الشهر القمري : ذي القعدة","العام الميلادي :1800"],"text":"حجَّ الأميرُ سعود بن عبد العزيز حجَّتَه الأولى، وكان معه غالِبُ أهل نجد والجنوب والأحساء والبوادي وغيرهم، وكانت حَجَّةً حافلةً بالشوكة وجميعِ الخيلِ والجَيشِ والأثقالِ، واعتمروا وقَضَوا حجَّهم على أحسَنِ الأحوالِ، ولم ينَلْهم مكروهٌ ورجَعوا سالِمين."},{"id":4284,"title":"هزيمة العثمانيين في معركة عين شمس (هليوبوليس) أمام الفرنسيين .","date":["العام الهجري :1215","العام الميلادي :1800"],"text":"أمام هذا التحول المفاجئ من تدخُّل الإنجليز في وجهِ اتفاق العريش لجلاء الفرنسيين من مصر، لم يجد كليبر مفرًّا من وقف عملية الجلاء التي كان قد بدأها تنفيذًا لاتفاقية العريش، ثم أسرع في صبيحةِ اليوم بالزَّحفِ على رأس جيشِه لوقفِ تقدُّم العثمانيين الذين وصلت طلائعُهم إلى المطرية على مسافةِ ساعتين من القاهرة، فوقعت معركةُ عين شمس (هليوبوليس) التي امتدَّ ميدانُها من المطرية حتى جهات الصالحية، وهزم الفرنسيون فيها العثمانيين هزيمةً شَديدةً."},{"id":4285,"title":"ثورة القاهرة الثالثة ضد الفرنسيين .","date":["العام الهجري :1215","العام الميلادي :1800"],"text":"أثناء معركة هليوبوليس كان فريقٌ مِن جيش الصدر الأعظم وبعضِ عناصر المماليك قد تسلَّلوا إلى داخِلِ القاهرة وأثاروا أهلَها على الفرنسيين، فكانت ثورةُ القاهرة الثالثة التي استمَرَّت مدة شهر تقريبًا، ولم يستطع كليبر إخماد الثورة إلَّا بعد التجائه إلى العنف، فدَكَّ القاهرة بالمدافع من كلِّ جانب، وشدَّد الضربَ على حي بولاق، حيث تركَّزت الثورة، فاندلعت ألسنة النيران في كل مكانٍ منه، والتهمت الحرائقُ عددًا كبيرًا من المحلَّات والخانات، فلم يجِدْ سكان بولاق مفرًّا من التسليم، وتلاهم سكان الأحياء الأخرى، وتولى مشايخُ الأزهر الوساطةَ وأخذوا من كليبر العفوَ الشامِلَ والأمان، ولكِنَّه ما لَبِث أن غدر بالمسلمين بعد أن خُمدت الثورة، وكان اقتصاصُه منهم رهيبًا شديدًا، فأعدم بعضَهم وفرضَ غرامات فادحةً على كثير من العلماء والأعيان، كما فرض المغارمَ على أهل القاهرة جميعًا، ولم يستثنِ منهم الطبقات الشعبية الكادحة، وعَهِد كليبر إلى المعلم \"يعقوب\" أن يفعل بالمسلمين ما يشاء، وممَّا يُذكَر أن بطريرك الأقباط لم يقرَّ يعقوب على تصرُّفاته، وكثيرًا ما بذل له النصحَ بالعدول عن خطته، ولكنَّ يعقوب كان يُغلِظُ له القول، وكان يدخل الكنيسة راكبًا جوادَه ورافعًا سلاحَه، ولم يزدَدْ إلا إمعانًا في تأييدِ الفرنسيين."},{"id":4286,"title":"بدء محاكمة سليمان الحلبي لقتله قائد الحملة الفرنسية في مصر .","date":["العام الهجري :1215","العام الميلادي :1800"],"text":"بعد قتل سليمانَ الحلبي للقائِدِ الفرنسي كليبر قائِدِ الحملة الفرنسية على مصرَ، تم القبض عليه وبدأت محاكمتُه، التي استمرت لمدة 3 أيام، نُفِّذ بعدها حكمُ القَتلِ في الحلبي بعد حَرقِ يده، ثم وضعه على الخازوق الذي اخترق مؤخِّرتَه، وبَقِيَ على هذه الحالة البشعة حتى توفِّي، ثم قُطِعت رأسه، وما زالت موجودةً في متحف الإنسان في باريس، مع الخنجرِ الذي قَتَل به كليبر!!!"},{"id":4287,"title":"إغلاق الفرنسيين الجامع الأزهر عقب اغتيال كليبر .","date":["العام الهجري :1215","العام الميلادي :1800"],"text":"تمَّ إغلاق الجامِعِ الأزهر أيَّامَ الحملة الفرنسية على مصر، وذلك عَقِب اغتيالِ القائد الفرنسي كليبر قائِدِ الحملة على مصرَ على يد الطالب الأزهري سليمان الحلبي، وظلَّ المسجد مغلقًا لأول مرة منذ إنشائه حتى خرجت الحملةُ من مصر."},{"id":4288,"title":"الإمام عبد العزيز يوجه الدعوة إلى الإمام المنصور صاحب اليمن .","date":["العام الهجري :1215","العام الميلادي :1800"],"text":"قال الإمام الشوكاني: \"وفي سنة 1215 وصل من صاحِبِ نجدٍ الإمامِ عبد العزيز مجلَّدان لطيفان، أرسل بهما إلى حضرة مولانا الإمام حَفِظه الله، أحدُهما يشتَمِلُ على رسائل لمحمد بن عبد الوهاب كلُّها في الإرشاد إلى إخلاص التوحيد والتنفير من الشرك الذي يفعله المعتَقِدون في القبور، وهي رسائلُ جيدة مشحونة بأدلَّة الكتاب والسنة، والمجلَّد الآخر يتضمَّنُ الردَّ على جماعةٍ مِن المقصِّرين من فقهاءِ صَنعاءَ وصَعدة ذاكروه في مسائِلَ متعلقة بأصولِ الدين وبجماعة من الصحابة، فأجاب عليهم جواباتٍ مُحَرَّرة مقَرَّرة محَقَّقة تدُلُّ على أنَّ المُجيبَ مِن العلماء المحقِّقين العارفين بالكتابِ والسنَّة، وقد هدَمَ عليهم جميعَ ما بَنَوه، وأبطل جميعَ ما دَوَّنوه؛ لأنهم مقصِّرون متعَصِّبون، فصار ما فعلوه خزيًا عليهم وعلى أهل صنعاء وصعدة، وهكذا من تصَدَّرَ ولم يعرف مقدارَ نَفسِه، وأرسل صاحبُ نجد مع الكتابين المذكورين بمكاتبةٍ منه إلى سيدي المولى الإمام، فدفع- حَفِظه الله جميعَ ذلك إليَّ- فأجبت عن كتابه الذي كتب إلى مولانا الإمام- حفظه الله- على لسانِه\"."},{"id":4289,"title":"الإمام عبد العزيز بن محمد يعزم على الحج .","date":["العام الهجري :1215","الشهر القمري : ذي القعدة","العام الميلادي :1801"],"text":"عزم الإمامُ عبد العزيز بن محمد بن سعود الحجَّ بالنَّاسِ الحَجَّةَ الثانية, وقد احتفلوا احتفالًا عظيما بالحَجَّة الأولى في السنة الماضية, وأجمل معه في الحجِّ غالب أهل نجد ومن تَبِعَهم من البوادي وغيرهم من النساء والأطفال، وخرج معه للحَجِّ ابنه الأمير سعود, ثمَّ إن الإمام عبد العزيز لما سار سبعة ووصل قرب الدوادمي المعروف في عالية نجد أيام، آنسَ من نفسه الملل والثِّقلَ فرجع للدرعية، وحَجَّ بالناس الأميرُ سعود واعتمروا وحجُّوا على أحسن حال، واجتمع سعود بالشَّريفِ غالب شريف مكة وبذل سعودٌ في مكة كثيرًا من الصدقات والعطاء، وكانت هذه حَجَّتَه الثانية."},{"id":4290,"title":"خروج الفرنسيين والإنجليز من مصر .","date":["العام الهجري :1216","العام الميلادي :1801"],"text":"بعد مقتَلِ كليبر آلت القيادةُ العامَّةُ للحملةِ إلى الجنرال مينو باعتبارِه أكبَرَ ضباط الحملة سنًّا، وكان هذا القائِدُ مِن أنصار البقاء في مصر وخُطَّة سياسته استهدفت توطينَ الفرنسيين فيها، إلا أنَّ الضغوطات الداخلية والخارجية اضطرَتْه إلى مغادرة مصرَ بعد الهجوم المشترك الذي قام به الإنجليز والعثمانيون على الفرنسيين في مصر. فتظافرت عدَّةُ عوامل أرغمت المحتَلِّين الفرنسيين على الخروجِ مِن مصر في النهاية، منها تحطيمُ أسطولهم في معركة أبي قير البحرية، وسيطرةُ الإنجليز البحرية في البحر المتوسط، وتشديدُهم الحصار على الشواطئ المصرية؛ مِمَّا أعجز الحكومة الفرنسية عن إرسال النجدات والإمدادات إلى فرنسا في مصر، وانضمام الدولة العثمانية إلى أعداءِ فرنسا، والانقسام الذي حدث في صفوفِ الحملة وبدأت بوادِرُه منذ بدأ جيش بونابرت زحْفَه الشاق من الإسكندرية إلى القاهرة، ثم استفحل أمرُه بعد رحيل بونابرت وخصوصًا عَقِبَ مصرع كليبر وإبَّان قيادة مينو للحملة، وجهاد الشعب المصري المُسلِم ضد الاحتلال الفرنسي الصليبي، ذلك الجهاد الذي تمثَّلَ في ثورات القاهرة الثلاث، وفي العمليَّات الجهادية التي اشتعلت في الدلتا، وفي المقاومةِ التي اشتَدَّت في الصعيد. ودون أدنى شَكٍّ كان لجهاد مسلمي مصرَ للحكم الفرنسي بالِغُ الأثر في زعزعةِ أركانه، وفي عجزِ الفرنسيين عن بلوغ غايتهم وتنفيذ أهدافهم وانهيار آمالهم في تشييد تلك المستعمرة الجميلة التي كانوا يحلمون باتخاذِها نواة لإمبراطوريتهم الاستعمارية الجديدة في مصر، وأمَّا الإنجليز الذين دخلوا إلى مصرَ بدعوى إخراج الفرنسيين فإنَّهم أيضًا خرجوا بموجِبِ معاهدة أميان التي كانت بين الفرنسيين والإنجليز في عام 1217هـ"},{"id":4291,"title":"والي مسقط يستولي على البحرين وآل خليفة يستنصر بالإمام عبد العزيز .","date":["العام الهجري :1216","الشهر القمري : محرم","العام الميلادي :1801"],"text":"سار سلطانُ بن أحمد صاحب مسقط البلد المعروف في عمان، في كثيرٍ من المراكب والسفن، ونازل أهل البحرين وأخذَه من يد آل خليفة, ثم آل خليفة ساروا إلى الإمام عبد العزيز في الدرعيَّة واستنصروه، فأمَدَّهم بجيش كثيفٍ تمكَّن من هزيمة سلطان أحمد وانتزاع البحرين منه وتسليمها لآل خليفة."},{"id":4292,"title":"إعادة افتتاح الأزهر بعد إغلاق أبوابه عقب مقتل كليبر .","date":["العام الهجري :1216","الشهر القمري : صفر","العام الميلادي :1801"],"text":"تمَّت إعادةُ افتتاح الجامع الأزهر بعد أن أُغلِقت أبوابُه عَقِبَ مَقتَلِ كليبر قائد الحملة الفرنسية في مصر، وقد ظل مُغلقًا زُهاءَ عام، حتى افتُتِح عند شروع الفرنسيين في الجلاء عن مصر."},{"id":4293,"title":"هجوم قوات الدرعية على كربلاء وهدمها القباب والأضرحة والمزارات الشيعية .","date":["العام الهجري :1216","الشهر القمري : ذي القعدة","العام الميلادي :1802"],"text":"بعد تصدِّي قبيلة الخزاعل الشيعية لبعضِ أتباع دولة الدرعية وقتلِها منهم حوالي 300 رجلٍ عام 1214هـ قُرْبَ النجف، احتَجَّ حكام الدرعية وطالبوا بديةِ القتلى، ولكِنْ لم يوافق الشيعة على ذلك، فتوجَّه الأمير سعود بجموعٍ كثيرة وقوَّة عظيمة إلى العراق، والتقى في كربلاء بجموعٍ كثيفة من الأعاجِمِ ورجال الشيعة الذين استماتوا في الدفاعِ عن معاقلهم الدينية، فانتصروا عليهم وأمَرَ الأمير سعود بهدمِ القباب والأضرحة والمزارات الشيعية، وهَدْم قبة قبر الحسين في كربلاء، وغَنِموا ما في القبة وما حولَها والنصيبة التي كانوا قد وضَعوها على القبر، وكانت مرصوفةً بالزمرد والياقوت والجواهر، وجميع ما وجَدوه من الأموال والسلاح واللِّباس والفُرُش والذهب والفضة وغيرها، ولم يلبثوا فيها إلَّا ضحوةً، وخرجوا منها قرب الظهر بجميعِ تلك الغنائم، فعَزَل سعود أخماسها وقسَّم باقيها للراجِلِ سهم وللفارس سهمان. ثم  ارتحل عائدًا إلى الدرعية."},{"id":4294,"title":"نابليون يفاوض الدولة العثمانية لتحسين العلاقات .","date":["العام الهجري :1217","العام الميلادي :1802"],"text":"بعد أن هرب نابليون إلى فرنسا عندما عَلِمَ بأنَّ هناك مشروعًا مُشتركًا بين العثمانيين وإنكلترا وروسيا، أخذ يراسِلُ الدولة العثمانية من فرنسا لتحسين العلاقات بينهما وإعادة التفاهمِ، وتم ذلك في عام 1216هـ على أساس إخلاء فرنسا لمصر وتأييد امتيازات فرنسا السابقة في الدولة العثمانية، كما اتَّفَقت فرنسا وإنكلترا بمصالحة أميان, خرجت إنكلترا بموجِبِها من مصر وأصبح لفرنسا حقُّ الملاحة في البحر الأسود أسوةً بروسيا، وأُقيمَ في اليونان جمهوريةٌ مُستقلة تحت حمايةِ الدولة العثمانية، وذلك بالاتِّفاقِ مع روسيا، وأُعيدَ لفرنسا ما صودِرَ لها من أملاك في الدولة العثمانية، وعادت لها امتيازاتُها."},{"id":4295,"title":"الشريف غالب  شريف مكة ينقض عهده مع الإمام عبد العزيز .","date":["العام الهجري :1217","العام الميلادي :1802"],"text":"في هذه السنةِ نقَضَ الشريفُ غالب شريفُ مكَّةَ الصلحَ مع الإمام عبد العزيز بن محمد بن سعود، ففارقه وزيرُه وزوج أخته عثمانُ بن عبد الرحمن المضايفي الذي خرجَ مِن مكة وترك الشريفَ غالبًا ونابَذَه، ووَفد المضايفي على الإمامِ عبد العزيز وبايعه على دينِ اللهِ ورَسولِه والسَّمعِ والطاعةِ، فعَيَّنه أميرًا على الطائف والحجازِ، وزَوَّده برسائِلَ إلى مشائخ القبائل يُعلِمُهم بهذا التعيين، ويطلُبُ منهم طاعتَه ومساعدته واعطاء الولاء لدولةِ الدرعيةِ، فكان لانشقاقِ المضايفي أثرٌ كبير في إضعافِ كِفَّة الأشراف, فبعدَ إعلانه الانشقاقَ ونزوله قرية العبيلا, انضمَّت إليه كثير من قبائل الحجاز وأعلنت خروجَها على الأشراف، فسار الشريفُ غالب بالعساكر والجموع ونازل المضايفي في العبيلا، ووقع قتالٌ، ولم يحصُل الشريفُ على طائِلٍ ورحَل عنه ودخَلَ الطَّائِفَ."},{"id":4296,"title":"انضمام القواسم في رأس الخيمة لدعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1217","العام الميلادي :1802"],"text":"وصلت دعوةُ الشيخ محمد بن عبد الوهاب سواحِلَ الخليج العربي بين عامي  1798-1805م؛ فقد انطلق مؤيِّدو دعوة الشيخ من البريمي نحو الخليج وعمان للداخل، وعبروا الجبالَ العمانية ووصلوا إلى مسقط، وانضَمَّت قبائل كثيرة لدعوتهم، ومنها القواسم وبنو علي، ولم ينقِذ الإمامَ العماني سلطانَ بن الإمام أحمد بن سعيد منهم سوى وفاةِ الإمام عبد العزيز في الدرعيَّة عام 1803 واضطرارهم للعودة إلى البريمي، وقد عقد القواسِمُ اتِّفاقًا مع الدرعية هذا العامَ للعَمَلِ على نشر دعوةِ الشيخ محمد بن عبد الوهاب إلى ما وراء البحار, وقد قَلَبت هذه الاتفاقية حياةَ القواسم رأسًا على عَقبٍ، فقد أحسُّوا بالقوة والدافِعِ الديني، وبالرغم من أنَّ السعوديين لم يكونوا قوةً بحريةً لِمعاونة القواسِمِ في البحر إلَّا أن قوَّتَهم البرية كانت ساحقةً وتستطيعُ حماية قواعد القواسِمِ في البر، وبذلك أَمِنوا الهجومَ من الخلفِ خاصَّةً من أئمَّةِ عُمان."},{"id":4297,"title":"وصول دعوة الإمام المجدد محمد بن عبد الوهاب اليمن .","date":["العام الهجري :1217","العام الميلادي :1802"],"text":"وصلت دعوةُ الإمام محمد بن عبد الوهاب اليمَنَ، ودخلَت بلادُ أبى عريش وأشرافُها في طاعةِ دولةِ الدرعية"},{"id":4298,"title":"عثمان المضايفي أميرا على الطائف من قبل الإمام عبد العزيز .","date":["العام الهجري :1217","العام الميلادي :1802"],"text":"لَمَّا فَشِل الشريف غالب في النَّيل من عثمان المضايفي في العبيلا، جمع المضايفي من يليه من الحاضرة والبادية، فسار إليه سالمُ بن شكبان بأهل بيشة وقراها, ومصلط بن قطنان بأهل رنية وقراها، ومن كان عنده من سبيع, وسار أيضًا حمد بن يحيى بأهل تربة ومعه البقوم, وسار هادي بين قرملة, ومعه جيش من قَحطان. وسار إليه غيرُ ذلك من عتيبة فاجتمعت تلك الجموعُ عند عثمان، فساروا إلى الطائِفِ وفيها الشريف غالب، وقد تحصَّن فيها وتأهب واستعَدَّ لحربهم، فنازلته تلك الجموعُ فيها فانهزم إلى مكَّة وترك الطائف، فدخله عثمان ومن معه من الجموعِ, وفتَحَها عَنوةً بغيرِ قتالٍ، وضَبَط البلدَ وسُلِّمت له جميع نواحيه وبواديه، وجمَعَ المضايفي الأخماسَ وبعَثَها إلى الإمام عبد العزيز، فقَرَّر ولايتَه على الطائف, واستعمله أميرًا عليها وعلى الحجاز."},{"id":4299,"title":"وفاة سليمان باشا الكبير والي بغداد وخلفه علي باشا زوج ابنته في ولاية بغداد  .","date":["العام الهجري :1217","الشهر القمري : ربيع الآخر","العام الميلادي :1802"],"text":"هو سليمان باشا أحد ولاة العراق, وكان من المماليك، وكان من عُتقاء محمد بك الدفتري الربيعي، واسمه سليمان آغا. ولِدَ في عام 1137هـ، وصار واليًا للبصرة، ثم نُقل واليًا على بغداد عام 1194هـ/1780م، وعُرِف بعد توليه ولاية بغداد باسم سليمان الكبير, وقد عُرِف عصرُه باسم العصر الذهبي لفترة حكم المماليك في العراق, في أواخر سنوات حكم سليمان باشا الكبير بدأت هجَمات أتباع دولة الدرعية، وكانوا يُغيرون على تخوم العراق, فكَلف بمحاربتِهم، فأرسل حملتين لمحاربةِ أتباع دولة الدرعية في الأحساء عام 1217هـ/ 1802م، وأرسل حملةً ثالثة ضِدَّهم في منطقةِ القصيم. توفِّيَ سليمان باشا الكبير في بغدادَ عن عمر ناهز الثمانين عامًا، حيث مَرِض واشتَدَّ مَرَضُه فاستدعى كبارَ المسؤولين وشاورهم في أمرِ ولاية بغداد مِن بَعدِه، ثمَّ عَهِدَ بولايتها إلى معاوِنِه علي باشا وهو زوج ابنته، وأوصاهم بطاعتِه وامتثال أمرِه وبذَلَ لهم النصيحة، وتوفِّيَ ليلة السبت 8 ربيع الثاني، ودفن في مقبرة مشهد وشُيِّع بموكب رسمي، ودفِنَ يوم السبت قبل صلاة الظهرِ."},{"id":4300,"title":"تأسيس الدولة الكثيرية الثانية بحضرموت .","date":["العام الهجري :1218","العام الميلادي :1803"],"text":"جاءت مَرحلةُ الدولةِ الكَثيريةِ الثانيةِ، على يدِ السُّلطانِ جَعفرِ بنِ علِيِّ بنِ عُمَرَ بنِ جَعفرٍ الكَثيريِّ، الذي جاء مِن هِجرتِه الطويلةِ بجاوةَ والهِندِ سنةَ 1218م، ثم أقام أوَّلًا بهنن، وشَرَع يُكاتِبُ الشنافِرَ وفَهدًا وأعيانَ السادةِ العَلويةِ، ويَبثُّ الدُّعاةَ لِإحياءِ دولةِ آلِ كَثيرٍ، وقامَ بشراءِ عَبيدٍ وجَنَّدَهم لِلقتالِ، ثم قَويَ أمرُه واستَولى على مَناطقَ مِن حَضرَمَوتَ، وأرسَلَ جُيوشَه غَربًا وشَرقًا، وفي عَهدِه وضَعَ حَدًّا لِلفَوضى والأزَماتِ الطائفيةِ والنِّزاعاتِ التي نَشأت في عَهدِ الدولةِ الكَثيريةِ الأُولى، واتَّسَم عهدُ الدولةِ الكَثيريةِ الثانيةِ بالاستِقرارِ السياسيِّ، ثم بدأت تَضعُفُ الدولةُ عندَما تأسَّست جارَتُها السَّلطنةُ القُعَيْطيَّةُ، حتى انتهت باغتيالِ السُّلطانِ مَنصورِ بنِ عُمَرَ بنِ جَعفرِ بنِ عيسى بنِ بَدرٍ الكَثيريِّ، على يَدِ الجمعدارِ عَوضِ بنِ محمدٍ القُعَيْطيِّ عامَ 1274هـ، واستَولى القُعَيْطيُّونَ على شِبامَ. ثم جاءت مَرحلةُ الدولةِ الكَثيريةِ الثالثةِ، باستيلاءِ السُّلطانِ غالِبِ بنِ مُحسِنٍ الكَثيريِّ على الحُكمِ، لكنه دخَلَ في مُنافسةٍ وصِراعٍ مع السَّلطنةِ القُعَيْطيَّةِ التي بدأت تَتكوَّنُ في ذلك الوقتِ نَفْسِه. إلا أنَّ السَّلطنةَ القُعَيْطيَّةَ كانت شديدةَ الاتِّساعِ، حيث انتزعَتْ أجزاءً كبيرةً مِن حَضرَموتَ كانت تَحتَ حُكمِ السَّلطنةِ الكَثيريةِ التي بدأت تَضعُفُ شَيئًا فشَيئًا."},{"id":4301,"title":"محمد علي يتولى حكم مصر .","date":["العام الهجري :1218","العام الميلادي :1803"],"text":"جاء محمدُ علي باشا إلى مصرَ مع الجنود الذين جاؤوا لإخراجِ الفرنسيين منها واستطاع بعد مناورات مع المماليك والولاة والعثمانيين والأهالي أن يتوصَّلَ إلى ولايةِ مصر في العاشرِ من شهر ربيع الثاني من عام 1220هـ حتى عندما حاول الإنجليز لدى الدولة العثمانية عزلَه أو نقلَه، تمسَّك به العلماء والقادة، فصدر أمرٌ بتثبيته عام 1221هـ، ثم استطاع أن يتفَرَّد بالحُكمِ بتخَلُّصِه من المماليك في حادثة القلعة عام 1226هـ وضَرْبِ العلماءِ بعضِهم ببعضٍ، فخلى له الجوُّ وتفَرَّد بالحُكمِ كما يحِبُّ ويشاء."},{"id":4302,"title":"استعادة الشريف غالب حكم مكة .","date":["العام الهجري :1218","العام الميلادي :1803"],"text":"رحل الشريف غالب بعسكَرِه مِن جُدة إلى مكة، ونازل أهل القصور الذين رتَّبَهم الإمام سعود بعد عودتِه من حصار جدة, فتمكَّنَ الشريف غالب من إخراجِهم بالأمان، واستولى على مكة."},{"id":4303,"title":"قوات الدرعية تدخل البحرين .","date":["العام الهجري :1218","العام الميلادي :1803"],"text":"بدأ الصدام بين آل خليفة ودولة الدرعية عام 1210هـ وعندما اشتَدَّ حصار قوات الدرعية على الزبارة ارتحل عنها أهلها جميعًا وانتقلوا إلى جزيرة أورال، حيث أقاموا في قرية الجو الواقعة على أحد المرتفعات جنوبي الجزيرة التي بدأت تُعرَف بالبحرين، ثم تعرَّضوا لهجوم سلطان مسقط الذي استطاع أخذ رهائن من البحرين، فاستعان آل خليفة بالإمام عبد العزيز عام 1218هـ حيث تمكَّنوا بمساعدتهم من استرجاع الرهائنِ واستعادة الجزيرة التي أصبحت تحت حُكم عمان، ومن وقتها توطَّدت العلاقة بينهما وخاصَّةً عندما عاد سليمان بن خليفة إلى حُكمِه بمساعدة الإمام سعود بن عبد العزيز عام 1224هـ."},{"id":4304,"title":"احتلال الإنجليز كابل .","date":["العام الهجري :1218","العام الميلادي :1803"],"text":"استطاع شُجاع الملك في هذا العام أن يستوليَ على كابل ويخلعَ أخاه محمودًا ويسجنَه وأن يُعلِنَ عن نفسِه مَلِكًا في بيشاور، ولكِنْ لم يلبَثْ أن استطاع أخوه فتح خان أن يهزِمَه ففَرَّ شجاع إلى بلادِ الهند عام 1224هـ أمَّا أخوهم دوست محمد فبدأ يقوَى نفوذُه حتى استولى على كابل، ولَقَّبَ نفسَه أميرَ كابل، فاستنجد شجاعٌ بالإنكليز الذين وطَّدوا نفوذَهم بالهند فأرسلوا جيشًا دخل كابل ونصَبوا شجاعَ الملك حاكِمًا عليها."},{"id":4305,"title":"غزو الإمام سعود البصرة .","date":["العام الهجري :1218","العام الميلادي :1803"],"text":"سار الإمامُ سعود من الدرعية بعد أن استلحق جميعَ رعاياه من البادي والحاضر، فنهض بجيوشه وقصدَ ناحية الشمال حتى نزل على قريةِ التنومة القريبة من القصيم فعيَّد فيها ونحَرَ ضحاياه بها، ثم أرخص عُربان الشمال من الظفيري وأذِنَ لهم بالعودة إلى أوطانِهم؛ لأنَّه يريد القفول إلى وطنه، وكان قصده أن يُبغِت أهل البصرة إذا بلَغَهم رجوعُه، ثم رحل من التنومة إلى جهة الدرعية، ثم رجع عاديًا إلى البصرة فوافق كتيبةَ خيل للمنتفق رئيسهم منصور بن ثامر، فأغار عليهم وأسر رئيسَهم منصورًا, ثم داهم البصرةَ من الجنوب وهدم جميعَ القباب والمشاهد التي خارج سور البلد, ثم أمر سعود أن يحتَشِدَ جنده على قصر الدريهمية لهدمِه، فهدموه واستمَرَّ في حصار البصرة اثني عشر يومًا ثم رحل قافلًا إلى وطنه."},{"id":4306,"title":"دخول الأمير سعود مكة بدون قتال .","date":["العام الهجري :1218","الشهر القمري : محرم","العام الميلادي :1803"],"text":"في الوقتِ الذي كانت الحربُ دائرةً بين الشريف غالب وعثمان المضايفي في الطائفِ، كان الأميرُ سعود بن عبد العزيز يجمَعُ البواديَ والحاضرة في السبلة الموقع القريب من بلدة الزلفي، فلما اجتمعوا إليه رحَلَ بهم إلى الحجاز ونزل العقيقَ المعروف عند المعان، وكان ذلك وقتَ الحَجِّ, وكانت الحُجَّاج الشاميَّة والمصريَّة والمغربية وغيرُهم في مكة، وهم في قوَّةٍ هائلةٍ وعُدَّة عظيمة، فهَمُّوا بالخروج إلى سعود والمسير إلى قتاله، ثم تخاذَلوا وفسَد أمرُهم وانصرفوا إلى أوطانِهم، فألقى الله الرعبَ في قلب الشريفِ غالب وهو في مكَّة فلم يستقِرَّ فيها، فانهزم إلى جُدَّةَ هو وأتباعُه من العساكِرِ، وحمل خزائِنَه وذخائِرَه وبعضَ متاعِه وشوكتِه, وترك أخاه عبد المعين في مكَّةَ يدبِّرُ شؤونها فكتب عبد المعين إلى الأمير سعود يَعرِضُ عليه السَّمعَ والطاعة وعلى أن يستبقيَه في إمارةِ مكَّةَ، وأرسل الكتابَ مع بعض علماء مكة, فلما اجتمع هؤلاء العلماءُ بالأمير سعود في السَّيلِ وعرضوا عليه الكتاب قَبِلَ ما فيه وأعطاهم كتابًا بالأمان وموافقتِه على بقاءِ ولاية الشريف عبد المعين على مكَّةَ, ثم إنَّ سعودًا وجموعه أحرموا بالعُمرة، ودخلوا مكَّةَ واستولَوا عليها بدون قتال، وأعطى أهلَها الأمانَ وبذَلَ لهم من الصَّدَقاتِ والعطاء الشيءَ الكثير, فلما قضى سعودٌ العمرة فرَّق أهلَ النَّواحي يهدِمونَ القبابِ التي بُنِيت على القُبورِ والمشاهِدِ الشِّركيةِ بأنفُسِهم ففعلوا، وكان في مكَّةَ من هذا النوع شيءٌ كثيرٌ في أسفَلِها وأعلاها ووسَطَها وبيوتها، فأقام فيهم أكثَرَ من عشرينَ يومًا وأهل مكَّةَ يهدمونَها، حتى لم يبقَ مِن تلك المشاهِدِ والقِبابِ إلا أعدموها وجعلوها ترابًا!  كانت العادة أن يصلِّيَ في المسجِدِ الحرامِ بالجماعةِ الحاضرةِ أحدُ الأئمَّةِ من المذاهب الأربعةِ، ثم يتلوه غيرُه، فأمر الأميرُ سعود بإبطال تلك العادةِ وألَّا يصلِّي في المسجِدِ الحرام إلَّا إمامٌ واحدٌ، فيصلي الصُّبحَ الشافعيُّ، والظُّهرَ المالكيُّ، وهكذا بقية الأوقات، ويصلِّي الجمعةَ مفتي مكَّةَ عبد الملك القلعي الحنفي, وأمر بتدريس كشفِ الشبُهاتِ في المسجد الحرام في حَلقةٍ يحضُرُها العلماء والأهالي ففعلوا, وكان الشريفُ في هذه المدةِ يراسل سعودًا، وطلبَ الصُّلحَ وبَذَل المالَ، وهو يريد أن يحصِّنَ جُدَّة."},{"id":4307,"title":"محاولة الأمير سعود فتح جدة .","date":["العام الهجري :1218","الشهر القمري : صفر","العام الميلادي :1803"],"text":"بعد أن استقَرَّت الأوضاع في مكَّةَ، ارتحل الأمير سعود إلى جُدَّة لفتحِها، فعسكر بجيشِه في الرغامة بالقربِ من سور جدة، فكتب إلى أهلها يدعوهم إلى التَّسليم, وكان الشريف غالب قد تحصَّن وراء سور جدة واستعد للقتالِ، فدامت المناوشات بينهما أسبوعًا، فلما رأى سعود حصانةَ جُدَّة رحل منها ورتب جندًا في قصرٍ مِن قصور مكَّةَ، ثمَّ رجع إلى الدرعية."},{"id":4308,"title":"هجوم سفينتي حرب أمريكيتين على السفن في ميناء طرابلس في ليبيا .","date":["العام الهجري :1218","الشهر القمري : جمادى الآخرة","العام الميلادي :1803"],"text":"على الرغم من معاهدة 1210ه بين الجزائر والولايات المتحدة، فإن السفنَ العثمانية التابعة لإيالة (ولاية) طرابلس بدأت في التعَرُّضِ للسفن الأمريكية التي تدخُلُ البحر المتوسط، وترتَّب على ذلك أن أرسَلَت الولايات المتحدة أسطولًا حربيًّا إلى ميناء طرابلس، هاجمت سفينتا حرب أمريكيتان تملك 35 مدفعًا السفُنَ الموجودةَ في ميناء طرابلس في ليبيا، إلَّا أن إحدى السفينتين (فلادليفيا) التي كانت تعدُّ أكبر سفينة في العالم في ذلك الوقتِ جنحت في المياه الضَّحلةِ في ميناء طرابلس، وتم أسرُ طاقَمِها المكون من 300 بحَّار، وطالب حاكِمُ طرابلس قرة مانلي يوسف باشا الولاياتِ المتحدة بدفع ثلاثة ملايين دولار تقَدَّم لهم كتعويضاتٍ قبلَ إطلاق سراح السفينة وطاقمِها، وطالب في نفس الوقت محمد حمودة باشا والي تونس الولاياتِ المتحدة بعشرة آلاف دولار سنويًّا. وظلت الولايات المتحدة تدفَعُ هذه الضريبة حمايةً لسفنها حتى سنة 1227هـ حيث سدَّد القنصل الأمريكي في الجزائر 62 ألف دولار ذهبًا، وكانت هذه هي المرة الأخيرة التي تسَدَّد فيها الضريبة السنوية."},{"id":4309,"title":"وفاة الإمام عبد العزيز بن محمد بن سعود حاكم دولة الدرعية .","date":["العام الهجري :1218","الشهر القمري : رجب","العام الميلادي :1803"],"text":"هو الإمامُ عبد العزيز بن محمد بن سعود بن محمد بن مقرن، ولِدَ 1132هـ/1720م ونشأ في الدرعيَّة، ونهل من علومِها الشرعية، ودرس على عُلَماء عصره، وأبرزهم الشيخُ محمد بن عبد الوهاب في العُيَينة، وبعد قدومه الدرعية عام 1157هـ شارك في كثير من المعارك والحروبِ في حياة أبيه, وبعد وفاةِ والده تولَّى الحكمَ سنة 1179هـ, وأكمل بناءَ الدولة ونشر الدعوةَ الإصلاحية التي بدأ بها والده الإمام محمد بمؤازرة الإمامِ محمد بن عبد الوهابِ وتوجيهِه، يقول ابن بشر: \"وما يجيءُ إلى الدرعية من دقيقِ الأشياء وجليلِها تُدفَعُ إليه- أي إلى الشيخ محمد بن عبد الوهاب- بيده ويضعُها حيث يشاء. ولا يأخذ عبد العزيز ولا غيرُه من ذلك شيئًا إلا عن أمرِه، بيَدِه الحَلُّ والعقدُ، والأخذ والإعطاء، والتقديم والتأخير، ولا يركب جيشٌ ولا يصدُرُ رأيٌ مِن محمد وابنِه عبد العزيز إلَّا عن قوله ورأيه. فلما فتح اللهُ الرياض واتسَعَت ناحية الإسلام وأمِنَت السبُلُ وانقاد كل صعبٍ من بادٍ وحاضر، جعل الشيخ الأمرَ بيد عبد العزيز وفوَّض أمور المسلمين وبيتَ المال إليه. وانسلخ منها ولَزِم العبادةَ وتعليم العِلمِ، ولكن ما يقطَعُ عبد العزيز أمرًا دونه ولا ينفِّذُه إلا بإذنه\" وفي عهدِه امتَدَّ نفوذ الدولة إلى الرياض وجميع بلدان الخرج، ووادي الدواسر في الجنوب، وفي الشمال امتد إلى القصيم ودومة الجندل بالجوف، ووادي سرحان وتيماء وخيبر والعراق, وفي الشرق تمكَّن الإمام عبد العزيز من السيطرةِ على الأحساءِ وإنهاء حكم بني خالد فيها, والبريمي التي كانت خاضعة لحكم قطر لسنوات طويلة، وامتد نفوذُ الدولة وانتشرت الدعوةُ إلى البحرين وعمان عن  طريق ولاءِ قبائل المنطقة ودفْعِها الزكاةَ لدولة الدرعية, وفي الغربِ امتَدَّ نفوذ الدولة إلى شرقي الحجاز, في الجنوب الغربي وصل نفوذ الدولة إلى بيشة والليث وجازان, وقد تحقَّق فيها الأمن والإيمان حتى أَمِنت البلدان والسبل. يقول ابن بشر: \"كانت الأقطارُ والرعية في زمنه مطمئنةً في عيشةٍ هنيئة، وهو حقيق بأن يلقَّب مهديَّ زمانه؛ لأن الشخص الواحد يسافر بالأموال العظيمة أيَّ وقت شاء شتاء أو صيفًا، يمنًا أو شامًا، شرقًا وغربًا، في نجد والحجاز واليمن وتهامة وغير ذلك، لا يخشى أحدًا إلا الله فلا يخشى سارقًا ولا مكابرًا. وكانت جميعُ بلدان نجد من العارض والخرج والقصيم والوشم والجنوب وغير ذلك من النواحي في أيام الربيع يسَيِّبون جميع مواشيهم في البراري والمفالي من الإبل والخيل الجياد والبقر والأغنام وغير ذلك، ليس لها راعٍ ولا مراعٍ، بل إذا عَطِشت وردت على البلدانِ ثمَّ تصدُرُ إلى مفالها حتى ينقضيَ الربيع أو يحتاجون لها أهلها\". وكانت دولتُهم تُعرَف بدولةِ آل مقرن في الدرعية إلى نهايةِ عهد الإمام عبد العزيز، وفي عهد ابنه سعود الكبير، نُسِبَت الدولة إلى اسم العائلة فعُرِفَت بالدولة السعودية. اغتال الإمامَ عبد العزيز شيعةُ العراق انتقامًا  لِما أصابهم في غزوةِ كربلاء قبل عامين, يقول ابن بشر: \"قُتِل الإمامُ عبد العزيز بن محمد بن سعود في مسجدِ الطريف المعروف في الدرعية وهو ساجِدٌ في أثناء صلاة العصر؛ مضى عليه رجلٌ قيل إنَّه كردي من أهل العمادية بلد الأكراد المعروفةِ عند الموصل اسمُه عثمان، أقبل من موطنه لهذا القصدِ مُحتَسِبًا حتى وصل الدرعية في صورة درويش وادَّعى أنه مهاجر, وأظهر النسُكَ بالطاعة، وتعلمَ شيئًا من القرآن فأكرمه عبد العزيز وأعطاه وكساه... وكان قصدُه غيرَ ذلك، فوثب عليه في الصف الثالث والناسُ في السجودِ فطعنه في أبهرِه، رحمه الله، أو في خاصرته أسفلَ البطن بخنجرٍ كان قد أخفاه وأعده لذلك، وقد تأهب للموت فاضطرب المسجِدُ وماج بعضُه في بعض ولم يكن يدرون ما الأمر... وكان لَمَّا طُعن عبد العزيز أهوى إلى أخيه عبد الله وهو في جانبِه وبَرَك عليه ليطعنَه، فنهض عليه وتصارعا وجرح عبد الله جرحًا شديدًا، ثم إنَّ عبد الله صرعه وضربه بالسَّيفِ، وتكاثر عليه الناس فقتلوه، وقد تبين لهم وجه الأمرِ، ثمَّ حُمل الإمام إلى قصرِه وقد غاب ذهنُه وقرُبَ نزعُه لأنَّ الطعنة قد هوت إلى جوفِه، فلم يلبث أن توفِّيَ بعدما صعدوا به القصر رحمه الله تعالى وعفا عنه، واشتد الأمرُ بالمسلمين وبُهِتوا\" وذلك في أواخر شهر رجب لهذا العام, كان الأميرُ سعود حين قُتِل والده في نخل له في الدرعية، فلما بلغه الخبر أقبل مسرعًا، واجتمع الناس عنده فقام فيهم ووعظهم موعظةً بليغة وعزَّاهم, فقام الناسُ فبايعوه خاصتُهم وعامتهم، وعزَّوه في أبيه، ثم كتب إلى أهل النواحي نصيحةً يَعِظُهم ويخبرهم بالأمر ويعزِّيهم ويأمرُهم بالمبايعة، وكل أهل بلد وناحية يبايعون أميرَهم لسعود، فبايعه أهلُ النواحي والبلدان ورؤساء قبائل العربان، ولم يختلف منهم اثنان."},{"id":4310,"title":"عزل ابن ماجد عن حكم الأحساء وتعيين ابن عفيصان .","date":["العام الهجري :1219","العام الميلادي :1804"],"text":"عزل الإمامُ سعودٌ سُليمانَ بن محمد بن ماجد عن إمارةِ الأحساء واستعمل إبراهيم بن سليمان بن عفيصان أميرًا عليها."},{"id":4311,"title":"وفاة سلطان بن أحمد بن سعيد إمام مسقط .","date":["العام الهجري :1219","العام الميلادي :1804"],"text":"هو سلطان بن أحمد بن سعيد البوسعيد إمامُ مسقط وهو مؤسِّسُ دولة البوسعيدية في عمان، ولد في عمان, وكان قد عَمِل على توحيد البلاد وتقويتها، ثم الاهتمام بالخارج لتوسيعِ نفوذ دولته، وقد اصطدم بقوات دولة الدرعية في البحرين عندما غزاها وانتزعها من آلِ خليفة. قتله رجلٌ من القواسم أهل رأس الخيمة أتباع دعوةِ الشيخ محمد بن عبد الوهاب. كان سلطان أحمد ركب البحرَ وصادفه القواسم في عُرض البحر وقد نزل من مركبه المنيع المشهور إلى سفينة صغيرة، فاعترضهم وهو فيها فحَصَلت مناوشةُ رميٍ، فرماه أحدُهم ببندقية فقتَلَه وهم لا يعلمون أنَّه إمام مسقط حتى سَمِعوا خادمه يدعوه باسمِه بعد قتله, وتولَّى حكم مسقط بعده أخوه بدر بن أحمد."},{"id":4312,"title":"عبد الوهاب أبو نقطة يسير لقتال الشريف غالب شريف في جدة .","date":["العام الهجري :1219","العام الميلادي :1804"],"text":"سار عبد الوهاب بن عامر المعروف بكُنيتِه أبو نقطة أمير ألمع وعسير وتهامة قاصدًا جُدَّةَ محاربًا لها بأمر الإمام سعود الذي أمر على من في جهة عبد الوهاب من أهل الخبت والحجاز أن ينفروا معه إلى جدة, فسار عبد الوهاب بهم وهم ستة آلاف مقاتل, ونزل السعديةَ الماء المعروف قرب سيف البحر، فلما تحقق الشريف حالَهم أراد أن يباغِتَهم في مكانهم قبل أن يأتيَ إليه أبو نقطة بجيشِه، فجهَّز العساكر الكثيرة قيل إنها عشرة آلاف رجل، وسار من مكةَ بتلك العساكر والجنود، وقصد عبد الوهاب على مائِه، فمرَّ بطريقه برجال مرابطين من عسيرٍ وغيرهم، وهم أربعون رجلًا فقتلهم، ثم سار إلى عبد الوهاب فالتقى الجمعان، واقتتل الفريقان, فحمل عبد الوهاب وقومُه على الشريف وجنوده فولَّوا الأدبار، فتَبِعَهم أهل عسير من ساقتِهم يقتلون ويغنمون ويأخذون من سلاح المُدبِرين ولباسِهم وما معهم، وكثيرُها يُرمى به في الأرض، وترك الشريفُ ثِقلَه ومدافِعَه وزهبته وسلاحه، واستولى عبد الوهاب ومن معه عليها، وقيل: إن البنادق التي جمعت 2500 بندق، والقتلى أكثر من ستمائة قتيل، أكثرهم من الترك والأمداد التي عنده من الدولة العثمانية، وجمع عمالُ سعود خُمس الغنائم وقيَّضوها, ورجع الشريف غالب إلى مكة وعبد الوهاب إلى وطنه بعد هذا النصرِ والغنيمة."},{"id":4313,"title":"الإمام سعود يسير لتأديب الظفيري لإخلالهم بفرائض الدين .","date":["العام الهجري :1219","الشهر القمري : ذي القعدة","العام الميلادي :1805"],"text":"سار الإمامُ سعود بجيوشه الكثيرة من جميع نواحي نجد والجنوب وعمان والأحساء وغير ذلك من البادي والحاضر، قاصدًا الشمال, وكان قد حدَث من عربان الظفير حوادِثُ من تضييع بعض فرائض الدين وإيواء المُحدَثين وإضافتهم، وأتاهم غزوٌ من بوادي الشمال، فأغاروا على بوادي المسلمين واجتازوا بالظفير فأضافوهم، وذكروا للإمام سعود أن أناسًا منهم يغزون مع أعداء المسلمين على بواديهم، وكان قبل ذلك قد حدَث بين الظفير ومطير بعضُ القتال، فقُتِل من مطير رجلٌ من رؤسائهم الدوشان. وقُتِل من الظفير مصلط بن الشايوش بن عفنان. فأرسل إليهم سعودٌ وهو في الدرعية فأصلح بينهم وكف بعضَهم عن بعض وتوعَّدَ من اعتدى منهم على الآخر, فلما سار سعود في هذه الغزوة اجتاز بوادي الظفير وهم في الدهناء على جهة لينة الماء المعروف, فأمرهم أن ينفِروا معهم غزاة، فنفر منهم شرذمةٌ رئيسُهم الشايوش بن عفنان، فاستغل سعود غزوهم، فانتهر الشايوش وغَضِب عليه فقال: إنهم عَصَوني وهم يريدون المسير لقتال مطير، فحَرف سعود الجيوش إلى الظفيري وشَنَّ عليهم الغارات وأمر فيهم بالقَتلِ والنهب، ثم بعد ذلك أعتق غالِبَهم من القتل, وأخذ جميعَ أموالهم ولم ينجُ منهم إلا الشريد من أقاصيهم، وتفرقوا فمنهم من هرب إلى المنتفق، والبعض إلى جزيرة العراق، والبعض الآخر إلى نجد, ثم رحل سعود إلى الزلفي وقسَّم الغنائمَ، وكان عند ظفير إبل وأغنام كثيرة لأهل سدير فأمرهم سعود أن يتعرفوا أموالَهم، وكل من عرف ماله أتى بشاهدين أو شاهد ويمينه ويأخذونه."},{"id":4314,"title":"محاولة استيلاء الإنكليز على الدردنيل ووقوف العثمانيين ضدهم .","date":["العام الهجري :1220","العام الميلادي :1805"],"text":"تحسَّنت العلاقة الفرنسية العثمانية، فعزل السلطان أميري الأفلاق والبغدان من منصبيهما وكانا مؤيَّدَين من قبل روسيا، فثارت ثائرة روسيا وأرسلت جيوشَها لاحتلال الإقليمين دون إعلانِ حرب، وتضامنت إنكلترا مع روسيا وأرسلت قطعات بحرية إلى مضيق الدردنيل، وطلبت من الخليفة أن يقومَ حلف بين إنكلترا والدولة العثمانية، وأن تسلِّم الدولةُ الأسطول وقلاع مضيق الدردنيل إلى إنكلترا، وأن تتنازل عن إقليمي الأفلاق والبغدان لروسيا، وأن تعلن الحرب على فرنسا، فرفضت الدولةُ العثمانية ذلك، فاجتازت القطعات الحربية مضيقَ الدردنيل بسهولةٍ وساد الأهالي الخوفُ، ورأى الخليفةُ أن يقبل طلبات إنكلترا غيرَ أن مندوب فرنسا عرَضَ عليه مساعدة فرنسا واستقدمَ الأسطول الفرنسي مقابِلَ عدم التنازل لإنكلترا، فوافق الخليفة وبدأ بتحصين العاصمةِ ومضيق الدردنيل بدعم الفرنسيين له، واضطرت القطعات البحرية الإنجليزية للخروجِ مِن الدردنيل خوفًا من الحصار في بحر مرمرة."},{"id":4315,"title":"أهل المدينة يبايعون الإمام سعود بن عبد العزيز .","date":["العام الهجري :1220","العام الميلادي :1805"],"text":"قبل مبايعة الشريف غالب بايع أهلُ المدينة الإمام سعود على دين الله ورسوله والسمع والطاعة، وهُدِّمت جميعُ القباب التي على القبور والمشاهد, وذلك أنَّ آل مضيان ورؤساء حرب ومن تبِعَهم من عُربانهم كانوا قد أحبُّوا الدعوة وأتباعها، فوفدوا على الإمام عبد العزيز في عهدِه وبايعوه, وأرسل معهم عثمان بن عبد المحسن أبا حسين يعلِّمُهم فرائض الدين ويقرِّرُ لهم التوحيد، فاجتمعوا على حرب المدينة ونزلوا عواليَها ثم أمرهم الإمام عبد العزيز ببناء قصرٍ فيها فبَنَوه وأحكموه واستوطنوه، وتَبِعَهم أهل قبا ومن حولهم وضيَّقوا على أهل المدينة وقطَعوا عنهم السوابل وأقاموا على ذلك سنين، وأرسل إليهم سعود وهم في موضِعِهم ذلك الشيخ العالم قرناس بن عبد الرحمن صاحب بلد الرس في القصيم, فأقام عندهم قاضيًا ومعلِّمًا كل سنة يأتي إليهم في موضِعِهم ذلك، فلما طال الحصار على أهل المدينة وقعت مكاتبات هذا العام بينهم وبين الإمام سعود وبايعوه هذه السنة."},{"id":4316,"title":"رئيس الحديدة وبيت الفقيه باليمن يبايع الإمام سعود ويغزو زبيد .","date":["العام الهجري :1220","العام الميلادي :1805"],"text":"بايع صالح بن يحيى العلقي رئيسُ الحُدَيدة وبيتُ الفقيه الإمامَ سعودًا على دين الله والسمع والطاعة، وحَسُنت عقيدته, فسيَّرَ إمامُ صنعاء عسكرًا حاصروا بندر الحديدة وأخذوه وأسروا ابن صالح، وكان والده استعمله أميرًا على الحُدَيدة, فجمع صالح جنوده وقومه وقبائل عديدة حاضرة وبادية نحو 3000 مقاتل، فنازل أهل زبيد وأخذوه عنوة، وغنموا منه من الأموال والمتاع الشيءَ الكثير، ولم يمتنع عليه إلا القلعةُ الأمامية وما تحميه، ثم خرج صالحٌ عن زبيد وعَزَل الأخماس وبَعَث بها إلى الدرعية، وقسَّم الباقيَ على جيشِه."},{"id":4317,"title":"عبد الوهاب أبو نقطة يغزو نجران بأمر من الإمام سعود .","date":["العام الهجري :1220","العام الميلادي :1805"],"text":"أمر الإمامُ سعود عبد الوهاب أبا نقطة ورعاياه من عسير وألمع وفهاد بن شكبان ورعاياه من بيشة وعبيدة وأهل سنحان ووادعة وقراها وأهل وادي الدواسر ومن تبعهم أن يقصِدوا نجران لقتالِ أهله, فسار هؤلاء في جمع بلغت عدته حوالي 30 ألفًا، ونازلوا أهلَ بدر مدَّةً وجرى بينهم وقائع وقتلى بين الفريقين، أكثَرُ القتلى من قوم عبد الوهاب, وأمر عبد الوهاب من معه أن يبنوا قصرًا مقابِلَ قصر بدر يصير ثغرًا لهم، ويضَيِّق على أهل بدر ونجران، فتَمَّ بناؤه وحَصَّنوه وجعلوا فيه مرابِطة، ووضعوا لهم جميعَ ما يحتاجون إليه ثمَّ رجعوا إلى أوطانهم."},{"id":4318,"title":"الشريف غالب يطلب الصلح والمبايعة مع الإمام سعود .","date":["العام الهجري :1220","العام الميلادي :1805"],"text":"أمر الإمام سعود عبدَ الوهاب أبا نقطة وجميعَ رعاياه من تهامة وسالم بن شكبان ورعاياه من أهل بيشة ونواحيها وعثمان المضايفي بجميع أهل الحجاز بالمسير إلى مكة، فينزلون ويضيقون على أهلِها، وأمرهم بانتظار الحاج الشاميِّ وأن يمنعوه إذا كان محاربًا، فسارت تلك الجموع إلى مكة فاشتدَّ الأمر على الشريف غالب، وبلغ منه الجَهدُ، وطلب منهم الصلحَ ومواجهة الإمام سعود ومبايعته على دين الله ورسوله والسَّمعِ والطاعة فصالحوه وأمهلوه، ومشت السوابِلُ والقوافل إلى مكة، ودخلها عبد الوهاب والمضايفي ومن معهم وحجُّوا واعتمروا، واجتمع عبد الوهاب مع الشريف غالب وفاوضه الحديثَ وتهادَوا فأجاز الشريف غالب عبد الوهاب بجوائِزَ سَنية، وأعرضوا عن الحاجِّ الشامي, وانصرف عبد الوهاب ومن معه من الأمراء والأتباع إلى أوطانهم, وأرسل الشريف إلى الإمام سعود أهلَ نجايب وطلب إتمام الصلحِ والمبايعة فأجابه إليها، وأَمِنَت السبُلُ ومَشَت السابلةُ إلى مكة من جميع النواحي، ورخصت الأسعار في الحرمين وغيرِها."},{"id":4319,"title":"غلاء وقحط في بلدان الجزيرة العربية .","date":["العام الهجري :1220","العام الميلادي :1805"],"text":"اشتدَّ الغلاء والقحط على الناس في نجد وما يليها، وسقط كثير من أهل اليمن ومات أكثر إبلِهم وأغنامهم، وفي آخر هذا العام بلغ البُرُّ ثلاثة أصوع بريال, وبلغ التمر سبع وزنات بريال، وبِيعَ في ناحية الوشم والقصيم خمس وزنات بريال, وأمَّا في مكة فالأمر فيها أعظَمُ بسبب الحرب والحصار بعد نقض الشريف غالب الصلحَ مع الإمام سعود، فسُدَّت كُلُّ الطرق عن مكة من جهة اليمن والحجاز وتهامة ونجد؛ لأن أهل هذه البلدان كلُّهم رعايا لدولة الإمام سعود في الدرعية, وأمَّا في نجد فاشتدَّ الجوع فيها على الناس واستمَرَّ الغلاء والجوع في نجدٍ نحو ست سنوات. لكِنَّ الله جعل لهم في الأمن عوضًا عن الجوع والغلاء، فالرجل يسافر إلى أقصى البلاد من اليمن وعمان والشام والعراق وغيرها لا يخشى أحدًا إلا الله, وقد صارت الدرعية لهم رداءً كالبصرة والأحساء، فمن أتاها بنفسه وعياله وسَّعَ الله عليه دنياه."},{"id":4320,"title":"ثورة الزعيم الوطني عمر مكرم الشعبية ضد الوالي العثماني خورشيد باشا .","date":["العام الهجري :1220","الشهر القمري : صفر","العام الميلادي :1805"],"text":"قاد الزعيمُ الوطني عُمر مكرم ثورةً شعبية مسلَّحةً في مصر ضِدَّ الوالي العثماني خورشيد باشا؛ مِمَّا كان لها أكبر الأثر في تغيير حكمِ مصر حيث تمكَّنَت من إقصاء خورشيد عن الحكم، واختيار محمد علي واليًا على مصر."},{"id":4321,"title":"محمد علي مؤسس الأسرة العلوية بمصر، واعتراف الباب العالي به .","date":["العام الهجري :1220","الشهر القمري : ربيع الأول","العام الميلادي :1805"],"text":"ولد محمد علي في مدينة قَوَلة الساحلية في جنوب مقدونيا عام 1769م، وهو تركي عثماني لا يمتُّ للألبانيين ولا لصقالبة مقدونية ولا يونانها بسببٍ ولا نسب، لكنَّه حين قدم مصر جاء مع الفرقة الألبانية التي أرسلها السلطانُ العثماني إلى مصر؛ ممَّا أشكَلَ أمره على البعض، فحسِبَ أنَّ له أصلًا ألبانيًّا! وكان محمد علي قد اختاره المصريون ليكون واليًا على مصر، فبعد جلاء الفرنسيين عن مصرَ استطاع محمد علي أن يسيطرَ على الوضع، وأن يحوز رضا العلماء والتجَّار والأعيان، حتى نادَوا به واليًا على مصر، وبعثوا برسالة للسلطان العثماني يطالبونه بتعيين محمد علي واليًا علي مصر، فاستجاب لرغبتهم، فتمَّ إعلانه واليًا على مصر في 17 مايو 1805م, كما كان لثورة عمر مكرم الشعبية أثرٌ في إبعاد خورشيد باشا عن حكم مصر وتهيئتها لمحمد علي الذي استقرَّ على أريكة الحكم في مصر هذا العام، وظل يحكمُها نحو 43 سنة، فقضى على المماليك في مذبحة القلعة الشهيرة، وكانوا مراكِزَ القوى ومصدرَ القلاقل السياسية، ممَّا جعل البلد في فوضى. وقضى على الإنجليز في معركة رشيد، وأصبحت مصر تتسم بالاستقرار السياسي لأوَّلِ مرة تحت ظلالِ الخلافة العثمانية. وبدأ محمد علي بتكوين أولِ جيشٍ نظامي في مصر الحديثة. وكان بدايةً للعسكرية المصرية في العصر الحديثِ، تمكَّن محمد علي أن يبنيَ في مصر دولةً عصرية على النسَقِ الأوروبي، واستعان في مشروعاتِه الاقتصادية والعلمية بخُبراء أوروبيين، ومنهم بصفةٍ خاصة السان سيمونيون الفرنسيون، الذين أمضوا في مصر بضع سنوات في الثلاثينات من القرن التاسع عشر."},{"id":4322,"title":"الشريف غالب يخل في الالتزام بالصلح الإمام سعود .","date":["العام الهجري :1221","العام الميلادي :1806"],"text":"بعد أن حَقَّق الإمامُ سعود طلَبَ الشريف غالب في الصلحِ والمبايعة، وقع من الشريفِ ما يَريبُ منها: أنَّه أبقى في مكة عسكرًا من الترك والمغاربة وغيرهم من الحاجِّ، وذلك أنَّ باشا الحاج عبد الله العظم هو الذي رتَّبَهم بأمر من الدولة العثمانية, ومنها أنَّه حصن جُدَّة وأحاطها بالخندق ومنعَ الغرباء والسفار من جهةِ دولة الإمام سعود عن دخول جدَّة، واستوطنها الشريف أغلبَ أيامِه، وبقيت تلك العساكر عنده إلى وقتِ الحجِّ القابل, واختار الإمامُ الإعراضَ عنه إلى وقتِ الحَجِّ."},{"id":4323,"title":"صدور فرمان من الدولة العثمانية بتثبيت محمد علي في ولايته على مصر .","date":["العام الهجري :1221","الشهر القمري : شعبان","العام الميلادي :1806"],"text":"صدر فرمان من الدولة العثمانية بتثبيت محمَّد علي باشا حاكِمِ مِصرَ في ولايته على البلادِ، وذلك بعد أن أصرَّت الزعامةُ الشعبيةُ ومعها جموعُ المصريين على ذلك"},{"id":4324,"title":"احتلال الزعيم الصربي قرة يوركي مدينة بلجراد .","date":["العام الهجري :1221","الشهر القمري : شوال","العام الميلادي :1807"],"text":"قام الزعيمُ الصربي قرة يوركي باحتلالِ مدينة بلجراد، وقام فيها بذبحِ جميع المسلمين الموجودين في المدينة أثناء الثورةِ الصربية على الدولةِ العثمانية."},{"id":4325,"title":"الإمام سعود يحج الحجة الثالثة ومواجهته مع عبد الله باشا العظم .","date":["العام الهجري :1221","الشهر القمري : ذي الحجة","العام الميلادي :1807"],"text":"خرج الإمامُ سعود للحَجَّة الثالثة في ذي القعدةِ، وكان قد سيَّرَ قبل خروجِه للحج في نهاية رمضان عبد الوهاب أبا نقطة برعاياه من عسير وألمع وفهاد بن سالم بن شكبان بأهل بيشة ونواحيها، وعثمان المضايفي بأهل الطائف, وأهل اليمن وأهل تهامة والحجاز وحجيلان بن حمد بشوكة أهل القصيم, ومحمد بن عبد المحسن بأهل الجبل ومن تبعه من أهل شمر وشوكة أهل الوشم, وواعدهم الإمامُ سعود المدينةَ النبوية واجتمع معهم مسعود بن مضيان وأتباعه من حرب، فاجتمع الجميع ونزلوا قرب المدينة, وكان الإمامُ سعود لَمَّا خرج من الدرعية أرسل إلى الأمراء المذكورين بمنع الحاجِّ من جهة الشام واستنبول ونواحيهما, فلما أقبل على المدينة الحاجُّ الشامي ومن تبعه وأميره عبد الله باشا العظم، أرسل إليه الأمراء أنْ لا يقدم إليهم ويرجع إلى أوطانه, وذلك أنَّ الإمام سعود خاف من غالب شريف مكة أن يحدث عليه حوادث عند دخول حاجِّ الشام وأتباعهم مكة, فرجع عبد الله العظم ومن تبعه من المدينة إلى أوطانهم, وكادت أن تقع اصطداماتٌ بين الجنود السعوديين وجنود عبد الله باشا العظم الذي لم يكُنْ في موقف عسكري يسمَحُ له بمقابلة السعوديين، وعلى إثرِ ذلك عزل السلطانُ سليم الثالث عبدَ الله باشا العظم عن منصبِه بناءً على تقاعسه عن مواجهةِ القوات السعودية ورجوعِه بالحُجَّاج, ثم رحل الأمراء وأتباعُهم من المدينة إلى مكة، فاجتمعوا بالإمام سعود فاعتَمَروا وحجُّوا على أحسَنِ حال، وبذل سعود في مكَّةَ العطاء والصدقات، وركب إليه الشريف غالب وبايعه، وأخرج سعودٌ الأتراك, وكسا الكعبةَ."},{"id":4326,"title":"محمد علي باشا يضع نفسه تحت الحماية البريطانية  .","date":["العام الهجري :1222","العام الميلادي :1807"],"text":"في بداية حكم محمد علي لمصر دخل في مفاوضاتٍ مع الإنجليز استمرَّت أربعة أشهر أكَّدَ فيها جديَّتَه ورغبته المخلصة في الارتباطِ بهم، بل وطلب وضع نفسِه تحت حمايتهم، وهذا ما يؤكِّدُه تقرير القائد الإنجليزي فريزر قائد الحملة البريطانية على الإسكندرية، والذي تولى التفاوضَ مع محمد علي، الأمر الذي أدى- بعد اقتناعهم به- إلى تخلِّيهم عن أصدقائهم من المماليك. وقد تضمَّن التقرير الذي أعده فريزر ثم أرسلَه الى الجنرال مور في 16 أكتوبر من هذا العام أهمَّ جوانب هذه المفاوضات، وقد جاء فيه: \"أرجو أن تسمحوا لي بأن أبسُطَ لكم ليكون... موضِعَ نظركم فحوى محادثة جرت بين باشا مصر والميجر جنرال شريروك والكابتن فيلوز أثناء قيامهما بمهمتهما لدى سمُوِّه. ولديَّ ما يجعلني أعتقد أن هذه المحادثة، ومن اتصالات خاصة كثيرة أخرى كانت لي معه، بأنه جادٌّ وصادقٌ فيما يقترحه. لقد أبدى محمد علي باشا والي مصر رغبته في أن يضع نفسه تحت الحماية البريطانية، ووعدناه بإبلاغ مقترحاتِه إلى الرؤساء في قيادة القوات البريطانية؛ كي يقوم هؤلاء بإبلاغها إلى الحكومة الإنجليزية للنظر فيها. ويتعهد محمد علي من جانبه بمنع الفرنسيين والأتراك أو أي جيش تابع لدولة أخرى من الدخولِ إلى الإسكندرية من طريقِ البحر وبعد الاحتفاظ بالإسكندرية كصديقٍ وحليف لبريطانيا العظمى، ولكنَّه لا مناص له من الانتظار أن تعاونَه إنجلترا بقواتها البحرية إذا وقع هجوم عليه من جهة البحر؛ لأنَّه لا يملك سفنًا حربية. ويوافق محمد علي باشا في الوقت نفسِه على تزويد كلِّ السفن البريطانية التي تقِفُ على بُعد من الاسكندرية بما قد تحتاج إليه من ماء النيل عند إعطائِها إشارةً يصير الاتفاق عليها\""},{"id":4327,"title":"وفاة السلطان العثماني سليم الثالث وتولية مصطفى الرابع .","date":["العام الهجري :1222","العام الميلادي :1807"],"text":"هو السلطانُ العثماني سليم الثالث بن مصطفى الثالث بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد الأول بن بايزيد الأول بن مراد الأول بن أورخان بن عثمان بن أرطغرل، أحدُ خلفاء الدولة العثمانية. تولى السلطةَ بعد وفاة عمه عبد الحميد الأول سنة 1203هـ وكانت المعارك الحربية مستمرةً، فأعطى وقتَه وجهده للقتال، وكان من أصحابِ الهمة العالية والمصلحين في عصرِه, وكانت البلادُ بحاجة لإصلاحات في كافة المجالات، فعيَّن أحد الشبان هو كوشك حسين باشا قبودانا عاما، الذي استفاد من خبرته واطلاعه على التحديثات الأوربية في عددٍ من المجالات والتنظيمات خاصةً في المجال العسكري، فقام بعدد من الإصلاحات، إلَّا أن هذه التحديثات كان لها ردودُ فِعلٍ سلبية جدًّا من الانكشارية الذين ثاروا على السلطان وطالبوا بإلغاء جميعِ التحديثات خاصَّةً النظام العسكري الجديد، وقد حصل الانكشارية على تأييدِ بَعضِ العلماء الذين شاركوهم في الاعتراض على هذه التحديث؛ بحُجَّة أنها تقليد للغرب الكافر, فثار الجنودُ غيرُ النظاميين وأيدَتْهم الانكشارية، فقتلوا المؤيِّدين للنظامِ العسكري الجديد، واضطر السلطانُ أن يصدِرَ أمرًا بإلغاء النظام العسكري الجديد، ولكن لم يقبل الثائرون بهذا، بل قرَّروا عَزلَ السلطان، فنودي بعزله في 21 من ربيع الثاني، وولَّوا بعده ابن عمه مصطفى الرابع بن عبد الحميد الأول, وبَقِيَ سليم معزولًا مدة عام وشهر، ثم حدثت محاولة لاستعادة السلطان سليم لحكم البلاد، ولكِنَّ رجال مصطفى الرابع قتلوا السلطانَ سليم الثالث ظنًّا منهم أن ذلك قد يخمِدُ الثورة، إلا أنَّ الثائرين اشتعلوا غضبًا، وانتهى الأمر بقتل مصطفى الرابع وتولية محمود الثاني. أمضى سليم الثالث في الحكم تسعة عشر عامًا."},{"id":4328,"title":"البحرية البريطانية تدمر رأس الخيمة بالجزيرة العربية .","date":["العام الهجري :1222","العام الميلادي :1807"],"text":"شَهِدت سواحِلُ الخليج العربي عملياتِ مسحٍ بريطانيةً لِموانئ اللؤلؤ في جزر البحرين والتعرف على المنطقة، وازداد في الوقت نفسِه نشاطُ القواسم البحري- أتباع دعوة الشيخ المجدد محمد بن عبد الوهاب- في تتَبُّع السفن البريطانية في المحيط الهندي، حتى وصلوا  لمسافة لا تبعُدُ عن بومباي نفسها سوى ستين ميلًا، وكان من جراء  ذلك المخطط إرسالُ الحملة البريطانية التي أبحَرت من بومباي بقيادة الجنرال كير نحو رأس الخيمة، وهناك أبدى القواسم فرسانُ البحر الشجعانُ أروعَ صور البسالة والبطولة في الدفاع عن المنطقة، ولكِنَّ البريطانيين الذين استمَرُّوا في ضرب معاقل القواسم بالمدافع لمدى ستة أيام من سفنِهم، أدى إلى تدمير القواسم وحرق سفنِهم بالكامل، فكان هذا من تمام السيطرة البريطانية على الخليجِ العربي."},{"id":4329,"title":"وفاة علي كيخيا باشا بغداد .","date":["العام الهجري :1222","العام الميلادي :1807"],"text":"هو علي كيخيا باشا بغداد كان وزيرًا لسليمان باشا الكبير والي بغداد سيره سنة 1213 على رأس حملة لغزو الأحساء والقطيف، لكِنَّ حملته على الرغم من قوته الهائلة إلَّا أنها باءت بالفشلِ، ولَمَّا قُتل سليمان باشا الكبير تولى بعده علي كيخيا ولاية بغداد، ولَمَّا استقر في الملك ودان له غالبُ رعايا العراق من الحضر والبادي، وثب عليه خمسة من غلمانِه وهو في الصلاة فقتلوه, فقام كيخيا سليمان فقتَلَهم, ولم يتِمَّ لهم أمر واستقَرَّ كيخيا سليمان في ولاية بغداد حتى أتاه التقريرُ من استانبول."},{"id":4330,"title":"صدور أول تكليف لمحمد علي باشا من قبل السلطان العثماني .","date":["العام الهجري :1222","العام الميلادي :1807"],"text":"تمَّ تكليف محمد علي باشا من قِبَل السلطان العثماني مصطفى الرابع بمهمة القضاء على الدولة السعودية، وأرسل محمد علي باشا إلى السلطان يعتذِرُ عن هذه المهمة الصَّعبةِ بسَبَبِ الظروف الاقتصادية السيئة في مصر والناتجة عن انخفاض فيضان النيل واستيلاء المماليك على صعيدِ مِصرَ، والخشيةِ مِن أطماع الدول الأوروبية في مصرَ."},{"id":4331,"title":"غلاء وقحط في نجد .","date":["العام الهجري :1222","العام الميلادي :1807"],"text":"اشتَدَّ الغلاء والقحط في نجد وبلغ البُرُّ أربعةُ أصوع بريال والتمرُ إحدى عشرة وزنة بريال، وأمحلت الأرض وهلكت غالبُ مواشي الحضر، فلمَّا كان وقتُ انسلاخ رمضان في وسط الشتاء أنزل الله علي نجدٍ الغيث وأحيا البلادَ وكَثُرَ العشب وعَمَّ في الحضر والبادي إلَّا أن الغلاء على حاله واشتدادِه حتى حُصِد الزرعُ."},{"id":4332,"title":"الإنجليز يحاولون الاستيلاء على الإسكندرية بإرسال حملة القائد فريزر .","date":["العام الهجري :1222","الشهر القمري : محرم","العام الميلادي :1807"],"text":"كان لفشل الإنجليز في السيطرة على مضيق الدردنيل سنة 1220 أثرُه في جعل القائد الإنجليزي يعمل لمحوِ ما فشِلَ فيه، فأرسل حملةً بقيادة فريزر إلى الإسكندرية واحتلَّها في مطلع هذا العام، وأرسل فرقة إلى ثغر رشيد لكنها هُزِمَت وأعاد الكَرَّة بعد أشهر فكان مصيرُه كالمرة السابقة، وجاء محمد علي للدفاع عنها واضطرَّ الإنجليز للرحيل عن مصرَ بعد دخولهم بستة أشهر."},{"id":4333,"title":"ثورة قباقجي ضد إصلاحات سليم الثالث الداخلية .","date":["العام الهجري :1222","الشهر القمري : ربيع الأول","العام الميلادي :1807"],"text":"أقدم السلطان سليم الثالث على عَمَلِ إصلاحات داخلية من عام 1206, وأنشأ فرقةَ النظام الجديد الذي يُلغي دور الانكشارية الذين زاد شرُّهم في الفترة الأخيرة وتدَخُّلهم في كل شيء؛ مِمَّا أثار الجنود الانكشارية فقاموا بثورةٍ عُرِفت بثورة قباقجي وساندهم بعض الأعيان ضِدَّ النظام الجديد، وادَّعَوا أن الجيش  الجديد كافرٌ؛ لأنه يرتدي البنطلون لبس الأوربيين بدلًا من الشالوار اللباس التقليدي؛ مما اضطر السلطان إلى أن يلغي النظام العسكري الجديد، ولكن ذلك لم ينفع؛ فإن الثورة الانكشارية بَقِيت على حالها ولم يرضَوا إلا بخلع السلطان، وقامت نكاية بالسلطان بقتل بعض أنصار هذه القرارات الإصلاحية في ميدان آت، ومنهم الدفتردار وكتخدا الدولة، ثم عزلوا السلطانَ سليم الثالث ونصبوا مكانه ابن عمه مصطفى الرابع الذي بات ألعوبةً في يدهم، ومع أنه ألغى كلَّ الإصلاحات التي أمر بها السلطانُ سليم الثالث وألغى كل المؤسَّسات التابعة له، لكنه لم يلبث كثيرًا حتى خلع هو أيضًا."},{"id":4334,"title":"توقيع هدنة بين الروس والدولة العثمانية .","date":["العام الهجري :1222","الشهر القمري : جمادى الآخرة","العام الميلادي :1807"],"text":"وقَّعت روسيا هدنةً مع الدولة العثمانية بسَبَبِ حُروبها مع نابليون بونابرت، إلَّا أن الحرب بين روسيا والدولة العثمانية ما لَبِثَت أن تجدَّدت عام 1809م بعد عامين من توقيع الهدنة."},{"id":4335,"title":"توقيع معاهدة دمنهور بين محمد علي والي مصر والإنجليز .","date":["العام الهجري :1222","الشهر القمري : شعبان","العام الميلادي :1807"],"text":"تم توقيع معاهدة دمنهور بين محمد علي والي مصر والإنجليز، وقد تمَّ بمقتضاها جلاءُ حملة فريزر عن مصر بعد فشلِها الذريع في تحقيقِ أغراضها وإصابتِها بهزيمةٍ فادحةٍ على يد المصريين."},{"id":4336,"title":"الإمام سعود يحج الحجة الرابعة .","date":["العام الهجري :1222","الشهر القمري : ذي الحجة","العام الميلادي :1808"],"text":"حجَّ الإمام سعود الحجَّةَ الرابعة بجميعِ نواحي رعاياه، حَجَّ معه أكثر من 100 ألف, ودخل مكَّةَ بجميع تلك الجموع واعتَمَروا وحَجُّوا بأحسن حال, وزار الشريفُ غالب الإمامَ سعودًا مرارا وصار معه كالشقيقِ فيزورُه أحيانًا وحده ومعه رجل أو رجلين، وأحيانًا بخيله ورجالِه, وكثيرًا ما يدخل سعود الحرم ويطوف بالبيتِ ويجلس فوقَ زمزم ومعه خواصُّه، وبَثَّ في مكة الصدقات والعطاء لأهلها وضعفائها شيئًا كثيرًا، وكسا الكعبةَ كسوةً فاخرةً، وجعل إزارَها وكسوة بابها حريرًا مطرَّزًا بالذهب والفضة، وأقام فيها نحوًا من ثمانية عشر يومًا, ثم رحل منها وقصد المدينة وأقام فيها عدة أيام ورتب مرابِطةً في ثغورِها، وأخرج مَن في القلعة من أهلِها، وجعل فيها مرابِطةً مِن أهل نجدٍ."},{"id":4337,"title":"خلع السلطان العثماني مصطفى الرابع وتولية أخيه محمود الثاني .","date":["العام الهجري :1223","العام الميلادي :1808"],"text":"اختلف زعماء الحركة التي أطاحت بالخليفة سليم الثالث وطُولِبَ بإعادته إلَّا أنه كان قد قُتِل، ثم نودِيَ بعزل الخليفة مصطفى الرابع بن عبد الحميد فتمَّ ذلك وحُجز في المكان الذي كان قد حُجز فيه سليم الثالث، بعد أن أمضى أربعة عشر شهرًا في الحكم، ثم أُعدِم في هذا العامِ وأقيم بعده أخوه محمود الثاني."},{"id":4338,"title":"غلاء وقحط في نجد وغيرها .","date":["العام الهجري :1223","العام الميلادي :1808"],"text":"في هذه السَّنةِ كان الغلاءُ والقحطُ في نجدٍ على حالِه في الشدَّةِ، وانتهى سعرُ البُرِّ أربعة أصوع بريال، والتمر عشر وزنات بريال، وعَمَّ الغلاء جميعَ نواحي نجد واليمن والتهايم والحجاز والأحساء, ووقع مع ذلك مرضٌ ووباءٌ مات فيه خلقٌ كثير من نواحي نجد، ودخلت السنةُ التالية والأمرُ على حالِه من الغلاءِ والمرضِ، ومات فيها والسَّنةِ التي قبلها مئاتٌ من سوادِ النَّاسِ."},{"id":4339,"title":"قتال بين أنصار الدرعية في عمُان وابن الإمام رئيس سحار .","date":["العام الهجري :1223","العام الميلادي :1808"],"text":"بعث الإمامُ سعود سَريَّةً قليلة إلى عمان لتعَلِّمَ أهلها فرائض الدين والاطلاع على أحوالهم, فلما وصلوا هناك فغذا قيسُ بن أحمد المسمى ابن الإمام رئيس سحار وجميع باطنة عمان وابن أخيه سعيد بن سلطان رئيس مسقط ومعهم من الجنود نحو عشرة آلاف رجل سائرين على النواحي التي تليهم من رعية الإمام سعود، الذين كان يرأسُهم من جهة سعود سلطانُ بن صقر بن راشد صاحِبُ رأس الخيمة، فأرسل إلى من يليه من أهل عُمان، فاجتمع عنده نحو ثلاثة آلاف رجل, فالتقى الجمعان: جمعُ قيس وجمع سلطان عند خوير بين الباطنة ورأس الخيمة، واقتتلوا قتالًا شديدًا، فانهزم جمعُ قيس هزيمةً شنيعةً وقُتِلَ قيس وهلك من قومِه خَلقٌ كثير بين القتل والغرق في البحر, ثمَّ بعد هذه الوقعة أرسل ابن قيس إلى الإمام سعود وسلطان بن صقر، وطلبَ المبايعةَ على دين الله ورسوله والسمع والطاعة، وبايع على ذلك وبذل مالًا كثيرًا وشوكةً من الحرب, وصار جميعُ عمان تحت ولاية الإمام سعود"},{"id":4340,"title":"الإمام سعود يرفض مهادنة الدولة العثمانية .","date":["العام الهجري :1223","العام الميلادي :1808"],"text":"عندما وصل سعودٌ بجيوشِه إلى مشارف الشام وقراها واكتسح ما أمامه من القرى والعربان، وقبل ذلك غزا كربلاء وهدد العراق وهزم جميعَ الجيوش التي أرسلها ولاةُ الشام والعراق لمحاربته، حتى اضطرت الدولةُ العثمانية أن تطلُبَ من سعود المهادنةَ والمسابلة وتَبذُل له مقابِلَ ذلك كلَّ سنة ثلاثين ألف مثقال ذهبي، وأوفدت الدولة لهذ الغرض رجلًا يسمَّى عبد العزيز القديمي وأوفدت بعده رجلًا آخر يسمى عبد العزيز بيك، فرجع كما رجع الأول بعدم القبول وبرسالة طويلة من سعود، ومما ورد فيها: \"وأما المهادنة والمسابلة على غير الإسلامِ، فهذا أمر محال بحولِ الله وقوَّتِه، وأنت تفهم أن هذا أمرٌ طلبتموه منا مرَّةً بعد مرة، أرسلتم لنا عبد العزيز القديمي ثم أرسلتم لنا عبد العزيز بيك، وطلبتم منا المهادنة والمسابلة، وبذلتم الجزيةَ على أنفُسِكم كلَّ سنة ثلاثين ألف مثقالٍ ذهبًا، فلم نقبل ذلك منكم ولم نُجِبْكم بالمهادنة، فإن قبلتم الإسلامَ فخيرتها لكم وهو مطلبنا، وإن توليتم فنقول كما قال الله تعالى: {وَإِنْ تَوَلَّوْا فَإِنَّمَا هُمْ فِي شِقَاقٍ فَسَيَكْفِيكَهُمُ اللَّهُ وَهُوَ السَّمِيعُ الْعَلِيمُ} [البقرة: 137] فلما أصبحت الدولةُ العثمانيةُ عاجزةً عن مهادنة الإمام سعود بن عبد العزيز بن سعود فضلًا عن محاربته، طلب عندئذ السلطان العثماني من والي مصر محمد علي باشا القيامَ بمحاربة الإمام سعود وإخراجِه من الحجاز، فتردَّد محمد علي أولًا ثم أخيرًا لبَّى طلب السلطان وسيَّرَ ابنَه طوسون سنة 1226هـ ثم خرج هو بنفسِه إلى أن سقطت الدولة السعودية سنة 1233هـ على يد إبراهيم باشا، فإنَّا لله وإنَّا إليه راجعون."},{"id":4341,"title":"الإمام سعود يتجه إلى العراق وينازل أهل كربلاء .","date":["العام الهجري :1223","الشهر القمري : جمادى الأولى","العام الميلادي :1808"],"text":"سار الإمام سعود بجيوشه من جميع نواحي نجد والأحساء والجنوب وأهل وادي الدواسر وأهل بيشة ورنية والطائف والحجاز والتهايم. خرج من الدرعية وتوجَّه ناحية العراق ونازل أهلَ كربلاء فوجدهم محصِّنين بلدَهم بسور عظيم وجنودٍ جمعوها بعد غزوتِه السابقة لهم سنة 1216، فأمر سعود بوضع السلالمِ على السور ووقع رميٌ وقتال شديدٌ، فلما علم سعود بحصانة البلد وعِظَمِ سورِها رحل عنهم."},{"id":4342,"title":"ثورة فرق الإنكشارية العثمانية على السلطان محمود الثاني .","date":["العام الهجري :1223","الشهر القمري : رمضان","العام الميلادي :1808"],"text":"بعد تولِّي السلطان محمود الثاني مقاليدَ الحكم في البلاد رأى أن يبدأ بالإصلاحِ الحربي، فكلَّف الصدر الأعظم مصطفى البيرقدار بتنظيم الإنكشارية وإصلاحِ أحوالهم، وإجبارِهم على اتِّباع التنظيمات القديمة الموضوعة منذ عَهدِ السلطان سليمان القانوني، والتي كانت قد أُهمِلَت شيئًا فشيئًا، فقامت فِرَق الإنكشارية العثمانية بثورةٍ عنيفة ضدَّ السلطان."},{"id":4343,"title":"الإمام سعود بن عبد العزيز يحج الحجة الخامسة .","date":["العام الهجري :1223","الشهر القمري : ذي الحجة","العام الميلادي :1809"],"text":"حج الإمامُ سعود بن عبد العزيز الحَجَّة الخامِسةَ برعاياه من جميعِ النواحي ودخل مكَّةَ واعتمر وحَجَّ ونصل قصر الشمالي المعروف في البياضة وأقام فيه, والشريف غالب يزورُه كُلَّ وقتٍ وهو لسعود بمنزلةِ أحدِ نوَّابه وأمرائه الذين في نجدٍ بالسَّمعِ والطاعة, وفشا الأمرُ بالمعروف والنهيُ عن المنكر في مكةَ، فلا يُشرَبُ التنباك في الأسواق، وأمر سعود أن يُجعَلَ في أسواقها مَن يأمرُ بالصلاةِ إذا دخل وقتُها, وبذل سعود لغالبٍ هدايا وتحفًا جزيلةً وأعطاه غالِبٌ مِثلَ ذلك, ثم ارتحل الإمامُ منها إلى وطنِه، وبعث إلى المدينة مرابِطةً مِن جميع نواحي نجدٍ بدَلَ المرابِطة الذين فيها في القلعة، وهذه عادته في الثغور يجعلُهم فيها سَنةً ثمَّ يستبدل بهم غيرَهم؛ ليرجعوا إلى أهاليهم. ولم يحُجَّ في هذه السنة أحدٌ من أهل الشام ومصر والعراق والمغرب وغيرهم إلَّا شِرذمةٌ من أهل المغرب حجُّوا بأمانٍ وسلامٍ."},{"id":4344,"title":"وباء ومرض شديد في الدرعية .","date":["العام الهجري :1224","العام الميلادي :1809"],"text":"اشتدَّ الوباءُ والمرض خصوصًا في الدرعية، فمكث ذلك إلى شهر جمادى ومات في الدرعية خلقٌ كثير من الغرباء والسكَّان حتى أتي عليهم أيامٌ يموت في اليوم الواحد ثلاثون وأربعون نفسًا، وكتب سعود نصيحةً بليغة لأهلِ الدرعية وأرسَلَها إلى جميع النواحي حَذَّرهم فيها من المحظورات وحثَّهم على التوبة، ودعا الله في آخِرِها دعاءً عظيمًا أن يرفَعَ الضرَّ والوباءَ عن الناسِ، وقرئ على الناسِ في مساجِدِ الدرعيةِ."},{"id":4345,"title":"الإمام سعود يبين لوالي الشام سبب منع حجاج الشام عن مكة .","date":["العام الهجري :1224","العام الميلادي :1809"],"text":"عندما منع الإمام سعود حاجَّ الشام من دخول مكَّةَ لأداء الحجِّ، أرسل والي الشام إلى الإمام سعود يستنكِرُ منع حجاج الشام من دخول مكة، فأرسل له الإمام سعود رسالةً مطولة بيَّن فيها سبَبَ مَنعِهم من دخول مكةَ، وممَّا ورد في هذه الرسالة: \"السلام التام والتحية والإكرام يُهدى إلى سيِّد الأنام محمد عليه أفضل الصلاة والسلام, ثم ينتهي إلى جناب الأحشم المكرَّم سلمه الله من الآفات واستعمله بالباقيات الصالحات، وبعد.. ما ذكرتَ من طرف الحاجِّ فأنت تفهَمُ أنَّ البيت بيتُ الله، والوفدَ وفدُه، ولا نمنَعُ عن بيته إلَّا من أمرنا بمَنعِه والله سبحانه وتعالى، قال: {وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِلنَّاسِ وَأَمْنًا} [البقرة: 125]، وقال تعالى: {سَوَاءً الْعَاكِفُ فِيهِ وَالْبَادِ وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ} [الحج: 25]، وقال تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا} [التوبة: 28] ولا يخفاكم ما يجري مع الحاجِّ من الأمورِ العظائِمِ الشِّركية مِن دعوة غير الله، وتعظيمِ الشِّرك بالله، وتعظيمِ المشاهد، وتَركِ الفرائض, وأعظَمُ الفرائض بعد التوحيد الصلواتُ الخمس، لا يؤذَّنُ لها ولا يصلِّي مع أحد جماعة، والأمور العظائم القبائح التي تُنقَلُ مع الحاج من أنواع المنكرات والفواحش من اللُّواطِ والقِحاب وشُربِ المسكر والزَّمر والطَّبل وما يُشابه ذلك من أنواع الملاهي التي يُعرف قبحُها, والله قال جل جلاله: {الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ} [البقرة: 197] فإذا كان الرَّفَثُ والجدال مِن مبطلاتِ الحَجِّ، فكيف بهذه القبائِحِ والمنكراتِ؟! فإن قال قائل: إنه لا يفعَلُ ذلك فنحن نقول: ما نعمُّ النَّاسَ بذلك, ولكِنَّ الحُكمَ على الظاهر, والظاهِرُ مع الحاجِّ وفي أوطانِكم فِعلُ ما ذكرناه، ومن رعاياكم من يقول: هذا ما فعَلَه إلا طوارِفُ [أي حاشية] السلطان, وإنَّ السلطان هو الذي يأمُرُ به, ونقول: هذا لا يفعَلُه ولا يأمر به مَن له أدنى عَقلٍ وبصيرةٍ في الدين فضلًا عن أنَّ السلطان يأمرُ به أو يرضاه, وهذا من الافتراءِ عليه والكذب, ولَمَّا أراد الله أن أهل الحرمين يدخلون في الإسلام, ويشهدون أنَّ الذي هم عليه قبل ذلك أنَّه الباطل،  والشاهد بذلك الشَّريفُ والعلماء والعامة, وأراد الله أن يجعَلَ لنا في الحرمين حُكمًا نافذًا وأمرًا  مطاعًا، فلم يكن لنا عذر من الله مِن مَنعِ [ما] أمَرَنا الله بمَنعِه، ونمنع مَن منَعَه القرآن، ونأذن [لِمن] أذِنَ له القرآن, فغايةُ المطلوب ومنتهى المراد عبادةُ الله وحده، ولا يُشرَكُ له، وتَرْك عبادة ما سواه، وألَّا يُصرَفَ شيء من أنواع العبادة لغير الله، وإقام الصلوات الخمس التي فرض الله في كتابه بعد الشهادتين، وأداء الزكاة والصوم والحج، ومتابعة الرسول صلى الله عليه وسلم، ونفي البِدَع وإزالة المنكرات، وإقامة الحدود على من أصاب منها شيئًا، وإعطاء كل ذي حَقٍّ حَقَّه، وإنصاف الضعيف من القويِّ بالعدل, فهذا جملة ما نحن عليه، وتفصيلُه يطول ذِكرُه, فمَن عَمِل ذلك ودان به فهو المسلمُ له ما لنا، وعليه ما علينا برًّا وبحرًا، ونحن وهو في بلد الله الحرام سواءٌ, ومن أبى عن ذلك منعناه من بلد الله الحرام، وقاتلناه حتى يكون الدينُ كُلُّه لله، كائنًا من كان، ولَمَّا ورد إلينا كتابُك وآدميك [ومندوبك] أركبنا أوادِمَ من أوادِمنا يمشون بالحاجِّ على هالشروط المذكورة، بأن يظهروا الإسلام، وإقام الصلوات الخمس جماعة بأذان وإقامة، وجميع المنكرات تُزال، وأنَّ الحاجَّ يبايعون على العمل بالإسلام، ولا يحجُّ عسكر قليل ولا كثير، ولا أزغة حرب، ولا يحجُّ المحمل لأنَّ المَحمَل فيه اعتقادات وتآليه به من دونِ الله, وظهرت للمسلمين ورأوها في مخالطتِنا لكم في الحج الماضي، ولا نشتهي أن المحمَلَ يجيء بأمامنا ويرجع ما وصل مكة، ولا يجوز لنا [أن] نقِرَّ سياق الشرك، ولا نرضى به، وعلى أنَّ جميع قوانين الحرمين المعروفة التي للبيت وخُدَّام البيت والشريف وعامة أهل مكة، وكذلك ما كان لمسجد الرسول صلى الله عليه وسلم وخُدَّامه، وما كان لأهل المدينة من جميع القوانين علمائهم وعامتهم وأهل القلعة، وكذلك قانون ابن مضيان وحرب أن الجميع ما يختلف منه [في] شيء, وأنه يسلم بأيدي رجاجيلنا وعلى أن ما يبقى في الحرمين ممَّن قَدِم معكم أحد، فإن أحدثتم بعد ما يمشي الحاج حدثًا على الإسلام وأهله، فلا بوجهي من الحاج شيء, فإن صبرتم بما ذكرنا فالحاج يمشي بوجهي عن جميع المسلمين ذهابًا وإيابًا, وذكرنا لملا حسن ورجب مثل ما ذكرنا في هذه الصحيفة, وذكرنا إلى أوادمك أنك معاهدنا على الإسلام، وأنك أمرتَ بالصلوات تقام، وأمرت على معازِفِ الخمر تُرفَع، وهذا إذا وفقك الله للعمل به، وعملت بالتوحيد، وأزلت الشرك، وأقمت الفرائض...\""},{"id":4346,"title":"الإمامُ سعود بن عبد العزيز يرسل عبدَ الله بن مزروع يغزو عمان .","date":["العام الهجري :1224","العام الميلادي :1809"],"text":"أرسل الإمامُ سعود بن عبد العزيز إلى عمان عبدَ الله بن مزروع صاحِبَمنفوحة وعِدَّةَ رجال من أهل نجد، وأمرهم بنزولِ قصر البريمي المعروف في عمان وإحصانه، ثمَّ إن سعودًا بعث بعده إلى عُمان مطلق المطيري بجيش من أهل نجد، وأمرَ أهل عمان بالاجتماع عليه والقتال معه، فاجتمع عليه مقاتِلةُ أهل عمان مع ما معه من أهل نجد، فقاتل أهل الباطنة سحار ونواحيها ومن تبعهم، ورئيسُهم يومئذ عزان بن قيس، وقاتلوا سعيدَ بن سلطان صاحِبَ مسقط، ودام القتالُ بينهم، وقُتِل من عسكر عزان مقتلة عظيمة، قيل بلغ عدد القتلى خمسمائة رجل، ثم اجتمع مع مطلق المطيري جميعُ من هو في رعية الإمام سعود من أهل عُمان، فنازل أهل سحار بألوف من المقاتِلة، ودخلت سنة 1225 هـ وهم على ذلك يقاتلون ويغنمون، وأخذ مطلق ومن معه قرًى كثيرة من نواحي سحار من أهل الباطنة، وبايع غالبُهم على دين الله ورسوله والسمع والطاعة، ولم يبقَ محارب إلا مسقط ونواحيها، مملكة سعيد بن سلطان وما تحت ولاية عزان من سحار، وغنموا منها غنائم كثيرة وبعثوا بالأخماس إلى سعود في الدرعية."},{"id":4347,"title":"مراكب الإنجليز تستبيح رأس الخيمة وتحرقها .","date":["العام الهجري :1224","العام الميلادي :1809"],"text":"أقبَلَت مراكِبُ الإنجليز الذين استنجد بهم سعيدُ بن سلطان صاحِبُ مسقط في عمان بعد أن نقَضَ عهده مع الدرعية، وقصَدَت مراكبهم أهلَ بلد رأس الخيمة في عمان ورئيسُها يومئذ سلطانُ بن صقر بن راشد بن مطر أميرُ القواسم، وحاربوهم فلم يحصُلوا على طائل, فرفعوا على البلد بلورًا وجعلوه في عين الشمس وقابلوا به البلدَ، فاشتعلت النار فيها وكان أكثر بيوتهم عسبان النخل فدخلوا البلدَ واستباحوها ونهبوا ما فيها وأشعلوا فيها النيرانَ ودَمَّروها، وهرب سلطان بن صقر وغالب أهل البلد حتى فرغ العدوُّ منها."},{"id":4348,"title":"الإمام سعود يرسل جيشًا إلى آل خليفة أهل البحرين .","date":["العام الهجري :1224","العام الميلادي :1809"],"text":"عندما تحقَّق للإمام سعود أنَّ آل خليفة أهل البحرين والزبارة يقع منهم بعض المخالفات, فخاف أن يقع أكبَرُ من ذلك, فأرسل إليهم جيشًا واستعمل عليه الأميرَ محمد بن معيقل, ثم أتبعه بعبد الله بن عفيصان واجتمعوا ونزلوا عند الزبارة المعروفة عند البحرين، فأقاموا فيها قريبَ أربعة أشهر حتى رجع الإمام سعود من الحجِّ، فأرسل أمراءَ جيشه إلى آل خليفة يأمرونهم أن يَفِدوا على سعود فساقوهم كرهًا، فقَدِموا عليه في الدرعية، وهم الأمير سلمان بن أحمد بن خليفة، وأخوه عبد الله، وعبد الله بن خليفة وأبناؤهم، ومعهم كليب البجادي وغيره من أعوانهم, ورؤساء رعيتهم، فلما قَدِموا قرَّرَ عليهم سعود ما حدث منهم,  ثمَّ اعتقل رؤساءَهم وردَّ أبناءَهم وبقيَّةَ الرعية إلى بلادهم, وكان سعودٌ لما قبض عليهم أخذ جميعَ خيلهم ونجائبهم وغير ذلك من الشوكة لهم في البحرين، والزبارة، ثم أمر فهدَ بن سليمان بن عفيصان أن يعبر إلى البحرين ضابطًا له، وجعله في بيت المال، ثم إنَّ أبناء آل خليفة نقلوا أكثر نسائِهم وأموالهم في السُّفن، ثم هربوا من الزبارة."},{"id":4349,"title":"وفاة الشيخ حسين ابن شيخ الإسلام محمد بن عبد الوهاب .","date":["العام الهجري :1224","الشهر القمري : ربيع الآخر","العام الميلادي :1809"],"text":"هو العلَّامةُ الشيخ القاضي حسين ابن شيخ الإسلام محمد بن عبد الوهاب، ولد بمدينة الدرعية ونشأ بها وقرأ العلمَ على والده الشيخ محمد بن عبد الوهاب. وكان كفيفَ البصر نيِّرَ البصيرة جَهْوريَّ الصوت بحيث يسمَعُ تكبيرَه في الصلاة أدنى المسجد وأقصاه مع كثرةِ الخلائق، وكان له معرفةٌ في الأصل (التوحيد) والفروع والتفسير, وله مجالسُ عديدة في تدريس الفقه والتفسير وغيرهما, وقد تولَّى إمامة مسجد البجيري في منازل الدرعية الشرقية، وكان خطيبَ الجمعة في مسجد الطريف الكبير الواقع تحت قصر آل سعود في المنازل الغربية من الدرعية، كما كان أحدَ قضاة الدرعية، وكان يقومُ بالإفتاء. أخذ عنه العلمَ جماعة منهم ابناه الشيخ علي بن حسين، والشيخ عبد الرحمن بن حسين، والشيخ أحمد الوهبي، والشيخ سعيد بن حجي، توفي في شهر ربيع الآخِرِ في وباء أصاب الدرعية. وخلَّفَ خمسة أبناء هم: الشيخ علي، والشيخ عبد الرحمن والشيخ حمد، والشيخ عبد الملك، وحسن، وأحفادُه يعرفون اليوم على انفرادهم بآل حُسين نسبة إلى جدهم الشيخ حسين بن شيخ الإسلام محمد بن عبد الوهاب."},{"id":4350,"title":"وفاة الأمير عبد الوهاب أبو نقطة أمير عسير ورجال ألمع .","date":["العام الهجري :1224","الشهر القمري : جمادى الآخرة","العام الميلادي :1809"],"text":"هو الأمير عبد الوهاب بن عامر المتحمي المشهور بـ (أبو نقطة) من بلدة طبب بعسير السراة، وعبد الوهاب من قبيلة ربيعة رفيدة، قَدِم عبد الوهاب مع أخيه محمد بن عامر على إمام الدرعية عبد العزيز بن محمد بن سعود في سنة 1215هـ فعاهداه على دينِ الله ومناصرة الدعوة السلفيَّة والجهاد في سبيل نشرِها، فقبل منهما وأرسل معهما سرية لإخضاع القبائل بقيادة ربيع بن زيد المخارم أمير ناحية الدواسر، فسارا من الدرعية برفقة هذه السرية فلمَّا وصلا قرى عسير الشرقية المجاورة لبلاد شهران، جاء إليهم جميعُ وفود قبائل عسير تعلن ولاءَها وانقيادها للإمام عبد العزيز بن محمد والدخول تحت إمارة محمد بن عامر المتحمي وحكم دولة الدرعية، فصار محمدُ بن عامر أميرًا لجميع قبائل عسير السراة وعسير تهامة المعروفين برجال ألمع، فأخذ محمد ينشرُ دعوة التوحيد ويغزو أعداءها إلى أن وافاه الأجل المحتوم بعملة الجدري سنة 1217 هـ فخلَفَه على إمارة عسير وقبائلها أخوه عبد الوهاب (أبو نقطة) فأخذ عبد الوهاب يغزو ويقود الجيوش لنشر دعوة التوحيد السَّلفية ومحاربة أعدائها من أنصار البِدَع، حتى قُتِل في وادي بيش, وخلفه في الإمارة ابن عمه طامي بن شعيب."},{"id":4351,"title":"نفي محمد علي باشا نقيبَ الأشراف إلى دمياط .","date":["العام الهجري :1224","الشهر القمري : جمادى الآخرة","العام الميلادي :1809"],"text":"نفى محمد علي باشا حاكِمُ مِصرَ عُمَر مكرم نقيب الأشراف إلى دمياط على الرغم أنَّ مَكرم كان له دورٌ في تولية محمد علي شؤون البلاد، عندما قاد هو وعددٌ من مشائخ الأزهر ثورةً لخلع خورشيد بيك باشا سنة 1805م تولى بعدها محمد علي حكم مصر، وحينما استقَرَّت الأمور لمحمد علي خاف من نفوذ المشائخ،  فنفى عمر مكرم إلى دمياط سنة 1809م, وأقام بها أربعةَ أعوام، ثم نقله إلى طنطا توفي فيها 1822م، وبذلك يكون محمد علي باشا قد انفرد بحُكم مصر بعد القضاءِ على الزعامة الشعبية التي كان يتزعَّمُها عمر مكرم."},{"id":4352,"title":"سيول تعم أرجاء الوديان والشعاب في نجد ونواحيها .","date":["العام الهجري :1224","الشهر القمري : جمادى الآخرة","العام الميلادي :1809"],"text":"نزل مطرٌ شديدٌ مصحوب برعد وبرق سال به شعاب بلدان كثيرة من نجد، وامتلأت الوديانُ حتى خشيَ الناس على محالِّهم ومنازلهم منه, وكان هذا السيل وقع مستهلَّ جمادى الآخرة في جمرة القيظ وقتَ حلول الشمس برج السرطان، وهذا لم يُعهَدْ بنزوله في مثل هذا الناحية منذ أزمانٍ."},{"id":4353,"title":"الإمام سعود يسير جيوشه إلى بندر عريش باليمن .","date":["العام الهجري :1224","الشهر القمري : جمادى الآخرة","العام الميلادي :1809"],"text":"كان حمُّود بن محمد أبو مسمار صاحب أبو عريش  قد بايع الإمامَ سعودًا على دين الله ورسوله والسمع والطاعة، ثم ظهر منه ما يريبُ من مخالفة المسلمين ومعاداتِهم، وحدثت عداوةٌ بينه وبين عبد الوهاب أبو نقطة ومنابذة, فكتب الإمامُ سعود إلى حمود بن محمد أبو مسمار يأمرُه أن يحارب أهلَ صنعاء ويسَيِّرَ إليهم جنوده، فلم يفعَلْ، فأمر سعود أهلَ النواحي الحجازية واليمنية ومن يليهم بالمسيرِ لقتاله, وبعث من الدرعيةِ فرسانًا انتقاهم مع نائِبِه غصاب العتيبي، وجعله ناظرًا على أمراءِ النواحي، ونهاه عن المخالفةِ لعبد الوهاب أبي نقطة؛ لأنَّه أمير الجميع، فسار عبد الوهاب بجميع رعاياه من عسير وألمع وغيرهم من أهل الطور وتهامة، وسار علي بن عبد الرحمن المضايفي من الطائف وقراه وبوادي الحجاز وغيرهم أهل بيشة وشهران وعبيدة وقحطان، فاجتمع ما ينيفُ على خمسين ألف مقاتل يقودُهم أبو نقطة, ثم حشد أبو مسمار بمن معه من أهل اليمن ونجران وقبائل يام وحاشد وبكيل وغيرهم من همدان, وداهم أبو مسمار جمعَ عسير الذي فيهم عبد الوهاب أبو نقطة وهم على غير أهبةِ قتال وحصل قتالٌ شديد، وقُتِل عبد الوهاب وعِدَّةٌ من رجال قومِه في هذه الواقعة, ثم كرَّت الجموع على قوم أبي مسمار فهزموهم هزيمة شنيعة، واستمروا في ساقتهم يقتُلون ويغنمون، واستولوا على بعضِ خيامهم ومحطَّتِهم، واستمر أبو مسمار في الهزيمة إلى حصنه أبو عريش، وأخذ المسلمون ظاهر بلاد صبيا ونواحيها، وغنموا أموالًا كثيرة, واستولوا على حصنها صُلحًا، وجعل فيه غصاب عسكرًا مُرابطين، وبعثوا السرايا في تهامة، فقتلوا ودمَّروا وغنموا، وانفضت تلك الوقعة عن قتلى كثيرة من الفريقين, وكان للمسلمين سفنٌ في البحر، فأخذوا غنائم كثيرة من بندر جازان."},{"id":4354,"title":"انتصار الدولة العثمانية على روسيا في معركة تاتاريجه .","date":["العام الهجري :1224","الشهر القمري : رمضان","العام الميلادي :1809"],"text":"حقَّقت الدولة العثمانية انتصارًا في معركة \"تاتاريجه\"، على الجيش الروسي البالغ 60 ألف شخص، قُتل فيها من الروس 10 آلاف جندي."},{"id":4355,"title":"الإمام سعود يحج الحجة السادسة .","date":["العام الهجري :1224","الشهر القمري : ذي الحجة","العام الميلادي :1810"],"text":"الإمامُ سعود يحُجَّ الحَجَّةَ السادسة وحَجَّ معه جمعٌ ممن شملتهم دولتُه مِن أهل العارض والجنوب ووادي الدواسر والأحساء ونواحيه وعمان وأهل نجد وأهل التهايم والحجاز واليمن والمدينة النبوية، ومعهم النساء والأطفال والثقيل والخفيف، وبنات الإمام سعود، وكثير من نساء آل مقرن، ودخلوا مكة واعتمروا وحَجُّوا بأمانٍ عظيم لا يُحمَل فيه سلاحٌ، ونزل سعود القصر الشمالي من البياضية، وأهدى عليه الشريفُ غالب هدايا سَنية وأعطاه عطاءً جزيلًا وبذل في مكة من الصدقات والعطاء شيئًا كثيرًا، ويزوره الشريف كل يوم إلَّا قليلًا، كأنه أحد أمرائِه الذين في نجد, ويدخُلُ سعود الحرمَ ويطوف بالبيتِ ويجلِسُ فوق زمزم مقابِلَ البيت الشريف، وكسا الكعبة المشرفة بالقيلان الأسود الفاخر، وجعل إيزارها وكسوة الباب من الحرير الأحمر المطَرَّز بالذهب والفضة، ثم رحل عنها في العشر الأواخر من ذي الحجة، وبعث إلى المدينة مرابِطةً بدل الذين فيها، ورجع إلى وطنه ولم يحُجَّ في هذه السنة أحدٌ من أهل الشام ولا مصر ولا استانبول ولا العراق إلَّا من كان يحُجُّ بأمانِ الإمامِ سعود."},{"id":4356,"title":"مساعدات الدولة الفارسية للبحرين ومسقط لمواجهة آل سعود .","date":["العام الهجري :1225","العام الميلادي :1810"],"text":"لَمَّا تمكَّنَت قوات الدولة السعودية من دخولِ البحرين والزبارة قصدَ أبناء آل خليفة صاحِبَ مسقط سعيد بن سلطان فاستنصروه وأرسلوا إلى العجم الفُرس واستصرخوهم, وكانت مراكِبُ الإنجليز عند سعيد في مسقط، فاستعانوا بهم فأقبلوا بجموعٍ عظيمة في مراكِبَ كثيرة، وبندروا عند الزبارة بالليل، فأظهر آلُ خليفة منها بقيَّة رجالهم وما فيها من المتاع والمال ودمَّروها جملة, ثم ساروا إلى البحرين ونازلوا فهد بن عفيصان والمرابِطة الذين في قصر المنامة، وهم نحو ثلاثمائة رجل، فحاصروهم وأقاموا على ذلك أيامًا، ثم أخرجوهم بالأمانِ على دمائِهم، فأمسكوا منهم فهد بن عفيصان ومعه ستة رجال، واعتقلوهم رهينةً مقابِلَ رجالهم الذين في الدرعية وتركوا الباقين."},{"id":4357,"title":"الإمام سعود يغزو المزيريب .","date":["العام الهجري :1225","العام الميلادي :1810"],"text":"غزا الإمام سعود غزوة المزيريب وآل خليفة في الاعتقال، فلما رجع طلب منه آلُ خليفة أن يفكَّ أسرَهم ووعدوه السَّمعَ والطاعة ويَنزلوا الزبارة، وأن يجتمعوا فيها ببنيهم وأقربائهم، فإن أراد بنوهم الامتناعَ فإنهم يرجعون إلى الدرعية، وبايعوا سعودًا على ذلك, وأعطوه عهدًا وميثاقًا، فارتحلوا من الدرعية وبعث معهم سعودٌ شوكة من الجيش، فلما وصلوا إلى ناحيتهم طلبوا منهم الموافقةَ على ما بايعوا عليه سعود، فأبوا عليهم فرجعوا إلى الدرعية وأقاموا فيها حتى رجع سعود من الحج، وأطلقوا ابنَ عفيصان ومَن معه."},{"id":4358,"title":"رخص الأسعار في نجد والحرمين .","date":["العام الهجري :1225","العام الميلادي :1810"],"text":"رخصت الأسعار وبلغ البُرُّ ثلاثة عشر صاعًا بريال، والتمر سبع وثلاثون وزنة بريال، ورخصت أسعار الحرمين، وبِيعَ الأردب بأربعة ريالات."},{"id":4359,"title":"عزل يوسف باشا والي الشام .","date":["العام الهجري :1225","العام الميلادي :1810"],"text":"بعد أن قفل الإمامُ سعود من الشام, جاء العزل ليوسف باشا والي الشام, وسار إليه سلمانُ صاحب عكا، فأجلاه واحتوى على جميعِ أمواله، وتولى إمارةَ الشام."},{"id":4360,"title":"وفاة سليمان باشا والي بغداد .","date":["العام الهجري :1225","العام الميلادي :1810"],"text":"هو سليمان باشا والي بغداد، وهو غير سليمان باشا الكبير. سار عبد الرحمن باشا الكردي إلى بغداد، فنازل أهلها ودخلها وقتل سليمان باشا، وسَبَبُ ذلك أن السلطان محمود بن عبد الحميد بعث رجلًا يقال له آغا بكر إلى سليمان يطلب منه خراجَ العراق من مدة سنين لم يأتِه منه شيء، فقام الأغا بكر عنده في بغداد، فلم يحصُلْ له شيء، ثم إن سليمان أعطاه رشوةً وأذن له في الخروجِ من بغداد، فخرج فاستصرخ الأكراد وبادية العراق على سليمان، وذكر لهم أنه عصى على السلطان, فسار إليه عبد الرحمن الكردي ووقعت المصافَّةُ خارج بغداد وهُزِمَ سليمان وجنوده فهرب سليمان لوجهِه، فأمسكه رجال من بوادي الدفافعة فقطعوا رأسه وأتوا به إلى الكردي."},{"id":4361,"title":"غزو الإمام سعود الشام .","date":["العام الهجري :1225","الشهر القمري : ربيع الآخر","العام الميلادي :1810"],"text":"سار الإمامُ سعود بجيوشِه التي استنفرها من جميعِ النواحي الحاضر والبادي من وادي الدواسر إلى مكة والمدينة، إلى جبلِ طيٍّ والجوف وما بين ذلك الدرعية، وقصد نقرة الشام المعروفة؛ لأنه بلغه الخبَرُ أنَّ بوادي الشام وعربانه من عنزة وبني صخر وغيرهم فيها, فلما وصل تلك الناحية لم يجِدْ فيها أحدًا منهم؛ إذ سبقه النذيرُ إليهم فاجتمعوا على دوخي بن سمير رئيس ولد علي من عنزة، وهو من وراء الجبَلِ المعروف بطويل الثلج قربَ نابلس نازلين عين القهوة من جبل حوران, ولما بلغ ابن سمير ومن معه إقبالُ سعود إليهم انهزم بمن معه من البوادي ونزلوا الغور من حوران, فسار سعود في تلك الناحية وأقبل فيها وأدبر واجتاز بالقرى التي حول المزيريب وبصرى، وكان أهلها قد هربوا عنها لَمَّا سمعوا بمسيره, ثم نزل عين البجَّة وروى منها المسلمون وشربت خيلهم وجيوشهم، ثم أقبل على قصر المزيريب، فظهر عليهم منهم خيلٌ، فحصل طرادٌ فانهزمت الخيل إلى القصر واحتصروا فيه, ثم ارتحل سعودٌ لأجل حصانته ونزل بصرى, وبات فيها ثم رجع قافلًا إلى وطنِه ومعه غنائمُ كثيرة من الخيل والمتاع والأثاث والطعام، وقُتِل من أهل الشام عِدَّةُ قتلى، وحصل في الشام رجفةٌ ورهبة عظيمة بهذه الغزوة في دمشقَ وغيرها من بلدانه وبواديه."},{"id":4362,"title":"الإمام سعود يحج الحجة السابعة .","date":["العام الهجري :1225","الشهر القمري : ذي الحجة","العام الميلادي :1811"],"text":"حجَّ الإمامُ سعود الحَجَّةَ السابعة واحتفل معه بالحَجِّ جميعُ رعيته من الجبل والجوف إلى الأحساء ووادي الدواسر ونواحيه وعمان وجميع أهل الحجاز وعسير وألمع وجميع طور تهامة ومن يليهم, فدخلوا مكةَ واعتمروا وحجُّوا بأمان عظيم، ونزل سعود القصر الشمالي من البياضية وبذل في مكة من الصدقات والعطاء شيئًا كثيرًا, وخطب سعود يوم عرفة. قال ابن بشر: \"حججت تلك السنة وشهِدتُ سعودًا وهو راكب مطيَّتَه مُحرِمًا بالحج ونحن مجتمعون في نمرة لصلاة الظهر، فخطب فوق ظهرها خطبةً بليغة, ووعظ الناسَ فيها وعلَّمهم مناسِكَهم وذكَّرَهم ما أنعم الله عليهم به من الاعتصام بكلمة لا إله إلا الله وما أعطى الله في ضمنها من الاجتماع بعد التفرق وأمان السبل وكثرة الأموال وانقياد عصاة الرجال، وأن أضعف ضعيف يأخذ حقه كاملًا من أكبر كبير من مشايخ البوادي، وأعظم عظيم من رؤساء البلدان، ونادى وهو على ظهرها لا يُحمَل في مكة سلاح ولا تتَبَرَّج امرأة بزينة, وتوعَّد من فعل ذلك من رعيته, ورأيتُ الشريف غالبًا أقبل فوق حصانه ونحن جلوس في الصف وليس معه إلَّا رجل واحد، ونزل سعود من كور مطيته وسلم عليه وتعانقا\".  ودخل سعود مكة وسار في الناس سيرةً حَسنةً بالأمر بالمعروف والنهي عن المنكر والصدقات والعطاء والرأفة، وجعل في الأسواق رجالًا وقت الصلاة يحضُّونَهم عليها، ولا تجد في الأسواق مِن شُرب التنباك ولا غيره من المحظورات إلا ما لا يرى ظاهرًا، وكسا الكعبةَ المشرفة بالقيلان الفاخر وجعل إيزارها وكسوة الباب من الحرير المنسوج من الذهبِ والفضةِ، وكان أكثر جلوسه في الحرم فوق زمزم مقابِلَ البيت الشريفِ."},{"id":4363,"title":"خروج أبناء الإمام سعود لعمان دون موافقة والدهم .","date":["العام الهجري :1225","الشهر القمري : ذي الحجة","العام الميلادي :1811"],"text":"بينما كان الإمامُ سعود في الحَجِّ خرج من الدرعية أبناؤه تركي وأخواه ناصر وسعد وقصدوا ناحية عمان ومعهم عدة رجال من أتباعهم وخَدَمِهم، وذلك أنه وقع بينهم وبين أبيهم مغاضبة عندما طلبوا منه زيادةً في عطائهم وخَراجِهم، فأبى عليهم ذلك وطلبوا الخروجَ إلى عمان للقتالِ فمنعهم منه، فلما وصلوا عمان عَلِم بهم أناس من أهل باطنة عمان وغيرهم فنفروا عليهم وهجدوهم بالليلِ بياتًا فحصل بينهم قتالٌ شديدٌ قُتِلَ من الفريقين عدَّةُ قتلى، فلما انقضت الوقعةُ أرسل أبناء سعود إلى مطلق المطيري أمير الجيوشِ في عمان، فأتى إليهم واجتمعوا به ومعه جنودٌ كثيرة من أهل نجد وأهل عمان، وصار رئيسُ الجميع تركي بن سعود فسارت تلك الجنود إلى عمان، فدخلوا عددًا من بلدان وحواضر عمان وغنموا منها أموالًا عظيمة، فلما بلغ الخبر الإمام سعود وهو في الحج أفزعه ذلك وغَضِبَ غضبًا شديدًا، فلما رجع إلى الدرعية طلب منه رؤساء أهلِها أن يعفوَ عنهم ويرسل إليهم ويبذُل الأمان، فأبى ذلك، فبعث جيشًا من الدرعية نحو أربعين رجلًا، وقال لهم: اقصُدوا قصر البريمي وأخرجوا منه المرابِطة الذين فيه وأمسكوه، ولا تدعوا أحدًا من جنودِهم يدخله، وكان أبناء سعود يأوون إليهم فيه، فلما أمسكوه هؤلاء طردوا عنه الأبناء فلم يدخلوه، وأرسل سعود أيضًا إلى مطلق المطيري ومن معه من الرؤساء وأتباعهم وأمَرَهم أن يخرجوا من عمان ولا يُبقوا رجلًا واحدًا فضاق الأمر بأبنائه، وشفَعَ فيهم رؤساء المسلمين أن يبذُلَ لهم الأمان، فأبى سعود إلا أنَّهم يأتون بالحسنة والسيئة، فأقبل مطلق المطيري مع الأبناء إلى الأحساء وخافوا من أبيهم، فأرسل مطلق إلى سعود يبلِّغُه خبرهم فأعطاهم الأمان، ولما قدموا الدرعية مَرِضَ ناصر بن سعود شهرين حتى مات ولم يعُدْه والده لمخالفتِهم أمرَه."},{"id":4364,"title":"وفاة الشيخ العلامة حمد بن ناصر بن معمر .","date":["العام الهجري :1225","الشهر القمري : ذي الحجة","العام الميلادي :1811"],"text":"هو العلَّامةُ المحَقِّقُ الشيخ حمد بن ناصر بن عثمان بن معمر النجدي التميمي من آل معمر أهل العُيَينة، نزح منها واستوطن مدينة الدرعية، وقرأ فيها على الشيخ محمد بن عبد الوهاب وأخيه الشيخ سليمان بن عبد الوهاب، وأخذ العربية عن الشيخ حسين بن غنام، وبعد ذلك جلس للتدريس بمدينة الدرعية، فأخذ عنه العلمَ خَلقٌ كثير من أهل الدرعية وغيرهم، منهم العلامة سليمان ابن الشيخ عبد الله بن محمد بن عبد الوهاب, وعبد الرحمن بن حسن بن محمد بن عبد الوهاب, وابنه العالم القاضي الأديب الأريب عبد العزيز بن حمد بن معمر. وعبد الله بن عبد الرحمن أبا بطين, وأرسله الإمام عبد العزيز بن محمد على رأس ركبٍ من العلماء ليناظروا عُلماء الحرم بطلبٍ من شريف مكة الشريف غالب سنة 1211، فأقام مدة عند الشريف قاضيًا، كانت وفاته في هذا العام بمكة بعد قضاء مناسك الحج في منتصف شهر ذي الحجة، فصلى عليه عددٌ كثير من المسلمين تحت الكعبةِ، ثم خرجوا به من الحرم إلى البياضية وخرج معهم الإمامُ سعود ودُفِن بمكة."},{"id":4365,"title":"وفاة الشيخ العلامة حسين بن غنام صاحب تاريخ ابن غنام .","date":["العام الهجري :1225","الشهر القمري : ذي الحجة","العام الميلادي :1811"],"text":"هو الشيخ العلامة أبو بكر حسين بن أبي بكر بن غنام الأحسائي المالكي مذهبًا التميمي نسبًا، ولد ببلدة المبرز بالأحساء ونشأ بها وقرأ على علمائها، ثم نزح منها إلى الدرعية، فقدمها على الإمام عبد العزيز بن محمد والشيخ محمد بن عبد الوهاب فأكرماه وأنزلاه المنزلة الرفيعة، فاستقرَّ في الدرعية وجلس فيها لطلاب العلم يقرؤون عليه علم النحو والعروض فقط، منهم الشيخ العلامة سليمان بن عبد الله ابن الشيخ المجدد محمد بن عبد الوهاب, والشيخ عبد الرحمن بن حسن ابن الشيخ محمد بن عبد الوهاب، والشيخ عبد العزيز ابن الشيخ العلامة حمد بن ناصر بن معمر. كانت له اليد الطولى في معرفة العلم وفنونِه, وصنَّف مصنفات منه: العقد الثمين في شرح أصول الدين, وألف تاريخه المشهور بتاريخ ابن غنام وسمَّاه \"روضة الأفكار والأفهام لمرتاد حال الإمام وتعداد غزوات ذوي الإسلام\" وله معرفة في الشعر والنثر، وله قصائد طوال موجودة في تاريخه, وهي تدل على طولِ نَفَسه في الشعر, وتوفِّي في الدرعية."},{"id":4366,"title":"تكليف محمد علي بقتال الدولة السعودية من قبل الدولة العثمانية .","date":["العام الهجري :1226","العام الميلادي :1811"],"text":"لما بدأ الإصلاح ودعوة التوحيد الصحيح ينتشران في أرض نجد والحجاز حتى دخل الحرمان تحت حكم الدولة السعودية- كان بدهيًّا أن يوجد معارِضون لهذه الدعوة والدولة على اختلاف مشاربِهم وأهدافهم، وكان من بين هؤلاء الدولةُ العثمانية الني انزعَجَت مِن امتداد سلطان دولة آل سعود إلى الحجاز وأطراف العراق والشام، وكذلك واليها في مصر محمد علي باشا الذي له أطماع وطموحات شخصية، وبعض الدول الأوربية التي أزعجها وصولُ هذه الدولة الناشئة إلى الممرَّات البحرية في الخليج والبحر الأحمر، وخاصة إنكلترا، فسعت بما لها من تأثيرٍ على الدولةِ العثمانية وعلى محمد علي باشا لتُوقِفَ هذا المد في نجد، حيث قبل والي مصر تكليفَ السلطان العثماني القيامَ بمهمة قتال هذه الدولة الناشئة واستعادة الحرمين، وقبل بدء أي عمل قام بقتل المماليك المنافِسين له خشيةَ غَدرِهم حيث دعاهم بمناسبةِ إرسال ابنه طوسون على رأس جيش إلى الجزيرة العربية، فقتلهم في هذه المناسبة. وتمثَّلت جهود محمد على في إرسال ثلاث حملات رئيسة لحرب الدولة السعودية؛ قاد الأولى ابنه طوسون، وتولى هو الحملة الثانية، والحملة الأخيرة كانت بقيادة ابنه إبراهيم التي انتهت بالقضاءِ على الدولة السعودية الأولى وتدمير عاصمتِها الدرعية واستباحة أهلها الذين وقعوا بين القَتلِ والأسر والتشريدِ. وذلك عام 1233هـ."},{"id":4367,"title":"عقد معاهدة تحالف بين مسقط وفارس .","date":["العام الهجري :1226","العام الميلادي :1811"],"text":"لوحظ أن الخلافَ القائِمَ بين السعوديين ودولة العجم استغَلَّه حُكَّام مسقط وغيرهم في مناطق الخليج العربي، في إقامة نوعٍ مِن الوفاق بينهم وبين دولة الفرس، وقد عبَّرَت البعثة الدبلوماسية التي أرسلها سعيد بن سلطان برئاسة سالم إلى بلاط الشاه في هذه السنة عن هذا الوِفاق؛ إذ كان هدفُها إقامةَ معاهدة تحالف بين مسقط وبين فارس, وقد نجحت هذه البَعثةُ في تحقيق هدفِها, وكان من ثمارِ ذلك أن ساعَدَت فارسُ حكومةَ مسقط بقوات عسكرية بقيادة صادي خان، فحاربت إلى جانب قواتها ضد السعوديين في عمان، واستردَّت حصون سمايل ونخل."},{"id":4368,"title":"قتال بين مطلق المطيري أمير جيوش الدولة السعودية في عمان وصاحب مسقط .","date":["العام الهجري :1226","العام الميلادي :1811"],"text":"جمع صاحبُ مسقط سعيد بن سلطان جموعًا وعسكرh كثيرا, واستنصر بالعجم فأتاه منهم نحو 3000 مقاتل، وساروا إلى عمان, وعاثوا فيما يليهم من رعايا وأتباع الدرعية، واستولوا على بلاد الجبري سمايل، وهرب الجبري منها, فسار مطلق المطيري بشوكةِ المجاهدين الذين معه في عمان من أهل عمان ونجد وغيرهم، فجمع اللهُ بينهم وبين عساكر صاحب مسقط وتنازلوا واقتتلوا قتالًا شديدًا، فانهزمت جنود صاحب مسقط, وركب المجاهدون أكتافَهم وقَتَلوا منهم مقتلةً عظيمة، وأخذوا خيامَهم ومحطَّتَهم وغالب متاعهم ومدافعهم، وهى أكثر من عشرة مدافع, ورجع  بقيَّتُهم إلى مسقط وسمايل، وأخذ المجاهدون منهم غنائم عظيمة."},{"id":4369,"title":"موقعة خكيكرة بين الكويت والبحرين من جانب وحاكم الدمام من جانب آخر .","date":["العام الهجري :1226","الشهر القمري : صفر","العام الميلادي :1811"],"text":"خاضت الكويت معركةَ خكيكرة مع البحرين بقيادة عبد الله بن أحمد آل خليفة وجابر بن عبد الله الصباح ضِدَّ حاكم ساحل الدمام رحمة بن جابر الجلهمي، الذي دعمه الإمامُ سعود بن عبد العزيز بن محمد حاكمُ نجد، وانتهت المعركة بانتصار البحرين والكويت, وكان من أسباب المعركة أنَّ الإمامَ سعودًا كتب إلى رحمة بن جابر الجلهمي في قطر يأمرُه فيها بالاستعداد لغزو البحرين، وكان محاربًا لآل خليفة حكام البحرين، فأرسل إليه الإمام سعود جيشًا من أهل نجد والأحساء، فاجتمعت عنده 60 سفينة ما بين كبيرة وصغيرة، فلما علم بذلك عبد الله بن أحمد آل خليفة حاكم البحرين أرسل إلى حاكم الكويت الشيخ جابر بن عبد الله الصباح يستنصره، فأتاه بحرًا بالسفن فبلغت سفنهم جميعًا 200 سفينة، والتقوا عند خوير حسان بالقرب من القطيفِ، وربطوا السفن واقتتلوا فقُتِل من أهل البحرين والكويت 1000 رجل، منهم دعيج بن صباح الصباح، وراشد بن عبد الله بن أحمد آل خليفة، وقُتِل من أتباع رحمة بن جابر الجلهمي 300 رجل، وانهزم رحمة بن جابر الجلهمي."},{"id":4370,"title":"مذبحة المماليك في مصر (مذبحة القلعة) .","date":["العام الهجري :1226","الشهر القمري : صفر","العام الميلادي :1811"],"text":"عندما وصل محمد علي باشا لسُدَّة الحكم في مصر، أخذ في التخلُّص من كل القوى المنافِسة له، حتى تلك التي وقَفَت بجانبه وساعدته في الحصول على هذا المنصِبِ الخطير، مثل العلماء ومشايخ الأزهر، والحامية الألبانية الذي هو واحِدٌ من أفرادها، ولكِنْ كان أقوى خصومِ محمد علي وأشدهم تهديدًا له هم المماليك، ولقد حاول محمد علي التخلصَ منهم عدة مرات، ولكنه فَشِل لكثرتِهم وتخوُّفِهم منه واتِّباعهم لأسلوب الكرِّ والفر، وكان محمد علي داهيةً شديد الذكاء، لا يُبالي بأيِّ وسيلة تحقِّق هدفه؛ لذلك لجأ إلى المكيدة حيث استغَلَّ مناسبة خروج طوسون باشا ولده على رأس حملة كبيرة للقضاءِ على دعوة الشيخ محمد بن عبد الوهاب بنجدٍ والحجاز، وأعدَّ وليمةً كبيرة دعا لها قادةَ المماليك وكبراءَهم وفرسانَهم وأبطالهم، وذلك بالقلعة الشهيرة بالقاهرة، وذلك يوم الجمعة الموافق 5 صفر 1226هـ 1 مارس 1811م. ولَمَّا اكتمل دخولهم للقلعة انهال عليهم الرَّصاصُ من كل مكان، فقُتِلوا جميعًا ما عدا أمين بك الذي قفز بفَرَسِه من على سور القلعة فنجا وهرب، ثم انطلق الجنودُ بعد ذلك إلى بيوت المماليك وأحيائِهم يَقتُلون من يجدونَه، وهكذا استطاع محمد علي أن يتخَلَّصَ من المماليك."},{"id":4371,"title":"معركة بحرية بين السعوديين وأهل البحرين .","date":["العام الهجري :1226","الشهر القمري : ربيع الأول","العام الميلادي :1811"],"text":"لما رجع سعود من الحج أطلق آلَ خليفة أهل البحرين والزبارة، وأذِنَ لهم بالرجوع إلى بلدهم، ووعدوه بالسمع والطاعة وعدم المخالفة، ووافق وقتُ وصولهم البحرين وقوعَ مقاتلة عظيمة في البحر بين عشايرهم وأبنائهم وبين أتباع الدولة السعوديةِ الذين في ناحيتِهم، وهم رحمة بن جابر بن عذبي أمير خوير حسان المعروف، وأبا حسين أمير الحويلة البلد المعروفة في قطر، وإبراهيم بن عفيصان أمير شوكة المرابِطة من أهل نجد وغيرهم، وذلك أنَّ هؤلاء سار بعضُهم على بعض في السفُنِ، فوقعت الملاقاة في البحر قربَ البحرين، فوقع قتالٌ شديد وكثُر القتلى بين الفريقين، ثم اشتعلت النار في السفُنِ، ومات بينهم خلق كثيرٌ قتلًا وحرقًا وغَرَقًا، فاحترقت السفن بمن فيها، واحترق لابن جابر وأبا حسين ومن معهم من المسلمين سبعةُ مراكب، واحترق لآل خليفة نحو ذلك, وقُتِل من أهل البحرين وأتباعهم ومن أتباع آل سعود نحو 1600 قتيل."},{"id":4372,"title":"اضطراب الأوضاع في عُمان ونقضهم العهد .","date":["العام الهجري :1226","الشهر القمري : جمادى الأولى","العام الميلادي :1811"],"text":"لَمَّا خرج أبناء سعود ومُطلق المطيري ومعه رؤساء المسلمين وأتباعهم من عمان وقع بعضُ الخلل, ونقَضَ العهد أكثر بنو إياس، فكتب سعود لعبد العزيز بن غردقة صاحب الأحساء أن يسيرَ بجيشٍ يكون هو أميرَه، فلما وصل ابن غردقة عمان وقع بينه وبين بني إياس وغيرهم من عمان وقعة هُزم فيها الغردقة و200 من أهل الأحساء وعمان وغيرهم."},{"id":4373,"title":"الحملة المصرية الأولى على الحجاز بقيادة أحمد طوسون باشا .","date":["العام الهجري :1226","الشهر القمري : رجب","العام الميلادي :1811"],"text":"انطلقت حملةُ أحمد طوسون بن محمد علي من مصرَ، ونزل طوسون على الساحِلِ الغربيِّ بجيشٍ قِوامه عشرة آلاف جندي, حرص طوسون أن يُغدِقَ الأموال والهدايا والخِلَع على شيوخ القبائل ورؤساء الجماعات التي تقطُن الموانئ الحجازية ولها نفوذ فيها؛ لتكون سندًا لقواتِه، ولتقبَلَ تأجير إبلها إلى قواته من أجل حَمل المُؤَن والعتاد من المناطق الساحلية إلى داخل البلاد، واستولى على ينبُع بدون مقاومة تذكر, ثم استدرج عبد الله بن سعود قوات طوسون إلى الأراضي النجدية من أجل إضعافِها وتشتيت قواتِها, حتى تمكنت القواتُ السعودية من إنزال هزيمةٍ كبيرة بقوات طوسون في وقعة وادي الصفراء بين المدينة والقصيم سنة1227، وقُتِل من جيش طوسون 1200 مقاتل، وبعد هذه الهزيمة اضطر طوسون إلى أن يطلُبَ العون والمساعدة من والده محمد علي باشا، ثمَّ عاد إلى ينبع وبقِيَ فيها مدَّةً ثم تقدَّم نحو المدينة، ونجح في الاستيلاءِ عليها بعد حصار دام شهرين، ثم توجَّه طوسون إلى جدة ودخلها, فاضطر عبد الله بن سعود أن يخرُجَ من مكة, فتمكن طوسون من دخول مكةَ بدون معارضة, ثمَّ استولى على الطائِفِ، لكن السعوديين عادوا وانتصروا في تَرَبة والحناكية وقطعوا طرقَ المواصلات بين مكة والمدينة، وانتشرت الأمراضُ في صفوف جيش طوسون، وأصاب الجنودَ الإعياءُ نتيجة شدة القيظ وقِلَّة المؤونة والماء، ما زاد موقف طوسون حرجًا، فرأى بعد تلك الخسائر أن يلزم خطةَ الدفاع، وأرسل إلى والده يطلُبُ المساعدة."},{"id":4374,"title":"دخول الإسلام أستراليا .","date":["العام الهجري :1227","العام الميلادي :1812"],"text":"بدايةُ دخول الإسلام في أستراليا تعود إلى بدايات القرن الماضي عندما قام الإنجليز أثناءَ احتلالهم لأفغانستان بجلب الذَّهَبِ إلى أستراليا؛ نظرًا للارتباط الإنجليزي بهذه القارة الحديثة. ولكِنَّهم فكَّروا في أن أستراليا نفسها يمكن أن تكونَ موطنًا للذهب، فاستقدموا عمالًا مسلمين من أفغانستان للعمل في المناجم الأسترالية، وأخذ هؤلاء الأفغان ينشرون الدين الإسلامي، وقاموا ببناء أول مسجد في غرب بيرث، وكان ذلك في عام 1904م. وأعقب ذلك الهجرات الداخلية للمسلمين إلى أستراليا، إلى أن انتشر الإسلامُ هناك، وتتابعت الهجراتُ حتى تمَّ نَشرُ الدعوة الإسلامية، وفي بدايةِ الستينيات من القرن العشرين فَتَحت أستراليا باب الهجرة أمام العرب والمسلمين، فهاجر إليها أعدادٌ كبيرة من لبنان وفلسطين ومصر وتركيا وإيران ويوغوسلافيا بَحثًا عن الرزق، وقد تمكَّن هؤلاء في ظلِّ الحريّة المكفولة لهم من نشر الإسلام وتثبيت أركانِه، حتى وصل عددُ الجالية المسلمة هناك اليوم إلى 650 ألفَ مسلم، مكونة من سبع عشرة جنسيَّة، أكبَرُها تَعدادًا الجالية اللبنانيَّة ثم التركيَّة ثم الباكستانيَّة والإندونيسيَّة والمصريَّة والماليزيَّة وغيرها من الجنسيَّات الإسلاميَّة، ويتركز قرابة 80% من المسلمين في مدينتي سيدني ومالبورن."},{"id":4375,"title":"استقلال صربيا عن الدولة العثمانية بموجب معاهدة بوخارست .","date":["العام الهجري :1227","الشهر القمري : جمادى الأولى","العام الميلادي :1812"],"text":"حاول العثمانيون عقدَ اتفاقٍ مع روسيا مماثلٍ لِما جرى بين إنكلترا وروسيا، ولكنَّه فَشِل واشتعلت نارُ الحرب بينهما، وهُزم العثمانيون واستولى الروسُ على بعض المواقع، وعُزِل الصدر الأعظم ضياء يوسف باشا وتولى مكانه أحمد باشا الذي انتصر على الروس، وأجلاهم عن المواقِعِ التي دخلوها، وساءت العلاقة بين فرنسا وروسيا، وكادت تقعُ الحرب بينهما، فطلبت روسيا الصلحَ مع الدولة العثمانية، وعقدت بين الطرفين مُعاهدة بوخارست التي نصَّت على بقاء الأفلاق والبغدان وبلاد الصرب تابعة للدولة العثمانية. وقد مكَّنَ الصُّلحُ السلطانَ محمود الثاني من القيام ببعض الإصلاحاتِ والقضاءِ على الثورات والتمَرُّد في الدولة، ولَمَّا عَلِم الصربيون بمعاهدة بوخارست، وإعادة خضوعهم للدولة العثمانية، قاموا بالثورة غيرَ أنَّ القوات العثمانية أخضعَتْهم بالقوة، وفَرَّ زعماء الثورة إلى النمسا، ولكِنَّ أحدهم وهو ثيودور فِتش أظهر الولاء للعثمانيين وخضع للسلطةِ العثمانية، وحصل على امتيازات خاصةٍ مِن الدولة."},{"id":4376,"title":"وفاة الشيخ عبد الله الشرقاوي شيخ الأزهر .","date":["العام الهجري :1227","الشهر القمري : شوال","العام الميلادي :1812"],"text":"هو الشيخُ عبد الله بن حجازي بن إبراهيم الشرقاوي أحدُ مشائخ الأزهر. ولِدَ بقرية الطويلة من قرى الشرقية بمصر سنة 1150هـ, وتعلَّم في الأزهر وتولى مشيختَه سنة 1208هـ, وفي عهده قام الأزهرُ بقيادة الحركة الوطنية ضِدَّ الحملة الفرنسية، وكانت له مواقِفُ شجاعة أثناء المعارك مع الفرنسيين، وتزَعَّم الشرقاويُّ قيادة ثورة القاهرة الأولى, ومن مؤلَّفاتِه التحفة البهية في طبقات الشافعية, وتحفة الناظرين في من ولِيَ مصر من السلاطين, وحاشية على شرح التحرير في فقه الشافعية, فتح المبدي شرح مختصر الزبيدي. توفي الشرقاوي بالقاهرة."},{"id":4377,"title":"الحملة المصرية الثانية بقيادة محمد علي باشا .","date":["العام الهجري :1228","العام الميلادي :1812"],"text":"بعد أن هُزم طوسون في وقعة وادي الصفراء بين المدينة والقصيم سنة1227 طلب المساعدةَ من والده، فجهَّز جيشَه وأخذ معه الأموال للمساعدة. قرر محمد علي باشا أن يسير بنفسِه إلى الحجاز لمتابعة القتال وبسْطِ نفوذه في شبه الجزيرة العربية، فغادر مصر على رأس جيش آخَرَ، ونزل في جدة، ثم غادرها إلى مكة وهاجم معاقِلَ السعوديين إلَّا أنه فَشِلَ في توسيع رقعة انتشاره، فأخلى القنفذةَ بعد أن كان قد دخَلَها، وانهزم ابنه طوسون في تَرَبة مرة أخرى. إلا أنَّ وفاة الإمام سعود في هذه الفترة وتولِّي إمارة الدرعية عبد الله بن سعود الذي لم يكُنْ في كفاءة والده في القيادة العسكرية؛ أدى إلى ضعف القوات السعودية، فتمكَّن محمد علي باشا من التغلُّبِ على الجيش السعودي في معركة بسل، وسيطر على تَرَبة، ودخل ميناء القنفذة، في حين سيطر طوسون على القِسمِ الشمالي من نجدٍ. عند هذه المرحلة من تطوُّر الأحداث اضطر محمد علي باشا أن يغادِرَ شبه الجزيرة العربية ويعود إلى مصر للقضاءِ على حركة تمرُّدِ استهدفت حُكمه، وبعد القضاء على هذه الحركة استأنف حربه ضدَّ الدولة السعودية، فأرسل حملةً عسكرية أخرى إلى شبه الجزيرة بقيادةِ ابنه إبراهيم باشا في 5 سبتمبر سنة 1816م"},{"id":4378,"title":"وفاة الأمير عثمان بن عبد الرحمن المضايفي .","date":["العام الهجري :1228","العام الميلادي :1812"],"text":"هو الأمير عثمان بن عبد الرحمن العدواني من قبيلة عدوان، كان من أمراء الشريف غالب أمير مكة ووزيره في الشؤون الخاصة، وكان على درجة عالية من الكفاءة أقنعت الشريفَ غالبًا أن يتَّخِذَه وزيرًا له وأن يكونَ صفيَّه وحميمَه، وقد تزوج المضايفي بأختِ الشريف غالب بن مساعد ثم تحوَّل إلى تأييد دعوة التوحيد بعد أن رأس وفدًا من قبل الشَّريفِ غالب للتفاوضِ مع حكَّام الدرعية، فلما عاد من الدرعية أخذ يدعو بالإمارة لنفسِه، وانضم إليه بعضُ قبائل الحجاز، وأعلن ولاءه للدولة السعودية التي عينته أميرًا على الطائف، وأصبح من أشد خصوم الشريف غالب وشارك في القوات السعودية التي واجهت حملةَ طوسون في الحجاز, وتشجَّع المضايفي بعد وقعة تربة التي هزم فيها طوسون، فتقدَّم نحو الطائف، ولكِنَّه هُزم وقد قُتِل كثيرٌ من رجاله، ووقع هو نفسه في الأسرِ، فأرسله الشريف غالب إلى محمد علي في مصر، لكِنَّ محمد علي كان قد خرج عامدًا إلى الحجاز قبل وصول عثمان إلى مصر, فطِيفَ بعثمان المضايفي على بغلة في جميع أنحاء القاهرة، ثم أُرسِلَ إلى الأستانة حيث أُعدِم هناك!"},{"id":4379,"title":"دخول قوات أحمد طوسون إلى مرفأ جدة .","date":["العام الهجري :1228","الشهر القمري : محرم","العام الميلادي :1813"],"text":"وجد أحمد طوسون باشا الطريقَ مفتوحًا أمامه للتوغُّلِ في الحجاز، وظهرت حاجةُ قواته إلى مرفأ جدة؛ ليكون مركزا لتموين الجيشِ في زحفِه نحو مكة، فأرسل طوسون باشا إلى شَريفِ مكَّةَ الشَّريفِ غالب؛ ليسمح له بالدخولِ إلى مرفأ جدة، فسَمَح له وأَخَذت قوات طوسون طريقَها في الزَّحفِ نحو مكة."},{"id":4380,"title":"وقوع وباء وحمى في بلدان سدير ومنيخ .","date":["العام الهجري :1229","العام الميلادي :1813"],"text":"وقع في بلدان سدير ومنيخ وباء وحمى مات فيه خلق كثير، وأكثر من مات من بلد جلاجل؛ حيث مات منهم أكثر من 600 نفس بين كبير وصغير، ولم يزل الوباءُ من مبتدأ هذه السنة إلى آخِرِها."},{"id":4381,"title":"عبد الله بن سعود يوجه أخاه فيصل لقيادة عساكر الدولة في الحجاز .","date":["العام الهجري :1229","العام الميلادي :1813"],"text":"كان عبدُ الله بنُ سعود بعد عودتِه من غزوِ الحجاز أقام في القصيمِ خمسة أشهر، وأرسل أثناءَ إقامتِه هناك أخاه فيصلًا إلى تربة؛ ليتولى قيادةَ جموعِ المسلمين التي من تهامة والحجاز وغيرهم ومَن معه من أهلِ نجدٍ."},{"id":4382,"title":"وفاة الأمير إبراهيم بن سليمان بن عفيصان أمير الأحساء .","date":["العام الهجري :1229","العام الميلادي :1813"],"text":"هو الأميرُ إبراهيم بن سليمان بن عفيصان أميرُ الأحساء، ومِن أبرزِ قادةِ وأمراء الدولة السعودية الأولى حقَّق عددًا من الانتصاراتِ في معاركَ مع خصومِ الدَّولةِ خاصَّةً في مناطِقِ شرقيَّ الجزيرة العربية, وقد تولَّى ابن عفيصان إمرةَ عددٍ مِن البلدان التي خضعت لحُكمِ الدولة السعودية؛ فقد تولى إمارةَ الأحساء في عهد الإمامِ عبد العزيز بن محمد بعد أن تمكَّن من فتحِها سنة  1210هـ/ 1795م، ثم أصبح إبراهيم أميرَ البحرين بعد أن أرسلَه الإمامُ عبد العزيز لمساعدة آلِ خليفة في التخلُّصِ من حُكمِ سلطان بن سعيد حاكمِ عمان، ثمَّ أميرَ قطر، ثم أمير عمان، ثمَّ أمير المدينة المنورة، ثم أخيرًا أميرًا لعنيزة إلى أن توفِّي فيها هذا العامَ"},{"id":4383,"title":"وفاة الشيخ عبد الله الأول بن  صباح أمير الكويت .","date":["العام الهجري :1229","الشهر القمري : جمادى الأولى","العام الميلادي :1814"],"text":"هو الشيخُ عبد الله الأول بن صباح  بن جابر بن سليمان بن أحمد تولى حكم الكويت بعد أن توفِّي والده سنة 1190هـ وقد بقي في حكم الكويت 39 سنة, وبعد وفاته تولى حكمَ الكويت ابنُه جابر الأول، الذي كان في البحرين وقتَ وفاة والده، فتسلم الحكم في الكويت الشيخُ محمد السلمان جد المالك الصباح بعد مبايعةِ الكويتيين له إلى حينِ عَودةِ الشيخِ جابرٍ مِن البحرين."},{"id":4384,"title":"محمد علي يوجه عساكره لليمن فتهزمهم القوات السعودية في القنفذة .","date":["العام الهجري :1229","الشهر القمري : جمادى الأولى","العام الميلادي :1814"],"text":"بعث محمد على صاحب مصر عسكرًا كثيفًا ووجَّهه إلى ناحية اليمن، لَمَّا استقر بمكة وجدة، فأرسل تلك العساكر برًّا وبحرًا، فسَيَّرَ في البحر أكثَرَ من أربعين سفينة وبندروا عند القنفذة, وكان في القنفذة عسكر من عسير نحو 500 مقاتل، فحصرهم الروم (جيش محمد علي) ورموهم بالمدافِعِ والقنابر، فلم يزالوا محاصرين لهم حتى أخرجوهم بالأمان واستولوا على القنفذة، وكان أميرُ عسير وتهامة طامي بن شعيب قد سار بجميع الشوكة من رعيته وتوجه إلى الحجاز، فلما بلغه استيلاءُ قوات محمد علي على القنفذة حَرَف جيوشه إليهم وقصدهم فيها، ومعه أكثَرُ من ثمانية آلاف مقاتل، فنازلهم فيها ووقع قتال شديدٌ، فنصر الله طامي ومن معه وقتلوا منهم رجالًا كثيرة وأخذوا المحطةَ وما فيها، ومِن خَيلِهم نحو 500، وغنموا من الركابِ ما لا يبلغه العدُّ، والمتاع والسلاح والأزواد ما لا يبلغه العدُّ، حتى قيل إنَّ الخيام التي أخذوا تزيد على 1000 خيمة، وانهزم شريدُهم في السفن؛ وذلك أنهم لما انهزموا تركوا المحطةَ وجنبوها وتوجهوا إلى السفن وركبوها، ونزلوا عن الخيلِ وتركوها فغَنِمَها أهل عسير مع رحايلهم وخيامهم ووجدوا باشتهم في الخيام فقتلوه."},{"id":4385,"title":"وفاة الإمام سعود الكبير بن عبد العزيز بن محمد وتولي ابنه عبد الله .","date":["العام الهجري :1229","الشهر القمري : جمادى الأولى","العام الميلادي :1814"],"text":"هو الإمامُ قائِدُ الجنودِ سعود الكبير بن عبد العزيز بن محمد بن سعود ثالثُ حُكَّام الدولة السعودية الأولى، ولد بالدرعية سنة 1165هـ وتولى الحكمَ بعد وفاة والده سنة 1218هـ يعتبر عصر سعودٍ قِمَّةَ ازدهار الحكم السعودي في الدولة السعودية الأولى؛ فقد استطاع إخضاعَ الحجاز وعمان، وبلغ حوران من الشام. يصِفُ ابن بشر الإمامَ سعودًا وعهده بقوله: \"أَمِنَت البلاد وطابت قلوب العباد, وانتظمت مصالحُ المسلمين بحُسن مساعيه وانضبطت الحوادث بيُمْنِ مراعيه.., وكان متيقظًا بعيد الهمة، يسَّر الله له الهيبةَ عند الأعداء والحِشمةَ في قلوب الرعايا ما لم يره أحد في وقته, وكانت له المعرفةُ التامة في تفسير القرآن، أخذ العلم عن الشيخ محمد بن عبد الوهاب.. وله معرفةٌ بالحديث والفقه وغير ذلك، بحيث إنه إذا كتب نصيحةً لبعض رعاياه من المسلمين ظهر عليه في حُسنِ نَظمِه ومضمونِ كلامِه عدمُ قصورٍ في الاطلاع على العلوم, وقد رأيتُ العجب في المنطوق والمفهوم.. فمن وقف على مراسلاتِه ونصائحه عرفَ بلاغتَه ووفورَ عِلمِه، وإذا تكلَّم في المحافل أو مجالِسِ التذكير بهر العقولَ مِمَّن لم يكن قد سَمِعه, وخال في نفسِه أنَّه لم يسمع مثله, وعليه الهيبةُ العظيمة التي ما سَمِعْنا بمثلها في الملوك السالفة. بحيث إنَّ ملوك الأقطار لا تتجاسَرُ مراجعة كلامه ولا ترمقُه ببصَرِها إجلالًا له وإعظامًا، وهو مع ذلك في الغاية من التواضع للمساكين وذوي الحاجة، وكثيرُ المداعبة والانبساط لخواصِّه وأصحابه, وكان ذا رأيٍ باهر وعقل وافر.. وكان ثبتًا شجاعًا في الحروب محبَّبًا إليه الجهاد في صِغَرِه وكبره، بحيث إنه لم يتخلَّفْ في جميع المغازي والحِجَج، ويغزو معه العلماء من أهل الدرعية.. وإخوانه وبنو عمه كلُّ واحد من هؤلاء بدولة عظيمة من الخيل والركاب والخيام والرجال وما يتبع ذلك من رحائِلِ الأمتاع والأزواد للضيفِ وغيره, وقام في الجهاد وبذَلَ الاجتهاد، وفتحَ أكثر البلدان في أيامِ أبيه وبعد موتِه، وأُعطي السعادةَ في مغازيه, ولا أعلَمُ أنه هُزِمَت له راية، بل نُصِر بالرعب في قلوب أعدائه، فإذا سمعوا بمغزاه ومعداه هرب كلٌّ منهم وترك أباه وأخاه وماله وما حواه\" وكان له مجلس علم في الدرعية بعد طلوع الشمسِ يَحضُرُه جمعٌ عظيم، بحيث لا يتخَلَّفُ إلا النادر من أهل الأعمال يجلسون حِلَقًا كُلُّ حلقة خلفها حلقةٌ، لا يحصيهم العَدُّ، فإذا اجتمع الناسُ خرج سعود من قَصرِه ويجلس بجانِبِه الشيخ عبد الله ابن الشيخ محمد بن عبد الوهاب، وهو الذي يقرأ عليه، ومن الكتب التي تُقرأ عليه في هذا المجلس تفسيرُ ابن جرير الطبري، وابن كثير, وله مجالِسُ أخرى يُقرأ فيها عليه رياضُ الصالحين، وصحيح البخاري. توفي الإمام سعود ليلة الاثنين 11 جمادى الأولى من هذه السنة, عن عمر 74 سنة، وكانت ولايته عشر سنين وتسعة أشهر وأيامًا، وكان موته بعِلَّةٍ وقعت أسفل بطنه أصابه منها حَصَر بول, وكان قد أنجب 12 ولدًا وانقرضت ذريَّتُه سنة 1265هـ, وتولَّى بعده ابنه عبد الله خلفًا له."},{"id":4386,"title":"كسوف الشمس  .","date":["العام الهجري :1229","الشهر القمري : رجب","العام الميلادي :1814"],"text":"كسفت الشمسُ وقتَ الضحى كسوفًا لم يُعهَدْ مِثلُه، وانطمست بالكليةِ وأظلمت الأرضُ وطَلَعت النجومُ."},{"id":4387,"title":"الجيوش الحجازية والتهامية السعودية تهزم قوات محمد علي بوادي زهران .","date":["العام الهجري :1229","الشهر القمري : شوال","العام الميلادي :1814"],"text":"سار طامي بن شعيب برعاياه من عسير وألمع وغيرهم في نحو 20 ألف مقاتل، وكان الروم (قوات محمد علي) قد ساروا من مكَّةَ والطائف بعساكِرَ كثيرة نحو 20 ألفًا من الأتراك والمغاربة، فحاصروا بخروش وغلاس في أودية وادي زهران, وحصلت موقعةٌ بين الروم وقوات طامي بن شعيب قربَ حِصنِ بخروش، فاقتتلوا قتالًا شديدًا حتى انهزم الرومُ هزيمةً شنيعة، فغنم طامي خيامَهم ومحطتَهم وزهبتَهم وأزوادهم وبغالهم، وقُتِل من الرومِ مقتلةٌ عظيمةٌ أكثر من ألف رجل، ولم يسلمْ منهم إلَّا من هرب على الخيل."},{"id":4388,"title":"حجُّ حاجِّ الشام ومصر .","date":["العام الهجري :1229","الشهر القمري : ذي الحجة","العام الميلادي :1814"],"text":"حجَّ هذا العامَ حاجُّ الشام ومصر، ولَمَّا انصرفوا من الحَجِّ أبقوا مع محمد علي في مكَّةَ رحايل وذخائر وأموالًا أتوا بها إليه من جهةِ الروم (الترك)"},{"id":4389,"title":"عودة محمد علي إلى مصر .","date":["العام الهجري :1230","العام الميلادي :1814"],"text":"بعد أن حقَّق محمد علي باشا عدةَ انتصارات في الحملةِ التي قادها بنفسِه لدعم جهودِ ابنِه طوسون في العمَلِ على إسقاط الدولة السعودية، اضطر أن يغادِرَ إلى مصر للقضاء على حركة تمرد استهدفت حكمه، فعيَّن حسين باشا الأرنؤطي واليًا على مكة، وأقام ابنَه أحمد طوسون قائدًا على القوات العسكرية في الحجاز, وبعد قضاء محمد علي على حركةِ التمَرُّدِ في مصر استأنف حربَه ضِدَّ السعوديين، فأرسل إليهم حملةً عسكرية أخرى بقيادة ابنِه إبراهيم باشا."},{"id":4390,"title":"وفاة الأمير طامي بن شعيب المتحمي أمير عسير وألمع .","date":["العام الهجري :1230","العام الميلادي :1814"],"text":"هو الأميرُ طامي بن شعيب المتحمي، أحدُ أشهر أمراء عسير في الدولة السعودية الأولى، تولَّى إمارة الإقليم بعد وفاة ابنِ عمه عبد الوهاب بن عامر «أبو نقطة» المتحمي سنة 1224هـ. كان طامي ذا بِنيةٍ صحيحة وقوية، قصيرًا في بنائه ذا لحية طويلة بيضاء مهيبة، عيناه تقذفان شررًا، يمتاز بروحٍ سَمحة، ومهذَّب تجاه رئيس الأتراك؛ ولذا كان محمد علي بعد اعتقالِه غالبًا ما يتحدَّثُ معه معجبًا به. أبدى طامي نشاطًا كبيرًا لتوطيد الحكم السعودي في عسير والمخلاف السليماني, قاد طامي عملياتٍ عسكريةً ناجحة مكَّنتْه من الاستيلاء على اللحية، ثم الحديدة في اليمن؛ وهي أقصى نقطة وصل إليها الحكم السعودي في اليمن، ومع بداية الحملات العثمانية على الجزيرة العربية التي قادها  محمد علي باشا ضدَّ الدولة السعودية الأولى كان لطامي بن شعيب مواقِفُ بطولية، جعلت محمد علي يحسبُ له حسابًا، كان محمد علي قد ركَّز بعد احتلاله لتربة على التقدُّم جنوبًا، فاستولى على رنية، ثم بيشة، وتقدَّم إلى بلاد عسير لتتبع طامي، الذي احتمى في البداية ببلدتِه طبب في عسير، ثم غادرَها وتحصَّن بحصنٍ له في مسلية في وادي بيش، فأرسل محمد علي في طلبِه والبحث عنه، فأدركوه متوجهًا إلى حصن في تهامة فيه مالٌ وسلاح ومتاعٌ، فغدر به حسن بن خالد الحازمي أحَدُ الأشراف، فقبض على طامي, فقُبض عليه في نهاية المطاف، فأخذه محمد علي معه مكبَّلًا بالحديد إلى مصر، حيث أُركِبَ جملًا وطِيفَ به في شوارع القاهرة، ثم أُرسِلَ إلى الأستانة، وشُهِرَ به، ثم أُعدِمَ وصُلِبَ هناك."},{"id":4391,"title":"معركة بسل بين قوات محمد علي باشا والقوات السعودية  .","date":["العام الهجري :1230","الشهر القمري : محرم","العام الميلادي :1815"],"text":"جرت معركةٌ حاميةُ الوطيس في بلدةِ بسل الواقعة بين الطائفِ وتربة بين قواتِ محمد علي باشا والقوات السعودية بقيادة فيصل بن سعود, وذلك أنَّ فيصلَ بن سعود لَمَّا قدم إلى الحجاز ليتولى قيادةَ جموع المسلمين نزل تربة واستنفر رعايا دولتِهم في الحجازِ، فقَدِمَ طامي بن شعيب في أهل عسير وألمع وزهران وغامد في عشرين ألفًا، فلما أقبلوا على تربة وأرسلوا إلى فيصل يخبرونه بقدومِهم خرج فيصل من تربة ومعه عشرةُ آلاف مقاتل فاجتمعوا بالقربِ مِن بئر غزال قريب من تربة، ثم رحلوا منه إلى بسل حيث الرومُ (قوات محمد علي) قد اجتمعوا بعددِهم وعُدَّتهم، فنازلهم فيصل بجموعِه، ووقع بينهم قتالٌ وطِراد، وقُتلَ من الرومِ عددٌ كثير, ثمَّ في اليوم التالي قَدِم محمد علي بعساكِرَ كثيرة، ووقع قتال بين الفئتين، فثبت فيصل ومن معه ووقع كسرٌ في ناحية غامد وزهران، ثم في قوم طامي وغيرهم، واتصلت الكسرة على جموع المسلمين لا يلوي أحدٌ على أحد، ووقى الله شَرَّ القتل وكفَّ أيدي الروم عنهم وعن ساقتِهم, ولم يُقتَل إلا أقل القليل، وبعدها زحَفَت هذه القواتُ واحتلت تربة ورنية التي أصبحت فيما بعد معسكرًا عامًّا لقوات الروم, ثم رحل محمد علي إلى بيشة ونازل أكلب، وأطاعوا له، ثم سار إلى تبالة فضربها بالمدافِعِ والقنابر وقتلَ أمير الفزع و100 رجلٍ ممن معه."},{"id":4392,"title":"محمد علي يسير بعساكره إلى عسير وألمع ورفيدة .","date":["العام الهجري :1230","الشهر القمري : ربيع الآخر","العام الميلادي :1815"],"text":"سار محمد علي بعساكِرِه إلى بلد طامي عسير وألمع ورفيدة وغيرهم فأطاعت لهم رفيدة، وثبت طامي بن شعيب ومن معه من عسير وألمع وبني أحمر والأسمر، واستعَدُّوا لقتال محمد علي ومحاربته, ورتَّب طامي جموعَه ورعاياه، فجعل مع حوان عسكرًا عند الطلحة- وهي عدَّةُ قرى في بلاد ربيعة رفيدة- فزحف محمد علي على الطلحة فقاتله حوان وهزمه ثم تراجع الروم وثبتوا، ووقع في قوم حوان خيانةٌ وخِذلان فانهزموا واستولى الروم على عددٍ مِن الحصون."},{"id":4393,"title":"قتال بين طوسون وعبد الله بن سعود في القصيم .","date":["العام الهجري :1230","الشهر القمري : جمادى الأولى","العام الميلادي :1815"],"text":"بينما كان طوسون باشا قائد الروم (قوات جيش محمد علي) في الحجاز يجهِّزُ للهجوم على نجد؛ إذ وصله كتابٌ من أهل الرس والخبراء يعرضان عليه الطاعةَ, فأرسل إلى عسكَرِه في الحناكية بالسيرِ إلى القصيم ودخول الرس والخبراء، فدخلوهما واستوطنوهما واستولوا على ما فيهما من القصيرات والمزارع,, وثبت بقيةُ بلدان القصيم وحاربوا الروم, فلما علم بذلك عبد الله بن سعود استنفر أهلَ الجبل والقصيم ووادي الدواسر والأحساء وعمان وما بين ذلك من نواحي نجدٍ، فخرج من الدرعية واجتمع بمن معه بالمذنب، ثم رحلَ بمن اجتمع به إلى الرويضة بالقُربِ مِن الرسِّ، فخرج عليهم عساكِرُ الروم وحصل رميٌ بالمدافع من بعيد, وذُكِر لعبد الله أنَّ عسكرًا من الروم نازلون على ماء بالقرب من البصير،  فهجم عليهم وهم متحصنون في قصر، فقتلهم جميعًا ثم عاد عبد الله إلى عنيزة ودخلها وأخذ يرسِلُ السرايا على عساكر الروم، ونَدِمَ كثير من أهل الرس على طاعتِهم لطوسون، وانحاز عدةُ رجال منهم مع عبد الله، وظَلَّ عبد الله يصابِرُ الروم وتقَعُ بينهم مقاتلات ومجاولات من بعيدٍ إلى أن طلب الرومُ الصلحَ مع عبد الله."},{"id":4394,"title":"عقد صلح بين الإمام عبد الله بن سعود وطوسون باشا .","date":["العام الهجري :1230","الشهر القمري : شعبان","العام الميلادي :1815"],"text":"بعد مناوشاتٍ وقتال بين قوات طوسون باشا وقواتِ عبد الله بن سعود عُقِدَت معاهدة صلح بينهما أن تضع الحرب بين الفئتين وتُتركَ بموجِبِها نجدٌ وأعماله بقبضة عبد الله, وتدخُلُ الحجازُ تحت الإدارة المصرية، وتعهَّدَ عبدُ الله بأن يعتبر نفسَه تابعًا للسلطان التركي، ووعد بالخضوعِ للوالي المصري في المدينة، وتعهَّد بتأمين سلامة الحج، والذَّهابِ إلى استانبول والمثول أمام السُّلطانِ في حال تم استدعاؤه، وإعادة كنوزِ مكة, وكتبوا بذلك سجلًّا، ثم رحل الروم من الرسِّ أول شعبان متوجهين إلى المدينة, فوضع طوسون حامياتٍ في مدن الحجاز الرئيسية وعاد إلى مصر مُنهيًا المرحلة الأولى من الحربِ على الدولة السعودية الأولى بهذا الصلحِ الذي لم يوافِقْ عليه والِدُه محمد علي ولم يقِرَّه، قال الجبرتي في تاريخه: \"وصلت الهجانةُ وأخبار ومكاتبات من الديار الحجازية بوقوعِ الصلح بين طوسون باشا وعبد الله بن سعود الذي تولَّى بعد موت أبيه كبيرًا على الوهَّابية وأنَّ عبد الله المذكور ترك الحروبَ والقتال وأذعن للطاعة، وحَقَن الدماءَ وحَضَر من جماعة الوهَّابية نحو العشرين نفرًا من الأنفار إلى طوسون باشا ووصل منهم اثنان إلى مصرَ، فكأن الباشا محمد علي لم يعجبه هذا الصلحُ ولم يظهر عليه علامات الرضا بذلك، ولم يحسِنْ نُزُلَ الواصلين، ولما اجتمعا به وخاطبهما عاتبهما على المخالفة فاعتذرا وذكَرَا أنَّ الأميرَ سعودًا المتوفى كان فيه عنادٌ وحِدَّةُ مزاجٍ، وكان يريد المُلكَ وإقامة الدين، وأمَّا ابنه الأمير عبد الله فإنه ليِّنُ الجانب والعريكة ويكرهُ سَفكَ الدماء على طريقةِ سَلَفِه الأمير عبد العزيز- لعله يقصد الأمير سعودًا- فإنه كان مسالِمًا للدولة حتى إنَّ المرحوم الوزير يوسف باشا حين كان بالمدينة كان بينه وبينه- عبد الله- غاية الصداقة ولم يقَعْ بينهما منازعة ولا مخالفةٌ في شيءٍ ولم يحصُل التفاقُمُ والخلافُ إلا في أيام الأمير سعود، ومعظم الأمر للشريف غالب بخلاف الأمير عبد الله؛ فإنه أحسَنَ السَّيرَ وترك الخلاف وأمَّنَ الطرُقَ والسُّبُلَ للحجَّاج والمسافرين، ونحو ذلك من الكلمات والعبارات المستحسنات، وانقضى المجلس وانصرفا إلى المحلِّ الذي أُمِرا بالنزول فيه ومعهما بعض التركِ ملازمون لصحبتِهما مع اتِّباعهما في الركوب والذَّهاب والإياب؛ فإنه أطلقَ لهما الإذنَ إلى أيِّ محل أراداه، فكانا يركبان ويمران بالشوارع بأتباعِهما ومن يصحبُهما ويتفرجان على البلدة وأهلِها، ودخلا إلى الجامع الأزهر في وقتٍ لم يكن به أحدٌ من المتصدِّرين للإقراء والتدريس، وسألوا عن أهل مذهب الإمام أحمد بن حنبل رضى الله عنه وعن الكتُبِ الفقهية المصنَّفة في مذهبِه، فقيل انقرضوا من أرضِ مِصرَ بالكليَّةِ، واشتريَا نُسَخًا من كتب التفسير والحديث مثل الخازن والكشَّاف والبغوي والكتب الستة المجمَعِ على صحتها وغير ذلك، وقد اجتمعتُ بهما مرَّتين فوجدتُ منهما أنسًا وطلاقةَ لسانٍ واطِّلاعًا وتضلُّعًا ومعرفةً بالأخبارِ والنوادر، ولهما من التواضع وتهذيب الأخلاق وحُسن الأدب في الخطاب والتفقُّه في الدين واستحضار الفروع الفقهية واختلاف المذاهب فيها ما يفوق الوصفَ\"."},{"id":4395,"title":"عبد الله بن سعود يؤدب أهل الخبراء والبكيرية .","date":["العام الهجري :1231","العام الميلادي :1815"],"text":"سار عبدُ الله بن سعود بجموعِه قاصِدًا القصيمَ ونزل على الخبراء وهَدَّم سورَها وسورَ بلد البكيرية عقوبةً لهم عمَّا تقدَّمَ منهم من استدعائِهم الروم (جيش طوسون) وإدخالهم, وخوفًا أن يُحدِثوا مثلها فيما بعد, وأخذ معه ثلاثةً من رؤساء الرس."},{"id":4396,"title":"الحملة المصرية الثالثة بقيادة إبراهيم باشا على نجد .","date":["العام الهجري :1231","العام الميلادي :1815"],"text":"جهَّز محمد علي باشا صاحِبُ مِصرَ العساكِرَ الكثيفةَ مِن مصر والروم والشام والعراق إلى نجدٍ مع ابنه إبراهيم باشا، فسار إلى المدينة وضبط نواحيَها، ثم سار إلى الحناكية وأقام فيها، وأكثَرَ الغاراتِ على ما حولها من العُربان، وأخذ أموالًا وقتل رجالًا، فاجتمع عليه كثير من تلك النواحي من حرب ومطير وغيرهم وعتيبة ومن عنزة الدهامشة"},{"id":4397,"title":"وفاة الشريف غالب بن مساعد أمير مكة .","date":["العام الهجري :1231","الشهر القمري : رمضان","العام الميلادي :1816"],"text":"هو الشريفُ غالبُ بن مساعد بن سعيد بن سعد بن زيد بن محسن بن حسين بن حسن بن أبي نُمي، شريفُ مكَّةَ، تولَّى الإمارةَ في مكة بعد أخيه الشريف سرور بن مساعد منذ سنة 1202هـ حتى نَفْيه سنة 1228هـ.  نشأ الشريفُ غالب في كنف والده ملازمًا له مشاركًا معه في حروب, وبعد موت الشريفِ سرور بن مساعد في رجب سنة 1202 قام مقامَه أخوه عبد المعين، ثمَّ رغب عن الأمرِ لأخيه غالب بعد أيام يسيرة من ولايتِه، وكان غالبٌ في سِنِّ الشباب، فكان له قتالٌ عظيم مع صاحبِ نجدٍ الإمام عبد العزيز بن سعود، ثم ابنه سعود، ولَمَّا فتح سعود مكَّةَ صارت بينهما صحبةٌ وودٌّ، فكان غالبٌ يتردد على سعود إذا كان في مكَّةَ يدخل عليه في كلِّ حين كأنَّه أحد أمرائه ويتبادلان الهدايا, وبقيَ أميرًا لمكة إلى أن نفاه محمد علي إلى مصرَ، ثمَّ منها نُفِي إلى سلانيك وتوفي فيها بعد أن حكم مكة 26 سنة منها 19 سنة تابعًا للعثمانيين و7 سنين أميرًا للإمام سعود بن عبد العزيز, وكان لغالبٍ من الأبناء يحيى وحسين وعبد الله وعلي وعبد المطلب."},{"id":4398,"title":"وفاة أحمد طوسون بن محمد علي باشا .","date":["العام الهجري :1231","الشهر القمري : شوال","العام الميلادي :1816"],"text":"هو أحمد طوسون بن محمد علي باشا المعروف بـ\"طوسون باشا\" الابن الأكبر لمحمد علي باشا والي مصر، وُلِدَ سنة 1208هـ، قاد الحملة الأولى جهةَ نجدٍ ضِدَّ الدولة السعودية الأولى، وخاض فيها عدة معارك انتصر في بعضِها وهُزِم في البعض الآخرِ منها. أصيبَ بجراحٍ في معركة تربة التي هُزم فيها, فنُقِل إلى جُدَّة للعلاج, ثم نُقِل إلى مصر, ومات فيها متأثرًا بجراحِه عن عمر 33 سنة."},{"id":4399,"title":"وفاة الشيخ عثمان دان فوديو زعيم حركة الإصلاح الديني الأفريقي .","date":["العام الهجري :1232","العام الميلادي :1816"],"text":"هو الشيخُ أبو محمد عثمان بن محمد الملقب بـ (فودي) بن عثمان بن صالح بن هارون بن محمد أحدُ علماء نيجيريا، كان مالكيَّ المذهب. ولِدَ في قرية طقِل في شمال نيجيريا، سنة 1169هـ يعتبرُ عثمان دان فوديو مؤسِّسَ دولة تكرور في سوكوتو في غربِ أفريقيا قريبًا من نهر الكونغو، وكان قد عاد من الحجِّ وهو ممتلئٌ حماسةً للإصلاح الديني، فكَثُر أتباعُه والمتحمِّسون لأفكارِه، فلما زاد عددُ أتباعه ومريديه، وفكَّرَ في الاتصال بأحدِ الملوك ليشُدَّ مِن أزره، فلجأ إلى أقوى ملوكِ الهوسة- وهو وقتذاك- الملِكُ نافتا (ملك غوبر)، وشرح له الإسلامَ الصحيح وطلبَ إليه إحياءَ معالم الدين، وإقامةَ العدل بين الناس. فاستجاب له أوَّلَ الأمر وأسند إليه الفتوى والإرشادَ بمجلِسِه وديوانه، غيرَ أنَّ بعض مدَّعي العلمِ الحاقدين قاموا يعَيِّرونه لاتصاله بالمَلِك ويتَّهمونه بالرياء والسعي إلى الجاه والسلطان، ووشَوا به عنده، ومنهم من أنكر عليه بعضَ أقواله وأفعاله، فوقعت بينه وبين المَلِك جفوة سافر بسَبَبِها الشيخ إلى بلاد زمفرة وكبي. يقول الإمام محمد بللو ابن الشيخ عثمان بن فودي عن معاناة والده: \"ثم إنَّه لما برز هكذا، وكثُرَ أتباعه من العلماء والعوام، وتراسل الخلقُ إلى الاقتداء به، وكفاه اللهُ من ناوأه من علماءِ وَقتِه، حتى نشر أعلامَ الدين، وأحيا السنة الغرَّاء، فتمكَّنت في البلد أيَّ تمكين- نصَبَ أهل الدنيا له العداوةَ مِن أمراء هذه البلاد،..... وإنما غاظهم ما يرون من ظهورِ الدين وقيام ما درس مِن معالم اليقين، وذَهاب بقاءِ ما هم فيه من الضَّلالِ والباطِلِ والتخمين، مع أنَّ سَلطنتَهم.. مؤسَّسة على قواعِدَ مخُالِفة للشريعة.... فلمَّا أوضح الشيخُ الطريق، واهتدى إليه أهلُ التوفيق... وبقِيَ أهل الدنيا من علماءِ السوء والملوك في طغيانِهم يعمهون،... فجعل أولئك الملوك والعلماء يؤذون الجماعةَ (أتباعه)، ويعترضون كلَّ من ينتسب إلى الشيخ،... ولم يزَلْ كُلُّ من تولى من ملوكِ بلادنا مجتَهِدًا في إطفاءِ ذلك النور، ويكيد بالشيخِ وبجماعته، ويمكُرُ بهم ويحتال في استئصالهم\" استطاع الشيخ عثمان بالدعوة أن يوحِّدَ تلك الجماعات المتناثرة في شتى أقاليم الحوصة ويجعل منها جماعةً واحدةً مُتماسِكةً، فأصبح له جَيشٌ قوي، ثم تعرض لولايات الحوصة الإسلامية، فسقطت واحدة تلوَ الأخرى في يدِه، وكان قد قسَّم مملكتَه على ولديه، ومات في هذه السنة بعد أن أسَّس مملكةً كبيرة سُرعان ما هبَّ الإنجليز للتدخل فيها, ولفودي مؤلَّفات كثيرة تجاوزت 150 كتابًا. توفِّي في ولاية سقطو (سوكوتو) بنيجيريا."},{"id":4400,"title":"تولي داود باشا ولاية بغداد وإسقاطه منها بعد ذلك .","date":["العام الهجري :1232","العام الميلادي :1816"],"text":"تولَّى داود باشا العثماني الولايةَ على بغداد، وكان معروفًا بقوته، فرفض ما وصل إليه المقيمُ البريطاني جيمس من المكانة؛ حيث كان الرجُلَ الثاني في صلاحياتِه بعد الوالي فأعلن: \"أنَّ حكومة بغداد لا تعترف بأيةِ حقوق أوربية\"، ومِمَّا قام به بناءُ جامع الحيدر خانة، وجامِعِ الأزبك، والمدرسة الداودية, فلم يَرُق للبريطانيين ولا للصفويين هذه القوَّة التي يتمتَّع بها داود باشا، فبدؤوا بالضغط على السلطةِ المركزية في استانبول؛ مِمَّا أضعف داود باشا ليعودَ النفوذُ البريطاني كما كان، بل تمكَّنوا من إسقاطه ليزدادَ بذلك نفوذُهم."},{"id":4401,"title":"استسلام عنيزة لإبراهيم باشا .","date":["العام الهجري :1232","العام الميلادي :1816"],"text":"لَمَّا استقر صُلحُ أهلِ الرسِّ مع إبراهيم باشا، رحل منها بعساكره إلى الخبراء، فلما نزلها دبَّ الرعب في قلوبِ جيش عبد الله وتفرَّقت البوادي، فرتَّب عبد الله المرابِطةَ في عنيزة، واستعمل محمد بن حسن بن مشاري بن سعود أميرًا عليها، ثم رحل هو إلى بريدة, ثم رحل إبراهيم باشا وعسكره من الخبراء إلى عنيزة ونازل أهلها، فسلَّمَت له وأطاعوا له، وامتنع أهل قصر الصفا فجر عليهم الباشا القبوسَ والقنابر ورماهم بها رميًا هائلًا يومًا وليلةً حتى حدثت ثلمةٌ في جدار القصر، ثم انهدَّ ما حوله بفعل المدافع, فلما رأى مَن في القصر أنَّ أهل البلد قد أطاعوه، وأن سور القصرِ هُدِم عليهم، طَلَبوا المصالحة من الباشا على دمائِهم وأموالهم وسلاحِهم، فخرجوا من القصرِ ودخله الرومُ، ورحل المرابِطة إلى أوطانهم، فلما بلغ عبد الله وهو في بريدة رحل منها وقصد الدرعيةَ وأذِنَ لأهل النواحي أن يرجِعوا إلى أوطانهم."},{"id":4402,"title":"عبد الله بن سعود يجمع جيوشه لمواجهة الحملة المصرية بقيادة إبراهيم باشا .","date":["العام الهجري :1232","الشهر القمري : جمادى الأولى","العام الميلادي :1817"],"text":"أمر عبد الله بن سعود بعضَ النواحي من أهل الوشم وسدير أن يتجهَّزوا بشوكتهم إلى القصيم، ثم أمر شوكةَ أهل القصيم أن تجتَمِعَ تحت رئاسة أمير القصيم حجيلان بن حمد, ثم تجهَّز عبد الله غازيًا من الدرعية واستنفر جميعَ القوات التابعة لها من الحاضرة والبادية، وخرج من الدرعية لعشرٍ بقين من جمادى الأولى، وقصد ناحيةَ الحجاز ونزل قربَ الرس واستلحق الشوكةَ التي مع حجيلان، وسار حتى نزل العلم- الماء المعروف- وهو يريدُ الغارة على البوادي الذين مع الباشا إبراهيم، فبلغهم خبَرُه فرحلوا إلى الحناكية ونزلوا على إبراهيم باشا."},{"id":4403,"title":"هزيمة الإمام عبد الله بن سعود أمام قوات إبراهيم باشا .","date":["العام الهجري :1232","الشهر القمري : جمادى الآخرة","العام الميلادي :1817"],"text":"في منتصف جمادى الآخرة حمل عبدُ الله بن سعود وقواته على قواتِ إبراهيم باشا حتى قربوا من محطة العسكر, فثوَّرَ الروم مدافعَهم فخَفَّ بعض البوادي مع عبد الله ومَن نزلوا قرب جبل ماوية قبالةَ الروم، فثبت الرومُ بواديهم لَمَّا رأوه نزل فوجه مدافِعَهم إلى المسلمين ورموهم فأثَّرت فيهم، فأمر عبد الله على بعض المسلمين أن يرحَلوا وينزلوا الماء، فلما هموا بالرحيل خفَّت البوادي فتتابعت فيهم الهزيمةُ ووقع الرعبُ في قلوبهم فاتَّصلت الهزيمة في جموع قوات عبد الله، واختلطت الجموعُ بَعضُها في بعضٍ وتَبِعَهم الروم والبوادي وقتلوا رجالًا وأخذوا كثيرًا من السلاح وغيره، سقط في الأرض من أهل الركائب وركب عبد الله في كتيبةٍ مِن الخيل وحمى ساقة قواتِه، وهلك في تلك الهزيمة بين القتل والأسر والظمأ نحو 200 رجل، وهذا أول وهَنٍ في الدولة السعودية الأولى."},{"id":4404,"title":"حصار إبراهيم باشا لمدينة الرس ومصالحة أهلها له .","date":["العام الهجري :1232","الشهر القمري : شعبان","العام الميلادي :1817"],"text":"لَمَّا صارت الهزيمةُ على عبد الله بن سعود في جمادى الآخرة رحل بالقُربِ من جَبَل ماوية ونزل إبراهيمُ باشا وقواته الرسَّ، فثبت له أهلُ الرس وحاربوه، وأرسل عبد الله للرس مرابِطةً مع حسن بن مزروع، والهزاني صاحب حريق نعام، فحاصرهم الرومُ أشَدَّ الحصار وتابعوا الحربَ عليهم في الليل والنهار، وكُلَّ يوم يسوقُ الباشا على سورِها صناديدَ الروم بعدما يجعل السورَ بالقبوس فوق الأرضِ مهدومًا، ومع ذلك ثبت أهلُ الرس والمرابطة، وقاتلوا قتالَ مَن حمى الأهل والعيال، وصبروا صبرًا عظيمًا، فكلما هَدَم الرومُ السورَ بالنهار بنوه بالليل، وكلَّما حفروا حُفَرًا للبارود حفَرَ أهل الرس تجاهَه حتى يبطلوه، وبعض الأحيان يثور عليهم وهم لا يعلمون، وطال الحصار إلى ذي الحجة، وذُكر أنَّ الروم رموه في ليلةٍ 5000 رمية بالمدافع والقنبر والقبس، وأهلكوا ما خلفَ القلعة من النخيل وغيرها، وعبدُ الله بن سعود وجنوده في عنيزة، فأرسل أهل الرس إليه إمَّا أن يرحلَ إليهم لقتال الرومِ، وإمَّا أن يأذَنَ لهم بالمصالحةِ، ثم أقبل عساكِرُ وقبوس وأمداد من الروم كثيرة ونزلوا على إبراهيم ومن معه في الرس واستعظم أمرُه وكثرت دولتُه، فوقعت المصالحة بينه وبين أهلِ الرسِّ على دمائِهم وأموالِهم وسلاحِهم وبلادِهم وجميعِ مَن عندهم من المرابِطة يخرجون إلى مأمَنِهم بسلاحِهم وبجميع ما معهم، فخرجوا من الرس وقصدوا عبدَ الله وهو في عنيزة، وقتُل من أهل الرس والمرابطة نحو سبعين رجلا وقُتِلَ من عسكر الروم ما ينيف على 600 رجلٍ."},{"id":4405,"title":"أهل شقراء يحفرون خندقا لحماية بلدهم من إبراهيم باشا .","date":["العام الهجري :1232","الشهر القمري : ذي الحجة","العام الميلادي :1817"],"text":"أمر حمد بن يحيى أمير شقراء  وناحية الوشم على أهل بلد شقرا أن يحفِروا خندقَ بلَدِهم، وكانوا قد بدؤوا في حَفرِه وقتَ حملة طوسون، فلمَّا صارت المصالحةُ تركوه فقاموا في حَفرِه أشَدَّ القيام واستعانوا فيه بالنِّساءِ والولدان لحَملِ الماء والطعامِ، حتى جعلوه خندقًا عميقًا واسعًا وبَنَوا على شفيرِه جدارًا من جهة السورِ، ثم ألزمَهم كل رجل غني يشتري من الحنطةِ بعَدَدٍ معلومٍ من الريالات خوفًا أن يطول عليهم الحصارُ، فاشتروا من الطعام شيئًا كثيرًا، ثم أمر على النخيلِ التي تلي الخندقَ والقلعة أن تُشذبَ عسبانها ولا يبقى إلا خوافيها، ففعلوا ذلك وهم كارهون، وذلك لأنَّ أهل هذه البلد هم المشارُ إليهم في نجد، والمشهورون بالمساعدة للشيخ والإمامِ عبد العزيز ومَن بَعدَهم، وكثيرًا ما يلهجُ بهم الباشا إبراهيم في مجالِسِه بذكرِهم، فخاف الأمير حمد على بلدِهم من الروم، فألزمهم ذلك فكانت العاقبةُ أنَّ اللهَ سَلَّم بلادهم من الروم بسَبَبِ الخندق، وحَمِدوا الله على ذلك، وصالحهم الباشا على ما يريدون، وصاحِبُ الطعام الذي اشتراه على عشرةِ آصُع باع خمسة، وسَلِمت النخيل المشذوبة من القَطعِ في الحربِ دون غيرها؛ لأنها ما تستُرُ عن الرصاص."},{"id":4406,"title":"السنغال تصبح مستعمرة فرنسية خالصة .","date":["العام الهجري :1233","العام الميلادي :1817"],"text":"بدأ الفرنسيون يتردَّدون على شواطئ السنغال قديمًا ويُنشِئون مراكِزَ إقامة لهم، وأسَّسوا مستعمرة لهم عند مصَبِّ نهر صنهاجة (نهر السنغال حاليًّا) وأقاموا حِصنَ سان لويس، ثم طردوا البرتغاليين من ممتلكاتِهم جنوبَ الرأس الأخضر ونازع الإنجليزُ الفرنسيين على المنطقةِ، فقد احتلُّوا المستعمرة الفرنسية سان لويس عام 1172هـ، ثم عادت السنغال إلى فرنسا بموجِبِ معاهدة 1198هـ، ولكِنَّ الإنجليز أعادوا الكَرَّةَ واحتلُّوا المنطقة غيرَ أن معاهدة باريس أعادت منطقةَ السنغال إلى فرنسا، ومنذ ذلك الوقتِ انتهى كلُّ تدخُّلٍ أوربي في أمورِ المستعمرة عدا فرنسا، وأصبح فيها حاكِمٌ عسكريٌّ فرنسيٌّ، وتم الاتفاقُ بين الإنجليز والفرنسيين على الحدودِ بين غامبيا والسنغال."},{"id":4407,"title":"انتصار الشريف حمود أبي مسمار على قوات محمد علي باشا .","date":["العام الهجري :1233","العام الميلادي :1817"],"text":"لما وصلت جيوشُ الروم بقيادة سنان أغا ومعه عددٌ مِن أهل الحجاز وتهامة عسير، استنجد محمد بن أحمد وقومُه من عسير بحمود أبي مسمار أميرِ العريش، فتولى أبو مسمار قيادةَ جموع قوات عسير ووقَعَت الملاقاة بينهم وبين الروم في حجيلا من نواحي عسير، وكثُرَ القتلى بين الفريقين فانهزم الرومُ وفَرَّ سنان إلى القنفذة."},{"id":4408,"title":"إلغاء الدولة العثمانية الإنكشارية في الجزائر .","date":["العام الهجري :1233","الشهر القمري : محرم","العام الميلادي :1817"],"text":"أقدمت الدولةُ العثمانيةُ على إلغاء حامية الانكشارية في الجزائر، وكان في هذه الحامية حوالي 34 ألفَ انكشاريٍّ. وكانت فِرَق الانكشاريَّة من أكثَرِ الفِرَقِ انضباطًا وقتالًا في الجَيشِ العثماني، لكِنْ تورُّط قادتِها في السياسةِ بعد ذلك أثَّرَ على مستواهم العسكريِّ؛ ممَّا أدى إلى إلغائِها."},{"id":4409,"title":"وفاة الشريف حمود أبو مسمار أمير العريش\n  .","date":["العام الهجري :1233","الشهر القمري : ربيع الأول","العام الميلادي :1818"],"text":"هو الأميرُ الشريف حمود بن محمد بن أحمد الحسني التهامي، ويُعرَفُ بأبي مسمار أمير من أشراف تهامة اليمن، كانت ولادته عام 1170هـ في قرية الملاحة من بلاد بني مالك بالسراة، كانت له ولأسلافه ولايةُ المخلاف السليماني من تهامة ودعوتهم لأئمة صنعاء. في سنة 1210 ثار حمود على ابن عمه علي بن حيدر، فنزل له عن إمارة عريش واستقلَّ بولاية أبي عريش وصبيا وضمد والمخلاف السليماني. واختطَّ مدينة (الزهراء) وبنى قلاعًا وأسوارًا. وكان شجاعًا كريمًا محبًّا للعمران، فيه دهاءٌ وحَزمٌ. وهو أولُ من استقَلَّ بالمخلاف السليماني عن أئمَّةِ صنعاء. وفي أيامِه استولت جيوشُ نجد على البلاد المجاورة له، فقاتلهم، فهزموه فانضوى إلى لوائِهم فدان بالدَّعوةِ السلفية، فأزال ما كان من أثَرٍ للبِدَعِ والوسائِلِ الشركية في بلادِه، وأصبح أميرًا من أمراء الإمام عبد العزيز بن محمد، ثم لابنه سعود، وقد قام بعملياتِ فتحٍ لصالح دولة الدرعية، فاستولى على اللحية والحُديدة وزَبيد وما يليها. وقد هزم الأميرُ حمود أبو مسهار قواتِ محمد علي باشا التي يقودُها سنان أغا في عسير، ثم وافاه الأجلُ بعد انتصاره بعشرة أيام عن عمر ثلاث وستين سنة، وقد دفن في قرية الملاحة مسقِطَ رأسه في الظهرة المعروفة بظهرةِ حمود نسبةً إليه، وهي واقعة على ضفاف كضامة الملاحة."},{"id":4410,"title":"حصار إبراهيم باشا شقراء واستبسال أهلها في الدفاع عن بلدهم .","date":["العام الهجري :1233","الشهر القمري : ربيع الأول","العام الميلادي :1818"],"text":"ركب إبراهيم باشا من أشيقر بخيلِه وقصد بلد شقراء، فأتاها واستدار فيها، وقاسَها وعَرَف موضِعَ منزلِه ومنزل عسكرِه وقبوسيه؛ لأنه يعلم أنَّ أهلها محاربون أشداءُ وأهلُ صدق في الحرب مجرِّبون، وكان قد أتى إليه أمدادٌ من العساكر والقبوس، وصار في قوَّةٍ عظيمة، فنزل أسفلَ البلد وشمالَه، فخرج إليه أهلُها فساق الباشا عليهم الرومَ، فوقع بينهم قتال شديد في وسطِ النخيل وخارجه، فقُتِل من الروم قتلى كثيرٌ وجُرح كثيرٌ منهم، فتكاثرت عليهم أفزاعُ الروم وجُرح الأمير حمد بن يحيى جرحًا شديدًا فدخلوا البلد واحتصروا فيها، ثم إنَّ الباشا جرَّ القبوس والقنابر والمدافع وجعلها فوقَ المرقب الجبل الشمالي، فرمى البلد فيه رميًا هائلًا أرهب ما حولَه من القرى والبلدان من أهل مدبر ومنيخ والمحمل وغيرهم، حتى سمعه من كان في العرمة ومجزل وما حوله. فلما احتصر أهلُ البلد فيها أنزل قبوسَه ومدافعه وقنابره من رأسِ الجبلِ وقَرَّبها من السور، وحَقَّق عليهم الحرب والرميَ المتتابع حتى قيل إنه رماها في ليلة واحدة بثلاثمائة حمل من الرصاص والبارود، وذُكِرَ أن رصاص القبوس والمدافع والقنابر والبنادق يتضارب بعضُها ببعض في الهواء فوق البلدِ وفي وسطها، ثم إنَّه هدم ما يليه من سورِها وقطع نخيلَها إلَّا قليلَها، هذا وأهل البلد ثابتون، وفي أكنافِها يقاتلون، فقرَّب الباشا القبوسَ من السور وهدَمَ ما يليه من الدُّورِ والقصور، فحماهم الله سبحانه وكفَّ أيديَ الروم عنهم؛ وذلك لصِدقِهم في مواطِنِ اللقاء بالسيف، فلما همَّ الروم بالحملة عليهم أثنى عزمَهم الخندقُ وما ذاقوه من شدة القتال أوَّلَ نزولِهم على شقراء، فصار الخندقُ من الأسباب لثباتِ أهلها لأنَّه لا يُرام، وفي كلِّ يوم وليلة والباشا يناديهم ويدعوهم إلى المصالحةِ ويأبون عليه، فلما كان يومُ الخميس وقَعَت المصالحة بين الباشا وبينهم؛ خرج إليه رجلان من رؤساء أهلِها فصالحوه على دمائِهم وأموالِهم وما احتوت عليه بلادُهم، وكان جميعُ بلدان الوشم أعطوه الطاعةَ لَمَّا نزل شقراء، فلما استقَرَّ الصلح بعث الباشا عساكِرَ من الترك رئيسُهم رشوان أغا إلى ناحية سدير ومنيخ، فنزل رشوان بلد جلاجل وفرَّق العساكر في البلدان وأخذوا ما فيها من الخيل الجِياد الثمينة وحنطة وعليقًا للخيل، وأقاموا عندهم إلى أن أراد الرحيلَ من بلد شقراء، فرحلوا من بلد سدير إلى الوشم، ولَمَّا كان بعد أيام من مصالحةِ أهل شقراء وشى بهم رجالٌ عند الباشا من أهل نجد ممن يساعده وسار معه وقال إنَّه ارتحل منهم عدَّةُ رجال من أعيانهم وعامَّتِهم إلى الدرعية، وأنَّهم يريدون أن ينقُضوا العهد بعدما ترتحل عنهم ويقطعوا سبلك، فأفزع ذلك الباشا وأهمه فدخل البلدَ مُغضَبًا بعددٍ كثير من عساكره، فلما دخل جعل العسكرَ في المسجد فأوقدوا فيه النيران، وذلك وقتَ الشتاء.ثم دخل الباشا بيت إبراهيم بن سدحان المعروف جنوبَ المسجِدِ، وأرسل إلى الأمير حمد وهو جريحٌ فجيء به بين رجلين، فتكلم الباشا عليه بكلامٍ غليظ.ثم أرسل إلى الشيخ عبد العزيز الحصين الناصري، وكان قد كَبِرَ وثقل فجيءَ به محمولًا فأكرَمَه وأعظمَه، فذكَرَ لهم ما حدث من أهل البلد.فعلوا وفعلوا وكان قصدُه أن يفتك بهم، فقال له الشيخ عبد العزيز الحصين: كل ما تقولُ صِدقٌ، ولكن العفو يا باشا. فقال: عَفَونا عَفَونا إكرامًا لمجيئك، فكفى الله سبحانه شَرَّه، وهدم سور البلد ودفَن خندَقَها، وأقام عليها نحوًا من شهر، ثم ارتحل منها بعساكِرِه، وأخذ معه عشرةَ رجال من رؤسائهم، وسار منها إلى بلد ضرم، وأتت إليه مُكاتبات أهل المحمل وحريملاء وأعطوه الطاعة."},{"id":4411,"title":"دخول إبراهيم باشا ضرما عنوة بعد أن ثبات أهلها في القتال .","date":["العام الهجري :1233","الشهر القمري : ربيع الآخر","العام الميلادي :1818"],"text":"كان عبدُ الله بن سعود لما صالح أهل شقراء وأطاع الرومَ جميعُ أهل الوشم وسدير والمحمل وغيرهم، أمر سعود بن عبد الله بن محمد بن سعود في عِدَّةِ رجال من أهل الدرعية ومتعب بن إبراهيم بن عيصان صاحب الخرج وعدة رجال معه ومحمد العميري في عدة رجال من أهل ثادق والمحمل- أمَرَ الجميعَ أن يسيروا إلى بلد ضرما ويدخلوها ليصيروا عونًا لأهلها ورِدءًا لهم، فساروا إليها ودخلوها، ثم إنَّ الباشا وعساكر الروم لَمَّا وصلوا قرب ضرما ركب عددٌ من خيلهم وطافوا على البلدِ وقاسوها وعرفوا منزلهم ونزل قبوسهم ومدافعهم وقنابرهم، ثم رجعوا إلى مخيَّمِهم، فلما كان صبيحة 14 من ربيع الثاني أقبل الباشا على البلد ونزل شرقيَّها قُربَ قصور المزاحمية بينها وبين البلد وحَطُّوا ثِقلَهم وخيامَهم ثم سارت العساكِرُ بالقبوس والمدافع والقنابر، ونزلوا بها شمالَ البلد قُربَ السور فثارت الحربُ بين الروم وبين أهلِها، وحَقَّق الباشا عليهم الرميَ المتتابع  وحاربهم حربًا لم يُرَ مثلُه وثبَّت الله أهل البلد فلم يعبؤوا به وطلب منهم المصالحةَ فأبوا عليه ولم يُعطوه الدنيَّةَ، وكانت هذه البلد ليس في تلك النواحي أقوى منها بعد الدرعية رجالًا وأموالًا وعددًا وعُدةً، فحشدت عليهم عساكر الروم والمدافع فلم يحصلوا على طائلٍ، ثم حشد الروم عليهم وقربوا القبوسَ من السور وحاربوها حربًا عظيمة هائلة، فرميت بين المغرب والعشاء بـ 5700 رمية بين قبس ومدفع وقنبرة، فهدموا ما والاهم من السور، فلما رأى الباشا صَبْرَهم وصِدقَ جِلادِهم، ساق الروم عليهم وأهل البلد فيه ثابتون، فحمل عليهم الروم حملة واحدة فثبتوا لهم وجالدوهم جِلادَ صِدقٍ وقتلوا منهم نحو 600 رجل، وردوهم إلى باشتِهم وبَنَوا بعض ما انهدم من السور، فنقل الباشا بعض القبوس إلى جنوب البلد فتتابع الرميُ من الجهتين وأهل البلد والمرابطة قبالتَهم عند السور المهدوم، فلم يفجأهم إلا الصارِخُ من خلفهم أن الروم خلفَكم في أهلِكم وأولادكم وأموالكم، فكَرُّوا راجعين والرومُ في أثرِهم، ودخل الروم البلد من كلِّ جهةٍ وأخذوها عَنوة وقتلوا أهلَها في الأسواق والسكك والبيوت، وكان أهلُ البلد قد جالدوهم في وسَطِ البلد إلى ارتفاع الشمس، وقتلوا من الروم قتلى كثيرين، ولكن خدعوهم بالأمان، فيأتون إلى أهلِ البيت والعصابة المجتمعة فيقولون: أمان أمان، ويأخذون سلاحهم ثم يقتلونهم، ونهبوا جميع ما احتوت عليه البلد من الأموال والسلاح والمتاع والمواشي والخيل، واحتصر سعودُ بن عبد الله في قصر من القصور ومعه أكثر من 100 رجل من أهل الدرعيَّةِ وغيرهم، فأرسل إليهم الباشا وأعطاهم الأمان، فخرجوا وساروا إلى الدرعية، وهرب رجالٌ من أهل البلد وغيرهم على وجوهِهم في البرية، فكانوا بين ناج ومقتولٍ، وخلت البلد من الرجال، وجمع الباشا النساء والأطفال وأرسلهم إلى الدرعية وهم نحو 3000 نفس، والذي قُتِل من أهل ضرما في هذه الواقعة 800 رجل، ومن المرابطة 50 رجلًا."},{"id":4412,"title":"حصار إبراهيم باشا للدرعية واستبسال أهلها في الدفاع عنها .","date":["العام الهجري :1233","الشهر القمري : جمادى الأولى","العام الميلادي :1818"],"text":"عندما نزل إبراهيم باشا على الدرعية رتَّبَ قبوسَه ومدافِعَه وقنابره على جهاتِ الدرعية الأربعة، وكان عبد الله بن سعود قد رتَّب جموع أهل الدرعية ومن كان عنده من أهل الآفاقِ مقابِلَ قوات الباشا، ومن أبرز القادة الذين كانوا مع عبد الله إخوانُه فيصل وإبراهيم وفهد، وتركي الهزاني صاحب حريق نعام، وعبد الله ابن القاضي أحمد العريني رئيس سدير، ومحمد العميري رئيس المحمل، تولى هؤلاء قيادةَ الجبهات، ومعهم المدافع والمتاريس، وفي كل برج من أبراج الجهات فيه رجالٌ من رؤساء أهلِها وأشياخهم وأثقالِهم الذين ليس لهم شِدَّةٌ في الحرب، وإنما عليهم حِفظُ نواحيهم, فلما نزل الباشا وفَرَّق عساكره تجاه جموعِ أهل الدرعية وقعت الحربُ بينهم واضطرمت نارُها وطار في السماء شَرُّها وشرارها، فتخاللت بينهم القنابرُ والقبوس والمدافع، وصار مطرها فوق تلك الجموعِ متتابعًا فاشتدَّ القتال وتصادم الأبطال، والحرب بين الروم وبين أهل الدرعية سجالٌ، واستمرَّت الحربُ والحصار ستة أشهر، أظهر فيها أهلُ الدرعية ضروبًا من البطولة والتضحية، وشهدت الحربُ عددًا من المعارك والوقائع بين الطرفين، مثل وقعة المغيصيبي، والحريقة، ووقعة غبيراء، ووقعة سمحة، كما حصلت مقتلة عظيمة بين الفريقين عند السليماني النخل المعروف في الدرعية, ووقعة البليدة، ووقعة شعيب قليقل، ووقعة كتلة الشعيب, ووقعة الرفيعة، وفي أثناء الحرب اشتعلت النار في زهبة الباشا وما في خزائنِه من البارود والرصاص وجميع الجيخان، وكان لثورتها أمر هائل لا يكادُ يُوصَفُ، وسُمِعَ صوتها مسيرة ثلاثة أيام أو أربعة، وأهلكت خيلًا ورجالًا وأحرقت خيامًا وأزوادًا وأثاثًا، وهربت العساكرُ في رؤوس الجبال، ووقع في قلوبِهم الرعبُ، وكان لهذه الحادثة وهَنٌ عظيمٌ على الروم، وهمَّ أهلُ الدرعية أن يحملوا عليهم ويدهموهم فيه، فلم يفعلوا وكان أمرُ الله قدرًا مقدورًا، فتراجع الرومُ وثبتوا، ثم أرسل الباشا إلى جميع نواحي نجد، وأخذوا من كل بلدٍ ما فيها من خزانة الجبخان وتتابع عليه بعد ذلك الجبخان والعساكر من مصر، وأتت إليه الرجال والقوافل، وهو في الدرعية من البصرة والزبير مع أهل نجد الذين فيهما ممن كان أجلاهم سعود عن نجد وأخذوا أموالهم. فتتابع عليه القوافِلُ من الأرز والحنطة والتنباك وجميع حاجات العساكر، وسارت إليه القوافِلُ أيضًا من جميع نواحي نجدٍ بجميع ما ينوب العساكِرُ، فثبت الباشا في موضعه وتعاظم أمرُه وتزايد بالحرب على الدرعية، فحاربها حربًا عظيمًا وهم ثابتون، والخارج منها كلَّ ليلة من أهل النواحي ومن أهلها يبذل الباشا لهم الأمان، وقُتِل أثناء الحرب فيصل بن سعود بن عبد العزيز. يقول ابن بشر: \"كان الروم إذا قُتِل منهم ألف أتى بدَلَهم ألفان، وتتابع العساكِرُ من مصر على الدرعية في كل أسبوع وشهر يأتي من مصر عسكرٌ وقافلة من الطعام والأمتاع وما ينوب تلك العساكر، فلما طال الحصار وكثرت الأمداد من مصر على الروم، وأهل الدرعيةِ كُلَّ يوم يَنقُصون، وذلك بتقدير الحيِّ القيومِ، وإليه يُرجَعُ الأمر كلُّه، وما ربُّك بغافلٍ عمَّا يعملون، واستمروا في تلك المحاجي قريبَ ستة أشهر، وصار في تلك المدة وقعاتٌ عديدة لا يحيطُ بها العلم ولا يدرِكُها من أرادها القلم\" وبعد وقعة الرفيعة خرج من الدرعية رئيسُ الخيالة غصاب العتيبي وهو ممن يُظَنُّ به الصِّدقُ مع آل سعود والصبر معهم فأصاب أهلَ الدرعية كآبةٌ ووَهَنٌ من خروجه، فلما خرج قصد الباشا فقَوِيَ عزم الباشا على الحربِ، فقرب القبوس من البلد، وفي صبيحة ثالث ذي القعدة حَمَل الروم على الدرعية من جميع الجهات الأربع فاقتحموها ودخل الرومُ الدرعية وقاتلهم الناسُ مِن منازلهم واشتَدَّ القتال حول قصر غصيبة المشهور الذي بناه الإمام سعود بن عبد العزيز، كان قد تحصَّن فيه سعد بن عبد الله سعود مع عِدَّة رجال، فجَرَّ عليهم الباشا القُبوس والقنابر، فلما رأى عبد الله بن سعود البوارَ، انتقل إلى منزلِه في الطريف وترك مخيَّمَه وثِقلَه في موضعِه، فأقبل الباشا بقبوسه وقنابره ومدافعه ونزل إلى باب المنزل واشتَدَّت وطأة الروم عليهم، فحماهم الله وكَفُّوا عنهم فهَمُّوا بالمصالحة، فتأبى الباشا، فشَمَّرَ الشيخ عبد الله ابن الشيخ محمد بن عبد الوهاب وشَهَر سيفَه وندَبَ للقتال، فاجتمع عليه أهلُ البجيري ونهضوا على الرومِ مِن كل جانب كأنهم الأسودُ، فأخرجوا الروم وقتلوا منهم مئاتٍ، ثم أرسلوا إلى الباشا وطلبوا الصلحَ فأجاب إليه بعدما كان آبيًا، ولان بعدما كان قاسيًا. وقيل: قُتِل من عساكر الروم في هذا الحصار 10 آلاف مقاتِلٍ، ومِن أهل الدرعية ألفٌ وثلاثمائة مقاتل."},{"id":4413,"title":"سقوط الدرعية عاصمة الدولة السعودية الأولى .","date":["العام الهجري :1233","الشهر القمري : ذي القعدة","العام الميلادي :1818"],"text":"لَمَّا قبل إبراهيم باشا الصلحَ خرج له من أعيان الدرعية عبد الله بن عبد العزيز بن محمد، والشيخ العالم علي ابن الشيخ محمد بن عبد الوهاب، ومحمد بن مشاري بن معمر، فأرادوا منه أن يصالِحَهم على البلدِ كُلِّه فأبى أن يصالِحَهم إلا على السهلِ، أو يحضُرَ الإمام عبد الله بن سعود فرفضوا، فدخل الرومُ الدرعية ووقعت الحربُ عند مسجد الطريف أيامًا ثم انفَضَّ عن عبد الله بن سعود كثيرٌ ممن كان عنده،  فلما رأى عبد الله ذلك بذل نفسَه للروم وفدى بها عن النِّساء والولدان والأموال، فأرسل إلى الباشا وطلب المصالحةَ، فأمره أن يخرج إليه فخرج إليه وتصالحَ على أن يركَبَ إلى السلطانِ فيُحسِنَ إليه أو يسيءَ، وانعقد الصلحُ على ذلك، ودخل عبد الله منزله وأطاعت البلدُ كُلُّها، فسلّم عبد الله بن سعود نفسَه للباشا في 8 ذي القعدة بعد حصارٍ شديد للدرعية دام ستة أشهر، ثم أرسله إلى القاهرة، واقتاد إبراهيم باشا بعض أمراء آل سعود وأفرادًا من أسرة الشيخ محمد بن عبد الوهاب أسرى، وأرسلهم إلى مصر، ومن هناك أُرسِلَ عبد الله بن سعود إلى استانبول، حيث أُعدِمَ في صفر سنة 1234هـ, وبهذا انتهت الدولةُ السعودية الأولى التي امتَدَّ نفوذُها إلى معظم أنحاء الجزيرة العربية على مدى 77 سنة."},{"id":4414,"title":"أحوال نجد بعد سقوط الدرعية ونهاية الدولة السعودية الأولى .","date":["العام الهجري :1233","الشهر القمري : ذي القعدة","العام الميلادي :1818"],"text":"لما انهار حكمُ الدولة السعودية على يدِ إبراهيم باشا ودُمِّرَت الدرعية، كَثُر في نجد الاختلافُ والاضطراب ونَهْب الأموال وقَتْل الرجال، وتقدم أناسٌ وتأخَّر آخرون، يقول ابن بشر: \"قلتُ: وانحل فيها نظامُ الجماعة والسَّمع والطاعة، وعُدم الأمرُ بالمعروف والنهيُ عن المنكر، حتى لا يستطيعَ أحد أن ينهى عن منكرٍ أو يأمُرَ بطاعةٍ، وعُملَ بالمحرَّمات والمكروهات جهرًا، وليس للطاعاتِ ومَن عَمِلَ بها قَدْرٌ، وجُرَّ الرباب والغناء في المجالس وسُفت الذواري على المجامع والمدارس، وعُمرت المجالس بعد الأذان للصلاة، واندرس معرفةُ الأصول وأنواع العبادات، وسُلَّ سيف الفتنة بين الأنام، وصار الرجل في جوف بيته لا ينامُ، وتعذرت الأسفار بين البلدانِ، وتطاير شَرَرُ الفتن في الأوطان، وظهرت دعوى الجاهلية بين العبادِ، وتنادَوا بها على رؤوس الأشهادِ، فلم تزل هذه المحن على الناس متتابعةً حتى أتاح الله لها نورًا ساطعًا وسيفًا لمن أثار الفتن.. تركي بن عبد الله بن محمد بن سعود."},{"id":4415,"title":"نقض إبراهيم باشا شروط الصلح  واستباحته الدرعية وأهلها .","date":["العام الهجري :1234","العام الميلادي :1818"],"text":"بعد سفر الإمام عبد الله بن سعود إلى مصر ارتحل إبراهيم باشا بنفسِه وحاشيتِه وقبوسه وقنبره ومدافِعِه من سمحان، ولم يلتزم الباشا بشروطِ الصُّلحِ التي نصَّت على عدمِ المساس بالبَلدةِ وأهلِها بسوءٍ, فنزل إبراهيم باشا في نخل تركي بن سعود المعروفِ بالعويسية أسفلَ الدرعية، وباقي عساكِرِه فَرَّقَها في نخيلِها وأطرافِها ودروبِها، وكان إبراهيم باشا بعث عساكِرَ مِن حاشيته وخَدَمِه وفَرَّقَهم في نواحي نجدٍ وأمَرَهم بهدمِ أسوار البلدان وحُصونِها، فنزلوا البلدانَ وهَدَموا الحُصونَ والأسوارَ، وصادروا أهلَها بخَراجِهم وعلَف الخيل وعليقها بالليل والنهار، وجمعوا ما فيها من الحِنطةِ والشَّعيرِ إلَّا ما قَلَّ، ثمَّ إن الباشا أخذ خَيلَ آل سعودٍ وشَوكةَ الحَربِ وما وجد عليه اسمَهم في بندُقٍ أو سَيفٍ، وأكثَرَت العساكِرُ مِن العَبَثِ في أسواقِ الدِّرعية بالضَّربِ والتسخيرِ لأهلِها، فكانوا يجمَعون الرِّجالَ من الأسواق، ويُخرِجونَهم من الدُّورِ ويَحمِلون على ظُهورِهم ما تَحمِلُه الحيوانات، فيُسَخِّرونهم لهَدمِ البيوت والدكاكين، ويحمِلون خشَبَها ويَكسِرونَه ويَرِدونَ لهم الماءَ ويَحمِلونَه ولا يَعرِفونَ لفاضلٍ فَضْلَه ولا لعالمٍ قَدْرَه، وصار السَّاقِطُ الخَسيسُ في تلك الأيام هو الرَّئيسَ. أقام الباشا في الدرعية نحو تسعة أشهر بعد المصالحةِ، وأمَرَ جميعَ آل سعود وأبناء الشيخ محمد بن عبد الوهاب وأبنائهم أن يرحَلوا من الدرعية إلى مصرَ، فارتحلوا منها بنسائِهم وذراريِّهم، ولم يبقَ منهم إلا من اختفى أو هرب، مِثلُ تركي بن عبدالله بن محمد بن سعود، والشيخ علي بن حسين ابن الشيخ محمد بن عبد الوهاب، هربا إلى قطر  وعمان. ثم جاء الأمرُ من محمد علي باشا لابنه إبراهيم بهَدمِ الدرعية وتدميرِها، فأمر أهلَها أن يرحَلوا عنها ثمَّ أمر العسكرَ أن يهدموا دُورَها وقُصورَها ويَقطَعوا نَخْلَها وشجَرَها ولا يرحَموا صَغيرَها ولا كبيرَها، فابتدر العسكَرُ إلى هدمِها مُسرِعين، وهدموها وبَعضُ أهلِها فيها مقيمون، وأشعلوا النار في بيوتِها، وأخرجوا جميعَ من كان فيها من السكان، فتركوها خاليةً مِن السكان، وتفَرَّق أهلُها في النواحي والبلدانِ، فحسبنا الله ونعم الوكيل."},{"id":4416,"title":"عساكر إبراهيم باشا تسير للأحساء لنهب ما كان فيها لآل سعود .","date":["العام الهجري :1234","العام الميلادي :1818"],"text":"بعث الباشا إبراهيمُ عَسكرًا إلى الأحساءِ نحو مائتين وأربعين، مقَدَّمُهم محمد كاشف، فساروا إليه مع عبد الله بن عيسى بن مطلق صاحب الأحساء، وأمرهم الباشا بجَمعِ بيت المال وجميعِ ما كان لآل سعود في الأحساءِ، فقَدِموا وأخذوا أموالًا، وقتلوا رجالًا، وصادروا ما كان لآل سعود فيه وطوارفهم، وقُتِلَ رجالٌ مِن أئمة مساجد الأحساء مِن أهل نجد، وأمسكوا عبد الرحمن بن نامي وحبسوه وأخذوا أمواله وقتلوه، وهرب سيفُ بن سعدون رئيس السياسب من الأحساء، وهرب معه رجالٌ من أتباعه ومن الأعيان، ركبوا البحر، وخرج آلُ عريعر منه، ولم يبقَ لهم فيه أمرٌ ولا نهيٌ، وقصدوا الشمال بعرَباتِهم وبَقِيَت العساكِرُ في الأحساء وعاثوا فيه إلى قريبِ ارتحال الباشا من نجد."},{"id":4417,"title":"التطور العمراني في الدرعية .","date":["العام الهجري :1234","العام الميلادي :1818"],"text":"يقول ابن بشر: \"كانت هذه البلدةُ -الدِّرعية- أقوى البلادِ، وقوَّةُ أهلها وكثرةُ رجالهم وأموالهم لا يحصيه التَّعداد، فلو ذهبت أعددُ أحوالهم وإقبالَهم فيها وإدبارَهم في كتايب الخيل والنجايب العمانيات، وما يدخلُ على أهلها من أحمالِ الأموالِ مِن سائر الأجناس التي لهم مع المسافرينَ منهم، ومن أهل الأقطار- لم يسَعْه كتاب، ولرأيت العجَبَ العجاب، وكان الداخِلُ في موسمها لا يفقد أحدًا من أهل الآفاقِ مِن اليمن وتهامة والحجاز وعمان، والبحرين وبادية الشام والعراق، وأناس من حاضرتهم، إلى غير ذلك من أهل الآفاقِ ممن يطول عَدُّه، هذا داخِلٌ فيها وهذا خارجٌ منها، وهذا مستوطِنٌ فيها، وكانت الدورُ لا تُباعُ فيها إلا نادرًا، وأثمانُها سبعة آلاف ريال وخمسة آلاف، والداني بألف ريال، وأقل وأكثر، وكلُّ شيء يقدره على هذا التقدير من الصغير والكبير، وكروة الدكان الواحد بلغت في الشَّهرِ الواحد خمسةً وأربعين ريالًا، وكروة الدكان الواحد من سائر الدكاكين بريالٍ في اليوم، والنازل بنصفٍ، وذُكر لي: أن القافلة من الهدم -الملابس- إذا أتت إليها بلغَت كروة الدكان في اليوم الواحد أربعة أريُل، وأراد رجلٌ منهم أن يوسِّعَ بيته ويعمره فاشترى نخلاتٍ تحت هذا البيت يريدُ قطعها ويعمر موضِعَها، كل نخلة بأربعين ريالًا أو خمسين ريالًا، فقطع النخل وعمر البيت، ولكِنَّه وقع عليه الهدم قبل تمامِه، وذَكر لي من أثقُ به أن رجلًا من أهل الدرعية قال له: إني أردت ميزابًا في بيتي فاشتريتُ خشبة طولها ثلاثة أذرع بثلاثة أريُل، وأجرة نَجْره وبِناه ريال, وكان غلاء الحطب فيها والخشب إلى حدِّ الغاية، حتى قيل: إنَّ حملَ الحطب بلغَ خمسة أريل وستة، والذراع من الخشبة الغليظة بريال، وكل غالبِ بيوتها مقاصير، وقصور كأنَّ ساكنيها لم يكونوا من أبناء ساكني القبور، فإذا وقفْتَ في مكان مرتفع ونظرت موسمها وكثرة ما فيها من الخلائق وتزايلهم فيه وإقبالهم وإدبارهم، ثم سمعتُ رنَّتَهم فيه ونجناجهم فيه، إذا كأنه دويُّ السيل القوي إذا انصَبَّ من عالي جبل، فسبحان من لا يزولُ مُلكُه ولا يُضامُ سُلطانُه ولا يُرامُ عِزُّه {قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [آل عمران: 26] \""},{"id":4418,"title":"مقتل الإمام عبد الله بن سعود آخر حكام الدولة السعودية الأولى .","date":["العام الهجري :1234","الشهر القمري : صفر","العام الميلادي :1818"],"text":"هو الإمامُ عبد الله بن سعود بن عبد العزيز بن محمد بن سعود، آخِرُ أئمَّةِ الدولة السعودية الأولى، وآخِرُ حاكمٍ اتَّخَذ من الدرعية عاصمةً للدولة السعودية، وكان عبدُ الله بن سعود ذا سيرةٍ حسنةٍ مقيمًا للشرائع آمرًا بالمعروف ناهيًا عن المنكرِ كثيرَ الصَّمتِ حَسَن السَّمتِ، باذِلَ العطاء موقِّرًا للعلماء، وكان صالحَ التدبير في مغازيه، ثبت في مواطِنِ اللقاء وهو أثبَتُ مِن أبيه في مصابرةِ الأعداء، وكانت سيرتُه في مغازيه وفي الدرعية في مجالس الدروس، وفي قضاء حوائجِ الناس وغير ذلك على سيرةِ أبيه سعود. بعد أن تمَّت المصالحةُ بينه وبين إبراهيم باشا بيومين على أن يسَلِّمَ نفسَه مقابِلَ حَقنِ دماءِ أهل الدرعية أمر الباشا إبراهيمُ الإمامَ عبدَ الله بن سعود أن يتجهَّز للمسير إلى السلطانِ، ثم أمر رشوان أغا ومن معه من العساكِرِ والدويدار ومن معه من العسكر أن يتجهَّزوا للمسير معه، ورحل عبدُ الله من الدرعية وليس معه من قومِه إلَّا ثلاثة رجال أو أربعة، وقابل في مِصرَ محمد علي باشا، ثم بعد يومين سافر إلى استانبول، حيث قُتِل هناك في آيا صوفيا بعد وصولِه بقليلٍ، ولم يفِ السُّلطانُ بوعودِه، ورجع إبراهيمُ من الجزيرة في الحادي والعشرين من صفر من عام 1235هـ بعد أن استمَرَّ حُكمُه أربعَ سنوات, ثم إنَّ إبراهيم باشا لم يفِ بشروط الصُّلحِ التي أعطاها لعبد الله مقابِلَ استسلامِه، وسَفَّره للسلطان، فبعد سفر الإمام إلى مصر استمرَّ الباشا وجنودُه في الدرعية لتخريبِها، ففَرَّق قواتِه في نواحي الدرعية لهَدمِ الأسوارِ والحُصونِ ومصادرة الأرزاق، ثم إحراقها وتدميرِها وقطْع نخيلها قبل المغادرة، وبعد مغادرة الباشا الدرعية خلى الجو لمحمد بن مشاري بن معمر، وكان من أغنياء الدرعية، فاستولى على أكثر مناطِقِها، فقدم مشاري بن سعود فتولَّى الحكمَ في سنة 1235هـ ثمَّ بعد عدةِ أشهرٍ قَبَض عليه ابنُ معمر وسَلَّمه للعثمانيين فقَتَلوه، وعاد هو لحكم الدرعيةِ."},{"id":4419,"title":"تولي تركي بن عبد الله الحكم في نجد .","date":["العام الهجري :1235","العام الميلادي :1819"],"text":"جاء تركي بن عبد الله بن محمد بن سعود، فدخل الدرعيَّةَ وتخلَّصَ من ابن مَعمَر، وانتقل إلى الرياض وجعلها مقرًّا لحُكمِه، فقَدِمَت حملاتٌ عثمانية أجبرته على الخروجِ مِن الرياض، واتجه إلى الجنوب وظَلَّ في بلدة الحلوة ثلاثَ سَنَواتٍ يجمَعُ الأنصار."},{"id":4420,"title":"اندلاع الثورة اليونانية طلبًا للاستقلال وانتصار محمد علي باشا .","date":["العام الهجري :1235","العام الميلادي :1819"],"text":"فُتِن أهالي بعضِ البلاد التي دخلها العثمانيون بالتقَدُّم الذي تمَّ في أوربا فأرادوا السيرَ على منهجِهم، فبَدؤوا يُرسِلون أولادَهم إلى أوربا للتعَلُّمِ فيها، فأسَّس اليونانيون جمعياتٍ سريَّةً لهم في النمسا وروسيا وبدؤوا يعملون للانفصالِ عن العثمانيين؛ لاختِلافِ الروابط العَقَديَّة، وكانت مراكِزُ جمعية الأخوة أهمَّ هذه الجمعيات في فيينا عاصمة النمسا وفي أوديسا في روسيا على البحر الأسود، ثم انتقل إلى كييف، ثم كثُرَ أتباعُها، وما إن قضى خورشيد باشا على علي باشا والي يانينة، حتى أعلنوا العِصيانَ بتحريض من الروس بالدرجةِ الأولى، وفي مدة قليلةٍ- حوالي ثلاثة أسابيع- استطاع المتمَرِّدون خلالها السيطرةَ على المورةِ كُلِّها، باستثناء المقاومةِ الشديدة التي أبداها العثمانيون في قلعةِ (تريبوليجة)- وهي مركز ولاية المورة- وحيث استمَرَّت هذه المقاومة شُهورًا عديدةً. وقد قَتَل الرومُ- بوحشية منقطعة النظير- العُثمانيين الذين وقعوا في الأسرِ أثناء هذا التمرُّد، وسَلَبوا أموالهم. لعب بطريرك جريجوريوس دورًا كبيرًا في تمرُّدِ الروم ضِدَّ الحكم العثماني، وقد أعَدَّ خطة إقامة دولة اليونان الأرثوذكسية الكبرى، وأصدر السلطانُ محمود الثاني فرمانًا -أي حكم أو دستور موقع من السلطان- بعَزلِ البطريرك جريجوريوس من منصبِه، ثمَّ قتله، فكلف خورشيد باشا بإخضاعِهم، فسار إليهم فانتصروا عليه وشَتَّتوا جُندَه، وانتحر هو بالسمِّ، ثم كلف محمد علي باشا والي مصرَ بإخضاعِ اليونان، وكان قد انتهى من فتح السودان، فسارت جيوشُ محمد علي باشا بحرًا من الإسكندرية بقيادة ابنه إبراهيم ومستشاره الفرنسي، فاحتَلَّ جزيرة كريت، ثم انطلق إلى المورة التي كانت مركزَ الثورة، فأنزل إبراهيم جنودَه بصعوبة بالغة؛ حيث إن أوربا كلها كانت وراءَ هذه الثورة، فدعَمَتها بالمال والسلاح، بل وبالمتطوِّعين من الرجال المقاتلين، واستطاع إبراهيم باشا أن يحرِزَ النصر ويفتح مدينة نافارين عام 1240هـ وأن يدخُلَ العثمانيون إلى أثينا عام 1241هـ رغم دفاع الإنكليز البحري، ثم إنَّ الدول الأوربية تدخَّلت باسم حماية اليونان ظاهرًا وبحقدٍ صليبي واضحٍ؛ إذ كانت روسيا تدعَمُ اليونان علنًا، ورأت أنَّ الفرصة مناسبة جدًّا لدخول استانبول وإعادتها لعهدها السابق مركزًا للأرثوذكس، ووقفت إنكلترا بجانب روسيا، وعُقِد الصُّلح مع الدولة العثمانية في معاهدة آق كرمان في الثامن والعشرين من صفر من عام 1242هـ."},{"id":4421,"title":"خروج حملة بحرية كبرى من بومباي إلى رأس الخيمة .","date":["العام الهجري :1235","الشهر القمري : صفر","العام الميلادي :1819"],"text":"كانت ظروفُ السُّلطاتِ البريطانية في الهند مهيَّأةً أكثَرَ مِن أيِّ وقت سابقٍ للقيام بتدخُّلٍ عسكري واسعِ النطاقِ في الخليج العربيِّ وتأكيد سيطرتِها البحرية المؤدِّيةِ إلى المحيطِ الهنديِّ، وكان إيفان تبيان حاكِمُ بومباي في ذلك الوقتِ مِن أنصار التدخُّلِ العسكريِّ في الخليج العربي، فعُرِضت عليه مشروعات عِدَّة للتدخُّل، فاختار منها المشروعَ الذي يَعرِض إنشاءَ قاعدة بريطانية في رأسِ الخيمة والتدخُّل العسكري السياسي في الخليجِ، ومن ثَمَّ خرجت حملةٌ بحرية كبرى من بومباي في 16 محرم من هذه السنة، تألَّفَت من سِتِّ سُفُنٍ حربيةٍ كبرى بالإضافةِ إلى عدد من السفن الصغيرة، وقد وصَلَت إلى رأسِ الخيمة في 16 صفر من هذه السَّنةِ لإجبار شيوخِ ساحل الخليج (الساحل المهادن) وأمرائِه على الدخولِ في معاهداتِ الصُّلحِ البحريِّ، وكانت النتيجةُ الأساسيةُ التي حصلت من هذه الحملةِ هي دخولَ شيوخ الإمارات العربية الساحلية في معاهداتٍ مختَلِفةٍ جعَلَت لبريطانيا يدًا في شؤون جنوبي شرقي بلاد العرب."},{"id":4422,"title":"حملة محمد علي في السودان .","date":["العام الهجري :1235","الشهر القمري : جمادى الأولى","العام الميلادي :1820"],"text":"بعد الانتصاراتِ التي حَقَّقَها محمد علي في الجزيرةِ العربيةِ، والتي تمثَّلَت في إسقاطِ الدولة السعودية، قَوِيَ عَزمُه على الإغارة على نواحي السودان، فجهَّز ولدَه إسماعيلَ باشا على رأس حملة لغزو السودان عُرِفَت باسم الغزو التركي للسودان، فغالِبُ جنود الجيش من الأتراك والألبان والمغاربة ولم يشارِكْ في الحملةِ أحَدٌ من المصريين؛ لأنَّ محمد علي لم يبدأ بعدُ بتجنيد المصريين. جمع محمد علي لجيشِ هذه الحملة الذخيرةَ والسِّلاحَ مِن البلادِ القبلية والشرقية في مصر، وأرسل لإحضارِ مَشايخِ العُربان والقبائل، وقد قَدَّمَت قبيلةُ العبابدة للحَملةِ الدَّعمَ بالجمال، وأفراد هذه القبيلة يَعرِفون المناطِقَ الحدودية بشكلٍ جيِّد، ثم في ذي القعدة سافر إسماعيلُ باشا إلى جهة قبلي، وهو أمير العسكر المعيَّنة لبلاد النوبة، والباشا محمد علي في الإسكندرية. لم تواجِهْ حملة إسماعيل باشا أيُّ مقاومة في السودان حتى وصلت قواتُه إلى حدود مملكة الشايقية، حيث كانت أوَّل مقاومة للغزو التركي، والذين تمكن إسماعيل من هزيمتِهم في معركة كورتي، ثمَّ واصلت قواتُ محمد علي لفتحِ عَدَدٍ مِن أقاليم السودان، فوصلوا إلى أعالي نهر النيل، وفتحوا دارَ فور وكردفان، كما تمكَّن إسماعيلُ باشا من إخضاعِ دَولةِ سنار التي  خرجَ إليه سلطانُها السلطان بادي السادس مبايعًا له ومُعلنًا بذلك نهايةَ سلطنة سنار الإسلامية أعظَمِ الممالك الإسلامية التي ازدهرت في السودان"},{"id":4423,"title":"إنشاء محمد علي باشا أول مدرسة حربية في مصر .","date":["العام الهجري :1236","العام الميلادي :1820"],"text":"لما جاء الكولونيل سيف -سليمان الفرنساوي- إلى مصرَ، كضابط مع الحملة الفرنسيةِ ولَمَّا آنس منه محمد علي باشا الكفاءةَ لتحقيق مشروعه؛ أنفذه إلى أسوان ليؤسِّسَ مدرسة حربية تخرِّجُ ضباطًا على النمط الأوربي؛ ليكونوا النواةَ الأولى من جيشِ مِصرَ الحديث، وبدأ العمَلَ في هذه المدرسة بأن قَدَّم إليه خمسمائة من خاصَّةِ مماليكه ليدَرِّبَهم على أن يكونوا ضبَّاطًا في النظامِ الحديث، وطلب إلى بعضِ رجاله أن يحذُوا حَذْوَه ويُقدِّموا مَن عندهم من المماليك، فاجتمع لدى الكولونيل سيف ألفٌ من هؤلاء وأولئك، أخذ يدرِّبُهم مدةَ ثلاث سنوات على فنونِ الحرب وأساليبها الحديثة، فصاروا نواةَ الجيش النظامي؛ إذ تكوَّنت منهم الطائفةُ الأولى من الضباط، وقد لاقى \"الكولونيل سيف\" متاعِبَ جَمَّة خلال تدريب طلاب هذه المدرسة، خاصةً وأنهم لم يعتادُوا الطاعة المُطلَقة لرؤسائِهم, كما لم يتعوَّدوا أن يتعلموا فنونَ الحرب الحديثة، ولم يألَفوا من الحركاتِ العسكرية سوى الكَرِّ والفَرِّ، هذا بالإضافة إلى أن الكولونيل سيفًا ضابِطٌ أوروبي نصراني، ومن هنا جاشت في نفوسِهم فكرةُ العصيان والتمَرُّد، فحاول أحدُهم تدبير مؤامرة لاغتياله أثناء التدريبِ على ضربِ النَّارِ، فأطلق أحدُهم عليه رصاصةً أطاحت بقبَّعتِه ولمست أذنَه، وبدلًا من أن ينتَقِمَ الكولونيل من الطالبِ أمسك البندقية واتَّخَذ مكانَه في الصَّفِّ ليعَلِّمَه كيف يكون التصويبُ نحو الهدف، ولكي يُزيلَ الحاجِزَ النفسي بينه وبين طلابه اعتنقَ \"الكولونيل سيف\"  الإسلامَ، وأصبح اسمه  \"سليمان \" وبعد ثلاث سنوات من التدريب الشاقِّ، تمَّ تخريجُ مجموعة من الضباط وصل عددُهم إلى حوالي ستة آلاف ضابط. ومضى مشروعُ محمد علي في بناء جيش مصر الحديث، وظلَّ \"سليمان باشا الفرنساوي \" على رأسِ هذا الجيش يعَلِّمُ ويدرِّبُ وينَظِّمُ وينشئُ المدارسَ الحربية على النظام الحديث، فتأسَّست مدرسة حربية في \"فرشوط\"، وأخرى في \"جرجا\"، واتسعت دائرةُ التجنيد، وتمَّ إرسالُ مجموعة من الطلاب إلى أوروبا لإتمام دروسهم العسكرية هناك."},{"id":4424,"title":"افتتاح \"غرفة ترجمة الباب العالي\" في الدولة العثمانية .","date":["العام الهجري :1236","الشهر القمري : رجب","العام الميلادي :1821"],"text":"افتُتحت في الدولة العثمانية \"غرفة ترجمة الباب العالي\" وكان خريجو هذه المدرسة هم عمادَ السلك الدبلوماسي العثماني، وهم من أسَّسوا الدبلوماسيَّةَ التركيةَ الحديثة، وكانت اللغةُ الرئيسية فيها هي اللغةَ الفرنسيةَ."},{"id":4425,"title":"معاهدة أرضروم بين الفرس والعثمانيين .","date":["العام الهجري :1237","العام الميلادي :1821"],"text":"في أوائل القرن التاسع عشر ظهر إلى الوجودِ في هذه المنطقة نفوذُ روسيا القيصرية المتمَثِّل في شمال إيران وبريطانية التي يتمَثَّل وجودُها في الخليج العربي وجنوب إيران، وقد أخذت إيران في هذه الفترة في إثارة المشاكِلِ في العراق ضِدَّ الدولة العثمانية عن طريق إثارة المتمَرِّدين وتحريضِهم للثورة؛ ونظرًا لرغبةِ الأطراف المعنيَّة في وضع حدٍّ لهذه المشاكل الحدودية بين الدولتين العثمانية والإيرانية، فقد توسَّطت كلٌّ من روسيا القيصرية وبريطانيا لحَلِّ الخلافات بين الحكومتين العثمانية والإيرانية، فتَمَّ توقيعُ هذه المعاهدة عام 1847م؛ حيث ورد نَصُّ المادة الثانية من هذه المعاهدة كما يلي (تتعهد الحكومة الإيرانية أن تتركَ للحكومة العثمانية جميعَ الأراضي المنخَفِضة، أي: الأراضي الكائنة بالقسم الغربي من منطقة زهاب، وتتعهَّد الحكومة العثمانية بأن تترُكَ للحكومة الإيرانية القِسمَ الشرقي، أي: جميع الأراضي الجبلية من المنطقة المذكورة بما في ذلك وادي كرند، وتتنازل الحكومةُ الإيرانية عن كل ما لها من ادِّعاءات في مدينة السليمانية ومنطقتها، وتعهَّدت رسميًّا بألَّا تتدخَّلَ في سيادة الحكومة العثمانية على تلك المنطقة، أو تتجاوز عليها، وتعترف الحكومةُ العثمانية بصورةٍ رسمية بسيادةِ الحكومة الإيرانية التامَّة على مدينة المحمرة ومينائها وجزيرة خضر والمرسي والأراضي الواقعة على الضفة الشرقية، أي: الضفة اليسرى من شط العربِ التي تحت تصرُّف عشائر مُعتَرَف بأنَّها تابعة لإيران، وفضلًا عن ذلك فللمراكب الإيرانية حقُّ الملاحة."},{"id":4426,"title":"إحراق البحارة اليونانيين للدونانمة .","date":["العام الهجري :1237","الشهر القمري : رمضان","العام الميلادي :1822"],"text":"تمكَّن البحَّارة اليونانيون من إحراق الدونانمة، أي: الأسطول البحري التركي، في إطار ثورةِ اليونانيين التي اندلعت شرارتُها في المورة ضِدَّ الحكمِ العثمانيِّ، وقُتِلَ في هذه المعركة نحوُ ثلاثة آلاف مقاتل من البحرية التركية."},{"id":4427,"title":"استيلاء تركي بن عبد الله على ضرماء .","date":["العام الهجري :1239","العام الميلادي :1823"],"text":"دخلت هذه السنةُ وتركي بن عبد الله في بلد عرقة محاربًا لأهلِ الرياض ومنفوحة، وأهلِ الخَرج وصاحب ضرما وثرمداء وحريملاء. وباقي بلدان نجدٍ يكاتبونه بلا متابعةٍ، ثمَّ إن تركي عزم أن يسطوَ على ناصر السياري في بلد ضرما، فقصده من بلد عرقة، واستخلف فيها عمرَ بن محمد بن عفيصان، وليس مع تركي إلا شرذمةٌ قليلة، فدخل عليه المسجد فوجده في سطحه، وتمكَّنَ من قتله، واستولى تركي على بلد ضرما وملكَها وأقام فيها."},{"id":4428,"title":"هلاك معظم العساكر المصرية في عسير .","date":["العام الهجري :1240","العام الميلادي :1824"],"text":"سار أحمد باشا رئيسُ مكَّةَ بعسكرٍ كثيرٍ مِن مِصرَ والحجاز وغيرِهم، ومعه عددٌ من أشراف مكة وأتباعهم، فقَصَدوا عسير في اليمن، ورئيسهم سعيد بن مسلط، فوقع بينهم وقعاتٌ، فوقع على عساكر الباشا بَردٌ وبَرقٌ لا يُعرَفُ له نظير، فهلك غالِبُ العسكر ولم ينجُ منهم إلا القليلُ."},{"id":4429,"title":"بداية قيام الدولة السعودية الثانية .","date":["العام الهجري :1240","الشهر القمري : محرم","العام الميلادي :1824"],"text":"في رمضان عام 1238هـ بدأ تركي بن عبد الله تحَرُّكَه من مخبَئِه في بلدة الحلوة جنوبي نجد؛ لإخراجِ بقية القوَّات الغازية وحامياتها الموجودة بالرياض ومنفوحة، فانطلق منها وجمَعَ أتباعه عند بلدة عرقة قُربَ الرياض، وتوافَدَت إليه جموعُ المؤيِّدين من سدير والوشم، وبعد قتالٍ استمَرَّ لمدة عام ضد الحاميتين أجبر من كان فيهما من الجنودِ على المغادرة إلى الحجاز في أواخر عام 1239هـ وأمر مشاري بن ناصر آل سعود بدخولِ الرياضِ، وتوجَّه هو إلى الوشم؛ حيث أقام في شقراء مدة شهرٍ، وفيها قَدِمَ عليه أمير عنيزة يحيى بن سليم مبايعًا إياه على السمع والطاعة. وذلك في مستهَلِّ عام 1240هـ، ويُعَدُّ هذا التاريخ الذي رحلت فيه القواتُ المصرية عن نجد بدايةً لقيام الدولة السعودية الثانية، وعاصمتُها الرياض، وانتقل الحكمُ في أسرة آل سعود من أبناءِ عبد العزيز بن محمد بن سعود إلى أبناء عبد الله بن محمد بن سعود، وفي خلالِ عامين شَمِلَت هذه الدولة معظَمَ بلاد نجد، ودان أهلُها بالولاء لتركي بن عبد الله."},{"id":4430,"title":"وفاة المؤرخ عبد الرحمن الجبرتي .","date":["العام الهجري :1241","العام الميلادي :1825"],"text":"هو عبدُ الرحمن بن حسن بن إبراهيم الجبرتي، وُلِدَ في القاهرة عام 1753م والجبرتي نسبةً إلى بلدة جبرت، وهي بلاد زَيلَع في الحبشة، كان والِدُه من كبارِ العُلَماء الفَلَكيين، وحصل على ثروةٍ كبيرةٍ مِن عمله في التجارة، وقد رُزِق بنيِّف وأربعين ولدًا ذكَرًا، فعاش الجبرتي وسطَ أسرة ثرية، وكان تلميذًا لوالِدِه في مختلف المعارفِ، كما درس الجبرتي في الأزهر وبرَعَ في العلومِ العصريَّة وفي التاريخ، عُيِّنَ الجبرتي كاتبًا في الديوان لَمَّا دخل الفرنسيون إلى مصر، وانقطع بعدئذٍ للتأليف، وقد عاصر أحداثًا هامَّةً جدًّا، وكان الجبرتي ممن تأثَّروا بدعوةِ الشيخ محمد بن عبد الوهاب في مصرَ، بل ويُعدُّ من أشَدِّ المتأثِّرين بدعوة الشيخ محمد بن عبد الوهاب، وكان يرى أن الأتراكَ قد ارتكبوا خطأ كبيرًا عندما حاربوا دعوةَ الشيخ محمد بن عبد الوهاب وأنصارَها؛ ممَّا دفع محمد علي باشا إلى التضييق عليه، بل والسَّعي للتخلص منه, وقد اشتهر بتاريخِه المعروف باسمِه (تاريخ الجبرتي) الذي عنوانُه: (عجائب الآثار في التراجم والأخبار) ابتدأه بحوادث سنة 1100هـ وانتهى سنة 1236هـ، وله (مَظهَرُ التقديس بزوال دولة الفرنسيس)، وتوفي في مصر،  وقيل: إنه مات متأثرًا بقتل محمد علي باشا لابنِه خليل بسبَبِ موقفه المعارِضِ مِن حكم محمد علي وثورتِه على الدولة العثمانية، وأنَّ محمد علي أمره بكتابة كتابٍ لِمَدحه فرفض الجبرتي فهدَّده فرفض أيضًا؛ مما جعله يقوم بقتلِ ابنه خليل، فظل الجبرتي يبكي ابنَه حتى كفَّ بَصَرُه. ولَزِمَ بيته بعد تلك الفاجعة التي ألَمَّت به، لا يقرأُ ولا يكتُبُ ولا يتابِعُ الأخبارَ، حتى توفِّيَ بعد مقتَلِ ولده بحوالي ثلاث سنوات."},{"id":4431,"title":"بلدان نجد تدين بالولاء لتركي بن عبد الله .","date":["العام الهجري :1241","العام الميلادي :1825"],"text":"دانت جميعُ بلدان نجدٍ كلِّها بالسَّمعِ والطاعة للإمام تركي بن عبد الله سوى الأحساءِ وما يليه، فاطمأنَّت الرعيَّةُ، وأَمِنت البلدان والقرى، وخافت سطوتَه أشرارُ البلدان، ولانت لهيبتِه رؤوس العُربان، وزالت عنهم الفِتَن والحُروبِ."},{"id":4432,"title":"السلطان العثماني محمود الثاني يقضي على الجيش الانكشاري .","date":["العام الهجري :1241","العام الميلادي :1825"],"text":"فسدت طبيعةُ الانكشاريين وتغَيَّرت أخلاقهم، وتبدلَّت مهمَّتُهم، وأصبحوا مصدرًا للبلاءِ للدولة والشعوب التابعة لها، وصاروا يتدخَّلون في شؤونِ الدولة وتعَلَّقت أفئدتُهم بشهوةِ السلطة وانغمَسوا في الملذات والمحرمات، وشق عليهم أن ينفِروا في برودة الشتاءِ، وفرضوا العطايا السلطانية، ومالوا إلى النَّهبِ والسلب حين غَزوا البلاد، وتركوا الغاية التي من أجلِها وُجِدوا، وغَرَقوا في شرب الخمور، وأصبحت الهزائِمُ تأتي من قِبَلهم بسبب تَركِهم للشريعة والعقيدة والمبادئ، وبُعدِهم عن أسباب النصر الحقيقية، وقاموا بخَلعِ وقَتلِ السلاطين، فجمع السلطانُ مجموعة من أعيان الدولة وكبار ضبَّاط الانكشارية في بيتِ المفتي، ثم أفتى المفتي بجوازِ العمل للقضاء على المتمَرِّدين. وقد أعلن الموافقةَ كُلُّ من حضر من ضباط الانكشارية مِن حيث الظاهِرُ، وأبطنوا خلافَ ذلك، ولما شعروا بقُربِ ضياع امتيازاتهِم وبوضع حدٍّ لتصرُّفاتهم، أخذوا يستعدون للثورة، واستجاب لهم بعضُ العوام. وفي 8 ذي القعدة عام 1241هـ بدأ بعضُ الانكشاريين بالتحَرُّش بالجنود أثناء أدائِهم تدريباتهم، ثم بدؤوا في عصيانهم، فجمع السلطان العلماءَ وأخبرهم بنيَّةِ المتمردين فشَجَّعوه على استئصالهم، فأصدر الأوامر للمدفعية حتى تستعِدَّ لقتالهم ملوِّحًا باللين والتساهل في الوقتِ نفسِه؛ خوفًا من تزايُدِ لهيب شرورهم. وفي صباح 9 ذي القعدة تقَدَّم السلطان ووراءه جنودُ المدفعية وتَبِعَهم العلماء والطلبة إلى ساحة (آت ميداني) حيث اجتمع العصاةُ هناك يثيرون الشَّغبَ، وقيل: إن السلطانَ سار معه شيخ الإسلام قاضي زادة طاهر أفندي والصدر الأعظم سليم باشا أمام الجُموعِ التي كانت تزيد على 60.000 نفسٍ، ثم أحاطت المدفعية بالميدانِ واحتَلَّت المرتفعات ووجَّهت قذائِفَها على الانكشارية، فحاولوا الهجومَ على المدافع ولكِنَّها صَبَّت حمَمَها فوق رؤوسهم، فاحتَمَوا بثكناتهم هروبًا من الموت، فأحرقت وهدمت فوقَهم وكذلك تكايا البكتاشية، وبذلك انتصر عليهم. وفي اليوم التالي صدر مرسومٌ سلطاني قضى بإلغاء فِئَتِهم وملابسهم واصطلاحاتهم وأسمائهم من جميعِ بلاد الدولة، وقتل من بقي منهم هاربًا إلى الولاياتِ أو نفيه، ثم قلَّد حسين باشا الذي كانت له اليدُ الطولى في إبادتهم قائدًا عامًّا (سرعسكر) وبدأ بعدها نظامُ الجيش الجديد، ثم أصبح السلطان محمود بعد ذلك حرًّا في تطوير جيشه، فترَسَّم خطى الحضارة الغربية، فاستبدل الطربوش الرومي بالعمامة، وتزيَّا بالزيِّ الأوروبي، وأمر أن يكونَ هو الزيَّ الرسميَّ لكُلِّ موظَّفي الدولة؛ العسكريين منهم والمدنيين، وأسَّس وسامًا دعاه وسامَ الافتخارِ، فكان أوَّلَ من فعل ذلك من سلاطين آلِ عثمان، وما قام به السلطان محمود من استبدال الطربوش بالعِمامةِ وفرْض اللِّباس الأوروبي على كافَّةِ المجموعات العسكرية: يدُلُّ على شعورهِ العميق بالهزيمة النفسيَّة."},{"id":4433,"title":"عودة الشيخ عبدالرحمن بن حسن ابن الشيخ محمد بن عبد الوهاب من مصر  .","date":["العام الهجري :1241","العام الميلادي :1825"],"text":"قَدِم الإمامُ الحافظ المتقِن قاضي قضاة الإسلام الشيخ عبد الرحمن بن حسن ابن الشيخ محمد بن عبد الوهاب مِن مِصرَ على الإمام  تركي بن عبد الله بعد أن بَقِيَ في مصر 9 سنوات منذ أن نفاه إليها إبراهيم باشا عام 1233، وكان معه ابنه عبد اللطيف صغيرًا, ففرح الإمامُ تركي به وأكرمه، واغتبط به المسلمون الخاصُّ والعامُّ، وبذل الشيخُ مِن نفسه للطالبين، فانتفع بعِلمِه كثيرٌ مِن المستفيدين."},{"id":4434,"title":"صدور أول جريدة عربية بمصر .","date":["العام الهجري :1242","العام الميلادي :1826"],"text":"أصدَرَ محمد علي باشا والي مصر جريدةَ (الوقائع المصرية) باللغتين العربية والتركية، وقد ظهرت فكرةُ الجريدة في الصحافة المصرية بجُهدٍ مِن الحملة الفرنسية؛ حيث أُنشِئت أوَّلُ جرَيدةٍ عَرَفَها الشعب المصري، وهي جريدة بريد مصر، التي صدرت باللغة الفرنسية في 29 أغسطس سنة 1798م، ومع جَلاء الحملة الفرنسية ومع استقرارِ الأوضاع في مصرَ بدأت فكرةُ وجود صحافة محلية والاستفادة من مطبعة بولاق. لم تكُنْ لمحمد علي سياسةٌ صحفية واضحةٌ غيرَ أنه كان شغوفًا بالاطِّلاعِ على الصحف ومعرفة ما حمَلت من آراءٍ وأخبار، فأُعجِبَ بالصحف الغربية وأصبحَت لديه رغبةٌ في التعَرُّف على أخبار الداخل والخارج، فقَرَّر إنشاء أول جريدة مصرية واعتبرها جريدةَ الحكومة الرسمية، وأمر بتهيئةِ الوسائل لنشر هذه الجريدةِ، ورسم لها خطةَ التوزيع والانتشار، وصدر أولُ عددٍ منها في 3 ديسمبر من عام 1828م، وكانت توزع على موظَّفي الدولة وضبَّاط الجيش وطلَّاب البَعَثات، وتعاقَبَ على إدارتها عددٌ من المديرين، فكان رفاعةُ الطهطاوي أوَّلَ مديرٍ لها من عام 1842، وفي عام 1880م تولى الشيخ محمد عبده رئاسةَ الوقائع المصرية، وأصبحت تصدُرُ يوميًّا عدا يوم الجمعة."},{"id":4435,"title":"وفاة الأمير رَحمَة بن جابِر حاكم ساحل الدمام .","date":["العام الهجري :1242","الشهر القمري : جمادى الأولى","العام الميلادي :1826"],"text":"هو الأميرُ رحمةُ بن جابر بن عذبي شيخُ الجلاهمة ورئيسُهم، جعله الإمامُ سعود بن عبد العزيز حاكِمَ ساحل الدمام، وهو قُرصانٌ كويتي، من الشجعان. اشتهر بمساعدته لأهل البحرين على الخلاصِ من الاحتلال الفارسي عام 1782م، فجعلوا له حصةً مما يحصُلون عليه من اللؤلؤ. ثم توقَّفوا. هاجر إلى دارين واحترف القرصنة 1802 م فكان له أسطولٌ قوامه خمسُ سفن. يزيدُ بحَّارتُها على الألف بحَّار. أخذ يعترض سفُنَ الغوَّاصين ولا سيما أهل البحرين والسُّفُن البريطانية، فيستولي على ما يتيسَّرُ. وضَجَّ منه عمَّالُ الإنكليز في الخليج، وحالفَ آل سعود 1809م إلى أن فَصَله عنهم موظَّفو الحكومة العثمانية 1816م ومنحوه ملكية ساحل الدمام ونصَّبوه أميرًا على خور حسن شمالي الزبارة في قطر، فبنى لنفسه قلعةً في الدمام 1818م وتواصلت معارِكُه مع أهل البحرين وغيرهم، وفي هذا العام جرت واقعة (تنورة) البحرية بين رحمة ومن معه من رعايا آل سعود، وبين آلِ خليفة أمراء البحرين ومن معهم من آل صباح أمراء الكويت، وكانت المعركةُ من العنف لدرجة أن ميازيب السفن سالت دمًا، ويقَدَّرُ عدد القتلى بألف وخمسمائة قتيل، في عدادهم دعيج صاحب الكويت، وراشد بن عبد الله آل خليفة، وشبَّت النارُ في سبع سفن، فانفجرت فيها مخازِنُ البارود وتطايرت أقسامها ومن فيها، وكان رحمة بين القتلى. قال أحد كتَّابِ الإنكليز \"إن رحمة أنجَحُ وأجرَأُ قرصان عرَفَتْه البِحارُ على الإطلاق\". وكان رحمة كثيرَ اللَّهج بالأشعارِ لا سيما أشعارُ الحرب والحماسة، وله شعرٌ جَيِّدٌ، وله محبَّةٌ لأهل دعوة التوحيد، وقد نظم فيها وفي دعاتها وعلمائها شِعرًا."},{"id":4436,"title":"وفاة الشيخ عثمان بن عبد الجبار  .","date":["العام الهجري :1242","الشهر القمري : شعبان","العام الميلادي :1827"],"text":"هو العالم الفقيهُ الشيخ عثمان بن عبد الجبَّار بن حمد بن شبانة الوهبي التميمي، بقيَّةُ العُلماء الزُّهَّاد، ورِثَ العلمَ كابرًا عن كابر مِن آبائه وأجداده وأعمامه وإخوانه، وممَّن تعلم منهم ابنُ عمه الشيخ حمد بن عثمان بن عبد الله، والشيخ حمد التويجري، والشيخ عبد المحسن بن نشوان بن شارخ، القاضي في الكويت والزبير، والشيخ عبد العزيز بن عيد الإحسائي نزيل الدرعية، وكان الشيخ عثمان فقيهًا له قُدرةٌ على استحضار أقوال العلماء، وله معرفةٌ في التفسير والفرائض والحساب، وهو عالمُ زمانِه في المذهَبِ، لا يدانيه فيه أحدٌ، تخرَّج على يديه وانتفع به خلقٌ كثير، منهم: ابنه القاضي الشيخ عبد العزيز، والشيخ عبد الرحمن بن أحمد الثميري قاضي سدير، والشيخ عثمان بن علي بن عيسى قاضي الغاط والزلفي، وغيرهم. وكان في الغايةِ مِن الوَرَعِ والعبادة والعفاف، عَيَّنه الإمام عبد العزيز بن محمد قاضيًا لعسير، وألمع عند عبد الوهاب أبو نقطة المتحَمِّي، وأقام هناك مدة ثم رجع، وأرسله الإمام عبد العزيز بن محمد أيضًا قاضيًا لعسير عند ابن حرملة وعشيرته، ثم أرسله الإمام سعود قاضيًا في عمان، وأقام في رأس الخيمة يقضي بين الناسِ ويُدَرِّس لطلابِ العلم، ثم رجع، ولَمَّا توفِّيَ عَمُّه محمد قاضي بلدان سدير، عَيَّنه الإمام سعود مكانه قاضيًا لبلدان سدير، واستمَرَّ في القضاء زمن الإمام سعود وزمن ابنه الإمام عبد الله وما بعدهما، إلى أن توفي في السابع والعشرين من هذا الشهر."},{"id":4437,"title":"اندلاع الحرب بين روسيا والدولة العثمانية ومعاهدة أدرنة .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"بعد أن أعلنت روسيا الحربَ على الدَّولةِ العُثمانية في شوال مِن هذا العام، اجتازت نهرَ بروت الفاصل بين الدولتين والذي يرفدُ نهر الدانوب قُربَ مَصَبِّه، واحتلت عاصمةَ إقليم البغدان ياش الواقعةَ على النهر، ثم دخلت بخارست عاصِمةَ الأفلاقِ، وجعلت على الإقليمينِ حُكَّامًا من قِبَلِها، ثم اجتازت نهرَ الدانوب واتَّجَهت جيوشُها لحصار مدينةِ فارنا الواقعةِ في بلغاريا على ساحلِ البحر الأسود، وحاصرَتْها برًّا وبحرًا، وجاءت إليها الإمداداتُ برًّا وبحرًا، ولكِنْ سَلَّمَت في النهايةِ عن طريق الخيانة بعدما يئس الروس من دخولِها، وكان تسليمُها في أول ربيع الثاني عام 1244هـ على يد يوسف باشا أحدِ القادة العثمانيين الذي التجأ أيضًا إلى بلاد الروس، وكذلك احتَلَّت روسيا مدينةَ قارص في شرق الأناضول، ثم تقدَّمت من جهةِ الغربِ واحتلَّت مدينةَ أدرنة، وخافت فرنسا وإنكلترا من أن تحتَلَّ روسيا استانبول فسارعتا للوقوفِ في وجه روسيا، وبجهودِ مملكة بروسيا عُقِدَت معاهدةُ أدرنة عام 1245هـ."},{"id":4438,"title":"أهل جبل شمر يبايعون الإمام تركي بن عبد الله على السمع والطاعة .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"وفد عيسى بن علي رئيس جبل شمر على الإمامِ تركي بن عبد الله ومعه رؤساءُ قَومِه، فبايعوه على دين الله ورسولِه والسَّمعِ والطاعة، وجعل في بيتِ مال الجبل حمدَ الشويعر الذي كان على بيتِ مالِ الجبل منذ أيام الإمامَينِ سعود وعبد الله."},{"id":4439,"title":"وفاة الشيخ عبد الله ابن الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"هو الإمامُ العلَّامةُ الأوحد الشيخ عبد الله ابن شيخ الإسلام محمد بن عبد الوهاب، الثِّقةُ الثَّبتُ, التقي الوَرِعُ المجاهد المحتَسِب, ذو الهمة العالية والشجاعة المتناهية, الذي خَلَف والِدَه شيخ الإسلام محمد بن عبد الوهاب في مؤازرة الإمامِ عبد العزيز بن محمد بن سعود، وخَلَفه في بثِّ العلم والقيام بدعوة التوحيد ونَشْرها، والدفاع عنها بالقلَمِ واللسان، والحُجَّة والبيان، وهو عالمُ نجد بعد أبيه ومُفتيها، ومَن له الفتاوى السديدة والأجوبة العديدة، والرُّدود العظيمة، ومن ضُرِبَت إليه أكبادُ الإبل مِن سائِرِ بلدان نجد، وتوالت عليه الأسئلةُ من جميع قرى نجد ومدُنِها. ولِدَ في الدرعية سنة 1165هـ ونشأ بها في كَنَف والده، وقرأ القرآنَ حتى حَفِظه ثم شرع في القراءةِ على والده، فتفَقَّه في المذاهب الإسلامية، ومهَرَ في علمي الفروع والأصول، وكان مع هذا عالِمًا بارزًا في علم التفسير والعقائد وأصول الدين، عارفًا بالحديث ومعانيه، وبالفِقهِ وأصوله، وعلم النحو واللغة، وله اليدُ الطولي في جميع العلوم والفنون، كرَّس جُهدَه وأوقف حياته على تحصيلِ العلم وتعليمه ونَشْره تدريسًا وتأليفًا، فأخذ عنه العِلمَ خلقٌ كثيرٌ من فطاحلة عُلماء نجد وجهابِذتِهم، وكان مَرجِعَ القضاة في عهد الإمامِ عبد العزيز بن محمد بن سعود، وابنِه الإمام سعود، وابنِه الإمام عبد الله، وقد ألَّف مؤلفات كثيرة، منها: جواب أهل السنة النبوية في نقض كلام الشيعة والزيدية، ردَّ به على بعض عُلماء الزيدية الذين اعترضوا على دعوةِ التوحيد السَّلَفية، وألَّف مختَصَر السيرة النبوية في مجلَّدٍ ضخمٍ، والكلمات النافعة في المكفِّرات الواقعة، وألَّف منسكًا صغيرًا للحج، وكتب رسائِلَ وفتاوى كثيرة، وكان له دروسٌ خاصة يحضُرُها الإمام سعود عبد العزيز، وابنه الإمام عبد الله بن سعود، في الدرعية، وقد صَحِبَ الأمير سعودَ بن عبد العزيز في دخوله مكَّةَ سنة 1218، وكتب حالَ دخوله مكة المكرمة مع الأمير سعود رسالةً وإجابةً منه لِمن سأله عمَّا يعتقدونه ويدينون للهِ به، وكان مع هذا شجاعًا مِقدامًا، وقف في باب البجيري المعروف -أثناء حصار إبراهيم باشا للدرعيَّة- وشهَرَ سَيفَه وقاتل قِتالَ الأبطال قائلًا كلمته المشهورة: \"بطنُ الأرض على عِزٍّ خيرٌ من ظهرِها على ذُلٍّ\" وقاتَلَ حتى رد العساكِرَ وزحزحهم عن مواقِفِهم، وذلك في آخر حرب الباشا على الدرعية، ثم نقله باشا إلى مصرَ بعد ما استولى على الدرعية، وذلك سنة 1242هـ, ونقل معه ابنه عبد الرحمن، وبقي بمصر محدودَ الإقامة حتى توفِّيَ  بمصر، وقد أنجب ثلاثةَ أبناء عُلَماء، هم: الشيخ سليمان، الذي قتله إبراهيم باشا في الدرعية، وعليٌّ قُتِلَ فيما بعد على يد بعض عساكرِ الترك بنجد، وعبد الرحمن نُقِلَ مع أبيه إلى مصر صغيرًا وتعلَّم بها ودرَّس برُواق الحنابلةِ."},{"id":4440,"title":"رخص الأسعار وكثرة الأمطار في نجد .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"وفيها أرخص اللهُ الأسعارَ وكَثُرت الأمطارُ وفاضت الآبارُ، فأول ما نزل الغيثُ في الموسم زرع عليه النَّاسُ، فلمَّا حُصِد الزَّرعُ ونُقِلَ في بيادره تتابَعَ الغيثُ فأعطنت الزروع، فلم يكن للناسِ شُغلٌ إلَّا نشرُها وجمعُها، واسوَدَّ التبن وتغَيَّر الحَبُّ، وأقام الناس على ذلك نحوًا من عشرين يومًا، كل يوم ينزل الحَيَا والسيلُ في آخِرِ النَّهارِ، وأوَّلُه صَحوٌ لم يُرَ عليها قزعة، فلما كبر البُسر وصار كالبندق أُصيب بدودةٍ تَضرِبُ البسرة عند القمعِ فتسقُط، وسقط ما في النخيل كله إلَّا أقلَّ قليل، وذلك في بلدان سدير وغيرها، وقُطِعت أكثَرُ عذوق النخل ولم يبقَ بها شيءٌ، والثمرة قبل ذلك في غاية الكثرة، واستمر ذلك في السنة التي تلتها، لكنه أخفُّ من التي قبلها، وظهرت أعراب الظفير على نجد، واكتالوا من بلدانِ سدير على عشرة أصواع بالريال."},{"id":4441,"title":"هزيمة إبراهيم باشا في معركة نافارين  .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"طلبت إنكلترا من الدولة العثمانية في الثامن من رجب عام 1242هـ أن تتوسَّطَ الدول الأوربية النصرانية بين الدولةِ العثمانية وبين ما يتبَعُها، فرفضت الدولةُ العثمانية ذلك؛ لأنَّ هذا تدخلٌ صريح في شؤونها الداخلية، فكان هذا الرَّفضُ حُجَّةً تذرعت به لإعلان الحربِ مَرَّةً أخرى بعد أن ضَعُفت الدولة سياسيًّا، فاتفقت روسيا وفرنسا وإنكلترا في الحادي عشر من ذي الحجة على إجبارِ الدولة العثمانية لإعطاء اليونان استقلالَها على أن تدفَعَ جِزيةً سنوية يتَّفِق عليها الطرفان، وأعطِيَ الخليفة شهرًا لإيقاف الأعمالِ ضِدَّ اليونان، وإذا عجز عن ذلك أو رفَضَ فإنَّ الدُّولَ النصرانيَّةَ تتَّخِذُ ما تراه مناسبًا، ولم يعمَلِ الخليفة أيَّ عمَلٍ، وبعد شهر أمرت الدولُ الثلاث روسيا وفرنسا وإنكلترا أساطيلَها بالتوجه إلى سواحل اليونان وطلَبَت من إبراهيم باشا التوقُّفَ عن القتال، فكان جوابه أنه يتلقَّى أوامِرَه من الخليفة أو من أبيه، ومع ذلك توقف عشرين يومًا عن القتال ريثما تَصِلُ إليه التعليمات، واجتمعت أساطيلُ الدول الأوربية في ميناءِ نافارين (خليج نافارين فيلوس شرقي بيلوبونز جنوب اليونان الحالية) ودمَّرَت الأسطولَ العثماني وأكثَرَ الأسطول المصري، وقُتِلَ ما يزيد على ثلاثين ألف جنديٍّ مصري، واحتج الخليفة فلم ينفَعْه احتجاجُه، فأعلن أن َّالقتالَ دينيٌّ لا سياسي في منشورٍ أصدره للمواطنين، ودعاهم فيه للدفاع عن عقيدتِهم، وخَصَّ بذلك روسيا التي تأثَّرَت من ذلك، وأعلنت الحربَ على الدولة العثمانية في شوال من هذا العامِ، وأمر محمد علي ابنَه بالانسحابِ، وكانت القوات الفرنسية تحلُّ محَلَّ المنسحبين، ثمَّ عَقَدت الدول الثلاث مؤتمرًا في لندن ودُعِيَت إليه الدولة العثمانية فرفضت الحضورَ، فقَرَّر المؤتمر إعلانَ استقلال اليونان وحُكْمها من قِبَلِ حاكم نصراني تنتخِبُه هذه الدول ويكون تحت حمايتها وتدفَعُ جِزيةً سنوية للدولة العثمانية مقدارها خمسمائة ألف قرش، ولكِنَّ الدولة العثمانية رفضت هذه القرارات التي تتعلَّقُ بالدولة ورعاياها، ولا يحِقُّ لأحدٍ التدخُّلُ وإصدار القرارات بشأنها، وانصرفت إلى قتال الروس الذين أعلنوا الحَربَ."},{"id":4442,"title":"أهل القصيم يبايعون الإمام تركي بن عبد الله على السمع والطاعة .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"أرسل الإمامُ تركي إلى رؤساء القصيم وأمراء بلدانه، وأمرهم بالقدومِ إليه فأقبل جميعُ أمراء القصيم ورؤسائه، فقَدِموا عليه في الرياضِ وبايعوه كلُّهم على السَّمعِ والطاعة، وعزَل محمَّدَ بن علي الشاعر عن إمارة بُرَيدة وجعَلَ مكانَه عبد العزيز بن محمد بن عبد الله، ثمَّ لما بلغ الإمامَ تركيًا ما يريبُه من محمد بن علي أرسل إليه وجعله عنده في الرياضِ ولم يأذن له بالعودةِ للقصيم حتى قَوِيَ عبد العزيز بن محمد وقَوِيَت شوكتُه."},{"id":4443,"title":"خروج فيصل بن تركي من مصر .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"أقبل فيصل بن تركي هاربًا مِن مصر وقَدِمَ على أبيه في الرياض فاستبشر به والِدُه، وصار فيصل الساعِدَ الايمان لوالده في إدارة الدولة، وقد كان فيصل من ضمن المنقولين إلى مصر سنة 1234 ومعه أسرته، وهم إخوانُه وعددهم أربعةٌ، وأخواتُه اثنتان، ووالدته، وثمانٍ مِن جواريه، وسبعةٌ من عبيدِه وخَدَمِه، وكان مجموعُ من نفى إبراهيم باشا إلى مصرَ مِن آل سعود وآل الشيخ 351 بموجِبِ البيان الذي أرسله إبراهيمُ لوالده في مصر، والجبرتي ذكر أنَّ الذين وصلوا إلى مصر 285 فردًا؛ مما يعني تخلُّفَ عَدَدٍ منهم، وهَرَبَ بعضِهم."},{"id":4444,"title":"رؤساء العربان يبايعون الإمام تركي بن عبد الله  .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"وَفد رؤساءُ العُربان من سبيع ومطير والعجمان وقحطان وغيرهم على الإمامِ تركي يبايعونه على السَّمعِ والطاعةِ، فأرسل معهم عمالًا يَقبَضون الزكاةَ."},{"id":4445,"title":"فتنة بين الصميط من أهل حرمة وآل راشد رؤساء أهل حرمة في  الزبير  .","date":["العام الهجري :1243","العام الميلادي :1827"],"text":"وقع سِبابٌ بين سليمان بن عبد الله الصميط من سبيعٍ، ومِن أهلِ حرمة وبين عبد الرحمن بن مبارك بن راشد، رئيس أهل حرمة، فوثب رجلٌ من آل راشد فقتَلَ سليمانَ، فكمن رجلٌ من الصميط لناصر بن راشد أمير الزبير فقتَلَه، وحصل مجاولات بين الفريقين، انضَمَّ إلى آل راشد آلُ زهير، ثم وقع الصلح بينهم واجتمعوا له وحضره العُلَماء والرؤساء والمشايخ، وكتبوا بينهم سِجِلًّا أودعوا فيه شيئًا عظيمًا من المواثيق، وشَهِدَ عليه 28 من المشايخ والعلماء والرؤساء، ثمَّ إن آل زهير وآل رشيد نقضوا الصُّلحَ وتآمروا على قَتلِ جاسر بن فوزان الصميط وهو يومئذٍ رئيسُ القوم، فتفرق قومُه في الكويت وقَدِمَ إلى الزبير أميرًا عليها علي بن يوسف بن زهير وصار له فيها قُوَّةٌ وشُهرةٌ، وتعاظَمَ أمرُه إلى أن هلك في الوباء الذي أصاب الزبير ونواحيَه، ثم صار هلاكُ آل زهير على يدِ أعوانهم آل راشد!"},{"id":4446,"title":"تحطيم الأسطول المصري في معركة نفارين .","date":["العام الهجري :1243","الشهر القمري : ربيع الأول","العام الميلادي :1827"],"text":"قام الأسطولان البريطاني والروسي بتحطيمِ الأسطول المصري في معركةِ نفارين؛ وذلك لخشيةِ كلا الأُسطولين من ازديادِ نُفوذِ محمد علي باشا بعد استدعاءِ السلطان العثماني للجيشِ المصري؛ لإخماد الثورةِ التي اشتعلت في بلادِ المورة ضدَّ الدولةِ العثمانيةِ."},{"id":4447,"title":"الدولة العثمانية توقع معاهدة أكرمان مع روسيا .","date":["العام الهجري :1243","الشهر القمري : ربيع الأول","العام الميلادي :1827"],"text":"وقَّعت الدولةُ العثمانية معاهدةَ أكرمان مع روسيا، وتمَّ بموجِبِ هذه المعاهَدةِ توسيعُ الاستقلال الداخلي لرومانيا وصربيا، كما تقَرَّر بموجِبِها عدمُ وجودِ أيِّ مُسلمٍ محليٍّ في قِلاعِ صربيا عدا الجنودِ الأتراك."},{"id":4448,"title":"إعلان روسيا الحرب على الدولة العثمانية واحتلالِ رومانيا .","date":["العام الهجري :1243","الشهر القمري : شوال","العام الميلادي :1828"],"text":"أعلنت روسيا الحربَ على الدولة العثمانية، وتمكَّنَت من إخراجِ العثمانيين من السواحِلِ الشرقية للبَحرِ الأسود، وقامت باحتلالِ رومانيا التي كانت تابعةً للدولة العثمانية في تلك الفترة."},{"id":4449,"title":"تجديد أهل رأس الخيمة ولاءهم للإمام تركي بن عبد الله .","date":["العام الهجري :1244","العام الميلادي :1828"],"text":"كانت رأسُ الخيمة قد أعلنت ولاءَها للدولة السعودية الأولى، ولجأ إليها عددٌ من الذين فرُّوا من الدرعية بعد استسلامِ الإمام عبد الله بن سعود، وجَدَّد أهلُ رأس الخيمة ولاءَهم لتركي بن عبد الله، حيث قَدِمَ إليه وفد منهم يطالبون بقاضٍ ومعلم وسَرِيَّةً، فأرسل معهم سَرِيةً بقيادة عمر بن عفيصان لحمايتِهم من خصومِهم، ومعه قاضٍ هو الشيخ محمد بن عبد العزيز العوسجي قاضي بلدان المحمل زمنَ الإمام سعود، وأصبحت واحةُ البريمي مركزًا للقوة السعودية في تلك الجهاتِ."},{"id":4450,"title":"وفاة الشيخ عبد العزيز بن حمد بن معمر .","date":["العام الهجري :1244","العام الميلادي :1828"],"text":"هو الإمامُ العلَّامة الشيخُ عبد العزيز بن الشيخ الإمام حمد بن ناصر بن عثمان بن معمر من آل معمر أهل العُيَينة، وهم من بين سعد بن زيد مناة بن تميم، وُلِدَ في الدرعية مركزِ الحركة العلمية في ذلك الحين سنة 1203هـ ونشأ في وسط العلماء العاملين الذين كانت تزخَرُ بهم الدرعيةُ ونجد في ذلك الزمنِ، فكان من شيوخِه والِدُه الشيخ حمد بن ناصر بن معمر، والشيخ الإمام عبد الله ابن شيخ الإسلام محمد بن عبد الوهاب، والشيخ العلامة المؤرخ أبو بكر حسين بن غنام، والشيخ أحمد بن حسين بن رشيد بن عفالق الحنبلي نزيل الدرعية، وغيرهم من العلماء، فمَهَر في جميعِ العلوم والفنون فصار عالِمًا محَقِّقًا وفقيهًا متبحرًا، له اليد الطولى والباع الواسع في التصنيف والتأليف ونشْر العلم وتخريجِ الكثير من الطلاب، والرَّد على المعارضين، وله عِدَّةُ مصَنَّفات وفتاوى ورسائل وأشعار، ومن أشهر مصنَّفاتِه وأجَلِّها الكتابُ المسمى: منحة القريب العجيب في الرد على عُبَّاد الصليب، ومن مصنَّفاته أيضًا: اختصار نظم ابن عبد القوي للمُقنِع. أخذ عنه العلم وانتفع به كثيرٌ من العلماء، وفي زمَنِه جرى على الديار النجدية والدولةِ السعودية ما جرى من التقتيل والتخريبِ، فدُمِّرَت الدرعية وتشَتَّت علماؤها وقادةُ الدعوة الذين كانوا بها؛ أخرجهم إبراهيم باشا من أوطانِهم ونفاهم إلى مِصرَ، وفر الشيخُ عبد العزيز بن معمر من الدرعية إلى البحرين، وكان لا يزال شابًّا في العقد الثالث من عمرِه، فأقام بها ولم تنقَطِعْ صلته بآل الشيخ الذين نُقِلوا إلى مصرَ، فكان يكاتب الشيخ عبد الرحمن بن حسن بأشعارٍ يتوجَّعُ فيها على ما حَلَّ بنجدٍ مِن الدمار والخراب. أرسل شيخُ البحرين عبد الله بن خليفة عليه شُبهةً كتَبَها قسيس نصراني إنجليزي عجز عن الردِّ عليها علماءُ البحرين والأحساء، فتناوله الشيخ عبد العزيز وأمعن النظرَ فيه وقال: تأخذونَ مني دحض هذه الشبهةِ بعد شهر إن شاء الله تعالى، فلبث شهرًا وأتمَّ الردَّ وبعث به إلى الأميرِ وفَرحَ به أشَدَّ الفَرَحِ، ودُعِيَ القسيس الإنكليزي وأعطاه الردَّ، فلما طالعه عَجِبَ له واندهش جدًّا لِما كان يظنه من عجز ِعلماء البحرين، وقال: هذا الرد لا يكونُ مِن هنا وإنما يكون من البحر النجدي، فقال له الأمير: نعم، إنه أحَدُ طلبة العلم النجديين. أقام الشيخ عبد العزيز في البحرين حتى توفِّيَ فيها."},{"id":4451,"title":"توقيع معاهدة أدرنة بين روسيا والدولة العثمانية .","date":["العام الهجري :1245","الشهر القمري : ربيع الأول","العام الميلادي :1829"],"text":"تَمَّ توقيعُ معاهدة أدرنة بين روسيا والدولة العثمانية في عهد السلطان محمود الثاني في منتصَفِ هذا الشهر، فبعد أن احتلت روسيا مدينةَ أدرنة خَشِيَت فرنسا وإنكلترا أن تحتَلَّ روسيا استانبول فإنَّ ذلك يهَدِّدُ مصالحهما الخاصة، فسارعتا للوقوف في وجهِ روسيا وبجهودِ مملكة بروسيا تم عقد معاهدة أدرنة والتي بمقتضاها دعمت روسيا مركزَها في البحر الأسود، بينما تقَلَّصت السيادةُ العثمانية، فانحسرت عن جميعِ مَصابِّ نهر الدانوب في البحر الأسود، ومن أهمِّ ما جاء في هذه المعاهدة إعادةُ الأفلاق والبغدان ودوبروجه والبلغار والبلقان وقارص وأرضروم إلى الدولة العثمانية، يعَدُّ نهر بروت الحَدَّ الفاصل بين الدولتين، وتكون الملاحةُ في نهر الدانوب عند مَصَبِّه من حقِّ الدولتين، مع حرية الملاحة الروسية في البحر الأسود، وعَدَم تفتيش السُّفُن الروسية أثناء عبورِها للمضائق العثمانية، وتعَوِّضُ الدولة العثمانية روسيا مبالِغَ كمصاريف حرب، ويُطلَق سراح الأسرى الذين عند الدولتين، وتستَقِلُّ بلاد الصرب وتُعطى ما بقِيَ من أجزائِها تحت حُكمِ الدولة العثمانية، وتُعادُ الامتيازات القنصلية الروسية، ويعامَلُ رعايا روسيا نفسَ معاملة رعايا الدُّوَل الأوربية الأخرى وكذا الامتيازات."},{"id":4452,"title":"بدء احتلال فرنسا للجزائر واستمرار عملية المقاومة (18) عامًا .","date":["العام الهجري :1245","الشهر القمري : شعبان","العام الميلادي :1830"],"text":"كان السببُ الظاهِرُ الذي دعا إلى احتلالِ الفرنسيين للجزائر هو ما قام به حاكمُ الجزائر الباي حسين التابِعُ للدولة العثمانية، وهو يستقبل المهنِّئين بعيد الفطر، وكان من بينهم السفيرُ الفرنسي الذي جرى حديثٌ بينه وبين الباي حسين بشأن الدُّيون التي على فرنسا للجزائر، فوجَّه السفير كلامًا يمَسُّ كرامة الباي الذي غَضِبَ، وكان بيده مروحة أشار بها في وجهِ السفير الذي أصاب وجهَه طرفُ المروحة، فكان هذا الحادث في عام 1243هـ هو السبب الذي تذرَّعت به فرنسا لدخولِها واحتلالها الجزائرِ في هذا العام، وكانت فرنسا تطمَعُ في احتلال أجزاءٍ مِن ساحل بلاد المغرب لتكَوِّنَ قواعِدَ لها بزعمها أنَّ قراصنةَ بلاد المغرب يتعدَّون على سفُنِها، فكانت هذه الحادثة هي الذريعةَ لاحتلال الجزائرِ."},{"id":4453,"title":"ضم الأحساء للدولة السعودية الثانية .","date":["العام الهجري :1245","الشهر القمري : رمضان","العام الميلادي :1830"],"text":"تطَلَّع الإمامُ تركي بن عبد الله بن محمد بن سعود إلى ضَمِّ الأحساء التي استعادها بنو خالد بعد سقوطِ الدرعية، وأراد التخلص من تهديدهم لدولته، فأمر عمر بن محمد بن عفيصان فغزاها فرَدَّ عليه أحدُ زعماء بني خالد بغزوِ بلدة حرمة بنجد. ولكنَّ الدائرةَ دارت على بني خالد ودخل الإمامُ تركي الأحساء دون قتالٍ، بعد هروب بني خالد منها، وقد وفد زعماءُ القطيف على الإمام وبايعوه على السَّمعِ والطاعة، وبهذا رجَعَت الأحساءُ مرة أخرى للدولة السعودية، وغادرها الإمام تركي تاركًا فيها عمر بن محمد بن عفيصان أميرًا عليها، وعبد الله الوهيبي قاضيًا لها."},{"id":4454,"title":"العثمانيون يقضون على المماليك في العراق .","date":["العام الهجري :1245","الشهر القمري : رمضان","العام الميلادي :1830"],"text":"حَكَم المماليكُ في العراق 1189 - 1247هـ، 1775 - 1831م. وأدَّى ضَعفُ السُّلطة المركزية والانحسارُ الفِعليُّ للوجودِ العثماني المباشِر عن أقاليمَ عديدة، إلى قيامِ سُلُطاتٍ محليَّةٍ قوية تمكَّنت مِن ملءِ الفراغ الناجم عن ذلك الانحسارِ، فظهرت سُلطةُ المماليك في العراق. وتميَّزت فَترةُ حكم المماليك بتعاقُبِ وُلاةٍ مماليكَ على السُّلطةِ في بغداد، وظهور دورٍ ملحوظٍ للقُوى الأوروبية في إسنادِ ترشيحِ أحَدِ الأغوات المماليك لولايةِ بغداد، ممن يَجِدون في تعيينه ما يحقِّقُ لهم مزيدًا من المصالحِ في العراقِ؛ الأمرُ الذي أضاف عاملًا جديدًا في إبقاءِ السلطة بيَدِ المماليك، وترسيخِ السيطرة العثمانية غيرِ المباشرة، فكان تعيينُ سليمان باشا الكبير سنة 1194هـ، 1780م بدعمِ كُلٍّ مِن المقيم البريطاني في البصرة، والسفير البريطاني في استانبول. كما جاء تعيينُ خَلَفِه علي باشا سنة 1802م بتدخُّل من المقيم البريطاني في بغداد، بينما وصل سليمانُ باشا الملقَّب بالصغيرِ إلى الحكمِ سنة 1808م بمساندةٍ ودَعمٍ مِن الفرنسيين، وكان آخِرُ الولاة داود باشا. وقد استطاعت الدولةُ العثمانية القضاءَ على المماليك إثرَ معركةٍ وقعت بين الطرفين في رمضان 1225هـ، أكتوبر 1810م وظلَّت الأسَرُ المحلية في العراق تحكُمُ بموجِبِ فرمانات من السلطة العثمانية، كأسرةِ الجليلي في الموصل، وأسرة البابانيين في السليمانية. وقد عَيَّنَت الدولةُ العثمانية الواليَ علي رضا باشا واليًا على بغداد، وعَمِلَ على توطيد نفوذِه في البلاد. وقد عَمِلَت بريطانيا على توطيدِ نفوذِها في العراق، فأوفدت بعثاتٍ تقومُ بأعمال المسحِ والتخطيطِ خلالَ الفترة (1830-1860م)."},{"id":4455,"title":"جهاد الإمام شامل للروس في بلاد القوقاز .","date":["العام الهجري :1246","العام الميلادي :1830"],"text":"نفَّذ شامِلٌ انسحابًا تكتيكيًّا إلى داخل الجبال، مغريًا الروس بالتوغُّل خلفه عبر الغابات الكثيفة، فانقضَّ عليهم المريدون من جهاتٍ مختلفة. وقتلوا أكثَرَ مِن نصف ضبَّاط الروس، وتوالت الهجماتُ على الروس حتى غنِمَ المريدون منهم أربعةَ مدافعَ روسية استُخدِمَت في حرب الروس الذين قُتِلَ منهم خلال أربع سنوات أكثر من 10.000 قتيلٍ"},{"id":4456,"title":"حملة محمد علي باشا على الشام بحجة توحيد الشام مع مصر .","date":["العام الهجري :1246","العام الميلادي :1830"],"text":"كان محمد علي باشا والي مصر يطمَعُ أن يوسِّعَ أملاكَه ويرغَبُ في ضَمِّ الشام إليه، ولَمَّا فَرَّ عددٌ من الهاربين من التجنيد إلى الشام والتجؤوا إلى عبد الله باشا والي عكَّا، ومنهم من هرب من الضرائب الفادحة، فتذرَّع محمد علي بهذه الذريعة للدُّخول إلى الشام، وكان قد راسل الخليفةَ بنيَّتِه، ولكِنَّ الخليفةَ لم يوافِقْه على ذلك، ولكِن محمد علي لم يصغِ إليه، بل أرسل جيشًا بريًّا بقيادة ابنه إبراهيم، وسيَّرَ حملةً بحرية في جمادى الأولى من عام 1247هـ. أما البرية التي سبقَتْها فقد استطاعت احتلالَ غَزَّة ويافا والقدس ونابلس والتقتا في حيفا، ثم سار إبراهيمُ وحاصر عكا برًّا وبحرًا، فكلَّف الخليفةُ عثمان باشا والي حلب بقتالِ إبراهيم، فسار إليه فترك إبراهيمُ الحصارَ لقوَّةٍ صغيرة، وسار لملاقاتِه، فالتقيا قرب حمص فهزَمَه إبراهيم، ورجع إبراهيم للحصارِ حتى تمكن من دخول عكَّا، ثم انطلق شمالًا، ويُذكَرُ أنَّه قد أعلن نصارى بلاد الشام بأنَّ إبراهيم باشا صديق لهم، وأبدوا استعدادًا تامًّا لمساعدته، كما أن ابراهيم باشا قد ألغى كافة القيود المفروضة على النصارى واليهود فقط في كل بلدٍ سيطر عليه تحت دعوى المساواةِ والحرية، ثم سير الخليفة جيشًا آخر لقتال إبراهيم بقيادة حسين باشا، ولكنه هُزِمَ أيضًا، فدخل المصريون حلب وتراجع حسين باشا حتى تحصَّن في ممرِّ بيلان -الطريق الطبيعي للأناضول. وعلى الرغم من أن جيشَ إبراهيم باشا قد تمكَّن من هزيمة الجيش العثماني واستطاع أن يستكمِلَ سيطرته على الشام إلَّا أن العثمانيين قد تمكَّنوا من إثارة الأهالي ضِدَّ ابراهيم باشا، مستغلِّين العديدَ من الأسباب، سواء كانت دينية، أو اقتصادية، خصوصًا بعد أن ضيَّق إبراهيم باشا الخناقَ على المسلمين في حين مَنَحَ حرياتٍ واسعةً للنصارى واليهود، لقد فتح إبراهيم باشا البابَ على مصراعيه لدخول البَعَثات التبشيرية الفرنسية والأمريكية، وألغى كافَّةَ القوانين الاستثنائية وجميعَ ما كان يسري على النصارى وَحدَهم، ويَعتَبِر بعضُ الكتَّاب أن عام 1249هـ / 1834م عامَ تحوُّلٍ تاريخي؛ حيث عاد اليسوعيون، وتوسَّعت البَعَثات الأمريكية، وتمَّ نَقلُ مطبعة الإرسالية الأمريكية من مالطة إلى بيروت، وأُسِّسَت مدرسة للبنات في بيروت على يد \"إيلي سميث\" وزوجته، وزُوِّدَت بعض الأديرة بمطابِعَ أخرى في إطار حرص الدول الأوروبية على حَصرِ المطابِعِ في يد المسيحيين فقط؛ حتى تتمكَّنَ من تحقيق أهدافِها، في ظِلِّ عَجزِ المسلمين عن امتلاكِ وسيلة التعبير عن آرائِهم، أو نشر أفكارهم في هذا المجال!!"},{"id":4457,"title":"خروج مشاري بن عبد الرحمن على خاله تركي بن عبد الله .","date":["العام الهجري :1246","العام الميلادي :1830"],"text":"بينما كان الإمامُ تركي غازيًا في الشمال خرج مشاري بن عبد الرحمن من الرياض مغاضِبًا لخاله الإمام تركي بن عبد الله، فبحث عمَّن يَنصُرُه عند مطيرٍ ورؤساء أهل القصيم وعنزة، وأخيرًا شريف مكة محمد بن عون، فلم يجِدْ منهم من ناصره، فعاد إلى الرياض نادمًا سنة 1248هـ وطلب من خالِه العفو فعفا عن وأكرمه، وأسكنه في بيتٍ عنده، وحجز النَّاسَ عن زيارته."},{"id":4458,"title":"احتلال فرنسا للجزائر .","date":["العام الهجري :1246","الشهر القمري : محرم","العام الميلادي :1830"],"text":"قامت فرنسا باحتلالِ الجزائر، وكان سببُ ذلك رفْضَ \"الباشا حسين\" تقديمَ اعتذارٍ إلى قنصل فرنسا، وكان القنصلُ الفرنسي قد أساء معاملةَ الباشا، فأشار الباشا بمروحةٍ في يده على وجهِ القنصل, فاعتبرها الفرنسيون إهانةً لفرنسا، فأمر مَلِكُ فرنسا بضرورةِ احتلال إقليمِ الجزائر، فأرسلت الحكومةُ الفرنسية جيشًا من 28 ألف مقاتل وأسطولًا يضم مائة سفينةٍ، وثلاثة سفن تحمل 27 ألف جندي بحري، ونزلت بالقرب من مدينة الجزائر، وبعد قتالٍ عنيف دخلوا مدينةَ الجزائر وواجهَتْهم المقاومة الجزائرية بقيادة عبد القادر الجزائري، حتى استسلم في رجب من عام 1263هـ وسيطرت فرنسا على الإقليمِ، وإن بقيت المقاومةُ تَظهَرُ مِن وقتٍ لآخر."},{"id":4459,"title":"استيلاء الاستعمار الفرنسي على الأوقاف الإسلامية بالجزائر .","date":["العام الهجري :1246","الشهر القمري : ربيع الأول","العام الميلادي :1830"],"text":"بدأ الاستعمارُ الفرنسيُّ في وَضعِ يَدِه على الأوقافِ الإسلامية بالجزائر، وانتهى الأمرُ بتصفية تلك الأوقاف لصالحِ الاستيطانِ الفرنسيِّ."},{"id":4460,"title":"خروج الإمام تركي بن عبد الله لمناطق الشمال .","date":["العام الهجري :1246","الشهر القمري : شعبان","العام الميلادي :1831"],"text":"سار الإمامُ تركي بن عبد الله بجميعِ رعاياه من أهلِ وادي الدواسر والأحساء والوشم وسدير والقصيم وجبل شمر وعربانهم، فقصد الشمالَ، ووافق فهيدًا الصييفيَّ رئيسَ سبيع -الذي كان يُعلِنُ عداوته للسعوديين منذ أيام سعود بن عبد العزيز- وأتباعَه، فصبَّحَهم وأخذهم، فلما حاز أموالهم ذكروا أنَّ لهم عنده ذمَّةً وعهدًا، فردَّ عليهم جميع ما أُخِذَ منهم، ثم سار ونزل على ماء الصبيحة قربَ الكويت، فأرسل إليهم رئيس الكويت جابر بن عبد الله الصباح بهدايا، ومكث الإمام تركي على ماءِ الصبيحة أكثر من 40 يومًا، وفد عليه كثيرٌ مِن رؤساء العربان، ثم بلغه هروب مشاري بن عبد الرحمن خارجًا عليه من الرياضِ مُغاضِبًا له، فعاد الإمام إلى الرياض."},{"id":4461,"title":"وباءٌ في مكة يسمى أبو زويعة .","date":["العام الهجري :1246","الشهر القمري : ذي القعدة","العام الميلادي :1831"],"text":"وقع وباءٌ وموتٌ عظيم في مكة، وهو الوباء المعروف بـ أبو زويعة (العقاص) وأوَّل ما وقع فيها قبل قدومِ الحاجِّ، ومات منه فئامٌ مِن الناس ثم ارتفع عنها مع دخول ذي الحجة، فلما كان يومُ النحر حلَّ الوباء والموت العظيم ثانيًا في الحاجِّ وغيرِهم، وقيل: لم يبقَ من حاج الشامِ إلا قدرُ ثلُثِه، ومن حاجِّ أهل نجد من كلِّ بلد هلك بعضُهم نصفُه، وبعضهم أقل أو أكثر، وأُحصي من مات من أهل مكة فكانوا 16 ألف نفسٍ، ولَمَّا قَدِمَ الحاج الشامي المدينةَ بالليل راجعًا من مكة وقع الموتُ في الناس وقتَ السَّحَرِ، وحل بهم أمرٌ عظيمٌ، فخرج أهل المدينة بالنساء والأطفال وتضرَّعوا في حرَمِ النبي صلى الله عليه وسلم، حتى رفع اللهُ عنهم البلاء."},{"id":4462,"title":"الحملة المصرية تدخل الأناضول ومعاهدة كوتاهية مع محمد علي  .","date":["العام الهجري :1247","العام الميلادي :1831"],"text":"استطاع إبراهيم باشا أن يستوليَ على بلاد الشام جميعِها ويهزِمَ جيشَ حسين باشا من قِبَلِ الخليفة العثماني، فتابع إبراهيمُ سيرَه باتجاه الأناضول فجهَّز الخليفةُ أيضًا جيشًا آخر بقيادة رشيد باشا الذي التقى مع إبراهيم قرب قونية بعد أن اجتاز إبراهيم جبالَ طوروس، واحتَلَّ أضنة، وانتصر إبراهيم باشا وأخذ القائِدَ رشيد باشا أسيرًا، وأصبحت أبوابُ استانبول مفتوحةً أمامه، فخَشِيَت الدول الأوربية أن يتوغَّلَ أكثر من ذلك خوفًا على مصالحِهم، وكان أكثرُهم خوفًا روسيا التي عَرَضت الدعمَ، فأرسلت خمسة عشر ألفَ مقاتل لحمايةِ استانبول، فخافت إنكلترا وفرنسا أيضًا من أن تحظى روسيا بمفردها بالنفوذِ، فطلبوا من الخليفة التفاهُمَ مع محمد علي باشا، فكانت معاهدة كوتاهية في عام 1248هـ التي أوقفت تقَدُّمَ إبراهيم باشا عن دخولِ الأناضول."},{"id":4463,"title":"طاعون عظيم يعم العراق وما حوله .","date":["العام الهجري :1247","العام الميلادي :1831"],"text":"وقع الطاعونُ العظيم الذي عَمَّ العراق والسواد والمجرة وسوق الشيوخ والبصرة والزبير والكويت وما حولها، وليس هذا مِثلَ الوباء الذي قبله المسمى العقاص (أبو زويعة)، بل هذا هو الطاعونُ المعتاد -نعوذ بالله من غضبه وعقابه- وحَلَّ بهم الفَناءُ العظيم الذي انقطع منه قبائل وحمائل، وخلت من أهلها منازلُ، وإذا دخل في بيتٍ لم يخرج منه وفيه عينٌ تطرفُ، وجثا الناسُ في بيوتهم لا يجِدون من يدفنهم، وأموالهم عندهم ليس لها والٍ، وأنتنت البلدانُ مِن جِيَف الناسِ، وبقيت الدواب والأنعام سائبةً في البلدان ليس عندها من يعلِفُها ويسقيها حتى مات أكثَرُها! ومات بعض الأطفال عطشًا وجوعًا، وخر أكثرهم في المساجد صريعًا، لأنَّ أهاليهم إذا أحسُّوا بالألم رموهم في المساجِدِ، رجاء أن يأتيَهم من ينقِذُهم، فيموتون فيها؛ لأنه لا يأتيها أحدٌ ولا يقام فيها جماعةٌ!! وبقيت البلدان خاليةً لا يأتي إليها أحدٌ، وفيها من الأموال ما لا يحصى عَدُّه إلَّا اللهُ."},{"id":4464,"title":"وفاة ابن لعبون أمير شعراء النبط .","date":["العام الهجري :1247","العام الميلادي :1831"],"text":"هو الشاعرُ المشهور محمد بن جمد بن محمد ابن لعبون بن  مدلج الوايلي البكري العنزي، أمير شعراء النبط، ولِدَ في بلدة حرمة بنجد سنة 1205هـ وحَفِظَ بها القرآن وتعَلَّم الكتابة، وكان خطُّه فائقًا. ونَظَم الشعرَ في صغرِه. ومال إلى اللهوِ والبطالة. ورحل إلى الزبير في العراق، ساعده ذكاؤه  الشِّعري وشخصيتُه المَرِحة الطَّرِبة في توطيدِ علاقاته مع كثيرٍ مِن وجهاءِ وأعيان نجد والزبير والكويت والأحساء والبحرين والهند، وورد في شعره ذِكرُ كِبارِ شخصيات عصره، كان شعره جيدًا إلَّا أن فيه تخبيطًا في العقيدةِ، وقيل: إنه أنشأ قصيدةً تاب فيها وتضَرَّع إلى الله. قصَدَ الكويت فمات فيها بالطاعون."},{"id":4465,"title":"تعيين علي باشا واليا على بغداد .","date":["العام الهجري :1247","العام الميلادي :1831"],"text":"قَدِمَ علي باشا واليًا على بغداد مِن جهةِ السلطان محمود العثماني، وعَزَلَ داود أفندي، وأشخصه إلى استانبول، واستولى على خزائنِه، وكان داود شغوفًا بجمع الأموال ومصادرةِ الرجال وأخذ أموالهم."},{"id":4466,"title":"عمال الإمام تركي بن عبد الله يجبون الزكاة من نواحي نجد .","date":["العام الهجري :1247","العام الميلادي :1831"],"text":"سار الإمامُ تركي بن عبد الله غازيًا من الرياض بجميعِ غَزوِه من نواحي رعاياه، ونزل الرمحية -الماء المعروف في العرمة- وأقام فيها نحو 40 يومًا ووفد عليه كثيرٌ من رؤساء العُربان من أهل الشمال، وأتاه كثيرٌ مِن الهدايا من رؤساءِ الظفير والمنتفق وغيرهم، وأتى إليه مكاتباتٌ من علي باشا والي بغداد، ثم بعث الإمام عمالَه لعُربان نجد يقبِضون منهم الزكاةَ، فكُلُّهم سَمِعوا وأطاعوا وأدَّوا الزكاة سوى العجمان، ثم رحل إليهم من موضِعِه الذي كان فيه، فلما بلغهم قدومُه عليهم، دفعوا الزكاةَ لعُمَّالِه."},{"id":4467,"title":"إصدار السلطان العثماني أمرًا بإلغاء حامية الإنكشارية في تونس .","date":["العام الهجري :1247","الشهر القمري : صفر","العام الميلادي :1831"],"text":"أصدر السلطانُ العثماني محمود الثاني أمرًا إلى والي تونس حسين باشا بأن يُلغي حامية الانكشارية الموجودة في إيالته، وأن يطبق القوانين التي شرَعَها السلطان لتحديثِ الدولة العثمانية."},{"id":4468,"title":"ظواهر غريبة في الأفق بنجد .","date":["العام الهجري :1247","الشهر القمري : صفر","العام الميلادي :1831"],"text":"حصل في السماء تغييرٌ عند طلوع الشمس وعند غروبها؛ ففي آخر صفر ليلة خمس وعشرين وست وعشرين منه، صار في السماء والأرض نورٌ قريبٌ من نور القمر، واستمَرَّ إلى آخر الشهر، فلما كان سابع ربيع الأول صار قَترٌ في السماء وتغيرت الشمسُ، وفي أول العشر الأواخر من هذا الشهر ظهرت الشمسُ مِن المشرق خضراءَ كأنَّها قطعةُ زجاج وصارت تلك الخُضرةُ في الجدران والأرض، وحسبها الناس كسوفًا! وفي هذا الشهر صار في الأُفقِ حُمرةٌ زائدة بعد غروب الشمس وقبل طلوعها، واستمَرَّ أيامًا، وشوهِدَ قبل انفلاق الصبح حمرةٌ بادية من جهة الشمال ليس من جهة الفجر نحو ثلاثة أيام، وفي النصف من هذا الشهر بعد صلاة المغرب ظهر من الأفق حمرةٌ عظيمة من جهة الجَدْي، ثم سارت إلى المغرب وأضاءت الأرض والجدران، واخضرَّت واحمَرَّت، حتى ظن الناسُ أن الشمس لم تغرب. وفي ربيعٍ الثاني في أوله اجتمع من السياراتِ خمسةٌ في برج الأسد (الشمس والقمر، والمريخ وزحل وعطارد)."},{"id":4469,"title":"عودة القائد العثماني البحري \"كوجاك مراد رئيس\" إلى الجزائر .","date":["العام الهجري :1247","الشهر القمري : ربيع الأول","العام الميلادي :1831"],"text":"عاد القائدُ العثماني البحري \"كوجاك مراد رئيس\" إلى الجزائر مع 12 سفينة عثمانية، وذلك بعد قيامه بغارة بحرية على موانئ إيرلندا، وأسَرَ خلالها 400 شخص، وقد استغرقت هذه الحملةُ إلى حين عودتها 3 أشهر."},{"id":4470,"title":"حصول جزيرة سيسام على استقلالها الذاتي عن الدولة العثمانية .","date":["العام الهجري :1247","الشهر القمري : رجب","العام الميلادي :1831"],"text":"حصلت جزيرةُ سيسام القريبةُ من سواحل الأناضول على استقلالِها الذاتيِّ عن الدولةِ العثمانيةِ، وذلك مقابِلَ مبلغٍ مِن المال تدفعُه سنويًّا للعثمانيين، وتبلُغُ مساحةُ هذه الجزيرة 550 كم2، وقد ضمَّتْها اليونان إليها عام 1913م."},{"id":4471,"title":"فتح إبراهيم باشا بن محمد علي عكا .","date":["العام الهجري :1247","الشهر القمري : ذي الحجة","العام الميلادي :1832"],"text":"نجح إبراهيم باشا بن محمد علي باشا في فتح عكا بعد حصار دام ستة أشهر، وكان لسقوطِها دويٌّ هائِلٌ على الدول الأوروبية، ولفتت الأنظارَ إلى عبقرية إبراهيم باشا وأركان حَربِه سليمان باشا الفرنساوي. وتجدُرُ الإشارةُ هنا إلى أن نابليون بونابرت القائِدَ الفرنسي كان قد عجز عن اقتحامِها قبل ذلك أثناء حملتِه على مصر والعالمِ الإسلاميِّ."},{"id":4472,"title":"عمر بن عفيصان أميرًا على الأحساء وعمان .","date":["العام الهجري :1248","العام الميلادي :1832"],"text":"كتب الإمام تركي بن عبد الله إلى عُمَرَ بنِ محمد بن عفيصان أمير الأحساء يتجهَّزُ برجالٍ معه إلى عمان؛ ليصير أميرًا للجميع، فسار إلى عمان وفتح بلدانًا وأخذ عربانًا."},{"id":4473,"title":"برد عظيم أضر بالنخيل في نجد .","date":["العام الهجري :1248","العام الميلادي :1832"],"text":"وقَعَ بردٌ شديدٌ في نجدٍ أضَرَّ بالنخلِ وقطرت العسبان دبسًا مِن شدة البرد، فلما جاء الصيفُ بان الخَلَلُ في النخيل ويَبِس أكثر عسبانها، وأما الزرع والقتُّ والنبات فضرَرُه قليل، ثم حصل في السنة التالية بردٌ أعظم من الأول حتى تجمَّد الماء في السواقي والزروع وبين الميزاب والأرض، وأضَرَّ بالنخل، وفي هاتين السنتين ما اختَلَّ حمل النخل، بل كان على معتاده، فلما كانت سنة الخمسين لم يحمِل النخلُ إلا بنصفِ حملِه."},{"id":4474,"title":"وفاة فيصل بن وطبان الدويش رئيس مطير .","date":["العام الهجري :1248","العام الميلادي :1832"],"text":"هو فَيصلُ بن وطبان بن محمد الدويش الملقَّب بالأكوخ، شيخ قبيلة مطير. تولى المشيخة من عام 1205هـ. انضَمَّ مع القوات العثمانية بقيادةِ إبراهيم باشا في الاستيلاءِ على مدن القصيم والعارض وحصار الدرعية، وكان سببُ انضمامه قتل 12 رجلًا من شيوخ مطير وأقربائه من قِبَلِ عبد الله بن سعود، وكان له مراسلات عديدةٌ مع إبراهيم باشا"},{"id":4475,"title":"ظواهر غريبة في أفق نجد .","date":["العام الهجري :1248","الشهر القمري : جمادى الآخرة","العام الميلادي :1832"],"text":"قال ابن بشر: \"في ليلة الثلاثاء 19 جمادى الآخرة بعدما مضى نصفُ الليل تطايرت النجومُ في السماء كأنها الجرادُ، وكأنها شُعَل النار وقدح الزند من جميع جهاتِ السماء كلها شرقًا وغربًا، وشمالًا وجنوبًا، وصار فيها شهبٌ عظيمة تنقض وتضيء بالأرضِ، ويبقى موضع الشهاب ساعةً لا يزول، وانزعج الناس لذلك، واستمر إلى بعد اسفرارِ الصبحِ حتى ستره النهارُ، وأخبرني من أثِقُ به أنه رأى شهبًا تنقض بعدما طلعت الشمسُ يراها كأنَّها الدخان\"."},{"id":4476,"title":"مبايعة عبد القادر الجزائري بإمارة الجهاد .","date":["العام الهجري :1248","الشهر القمري : جمادى الآخرة","العام الميلادي :1832"],"text":"بويع القائِدُ الجزائري عبد القادر بإمارةِ الجهاد في بلاده، والتَفَّ حولَه كُلُّ المجاهدين، وقد دخل بعد ذلك مدينةَ تلمسان."},{"id":4477,"title":"الإمام تركي بن عبد الله يعتقل فلاح بن حثلين ويسجنه في الرياض .","date":["العام الهجري :1248","الشهر القمري : شوال","العام الميلادي :1833"],"text":"سار الإمامُ تركي بن عبد الله بجنودِه من جميع الرعايا من أهلِ نجدٍ باديها وحاضرها، وعدا على فلاح بن حثلين وعُربانه من العجمان وأخلاطِ مَن معهم من العربان، فسبق إليهم النذيرُ، فانهزم ابن حثلين ومن معه من منزلهم قربَ أم الربيعة، فنزل الإمام تركي في نفس المكان فرجع إليه المرضف شيخُ آل مرة وأتباعه، وصالحه على نفسه ومن تَبِعَه من العُربان، فلما عَلِمَ ابن حثلين بذلك داخَلَه الرُّعبُ، فركب قاصدًا تركيًا، وألفى عليه بلا ذمَّةٍ ولا عهدٍ، فقَيَّده الإمام بالحديدِ، ثم أرسله في قيوده إلى الرياض واعتقَلَه فيه."},{"id":4478,"title":"الإمام تركي بن عبد الله يحذر الأمراء والرؤساء من ظلم الرعية .","date":["العام الهجري :1248","الشهر القمري : ذي القعدة","العام الميلادي :1833"],"text":"لما رجع الإمامُ تركي من بعض غزواته وخرج من الدهناء ونزل غدير وثيلان، أمَرَ على رؤساء النواحي وأمرائهم أن يجتمعوا عنده، فلما حضروا قام فيهم مذكِّرًا بنعمة الاجتماع بعد الفُرقةِ، ثم أغلظ الكلام على الأمراء وتهدَّدهم وتوعَّدَهم عن ظلم الرعايا وقال: \" اسمَعوا يا أمراء البلدان، اسمعوا يا أمراء المسلمين، إياكم وظلمَ الرعايا والأخذ منهم غير الحقِّ، فإذا ورد عليكم أمري بالمغزى حملتموهم زيادةً لكم إياكم، وذلك فإنه ما منعني أن أجعل على أهل البلدان زيادة ركاب لغزوهم إلَّا من أجل الرفقِ بهم، وإني ما حمَّلتُهم إلا بعضَ ما حمَّلهم الذي قبل... ثم تكلم للرعايا فقال لهم: أيُّما أمير ظلمكم فأخبروني، فقام أمير بريدة عبد العزيز بن محمد بن عبد الله بن حسن فقال: يا إمامَ المسلمين خُصَّ بقولك ولا تعُمَّ به، فإن كنت نقمت على أحدٍ مِنَّا فأخبره بفِعلِه, فقال: إنما القولُ فيك وأمثالك، تحسبون أنكم ملكتم البلد بسيوفِكم، وإنما أخذها لكم وذَلَّلها سيفُ الإسلامِ والاجتماع على الإمام\"."},{"id":4479,"title":"توقيع اتفاقية \"كوتاهية\" بين محمد علي باشا والدولة العثمانية .","date":["العام الهجري :1248","الشهر القمري : ذي الحجة","العام الميلادي :1833"],"text":"تمَّ توقيعُ اتفاقية \"كوتاهية\" بين محمد علي باشا والدولة العثمانية بعد حروبٍ دامية بينهما، بتدخُّلٍ من روسيا وبريطانيا وفرنسا؛ للحِفاظِ على مصالحِهم، واتفق الطرفان على أن تتخلى الدولةُ العثمانيةُ لمحمد علي عن سوريا وإقليم أضنة، ونَصَّت المعاهدة على أن تتراجَعَ جيوش محمد علي عن إقليمِ الأناضول إلى ما بعد جبالِ طوروس، مع تثبيت محمَّد علي في ولاية مصر مدَّةَ حياته له ولنَسلِه، ويُعطى معها الشام وكريت والحجاز، فيُعَيِّن محمد علي واليًا مِن قِبَلِه على ولاياتِ الشام الأربع: عكا وطرابلس ودمشق وحلب، وعلى جزيرة كريت أيضًا، ويعين إبراهيم بن محمد علي واليًا على إقليم أضنة، وهو الإقليم المتاخِم للأناضول."},{"id":4480,"title":"محمد علي ينشئ الدولة المصرية الحديثة .","date":["العام الهجري :1249","العام الميلادي :1833"],"text":"تمكَّن محمد علي أن يبنيَ في مصر دولةً عصرية على النَّسَق الأوروبي، واستعان في مشروعاتِه الاقتصادية والعِلميَّةِ بخبراء أوروبيين، ومنهم بصفة خاصة السان سيمونيون (أتباع سان سيمون الفيلسوف والاقتصادي الفرنسي) الفرنسيون، الذين أمضَوا في مصر بضعَ سنوات في الثلاثينيات من القرن التاسع عشر، وكانوا يَدعُون إلى إقامة مجتمع نموذجيٍّ على أساسِ الصناعة المعتَمِدة على العلم الحديث. وكانت أهمُّ دعائِمِ دولة محمد علي العصرية: سياستُه التعليميَّة والتثقيفية الحديثة؛ فإنَّه طَفِقَ منذ 1809م بإرسالِ بعثات تعليمية إلى مدن إيطالية (ليفورنو، ميلانو، فلورنسا، وروما) لدراسةِ العلوم العسكرية، وطُرُق بناء السفن، والطباعة. وأتبعها ببعثاتٍ لفرنسا، ولأول مرة أصبح التعليمُ منهجيًّا. فأنشأ المدارسَ التقنيةَ ليلتَحِقَ خرِّيجوها بالجيش. وأوجد زراعاتٍ جديدة، كالقطن، وبنى المصانع واعتنى بالريِّ، وشيَّد القناطِرَ الخيرية على النيل عند مصَبَّي فرعي دمياط ورشيد. ولما استطاع محمد علي القضاءَ على المماليك ربط القاهرة بالأقاليمِ، ووضع سياسةً تصنيعية وزراعية موسَّعة، وضبط المعاملاتِ الماليةَ والتجاريةَ والإدارية والزراعية لأولِ مرة في تاريخ مصرَ."},{"id":4481,"title":"أهل عسير يستولون على بلدة المخا في اليمن ويُخرجون الترك منها .","date":["العام الهجري :1249","العام الميلادي :1833"],"text":"سار أهلُ عسير وألمع وجنودُهم من أهلِ اليمن على بلدة المخا في اليمن، وقد أخذها التركُ ومَلَكوها، فلَبِسَ من عسير وأتباعهم قدرُ ألفي رجلٍ أكفانَهم وقصدوا أسوارَها وتسوَّروا جدرانها، وقُتِلَ كثيرٌ فوق السور، فلم يَثنِ عَزمَ الباقين، فأخذوا البلدَ عَنوةً من أيدي الترك وغنموا أموالًا لا تحصى."},{"id":4482,"title":"توقيع معاهدة \"خونكار أسكله سي\" بين الدولة العثمانية وروسيا. .","date":["العام الهجري :1249","الشهر القمري : محرم","العام الميلادي :1833"],"text":"عُقِدَت اتفاقيَّةٌ جانبية بين الدولة العثمانية وروسيا باسم (خونكار أسكله سي) تعهَّدت فيها روسيا بالدفاع عن الدولة ضِدَّ جيوش محمد علي أو أي معتدٍ آخر، وبذلك أصبح بإمكانِها التدخل في شؤون الدولة الخاصة وقتما تريد. وتُعتَبَرُ هذه المعاهدة قمةَ النفوذ الروسي في الدَّولةِ العثمانية والتي نَصَّت على: عقدِ تحالفٍ بين الدولة العثمانية وروسيا. عقدِ اتفاقية دفاعٍ مُشترك بين الدولة العثمانية وروسيا. مَنحِ روسيا حقَّ حماية الرعايا النصارى في البلقان. وحماية الأراضي المقدسة. وحق حرية الملاحة في المضائق والمياه العثمانية, وإغلاقها أمامَ السفن الحربية الأوروبية. وقد استمرت هذه المعاهدةُ لمدة ثماني سنواتٍ."},{"id":4483,"title":"فشل القوات الفرنسية في اقتحام بلدة بليدة الجزائرية. .","date":["العام الهجري :1249","الشهر القمري : رجب","العام الميلادي :1833"],"text":"حاولت القواتُ الفرنسيّةُ في بداية الاحتلال الفرنسي للجزائر اقتحامَ بلدة بليدة الجزائرية، فقاوم سكانُها ذلك مقاومةً باسلة، بفَضلِ الله تعالى، وفَشِلَت القواتُ الفرنسية في مسعاها."},{"id":4484,"title":"انسحاب الجيش الروسي من رومانيا بعد احتلالها .","date":["العام الهجري :1249","الشهر القمري : رمضان","العام الميلادي :1834"],"text":"انسحَبَ الجيش الروسي من رومانيا بعد خمسِ سَنواتٍ ونصف من احتلالها، وكانت رومانيا تَتْبَع في تلك الفترة الدولةَ العثمانية، لكِنَّ الروس احتلوها أثناءَ حَربِهم مع العثمانيين عام 1828م."},{"id":4485,"title":"معاهدة بين عبد القادر الجزائري والقائد الفرنسي دي ميشيل .","date":["العام الهجري :1249","الشهر القمري : شوال","العام الميلادي :1834"],"text":"وقَّع الأمير عبد القادر الجزائري مُعاهدةً مع القائد الفرنسي دي ميشيل، بوهران بعد اضطرار الفرنسيين للتحاوُرِ مع الأمير الذي أمر بمنعِ أي معاملةٍ تجارية مع الغزاة, وبحَسَبِ المعاهدة فإن فرنسا قد اعترفت بإمارةِ عبد القادر على الغَربِ الجزائري عدا وهران وأرزيو ومستغانم. لكِنَّ تطبيق المعاهدة واجهَ صعوباتٍ عدة، وكان من نتائِجِها وقفُ القتال بين الطرفين، والقيامُ بتبادُلِ الأسرى بينهما."},{"id":4486,"title":"وفاة الإمام تركي بن عبد الله بن سعود وتولي ابنه فيصل الحكم من بعده .","date":["العام الهجري :1249","الشهر القمري : ذي الحجة","العام الميلادي :1834"],"text":"هو الإمامُ تركي بن عبد الله بن محمد بن سعود بن محمد بن مقرن، من أمراءِ نجد، وَلِيَها بعد مقتل ابنِ عَمِّه مشاري بن سعود. كان تركي بن عبد الله فارًّا من وجه التُّرك وعُمَّال والي مصر محمد علي، في الخَرجِ بنجد، وعلم بأنَّ مشاري بن معمر قبض على ابنِ عَمِّه مشاري وسَلَّمه إلى الترك فقَتَلوه، فخرج من مخبئه ودخل العارضَ فنازع ابن معمر برهةً مِن الزمن، ثم قتَلَه بابن عمه، وتولى الحكمَ مكانه. وبولايةِ تركي بن عبد الله انتقل الحكمُ في آل سعود من سلالةِ عبد العزيز بن محمد بن سعود إلى سلالة أخيه عبد الله بن محمد بن سعود، وكان تركي شجاعًا؛ أخذ على عاتقه إخراجَ الترك ومَن معهم من المصريين عن بلادِه، فاستردَّ الأحساء والقطيف، وصالحَه أميرُ حائل، وانبسط نفوذُه في القصيم. واستمَرَّ إلى أن قام مشاري بن عبد الرحمن ابن أخت تركي بن عبد الله -وهو ابنُ عمه أيضًا- بقَتلِه غدرًا، قال ابن بشر: \"عزم مشاري على إظهارِ ما أبطن وجَرَّد سيفه لإثارة الفِتَن، وذلك بمساعدة رجالٍ أسافِلَ مِن الخدمِ الأراذلِ، وقد تواعدوا عليه بعد صلاةِ الجمعة إذا خرج من المسجِدِ، فلما صلى الجمعة وخرج.. من المسجدِ، وقف له البغاة عند الدكاكين بين القصر والمسجد، وبيده مكتوبٌ يقرؤه، وفي جنبه رَجُلٌ على يساره، واعترضهم منهم عبدٌ خادم لهم يقال له إبراهيم بن حمزة، فأدخل الطبنجة مع كُمِّه وهو غافِلٌ فثورها فيه، فخَرَّ صريعًا، فلم تخط قلبه، وإذا مشاري قد خرج من المسجد فشَهَر سيفَه وتهدَّد الناس وتوعَّدَهم، وشهر أناسٌ سُيوفَهم معه فبُهِتَ الناس وعَلِموا أن الأمر تشاوروا فيه وقُضِيَ بليلٍ، فلما رأى زويد العبد المشهور مملوكُ تركي عمَّه صريعًا، شهر سيفه ولَحِقَ برجلٍ من رجاجيل مشاري فجَرَحَه.. ثم إن مشاري دخل القصرَ من ساعته وأعوانه معه.. وجلس للناسِ يدعوهم إلى البيعةِ، فلما علم آلُ الشيخِ وقوعَ هذا الأمر جلسوا في المسجد، فلم يخرجوا منه حتى أرسل إليهم مشاري يدعوهم فأبَوا أن يأتوا إلا بالأمانِ، فكتب لهم بالأمان، فأتوا إليه وطلب منهم المبايعةَ فبايعوه، ثمَّ نُقِلَ تركي من موضعه ذلك، وأدخلوه بيت زويد فجُهِّزَ وصلى عليه المسلمون بعد صلاة العصر، ودُفِنَ في مقبرة الرياض آخر ساعة من يوم الجمعة\"، وكان قتلُ تركي بن عبد الله على يد ابن عمه مشاري بن عبد الرحمن أوَّل جريمةٍ مِن نوعِها في آل سعود.  وكان ابنُه فيصل في القطيف على رأس جيشٍ، فلما علم بمقتلِ أبيه رجع من فوره واستطاع أن يقتُلَ مشاري، ثم يتولى الإمامةَ والحُكمَ."},{"id":4487,"title":"العساكر المصرية مع شريف مكة تغزو عسير  .","date":["العام الهجري :1250","العام الميلادي :1834"],"text":"سارت العساكِرُ المصرية وملأت السَّهلَ والجبل لمحاربةِ عسير في بلدان اليمن، ومعهم أحمد باشا وشريف مكة محمد بن عون، فلمَّا وصلوا بلادهم أرسلوا إليهم أنَّهم ما يريدون منهم إلَّا رسمَ الطاعة، وأنهم ما أتوا إلا للصلاحِ، فأطاع لهم عسير، وجعلوا في ثغورِ بلادهم عسكرًا، فلما تمكَّنوا من بلادهم طلبوا منهم أموالًا ونِساءً، فأجمع رأيُ رؤساء عسير أن يجمَعوا شوكَتَهم وعَدَدَهم وعُدَّتَهم، وينفرون عليهم ويسيرون معهم بنسائِهم وأبنائِهم حتى لا يَفِرُّوا، والترك إذا رأوهم على ذلك لا يخافون لأنَّهم لا يعلمون أنَّهم جاءوا لحرب، وأنَّهم ما جاؤوا إلا ليعرضون ويلعبون عندهم، فقامت العساكِرُ تطَّلِعُ عليهم وتنظُرُ إليهم، وهم مُقبِلون يلعبون ويرمون، والعساكِرُ يَضحَكون، فلما دنوا منهم حَمَلوا عليهم حملةً واحدة صادقة، ووضعوا فيهم السِّلاحَ، فولت العساكِرُ مُنهَزمةً وقتلوا فيهم قتلًا ذريعًا، وأخذوا خيامَهم ومدافِعَهم وأموالَهم، حتى قيل: إنه لم يبقَ منهم إلا نحو 150 قصدوا البندر، وقصَدَ ابنُ عون وأحمد باشا مكَّةَ بشرذمة قليلة، وأرسل أهل عسير إلى الإمام فيصل شيئًا من سلاحهم وخَيلِهم، ثم قام كل أهلِ بلدٍ من عسير على من عندهم من عساكِرِ الترك في بلَدِهم فقَتلوهم!"},{"id":4488,"title":"فيصل بن تركي يقتل مشاري بن عبد الرحمن ويسترد الحكم منه .","date":["العام الهجري :1250","الشهر القمري : محرم","العام الميلادي :1834"],"text":"لما بلغ فيصلًا خَبَرُ مقتل والده، جمع الأمراء والرؤساء الذين معه في الغزو، وهم رئيس جبل شمر: عبد الله بن علي بن رشيد، ورئيس بريدة: عبد العزيز بن محمد، ورئيس الحريق: تركي الهزاني، وحمد بن يحي أمير بلدان سدير، وغيرهم من الرؤساء والرجال، ورؤساء العربان، أخبَرَهم بمقتل والده فوعَظَهم وذكَّرَهم، فبايعوه جميعًا على السمعِ والطاعةِ، ثم رحل مِن الأحساء بجنوده وأمرائِه إلى الرياض فدخلها وحاصَرَ مشاري في قصرِ الرياضِ، حتى تمكَّن من قَتلِه بعد أن تخاذَلَ عنه كثيرٌ مِن أهل الرياض، فلمَّا قُتِلَ مشاري دخل فيصل القصرَ وجلس على سريرِ المُلكِ، فوفد عليه أمراء البلدان ورؤساء العربان من كلِّ جهةٍ، فبايعوه، وأقر القضاةَ على أعمالِهم في بلدانهم."},{"id":4489,"title":"وفاة الشاه فتح الله شاه زعيم القاجاريين في إيران .","date":["العام الهجري :1250","الشهر القمري : رجب","العام الميلادي :1834"],"text":"هو الشاه فتح علي شاه قاجار زعيم القاجاريين الشيعة في إيران. ولِدَ سنة 1772 وكان فتح علي ثاني شاه قاجاري على فارس. وقد حكم من 17 يونيو 1797 حتى وفاته. وقد شَهِدَ عهده فقدانَ إيران بالقوة -وبغير رجعة- أراضيَها الشمالية؛ الأراضي القوقازية التي تضمُّ جورجيا، داغستان، أذربيجان، أرمنيا، لصالح روسيا القيصرية إثرَ الحرب الروسية الفارسية (1804-1813)، الحرب الروسية الفارسية (1826-1828) والمعاهدتين اللتين أُبرِمتا في عَقِبَيهما: معاهدة ولستان، ومعاهدة تركمانچاي. توفي الشاه فتح علي بعد أن هزل من المرض كثيرًا، عن عمر يناهز 64 عامًا، ودام في الملك ستًّا وثلاثين سنة، فخَلَفَه في الملك محمد شاه ميرزا بن عباس ميرزا، الذي كان ولي العهد قبل وفاة والده بسنة، وكان جلوسه على العرش في السابع من رجب من سنة 1250هـ، فثار عليه أعمامُه، فانتصر عليهم وقبض على صولجان الملك، فصار يدعى محمد شاه."},{"id":4490,"title":"وفاة الشيخ حسن بن محمد العطار شيخ الجامع الأزهر .","date":["العام الهجري :1250","الشهر القمري : ذي القعدة","العام الميلادي :1835"],"text":"هو الشَّيخُ علَّامةُ مِصرَ: أبو عليٍّ حسن بن علي محمد بن محمود العطار، شيخ الجامع الأزهر، وهو الشيخ السادس عشر في سلسلة شيوخ الأزهر، أصله من المغرب. ولد بالقاهرة سنة 1180 هـ، كان أبوه الشيخ علي محمد العطار فقيرًا يعمل عطَّارًا، من أصل مغربي، وكان له إلمامٌ بالعلم، وكان حسن يساعِدُه في دكانه، ولَمَّا رأى منه حبًّا للعلم وإقبالًا على التعَلُّم، شجعه على طلب العلم،، كان طويلًا بعيدَ ما بين المنكِبَين واسِعَ الصدر، أشم أسمر اللون خفيف اللحية صافي العينين، حاد النظر، حاد الفطنة، شديد الذكاء. جَدَّ في التحصيلِ حتى بلغ من العِلمِ في زمنٍ قليلٍ مبلغًا تميَّزَ به واستحق التصديَ للتدريس، ولكنَّه مال إلى الاستكمال، واشتغل بغرائبِ الفنون والتقاط فوائدها، كالطب والفلك والرياضة. عندما احتل الفرنسيون مِصرَ سنة 1798 كان حسن العطار في الثانية والثلاثين من عمره، ومِثلَ كثيرٍ مِن العلماء في ذلك الحين فَرَّ إلى الصعيد خوفًا على نفسِه من أذاهم. ومكث العطارُ في الصعيد نحو ثمانية عشر شهرًا تقريبًا، ثم عاد بعدها إلى القاهرةِ بعد استتباب الأمن، وعندما عاد إلى القاهرة تعَرَّف ببعض علماء الحملة، واطَّلع على كُتُبِهم وتجارِبِهم وما معهم من آلاتٍ علمية فلكية وهندسية، كما اشتغل بتعليمِ بَعضِهم اللغةَ العربية، فأفاد منهم واطَّلَع على علومهم، واشتغل أثناءَ الحملة الفرنسية بالتدريس في الأزهر. ثم ارتحل إلى بلادِ الروم والشام والأراضي الحجازية سنة 1802 وزار تركيا ونزل بعاصمتِها القسطنطينية، ثم أقام في ألبانيا مدةً طويلة وسكن ببلد تدعي اشكودره من بلاد الأرنؤد، وتزوَّج بها، ثم دخل بلاد الشام سنة 1810م وعمل هناك في التدريسِ، وأقام بها خمسَ سنين. ثم عاد العطَّارُ إلى مصر سنة 1815م بعد أن استقَرَّ الحكم فيها لمحمد علي، وبواسطة بعض تلاميذه المقرَّبين من محمد علي التقى به، فلَمَّا لَمس منه محمد علي حِرصَه على مساعدتِه في تطوير مصرَ، جعله أوَّلَ مُحرِّرٍ لجريدة الوقائع المصرية في بدء صدورِها، ثم تولى مشيخةَ الأزهر سنة 1246هـ إلى أن توفِّي. استغل العطار قُربَه من محمد علي، وثقتَه به، فأوعز إليه بضرورةِ إرسالِ البعثات إلى أوروبا لتحصيلِ عِلمِها، وأوصى بتعيينِ تلميذه رفاعة الطهطاوي إمامًا لأعضاءِ البعثة العلمية إلى باريس، وأوصى الطهطاوي بأن يفتَحَ عينيه وعقله، وأن يدوِّنَ يومياتٍ عن رحلتِه، وهذه اليومياتُ هي التي نشرها الطهطاوي بعد ذلك في كتابِ (تخليص الإبريز في تلخيص باريز)  وكان العطار قد قاد حركةَ إصلاحِ الأزهر في عصره، وجمع بين الثقافةِ العربية والغربية، وكان يُتقِنُ التركية ويلِمُّ بالفرنسية. وكان يحسِنُ عَمَل المزاول الليلية والنهارية. وتَرَك مؤلفاتٍ كثيرةً منها: رسالة في كيفية العمل بالإسطرلاب, وكتاب في الإنشاء والمراسلات، وديوان شعر، وحواشٍ في اللغة والمنطق وعلم الكلام وأصول الفقه. وكان مِن أبرز تلاميذ العطار: رفاعة الطهطاوي، ومحمد عياد الطنطاوي. توفي العطار في القاهرة ودُفِنَ فيها."},{"id":4491,"title":"وصول الحملة التي أعدها محمد علي باشا إلى ينبع .","date":["العام الهجري :1251","العام الميلادي :1835"],"text":"كان محمد علي باشا والي مصر يعمَلُ على تكوين دولة كبرى على حسابِ الدولة العثمانية، فضَمَّ السودان والشام وأجزاءً من بلاد اليونان والأناضول إلى سيطرته. وكان يَعُدُّ شبهَ جزيرة العرب من المناطق التابعة لدولته؛ ولهذا لم يكن غافلًا عما يجري في نجد من حركة لإعادة الدولة السعودية. ووجد أنَّ مِمَّا يسهل عَمَلَ الحملات العسكرية أن يترأَّسَها أحدُ أفراد الأسرة السعودية. وأراد محمد علي باشا التخاطبَ مع الإمام فيصل بن تركي، فأرسل إليه دوسري بن عبد الوهاب أبو نقطة، مبعوثًا ليكونَ وسيطًا بينهما. وطلب من الإمامِ فيصل إرسالَ الخَراج إليه، وتزويد القوات المصرية المحاربة في شبه الجزيرة العربية ببعض ما تحتاج إليه. ولكن الإمام لم يشأ أن يلبِّيَ هذه الطلبات، ربما لأنَّه خَشِيَ أن تُستعمَلَ ضِدَّه مستقبلًا. وفي الوقت نفسِه اتخذ موقفًا لينًا تجاه حكومة محمد علي، فأرسل هدايا ثمينة إلى أحمد باشا ممثِّل محمد علي في الحجاز مع أخيه جلوي بن تركي، على أملِ أن يكونَ في ذلك تعبيرٌ عن حُسنِ نيَّتِه تجاه الدولة. وأبدى استعدادَه لتلبية بعضِ طلبات القوات المصرية من الإبل. لكِنَّ محمد علي لم يقتنِعْ بذلك الموقف، فجهَّز حملة عسكرية بقيادة إسماعيل بك، ووضع على رأسِها -من الناحية الشكلية- خالد بن سعود بن عبد العزيز -الشقيق الأكبر للإمام عبد الله بن سعود- وكان خالد بن سعود قد أسَرَه إبراهيم باشا عند سقوط الدرعية، وأُرسِلَ إلى مصر مع بقَّية آل سعود، ووصلت الحملةُ إلى ينبع في هذه السنة."},{"id":4492,"title":"الشيخ عبد الله أبا بطين ينتقل قاضيًا لأهل القصيم بطلب أهلها .","date":["العام الهجري :1251","العام الميلادي :1835"],"text":"طلب رؤساءُ القَصيمِ مِن الإمام فيصل أن يبعَثَ إليهم الشيخَ عبد الله بن عبد الرحمن أبا بطين قاضيًا في بلدانهم، كمدرِّس لطلبة العلم في أوطانِهم، فأمر عليه الإمام فيصل وهو في بلد شقراء قاضيًا لأهل الوشم أن ينتَقِلَ إلى القصيم، فقَدِمَ عُنَيزة وأقام فيها، ثم طلبوا نزولَه عندهم وانتقاله إليهم بأهله، فانتقل بعياله عندهم واستوطن عُنيزة، فأكرموه غاية الإكرام وعظَّموه بما يستحِقُّه من الإعظام، فاجتمع عنده طلبةُ عِلمٍ كثيرون، ورحل إليه من الغرباء صغيرٌ وكبيرٌ، وانتفع به من طلبتهم كثير."},{"id":4493,"title":"عبد القادر الجزائري ينتصر على الفرنسيين  في معركة المقطع  .","date":["العام الهجري :1251","العام الميلادي :1835"],"text":"أعلن عبد القادر الجزائري الجهادَ ونظَّم حُكمَه، فكان بمثابةِ رئيس للوزراء وله نائب ووزراء، واتخذ من مدينةِ المعسكر قاعدةً له، واتَّصل بمن بقي من العثمانيين، فأعلنوا السَّمعَ والطاعة، ثم بويع أميرًا للجهاد في جمادى الآخرة 1248هـ / تشرين الثاني 1832م، ثم قَوِيَ أمره حتى جرت بينه وبين الجنرال دي ميشيل معاهدة بتاريخ 17 شوال 1249هـ / 26 شباط 1834م لوقف القتالِ، وإطلاق سراح الأسرى، وحرية التجارة، واحترام عادات وديانة المسلمين، لكِنَّ المعاهدةَ لم تَرُقْ للفرنسيين الذين غيَّروا دي ميشيل وعيَّنوا مكانه حاكمًا للجزائر هو تريزل، وكان عبد القادر الجزائري قد سار إلى موسى حسن الذي احتَلَّ بلدة المدية، فانتصر عليه، وكان لا بد من الصدام مع الفرنسيين. فعندما خرج  الجنرال الفرنسي تريزل على رأسِ جيش مكون من 2500 جندي مدعَّمين بمؤونة وذخيرة ومدافع، كان متوجهًا لمعسكر عاصمة الأمير عبد القادر آنذاك. حيث هاجَمه الأميرُ عبد القادر على نهر المقطع قُربَ الساحل، فانتصر عليه انتصارًا عظيمًا، اضطر الفرنسيون على إثره إلى توقيع معاهدة المقطع مع عبد القادر في ربيع الأول 1251هـ / حزيران 1853م. يَعتَبر الجزائريون معركةَ المقطع من أشهر المعارك التي خاضها عبد القادر الجزائري ضد فرنسا وعمره لم يتجاوز ال26 سنة، ويذكر أن عدد قتلى معركة المقطع 500 قتيل فرنسي."},{"id":4494,"title":"قحط وغلاء الأسعار في نجد .","date":["العام الهجري :1251","العام الميلادي :1835"],"text":"قَلَّ المطَرُ وغَلَت الأسعار، فصار البُرُّ سِتةُ أصواعٍ وخمسة بريال فرنسي، والتمر خمسة عشر وزنة، وأصاب الناسَ مجاعةٌ، وجلا كثيرٌ من أهل سدير للزبير والبصرة، ولم يأتِ من السيل إلا قليلٌ في الصيف، وكان هذا الغلاء والقحط وقع بعد قتلِ الإمام تركي، وعلى وجه إقبال خالد بن سعود مع العسكرِ المصري."},{"id":4495,"title":"فيصل بن تركي يغزو القبائل التي تمتنع عن دفع الزكاة .","date":["العام الهجري :1251","العام الميلادي :1835"],"text":"سار الإمامُ فيصل بن تركي بجنودٍ مِن العارض والخرج والفرع والأفلاج ووادي الدواسر والقصيم والجبل والوشم وسدير وغيرهم وجميع غزوان العربان، فنزل روضة التنهات المعروفة عند الدهناء، وأقام فيها أكثَرَ من شهرين؛ وذلك لأنه بلَغَه أنَّ بعض العربان فيهم امتنعوا عن الزكاة، فإذا سمعوا بخروجه سَمِعوا وأطاعوا، فوفد عليه رؤساءُ العربان، وأرسل إليهم عمالًا، لكلِّ فريقٍ عامِلُه، فقبضوا منهم الزكاة، وألفى عليه أخوه جلوي أثناء تلك المدة ثم قَفَل راجعًا إلى وطنه، وأذن لأهل النواحي يرجعون إلى أوطانهم."},{"id":4496,"title":"عقد أول هدنة بحرية بين رؤساء المشيخات والإمارات العربية في الخليج العربي .","date":["العام الهجري :1251","الشهر القمري : محرم","العام الميلادي :1835"],"text":"كانت الملاحة في الخليج العربي قد اضطربت لمدة سنتين بدءًا من عام 1249هـ؛ وذلك بسبَبِ الصراع بين مشيختي الشارقة وأبو ظبي، ثم بسبب الاضطرابات الداخلية في مشيخةِ أبو ظبي، وكان لتلك الاضطرابات أكبَرُ الأثر في حياة القواسم وبني ياسر، وهما أكبَرُ قبيلتين بحريتين في ساحل الصلحِ البحري، فتوقفت أعمالُ الغوص لصيد اللؤلؤ، وساءت أحوالُهم المعيشية إلى حدٍّ كبير، فكان هذا هو العامِلَ الرئيسي الذي مهَّد لعقد أول هدنة بحرية في محرم من هذه السنة؛ حيث اجتمع رؤساء المشيخات والإمارات المطِلَّة على ساحل الخليج عند المقيم السياسي البريطاني، وتعهدوا بعدم اللجوءِ إلى الاشتباكات البحرية فيما بينهم أثناء موسِمِ الغوص، ثم تحولت الهدنةُ فيما بعد لتكونَ لمدة سنة كاملة، وتُجَدَّد سنويًّا بالاتفاق مع المقيم السياسي البريطاني."},{"id":4497,"title":"أمير القطيف وسيهات يبايعان الإمام فيصلًا .","date":["العام الهجري :1251","الشهر القمري : ربيع الآخر","العام الميلادي :1835"],"text":"بعث الإمام فيصل زويد العبد ومعه 100 مطية من الركاب ناحيةَ القطيف، فأمر فيه ونهى، وعزل رجالًا وثَبَّت رجالًا، ووفد ولدُ أمير القطيف ابن غانم وابن عبد الرحيم أمير سيهات على الإمام فيصل، وبايعاه على السَّمعِ والطاعة."},{"id":4498,"title":"ظهور الحركة الأندلسية في أسبانيا .","date":["العام الهجري :1251","الشهر القمري : جمادى الأولى","العام الميلادي :1835"],"text":"رفضت المدُنُ الأندلسيَّةُ أن ترضخَ لمطالبِ السياسيِّ الليبرالي منديزابال: \"بأن تقومَ الدولةُ ببيعِ ممتلكاتِ الكنيسةِ ومُصادرتِها، كحَلٍّ لمشاكِلِها الماليةِ في أسبانيا\"، وتوحَّدت مناطِقُ الأندلس عبر \"مجلس أعلى للثورة\" مقرُّه بلدةُ أندوجر (مقاطعة جيان) يمثِّل جميعَ الأندلس عبر ممثِّلينَ من جميعِ مقاطعاتِها. وانتخَبَ المجلسُ الكوندي دي دوناديو -مثِّل مدينة جيان- رئيسًا له، وأرسل إنذارًا للحكومةِ في مجريط يعبِّرُ فيه عن رغبةِ الأندلسيين في حُكمِ ديموقراطي على أساسِ دستورِ (أندوجر)، وجعل الحكومةَ مسؤولةً أمامَ الإرادة الشعبية. ثم كوَّن المجلِسُ جيشًا أندلسيًّا للدفاعِ عن الأندلس. لكِنَّ منديزابال نجح في إقناع المدن الأندلسية الواحدة تلوَ الأخرى بالرُّجوعِ للحكومة. ثم اضطرَّ مجلس الثورة الأعلى الأندلسي في أندوجر أن يحُلَّ نفسَه. كانت هذه الأحداث مهمَّةً في تكوين القوميَّةِ الأندلسية إذ تحرَّكت فيها الأندلسُ لأولِ مرة منذ ثورات المورسكيين كأمَّةٍ واحدة أمام الحُكمِ المركزيِّ في مجريط، وكانت الثوراتُ قبل ذلك أسبانيةً في الأندلس وليست أندلسية. وخيرُ تقدير لأهمية هذه الثورة ما قاله بلاس انفانتي -أسلم لاحقًا ثم أُعدِمَ لدفاعه عن المسلمين- وهو مؤسِّس القوميَّةِ الأندلسيَّةِ، قال: \"لقد أعطت الأندلسُ سنة 1835م برهانًا واضحًا عن وجودِ شعورِ وَحدةٍ مصيرية في منطقتِها، تنبضُ فيه رغبتُها في المساهمة كوحدة تَشعُرُ بنفسِها في سيادةِ الدولة المركزية. وقد كوَّنت الولاياتُ الأندلسيَّةُ الموحَّدةُ أكبرَ وأقوى مقاومة لمنديزابال، وأنشأت أمام القوى المركزية الليبرالية قوةً جهوية فاعلة، لها جيشُها الخاص، تعاملت ندًّا لندٍّ مع كرستينا (الوصية على العرش). وأعلنت أُسُسَ الحُكم الشعبي، وتصرَّفت بشرفٍ وأخلاق\". وتتلخَّصُ أهم سماتِ الحركة الأندلسية في القرن التاسع عشر في الانتماء إلى منطقة واحدة (الأندلس)، وأمَّة واحدة أندلسية، والمطالبة بحقوقِها، والوقوفِ في وجهِ تجاوزات الدولة المركزية الليبرالية، والكنيسة الكاثوليكية، والإقطاع الزراعي."},{"id":4499,"title":"سيادة ليبيا على البحر المتوسط في عهد أسرة قره مانلي .","date":["العام الهجري :1252","العام الميلادي :1836"],"text":"كانت ليبيا في عهد أسرة القره مانلي تمتلك أسطولًا بحريًّا قويًّا مكَّنَها من أن تتمَتَّعَ بمكانة دولية مَهيبة، وأصبحت تنعَمُ بنوعٍ مِن الاستقلال. فأسَّس أحمد القره مانلي أسرةً حاكمة استمرَّت في حكم ليبيا حتى هذا العام، ويعتبر يوسف باشا القره مانلي أبرزَ ولاة هذه الأسرةِ."},{"id":4500,"title":"ظهور الدعوة السنوسية في شمال أفريقيا .","date":["العام الهجري :1252","العام الميلادي :1836"],"text":"كان مؤسِّسُ الدعوة السنوسية محمد بن علي المعروف باسم السنوسي الكبير في الجزائر حين دراستِه في فاس تأثَّر كثيرًا بالحركة الصوفية هناك، وخاصة أولئك الذين ينتَمون إلى الطريقة التيجانية، والتحَقَ فيما بعد بجماعاتٍ متعددة من المتصوَفِّة حين كان يدرُسُ في الحجاز على الشيخِ الإدريسي، وكان يحمِلُ أفكارًا إصلاحيَّةً وتجديدية، فقام بإيجاد طريقة صوفية خاصةٍ به حين كان في مكَّةَ، أطلق عليها اسمَ السنوسية، وكانت من دعوته مقاومةُ النفوذ الأجنبي، ووجد السنوسي أنَّ بلادَه الجزائر بدأت تسقُطُ في يد الفرنسيين، فاستقر به المقامُ في برقة؛ حيث أسَّس زاوية البيضاء، ثم أقيمت العديدُ مِن الزوايا والمراكز الدينية والتربوية على الطريقة السنوسية، ولاقت دعوته صدًى في سكان الصحراء من الشمال الأفريقي كله والسودان."},{"id":4501,"title":"مقتل محمد ابن وطبان رئيس الزبير .","date":["العام الهجري :1252","العام الميلادي :1836"],"text":"هو الأميرُ محمد بن إبراهيم بن ثاقب بن وطبان أمير الزبير، كان من أعظَمِ أهلِ ناحيته عقلًا ومعرفةً ودهاءً، وكان متحفِّظًا على نفسه، يعرِفُ الحِيَل ويخافُ منها، وكانوا يسمونه \"البلم يغرق غيره ويَسلَم\" كان أبوه إبراهيمُ أمير الزبير، فلما مات صار مكانَه، فحصل بينه وبين آل زهير وأهلِ حرمة الجالين في الزبير ضغائِنُ عظيمة، فأخرجوه بسببها من الزبير، فانتقل مع أهله وعياله ونزل بلد الكويت، ثم عاد لحُكمِ الزبير والبصرة ولم يزَلْ فيها حتى قتَلَه متسلِّم البصرة على الرغمِ مِن شِدَّةِ تحفُّظِه على نفسه، وفِطنتِه وكثرةِ عَدَدِه وعُدَّتِه!"},{"id":4502,"title":"تحرك الإمام فيصل بن تركي من الرياض لملاقاة القوات المصرية .","date":["العام الهجري :1252","الشهر القمري : شوال","العام الميلادي :1837"],"text":"حاول الإمام فيصل أن يتفادى الصدامَ مع القوة المصرية الموجَّهة إليه؛ إذ لا قِبَلَ له بها. فأرسل الهدايا مع مبعوثٍ منه إلى قائدَيها خالد بن سعود وإسماعيل بك، إظهارًا لحُسن نيته. ولما عاد المبعوث أطلع الإمامَ على نيات محمد علي باشا في مهاجمةِ البلاد. وواصلت الحملةُ تقَدُّمَها من المدينة النبوية إلى الحناكية، وكان الإمامُ فيصل لما بلغه مسيرُ العساكر المصرية بقيادة إسماعيل بك وخالد بن سعود، استشار رؤساءَ رعيَّتِه الذين عنده، في المسير إليهم أو عدَمِه، فأشار عليه عبد الله بن علي رئيسُ جبل شمر بالنفيرِ والمسير وأن يقصِدَ القصيم ويقيمَ فيه وينزِلَ قبل أن يقدمَ العساكِرُ، فيجيبونه ويتابعونه، فيكون نزوله عندهم فيه ثباتٌ لهم ورِدَّةٌ عن عَدُوِّه، فاستنفر الإمامُ فيصل قواته في الأحساء، وجنوب نجد وسدير، وتقَدَّم من الرياض إلى القصيم؛ لملاقاة القوات المصرية والدفاع عن المنطقة."},{"id":4503,"title":"إنشاء أول وزارة للمعارف في مصر والعالم العربي باسم ديوان المدارس .","date":["العام الهجري :1252","الشهر القمري : ذي القعدة","العام الميلادي :1837"],"text":"تم إنشاءُ أوَّلِ وَزارة للمعارفِ في مصرَ والعالم العربيِّ، باسم ديوان المدارس، وقد تولى رئاستَها مصطفى مختار باشا، الذي كان أحد أعضاءِ البعثة العلمية الأولى التي أرسلها محمد علي باشا إلى فرنسا."},{"id":4504,"title":"مواجهة الإمام فيصل العساكر المصرية في القصيم .","date":["العام الهجري :1252","الشهر القمري : ذي الحجة","العام الميلادي :1837"],"text":"نزل الإمامُ فيصل بجنودِه على ماء الصريف من أرضِ القصيمِ، فأقام عليها أكثَرَ مِن شهر حتى بلغه أنَّ خالد بن سعود وإسماعيل بك وعساكِرَهم نزلوا الرسَّ، فرحل الإمام ونزل عُنَيزة، واستنفر أهلَها، فركب معه أميرُها يحيى بن سليمان، ورئيسُ بريدة عبد العزيز بن محمد، ونزل في رياض بلد الخبرا بين الرس والخبرا، فأقام فيها عشرين يومًا، وهو ملازم  عسكر الترك في الرس ومحاربٌ لهم، ولكن لم يحصُلْ بينه وبينهم قِتالٌ، ولا طلع عليه أحدٌ منهم، حاول أن يُدخِلَ بعضَ جنوده بلد الشنانة عند الرسِّ، لكنهم لم يتمكَّنوا، فاستشار الرؤساءَ في الرحيل أو المقام، فأشاروا عليه أن يأمُرَ بالرحيل إلى عُنَيزة، ثم يَشُنَّ الغارةَ بمن معه على الذين تابعوا عساكِرَ الترك فلما شُدَّت رحايلهم وحمَّل عليها، ظَنَّ أناس من أطراف الغزو أن القومَ راحلون ومنهَزِمون فشالوا على  رواحِلِهم ووقع الفشَلُ في جندِه، فأمر فيصل رجالَه بتسكينِهم، وضَرَب من رحَلَ وانهزم منهم، فقاموا وأدَّبوا فيهم فسكنوا وباتوا في مكانِهم، فلما أصبح فيصل ركِبَ بجنوده قاصدًا عنيزة فوقع فشَلٌ وخِفَّةٌ في جيشه، فلما نزل عنيزة شاور رؤساء قومه المقامَ أو الرحيل، فاقتضى رأيه أن يرحل ويقصِدَ بلده، وأذن لأهلِ النواحي يقصِدون بلدانَهم."},{"id":4505,"title":"خروج الإمام فيصل من الرياض وانتقاله للأحساء .","date":["العام الهجري :1252","الشهر القمري : ذي الحجة","العام الميلادي :1837"],"text":"لما دخل الإمامُ فيصل الرياضَ بعد عودتِه من القصيم، رأى من بعض أهلِها ريبةً، وجاهر بعضُهم بالعداوةِ، فعمل فيصل على جمعِ أمواله وأهله وخيله والنجايب، وخرج بهم من الرياض إلى الخَرج، فأقام بها عشرة أيام حتى استلحق باقي أهله وشيء من متاعه وعَدَد من رجاله وعبيده، ثم قصد الأحساءَ، فلما وصلها استقبلها أميرُها مِن قِبَلِه عمر بن عفيصان ورؤساؤها وبايعوه على النصرةِ والقيام معه، ونزل قصر الكوت بعياله وأثقالِه، وأقام في الأحساء آخِرَ عاشوراء وصفر وربيع من سنة 1253هـ ووفد عليه رؤساء العربان من مطير والعجمان والسهول وسبيع وغيرهم."},{"id":4506,"title":"خورشيد باشا يستدرج الإمام فيصل .","date":["العام الهجري :1253","العام الميلادي :1837"],"text":"أرسل محمد علي باشا حملةً عسكريةً بقيادة واحد من أمهرِ قادته العسكريين، وهو خورشيد باشا. وكان أوَّل ما فعله خورشيد وهو في طريقه إلى نجد أن أرسل رسالةً وهدايا إلى الإمام فيصل بن تركي مع الشريف عبد الله، صاحب ينبع، وأذِنَ للإمام أن يأخُذَ ما أراد أخْذَه من ممتلكاته الموجودة في الرياض، ووعده بالتقريرِ في مُلكِه، ولا عليه مُنازِع، وربما كان قصد خورشيد باشا من هذا الوعد هو أن يبقي الإمام فيصلًا حاكِمًا على جنوبيَّ نجد والأحساء، وهما المنطقتان اللتان لا تزالان مواليتَين له. وربما سعى إلى كسبِ الوقتِ حتى يصل إلى العارض قبل أن ينال الإمامُ فيصل من خالد بن سعود."},{"id":4507,"title":"عبد الله بن علي بن رشيد يستعيد حكمه لجبل شمر .","date":["العام الهجري :1253","العام الميلادي :1837"],"text":"أقبل عبدُ الله بن علي بن رشيد رئيس جبل شمر ومعه من أعوانه وعشيرته رجالٌ؛ لمحاربة عيسى بن علي، ونزل عند بني تميم في بلد قفار المعروفة في حائل، وأقام عندهم، ثم سطا على عيسى بن علي وأخرجَه مِن قَصرِه ومن البلد، وقتل رجالًا ونهب أموالًا."},{"id":4508,"title":"خالد بن سعود يدخل الرياض يطلب البيعةَ له .","date":["العام الهجري :1253","الشهر القمري : صفر","العام الميلادي :1837"],"text":"رحل خالد بن سعود وإسماعيل بك وعساكِرُ الترك من القصيمِ إلى الرياض ودخلوها يوم السبت 7 صفر، ودخل خالد وإسماعيل القصرَ واستوطنوه ونزل العسكرُ خارج الرياض، وقَدِمَ عليهم رؤساء البلدان وتابعوهم، وأرسلوا إلى الهزاني ورؤساء أهل الحوطة يطلبون منهم المتابعةَ والقدومَ إليهم، فأبوا عليهم، وكتبوا لخالد إن كان الأمرُ لك ولا يأتينا في ناحيتِنا عسكرٌ مِن الترك فنحن رعيَّةٌ لكم، وإن كان الأمر للتركِ فنحن لهم محارِبون، فغضب إسماعيل وأتباعه وقالوا: لا نرضى إلا بقتلِ أهلِ هذه الناحية ونَهْبِ أموالِهم."},{"id":4509,"title":"توقيع الأمير عبد القادر الجزائري معاهدة تافنة مع الفرنسيين .","date":["العام الهجري :1253","الشهر القمري : صفر","العام الميلادي :1837"],"text":"نجح الأميرُ عبد القادر الجزائري في إحراز نصرٍ على القائد الفرنسي الجنرال \"بيجو\" في منطقة \"وادي تفنة (أو تافنة) \"، الأمرُ الذي أجبر القائدَ الفرنسي على عقدِ معاهدة هدنة جديدةٍ عُرفت باسم \"معاهدة تافنة\"، وعاد الأميرُ عبد القادر بعدها لإصلاحِ حالِ بلادِه وترميمِ ما أحدَثَتْه المعارك بالحصون والقلاع، وتنظيم شؤونِ البلاد، لكِنَّ الفرنسيين نقَضوها عام 1839م."},{"id":4510,"title":"إصدار فرنسا قانونا يخضع القبائل الجزائرية للإجراءاتِ الفرنسية .","date":["العام الهجري :1253","الشهر القمري : ربيع الآخر","العام الميلادي :1837"],"text":"أصدرت فرنسا قانونًا أخضَعَت به أراضيَ القبائل الجزائرية لإجراءاتِ القوانينِ الفرنسية، وهو ما سهَّل للفرنسيين الاستيلاءَ على تلك الأراضي."},{"id":4511,"title":"هزيمة جيش خالد بن سعود قرب بلدة الحلوة .","date":["العام الهجري :1253","الشهر القمري : ربيع الآخر","العام الميلادي :1837"],"text":"بعد سَيرِ القوات المصرية نحوَ الرياض وجدت التشجيعَ مِن سكَّانها الذين قَدِمَ منهم وفد؛ ليعلن ولاءَهم للجيش المصري، وفر منها المعارِضون من آلِ الشيخ إلى جهات الحلوة والحريق وحوطة بني تميم في جنوبي نجد. فأراد خالد بن سعود أن يُخضِعَ المناطِقَ الجنوبية من نجدٍ بالقوة، بعد أن رفضت طاعتَه، فكتب خالد إلى أمراء سدير والمحمل والوشم وبلدان العارض بالنفير معه لقتالِ مناطق الجنوب، فخرجوا جميعًا إلَّا أمير سدير أحمد بن محمد السديري، تخلَّف بسبب القَحطِ، واستنفر خالد أهلَ الرياض، فلما وصل الخرج استنفر أهلَها، فركب معهم فهد بن عفيصان، فاجتمع لخالد وإسماعيل 7000 مقاتِلٍ مِن الترك والعُربان وأهل البلدان المتابعين لهم، فقصدوا بلدة الحلوة. كان أهلُ الحلوة قد أخرجوا نساءهم وأبناءهم وأدخلوهم الحوطةَ، وكان الشيخ عبد الرحمن بن حسن، والشيخ علي بن حسين، وعبد الملك بن حسين، وحسين بن حمد بن حسين -أبناء الشيخ محمد بن عبد الوهاب- بعد أن أقبل عساكِرُ خالد وإسماعيل على الرياض؛ هربوا منه وسكنوا بلد الحوطة، وبعضهم نزل على تركي الهزاني في الحريق، فلما صارت هذه الحادثة جعل الله بسببهم ثباتًا لهم ويقينًا يشجعونهم ويأتمرون بأمرِهم ولا يقطعون أمرًا دون مشورتِهم، فلما دخل عسكر الترك حرة قرب بلدة الحلوة، صعد أهل الحلوة الجبَلَ لقتالِهم، فوقع القتال من أوَّلِ النهار إلى بعد الظهرِ، وهم في قتال وإقبال وإدبار، فأتى المدَدُ من أهل الحوطة والحريق وغيرهم، وحصلت مقتلة عظيمة على عسكر الترك وأتباعهم، فنزلت بهم هزيمةٌ ساحقة. يقول ابن بشر: وأول من انهزم الأعرابُ الذين مع العسكرِ، ثم وقعت الهزيمةُ العظيمة التي ما وقع لها نظيرٌ في القرون السالفة ولا في الخلوفِ الخالفة، على عساكِرِ التركِ وأعوانِهم، وهلكت تلك الجنودُ ما بين قتلٍ وظمأٍ، وذُكر لي أن الرجلَ من القرابة الذين ليس لهم خيلٌ لا ينهزِمُ أكثر من رميةِ بندقٍ، ولم ينجُ واحد منهم، وتفَرَّقت الخيالة في الشِّعابِ فهلكوا فيها ليس لهم دليل، ولا يهتدون إلى السبيل، ونجا خالدٌ بنفسِه ومن معه من أهل نجد، لما رأوا الهزيمة انهزموا وحدَهم، وتركوا عسكَرَهم وجندهم، وتزبن إسماعيل والمعاون وشرذمة معهم من الخيالة هزيمةَ خالد، فاجتمعوا به وساروا معه، وهربت الأعرابُ على رحايل العسكر، وتركوا جميعَ محلَّتِهم وأمتعتِهم، فغَنِمَ أهل الحوطة وأهل الحريق وأتباعُهم جميعَ ما معهم من الأموال والسلاح والخيام، وفيها من الذهب والفضة ما ليس له نظيرٌ، وذلك يوم الأربعاء منتصف ربيع الآخر، وكان معهم فهد بن عفيصان بغزوِ أهل الدلم، فهرب عنهم في الليل، فلما وصل بلده أخبرهم بالأمرِ، وأمرهم يخرُجون ويأخذون ما وجدوا منهم، فتلقَّاهم غزوان أهل نجد وهزموهم إلى بلدِهم ونزلوا عندها، وحصل بينهم وبين أهلِها مناوشة رميٍ بالبنادق، ووافاهم أحمد السديري بغزو أهل سدير فيها، ثم إن خالدًا وإسماعيل وأتباعَهم رحلوا من الدلم وقصدوا الرياضَ ودخلوها. قيل: إن الذي نجا من الخيَّالة مع إسماعيل قريبٌ من  مائتين دخلوا معه الرياض، وكان قد أبقى في الرياضِ لَمَّا خرج إلى الحوطة أكثر من مائتين من المغاربة والترك في القصر\"."},{"id":4512,"title":"محاصرة الإمام فيصل بن تركي مدينة الرياض .","date":["العام الهجري :1253","الشهر القمري : جمادى الآخرة","العام الميلادي :1837"],"text":"لما هُزِمَ خالد بن سعود في بلدة الحلوة، سارع الإمام فيصل بن تركي من الأحساء إلى الخَرج، وانضم إليه أهلُ الخرج والحوطة والحريق والفرع الذين هزموا خالدًا. وانطلق بهم نحوَ الرياض، وحاصرها. ولكنه اضطرَّ إلى فَكِّ الحصار والتراجع نحو منفوحة في شعبان من هذه السنة أيضًا، وذلك بعد أن زحفت حشودٌ من قبيلة سبيع بقيادة فهيد الصييفي، ومن قبيلة قحطان بقيادة قاسي بن عضيب؛ لنجدة خالد بن سعود. فشنُّوا الغارة على الإمام فيصل وجنوده. وهناك جرت لأوَّلِ مرة محادثات للصلح بين الإمام فيصل بن تركي وخالد بن سعود، في شعبان من هذا العام أيضًا، لكِنَّها انتهت بالفشل، ودارت الحرب مجدَّدًا بين الفريقين مع وصولِ قوات جديدةٍ من مصر."},{"id":4513,"title":"علي باشا والي العراق يستولي على بلد المحمرة .","date":["العام الهجري :1253","الشهر القمري : رجب","العام الميلادي :1837"],"text":"سار علي باشا والي العراق من بغداد بعساكِرَ عظيمة، قيل إنهم 70 ألفًا من عقيل وغيرهم، وقصد بلد المحمرة المعروفة عند البصرة، واستلحق  أهل الزبير وساروا معه، فنزل المحمرة وحاصرها وأخذها عَنوةً، ونهَبَها وأخذوا منها من الأموالِ ما لا يُعَدُّ ولا يحصى."},{"id":4514,"title":"الحرب الأفغانية البريطانية الأولى  .","date":["العام الهجري :1254","العام الميلادي :1838"],"text":"حربٌ دارت بين الراج البريطاني (الحكم البريطاني في الهند) والشعب الأفغاني المسلِم من سنة 1838م إلى سنة 1842م حين غزت بريطانيا أفغانستانَ لاحتلالها بهدف إنشاء دولة عازلة بين إمبراطوريتهم وروسيا القيصرية، لكِنَّ الحرب انتهت بانتصار حاسم للأفغان؛ حيث سُحِق فيها مُعظَمُ الجيش البريطاني."},{"id":4515,"title":"توقيع معاهدة بلطة ليمان بين الدولة العثمانية، والمملكة المتحدة .","date":["العام الهجري :1254","الشهر القمري : جمادى الأولى","العام الميلادي :1838"],"text":"كانت معاهدة بلطة ليمان معاهدةً تجارية وُقِّعَت بين الدولة العثمانية والمملكة المتحدة لبريطانيا العظمى وأيرلندا؛ لتنظيم التجارة الدولية. وتمَّ تحديد الرسوم لتكون 5 % على الواردات، و12 % على الصادرات، و3 % على البضائع المارة (ترانزيت). كما وافق العثمانيون على إلغاء جميع الاحتكارات. ففي عام 1831 قاد إبراهيم باشا بن محمد علي باشا حملةً عسكريةً ناجحةً في بلاد الشام، منَصِّبًا نفسَه حاكمًا، وبدأ في عَصْرَنة دولته. وقد كان هناك قَلَقٌ في المملكة المتحدة من احتمال تأسيس دولة مستقلة متحالِفة مع الإمبراطورية الروسية ضِدَّ العثمانيين وبلاد فارس القاجارية (فاستقلال ووحدة أراضي كل من الدولة العثمانية وبلاد فارس كانت من الأمور البالغة الأهمية للمصالح البريطانية في المنطقة). كما كان هناك العديدُ مِن الشكاوى من رجال الأعمال البريطانيين من تعَرُّضِهم لرسوم تُفرَضُ على بضائعِهم المارَّة عبرَ أراضي الدولة العثمانية، وكذلك تعَرُّضهم لرسوم عشوائية من الباشوات المحليين. وعندما رفض محمد علي تنفيذَ الاتفاقية بسبب ما تشَكِّلُه من تهديد لمشروعِه التصنيعي الناشئ، أمهله السلطانُ محمود الثاني فترةَ سماح لمدة سنة، ولكنَّ محمد علي رفض بعدها الالتزامَ بالمعاهدة."},{"id":4516,"title":"استسلام الإمام فيصل بن تركي لقوات خورشيد باشا .","date":["العام الهجري :1254","الشهر القمري : رمضان","العام الميلادي :1838"],"text":"وصلت حملةُ خورشيد باشا إلى الرياض في رجب من هذه السنة، وطُلِب من الإمام فيصل بن تركي -الموجود في الدلم- الاستسلام، وإلا فإنه سيواجِهُ الحرب، ولما رفض الإمام فيصل الإنذار، وقع القتالُ بين الطرفَين في معركة الخراب، في جهة الدلم، وتغلبت فيه قواتُ خورشيد باشا على الإمام فيصل وأتباعه. وانتهى الأمرُ باستسلام فيصل بن تركي في رمضان من هذا العام، بعد أن حصل على الأمان للبلدة. وفي اليوم الثاني من شوال أُخِذ إلى مصر ومعه ولداه: عبد الله ومحمد، وأخوه جلوي بن تركي، وابن أخيه عبد الله بن إبراهيم بن عبد الله؛ حيث انضموا إلى بقية آل سعود هناك. وكانت تلك نهايةَ الفترة الأولى من حكم الإمام فيصل بن تركي."},{"id":4517,"title":"احتلال بريطانيا مدينة عدن .","date":["العام الهجري :1254","الشهر القمري : ذي القعدة","العام الميلادي :1839"],"text":"لقد كانت عدن محطَّ أنظار كثيرٍ مِن الدول الطامعة في إرساء قواعدَ لها على البحر الأحمر والخليج العربي، ومن ثَمَّ السيطرة على المحيط الهندي، والحصول على السيطرة الاقتصادية والسياسية في تلك المنطقة، فتوالت على عدن الكثيرُ مِن القوات والدول المستعمرة، وكان من أهمِّ تلك الدول بريطانيا؛ حيث قامت ببعض المقَدِّمات لاحتلالِ عدن، فأرسلت في بداية الأمر الكابتن هينز أحدَ ضباط البحرية إلى منطقةِ خليج عدن في عام 1835م؛ وذلك لمعرفة مدى صلاحية المنطقة لتكونَ قاعدةً بحريةً ومستودعًا للسفن البريطانية، وقد أشار هينز في تقريره إلى ضرورة احتلال عدن لأهميَّتِها الاستراتيجية. وكان لا بد للإنجليز من سَبَبٍ يبررون به احتلالهم لعدن، فكان أن وقَعَت حادثة استغلوها استغلالًا كبيرًا؛ ففي عام 1873م جنحت سفينةٌ هندية تسمى: (دريادولت) وكانت ترفَعُ العلم البريطاني بالقُربِ من ساحل عدن، فادعى الإنجليز أنَّ سكَّان عدن هاجموا السفينةَ ونهبوا بعضَ حمولتِها، وأن ابن سلطان لحج وعدن كان من المحَرِّضين على نهب السفينة. ثم لما مضى حوالي شهر من حدوث ذلك وزادت كذلك رغبةُ بريطانيا للسيطرة على البحر الأحمر وجَعْل عدن كمحطةٍ تعمل على تمويل سُفُنِها بالوقودِ، وجعْلها قاعدةً عسكرية تهيمِنُ على المنطقة العربية، قام حينها (كوماندر هينز) قائد السفينة (بالينورس) في البحر الأحمر بكتابةِ تقريرٍ إلى (سيرتشارلز مالكولم) مدير البحرية البريطانية في الهندية في 6 يوليو1837م، قال فيه: \"يشَرِّفني أن أعلِمَكم أنه لدى وجودي في عدن خلال شهر إبريل تبيَّنتُ أن البضاعة التي تمت استعادتها من السفينة المحطَّمة (دريادولت) التي تحمل العلم الإنكليزي والعائدة إلى مدراس كانت مطروحةً في السوق بأقَلَّ مِن ثُلُثِ قيمتِها\". فأرسلت الحكومةُ البريطانية الكابتن هينز لإجراءِ مفاوضات مع سلطان لحج ولكنها باءت بالفشَلِ بعد محاولة سلطان لحج إعادةَ البضائع المسروقة، ودفع قيمة ما تلف أو بِيعَ منها، إلا أن هينز لم يوافِقْ لأن بريطانيا كانت تريد عدن نفسَها. وفي عام 1839م نفسه أعدَّت حكومة الهند البريطانية عِدَّةَ إجراءات للاستيلاء على عدن، وقامت بعض المناوشات بين العرب في عدن وبعض جنودِ السفن البريطانية المسَلَّحة التي رابطت بالقُربِ مِن ساحل عدن انتظارًا لوصول السفن الباقية، وبعد ثلاثة أيام في 19 يناير 1839م قَصَفَت مدفعية الأسطول البريطاني مدينةَ عدن ولم يستطِعِ الأهالي الصمودَ أمام النيران الكثيفةِ، وسقطت عدن في أيدي الإنجليز بعد معركةٍ غير متكافئة بين أسطولِ وقوَّات الإمبراطورية البريطانية من جانبٍ، وقوات قبيلة العبدلي من جانب آخر. وبدأت متاعِبُ الحكم المصري في اليمن بعد سقوطِ عدن في أيدي البريطانيين؛ فقد بدأ هينز اتصالاته بمشاريعِ المناطق الجنوبية الواقعة تحت نفوذ المصريين، يُغريهم بالهدايا والمرتَّبات ويحثُّهم على التمَرُّد على الجيش المصري، ولكن الأحوال تطورت بسرعةٍ بعد تحالُف الدول الكبرى ضِدَّ محمد علي، وانتهى الأمر بانسحاب القوات المصرية من اليمن في عام 1840م، وانفردت بريطانيا وحدها بمقَدَّرات جنوب اليمن كُلِّه، وبدأت إنجلترا عشيَّةَ احتلالها لعدن في تنفيذ سياسةِ التهدئة في المنطقة حتى تضمَنَ استقرار الأمور في عدن بما يحقِّقُ مصالحها الاستراتيجية والتجارية والبحرية، فعقدت مع سلطان لحج معاهدةً للصداقة ومنحَتْه راتبًا سنويًّا إلا أن هذا لم يُجْدِ نفعًا؛ حيث حاول سلطان لحج استعادة عدن ثلاثَ مرات في عامي1840و1841م لكن تلك المحاولات لم تنجَحْ؛ للفارق الهائل في تسليحِ القوتين. وكان الحاكِمُ البريطاني إذا قامت إحدى القبائِلِ على الإنجليز يثيرُ قبيلةً أخرى عليها. وقد جاء في الكتاب الذي أرسلَتْه شركة الهند الشرقية البريطانية إلى الكابتن هينز المقيم في عدن، جاء فيه ما يلي: (حَرِّضِ القبيلةَ الموالية على القبيلة المعادية، فلا تحتاج إلى قواتٍ بريطانية، وإنه وإن كان هَدْرُ الدماء مما يؤسَفُ له، فمِثلُ هذه السياسة تفيدُ الإنجليز في عدن؛ لأنَّها توسِّعُ الثُّلمةَ بين القبائل) كما استغل الكابتن هينز اليهودَ في المنطقة حتى يكونوا عيونًا له على العرب عِلمًا بأنه كان في عدن ما يقارِبُ من 180 يهوديًّا، ويعترف هينز بأن أحسن من ينقل الأنباءَ إليهم هم اليهود؛ لِما عُرِفَ عنهم، وهو قد وظَّفَهم لحسابه، وهؤلاء اليهود قد وافوا الكابتن هينز بكل صغيرة وكبيرة في اليمن أكمَلَ، ومن ضمنها عدن وقعطبة وتعز ولحج، مقابل مبالغ تافهة. ولم يكن الاستيلاءُ على عدن هو غايةَ ما تبغيه بريطانيا في المنطقة، وإنما كان هذا الاستيلاءُ بمثابة نقطة للتوسُّعِ، وبداية الانطلاقِ لتأكيد النفوذ البريطاني في جنوبِ اليمن والبحر الأحمر وعلى الساحل الشرقي الإفريقي، وكذلك لإبعاد أي ظِلٍّ لِقوًى أخرى."},{"id":4518,"title":"مصر ترفض معاهدة لندن فيفصل الأوروبيون بينها وبين الشام .","date":["العام الهجري :1255","العام الميلادي :1839"],"text":"كانت معاهدةُ خونكار أسكله سي بين روسيا والدولةِ العثمانيةِ بمثابةِ تحالُفٍ دفاعيٍّ بين روسيا والعثمانيين؛ مما أدى إلى مسارعة كلٍّ مِن بريطانيا وفرنسا بالتصدِّي لمحمد علي خشيةَ المزيد من التدخُّلِ الروسي، وفرضت عليه اتفاقيَّةَ لندن سنة 1255هـ / 1840م. وقد ترتَّب على هذه الأحداث إجهاضُ محاولة الإصلاح التي حاول السلطانُ محمود الثاني أن يقومَ بها في الدولة العثمانية، واضطرت الدولةُ العثمانيةُ لقبولِ وصاية الدُّوَل الأوروبية في مقابِلِ حمايتِها مِن أطماع محمد علي، وكان محمد علي قد رفض أولًا هذه المعاهدة، ثم أُجبِرَ تحت ضغوط الإنجليز على توقيعِ المعاهدةِ التي من بنودِها أن يتنازل فيها عن حُكمِ بلاد الشام، وأن يظلَّ حُكمُ مِصرَ وراثيًّا له ولأبنائِه. أن يحَدَّدَ الجيش المصري بثمانية عشرَ ألفًا. ألَّا تَصنَعَ مِصرُ سفنًا للأسطول. ألَّا يعين والي مصر في الجيشِ ضابطًا أعلى من رتبةِ ملازم وأن يدفع للدولة العثمانية ثمانين ألف كيس سنويًّا."},{"id":4519,"title":"خلع الأمير فيصل بن تركي وتولية خالد بن سعود في نجد .","date":["العام الهجري :1255","العام الميلادي :1839"],"text":"كان الإمام فيصل بن تركي تولَّى حكم نجدٍ بعد مقتل أبيه، وتمكَّنَ من إخضاعِ أكثَرِ الإمارات ما عدا الحجاز، وعَيَّن عبد الله بن رشيد أميرًا على حائل، فلمَّا انزعج محمد علي حاكِمُ مصر أرسل حملةً احتَلَّت نجدًا وقبضت على الإمام فيصل بن تركي، ثم أُرسِلَ إلى مصر خلال هذه السنة، وأقامت الحملةُ خالدَ بنَ سعود بن عبد العزيز بن محمد -الذي تربَّى في مصر- حاكِمًا لنجد، وكانت غايةُ محمد علي باشا تفريقَ الأسرة السعودية."},{"id":4520,"title":"موافقة الدولة العثمانية على منح اليونان حكمًا ذاتيًّا  .","date":["العام الهجري :1255","العام الميلادي :1839"],"text":"وافقت الدولةُ العثمانيَّةُ على قَبولِ معاهدةِ لندن والتي أقرَّتْها الدولُ الأوربية الكبرى، وقد نصَّت هذه المعاهدةُ على تأسيسِ إمارة يونانية تكونُ مستقلَّةً ذاتيًّا ومرتبطة بالعثمانيين، وتقوم بدفعِ الضرائب للسلطان العثماني."},{"id":4521,"title":"انسحاب الإنجليز من كابل والاعتراف بمحمد دوست حاكمًا لبلاد الأفغان .","date":["العام الهجري :1255","العام الميلادي :1839"],"text":"كان الراج بريطاني -راج، يعني: الحكم- دخل كابل عام 1218 ويمثِّلُ هذا الدخولُ الحربَ الأفغانية الإنجليزية الأولى، التي انتصر فيها الأفغان. كان هدف بريطانيا هو إنشاءَ دولة في أفغانستان عازلة بينها وبين روسيا عندما ساعدت شجاع الملك في استعادة حُكمِ كابل مِن أخيه فتح خان، وفي هذا العام فرَّ أخوه محمد دوست إلى بخارى، فحاول أن يهاجِمَ بلاد الأفغان من جهةِ الشمال غير أن هجماتِه فَشِلت، فجاء إلى الأفغان وسلم نفسَه للإنجليز الذين نقلوه إلى كلكتا في البنغال، وانسحب الجيشُ البريطاني من كابل عام 1257هـ وهاجمه أثناء الانسحابِ أكبر خان بن محمد دوست، وكاد أن يبيدَهم ويقضيَ عليهم، وفي أثناء القتال بين الإنكليز وحليفِهم شجاع الملك من جهةٍ وأكبر خان من جهةٍ قُتِلَ شجاع ومُنِيَت إنجلترا بخسائِرَ اضطرت بنتيجتِها أن تعيدَ محمد دوست إلى بلاد الأفغان، وأن تعترف بحكمِه وعقدت معه معاهدةَ صداقةٍ."},{"id":4522,"title":"ظهور دعوة أغاخان (الإسماعيلي) بالهند .","date":["العام الهجري :1255","العام الميلادي :1839"],"text":"ظهر في إيران رجلٌ شيعي إسماعيلي اسمُه حسن علي شاه، وجمع حولَه عددًا كبيرًا من الإسماعيليَّةِ وغيرهم، فأرهبوا القوافل، وهاجموا القرى حتى ذاع صيتُه، وقَوِيت شوكته، وخَشِيَته الأسرة القاجارية الشيعية الحاكمةُ في إيران، فأُعجِبَ الناس بقوته، وانضموا تحت لوائِه؛ طمعًا في المكاسب المادية التي وعدهم بها، وكان الإنجليزُ في ذلك الوقت يعملون على بَسطِ الثورة ضِدَّ شاه إيران. وقام الإسماعيلي حسن علي بالثورة ضِدَّ الشاه القاجاري بعد أن وعَده الإنجليزُ بحكم فارس، لكِنَّ الثورة لم يُكتَب لها النجاح، حيث قَبَض عليه الشاه وسجنه، فتدخَّل الإنجليز للإفراج عنه، فتحقق لهم ذلك على أن يُنفى خارج إيران، فزيَّن له الإنجليز الرحيلَ إلى أفغانستان، فلما وصلها كشف أمرَه الأفغانُ، فاضطرَّ إلى الرحيل إلى الهند فأقام بها، واتخذ من مدينة بومباي مقرًّا له، واعترف به الإنجليزُ إمامًا للطائفة النزارية الإسماعيلية لقبوه بـ \"آغا خان\". وتجمَّع الإسماعيليون في الهند حوله، فلما رأى فيهم الطاعةَ العمياء، كما هي طاعة الإسماعيلية لأئمَّتهم، قَوِيَ عُوده، وأخذ ينظِّمُ شؤون طائفتِه إلى أن هلك سنة 1881م. ويعتبر حسن علي شاه مؤسِّسَ الأسرة الآغاخانية، وأوَّلَ إمام إسماعيلي يلقَّب بـ (أغاخان) وهو الإمامُ السادس والأربعون في ترتيب الأئمة الإسماعيلية في رأي هذه الفرقة، وصارت هذه الفرقةُ مِن الإسماعيلية تُعرَف بـ \"الأغاخانية\". وعقائد الأغاخانية هي عقائِدُ الإسماعيلية، ومِن أبرزها ما صاغه الأغاخانيون بأسلوبِهم، وما احتوته كتبُهم ونشراتهم؛ فبنى الإسماعيليون ومنهم الأغاخانيون معتقدَهم في الألوهية على ما أسموه (التنزيه والتجريد) وانتهوا إلى تعطيلِ الله سبحانه عن كلِّ وصفٍ وتجريدِه من كل حقيقة، وقالوا: \"لا هو موجود، ولا لا موجود، ولا عالم ولا جاهل، ولا قادر ولا عاجز..!\" ونَفَوا أسماءه وصفاته بزعم أنه فوق متناول العقل. وصرفوا صفاتِ الله إلى أول مبدعٍ خلقه الله ـ بزعمهم ـ وهو العقل الأول، واعتبروا أن المخلوقاتِ كُلَّها وُجِدَت بواسطة العقل والنفس! حيث يقول مصطفى غالب، وهو من الإسماعيلية المعاصرين، في كتابه \"الثائر الحميري الحسن الصباح\": \"والعقل الأوَّلُ أو المبدِعُ الأول في اعتقاد الإسماعيلية هو الذي رمز له القرآن بـ (القلم) في الآية الكريمة (ن * وَالْقَلَمِ وَمَا يَسْطُرُونَ}، وهو الذي أبدع النفسَ الكلية التي رمز لها القرآن أيضًا بـ ( اللوح المحفوظ) ووصفت بجميع الصفات التي للعقل الكلي، إلَّا أن العقل كان أسبقَ إلى توحيد الله فسُمِّيَ بـ (السابق) وسميت النفس بـ (التالي)، وبواسطة العقل والنفس وُجِدَت جميع المبدعات الروحانية والمخلوقات الجسمانية، من جماد وحيوان ونبات وإنسان، وما في السموات من نجوم وكواكب. ويصرف الأغاخانيون صفات الربوبية والألوهية إلى أئمتهم؛ فقد ادَّعى الأغاخان الثالث أنَّ الإله متجسم فيه شخصيًّا وأن آلافًا من البشر يعتقدون ذلك. ويعتقدون أن النبوَّةَ مكتسبة وليست هبةً من الله، والنبي صلى الله عليه وسلم عندهم عبارةٌ عن شخص فاضت عليه من \"السابق\" بواسطة \"التالي\" -أي: العقل والنفس- قوةٌ قدسية صافية؛ ذلك أن الإنسانَ تميَّز عن سائر الموجودات بالاستعداد الخاص لفيض الأنوار عليه، وأن النبيَّ صلى الله عليه وسلم يمثِّل أعلى درجات هذا الاستعداد، وأن هذه القوةَ القدسيَّةَ الفائضة على النبي صلى الله عليه وسلم لا تستكملُ في أول حلولها.. وأنَّ كمال هذه القوةِ أن تنتقل من الرسولِ الناطق إلى الأساسِ الصامت، أي الإمام، وهم بهذا الاعتقاد يعتبرون الإمامةَ مكملة للنبوة واستمرارًا لها، واشترطوا على النبي صلى الله عليه وسلم قبل أن يصِلَ إلى مرتبته أن يمرَّ بمرتبة الولي؛ لأنه يجمع في نفسه الولاية والنبوة والرسالة. ويعتقدون أن رسالةَ النبي صلى الله عليه وسلم محمد صلى الله عليه وسلم ليست آخرَ الرسالات، بل هي حلقةٌ من حلقات تتابُعِ النبوة التي انتهت بظهورِ إمامهم السابع محمد بن إسماعيل بن جعفر كما يزعمون. واعتقدوا أنَّه فاتح عهد جديد، وصاحِبُ شريعة نسخت شريعة محمد صلى الله عليه وسلم!! ويتوجَّه بعض الأغاخانيون بقِبلتِهم إلى حيث يقيمُ إمامُهم، وهم لا يقيمون الصلاةَ مع المسلمين، ولا يُسمُّون أماكِنَ عبادتهم مساجِدَ، إنما بيتُ الجماعة، والصلاة عندهم عبارةٌ عن مجموعة من السَّجَدات، وهم يجمعون في صلاتِهم بين الظهر والعصر، وبين المغرب والعشاء، والأغاخانيون يعتبرون قبلةَ المسلمين الكعبة ليست سوى حِجارة، ويقولون إن الحج إليها في بداية الإسلام كان نظرًا للمستوى العقلي للنَّاسِ في ذلك الوقت، وبدلًا من ذلك يفضِّلون الذهاب للأغاخان وزيارته، وتقديم الولاء والإجلال له، ويوجدون بشكلٍ خاص في باكستان؛ حيث المركز الرئيسي في مدينة كراتشي، وفي المنطقة الشمالية الجبلية من باكستان مثل منطقة جيترال وكيلكيت، ويُعرَفون هناك بالهونزا، إضافةً إلى وجودٍ أقَلَّ في بعض المدن، مثل العاصمة إسلام أباد، ولاهور، وروالبندي. وفي غرب الهند في ولاية كجرات، لا سيما في مدينة بومباي. وكذلك في سوريا وخاصة في مدينة سلمية التابعة لمحافظة حماة، وفي بعضِ قراها، وفي جوار قلعة الخوابي قرب طرطوس، وفي قدموس. ويوجدون في شرق أفريقيا: في أوغندا وكينيا وتنزانيا وزنجبار وما حولها، وفي جزيرة مدغشقر جنوب شرق أفريقيا. كما يوجدون بشكل أقل في قم بإيران، وفي المناطق الجبلية لطاجيكستان، ومنطقة جبال الهندوكوش في أقصى الشمال الشرقي لأفغانستان، ويُعرَفون في أفغانستان باسم (مفتدي)، ولهم في عُمان حيٌّ خاص في مطرح بالقرب من مسقط. وينتشرون كذلك في بورما، أمَّا في طاجكستان وهي إحدى جمهوريات آسيا الوسطى، فإنهم يوجدون في إقليم بدخشان الذي يتمتع بما يشبه الحُكم الذاتي، ويقدَّر عددهم هناك بـ 100 ألف."},{"id":4523,"title":"تجدد القتال بين قوات محمد علي باشا وبين العثمانيين .","date":["العام الهجري :1255","الشهر القمري : ربيع الآخر","العام الميلادي :1839"],"text":"حدَثَت ثوراتٌ في بلاد الشام ضِدَّ حُكمِ إبراهيم باشا فأخضَعَها بكُلِّ شِدَّةٍ، فهدأت، وفاتَحَ محمد علي وكلاءَ الدول الأوربية في مصرَ بأنه يريد ولايةَ مصر والشام وجزيرة العرب له ولأولاده من بعدِه، ونُقِلَت هذه الرغبات إلى الدولة العثمانية التي أرسلت له مندوبًا اتَّفَق معه على أن تكون مصرُ وجزيرة العرب مِلكًا متوارثًا لأسرة محمد علي باشا وبلاد الشام لمحمد علي مدَّةَ حياتِه، وأما جبال طوروس فتكون كُلُّها للعثمانيين، وتكون هي الحدَّ الفاصل بين الدولتين، ولكِنَّ محمد علي أصرَّ على أن تكون الجبالُ له، وسار حافظ باشا على رأس جيشٍ مِن أرمينيا وسيواس وتقَدَّم إلى بلاد الشام، وفي الحادي عشر من ربيع الثاني من هذا العام التقى مع إبراهيم باشا في بلدة نزيب (نصيبين) الواقعة اليوم في تركيا إلى الغربِ مِن نهر الفرات قريبًا من الحدود السورية، فانهزم الجيشُ العثماني تاركًا عَتادَه في ساحةِ القتال، فأخذ المصريون مائة وستة وستين مدفعًا وعشرين ألف بندقية! ويذكر أنه كان في الجيشِ العثماني القائِدُ الألماني المشهور فون مولتكه، وتوفِّيَ الخليفةُ قبل أن تَصِلَه أنباءُ المعركةِ."},{"id":4524,"title":"وفاة السلطان العثماني محمود الثاني وتولي ابنه عبد المجيد الأول .","date":["العام الهجري :1255","الشهر القمري : ربيع الآخر","العام الميلادي :1839"],"text":"هو الخليفةُ العثماني السلطان محمود خان الثاني بن عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني. تولى السلطنةَ في 20 يوليو 1785م، وكان السلطان الثلاثين للدولة العثمانية، شَهِدَ عَصرُه خطواتِ إصلاحٍ واسِعةً، وقد اتَّسم عهدُه بالتوجه للغرب العلماني، وهو الذي أمَرَ محمد علي باشا مصرَ أن يجهِّزَ الجيوش على الدَّولةِ السعودية الأولى بعد أن ضَمَّت بلاد الحجاز لحُكمِها، فأغار عليها الباشا محمد علي بجيوشِه المتتالية حتى قضى عليها ودمَّر الدرعيَّةَ مَقَرَّ الحكمِ فيها، ولا تزال جيوشُه تتابع على غزو نجد بعد استرجاعِ الإمام تركي بن عبد الله الحُكمَ السعودي في نجد. والسلطانُ محمود هو الذي تخلَّصَ من الانكشارية لَمَّا وقفوا ضِدَّ الإصلاحات والتنظيمات المدنية والعسكرية التي تبنَّاها، فقضى عليهم تمامًا عام 1240هـ، وفي عهده استقَلَّت اليونان عن الدولة العثمانية بدعمٍ وتأييدٍ فرنسي وروسي وبريطاني، كما أنهكت الدولةَ العثمانية كثرةُ الحروبِ مع روسيا، ومحمد علي باشا والي مصر الطَّموح الذي يتطَلَّعُ إلى ضَمِّ بلاد الشام إلى ولايته، ووقعت الجزائِرُ تحت الاحتلال الفرنسي في سنة 1245 هـ 1830م. تعَرَّض السلطان محمود للإصابةِ بعدوى السل، ولَمَّا اشتَدَّ به المرض نُقِلَ إلى إحدى ضواحي استانبول للاستشفاء بهوائها النقي، ثم لم يلبَثْ أن عاجلته المنية، فتوفي في التاسع عشر من ربيع الثاني من هذا العام عن عمر أربع وخمسين سنة، بعد أن دام في الحُكمِ ثلاثًا وعشرين سنة وعدة أشهر، وتولَّى ابنُه عبد المجيد الأول خلَفًا له، وعمرُه دون الثامنة عشرة."},{"id":4525,"title":"السلطان العثماني عبد المجيد الأول يصدر أول دستور للبلاد .","date":["العام الهجري :1255","الشهر القمري : جمادى الأولى","العام الميلادي :1839"],"text":"لما تسلَّم السلطان عبد المجيد الأول بن محمود الثاني الحُكمَ، وهو ما يزال دون الثامنةَ عشرة من عمرِه، كان صِغَرُ سِنِّه هذا فرصةً لبعض الوزراء التغريبيين لإكمال ما بدأه والِدُه الراحل من إصلاحاتٍ على الطريقة الأوروبية، والتمادي في استحداثِ الوسائل الغربية، ومن هؤلاء الوزراءِ الذين ظهروا في ثيابِ المصلحين ومُسوحِ الصادقين (مصطفى رشيد باشا) الذي كان سفيرًا للدولة في (لندن) و (باريس)، ووصل إلى منصِبِ وزير الخارجية في أواخِرِ عَهدِ السلطان محمود الثاني، وكانت باكورةُ إصلاحاته استصدارَ مرسوم من السلطان عُرِفَ بـ (خط شريف جلخانة) أي: المرسوم المتوَّج بخط السلطان، الذي صدر عن سراي الزهر عام 1839م، وبدأ عهدٌ جديد يسمَّى عهد التنظيمات الخيرية العثمانية، التي كان من بينها احترامُ الحريات العامة والممتَلَكات والأشخاص، بصرف النظَرِ عن معتقَداتِهم الدينية، ونصَّ فيه على مساواة جميع الأديانِ أمام القانون، ولم يلقَ الخط الشريف أو الدستور الذي سانده مصطفى رشيد وقِلَّةٌ من المحيطين به ترحيبًا أو تأييدًا من الرأيِ العام العثماني المُسلِم؛ فأعلن العُلَماءُ استنكارَهم وتكفيرهم لمصطفى رشيد باشا، واعتبروا الخطَّ الشريف منافيًا للقرآنِ الكريم في مُجمَلِه، وبخاصة في مساواته للنصارى بالمسلمين، ورأوا أنَّ ذلك -وبغضِّ النظر عن النواحي الدينية- سيؤدِّي إلى إثارة القلاقل بين رعايا السلطان. وكان الهدفُ بالفعل هو ما خَطَّطَت له الحركةُ الماسونية، وهو إثارةُ الشعور القومي لدى الشعوبِ النصرانية ضِدَّ الدولة العثمانية، وبهذا المرسومِ طُعنت عقيدةُ الولاء والبراء في الصَّميمِ، ونُحِّيَت جملةٌ من أحكام الشريعة الإسلامية فيما يتعلَّقُ بأهلِ الذمَّةِ وعَلاقاتِ المسلمين مع غيرهم، وحينما رأى المسلمون أنَّ الدولة تساوي بهم النصارى واليهودَ، وتستبدل بالشريعةِ الحنيفةِ قوانينَ النصارى، وتخلَعُ الأزياء القديمة الشريفة لتتَّخِذَ زيَّ النصارى، وأحسُّوا كذلك أنَّ حكومة رشيد لا تكادُ تأتي أمرًا إلا راعت فيه خاطِرَ النصارى وحَرَصت أن لا تمسَّهم بأذًى أو تنالَهم بضَيمٍ- نفروا من ذلك نفورًا عظيمًا، ولم يجِدِ السلطان ورجالُ دولته من بدٍّ في إسقاطِه وعَزْلِه أمام مظاهِرِ السَّخَطِ الشعبي، وخَوْفهم من وثوبِ المسلمينَ وثَورتِهم."},{"id":4526,"title":"وفاة الإمام العلامة بدر الدين الشوكاني .","date":["العام الهجري :1255","الشهر القمري : جمادى الآخرة","العام الميلادي :1839"],"text":"هو الإمامُ العلَّامةُ بدرُ الدين محمد بن علي بن محمد بن عبد الله بن الحسن بن محمد بن صلاح بن إبراهيم بن محمد العفيف بن محمد بن رزق، ينتهى نسَبُه إلى خيشنة الشوكاني نِسبةً إلى شوكان من بلاد خولان باليمن، وهو أحدُ أبرز عُلَماءِ أهل السنة والجماعة وفقهائِها، ومِن كبار علماء اليمن، ولِدَ في هجرة شوكان يوم الاثنين 28 من ذي الحجة سنة 1173 هـ بصنعاء، وتولى قضاءها، برعَ في الفقه والحديث والأصول والتفسير، وله مصنَّفات وفتاوى تدُلُّ على سعة عِلمِه وعُلُوِّ شأنِه، أما مصنَّفاتُه الكثيرةُ فيَصعُبُ حَصرُها هنا، ولكن من أشهرِها: نيل الأوطار في شرح منتقى الأخبار، وله تفسير فتح القدير الجامع بين فنَّي الرواية والدراية من علم التفسير، وله إرشاد الفحول إلى تحقيق الحق من علم الأصول، وله إرشاد الغبي إلى مذهب أهل البيت في صحب النبي صلى الله عليه وسلم، وله البدر الطالع بمحاسن من بعد القرن السابع، وله الدر النضيد في إخلاص كلمة التوحيد، وله السيل الجرار المتدفق على حدائق الأزهار في الفقه، وغيرها كثير، وأخذه عنه الطلبةُ، وتكرر أخذُهم عنه في كل يوم من تلك الكتبِ، وكثيرًا ما كان يقرأ على مشايخِه، فإذ فرغ من كتاب قراءةً أخذه عنه تلامذتُه، بل ربما اجتمعوا على الأخذِ عنه قبل أن يفرغَ من قراءةِ الكتاب على شيخِه، وكان يبلُغُ دروسه في اليوم والليلة إلى نحو ثلاثة عشر درسًا، منها ما يأخذه عن مشايخه، ومنها ما يأخذه عنه تلامذته، وكان في أيام قراءته على الشيوخِ وإقرائه لتلامذته يُفتي أهل مدينة صنعاء، بل ومن وفد إليها، بل ترد عليه الفتاوى من الديار التهامية، وشيوخُه إذ ذاك أحياءٌ، وكادت الفُتيا تدورُ عليه من عوامِّ الناسِ وخواصِّهم، واستمر يُفتي من نحو العشرين من عمرِه فما بعد ذلك، وكان لا يأخُذُ على الفتيا شيئًا؛ تنزُّهًا، فإذا عوتب في ذلك قال: أنا أخذتُ العلم بلا ثمنٍ، فأريد إنفاقَه كذلك. توفِّيَ الشوكاني في ليلة الأربعاء السابع والعشرين من شهرِ جمادى الآخرة."},{"id":4527,"title":"اتفاق إنجلترا وبعض دول أوربا بشأن محمد علي باشا وإجلائه من الشام .","date":["العام الهجري :1256","العام الميلادي :1840"],"text":"كانت فرنسا توَدُّ أن تدعَمَ محمد علي باشا وأن يحتفِظَ بما أخضعه من مناطِقَ، ولكِنَّ إنجلترا لا تريد ذلك؛ لمنافسة فرنسا على مركزها في مصر، وخوفًا من منافَستِها على طريق الهند، وأما النمسا وبروسيا فتريان في قوة محمد علي خطرًا على أوربا خشيةَ أن يسيطرَ على الدولة العثمانية فيفَكِّرَ في إعادة ما كانت عليه، ولقد تمَّ عقد اتفاقية عام 1256هـ بين إنكلترا وروسيا والنمسا وبروسيا بعد انسحاب فرنسا ومحاولة اتفاقها مباشرةً مع الدولة العثمانية ومحمد علي، وتشجيعه على رفض مطالب إنكلترا، ودعمه إن عارضته إنكلترا، غير أن الاتفاقية قد نصَّت على الآتي: يجب على محمد علي أن يعيد إلى الدولة العثمانية ما أخذه من بلاد الشام، ويحتفظ لنفسِه بالجزء الجنوبي منها، مع عدم دخول عكا في هذه الجزء، يحِقُّ لإنكلترا بالاتفاق مع النمسا محاصرةُ موانئ الشام، ومساعدة كل من أراد من السكان خلع طاعة محمد علي والعودة إلى الدولة العثمانية، (ومعنى هذا: التحريضُ على العصيان)، أن يكون لمراكب روسيا وإنكلترا والنمسا حق الدخول إلى استانبول لحمايتها فيما إذا تعرَّضت لهجوم من قِبَل المصريين، ولا يحِقُّ لأحد أن يدخلها ما دامت غيرَ مهددة بهجوم. يجب أن تُصَدَّق هذه الاتفاقية خلال شهرين في لندن، كما يجب تصديقُها من الخليفة العثماني. ثم عُرِضت الاتفاقية على محمد علي فرفض ذلك، فاجتمع سفراء هذه الدول في استانبول مع الصدر الأعظم، واتخذوا قرارًا بسَلخِ ولاية مصر من محمد علي، وسحبت فرنسا سفُنَها من سواحل مصر والشام تاركةً السفن الإنكليزية بمفردها؛ مما أثار الرأيَ العام الفرنسي على الحكومةِ التي تخَلَّت عن حليفها محمد علي وقتَ أزمته، ثم حصَّنت الموانئ الشامية وخاصةً بيروت وعكا، وجاء إبراهيم باشا من مقَرِّه قرب بعلبك إلى بيروت بناءً على طلب سليمان باشا الفرنساوي، وأنزلت إنكلترا قواتِها شمال بيروت، وبدأت المعارِكُ، وهدمت أكثر المدينة وأحرقت، وكذا بقية الثغور الشامية، وتمكنت القوات الإنكليزية ومن معها من أخذ الموانئ وإجلاء المصريين، وطلب محمد علي من ابنِه إبراهيم الانسحابَ حيث لا يستطيع مقاومةَ الدُّوَل كلها، فانسحب وتعرَّض أثناء ذلك لكثيرٍ من الهجمات عليه من العرَبِ، حتى فقد ثلاثة أرباع جيشِه."},{"id":4528,"title":"تحرر فلسطين من الاحتلال الفرنسي الذي فرض عليها من نابليون  .","date":["العام الهجري :1256","العام الميلادي :1840"],"text":"وقعت فلسطينُ تحت الاحتلال الفرنسي في عام 1799م/1214هـ حين توجَّه نابليون بونابرت على رأس جيشٍ فرنسي قوامه 13000 جندي بحملةٍ عسكرية نحو فلسطين, هدفُها احتلال فلسطين والشام وإخضاعها للسيطرة الفرنسية، ومِن ثمَّ القضاء على السلطنة والإمبراطورية العثمانية في اسطنبول, فاحتلَّ العديد من المدن الفلسطينية وارتكب نابليون مجزرةً؛ حيث قتل فيها أكثر من 12000 أسيرٍ عربيٍّ، ثم أصيب جيش نابليون بداءِ الطاعون، ورغم ذلك توجَّه نابليون بجيوشه نحو عكا، ولم يتمكَّنْ مِن فتحِها؛ بسبب صمودِ أهلِها,، وخلال القرن 19 شهدت فلسطين تطوراتٍ مهمَّةً، ومنها حملة محمد علي باشا إلى فلسطين 1831م وقامت في فلسطين ثوراتٌ كثيرة ضِدَّ نظام إبراهيم باشا بسبَبِ نظام الضرائب والتجنيد الإلزامي، غيرَ أن هذه الثورات لم تنجَحْ، وفي عام 1840م عُقِدَ مؤتمر في لندن أقرَّ انسحاب محمد علي من بلاد الشام ومصر.. ثم عادت فلسطينُ إلى أحضان الخلافةِ العثمانية."},{"id":4529,"title":"تأسيس حاكم تونس أحمد باي مدرسة باردو العربية .","date":["العام الهجري :1256","الشهر القمري : محرم","العام الميلادي :1840"],"text":"أسَّس أحمد باي حاكِمُ تونس مدرسةَ باردو العربية التي تعتبَرُ أول مدرسة عصرية لتخريج الضباطِ والفنيين لجيشه النظامي، وجعل الباي مقرَّ المدرسة في سرايته، وانتقل هو إلى قصرٍ آخر، وجلب لها أساتذةً وضباطًا أوربيين، واستمرت في العمل لمدة 24 عامًا."},{"id":4530,"title":"دخول الجيش العثماني مدينة حلب .","date":["العام الهجري :1256","الشهر القمري : رمضان","العام الميلادي :1840"],"text":"استطاع الجيش العثماني الدخولَ إلى مدينة حلب في سوريا، وذلك بعد طردِ الجيش المصري بقيادة إبراهيم باشا من بلاد الشام، وذلك بعد معاهدة لندن في يوليه 1840م، والتي نصَّت على إخلاء والي مصر محمد علي باشا لبلاد الشام، وعودة الدولة العثمانية للسيطرةِ عليها."},{"id":4531,"title":"بداية الحروب الطائفية في لبنان  .","date":["العام الهجري :1257","العام الميلادي :1841"],"text":"شرعت فرنسا وإنجلترا تُثير الفِتَن الطائفية من عام 1256هـ/ 1841م بين الأقليات غير المسلِمة في لبنان، والهَدفُ هو إنهاك قوة الدولةِ العثمانية التي أرسلت قواتٍ لإنهاء الفتنة، وكذلك إيجادُ المبرر للتدخُّل الفرنسي والبريطاني في لبنان؛ تمهيدًا لتمزيقِه واحتلالِه."},{"id":4532,"title":"حكم آل ثنيان لنجد وانسحاب القوات المصرية منها .","date":["العام الهجري :1257","العام الميلادي :1841"],"text":"ظهر عبدُ الله بن ثنيان بن إبراهيم بن ثنيان بن سعود بن محمد بن مقرن بن مرخان بن إبراهيم بن موسى بن ربيعة بن مانع بن ربيعة المريدي، على مسرحِ الأحداث التاريخية في نجدٍ بعد غزوة البياض التي رافق فيها خالدُ بن سعود ضِدَّ آل شامر من هذه السنة. وكان خالد بن سعود حريصًا على مراقبةِ تحرُّكات عبد الله بن ثنيان؛ لأنه ظَلَّ يشُكُّ في نواياه تجاهه. وعندما قرر خالد بن سعود التوجُّهَ إلى بلدة الشنانة ليودِّعَ خورشيد باشا الذي قرَّر الرحيل إلى مصر بعد معاهدة لندن في 1256هـ، طلب خالد من ابن ثنيان أن يرافِقَه فتعَلَّل ابن ثنيان بالمرضِ، وعندما غادر خالد الرياض انسَلَّ ابن ثنيان وذهب إلى قبائل المنتفق في جنوبي العراق، والتجأ إلى رئيسِها عيسى بن محمد السعدون، وظلَّ هناك عدة أسابيع دارت خلالها مراسلاتٌ بينه وبين خالد بن سعود، وكان من أهَمِّ ما توصل إليه الطرفان أن يعود ابن ثنيان إلى الرياض مكرَّمًا ويُعطى أمانًا. ولما عاد ابن ثنيان إلى الرياض شَكَّ قبل أن يدخُلَها في نوايا خالد بن سعود تجاهَه، فتوجه إلى الجنوب عند قبيلة سبيع، فساعده رئيسُها راشد بن جفران، وأهالي الجنوب في الحوطة والحلوة والحريق وغيرها، ومن هناك أعلن ابنُ ثنيان رفْضَه لحكم خالد بن سعود الذي كان يعمل باسمِ محمد علي باشا فعليًّا وباسمِه هو ظاهريًّا. وظل ابن ثنيان مؤمِنًا بضرورة عودةِ الحكم السعودي رافِضًا التبعيَّةَ السياسية لسيادة محمد علي باشا، وساعده على ذلك أمران؛ الأولُ: تأييد غالبية أهالي نجد له؛ لأنه مُطالِبٌ شرعي بالحكم في غيابِ الإمام فيصل بن تركي، بالإضافةِ إلى تأييد علماء نجد له، والثاني: خروجُ قوات محمد علي باشا من الجزيرة العربية عَقِبَ توقيع معاهدة لندن عام 1256هـ، وهي المعاهدةُ التي نصَّت على أن حكم محمد علي باشا محصورٌ في ولاية مصر العثمانية فقط. فرأى النجديون أن تحرُّكَ ابن ثنيان ضِدَّ خالد بن سعود تجسيد لمبدأ الحكم الرافض للتبعيَّة السياسية للإدارة في مصر، وعدُّوا تحرُّكَه هذا تخليصًا لهم من حكم محمد علي باشا المفروض عليهم بالقوة. وقد أثبتت الحوادثُ التاريخية تدريجيًّا أن مقاومة خالد بن سعود للتيَّار الذي كان يقوده ابن ثنيان كانت مقاومةً واهية، بينما أخذ موقِفُ ابن ثنيان في النمو والتأييد؛ لذا لم يصمد خالد بن سعود وأتباعه في وجهِ ابن ثنيان بعد انسحاب القوات المصرية من نجد، واضطر خالدٌ إلى الانسحاب شرقًا إلى الأحساء ومنها إلى الكويت، ثم توجَّه إلى مكة المكرمة حيث توفِّيَ فيها. تسلَّم ابن ثنيان حُكمَ نجد ومَدَّ نفوذه إلى بلاد أخرى كانت تابعة للدولة السعودية الأولى، وذلك إحياءً لوجودها. لكِنَّ حُكمَه لم يدم طويلًا بعد أن عاد الإمامُ فيصل بن تركي سنة 1259 هـ من منفاه في مصر إلى الرياضِ؛ لأنه كان الإمامَ الشرعيَّ المبايَع. أمسك فيصلُ بن تركي بعبد الله بن ثنيان بعد مقاومةِ الأخير له، فحبسه في السجنِ، وتوفِّيَ فيه، وصلى عليه الإمامُ فيصل، ودُفِنَ في مقابر العود."},{"id":4533,"title":"انسحاب القوات المصرية من القدس وعودتها للسيادة العثمانية .","date":["العام الهجري :1257","الشهر القمري : ربيع الأول","العام الميلادي :1841"],"text":"انسحبت القواتُ المصرية من القُدسِ، وذلك بناءً على معاهدة لندن في العام الماضي 1256هـ، والتي قلَّصَت الدور المصري في الشام؛ مما أدى بالقوات المصرية إلى الانسحابِ منها، ورجوعها للسيادة العثمانية مرةً أخرى."},{"id":4534,"title":"إصدار السلطان العثماني \"فرمان مصر\" .","date":["العام الهجري :1257","الشهر القمري : ربيع الآخر","العام الميلادي :1841"],"text":"أصدَرَ السلطان العثماني \"فرمان مصر\" الذي نصَّ على إعطاء محمد علي باشا ولاية مصر والسودان وراثيًّا، وقد بَقِيَ هذا الفرمان مرعيًّا في مصر كدستور حتى نهاية عام 1914م حين أُعلِنَت الحمايةُ البريطانية على مصر."},{"id":4535,"title":"معاهدة المضائق وإلغاء معاهدة خونكار اسكله سي  .","date":["العام الهجري :1257","الشهر القمري : جمادى الأولى","العام الميلادي :1841"],"text":"بدأت إنكلترا وفرنسا تعملان لإلغاء المعاهدة الدفاعية بين روسيا والدولة العثمانية خونكار اسكله سي، التي تقضي بمرورِ السفن الروسية من المضائقِ العثمانية في الوقتِ الذي تشاء ودون تفتيشِ سُفُنِها، وقد استطاعت الدولتان فرنسا وإنكلترا الاتفاقَ مع الدول الأخرى -بما فيها روسيا- على أن تبقى المضائِقُ مُقفَلةً أمام جميع الدول بلا استثناء، ووُقِّعت المعاهدة التي عُرِفت بمعاهدة المضائق في 23 من جمادى الأولى من هذا العام، والتي نصَّت على أنه لا يجوزُ لأي دولة غير تركيا وروسيا اللتين تملكان سواحل في البحر الأسود- إبقاءُ أي سفينة حربية في هذا البحر، وقد أبطلت هذه المعاهدةُ بشَكلٍ كامل معاهدةَ \"اتفاقية رصيف هنكار\"."},{"id":4536,"title":"وقوع معركة بقعاء بين زعماء القصيم وعبد الله بن رشيد وأتباعه .","date":["العام الهجري :1257","الشهر القمري : جمادى الأولى","العام الميلادي :1841"],"text":"حدثت معركةُ بقعاء بين زعماء القصيم وجبل شمر، وملخَّصُها أن غازي ضبيان رئيسُ الدهامشة من عنزة أغار على ابن طوالة من شمر، فأخذ منهم إبلًا وأغنامًا لأهل حائل، فأغار عبد الله بن علي بن رشيد رئيس الجبل على غازي فأخذ منهم إبلًا كثيرةً، فغضب لهم أميرُ بريدة؛ لأن غازيًا من أهل القصيم، فنادى أمير بريدة في حرب ابن رشيد، وكان أهل القصيم قد اتَّفَقوا فيما بينهم لمحاربة كلِّ من يقصدهم بعداوة مهما كانوا، وأجمعوا على حرب ابن رشيد، وكان معهم حلفاءُ وأتباعٌ، فأغاروا على شمر فأخذوا منهم أموالًا كثيرة من الإبل والغنم والأثاث، فأشار يحيى بن سليم أمير عنيزة لعبد العزيز أمير بريدة: دعنا نرجع؛ فهذا العز والنصر كفاية، فأقسم ألَّا يرجِعَ، فتجهز يحيى بن سليم بجنودٍ كثيرة من أهل عنيزة وأتباعهم وتجهَّز عبد العزيز أمير بريدة بأهلِ بريدة وجميـع بلدان القصيم واجتمعوا على موضعِ ماء يسمى (بقعاء) ليقاتِلَ ابن الرشيد في بلده حائل، فساروا إلى الجبل ونزلوا بقعاء المعروفة في جبل شمر، فخرج إليهم أهلها فأمسكوهم عندهم، ونزلت عُربان عنزة على ساعد -الماء المعروف عند بقعاء- فلما علم بذلك عبد الله بن رشيد أمر أخاه عبيد العلي وفرسانًا معه أن يُغيروا على عربان عنزة، فشَنُّوا عليهم الغارة قبل الفجر فحصل قتالٌ عظيم بينهم، مرة يهزِمُهم العربان، ومرة يهزمهم عبيد وأتباعه هذا، ويحيى وعبد العزيز في شوكة أهل القصيم ينتظرون الغارةَ في بقعاء إلى طلوع الشمس، فلما لم يأتهم أحدٌ والقتال راكد على أصحابهم، فزع يحيى بن سليم بالخفيف من الرجالِ وأهل الشجاعة على أرجُلِهم، فلما وصلوا فإذا عبد الله بن رشيد ومعه باقي جنوده قد ورد عليهم مع أخيه عبيد، فانهزم عربان القصيم لا يلتَفِتُ أحد على أحد، وتبعتهم خيول شمر يأخذون من الإبل والأغنام، وتركوا يحيى بن سليم ومن معه في مكانِهم لا ماء معهم ولا رِكابَ، فلما رأى عبد العزيز ومن معه ذلك انهزموا وركبوا ركائبَ يحيى ومن معه وتركوهم، ثم وقع القتال بين يحيى وابن رشيد ثم أُسِرَ في نهايتها يحيى بن سليم وقُتِل. وقد قُتِلَ في هذه المعركة كثيرٌ من رؤساء أهل القصيم ووجهائهم وتجَّارهم، وغَنِمَ فيها ابن رشيد كثيرًا من المال والسلاح."},{"id":4537,"title":"محاصرة دير القمر والإيذان ببدء الحرب الأهلية الأولى في لبنان .","date":["العام الهجري :1257","الشهر القمري : شعبان","العام الميلادي :1841"],"text":"بادرت القواتُ الدرزية بزعامة أولاد بشير جنبلاط إلى محاصرة \"دير القمر\"؛ إيذانًا ببدء الحرب الأهلية الأولى. وعلى الرغم من استعداداتِ الموارنة وادِّعاءاتهم بما سيفعلونه بالدروز عندما تقع الحرب، تحوَّل القتال إلى كارثة مروِّعة نزلت بالموارنة في دير القمر؛ إذ دبَّت فيهم الفوضى، فأصبحوا أهدافًا سهلة للقوات الدرزية. وما إن سمع البطريرك بما حدث لدير القمر، حتى أغلق الكنائس، وطلب من كلِّ نصراني أن يحمِلَ السلاح. وهاجمت القواتُ المارونية بعضَ المواقع الدرزية المتفَرِّقة؛ لينتشر لهيبُ الحرب الأهلية بسرعة في البلاد. وتبادل الطرفانِ إحراق القرى وسلْب الأموال، والتمثيل بالأسرى والقتلى. ولكِنَّ كِفَّة الدروز كانت هي الراجحةَ؛ فبعد أن سيطروا على المناطق المارونية في الجنوب شرعوا يدقُّون أبواب النصف الشمالي الماروني عبْرَ نهر الكلب. وخلال هذه الحرب الأهلية وقف الأرثوذكس إلى جانب الدروز؛ لاعتقادهم أن تفوُّقَ الموارنة سيعَرِّضُهم لاضطهاد ماروني، حملًا لهم على ترْك عقيدتِهم. وحينما اشتَدَّ الضغط الدرزي على الموارنة وثبت لهؤلاء أن الحرب تسير في مصلحة خصومهم، وأن الجبهة المارونية هشة مفكَّكة؛ إذ كان رجال الدين الموارنة في جانب، والإقطاعيون في جانب آخر، فضلًا عن تعدد الخلافات بين الزعامات المارونية- سارَعَ الموارنةُ حينها إلى السلطاتِ العثمانية، والقناصل الأوروبيين -خاصة القنصل الفرنسي. وأسفرت الحربُ عن موافقة البطريرك الماروني على إبعادِ الأمير بشير الشهابي الصغير الدرزي عن الحُكم، على أن يحلَّ محلَّه الأميرُ بشير الشهابي الكبير؛ الأمر الذي ترك انطباعًا سيئًا لدى القنصل الإنجليزي عن رجالِ الدين الموارنة."},{"id":4538,"title":"ثورة الدروز في لبنان وتقسيم البلاد إلى شطرين بين الدروز والموارنة  .","date":["العام الهجري :1258","العام الميلادي :1842"],"text":"دعمت فرنسا الموارنةَ في لبنان على حين دعَمَت إنكلترا الدروز، فاعتدى الدروزُ على الموارنة في عام 1257هـ ودخلوا ديرَ القمر وارتكبوا أبشَعَ الأعمال، وكرَّروا الاعتداء عام 1261هـ، فعزل الخليفةُ العثماني الأميرَ بشير الشهابي ووضع واليًا عثمانيًّا مكانه، وحَرَم الجبل مما كان له من امتيازات، ولم تقبل الدولُ الأوربية بذلك فاضطرَّ أن يعيد للجبل امتيازاتِه، وأن يعيِّنَ قائمينِ درزي وآخر ماروني، وذلك في عام 1258هـ، ولكن الأمر لم يستقِمْ لاختلاط الطوائِفِ في القرى، فرأى الخليفة ضمَّ شمال الجبل -أي منطقة الموارنة- إلى ولاية طرابلس، فاحتَجَّ الموارنة فأرسل من يدرس الموضوعَ ويقَدِّمُ الحلول، فلم يفد ذلك شيئًا، وأصر الدروز أن يبقى الموارنة تحت سلطانِهم، وفَضَّل الموارنة بعدئذ أن يتَّبِعوا ولاية أخرى من أن يكونوا تحت سلطانِ الدروز، فاستحسن الخليفةُ الرأيَ."},{"id":4539,"title":"تقديم مشروع لتقسيم لبنان وموافقة الدول الكبرى عليه .","date":["العام الهجري :1258","العام الميلادي :1842"],"text":"كان الأميرُ ميترينخ وزيرُ خارجية ومستشار النمسا، صاحِبَ مشروعٍ مبنيٍّ على الواقِعِ الموجود في لبنان، وقِوامُه الاعترافُ بالحقيقة الطائفية في هذا البلد، إذا أريد التوصُّلُ إلى نظامِ حُكمٍ يكون مقبولًا من الطرفين المتنازعَين: الموارنة والدروز، على أن يكون ذلك في إطارٍ مِن الاعتراف بالسيادة العثمانية. فدعا المستشارُ النمساوي إلى تقسيم الجبل، بإنشاء وحدتَين إداريتَين؛ إحداهما درزية في نصفه الجنوبي، ويحكُمُها حاكم درزي. والثانية مارونية تحت حاكم ماروني في النصف الشمالي من الجبل. وقد حصل هذا المشروعُ على موافقة الدول الكبرى، وعُدَّ ذلك نصرًا كبيرًا للدبلوماسية الأوروبيَّةِ على البابِ العالي."},{"id":4540,"title":"استيلاء عبد الله بن ثنيان على الأحساء .","date":["العام الهجري :1258","الشهر القمري : محرم","العام الميلادي :1842"],"text":"بعث عبد الله بن ثنيان قوةً بقيادة عبد الله بن بتال المطيري لاحتلال الأحساء، فاستولى عليها، ثم عيَّن عمر بن عفيصان أميرًا على الأحساء وكلَّفه بالسير إلى القطيف فأخضعها، وهدَمَ سور سيهات، وقبض على أميرها ابن عبد الرحيم، كما أشخص أميرَ القطيف علي بن غانم إلى نجد لمقابلة ابن ثنيان، فوجَّه إليه تهمة الخيانة العظمى بالتواطؤِ مع آل خليفة، فسجنه وصادر أموالَه وأملاكه، ثم عيَّنَ أحمد السديري أميرًا على القطيف، وكتب إلى ابن عفيصان بالرجوعِ إلى الأحساء، كما بعث قوةً إلى ميناء العقير، فاستخلصه من أيدي آلِ خليفة، وكان أهل الأحساء قد رحَّبوا بحكم ابن ثنيان في البدايةِ إلَّا أنهم سخطوا عليه أخيرًا بسبب أعمالِه في القطيف."},{"id":4541,"title":"نزول الغيث على نجد بعد سنوات عجاف .","date":["العام الهجري :1258","الشهر القمري : رمضان","العام الميلادي :1842"],"text":"في ليلةِ عشرين من رمضان أنزل اللهُ من الغيث العظيم على نجدٍ، فسالت منه الوديان، وضاقت من جَورِ سَيلِه الشعبان، وعمَّ جميع الأوطان والبلدان حتى أشفقوا من الغرق، فتضَرَّعوا إلى الله خوفًا من الغرق، فكان هذا السيلُ رحمة من الله للعباد والبلدان، وإنقاذًا من بعد السنين الشداد، فجرى به كلُّ وادٍ، وكان قد مضى على وادي سدير نحو أربع عشرة سنة ما عَمَّ بلدانَه سَيلُه، وغارت آبارُه وهلك كثيرٌ من نخله، فأخذ وادي منيخ أكثَرَ من خمسة أيام وجرت الأودية كلُّها بسيلٍ لم يُعرَفْ مِثلُه منذ أعوام، ونزل على الوشم مسيلٌ عظيم لم يُعرَف له نظير منذ ثلاثين سنة، حتى قيل: إن وادي بلد القرابين شال صخرةً عظيمة في مجراه ولا يدري أحد أين رماها، وجرى وادي حنيفة وخرب العامِرَ وخرب السيل في الفرع والخرج والجنوب، وجعل كلَّ عامرٍدامرًا، وعم الضِّرابَ والآكامَ، وابتهج به جميعُ الأنام، وهذه المنة الجسيمة كلها في هذه الليلة العظيمة، وذلك في الوسمي لسبعٍ مضين من حلول الشمس برج العقرب، وكان الناس في غاية الضعفِ مِن قلة البَذرِ وقِلَّة العوامل والرجال بعد سنين القحط، والوقت الشديد والجَدب المبيد، وغَور الآبار، وموت النخيل والأشجار، حتى جلا أهلُ البلدان ولم يبقَ في كُلِّ بلد إلا عُشرُ أهلِها، وتتابعت المصائب عليها، وتشتَّت شَملُها وتفَرَّقوا في الأقطارِ، وأكثَرُهم جَلَوا إلى البصرة وما حولها من الديار، ودام هذا الوقتُ كلَّ سنة بزيادةِ شِدَّةٍ إلى أن مضت تسعُ سنين، فأنزل الله لهم هذه السنة هذا السيلَ العظيم البركة، فكانوا على أوفَقِ التيسير في البَذرِ والعوامل والمحترفين، وسخَّر الله الغنيَّ للفقير، والمستأجِرَ للأجير، والمُعير للمستعير، حتى لم يحتَجْ حاجةً أحدٌ تلجِئُه إلى ترك الزرع، فضاقت كلُّ بلد بزروع أهلها، وزرعوا وَعْرَها وسهلها، وأعشبت الأرض من أوانها، وأربعت المواشي في وسط بلدانها وتزخرفت."},{"id":4542,"title":"ظهور الطريقة السنوسية في الجبل الأخضر بليبيا .","date":["العام الهجري :1259","العام الميلادي :1843"],"text":"بدأت الدَّعوة السنوسية في الجزائر على يدِ مؤسِّسِها محمد بن علي المعروف بالسنوسي الكبير، وبدأت هذه الدعوةُ تنتشِرُ داخِلَ أفريقيا من الصومال إلى السنغال وعلى طول الطريق إلى تشاد، وفي المغرب، وكانت أكثر المناطق التي انتشرت فيها بقوة هي ليبيا، وخاصةً منطقة الجبل الأخضر؛ حيث كان فيها أكثر من 300 زاوية سنوسية تعيشُ على الزراعة، وهم أوَّلُ من قاوم المحتلين الإيطاليين في ليبيا، وكان من أبرَزِ رجال هذه الدعوة عمر المختار، المعروف في الجبل الأخضر، كما انتشرت في برقةَ."},{"id":4543,"title":"موت الزرع قبل أن يشتد سنبله .","date":["العام الهجري :1259","العام الميلادي :1843"],"text":"حصل في هذا العامِ بَردٌ في آخر الحميم على أوَّلِ دخول الذراع مع طلوع المؤخر، فمات كل زرع لم يشتَدَّ سنبله، وما اشتد في سنبله سَلِمَ من الموت، وهذا لم يُعهَدْ في هذا الوقتِ."},{"id":4544,"title":"استعمار فرنسا لجزر القمر .","date":["العام الهجري :1259","العام الميلادي :1843"],"text":"استعمرت فرنسا جُزُرَ القمر الكبرى وأنجوان ومايوت وموهيلي، ما بين عامي 1843 و1920م، وقد وضعَتْها فرنسا تحت إدارةِ الحاكم العام في مدغشقر. وفي سنوات لاحقةٍ أقام فيها المقيمون الفرنسيون والشركاتُ الفرنسية وبعضُ التجار العرب الأغنياء اقتصادًا زراعيًّا يعتَمِدُ على المزارع التي كانت تصدِّرُ ثلث الإنتاج. وفي سنة 1947م أصبحت جزرُ القمر واحدةً من الأقاليم الفرنسية فيما وراء البحار، وأعطيت تمثيلًا في البرلمان الفرنسي. وقيل: عُرِفَت جزر القمر دوليًّا لأول مرة عندما ظهرت على خريطةِ العالم التي رسَمَها الرحالة البرتغالي ديوجو ريبير عام 934هـ 1527م، ورغم سيطرةِ النفوذ الإسلامي والعربي على الجزرِ، فإنَّ الاضطرابات كانت تسودها، واستطاعت فرنسا أن تفرِضَ سيطرتها على جزيرة مايوت هذا العام، وقام وفدٌ من سكان جزيرة أنجوان بمقابلةِ قائد القوات المصرية في شرق إفريقيا رضوان باشا في 1292هـ  1875م، وطلبوا منه دخولَ الجزيرة تحت الحمايةِ المصرية، إلَّا أن الحكومة المصرية كانت مشغولةً بتدعيم سيطرتها على مناطِقَ أخرى أكثَرَ مِن اهتمامِها بتلك الجزر الصغيرة؛ لذلك لم تعطَ هذه الدعوةُ أيَّ اهتمام، فوقَّع حكام أنجوان معاهدة مع الإنجليز سنة 1300هـ 1882م نصَّت على إلغاء تجارة الرقيق في الجزيرة، فثار تجَّارُ الرقيق على هذه المعاهدة، واندلعت حروب أهلية، فطلب حكامُ الجزيرة فَرْضَ الحماية الفرنسية عليهم، ووقِّعَت معاهدة بذلك في 1304هـ 1887م، أما جزيرة موهيلي فاحتلتها فرنسا سنة 1303هـ 1886م. ورغم وجودِ أغلبية مسلمة في الجُزُر الأربع فإنَّهم لم يكن لهم دور فعَّالٌ في مقاومة النفوذ الفرنسي، كما لم يحاولوا تنظيم أنفسهم، وانشغلوا بالحروبِ الأهلية فيما بينهم. وصدر قرارٌ فرنسي سنة 1330هـ 1912م أصبحت بموجِبِه هذه الجزر مستعمرةً فرنسية، وأُلحِقَت بمدغشقر، وبَقِيَت تتبعها عامين، ثم انفصلت وأصبحت مستعمَرةً مستقلةً حتى الحرب العالمية الثانية. وفَرَضَت بريطانيا سيطرتَها على الجزر أثناء الحربِ بعد هزيمة فرنسا أمام ألمانيا، واتخذتها قاعدةً لسفنها الحربية في المحيط الهندي، ثم عادت هذه الجزرُ إلى فرنسا بعد انتهاء الحرب."},{"id":4545,"title":"استعادة الإمام فيصل بن تركي قصر الدمام .","date":["العام الهجري :1259","العام الميلادي :1843"],"text":"بعد أن استقَرَّ الإمام فيصل بن تركي في الرياض وبايعه رؤساءُ القبائل وأمراء بلدان نجد، تطلع إلى الخليج، وبدأ باستعادة قَصرِ الدمام من آل خليفة حُكَّام البحرين، وجعل فيه قوةً سعودية، وحاول أكثَرَ مِن مرة ضَمَّ البحرين ولكِنَّه لم يتمكَّنْ من ذلك؛ بسبب التدخُّلات البريطانية التي كانت تخشى على مصالحِها ونفوذها، فعَمَدت إلى ضرب ساحل الأحساء، وانتهى الأمرُ بأن توسط سعيد بن سحنون حاكِمُ أبو ظبي بين الطرفين، على أساس أن تقوم البحرين بدفعِ الزكاة للدولة السعودية سنويًّا."},{"id":4546,"title":"وفاة عيسى بن محمد السعدون رئيس المنتفق محترقًا .","date":["العام الهجري :1259","العام الميلادي :1843"],"text":"هو عيسى بن محمد السعدون رئيس المنتفق، احترق في منزلِه، وسببُ ذلك  أنَّ بيوتَهم التي يأوون إليها من قَصَبٍ يتَّخِذونها في وقت القيظ على شاطئ الفرات، فاتَّفق في ليلة نام مع أهله، ونسيت الخادِمُ الفنر أن تطفِئَه وتركته معلقًا على القصب المحكَم شَدُّه كالجدار، فعَلقَت النارُ فيه فاضطرمت في البيتِ وهو في نومِه مع أهله على سريره، فما استيقظ إلا وقد شملت النار جميعَ البيت وليس له مَهربٌ، وعليه بابٌ مُحكَمٌ، فهرب إلى أسفل البيت بين صناديقَ رجاءَ أن ينجو أو يأتيَه من يخرجه، فلما ظهرت النارُ في البيت واجتمع الناسُ لها، فلما أطفؤوها بالماء، وجدوه قد احترق إلى مجمعِ فخذيه، فأخذوا باقيَه ودفنوه، واذا بزوجته نائمةٌ على سريرها قد احترق جانبُها الأعلى، وكانت سيرتُه فيما ظهر غيرَ ما كان عليه أسلافُه من محبة أهل السنة والجماعة وكراهة الرافضةِ وغيرهم من أهل البِدَع، بل كان يُكرِمُ الرافضةَ ويحتَرِمُهم ويُدنيهم، وهو في الظاهِرِ على طريقة أهلِه وعشيرتِه فيما يَدَّعي."},{"id":4547,"title":"تأليف البرلمان الإنجليزي \"لجنة إعادة أمة اليهود إلى فلسطين\"  .","date":["العام الهجري :1259","العام الميلادي :1843"],"text":"ألَّف البرلمان الإنجليزي لجنة \"إعادة أمة اليهود إلى فلسطين\", وفي العام نفسه تألَّفت في لندن \"الجمعية البريطانية والأجنبية للعمل في سبيل إرجاع الأمة اليهودية إلى فلسطين\". وألحَّ رئيسها القس كريباس على الحكومة البريطانية كي تبادِرَ للحصول على فلسطين كلِّها من الفرات إلى النيل ومن المتوسِّط إلى الصَّحراء."},{"id":4548,"title":"مغادرة الإمام فيصل بن تركي لمصر .","date":["العام الهجري :1259","الشهر القمري : محرم","العام الميلادي :1843"],"text":"تمكَّن الإمام فيصل بن تركي من الهروبِ مِن سِجنِه في مصر متدلِّيًا بحبل، ونزل معه ابنه عبد الله، وأخوه جلوي بن تركي، وابن أخته عبد الله بن إبراهيم، وكان ذلك ليلًا، ثم غادروا مصر حتى وصلوا جبل شمر، فاستقبلهم عبدُ الله بن علي بن رشيد -والي جبل شمر مِن قِبَل فيصل- فأكرمهم ووعدهم بالمساعدةِ بالمال والرِّجالِ، والقتال معهم."},{"id":4549,"title":"ظاهرة كونية غريبة في السماء .","date":["العام الهجري :1259","الشهر القمري : صفر","العام الميلادي :1843"],"text":"في أوَّلِ يومٍ مِن صفر بعد صلاة المغرب في وسَطِ القبلة ظهر عمودٌ أبيض مستطيل من الأفق إلى وسط السماء، مثل المنارة في رأي العين، وانزعج الناسُ لذلك، وكثر التنافس في طلوع هذه الآية، وما زال يضمحلُّ شيئًا فشيئًا إلى طلوع شهر صفر."},{"id":4550,"title":"استعادة الإمام فيصل بن تركي حكمه في نجد .","date":["العام الهجري :1259","الشهر القمري : ربيع الآخر","العام الميلادي :1843"],"text":"لما بلغ ابنَ ثنيان في الرياض خبَرُ وصول فيصل بن تركي جبل شمر، عزم على قتالِ فيصل ومَنْعِه من دخول الرياض, ودارت مفاوضاتٌ ومراسلات رفض فيها ابن ثنيان الخروجَ مِن الرياض وتسليمَها لفيصل، واستعَدَّ الطرفان للحربِ، لكن فيصل تمكَّن من دخول الرياض بدون قتالٍ، وقبض على ابن ثنيان وحَبَسَه في أحد بيوت القصر إلى أن مات فيه. وتمكَّن الإمام فيصل من استعادة أكثر الأملاك التي خضعت له في فترةٍ وجيزة."},{"id":4551,"title":"وفاة الأمير عبد الله بن ثنيان .","date":["العام الهجري :1259","الشهر القمري : جمادى الآخرة","العام الميلادي :1843"],"text":"هو عبد الله بن ثنيان بن إبراهيم بن سعود بن محمد بن مقرن، من أمراء نجد، وكان في الرياض يُظهِرُ الطاعة لخالد بن سعود القادم من مصر الذي أخرج فيصل بن تركي وحلَّ محلَّه، فعمل ابن ثنيان على إخراج خالد والقوات المصرية، وكان شجاعًا مَهيبًا أطاعته نجد، فصَفَت له الإمارةُ إلى أن عاد فيصل بن تركي من أَسْرِه في مصر، فامتنع عليه عبدُ الله، وظَفِرَ به فيصل فحبسه في الرياض، فمات في السجن، فخرج فيصل في جنازته وصلى عليه. أنجب عبدُ الله ثلاثةً من الأبناء، وهم: محمد، وعبد القادر، وعبد الله، وقد سمِّيَ على والده لأنَّ والده توفِّيَ وهو حَمْلٌ, وقد نزح عبد الله بن عبد الله الملقَّب باشا إلى استانبول وخلع عليه هناك لقَبَ باشا وتوفِّيَ باستانبول، وقد أنجب باشا عبد الله أربعة أبناء: أحمد، وعبد القادر، وسعود، وسليمان الذي أنجب ابنًا واحدًا هو عبد العزيز بن سليمان، الذي تولى أمانة مدينة الرياض عام 1386هـ."},{"id":4552,"title":"قتل أمير القطيف السابق علي بن عبد الله بن غانم .","date":["العام الهجري :1260","العام الميلادي :1844"],"text":"لما استعمل الإمامُ فيصل عبدَ اللهِ بنَ سعد المداوي أميرًا على القطيف استلحق علي بن عبد الله بن غانم الرافضي رئيس القطيف السابق، فناوبه بأشياءَ ذُكِرَت له فضَرَبَه بالخَشَبِ حتى مات، فغضب الإمامُ فيصل وأرسل إليه غلامَه بلال بن سالم الحرق، فأشخصه إلى الإمام وجلس مكانَه في القطيف، فلما أتى المداوي إلى الإمام ذكَرَ له عُذْرَه في ضربه لابن غانم، فقبل منه ورَدَّه إلى القطيف أميرًا."},{"id":4553,"title":"معارك عنيفة بين الجزائريين والفرنسيين في منطقة جبال الأوراس .","date":["العام الهجري :1260","الشهر القمري : ربيع الأول","العام الميلادي :1844"],"text":"اندلعت معاركُ عنيفةٌ بين الجزائريين والفرنسيين، وذلك في أثناء الاحتلال الفرنسي لمنطقة جبال الأوراس بقيادة أحمد باي، وقد استمَرَّت عشرين يومًا."},{"id":4554,"title":"الاعتداء الثاني للدروز على الموارنة في جبل لبنان .","date":["العام الهجري :1261","العام الميلادي :1845"],"text":"لم يُعجِبِ الدروزَ أن يكون الموارنة في الجبل تحت سلطةِ غيرهم -وهو الرأي الذي أخذ به الخليفةُ العثماني في حلِّ المشكلة بين الدروز والموارنة في الجبل- فقام الدروز باعتداءاتِهم الثانية في هذا العامِ بعد الاعتداء الأول عام 1258هـ، فأرسلت الدولةُ العثمانية بعد ذلك جيوشَها واحتَلَّت المنطقةَ كُلَّها، وأعلنت فيها الأحكامَ العُرفيَّةَ، ثم اتفقت الدولُ الأوربية مع الخليفة على تشكيلِ مجلسٍ يَضُمُّ أعضاءً مِن المجموعتين ومن غيرهم، ولم تنته القضيَّةُ إلا بمذابِح عام 1277هـ."},{"id":4555,"title":"إبادة القوات الفرنسية لقبيلة أولاد رباح الجزائرية .","date":["العام الهجري :1261","الشهر القمري : جمادى الآخرة","العام الميلادي :1845"],"text":"أقدمت القواتُ الاستعمارية بقيادة الجنرال بليسي السفَّاح على جريمة خطيرة ظلَّت طيَّ الكتمان، وهي محارِقُ في كلٍّ مِن النقمارية وأولاد رباح، وحسَبما تداول عن هذه المعارك أن القواتِ الاستعمارية كانت وراءَ كُلِّ أنواع التعذيب التي حدثت في المنطقة، ومنها ثلاثُ محارق في النقمارية وأولاد رباح، حيث تم حشدُ مئات المواطنين في شهر أوت من سنة 1845م داخِلَ مغارات وكهوف تحت الأرض وبعد الغَلقِ عليهم بالإسمنت المسلَّح، تم إبادة أكثر من 1000 مواطن (رجال ونساء وشيوخ وأطفال) عن طريق المحارِقِ! وكل هذه الإبادة الجماعية هي ردُّ فعل على انطلاق مقاومةٍ شعبية من طرَفِ السكان الذين لم يتقَبَّلوا وجود قوات الاستعمار بمنطقتِهم."},{"id":4556,"title":"وقعة بين ابن رشيد رئيس جبل شمر وأهل عنيزة .","date":["العام الهجري :1261","الشهر القمري : رمضان","العام الميلادي :1845"],"text":"في رمضانَ من هذه السنة كانت وقعةُ ابن رشيد رئيس الجبل على أهل عُنيزة، وذلك أنَّ عبد الله بن سليم بن زامل أميرَ عنيزة أخذ إبلًا لابن رشيد، فطلب منه الأداء، فأبى عليه وحَذَّره وأنذَرَه، فجهَّز ابنُ رشيد إليهم أخاه عبيد في 250 مطية وخمسين من الخيل، فأغار على غَنَم عنيزة قريبًا من البلد، ففزع أهلُ عنيزة، وكان ابن رشيد قد جعل لهم كمينًا، فلما نشب القتالُ خرج عليهم الكمين فولَّوا منهزمين، واستولى عبيد وقومه على أكثَرِ الفَزع، فقتلوا في المعركة كثيرًا من رجالهم، منهم الأمير عبد الله بن سليم وإخوته وبنو عمه، قتَلَهم صبرًا، وأمسك منهم رجالًا وربطهم وأنفَذَهم إلى أخيه عبد الله في الجبل، فركب إليه عبد العزيز بن الشيخ العالم عبد الله أبا بطين، فألفى عليه في الجبل فأطلق له رجالًا وكساهم."},{"id":4557,"title":"عدوان العجمان على حاج الأحساء والقطيف والبحرين .","date":["العام الهجري :1261","الشهر القمري : ذي القعدة","العام الميلادي :1845"],"text":"في آخِرِ هذه السنة أقبل حاجُّ الأحساء والقطيف والبحرين وسيف البحر ومعه عجمٌ كثيرٌ، فرصد لهم في الطريق فلاح بن حثلين رئيسُ العجمان ومعه أناسٌ مِن أعراب سبيع، فشَنُّوا عليهم الغارةَ، فتفرق من الحاج نحوًا من نصفه، وانهزم أكثرُ الحاج، فمنهم السالم والمأخوذ، فلما بلغ الإمام فيصل خبَرُهم استنفر المسلمين فرَكِبَ من الرياض آخِرَ ذي القعدة ومعه الشيخ العالم القاضي عبد الرحمن بن حسن ابن الشيخ محمد بن عبد الوهاب ونزل حريملاء حتى اجتمع عليه غزوانه من جميع النواحي، فلما سمع ابن حثلين بمغزى الإمامِ انهزم إلى ديرة بني خالد، فقصده الإمام في ديار بني خالد فأقبل عليه رؤساءُ العُجمان وسبيع، وسألوه بالله ألا يأخُذَ البريءَ المطيع بالغَوِيِّ المضيع، وهذا الجاني ابن حثلين ومن تبعه دونَك, فعفا عنهم وأمَرَهم أن يَخرُجوا من ديرة بني خالد هم وأتباعهم من سبيع ولا يمكثوا فيها ولا يومًا واحدًا، فرحلوا عنها وقصدوا السرَّ فشَنَّ عليهم عربان مطير وغيرُهم، فأخذوا كثيرًا من أدباشهم وأوباشهم، فمزَّقَهم الله كلَّ ممزَّق, ثم إن رؤساء العجمان طلبوا من فيصل الأمان وأنهم يدفعون ما أخذوا للمسلمين والنَّكال، فأخذ فيصل منهم خمسة وعشرين فرسًا، ثم أرسل الإمام فيصل قافلةً إلى أهل الأحساء فيها زهاب وغيره، أمَّا ابن حثلين فانسلخ العُجمان عنه وتبرأوا منه، فهرب إلى محمد بن هادي بن قرملة، فلما علم الإمام بذلك قصد ابن حثلين فهرب من عند ابن قرملة فرجع الإمامُ فيصل إلى الرياض."},{"id":4558,"title":"محاسبة الإمام فيصل بن تركي قطَّاع الطريق وتصفيتهم .","date":["العام الهجري :1262","العام الميلادي :1845"],"text":"تمكَّن الإمام فيصل خلال هذا العامِ مِن القبض على فلاح بن حثلين وقطع رأسَه في الأحساء  على إثرِ قَطعِه الطريقَ على حاجِّ الأحساء والقطيف والبحرين، وكذلك تمكَّنَ من مشعان بن هذال لَمَّا أخذ الحدرة ولم يمتَنِعْ بعدها إلا خمسين يومًا حتى اقتصَّ منه، وكذلك هادي بن مذود لما أخذها لم يحُلْ عليه الحول، وقطع الله أصله ونسْلَه على يد الإمام، وكذلك ما جرى على الدبادية -وهم فرع من مطير- قتَلَهم مرةً واحدةً لَمَّا فعلوا بأهل سدير ما فعلوا بحَفرِ الباطن، وما جرى على عُربان السويلمات من القَتلِ والأخذ لَمَّا قطعوا طُرُق المسلمين."},{"id":4559,"title":"الإنجليز يبيعون كشمير لأسرة الدوغرا الهندوسية لمدة مائة عام .","date":["العام الهجري :1262","العام الميلادي :1845"],"text":"كانت كشمير تحت حكم المغول المسلمين، ثم سيطر الأفغانُ عليها بعد المغول، ثم بعد التدخُّل الإنجليزي استطاع السيخُ أن يتحكَّموا بالإقليم الكشميري، وكانت أيامُهم فيها من أسوأ الأيام على المسلمين من إراقة الدماء وهدمِ المساجِدِ، ثم أخذها الإنجليزُ مِن السيخ عام 1262هـ / 1846م ثم قاموا ببيعِها بموجِبِ اتفاقية أمريتسار (وهي المدينة التي تعد قاعدة السيخ) بمبلغ سبعة ملايين ونصف مليون روبية إلى أسرة الدوغرا الشيخية لمدة مائة عام من 1846 إلى 1946م، ولم ينس الإنجليز (لتمُرَّ هذه الصفقة على المسلمين) أن يجعَلوا أسرة الدوغرا تتعهَّدُ بأن تحكُمَ رعيتها المسلمةَ بالعدل، وكان -كما هو مشهور- حبرًا على ورق، وإلَّا فالواقع خيرُ شاهد على ما قام به الدوغرا تجاهَ المسلمين الذين ظلُّوا طيلة قرن من الزمن مكَبَّلين بأغلال العبودية والاضطهاد والتنكيل، رغم أنهم الأكثرية؛ فهم يشكلون ثمانين بالمائة من السكان!"},{"id":4560,"title":"وفاة فلاح ابن حثلين أمير العجمان  .","date":["العام الهجري :1262","العام الميلادي :1845"],"text":"هو فلاح بن مانع بن حثلين العجمي أميرُ قبيلة العجمان، قام في السنة الماضية ومعه بعض العُجمان وعربان من سبيع بالغارة على حاجِّ الأحساء والقطيف والبحرين وسيف البحر، فطلبه الإمام فيصل بن تركي ففَرَّ إلى  ديرة بن خالد، فأجلى الإمام فيصل العجمانَ من ديرة بني خالد، ففَرَّ ابن حثلين إلى محمد بن هاد بن قرملة بعد أن انسلخ منه العجمان وتبرؤوا منه، ثم إنَّ فلاح بن حثلين قام يدير الرأيَ في الحيلة للرجوعِ إلى ديرة بني خالد، ووقع في نفسِه أنَّه لا يَقدِرُ على ذلك إلَّا بمصافاة الدويش وأتباعه، فرحل من مكانِه وقصَدَهم في ديرة بني خالد، ومعه قطعةٌ قليلة من العجمان، فنزل على منديل بن غنيمان رئيسِ من الملاعبة من مطير، وطلبه أن يجيره ويجمع بينه وبين الدويش، فأبى ابن غنيمان وقال: لا نقدِرُ على ذلك، ونحن بيدِ الإمام فيصل، ولا يجسرُ يجيرُ عليه أحد، وأرسل منديل إلى الحميدي الدويش وأخبره بالأمر، فركب من ساعته بعَدَدِه وعُدَّتِه وألفى عند ابن غنيمان ورحل معه بابن حثلين ومن تَبِعَه وأدخلهم مع عُربانه، وأرسل إلى فيصل يخبره، وركب وافدًا عليه ومعه رؤساء قومِه فلما دخلوا على الإمام ذكَرَ لهم ما فعل ابن حثلين بالمسلمين، وقال: لا بدَّ من إمساكه وأخْذِه من عندكم وأخذ الثأر منه للمسلمين، وألزمه بذلك فلم يجِدْ بدًّا من طاعته، فأمر الإمامُ على رجال من خدَّامه يركبون معهم ويأخذون ابن حثلين من عند الدويش، وقصدوا به الأحساءَ وأدخلوه قصرَ الكوت عند أحمد السديري، فقطعوا رأسَه، وعندما قُتِلَ فلاح بن حثلين خلفه أخوه العجمان الشيخ حزام بن حثلين عمُّ راكان بن فلاح حوالي خمسة عشرة عامًا في زعامة قبيلة العجمان، ثم تنازل عن زعامته لابن أخيه الشيخ راكان بن فلاح بن حثلين، عام 1276هـ."},{"id":4561,"title":"زيارة محمد علي باشا والي مصر لاستانبول .","date":["العام الهجري :1262","الشهر القمري : رجب","العام الميلادي :1846"],"text":"زار محمد علي باشا والي مصرَ استانبول عاصمة الدولة العثمانية؛ لتقديم فروضِ الولاءِ والطاعة، وذلك بعد سنوات من الحروبِ بين الجانبين، وكان عمرُه آنذاك 77 عامًا، وتعَدُّ هذه الزيارةُ هي الأولى والأخيرة له للعاصمة العثمانية، وقد استمَرَّت لمدة 29 يومًا."},{"id":4562,"title":"وفاة العلامة أشرف علي التهانوي .","date":["العام الهجري :1262","الشهر القمري : رجب","العام الميلادي :1846"],"text":"هو الشيخُ المحَدِّث الكبير، أشرف علي التهانوي بن عبد الحق بن الحافظ فيض علي، صاحِبُ التصانيف النافعة المفيدة، وُلِدَ صباح الخامس من شهر ربيع الثاني سنة 1280هـ / 10 سبتمبر 1863م، في إحدى قرى الهند وهي قرية (تهانه بهون)، وترعرع في بيئة علمية، وكان منذ نعومة أظفاره مكبًّا على العلم والعلماء، بعيدًا عن اللهو. ويعتبر أشرفُ علي التهانوي أحد كبار مشيخة ديوبند، تخرَّج عليه خلقٌ كثيرون، وعلماء أمثال: الشيخ المفتي محمد شفيع المفتي الأكبر بباكستان، والعلامة السيد سليمان الندوي، والمحدِّث ظفر أحمد التهانوي، والشيخ محمد إدريس الكاندهلوي، والشيخ عبد الباري الندوي. مات رحمه الله في النصف الأول من ليلة الأربعاء، 16 رجب، وصلَّى عليه ابن أخته العلَّامة المحدث الشيخ ظفر أحمد العثماني التهانوي، ودُفِنَ في المقبرة التي وقَفَها الشيخ بنفسه لدفنِ موتى المسلمين."},{"id":4563,"title":"قيام السلطنة القعيطية وصراعها مع الدولة الكثيرية .","date":["العام الهجري :1263","العام الميلادي :1846"],"text":"أُسِّستِ المَملَكاتُ القُعَيْطيَّةُ في حَضرَموتَ على يَدِ عُمَرَ بنِ عَوَضِ بنِ عبدِ اللهِ القُعَيْطيِّ، والأسرةُ القُعَيْطيَّةُ تَرجعُ جُذورُها إلى قَبيلةِ يافِعٍ، فبَعدَ مَوتِ السُّلطانِ بَدرٍ أبي طُوَيرِقٍ الكَثيريِّ، دخَلَ حُلَفاؤُه مِنَ السَّلاطينِ في تَطاحُنٍ على السُّلطةِ، حتى إنَّ بَعضَ السَّلاطينِ الكَثيريِّينَ استَنجَدَ بالجيشِ الإماميِّ في صَنعاءَ، فكانَ أنْ تلاشَت تَدريجيًّا السُّلطةُ الكَثيريةُ، وأصبَحتِ الشِّحرُ وحَضرَموتُ ضِمنَ الحُكومةِ المركزيةِ في صَنعاءَ، فاضطُرَّ الكَثيريونَ إلى الاستِنجادِ بقَبائِلِ يافِعٍ ضِدَّ السُّلطةِ الإماميةِ، فتمكَّنوا مِن إخراجِها مِن حَضرمَوتَ، ولكنَّ المنطقةَ وقعت في يَدِ يافِعٍ، وانتَهتِ الدولةُ الكَثيريةُ الأولى، وظهرَ حُكمُ الطوائفِ اليافعيةِ بساحِلِ حَضرمَوتَ على أنقاضِ الكَثيريِّينَ، وبَعدَ أن قامتِ الدولةُ الكَثيريةُ الثانيةُ في القرنِ التاسعِ الهِجريِّ كانَ تركيزُ سَلاطينِها على استِعادةِ تِرْيَمَ وسَيْئُونَ مِن يَدِ اليافعيِّينَ، واستَولى أيضًا الكَثيريونَ على الشِّحرِ مِنَ اليافعيِّينَ، لكنِ استَطاعَ التحالُفُ القُعَيْطيُّ بقيادةِ عَوَضِ بنِ عُمَرَ مع الكَسَاديِّ إخراجَ الكَثيريِّينَ منها، وأصبَحتِ الشِّحرُ منذُ ذلك الحينِ جُزءًا مِنَ السَّلطنةِ القُعَيْطيَّةِ، ووُقِّعتِ اتفاقيةٌ اعتَرفوا فيها لِآلِ كَثيرٍ بتِرْيَمَ وسَيْئُونَ.ثم وَقَعت خِلافاتٌ بينَ القُعَيْطيِّينَ والكَسَاديِّينَ، ورأت بريطانيا أنْ تَمنحَ حمايَتَها للقُعَيْطيِّ بَدَلًا مِنَ الكَسَاديِّ، وحَذَّرتِ الكَثيريِّينَ مِن مُساعدةِ الكَسَاديِّ، وسمَحَت للقُعَيْطيِّ بشَنِّ هُجومٍ على المُكَلَّا، وانتهى أمرُ الكَسَاديِّ، واعترفَت انجِلتِرا بسَلطنةِ القُعَيْطيِّ على الشِّحرِ والمُكَلَّا، ووَقَّعوا اتفاقيةَ حِمايةٍ، وكذلك فَعَلوا مع السَّلطنةِ الكَثيريةِ في حَضرَموتَ، حَكَمتِ الدولةُ الكَثيريةُ سَيْئُونَ وتِرْيَمَ، وتريس والغرف ومريمة والغَيْل، في الوقتِ الذي حَكمت فيه الدولةُ القُعَيْطيَّةُ المُكَلَّا والشِّحرَ وغَيْل أبا وزير وجميعَ بُلدانِ الشواطئِ، وتمت مُحاولاتٌ لِتَهدئةِ الوَضعِ المُحتَدِمِ بينَ الدولةِ الكَثيريةِ، والدولةِ القُعَيْطيَّةِ، لِيَتسَنَّى تنظيمُ شُؤونِ بِلادِ حَضرَموتَ، فكانت مُعاهدةُ عَدَنٍ عامَ 1336هـ، ثم كانَ في عامِ 1346هـ مؤتمرُ سِنغافورةَ، الذي أذاعت فيه الدولتان القُعَيْطيَّةُ والكَثيريةُ بَلاغًا رَسميًّا إلى أهالي حَضرَموتَ كافةً بتَجديدِ الاتِّحادِ وتَوثيقِ عُرى الصَّداقةِ والتَّعاونِ."},{"id":4564,"title":"غزو الروس لتركستان .","date":["العام الهجري :1263","العام الميلادي :1846"],"text":"بعد أن سيطر الروسُ تمامًا على سيبيريا (تشمل منطقة آسيا الشمالية) عام 1078هـ أصبحت تركستان تحدُّهم من جهة الجنوب حيث تمتدُّ سهول القازاق الواسعة والتي تعد قليلةَ السكان؛ الأمر الذي أغراهم بها، ولكِنْ كان قبل ذلك انصبَّ همهم على القفقاس فما أن انتهوا من أمر القفقاس وأصبحت تحت قبضتِهم حتى توجهوا إلى تركستان فسيطروا على سواحل بحر الخزر الشمالية والشرقية عام 1249هـ، ثم تابعوا تقَدُّمَهم نحو نهر سيحون، واحتلُّوا طاشقند وسمرقند، ووصلوا حتى نهر جيحون، أي: فصلوا بين الأراضي التابعة لخانية خوقند والأراضي التابعة لخانية بخارى، وتوقَّفوا عند نهر جيحون، ولا يزال الحد الفاصل بين الإمبراطورية الروسية وبلاد الأفغان، وذلك في المدة 1270هـ إلى 1286هـ، ثم توسَّعوا نحو الجنوب على سواحل بحر الخزر الشرقية ليحيطوا بخانية خوارزم من جهة الغرب، ولم يبقَ أمام الاستعمار الروسي إلَّا هذه الخانيات الثلاث خوقند وبخارى وخوارزم إضافةً إلى بلاد الطاجيك وبلاد التركمان، وبدؤوا بخانية خوقند التي أصبحت منعزلةً عن الخانيتين الأخريين، ففَرَضوا سيطرتهم عليها عام 1293هـ ثم اتَّجَه الروس إلى خانية بخارى، ففرضوا سيطرتَهم عليها عام 1303هـ وتابعوا سيرَهم إلى بلاد التركمان فدخلوها في العام نفسِه بعد مقاومة عنيفةٍ مُدافِعين عن عاصمتهم مرو دفاعًا مجيدًا، وهكذا أصبحوا على حدودِ إيران، وعزلوا خوارزمَ التي بقيت وسطَ البلاد الخاضعة أو المحمية للروسِ، فدخلوها عام 1306هـ وتوجهوا بعدها إلى بلادِ الطاجيك فأخضعوها عام 1311هـ."},{"id":4565,"title":"تمرد قبائل شمال عُمان ضد القائد السعودي سعد المطيري .","date":["العام الهجري :1263","العام الميلادي :1846"],"text":"تمرَّدَت قبائل شمال عمان ضِدَّ القائد السعودي سعد بن مطلق المطيري، وشكَوا إلى الإمام فيصل أنه يتشَدَّد في معاملته معهم، واستدعى الإمام فيصل قائدَه سعد بن مطلق المطيري إلى الرياض للتفاهُمِ معه بشأن الموقف المتدهوِرِ في البريمي. وفي غياب سعد بن مطلق حلَّ محلَّه محمد بن يوسف العجاجي بالوكالةِ، واستطاع توثيقَ عُرى الصداقة بين القبائل هناك، وظَلَّ يحكُمُ عدة شهور حتى وصل حاكِمٌ جديدٌ للبريمي من قِبَل الإمام فيصل هو عبد الرحمن بن إبراهيم."},{"id":4566,"title":"شريف مكة يقصد نجدًا بتحريض من رؤساء القصيم .","date":["العام الهجري :1263","الشهر القمري : ربيع الآخر","العام الميلادي :1847"],"text":"قصد في هذه السنة شريفُ مكَّةَ محمد بن عون بتحريضٍ من رؤساء أهل القصيم الذين زيَّنوا له أنَّه إن سار إلى نجدٍ فلا يقاومُه أحدٌ ولا يثبُتُ فيصلُ بن تركي في مكانِه، فجهَّز نفسَه وعساكره واستلحق عساكِرَ الترك من المدينة والحناكية، وظهر معه خالدُ بن سعود واجتمع عليه عساكِرُ كثيرةٌ، وقَدِمَ القصيم في ربيع الآخر وأطاعه أهلُ القصيم كلُّهم، ووفد عليه كثيرٌ من رؤساء العُربان وأمراء البلدان، فلما علم فيصل بهذا الخبر استنفر رعيَّتَه وأمر ابنَه عبد الله أن يركَبَ من الرياض، وجهَّزَ معه الخيل والرجال ونزل ناحية سدير، وتكاملت عليه باقي غزوانه فيها، فلما علم الشريف بذلك داخلَه الفَشَلُ، وأرسل إلى فيصل يطلب الصلحَ وأن يرسِلَ له أحد إخوانِه مع هدية تكسِرُ عنه الفشَلَ، فقبل فيصل فأرسل له أخاه محمدًا ومعه ثماني عمانيات وخيل، لكِنَّ أهل القصيم أشاروا عليه برَدِّ الهدية ليعلمَ أهلُ نجد بقوَّتِه فيكاتبوه، فلما علم فيصل بذلك غَضِبَ وأمر بالنفير لملاقاةِ الشريف، فلما بلَغَ الشريف خروجُ الإمام فيصل وابنه عبد الله داخله الفشل وحَلَّ به الرعب وقنع باليسيرِ وشتَمَ مَن أشار عليه من أهل القصيم بالخروجِ، وأرسل إلى فيصل للمصالحة الأبدية والمسالمة المَرْضية فقَبِلَ منه فيصل وأرسل له هدايا من النجائِبِ العمانيات وأطايب الخيل، وعاد من عنيزة إلى مكة في منتصف رجب من هذه السنة راضيًا على فيصل ساخطًا على أهل القصيم ورؤسائِهم."},{"id":4567,"title":"وفاة عبد الله بن رشيد أمير جبل شمر وخلفه ابنه طلال .","date":["العام الهجري :1263","الشهر القمري : جمادى الأولى","العام الميلادي :1847"],"text":"هو الأمير عبد الله بن علي بن رشيد، من الجعافرة (آل جعفر) من الربيعية، من عبدة، من شمر: أول حكام آل رشيدٍ في جبل شمر، ومؤسِّسُ حُكمِهم فيها. ولِدَ بحائل سنة 1202ه. كان جدُّه رشيد من سكان حائل ومات في أواخر القرن الثاني عشر للهجرة, وعُرِفَ أبناءُ رشيد وأحفاده بآل رشيد. وكانت لهم في شماليَّ جزيرة العرب إمارةٌ واسعة ظهر فيها أمراءُ وفرسان عُرِفوا في تاريخ نجد الحديث. خلَّف رشيد عليًّا. وعلي خلَّفَ عبد الله وعبيدًا، حاول عبد الله بن علي بن رشيد -وهو من أغنياء أسرة جعفر العريقة وأعيانها- سنة 1235ه أن يستوليَ على العرش في حائل وينتزِعَه من آل علي بمعاونة أقاربِه الكثيرين ذَوِي النفوذ، فنَشبت الحرب بينهم وبين آل علي ودارت الدائرةُ على عبد الله فنُفِيَ، ولكِنَّ عبد الله عاد بعد عشر سنوات إلى جبل شمر فعَيَّنَه فيصل بن تركي أميرًا على جبل شمر؛ اعترافًا بفضله في استرداد حكم الرياض، ومساعدته له في قتل مشاري بن عبد الرحمن الذي تآمرَ على قتل والدِه تركي بن عبد الله، وقتل عبدَ مشاري حمزة بن إبراهيم الذي باشر قتل تركي بن عبد الله، وبعد أن تمكَّنَ عبد الله بن رشيد في حائل طردَ بيت آل علي من جبل شمر, ثم بنى عبد الله القصر الكبير، وقد توثَّقَت العلاقةُ بين فيصل بن تركي وبين ابن رشيد بالمصاهرة بين الأسرتين، فقد تزوَّج عبد الله بن فيصل بن تركي من نورة آل عبد اللهِ الرشيد، ثم من ابنة عمها طريفة بنت عبيد ابن رشيد، ولما توفي عنها، تزوَّجها شقيقه محمد بن فيصل بن تركي, وكذلك تزوَّج عبد الله ابن رشيد بالجوهرة أخت فيصل بن تركي، وتزوَّج ابنه طلال من الجوهرة بنت فيصل. توفي عبد الله بن رشيد في حائل بعد عودته من غزوة غزا فيها عنزة، وخلَفَه في حكم الجبل ابنُه طلال, وكان ابن رشيد خلَّفَ من الأبناء متعبًا الأول-وتوفي صغيرًا- ومحمدًا، وطلالًا، ومتعبًا."},{"id":4568,"title":"عزل الإمام فيصل بن تركي لأمير عنيزة .","date":["العام الهجري :1264","العام الميلادي :1847"],"text":"بادر الإمامُ فيصل بن تركي إلى عَزْلِ أمير عنيزة في هذه السنة؛ وذلك لاعتقاده بأنه أغرى شريفَ مكة محمد بن عون بغزوِ نجد، وفتح له أبوابَ بلدتِه. وأمَّر الإمامُ فيصل على عنيزة ناصرَ بن عبد الرحمن السحيمي. فناصَبَ آلُ سليم أسرةُ الأمير المعزول أسرةَ السحيمي الأميرِ الجديد العداءَ، وحاولوا بزعامةِ عبد الله بن يحيى بن سليم اغتيالَ السحيمي، والاستيلاءَ على قصرِ الإمارة، ولكِنَّ محاولتهم باءت بالفشلِ، فهربوا من عُنيزة واحتموا بأميرِ بُرَيدة، وألزمهم الإمام فيصل بن تركي بالقدومِ إليه في الرياض؛ ليرى فيهم، وقَتَل السحيمي أميرَ عنيزة السابق. وأمر الإمام فيصل بن تركي السحيمي بالحضورِ إليه ليحاكَمَ مع عبد الله بن يحيى بن سليم ومن معه عند قاضي الرياضِ."},{"id":4569,"title":"عودة الشيخ عبد اللطيف بن عبد الرحمن بن حسن من مصر .","date":["العام الهجري :1264","العام الميلادي :1847"],"text":"قَدِمَ الشيخ عبد اللطيف بن عبد الرحمن بن حسن من مصر إلى نجد واستعمله الإمامُ فيصل قاضيًا في الأحساء، ثم عاد إلى الرياض ليكونَ قاضيًا فيها مع أبيه. وكان قد جلب معه كتُبًا كثيرة انتفع بها وبعِلْمِه كثيرٌ من أهل العلمِ، والقُضاة."},{"id":4570,"title":"وفاة الأمير خالد بن سعود قائد الحملة المصرية .","date":["العام الهجري :1264","العام الميلادي :1847"],"text":"الأميرُ خالد بن سعود بن عبد العزيز بن محمد بن سعود أميرٌ مِن آل سعود، وهو مِن أمٍّ حبشية. نشأ بمصرَ بعد حرب إبراهيم باشا للدرعية,  ولما قَوِيَ أمر الإمام فيصل بن تركي في الديار النجدية أرسل محمد علي باشا خالدًا مع قوة عسكرية يقودُها إسماعيل بك سنة 1252 هـ لقتال فيصل بن تركي، فنشبت بينهما معاركُ انتهت باستسلام فيصل لخورشيد باشا في رمضان 1255 1838 م ووجَّهه خورشيد إلى مصر، ومعه ولداه عبد الله ومحمد وأخوه جلوي بن تركي. وتولى خالدٌ الإمارة، فسيَّرَ حملة بقيادة سعد بن مطلق إلى الأراضي المجاورة لنجد، وخضعت له عددٌ من بلدان نجد عدا الخرج وبلدة الحلوة، رفض أهلها الخضوع له؛ لعِلمِهم أن حُكمَه صوريٌّ والحكم الحقيقي لمحمد علي باشا. كتب خالدُ بن سعود إلى إمام مسقط سعيد بن سلطان يطالِبُه بالجزية التي كان يؤدِّيها من قبل لأجداده آل سعود. ومال خالدُ بن سعود إلى اللَّهوِ، فنفر منه أصحابُه، وثار عليه عبد الله بن ثنيان بن إبراهيم بن ثنيان ابن سعود، فرحل خالد إلى الأحساء، فلما دخل ابن ثنيان الرياضَ واجتمع عليه أهلُ نجد مضى خالد بن سعود إلى الدمَّام ثم الكويت، ومنها إلى مكة. وتوفي بجُدة محمومًا."},{"id":4571,"title":"أسر عبد القادر الجزائري بعد أن هزم الآليات الفرنسية .","date":["العام الهجري :1264","الشهر القمري : محرم","العام الميلادي :1847"],"text":"بدأ الأميرُ عبد القادر الجزائري سياسةً جديدةً في حركته، واستطاع أن يحقِّقَ بعض الانتصارات، وبعد أن كبَّد عبد القادر الجزائري الآلياتِ الفرنسيةَ هزائِمَ متلاحِقةً، دعمت فرنسا قواتِها بسرعة، فلجأ الجزائريُّ مرة ثانية إلى بلاد المغرب، وعلى الرغمِ من انتصار الأمير عبد القادر على جيش الاستطلاع الفرنسي فإن المشكلة الرئيسية أمامَ الأمير كانت هي الحصول على سلاح لجيشِه، ومن ثمَّ أرسل لكُلٍّ من بريطانيا وأمريكا يطلب المساندةَ والمَدَد بالسلاحِ في مقابل إعطائِهم مِساحةً مِن سواحل الجزائر كقواعِدَ عسكرية أو لاستثمارها، وبمثل ذلك تقَدَّم للعرشِ الأسباني ولكِنَّه لم يتلقَّ أي إجابة، وأمام هذا الوضعِ اضطرَّ في النهاية إلى التفاوض مع القائد الفرنسي الجنرال لامور يسيار على الاستسلامِ على أن يسمَحَ له بالهجرة إلى الإسكندرية أو عكَّا ومن أراد من أتباعِه، وتلقى وعدًا زائفًا بذلك فاستسلم في 23 ديسمبر 1847م، أوَّلَ محرم 1264هـ، ورحل على ظهر إحدى البوارج الفرنسية، وإذا بالأمير يجِدُ نفسِه بعد ثلاثة أيام في ميناء طولون، ثم سيق إلى قلعة (أمبوزا) بمدينة طولون الفرنسية، وظل حبيسًا مدة خمس سنوات، وهكذا انتهت دولةُ الأمير عبد القادر، وقد خاض الأميرُ خلال هذه الفترة من حياته حوالي 40 معركةً مع الفرنسيين والقبائل المتمَرِّدة."},{"id":4572,"title":"قحط في نجد ثم غيث  .","date":["العام الهجري :1264","الشهر القمري : صفر","العام الميلادي :1848"],"text":"وفي هذه السنة منع اللهُ الغيثَ بحكمته، فلم يقَعْ في الأرض حَيَا في بلدان نجدٍ ولا غيمٌ ولا مطرٌ كثيرٌ ولا قليلٌ، من أولها إلى آخر الشتاء، وقتَ حلول الشمس برج الحوت، فقَنِط الناس قنوطًا عظيمًا؛ لأن الناس يقولون: ما نعلم أن السماء عَدِمَ فيها الغيم مثل هذه السنة، فلما كان رابعَ عشر صفر أنشأ الله الغيمَ في السماء فصَبَّ الغيث فامتلأ كلُّ وادي بما فيه، وضاقت مجاريه وخرَّب السيل في البلدان كثيرًا، فلم يأتِ آخر الليل إلا وكلُّ إنسان يستغيث ربَّه أن يرفعه عنهم، ثم عادهم السيلُ في رابع عشر ربيع الآخر ليلة الثلاثاء ويومَها على أول حلول الشمسِ برج الحمل، فجاء سيلٌ ضاقت منه الوديان وخرب البلدانَ في كُلِّ بلد من بلدان نجد، ثم عادها الحيَا على أول دخول جمادى الآخرة، واستمَرَّ على جميع البلدان المطرُ نحو أربعة عشر يومًا لم تطلُعِ الشمس، وكل يوم معه سيلٌ يجري، وحار الماءُ في وسط منازل البلدان حتى إنَّه ظهر في مسجد الجامع في بلد المجمعة، وسقط أكثَرُ من ثلثه، وظهر الماء في المجالس وبطون النخل، وأعشبت الأرض عشبًا لم يُعرَف له نظير!"},{"id":4573,"title":"دخول الجيش التركي رومانيا .","date":["العام الهجري :1264","الشهر القمري : رمضان","العام الميلادي :1848"],"text":"استطاع الجيش التركي أن يدخُلَ رومانيا، وقد ردَّت روسيا على هذه الخطوة من تركيا باحتلالِ مولدافيا، وذلك في إطار التنافُسِ بين الدولتين في منطقة البلقان في أوروبا."},{"id":4574,"title":"وفاة الشاه محمد القاجاري شاه إيران وتولي ناصر الدين شاه الزعامة .","date":["العام الهجري :1264","الشهر القمري : شوال","العام الميلادي :1848"],"text":"هو الشاه محمد بن عباس القاجاري الشيعي، شاه إيران في الفترة من 23 أكتوبر 1834 إلى وفاته سنة 1848، ينتمي إلى سلالة القاجاريين التي حكمت بلاد فارس بين عامي 1779 و1925. وهو ابنُ عباس ميرزا، ابن فتح علي شاه وولي عهده. خلَفَ محمد شاه جَدَّه في الحكم. ثم ثار عليه عمُّه علي ميرزا. توفِّيَ محمد شاه يوم الثلاثاء 6 شوال من هذا العام  ودام ملكُه أربع عشرة سنة وثلاثة أشهر، وكان ابنه ناصر الدين ميرزا ولي العهد الذي تولى بعد وفاة والده ملك إيران."},{"id":4575,"title":"دخول مسقط في نزاع مع الرياض .","date":["العام الهجري :1265","العام الميلادي :1848"],"text":"دخلت مسقط مع الرياض في نزاعٍ عندما رأت ضعفَ القوَّة السعودية إثرَ اعتداءِ حاكم أبو ظبي سعيد بن طحنون عليها، فرفض الثويني ابنُ حاكم مسقط أن يدفَعَ ما تعهد به من الزكاة عام 1261هـ وتحالف معه ابنُ طحنون في السنة نفسِها واتَّفَقا على مساعدة بعضهما البعض ضِدَّ السعوديين."},{"id":4576,"title":"وقعة اليتيمة بقيادة عبد الله بن فيصل .","date":["العام الهجري :1265","العام الميلادي :1848"],"text":"لَمَّا قفل عبد الله بن فيصل راجعًا بعد غارته على عنزة، نزل النفوذَ المسماةَ اليتيمةَ، ووجد آثارَ جيش عبد العزيز المحمد أبو عليان معه أهل عنيزة واستنفر معه أيضًا من وافقه من أهل بُريدة على قتال عبد الله ومن معه، فأشار على عبد الله بن فيصل من معه أن يسيرَ في طريقه ويتركَهم ما دام أنَّهم لم يعترضوه، فقال: لا والله لا أرجِعُ عنهم حتى يطأَهم جيشي، فقصدَهم في موضعهم فثار القتالُ وصمدوا للقتال وحَمِيَ وطيسُه، ثم انهزم عبد العزيز المحمد ومن معه، وتركوا بالميدان نحوَ مائةٍ وخمسين قتيلًا، وقصد عبد العزيز عُنيزةَ وتلاحق عليه فلولُ جيشِه. وكان يظنُّ أن أهل عنيزة يساعدونَه على إعادة الكَرَّة، ولكنَّ الشيخ عبد الله أبا بطين ثبَّط عزمهم، وأشار عليهم بعدم الدخولِ في أمر عبد العزيز، ثمَّ ذهب إلى عبد العزيز المحمد أبو عليان وحَذَّره من الفتنة، فرحل عبد العزيز من عنيزةَ، وقصد بُريدة وهرب السحيمي قاصدًا ابن رشيد، فوافاه في القوارة مقبلًا لنصرة الإمام فيصل. فلما فارق عبد العزيز عُنَيزةَ وهرب السحيمي، انتدب أهُل القصيم الشيخ عبد الله أبا بطين فركِبَ إلى الإمام فيصل وقال له: إن أهل البلاد يطلبون العفوَ عما مضى، وفوَّضوني أن أقَدِّمَ لكم خضوعَهم، وإنهم بالسمع والطاعة. وكان عبد الله اليحيى، وزامل العبد الله مع الإمام فيصل، فاستشرفا للإمارة، ولكِنَّ الإمام فيصل أرسل محمد بن أحمد السديري في عِدَّةِ رجال وأمره أن ينزل القصرَ، فدخل البلدَ ونزل القصر، ورحل الإمامُ فيصل ونزل خارج البلد، ثم دخلها بنفسه وحاشيته، فبايعوه على السَّمعِ والطاعة."},{"id":4577,"title":"اتفاق بلطة ليمان بين العثمانيين والروس .","date":["العام الهجري :1265","العام الميلادي :1848"],"text":"ثار أهلُ الأفلاق والبغدان رغبةً في تكوين دولةٍ واحدةٍ تشمَلُ الإقليمين مع ترانسلفانيا، ففَرَّ أمير الإقليمين وتشكَّلَت حكومةٌ مؤقَّتةٌ، فأرسلت الدولةُ العثمانية جيشًا بقيادة عمر باشا لإعادةِ الوَضعِ إلى ما كان عليه، وسارعت روسيا واحتَلَّت البغدان والأفلاق، وطردت الحكومةَ المؤقَّتةَ فاحتجت الدولةُ العثمانيةُ على هذا الفِعلِ، وكادت تقَعُ الحربُ بين الطرفين، ثم جرى اتفاق بلطة ليمان قرب استانبول عام 1265هـ ينصُّ على أن يبقى تعيينُ أمراء الإقليمين من حَقِّ الدولة العثمانيةِ، وأن يبقى فيهما جيشٌ عثمانيٌّ روسيٌّ لمدة أربع سنواتٍ حتى يستقِرَّ الوَضعِ."},{"id":4578,"title":"أهل القصيم يخرجون عن طاعة الإمام فيصل بن تركي .","date":["العام الهجري :1265","الشهر القمري : ربيع الآخر","العام الميلادي :1849"],"text":"لَمَّا رحل الشريف محمد بن عون العامَ الماضي من القصيم عائدًا إلى مكة بعد الفشل في تحقيق مرادِه، أوفد أهل القصيم إلى الإمام فيصل منهم رجالًا يعتذرون عمَّا بدر منهم، فقَبِلَ عُذرَهم وغفر لهم خطأَهم، ثم إن الإمام فيصل عزل عن إمارة عُنيزة إبراهيمَ بن سليمان بن زامل؛ لأن الشريف لم ينزِلْ عُنَيزةَ إلا بإذنه، وجعل مكانَه ناصِرَ بن عبد الرحمن السحيمي من أهل العقيلية، الذي قدِمَ إلى عنيزة بكتابٍ فيه توليته الإمارة من الإمام فيصل، فأخرج آل زامل من القصر وأنزله أخاه وضبَطَه برجالٍ واستقام له الأمرُ وبايعه أهلها، ثم تعرَّض لمحاولة اغتيالٍ فاشلة، فقَتَل السحيميُّ إبراهيمَ بن سليمان أميرَ عنيزة السابق فاشتعلت الفتنة، فأراد فيصل إخمادها فأرسل إلى السحيمي ليقدمَ عليه في الرياض، فلما قَدِم حكم عليه القضاءُ بديةِ إبراهيم بن سليمان وأقعده فيصلٌ عنده في الرياضِ، ثم جهَّزَ الإمام عبد الله المداوي ورجالًا معه إلى عُنيزة وأمرهم أن يدخلوا القصرَ فلم يتمكَّنْ من دخولِه، ثم إن أهل عنيزة أجمعوا على الحربِ، فلما علم بذلك السحيمي عرض على الإمام أنَّه هو الذي يُخمِدُ الفتنة وأعطى العهودَ والمواثيق بذلك، فأذِنَ له الإمام بالذهاب إلى عُنيزة، فلما وصلها نقضَ عهودَه ودخل مع أهل عنيزةَ في أمرِهم، ثم عرضوا على أميرِ بريدة عبد العزيز المحمد أبو العليان أن يدخُلَ معهم وهو أميرُ الجميع فوافَقَهم فتعاقدوا على نكثِ عهد الإمام، وقاموا لحربه وجمعوا جموعًا كثيرة من رجالِ بلدانهم ومن كان حولَهم من بُدوانهم، فأعطوهم السلاحَ وبذلوا لهم الأموالَ وعاقدوهم على بيع الأرواح، وضربوا طبولهم بالليلِ والنهار، وكان الإمام فيصل قد أمَرَ على أهل البلدان من رعيتِه بالغزوِ، فتجهَّز غازيًا وخرج من الرياض لثلاثٍ بَقِين من ربيع الثاني، وخرج معه أولاده عبد الله ومحمد، ولحق به ابنه سعود بأهل الخَرج، وخرج معه الشيخ عبد اللطيف بن عبد الرحمن بن حسن آل الشيخ إمامًا وقاضيًا، ولَمَّا نزل قرب المجمعة لقِيَه ابن بشر (صاحب كتاب عنوان المجد في تاريخ نجد) الذي يقول: \"ثم رحل ونزل قريبًا من المجمعة، فركبتُ إليه للسلام عليه، فكان وصولي إلى مخيَّمِه قبل صلاة العصر، فصليت معهم وإذا المسلمون مجتمعون للدرس في الصيوان الكبير، وإذا الإمام جالس فيه والمسلمون يمينه وشماله، ومِن خَلفِه وبين يديه، والشيخ عبد اللطيف إلى جنبه، فأمر القارئ عليه بالقراءةِ، فقرأ عليه في كتاب التوحيد، فقرأ آية وحديثًا، فتكلم بكلامٍ جَزْلٍ وقولٍ صائبٍ عَدْلٍ، بأوضح إشارة وأحسن عبارة، فتعجَّبْت من فصاحته وتحقيقه وتبيينه وتدقيقِه... ثم سلمتُ على الإمام فقابلني بالتوقير والإكرام ورحَّبَ بي أبلغَ ترحيب وقرَّبني أحسن تقريب.. وسلمت على الشيخين عبد اللطيف بن عبد الرحمن بن حسن، وعبد الله بن جبر، فقمنا ودخلنا مع الإمام خيمته وجلسنا عنده، فابتدأ الشيخ عبد الله يقرأ على الإمام في كتاب سراج الملوك، والشيخ عبد اللطيف يسمع، ولكِنَّ الإمامَ هو الذي يتكلم على القراءة ويحقِّق المعنى\". ثم في الصباح رحل الإمام إلى المجمعة ومنها إلى أُشيقر إلى أن نزل المذنب فبايعه أهلها، ثم أرسل إلى أهل القصيم يذكِّرُهم أن الدِّينَ لا يستقيم إلَّا بجماعة ولا يكون إلا بالسمع والطاعة، وأنَّه يعِزُّ عليه أن يُقتَلَ رجلٌ واحد من المسلمين، فلا تكونوا سببًا في إهراق دمائكم، فأرسلوا إليه رجلًا من رؤساء بريدة يقال له مهنا بن صالح، فلما وصل تم الصلحُ على أن يؤدِّيَ أهل القصيم الزكاةَ للإمام، ويركبون معه غزاةً ويدخلون في الجماعة والسمع والطاعة."},{"id":4579,"title":"وفاة محمد علي باشا بمصر  .","date":["العام الهجري :1265","الشهر القمري : رجب","العام الميلادي :1849"],"text":"هو محمد علي باشا المسعود بن إبراهيم آغا القوللي الملقَّب بعزيز مصر، مؤسِّسُ الأسرة العَلَوية وحاكم مصر، من مواليد قوالة على الساحل المقدوني 1769م، كان عمه يشغل منصب (متسلم - أو نائب والي) وفي ديوان عمِّه هذا تمرَّس محمد علي بالأعمال والمعاملات من غيرِ أن يحظى بتربيةٍ مدرسية صحيحة. حتى إذا بلغ العشرين كان قد نجح في تجارةِ التبغ وعقد الصفقاتِ فيها، والتبغ مادةُ التجارة الرئيسية في بلده الأم. وظهرت عليه أمارات النزوع إلى السلطة وقوة الشخصية منذ نعومةِ أظفاره. وعندما غزا نابليون مصر أرسل السلطان سليم الثالث بِضعَ سُفُن حاملة جنودًا إلى مصر في صيف سنة 1799. كان على عمِّ محمد علي أن يبعثَ إلى مصر أيضا بكتيبةٍ مؤلفة من ثلاثمائة رجل، فعهد إلى ابنِه الصغير بقيادتِها، وعيَّن محمد علي مستشارًا لابنه. ولم تكد الكتيبةُ تَصِلُ إلى مصر حتى تولَّى محمد علي القيادةَ الفعليةَ، وأظهر في المعارك التي قادها ضِدَّ الفرنسيين من الكفاءةِ القيادية ما أهَّلَه للوثوب بقفزةٍ واحدة إلى منصِبِ القيادة العامة في سنة 1801م، وفي سنة 1805 أصبح حاكِمَ مصر بدون منازِعٍ، مستعينًا على بلوغ مأربه بشيوخِ الأزهر. ووافق السلطانُ على تعيينه واليًا على مصر. ومنحه لقبَ باشا. وأظهر من الغَيرة على الدين والرَّغبة في الجهاد والعمل لبناء مصر، ما جعله يستحوِذُ على محبة أهل مصر الذين التَفُّوا حوله وساندوه. خاض محمد علي في بداية فترة حكمه حربًا داخليَّةً ضِدَّ المماليك والإنجليز إلى أن خضعت له مصرُ بالكليَّة، ثم خاض حروبًا بالوكالةِ عن الدولة العثمانية في جزيرة العرب ضِدَّ الوهَّابيين وضِدَّ الثوار اليونانيين الثائرين على الحكم العثماني في المورة، كما وسَّع دولته جنوبًا بضمه للسودان. خلال فترة حكمِه لمصر استطاع أن ينهض بمصر عسكريًّا وتعليميًّا وصناعيًّا وزراعيًّا وتجاريًّا؛ مما جعل من مصرَ دولةً ذات ثقل في تلك الفترة، حتى أصبح ينافس الدولةَ العثمانية نفسَها؛ فقد خاض حروبًا ضِدَّها حتى دخل الأناضول وكاد يُسقِطُ الدولة العثمانية، ولكن أُخمِدَت حركتُه لتعارضها مع مصالحِ الدُّوَل الغربية التي أوقفت محمد علي وأرغمَتْه على التنازل عن معظم الأراضي التي ضَمَّها. وبسبب المشاكل في آخرِ عهد محمد علي الناجمة عن كثرة حروبِه مع خصومِه وغَرَقِ مِصرَ بالديون تخلَّى عن الحكم لابنه إبراهيم باشا في شعبان من سنة 1264هـ ثمَّ لم يعمَّرْ بعدها كثيرًا حتى توفِّيَ في رجب من هذا العامِ."},{"id":4580,"title":"وفاة علي محمد الشيرازي الملقب بالباب مؤسس فرقة البابية المنحرفة .","date":["العام الهجري :1266","الشهر القمري : شعبان","العام الميلادي :1850"],"text":"هو علي محمد ابن المرزا رضى البزَّاز الشيرازي الملقَّب بالباب مؤسِّس فرقة \"البابية\" وهي إحدى الفِرَق التي حرَّفت العقيدة الإسلامية، وهي أصلُ فرقة البهائية, وهو إيرانيُّ الأصل، ولِدَ بشيراز سنة 1235هـ، ومات أبوه وهو رضيعٌ، فرَبَّاه خاله المرزا سيد علي التاجر، ونشأ في أبي شهر فتعَلَّم مبادئَ القراءة بالعربية والفارسية، وتلقى شيئًا من علوم الدين، وتقشَّف، فكان يمكث في الشَّمسِ ساعات عديدة. وأثَّر ذلك في عَقلِه، ولَمَّا بلغ الخامسةَ والعشرين سنة 1260هـ جاهَرَ بعقيدة ظاهِرُها توحيد الأديان، وقِوامُها تلفيقُ دينٍ جديد. والبابيَّةُ فرقةٌ ضالةٌ كافرةٌ مَوطِنُها الأول إيران، وسمِّيت \"بالبابية\" نسبة لزعيمِها الأول، والذي لقَّب نفسَه بالباب. وإن كانت البابيةُ في أصلها بيضةً رافضيةً إلَّا أنها اتُّهِمَت بقضية تدرج مؤسسيها في الكذب، وأنها دُعِمَت مِن قِبَل الغرب الكافر. فقد ادعى مؤسِّسُها \" علي محمد الشيرازي \" عام 1260هـ لنفسه أنَّه الباب والوسيلة للوصولِ إلى الإمام المنتظر، ثم تحوَّل عن ذلك وزعَمَ أنَّه هو بعينه الإمام المنتظر عند الباطنية، ثم تجاوز ذلك وزعم أنَّه نبي مرسَلٌ وأنَّ له كتابًا أفضل من القرآن اسمه \"البيان\"، وبعد ذلك تطور به الأمرُ وزعم أن الإله حلَّ فيه -تعالى الله عما يقول علوًّا كبيرًا- وقد أوعزت اليهوديَّةُ العالمية إلى يهود إيران أن ينضمُّوا تحت لواء هذه الحركة بصورةٍ جماعية، ففي طهران دخل فيها (150) يهوديًّا، وفي همدان 100 يهودي، وفي كاشان 50 يهوديًّا، وفي منطقة كلبا كليا 85 يهوديًّا، كما دخل حبرانِ من أحبار اليهود إلى البابيَّة في همدان، وهما: الحبر الباهو، والحبر لازار. ودخول هذا العدد الكبيرِ مِن اليهود في مدَّةٍ قصيرة في هذه النِّحْلة يكشِفُ الحجم الكبير للتآمُرِ، والأهدافَ الخطيرة التي يسعى اليهودُ لتحقيقها من وراء دَعمِ هذه الحركات التي تُسعَّرُ ضِدَّ الإسلام والمسلمين. ولَمَّا خشيت حكومة إيران الفتنةَ بسبب دعوته سجَنَت بعض أصحابه. وانتقل هو إلى شيراز، ثم إلى أصبهان، فتلقى حاكمُها أمرًا بالقبض على الباب، فاعتُقل وسُجِنَ في قلعة \"ماكو\" بأذربيجان، ثم انتقل إلى قلعة \"جهريق\" على أثر فتنة بسببه، ومنها إلى تبريز، وحُكِم عليه فيها بالقتل وذلك بفتوى من العلماء بارتدادِه، فأُعدِمَ رميًا بالرصاص. وألقِيَ جسَدُه في خندق تبريز، فأخذه بعضُ مريديه إلى طهران. وفي حيفا (بفلسطين) قبر ضخمٌ للبهائية يقولون إنهم نقَلوا إليه جثَّةَ الباب خِلسةً, وله عدة مصنفات، منها كتاب \"البيان\" طُبِع بالعربية والفارسية."},{"id":4581,"title":"أهل قطر يبايعون الإمام فيصل بن تركي على السمع والطاعة .","date":["العام الهجري :1267","العام الميلادي :1850"],"text":"جهَّز الإمامُ فيصل بن تركي لغزوِ قطر، فلما عَلِمَ أهلُ قطر بذلك طلبوا الأمانَ من فيصل وبايعوه على دينِ الله والسمع والطاعة، فأمر الإمامُ فيصل على السُّفن التي لأهل قطر، وهي نحو 300 سفينة أن يُهَيِّئوها وجعل فيها رجالًا مِن جُندِه، ثمَّ أمرَ على أولاد عبد الله آل خليفة الجالين من البحرين أن يركبوها ويتولَّوا قيادتَها."},{"id":4582,"title":"وفاة الشيخ القاضي محمد بن مقرن بن سند .","date":["العام الهجري :1267","العام الميلادي :1850"],"text":"هو الشيخُ القاضي محمد بن مقرن بن سند بن علي بن عبد الله بن فطاي بن سابق بن حسن الودعاني الدوسري، وهو من أعلامِ الحنابلة في القرن الثالث عشر الهجري، قال عنه ابن بشر: \"كان -رحمه الله- فطِنًا متيقظًا له عقلٌ راجِحٌ ورأيٌ صائبٌ ووجهٌ سامحٌ صابحٌ، إذا قال رأيتَ قولَه مُسكتًا عن الجواب، وإذا أشار بالرأي يلوحُ من رأيه الصواب\" استعمله الإمام سعود بن عبد العزيز قاضيًا في بلدان المحمل، وأرسله قاضيًا في عُمان، فنفع الله به وأصلح الله عمان على يده، ثم أرسله إلى عبد الوهاب أبو نقطة في ناحية عسير، ولما كانت ولايةُ تركي بن عبد الله أثبته على عمله في القضاء لأهل المحمل، ولَمَّا وصل خورشيد باشا الرياضَ وطاعت له نجدٌ أرسل إليه فلما قَدِمَ عليه أكرمه وألزمه القضاءَ عنده، ثمَّ إنَّه تعلَّل بأعذار فأذِنَ له فرجع إلى وطنه. وفي ولاية عبد الله بن ثنيان لا يسلُكُ جهةً إلا هو معه، وفي عهد الإمام فيصل أرسله قاضيًا للأحساء في وقت الموسم، فأصابته حمى فلم يزل محمومًا سقيمَ البدن حتى توفِّيَ."},{"id":4583,"title":"أهل البحرين يطلبون العفو والصلح مع الإمام فيصل  .","date":["العام الهجري :1267","العام الميلادي :1850"],"text":"وكان أهلُ البحرين حين نزل الإمامُ فيصل بن تركي في ناحيتِهم أرسلوا إلى سعيدِ بن طحنون رئيسِ بلدان أبو ظبي في ناحية عُمان يستنجدون به أن يفزعَ لهم، وكان ذو قوةٍ مِن الأموال والرجال والسفن، ففزع لهم وأقبل في عددٍ مِن السفن المملوءة من الرجال، فلما أقبل على الجهةِ التي نزل فيها الإمامُ فيصل ناحيةَ قطر، داخل ابن طحنون الفشَلَ والوجَلَ، وأرسل إلى الإمامِ يطلب منه أن يتصالحَ مع أهل البحرين، فأجابه الإمامُ بقوله: إنه لا ينتظم بيننا وبين هؤلاء الأقوامِ كلامٌ ولا مصالحةٌ إلَّا بقدومك إلينا والجلوس بين أيدينا، فقال ابن طحنون: أعطِني الأمانَ على يد الأمير أحمد السديري، فأرسل إليه الأمان مع أحمد السديري، وأقبل معه ابن طحنون بهدايا كثيرة من السلاحِ وغيره، فلما جلس بين يدى الإمام أوقع اللهُ في قلبه هيبةَ الإمامِ وأقَرَّ بأنَّ مَن نابذه وخالفه لم يحصُلْ له سوى الخيبة، وتودَّد إليه في عقد المصالحة بينه وبين أهل البحرين، فأجابه على أنَّهم يؤدون الخَراجَ السابق واللاحِقَ، وعلى ما ضُرِبَ عليهم بسبب ما صدر منهم من المخالفةِ في الأقوال والأفعال، فصبر أهلُ البحرين ورضُوا بما قال، ودفعوا تلك الأموالَ، وأُطفئت نارُ الحرب وزال عن الخائف الكَربُ."},{"id":4584,"title":"آل سديري في طاعة الإمام فيصل .","date":["العام الهجري :1267","العام الميلادي :1850"],"text":"كان أحمدُ السديري وبنوه من أحسَنِ الناس سيرةً وأصفاهم سريرةً وألينِهم طبيعةً، ولهم في الولاياتِ فنونٌ رفيعة وسيعة؛ فلذلك استعمل الإمامُ أحمدَ أميرًا في عمان، وابنَه تركيًا أميرًا في الأحساء ونواحيه، وابنَه محمدًا أميرًا في سدير وبلدانه، وعبدَ المحسن ابنه أيضًا أميرًا في بلدهم الغاط، فلو نظرتَ إلى أصغرِهم لقلتَ هذا بالأدبِ قد أحاط، وإن نظرتَ إلى الأكبر لرأيتَ فوق ما يُذكَر، لم يكُنْ في عصرِهم مثلُهم للمُطيع الصاحِبِ، ولا أشدُّ منهم على العدو المحاربِ، فهم عيبة نصحٍ للإمام وفظًّا غليظًا على محاربيه، يبادرون لطاعته ويقدمونها على ما لهم من الذِّمام."},{"id":4585,"title":"وفاة رؤوف باشا رئيس وزراء الدولة العثمانية .","date":["العام الهجري :1268","الشهر القمري : ربيع الآخر","العام الميلادي :1852"],"text":"هو الصَّدرُ الأعظم محمد أمين رؤوف باشا رئيس الوزراء بالدولةِ العُثمانية، وهو عثماني تركي، توفِّيَ عن عمر يناهز الثمانين عامًا، وقد تولى الوزارة 5 مرات، بلغ مجموعُ سِنِيها 14 عامًا."},{"id":4586,"title":"تركيا وحرب القوى العظمى في القرم ضد روسيا .","date":["العام الهجري :1269","العام الميلادي :1852"],"text":"حاولت روسيا إعادةَ اتفاقية خونكار أسكله سي، ولكِنَّ الدولة العثمانية رفضت ذلك، كما رفضت حقَّ حماية روسيا للنصارى المقيمين في الدولةِ العثمانية، وأُعيدَ رشيد باشا للصدارة العظمى بعدما عُزِلَ سابقًا؛ إرضاءً لروسيا، فهددت روسيا باحتلالِ الأفلاق والبغدان، فأبلغ الخليفةُ ذلك التهديدَ لسفراء الدول، فأعطت إنكلترا الأوامِرَ لقطعاتِها البحرية المنتَظِرة في مالطة بالتحَرُّك إلى مياه اليونان، والاشتراك مع القوَّاتِ الفرنسية فيها، ثم التوجُّه لمضيق الدردنيل، وأما القواتُ الروسية فقد تقَدَّمت واحتلَّت إقليمَي الأفلاق والبغدان، فسَعَت النمسا للصلحِ، وعُقدَ مؤتمرٌ للصُّلحِ في نهاية العام 1269هـ، ولكن انتهى دون نتائِجَ، وأرسلت الدولةُ العثمانيةُ بضرورةِ إخلاء ولايتي الأفلاق والبغدان في مدة خمسة عشر يومًا، وأمرت القائدَ عمر باشا بالتحَرُّك لدخول الولايتين عند انتهاءِ المهلة، وقد دخل فعلًا وأجبر الروس على الانسحابِ، كما انتصر العثمانيون في الوقتِ نفسِه في جهة القفقاس، واحتلُّوا بعضَ القلاعِ، ثم توقَّف القِتالُ بسَبَبِ الشتاءِ، واستنجد قيصر روسيا بملك النمسا فيما إذا تدخَّلت الدول الغربية فاعتذر، أما في البحرِ فقد دمَّرَت الأساطيل الروسية في البحرِ الأسود القطعاتِ العثمانيةَ في ميناء سينوب، ثم وصلت القطعاتُ الفرنسية والإنكليزية ولم تُجْدِ محاولاتُ الصلح، وكان موقف فرنسا وإنكلترا ضِدَّ روسيا حفاظًا على مصالحهم. وقد جرى اتفاقٌ في استانبول في الثاني عشر من جمادى الآخرة عام 1270هـ بين العثمانيين وفرنسا وإنكلترا على محاربة روسيا، وأن ترسِلَ فرنسا خمسين ألف جندي وترسِلَ إنكلترا خمسة وعشرين ألفًا على أن يرحلوا بعد خمسةِ أسابيع من الصلحِ مع روسيا، وأعلنت فرنسا الحربَ على روسيا بالاتفاق مع إنكلترا، ثم اتفقت الدولتان في لندن في العام نفسِه في الثاني عشر من رجب ألا تنفَرِدَ إحداهما بالاتصال مع روسيا أو الاتفاقِ معها، وأن تمنع روسيا من ضَمِّ أي جزء من الدولة العثمانية إليها، وجمعت جيوشَها في غاليبولي واستانبول، ثم بدأت المعاركُ البحرية قبل أن تَصِلَ الجيوشُ البرية وهَدَمَت القِطَعُ البحرية الإنكليزية والفرنسية قلاعَ مدينة أوديسا، واجتازت الجيوشُ الروسية نهر الدانوب وحاصرت مدينةَ سلستريا مدة خمسين يومًا ولم تستطع اقتحامَها، وجاء المدَدُ للعثمانيين فترك الروس الحصارَ وانسحبوا، وأراد العثمانيون ملاحقَتَهم واحتلال الأفلاق والبغدان حيث أخلاهما الروس إلَّا أن النمساويين قد احتلُّوا هذين الإقليمين ووقفوا في وجهِ العثمانيين، ثم نقلت الدُّولُ المتحالفة المعركةَ إلى أرض روسيا وحاصرت ميناءَ سيباستبول وهَزَمت الجيوش الروسية، ثم اقتَنَعت النمسا بالانضمام إلى الدُّوَل المتحالفة، ثم انضمت أيضًا مملكة البيمونت الإيطالية إلى التحالُف، والتي احتلَّت ميناء كيرتش وبحر آزوف؛ لمنع وصول الإمدادات الروسية إلى ميناء سيباستبول التي استطاع الحلفاءُ دُخولَه في ذي الحجة من عام 1271هـ، وحاصرت مدخل البحر الأبيض الشمالي، واحتلت بعضَ الموانئ على المحيط الهادي، ثم توغلت في أوكرانيا، أما الروسُ فاستطاعوا أن يدخُلوا مدينة قارص، ثم حلَّ الشتاءُ فتوقفت الحروب، ثم انضمت السويدُ إلى التحالف إلى أن وافقت روسيا على طلباتِهم التي زادت عما طُلِبَ منها سابقًا، وعُقِدَت في باريس معاهدةٌ تنصُّ على: تُخلَى المناطِقُ التي احتُلَّت أثناء الحرب من كلا الطرفين، ويُطلَق سراح الأسرى، ويَصدُرُ عفوٌ عامٌّ عن جميع الذين تعاونوا مع خصومِ دُوَلهم، تُطلَق حرية الملاحة في البحر الأسود للدول جميعًا، ولا تُنشَأُ فيه قواعِدُ بحرية حربية، تطلَقُ حرية الملاحة في نهر الدانوب، تبقى الصِّربُ مرتبطة بالدولة العثمانية ولها استقلالٌ ذاتيٌّ يُضمَنُ مِن قِبَل الدول، ثم اتُّفِق على تكوين دولةٍ شبهِ مستقلة تضم الأفلاق والبغدان تسمَّى الإمارات المتحدة، وتكون تحت حماية جميع الدول، فتخرج بالتالي من التبعية العثمانية، وكانت هذه المعاهدةُ في عام 1275هـ."},{"id":4587,"title":"توقيع الفرنسيين معاهدة المقطع مع الأمير عبد القادر الجزائري .","date":["العام الهجري :1269","الشهر القمري : ربيع الأول","العام الميلادي :1853"],"text":"وقَّع الفرنسيون معاهدةَ المقطع مع الأمير عبد القادر الجزائري، وجاءت هذه المعاهدةُ بعد هزيمتهم أمامَه تحت قيادةِ الحاكمِ الفرنسي \"تيرزيل\"."},{"id":4588,"title":"أهل عنيزة يخرجون أميرهم جلوي بن تركي .","date":["العام الهجري :1270","العام الميلادي :1853"],"text":"حصل خِلافٌ بين أهل عُنيزة وأميرهم جلوي بن تركي، فأخرجوه منها ونزل بُرَيدة وكاتَبَ أخاه الإمام فيصلًا، وأخبره بالأمر، وكتب أهلُ عنيزة إلى الإمام فيصل ينتَقِدون شِدَّةَ وطأة الأمير جَلَوي عليهم، وعدم مراعاته لذوي المقامات منهم، وتكليفهم بأمورٍ ليست من مقامهم، وأنه يتعمَّدُ اضطهاد الأعيان وإذلالَهم مِمَّا لم يسَعْهم الصبر عليه، وإنهم اختاروا له العزلةَ إلى أن يأتي أمرُه بإرسال من يَخلفُه، ولكنه فارق البلاد، ونحن لم نخرُج عن الطاعة، وما زلنا بالسمع والطاعة. ولكِنَّ الإمام أرجع الرسولَ ورسالتَه لم يقرأها، وكأنَّ عبد الله الفيصل قد أخذ يتدخَّلُ في الأمور، وكان يميلُ إلى الشدة في التعامُل معهم، فصَمَّم على حربهم، فلما كان في شهر ذي الحجة من هذه السنة خرج عبد الله ومعه غزوُ الرياض، والخرج، والجنوب، والمحمل، وسدير، والوشم، فأغار على وادي عُنيزة، فخرج إليه أهلُ عنيزة وحصل بينهم قتالٌ شديدٌ قُتِلَ فيه سعد بن محمد بن سويلم، أمير ثادق، فرحل عبد الله الفيصل ونزل العوشرية. ثم رحل ونزل روضةَ العربيين، ثم ركب الأميرُ عبد الله اليحيى السليم إلى الإمام فيصل وبسَطَ له الأمر، وقال: إنَّنا لا نزال على السمعِ والطاعة ولا نحتاجُ إلى تجريد الجيوشِ وأمرُك نافذ، فرَضِيَ عنهم، وكتب لابنِه عبد الله أن يرجِعَ مع عمه جلوي إلى الرياض، فرجعوا دون أن تكون مصادمةٌ غير الأولى، وبهذا رجع آل سليم إلى إمارة بلدِهم ولم يوجِدوا هذه الحركةَ إلَّا لهذا القصد؛ لأنهم خشُوا أن يطول الأمر فتكونَ عُنيزة مركزًا لإمارة القصيم من قِبَلِ الحاكم بدلًا من بُرَيدة فتضيعَ إمارتُهم بذلك."},{"id":4589,"title":"ولاية محمد سعيد باشا بن محمد علي باشا لحكم مصر .","date":["العام الهجري :1270","العام الميلادي :1853"],"text":"تولَّى محمد سعيد باشا بن محمَّد علي باشا حُكمَ مِصرَ خلفًا لابن أخيه عباس الأول، وهو الرابِعُ من أسرة محمد علي باشا الذين تولَّوا الحكم. وتميَّز عَهدُه بعدد من الإجراءات الإصلاحية التي وقفت إلى جانبِ الفلاحِ المصري، وأبرَزُ أعمالِه حفرُ قناةِ السويس."},{"id":4590,"title":"نزاع على رئاسة المنتفق بين أبناء السعدون .","date":["العام الهجري :1270","العام الميلادي :1853"],"text":"بعد وفاة عيسى بن محمد السعدون سنة 1259هـ تولَّى بعده أخوه بندر فأخذ نحوًا من ثلاث سنين من ولايتِه وحكَمَهم في ابتداءٍ مِن الخلل، ثم مات ووَلِيَ بعده أخوه فهد، فلم تطُلْ مُدَّتُه، فقد مات قبل أن يتِمَّ سنة في رئاستِه, ثم مرج حكمُ المنتفق بعده، فتارةً في أولاد راشد السعدون، وتارةً في أولاد عقيل السعدون، وتارة في ولد عيسى السعدون، يتحاربون ويتقاتلون بينهم، حتى هلك منهم أممٌ؛ يأخذ الواحِدُ منهم مدة قليلة، ثم يأتيه المحارِبُ له فيُخرِجُه، فيشيخ مكانَه، ثم يذهب المُخرَجُ فيجمَعُ له قوة ويزيد الحُكَّام خراجًا، فيُظهِرون معه عسكرًا فيأتي صاحِبَه ويُخرِجُه. ودام ذلك بينهم إلى هذه السنة وأمرُهم في مروج، والثابتُ المستقِرُّ في الحكم هذا العام هم ولد راشد بن ثامر السعدون."},{"id":4591,"title":"انتقال الأمير عبد القادر الجزائري إلى دمشق .","date":["العام الهجري :1270","العام الميلادي :1853"],"text":"ظلَّ الأمير عبد القادر الجزائري في سجون فرنسا يعاني من الإهانة والتضييق حتى عام 1852م، ثم استدعاه نابليون الثالث بعد تولِّيه الحكم، حيث وافق له أن يرحل إلى الشرق براتبٍ من الحكومة الفرنسية. توقَّف الجزائري في استانبول حيث السلطانُ عبد المجيد الأول، والتقى فيها بسفراءِ الدول الأجنبية، ثم استقَرَّ به المقام في دمشق منذ عام 1856م وفيها أخذَ مكانه بين الوُجَهاء والعلماء، وقام بالتدريسِ في المسجد الأموي، كما قام بالتدريس قبل ذلك في المدرسةِ الأشرفية، وفي المدرسة الحقيقية، وفي عام 1276هـ /1860 م تحرَّكت شرارة الفتنة بين المسلمين والنصارى في الشام، فكان للأمير دورٌ فعَّال في حماية أكثر من 15 ألف نصراني؛ إذ استضافهم في منازِلِه."},{"id":4592,"title":"وقوع معركة \"سينوب\" البحرية بين روسيا والدولة العثمانية .","date":["العام الهجري :1270","الشهر القمري : صفر","العام الميلادي :1853"],"text":"أعلنت الدَّولةُ العثمانيةُ الحَربَ على روسيا في 1 محرَّم من هذه السنة، وأرسلت قِسمًا من أسطولها البحري إلى ميناء \"سينوب\" على البحر الأسود، وكان يتألَّفُ من ثلاث عشرة قطعة بحَرية بقيادة \"عثمان باشا\"، ثم وصلت إلى الميناء بعضُ القطع البحرية الروسية في 18 محرم من هذه السنة بقيادة \"ناخيموف\" قائد الأسطولِ الروسي؛ لتكشِفَ مواقع الأسطول العثماني، وتَعرِف مدى قوَّتِه، وظلَّت رابضةً خارج الميناء، محاصرةً للسفن العثمانية، وأرسل ناخيموف إلى دولتِه لإمداده بمزيدٍ مِن القطع البحرية، فلما حضرت جعَلَ أربعًا من سفُنِه الحربية خارجَ الميناء؛ لتقطع خطَّ الرجعة على السفن العثمانية إذا هي حاولت الهرَبَ. ولما توقَّع \"عثمان باشا\" غَدْرَ الأسطول الروسي، أمَرَ قواده وجنوده بالاستعدادِ والصبر عند القتال، على الرغم من تعهُّدِ نيقولا قيصر روسيا ووعْدِه بعدم ضرب القوات العثمانية إلَّا إذا بدأت هي بالقتال، لكِنَّ القيصر حنث في وعده؛ إذ أطلقت السفنُ الروسية النيرانَ على القطع البحرية العثمانية التي كانت قليلةَ العدد وضئيلةَ الحَجمِ إذا ما قُورِنَت بالسفن الروسية، وذلك في 28 صفر من هذا العام، وأسفرت المعركةُ عن تدمير سفن الدولة العثمانية، وقَتْل أكثر بحارتها. وقد أثار هذا العمَلُ غَضَبَ فرنسا وإنجلترا، فقررتا الدخولَ في حَربٍ ضِدَّ القيصر الروسي إلى جانب السلطان العثماني، واستمَرَّت نحو عامين، وهي الحربُ المعروفةُ بـ\"حرب القرم\"."},{"id":4593,"title":"انتصار الجيش العثماني في معركة جاتانا على الجيش الروسي .","date":["العام الهجري :1270","الشهر القمري : ربيع الآخر","العام الميلادي :1854"],"text":"تعرَّض الجيشُ الروسي لهزيمةٍ قاسية في معركة جاتانا في رومانيا من الجيشِ العثماني، وبذلك فَشِلَ الروس في طردِ العثمانيين من رومانيا، والذي كان هدفًا رئيسيًّا من أهداف تلك المعركةِ."},{"id":4594,"title":"عقد الدولة العثمانية \"معاهدة استانبول\" ضد روسيا. .","date":["العام الهجري :1270","الشهر القمري : جمادى الآخرة","العام الميلادي :1854"],"text":"عقدت كلٌّ من الدولة العثمانية وإنجلترا وفرنسا \"معاهدة استانبول\"، والتي نصَّت على ألَّا تَعقِدَ أيُّ دولة منهم أي صلح منفرد مع روسيا، وأن تكوِّنَ الدولُ الثلاث جيشًا واحدًا في حرب أيٍّ منهم ضِدَّ روسيا."},{"id":4595,"title":"إعلان فرنسا وإنجلترا الحرب على روسيا .","date":["العام الهجري :1270","الشهر القمري : جمادى الآخرة","العام الميلادي :1854"],"text":"أعلنت كلٌّ من فرنسا وإنجلترا بصفةٍ رسمية الحربَ على روسيا؛ وذلك تنفيذًا لمعاهدة استانبول التي وقَّعَتْها الدولتان مع الدولة العثمانية، والتي تقضي بتكوينِ جيشٍ واحد من كلٍّ مِن تركيا وفرنسا وإنجلترا بهدفِ حربِ روسيا."},{"id":4596,"title":"انتصار العثمانيين على الروس في معركة \"قالافات\" .","date":["العام الهجري :1270","الشهر القمري : رجب","العام الميلادي :1854"],"text":"انتصر الجيشُ العثماني بقيادة عمر باشا على الجيشِ الروسي في معركة \"قالافات\" في رومانيا، وطارد الجيشُ العثماني الروسَ مسافة 80 كم."},{"id":4597,"title":"صدور امتياز قناة السويس  .","date":["العام الهجري :1270","الشهر القمري : شعبان","العام الميلادي :1854"],"text":"بعد أن تولى محمد سعيد باشا حُكمَ مِصرَ في 14 يوليو 1854م تمكن فرديناند دي لسبس المهندس الفرنسي -الذي كان مقرَّبًا من سعيد باشا- من الحصول على فرمان عقدِ امتياز قناة السويس الأوَّل، وكان مكوَّنًا من 12 بندًا، كان من أهمها حفر قناة تصِلُ بين البحرين، ومدة الامتياز 99 عامًا من تاريخ فَتحِ القناة، واعترضت إنجلترا بشدَّةٍ على هذا المشروع خوفًا على مصالحِها في الهند. قام دي لسبس برفقة لينان دي بلفون بك وموجل بك كبيرَي مهندسِي الحكومةِ المصريةِ بزيارةِ منطقةِ برزخ السويس في 10 يناير 1855 لبيانِ جدوى حفرِ القناة، وأصدر المهندسان تقريرَهما في 20 مارس 1855 والذي أثبت سهولةَ إنشاءِ قناة تصل بين البحرين. وقام دي لسبس بتشكيلِ لجنة هندسيةٍ دوليةٍ لدراسة تقريرِ المهندسين وزاروا منطقةَ برزخ السويس وبورسعيد وصدر تقريرُهم في ديسمبر 1855م وأكَّدوا إمكانية شق القناة وأنَّه لا خوفَ مِن منسوب المياه؛ لأنَّ البحرين متساويَينِ في المنسوب، وأنه لا خوف من طمي النيل لأن بورسعيد شاطئها رملي. وفي 5 يناير 1856م صدرت وثيقتان هما عقدُ الامتياز الثاني وقانون الشركة الأساسي، وكان من أهمِّ بنودِه قيام الشركة بكافة أعمال الحَفرِ وإنشاء ترعة للمياه العذبة تتفَرَّعُ عند وصولها إلى بحيرة التمساح شمالًا لبورسعيد وجنوبًا للسويس، وأنَّ حجم العمالة المصرية أربعة أخماس العمالةِ الكلية المستخدَمة في الحفر. وفي الفترة من 5 إلى 30 نوفمبر 1858م تم الاكتتابُ في أسهم شركة قناة السويس وبلغ عددُ الأسهُم المطروحة للاكتتاب 400 ألف سهم بقيمة 500 فرنك للسَّهمِ الواحد، وتمكن دي لسبس بعدها من تأسيسِ الشركة وتكوين مجلسِ إدارتِها."},{"id":4598,"title":"انهزام الجيش الروسي في معركة \"يركوي\" .","date":["العام الهجري :1270","الشهر القمري : شوال","العام الميلادي :1854"],"text":"تعرَّض الجيشُ الروسي لهزيمةٍ قوية من الجيش العثماني بقيادة القائد العثماني عمر باشا، وذلك في معركة \"يركوي\" قربَ رومانيا، وخَسِرَ الروس في هذه المعركةِ 6 آلاف جندي."},{"id":4599,"title":"إنزال فرنسا وإنجلترا قواتهما في شبه جزيرة القرم .","date":["العام الهجري :1270","الشهر القمري : شوال","العام الميلادي :1854"],"text":"أنزلت كلٌّ من فرنسا وإنجلترا عددًا كبيرًا من قواتهما العسكرية في شبه جزيرة القرم الواقعة حاليًّا في أوكرانيا؛ وذلك لمساندة الدولة العثمانية في حربها ضد روسيا، تنفيذًا لمعاهدة استانبول الموقَّعة في جمادى الآخرة من هذه السنة."},{"id":4600,"title":"وفاة الشيخ المفسر شهاب الدين محمود الألوسي .","date":["العام الهجري :1270","الشهر القمري : ذي القعدة","العام الميلادي :1854"],"text":"هو الشيخُ المفسِّر أبو الثناء شهاب الدين محمود بن عبد الله الألوسي الحسيني البغدادي صاحِبُ التفسير المعجب المسمى (روح المعاني)، أحد علماء القرن 13 الهجري، وهو مفتي بغداد، وخاتِمةُ المحقِّقين من أعلام المشرق، ولِدَ ببغداد سنة 1217 وتعلم بها وتوفِّيَ فيها، جلس للتدريس وأقبل عليه الطلاب من كلِّ مكان، وترك مؤلفات كثيرة أهمها: التفسير المعروف بروح المعاني في تفسير القرآن العظيم والسبع المثاني. قال عنه صاحب فهرس الفهارس: \"خدم العِلمَ في القرن المنصرم خدمةً تُذكَر ولا تُكفَر، له من الرحلات: نشوةُ الشمول في السَّفَر إلى استامبول، وكتاب نزهة الألباب في الذهاب والإقامة والإياب، تعرَّض فيها لذكر أشياخِه وما قرأه عليهم وما أخذ منهم، وله أيضًا غرائب الاغتراب ونزهة الألباب، وله نشوة المدام في العود إلى دار السلام. في هذه الرحلات الثلاثة تفصيل رحلته إلى الأستانة ومن لقِيَ في ذهابه وإيابه من رجال العلم والأدب، لا سيما شيخ الإسلام عارف حكمت بك، وما جرى بينهما من المباحثة. وله مجلدٌ نفيس في ترجمة شيخ الإسلام بالمملكة العثمانية عارف حكمت بك \"، قال عنه الزركلي: \"مفسِّر، محدث، أديب، من المجدِّدين، من أهل بغداد، مولده ووفاته فيها. تقلَّد الإفتاء ببلده سنة 1248هـ، ثم عزل عنه، فانقطع للعلم. ثم سافر سنة 1262هـ إلى الموصل فالأستانة، ومرَّ بماردين وسيواس، فغاب 21 شهرًا وأكرمه السلطانُ عبد المجيد الأول. وعاد إلى بغداد يدوِّنُ رحلاته ويكمِلُ ما كان قد بدأ به من مصنَّفاتِه، فاستمَرَّ الى أن توفِّيَ\"."},{"id":4601,"title":"انهزام الجيش الروسي في معركة \"ألما\" .","date":["العام الهجري :1270","الشهر القمري : ذي الحجة","العام الميلادي :1854"],"text":"تعرَّض الجيش الروسي لهزيمةٍ كبيرة في معركة \"ألما\" من قواتِ فرنسا وإنجلترا والدولة العثمانية، وخَسِرَ الروس في هذه المعركة 7 آلاف قتيل."},{"id":4602,"title":"صمود العثمانيين وعجز الروس في اقتحام قلعة سلسترا ببلغاريا .","date":["العام الهجري :1271","العام الميلادي :1854"],"text":"كان الفرنسيون أصحابَ الحَقِّ في حماية النصارى في بيتِ المقدِسِ، ثمَّ استطاع الروسُ الحصولَ على هذا الحَقِّ أيام نابليون بونابرت، فلمَّا رجعت الدولةُ الفرنسية وأرادت إعادةَ حَقِّها اصطدمت مع روسيا، فكانت الدَّولة العثمانية قد ألَّفت لجنةً مِن رجال الكنائِسِ على اختلافِ مذاهِبِهم فأيَّدوا فرنسا فهدَّد الروسُ بالحربِ وأرادوا إعادةَ معاهدة خونكار أسكله سي، وحاولت الاستعانةَ بإنكلترا وفرنسا اللتين رفضتا ذلك، وألغى السلطانُ عبد المجيد الأول امتيازَ الروس بحماية النصارى في الدولة العثمانية، وأعاد إلى الصدارةِ العظمى مصطفى رشيد باشا المعروف بعدائِه للروس، فقامت روسيا باحتلالِ الأفلاق والبغدان، وقامت الحرب بين الروس والعثمانيين ولكِنَّ إنكلترا وفرنسا حاولتا التوسُّطَ، ولكن لم تنفَعْ كلُّ محاولات الصلح فوقفَتَا بجانب الدولة العثمانية خوفًا على مصالحهما فعقدتا اتفاقًا لمساعدة العثمانيين ومَنْع الروس من احتلال أيِّ جزء من الأراضي العثمانية، فأوقَفوا الهجومَ الروسي في بلاد القرم عند نهر ألما، فاضطرت روسيا إلى الرجوعِ عن بعض المناطق التي احتلَّتْها لَمَّا رأت الإمداداتِ تتوالى على الدولةِ العثمانية، وعُقِدت بعدها معاهدةُ باريس."},{"id":4603,"title":"خسارة الروس 20 ألف قتيل في هجوم جيش الاتفاق .","date":["العام الهجري :1271","الشهر القمري : رمضان","العام الميلادي :1855"],"text":"خَسِرَ الروس 20 ألف قتيل في هجومِ جَيشِ الاتفاق الفرنسي الإنجليزي العثماني على قلعة \"سيفاستوبول\"- الواقعة حاليًّا في أوكرانيا- وذلك في أثناء \"حرب القرم\" بين الدولة العثمانية وحلفائِها من جهة، وبين روسيا من جهةٍ أخرى."},{"id":4604,"title":"استدانة الدولة العثمانية لأول مرة في تاريخها من الخارج .","date":["العام الهجري :1271","الشهر القمري : ذي القعدة","العام الميلادي :1855"],"text":"قامت الدولةُ العثمانية لأوَّلِ مرة في تاريخها بالاستدانة من الخارج؛ حيث حصَلَت على قرض مقداره 5 ملايين قطعة ذهبية بفائدة 5% من إنجلترا؛ وذلك لتغطية نفقات حَربِها ضِدَّ روسيا."},{"id":4605,"title":"الإمام شامل يقود الثورة في داغستان ضد الروس .","date":["العام الهجري :1272","العام الميلادي :1855"],"text":"انتقلت قيادةُ الثورة في داغستان ضِدَّ الروس إلى الشيخ الإمام شامل بن دنكاو الداغستاني، وكان قد صَحِبَ منذ صغره الشيخَ المجاهد محمد الكمراوي قائدَ الثورة الأول في رحلته العلمية، وعكف معه على العلم والعبادة، والأمر بالمعروف والنهى عن المنكر، حتى قامت الثورةُ المباركة وكان الإمامُ شامل الذراعَ الأيمن لمحمد الكمراوي، وقائد جيوشه وشريكه في الأمور حتى ليلة استشهاده، ثم اشترك مع القائد الثاني حمزة بك علي حتى استشهاده أيضًا، فأجمع الناسُ على تولية الشيخ الإمام شامل قيادة الثورة، ومن يومها أصبح اسمُه الإمام شامل. حمل على عاتقِه إحياءَ الدين الإسلامي ونَشْر العلم، وتطبيق الشريعة، وإقامة العدل، وتطهير المجتمع من الآثار المرذولة التي خَلَّفها الاحتلال الروسي للبلاد، وجاءت خطواتُ الإمام شامل لتحقيقِ هذا الهدف بالقضاء على المنافقين؛ حيث قام بتطهير المجتمَعِ الداغستاني من العُملاء والموالين للاحتلال الروسي، ثم ضَمَّ الشيشان مع داغستان؛ حيث لم يكن هدفُ الإمام شامل تحرير داغستان فقط من الاحتلال الروسي، بل كان يهدفُ لتطهير منطقة القوقاز بأسْرِها من الروس، واستعادة الحُكم الإسلامي عليها مرةً أخرى؛ لذلك عَمِلَ الإمامُ شامل على توسيعِ قاعدة الدولة الإسلامية، فانتقل بالثورةِ إلى الشيشان، وصار قوة كبيرة يُخشى بأسُها، وأنزلت هذه القوةُ العديدَ من الهزائمِ المدوِّية على الجيش الروسي، خاصةً في معركة ويدانو سنة 1251هـ التي قُتِل فيها ستة آلاف صليبي روسي، ولقد انضمَّ للإمام شامل مجموعةٌ من العلماء العاملين المجاهدين المخلِصين، كما انضم له الكثيرُ مِن الشيشان، وانضَمَّ له من قبائل الشركس واللاز والأبخاز وغيرهم من أهل منطقة القوقاز، وبَقُوا يقاتِلون معه."},{"id":4606,"title":"انتصار الجيش العثماني في معركة \"أنجير\" على الجيش الروسي .","date":["العام الهجري :1272","الشهر القمري : صفر","العام الميلادي :1855"],"text":"انتصر القائدُ العثماني عمر باشا على الجيشِ الروسي في معركة \"أنجير\"، أثناءَ الحرب الروسية العثمانية المسمَّاة \"حرب القرم\"."},{"id":4607,"title":"صدور فرمان لتنظيم أوضاع النصارى في الدولة العثمانية .","date":["العام الهجري :1272","الشهر القمري : جمادى الآخرة","العام الميلادي :1856"],"text":"أصدر السُّلطانُ العثماني عبد المجيد الأول فرمانًا (قانونًا) عُرِفَ باسم \"إصلاحات خط همايوني\" حول أوضاع النصارى في الدولةِ العثمانية، وقد تعرَّض هذا الفرمان لانتقاداتٍ كبيرة داخل الدولة. وقد تضَمَّن البنودَ التالية: المساواة بين كل مواطِني الدولة العثمانية في الحقوقِ والواجبات مهما كانت أديانُهم ومذاهبُهم. عدم إجبار أي شخص على تركِ دينه. إلغاء نظام الالتزام (جباية الأموال والضرائب من عامة الشعب لإرسالها إلى السلطان العثماني) والقضاء على الرشوة والفساد. إلزام كل المواطنين في الدولة بالخدمة العسكرية. حق التعيين في مناصب الدولة المدنية والعسكرية مكفولٌ للكفاءات بدون تمييز ديني. محو كل الألفاظ التي تمَسُّ فئة من المواطنين، سواء كانت دينية أو مذهبية. إعفاء الكنائس من الضرائب والمصروفات. يُنتخب بطاركة الكنائس من كل المِلل، وتكون فترة انتخابهم حتى وفاتِهم. لا يحق لأحدٍ نَزعُ سلطة البابا إلَّا من كنيست. تشكيل مجلس مكوَّن من رجال الكنيسة (كهنة ورهبان) ورجال من خارج الكنيسة (نصارى ليسوا رهبانًا أو كهنة) لإدارة شئون المِلَّة. السلطان شخصيًا وفقط هو من له الحَقُّ في ترخيص بناءِ وترميم الكنائس والمقابر الخاصة لغير المُسلمين. الدعاوى القضائية بين النصارى والمسلمين تُعقد في دواوين (محاكم) خاصة، ويرأسها قُضاةٌ من الطرفين."},{"id":4608,"title":"توقيع \"معاهدة باريس\" لإنهاء \"حرب القرم\" .","date":["العام الهجري :1272","الشهر القمري : رجب","العام الميلادي :1856"],"text":"وقَّعت كلٌّ من الدولة العثمانية وإنجلترا وفرنسا والنمسا وروسيا وبروسيا وساردونيا \"معاهدة باريس\"؛ وذلك لإنهاء حرب القرمِ التي شاركت فيها الدُّوَل السابقة، وتعَدُّ من كبرى الحروب التي شهدها العالَمُ في تلك الفترة، وتعدُّ هذه المعاهدة من المعاهدات التي صاغت الوجهَ السياسي لأوروبا في القرنِ التاسع عشر."},{"id":4609,"title":"إنشاء مجلس تجار مختلط من المصريين والأجانب .","date":["العام الهجري :1272","الشهر القمري : شعبان","العام الميلادي :1856"],"text":"قرر سعيد باشا حاكِمُ مِصرَ إنشاء مجلس تجَّار مختلط من المصريين والأجانب، وقد أدى إنشاء مثل هذا المجلس إلى تسرُّبِ القانون الأجنبي ليحُلَّ محَلَّ الشريعة الإسلامية في المعامَلاتِ."},{"id":4610,"title":"الإنجليز يعلنون أن الهند من أملاك التاج البريطاني .","date":["العام الهجري :1274","العام الميلادي :1857"],"text":"سيطر الإنجليز على الهند جزءًا بعد آخر بكُلِّ الوسائل، واستولوا على أوقاف المسلمين التي كانت المصدرَ الوحيد لكتاتيب التعليمِ، فزاد الجهل، وبالوقتِ نَفسِه قاموا بتقوية مركز الهندوس وتعليمِهم؛ ليكُونوا أعوانَهم ضِدَّ المسلمين، ودخل نتيجةَ الفقر كثيرٌ مِن المسلمين في الجيش الإنجليزي ولكِنَّهم كانوا يعامَلون بالاستهزاء مِمَّا وَلَّد لديهم الكراهة الزائدة، فحدثت ثوراتٌ ضِدَّ الجيش شَمِلَت معظم أجزاء البلاد، ثم جاءت النجدات للإنجليز فدخلوا دلهي وحاصروا المدنَ ودخلوها وانتقَموا من الأهالي شَرَّ انتقام إلى أن أنهَوا الثورات عام 1274هـ فأعلنت إنجلترا انتهاءَ حُكم شركة الهند الشرقية، وعَدَّت بلاد الهند من أملاكِ التاج البريطاني يتصَرَّفُ بها كيف يشاء، وصَبَّ الإنجليز جام غضَبِهم على المسلمين؛ لأنهم هم المحَرِّكُ للثورة فصادروا الأراضيَ والأملاكَ، وهَدَموا المساجِدَ وحَوَّلوها ثكناتٍ عَسكريَّةً، وأعان الهندوسُ الإنجليزَ على أفعالهم تلك؛ ثأرًا وانتقامًا، وبَقِيَت بعض الإمارات الصغيرة بيَدِ المسلمين."},{"id":4611,"title":"صدور عهد الأمان بتونس .","date":["العام الهجري :1274","الشهر القمري : محرم","العام الميلادي :1857"],"text":"صدر إعلانُ عهد الأمان في 20 محرم من هذه السنة، في عهد محمَّد باي، ويتكوَّنُ هذا العهد من مقدِّمة وإحدى عشرة مادة، وتشير المقدمة إلى وجوب الاهتداء بأحكام الشريعة الإسلامية الغرَّاء باعتبار أنَّ الإسلامَ هو الدينَ الرسمي للدولة التونسية، وأن الباي والسكَّان مسلمون، وأن الدولة العثمانية تؤكِّدُ الأمان لرعاياها وتراه من الحقوقِ المَرعيَّة. وتضَمَّنت موادُّ هذا العهد الأمانَ التامَّ لجميع سكَّان تونس دون النظَرِ إلى دياناتهم وأجناسِهم وجنسيَّاتِهم، ومساواة الجميعِ في مسائل الضرائبِ والرسوم الجُمركية. وتقرير الحرية في مزاولة التجارة وجميع مجالات العمل وشراء العقارات والأراضي الزراعية، بشرط أن يلتزِمَ الجميعُ القوانين العامَّةَ فيما يتَّصِلُ بالعمل وتمَلُّك العقارات. ونظَّم العَهدُ مسألةَ التجنيد؛ بحيث لا يظَلُّ المجنَّدُ في الخدمة أكثَرَ مِن مدة محددة حتى يتاحَ له الفرصةُ الملائِمةُ لتدبيرِ مَعيشتِه ومعيشة أسرته. ويلاحَظُ أنَّ هذا العهدَ فيه مزجٌ بين الاتجاه الإسلامي والاتجاه الأوربي السائد في ذلك الوقتِ."},{"id":4612,"title":"وفاة مصطفى رشيد باشا رئيس وزراء الدولة العثمانية .","date":["العام الهجري :1274","الشهر القمري : جمادى الأولى","العام الميلادي :1858"],"text":"هو مصطفى رشيد باشا الكبير، الصَّدرُ الأعظم ورئيس الوزراء في الدولة العثمانية. ولِدَ باستانبول سنة 1800 م ويعدُّ رشيد باشا أحدَ كبار رؤساء الوزارة في التاريخ التركي، وأحدَ عمالقة الدبلوماسية العثمانية خاصةً في عهد التنظيمات، وكان من دعاة التغريبِ؛ ولذلك كثيرٌ من تنظيماته كانت مقتَبَسةً من النظم الغربية التي تتعارض مع الشريعةِ الإسلامية؛ ولذلك لما أصدر أوَّلَ دستور للبلاد سمَّاه (خطا شريفا) جمع بين الشريعة والقوانين الأوروبيَّةِ، أعلن العلماءُ استنكارهم وتكفيرَهم لمصطفى رشيد باشا، واعتَبَروا الخط الشريف منافيًا للقرآنِ الكريم، وقد تولَّى الوزارة ستَّ مرات في عهد السلطان عبد المجيد الأول، كصدر أعظم، كما عمل وزيرًا للخارجية أربع مرَّاتٍ، وواليًا لأدرنه، وسفيرًا في لندن ثم باريس. توفي مصطفى رشيد باشا عن عمر يناهز السابعة والخمسين عامًا."},{"id":4613,"title":"وفاة الشريف محمد بن عون شريف مكة .","date":["العام الهجري :1274","الشهر القمري : شعبان","العام الميلادي :1858"],"text":"هو الشريف محمد بن عبد المعين بن عون بن محسن بن عبد الله بن حسين بن عبد الله بن حسن ابن أبي نمي، ولِدَ بمكة سنة 1204ه،ـ ونشأ بها، ولما استولى محمد علي باشا على مكَّةَ ذهب به إلى مصر وجلس بها عنده مدَّةَ سنواتٍ، ولَمَّا قُتِل الشريف يحيى بن سرور الشريف شمبر بمكة في شعبان سنة 1243هـ تولى عبد المطلب بن غالب إمارةَ مكة وهي إمارته الأولى وبقي أميرًا حتى قَدِمَ محمد بن عبد المعين بن عون من مصر في جمادي الآخر سنة 1243هـ وتولَّى إمارة مكة حتى سنة 1253حيث أعيد إلى مصر، ثم صدر الأمر السلطاني على محمد على باشابمصر بإعادةِ محمد بن عبد المعين بن عون أميرًا لمكَّة، فأعيد إليها 1256هـ وبقي أميرًا لمكة حتى سنة 1267 حيث ورد الأمرُ السلطاني بترحيلِه وجميع أبنائه إلى تركيا، وتولية الشريف عبد المطلب بن غالب، وهي المرة الثانية لولاية الشريف عبد المطلب، ثم عاد محمد بن عبد المعين ابن عون من تركيا وتولى إمارة مكة سنة 1271هـ وبقي بها أميرًا حتى توفِّيَ في ثالث شعبان من هذه السنة، وخلَّف ستة أبناء، هم: عبد الله، وعلي، وحسين، وعون، وسلطان. وتولى بعده إمارة مكة ابنُه الأكبر عبد الله."},{"id":4614,"title":"عزل السلطان بهادر شاه آخر سلاطين الدولة المغولية الإسلامية بالهند .","date":["العام الهجري :1274","الشهر القمري : شعبان","العام الميلادي :1858"],"text":"عزَلَ الإنجليزُ السلطانَ بهادر شاه الثاني عن الحُكمِ في الهند، ونَفَوه خارج البلاد, وهو آخِرُ سلاطين الدولة الإسلامية التي حكَمَت بلاد الهند، وبعَزلِه انتهى الحكمُ الإسلامي في الهند بعد أن استمَرَّ فيها ثمانية قرون ونصف قرن. كما يعتبر بهادرُ شاه الثاني آخِرَ حكام بني تيمور في الهند، وقد استمر حُكمُ بني تيمور في الهند قرابةَ ثلاثة قرون، وباستعمار الإنجليز بلادَ الهند عانت الهند من تعسُّفِ الإنجليز وظُلْمِهم وطغيانِهم، واستنزفت الشركةُ البريطانية ثرواتِ هذه البلادِ واستعبدت أهلَها، وأسفر ذلك في النهايةِ عن ثورة وطنية ضِدَّ هذا الظلم وذلك الإجحافِ."},{"id":4615,"title":"تولي الشيخ صباح الثاني بن جابر الحكم في الكويت .","date":["العام الهجري :1275","العام الميلادي :1858"],"text":"تولى الشيخُ صباح الثاني الحُكمَ بعد وفاة والِدِه الشيخ جابر بن عبد الله الصباح، وكانت فترةُ حُكمِه قصيرةً، وفي فترة حكمه احتفظ بالسلطةِ السياسيةِ وتركَ السلطةَ القضائيَّةَ إلى القاضي؛ حيث كان يتولاها وحدَه وبدون تدخُّلٍ منه، وقد اتَّسَعت التجارةُ في عهدِه وكثُرَت أموال الكويت، وأراد أن يضع رسومًا جمركيَّةً على البضائِعِ الخارجةِ من الكويت لكِنَّ التجَّارَ قالوا له: \" لا تجعَلْ على أموالنا ما لم يجعَلْه أبوك ولا جَدُّك مِن قَبلُ\" وقالوا له: إن أموالَهم ستكون وقفًا على ما تحتاجه الكويت، فوافقَهم على ذلك. وقد لفتَ نظر الكولونيل \"بلي\" حين زار الكويت ثانيةً في عام 1865 باطِّلاعه على ما يجري خارجَ الكويت من أمورٍ لها صلة بالأحداثِ في أوروبا والعالم، وكان ذلك من خلال صحيفةٍ عربية كانت تصدُرُ في باريس وترسَلُ إليه حافلةً بالأخبار الأجنبية والمحلية. وفي عهده هاجم عبدُ الله بن سعود قبيلةَ العجمان، فلجؤوا إلى الكويت، فأرسل عبد الله بن سعود رسولًا يطلُبُ منه أن يطرُدَ العجمان، لكِنَّ الرسولَ أساء التعبير فقال له: إنَّ معزبَك (وتعني سيدك) يأمُرُك بإخراج العجمان، فغضب الشيخُ صباح وأمر باستنفار أهلِ الكويت لقتالِ عبد الله بن سعود، فوصل الخبرُ إلى عبد الله، فأظهر أسَفَه وبادر إلى الاعتذارِ عن سوءِ تصَرُّفِ رَسولِه."},{"id":4616,"title":"استقلال رومانيا .","date":["العام الهجري :1275","العام الميلادي :1858"],"text":"في عام 1821م أُلقِيَ القبض على فلاديميرسكو زعيمِ مولدافيا ونُفِّذَ به حكم القتل بتهمةِ الخيانة؛ لأنه كانت له محاولات للخروجِ عن السلطنة العثمانية. ومع ذلك استمرت الثورات في رومانيا، التي أدَّت إلى معاهدة 1829م التي سُمِح لروسيا بموجِبِها باحتلالِ الإمارات الرومانية. وأصبح أميرُها يُعيَّنُ لمدى الحياة بالتوافُقِ ما بين القيصر الروسي والسلطان العثماني. وبعد عِدَّةِ ثورات قامت في تلك الإمارات قرَّر المؤتمَرُ الدولي في سنة 1858م منْحَ الإمارات نظامَ حُكمٍ ذاتي تستَمِرُّ بموجِبِه بدَفعِ الضريبة للسُّلطان العثماني, وفي عام 1881م أُعلِنَ استقلال رومانيا، وأصبح الأمير كارول المَلِكَ الأول، واستمَرَّت الحياة السياسية في العهد الملكي كما كانت عليه في السابقِ من تناوب الحُكمِ بين المحافِظين (البويار) من جهةٍ، والبورجوازيين والمثقفين والليبراليين من جهة ثانية. ووقع الاختيارُ على الأمير شارل دو هوهنزولرن سيغمارتغن الذي اتخَذَ اسم كارول دو رومانيا وأصدَرَ دستورًا جديدًا (1866م). في عام 1876م قرَّر الأمير كارول الاشتراكَ بالحرب الروسية التركية التي اندلعت في عام 1876م. لكنْ جاءت النتائج مخيِّبةً للآمال؛ إذ استُبعِدَت رومانيا عن المفاوضاتِ, وجاءت معاهدةُ السلام بعد عِدَّةِ حروب وقَعَت في المنطقة؛ لتثبت حدود «رومانيا الكبرى»."},{"id":4617,"title":"عزل الأمير عبد العزيز المحمد أبو عليان عن إمارة بريدة  .","date":["العام الهجري :1275","العام الميلادي :1858"],"text":"عاد الأميرُ عبد العزيز المحمد أبو عليان إلى إمارته في بُريدةَ بعد أن استرضى الإمامَ فيصل بن تركي، ولكنْ لم تكن الثقةُ بينهما تامةً، فالوحشةُ لم تفارِقْ عبد العزيز بل ازدادت؛ ذلك لأن الإمام لا ينظرُ إليه بالعين التي كان ينظرُه فيها، وما زال متَّهمًا عنده لكثرةِ نزعاته وعدم استقامته، ويزيد الإمامَ ما يتواترُ عليه من مهنَّا الصالح من أخبارٍ عن عبد العزيز لم تكُن في مصلحته، ومهنا كان طامِعًا بمركز عبد العزيز، فأثَّرت تلك الأخبار في الإمام، فاستدعى عبد العزيز إلى الرياض فقَدِمَ ومعه ابناه علي وعبد الله، فأمرهم بالبقاء عنده وجعَلَ عبد الله بن عبد العزيز بن عدوان أميرًا في بريدة، وهو من بني عم عبد العزيز المحمد."},{"id":4618,"title":"بدء أعمال الحفر في قناة السويس .","date":["العام الهجري :1275","الشهر القمري : رمضان","العام الميلادي :1859"],"text":"بدأت في مصرَ أعمالُ حَفرِ قناة السويس، وهي القناة التي تربطُ بين البحرين الأبيض والأحمر، واستمَرَّ الحفر في القناة لمدة 10 سنوات ونصف، وقد شارك فيه 60 ألف فلاحٍ مصري، وبلغ طولُها آنذاك 162,5 كم، وافتُتِحَت للملاحةِ في 19 من نوفمبر 1869م."},{"id":4619,"title":"الفتنة الطائفية في الشام بين الدروز والموارنة .","date":["العام الهجري :1276","العام الميلادي :1859"],"text":"تجدَّدت الفِتنةُ الطائفية في بلاد الشامِ؛ إذ اعتدى الموارنة على الدروز عام 1276هـ، فقام الدروز يأخُذونَ بالثأرِ، وامتَدَّ اللهيبُ مِن جبل لبنان إلى طرابلس وصيدا وزحلة ودير القمر واللاذقية ودمشق، وأسرعت الدولةُ فأرسلت فؤاد باشا وقضى على الفتنةِ، وعاقب المسؤولين عنها كلًّا بما يستحِقُّ، واحتَجَّت الدُّولُ الأوربية وهدَّدت بالتدخُّلِ، وكانت متفرقةَ الرأي ثم اجتمعت أو اتَّفَقت على أن ترسِلَ فرنسا ستة آلاف جندي لمساعدة الدولةِ فيما إذا عجزت عن إطفاءِ الفتنةِ -حسب زعمهم- وأنزلت فرنسا قوتَها في بيروت في الثاني والعشرين من محرَّم من عام 1277هـ، وهذا يُعَدُّ تدخلًا في شؤون الدولة العثمانية التي أحسَنَت القيامَ بمهمتها، لكن كان القصدُ تقوية النصارى وإظهارُهم بمظهرِ القوة، وأن أوربا كُلَّها من خَلْفِهم لتزدادَ قُوَّتُهم ويخشى خصومُهم بأسَهم، وجرى الاتفاقُ مع فؤاد باشا على أن يعوَّضَ النصارى على ما خسروه، ويُمنَحَ أهلُ الجبل حكومةً مُستقلَّةً تحت سيادة الدولةِ، وأن يرأس هذه الحكومةَ رجل نصراني لمدة ثلاث سنوات، ولا يحِقُّ عزلُه إلَّا برأي الدول الأوروبية، وتقترحه الدولةُ وتوافِقُ عليه أوروبا، وقد اختير أوَّلُ حاكم وهو داود الأرمني، ويذكَرُ أن هذا التساهل ألزم فرنسا بالانسحابِ مِن الشام إذ أخلَت المناطِقَ التي دخلَتْها في السابع والعشرين من ذي القعدة عام 1277هـ أي: بعد عشرة أشهر وخمسة أيام من دخولِها."},{"id":4620,"title":"الروس يأسرون الشيخ الإمام محمد شامل بعد جهاد طويل للروس .","date":["العام الهجري :1276","العام الميلادي :1859"],"text":"كان الشيخُ الإمام محمد شامل الداغستاني في عام 1834م قد دعا جميعَ رؤساء القبائل وكبار القضاة إلى اجتماعٍ في منطقةٍ وسطَ جبال القوقاز وتباحَثوا في أمرِ جهادِ الرُّوسِ، فبادر الإمامُ شامل بوضع القواعدِ اللازمة للارتقاءِ بالمقاومة الإسلاميَّةِ ضِدَّ الروس، وحوَّل القبائل إلى شَعبٍ واحدٍ، وقسَّم المناطِقَ إلى أقسامٍ عِدَّةٍ ووضع لكلِّ قسمٍ نائبًا يأخذُ على عاتقه الأمورَ الشرعيَّةَ والعُرفيَّةَ والعسكرية, وأنشأ ديوانًا أعلى للقضاءِ كان مقَرُّه في الشيشان مهمَّتُه تنفيذُ الأحكام الشرعية، وأنشأ المصانِعَ لإنتاج الأسلحة والذخائر, ووضع الشيخُ شامل تنظيمًا لحكمِ البلاد تحت رئاستِه والتفَّتْ شعوبُ القوقاز كلُّها حوله بعد أن نجحَ في ترسيخِ أحكام الإسلام في نفوسِ المسلمين وتربيتِهم التربيةَ الروحيَّةَ الجهاديَّةَ في سبيل اللهِ؛ لذلك انطلق المجاهِدون في حروبِهم ضِدَّ الروس من خلال فَهمِهم لعقيدةِ الجهاد الذي يُعتبر ذِروةَ سَنامِ الإسلام، واستطاع الشيخُ شامل خلال ثلاثين سنة إجلاءَ الروس من معظم بلاد القوقاز، وأنزل بهم هزائِمَ ساحقة، وانتشرت أخباره إلى أرجاء أوروبا، وأصبحت بطولاتُه رمزًا للأمم المقهورة, مِمَّا أثار الروسَ، فرصدوا مكافأةً لِمن يأتي برأسِ الإمام شامل 45.000 روبل فكتب الإمامُ شامل إلى الجنرال الروسي يقول فيه: \"كم كانت سعادتي حين علمتُ أنَّ رأسي تساوي هذا الثَّمَنَ الضخمَ، ولكنك لن تكون سعيدًا حينما أُخبرك أنَّ رأسَك ورأس القيصر ذاتِه لا يساوي لديَّ كوبيكا واحدًا!\" وقع الإمامُ شامل ضحيَّةَ التسويات الدولية؛ ففي 1856 انتهت الحربُ التركية الروسية وهو ما سمح لروسيا بالتركيزِ بقوَّتِها على الجبهة القوقازية بقوة 300,000 مقاتل، وأُوكِلت المهمة إلى الجنرال الشاب أليكساندر إيفانوفيتش بارياتسكي، فدفع بقواتِه بالهجوم من جميع الجهات على قوَّات الإمام شامل، حتى تمكَّنوا مِن أسْرِه عام (1859م) ومِن ثمَّ نَفْيه إلى خارج منطقة القوقاز. ولكِنَّه أُخلي سبيلُه بعد ذلك بشروطٍ أهمُّها الجلاءُ عن البلاد."},{"id":4621,"title":"وفاة محمد بن علي السنوسي الكبير صاحب الدعوة السنوسية .","date":["العام الهجري :1276","العام الميلادي :1859"],"text":"هو محمد بن علي السنوسي الكبير صاحِبُ الدعوة السنوسية، وواحِدٌ من كبار المُصلِحين في العالم الإسلامي في العصر الحديث. ولِدَ بمقاطعة وهران بالجزائر سنة 1202 هـ / 1798م، ورحل إلى فاس سنة 1812م، والتحق بجامِعِ القرويين وبعد تخرُّجِه فيها عُيِّن مدرسًا بالجامعِ الكبير بفاس. عاصرَ دخولَ الدولةِ السعودية الأولى للحجازِ واختلط بعُلَمائِها وأخذ عنهم، ثم عاد إلى ليبيا وقام بدعوته الإصلاحية التي اتخذت الإسلامَ طريقًا لها في العمَلِ، فدعا المجتمَعَ الليبي إلى العودةِ إلى الإسلام والاعتماد على الكتابِ والسنَّةِ ومحاربة الاختلافِ والتفَرُّق في الدينِ، ومواجهة المبشِّرين بالنصرانية، ومحاربة الاستعمار الإيطالي المتسَلِّط. لَقِيَت الدعوة التي أسَّسها السنوسي صدًى في نفوس سكان الصحراء في الشمال الإفريقي كله والسودان، وكسب صاحبُها من النفوذ والسُّمعة, وقد حقَّقت قدرًا كبيرًا من النجاح، فكَوَّن دولة إسلامية امتدَّت آثارها إلى أفريقيا الغربية. وأقام مدرسةً عِلميةً إسلاميةً خرَّجت العلماءَ والقضاة والدعاة، وله عددٌ من المؤلَّفات بلغت نحو 40 كتابًا. توفي السنوسي في الجغبوب، وخلفه ابنه أحمد المهدي في قيادة الحركة السنوسية."},{"id":4622,"title":"عبد الله بن فيصل يؤدب العجمان وآل مرة لفسادهم في الأحساء .","date":["العام الهجري :1276","العام الميلادي :1859"],"text":"أغار عبد الله بن فيصل على العجمان وآل شامر وبني حسين وآل عذبة من المرة، وانتصر عليهم في وقعةِ الصبيحة بالدوادمي، وملأ يدَه من أموالهم، وقتل منهم خلقًا كثيًرا، وقد كانوا يَعيثون في أطرافِ الأحساء فسادًا، وكان الشيخُ أحمد بن مشرف أرسل قصيدةً لعبد الله بن فيصل يحرِّضُه عليهم ويبَيِّن له خطَرَهم على البلادِ."},{"id":4623,"title":"وفاة الأمير جابر الأول بن عبد الله بن صباح حاكم الكويت .","date":["العام الهجري :1276","العام الميلادي :1859"],"text":"هو الأميرُ جابر الأول بن عبد الله بن صباح، ثالثُ أمراء الكويت من آل الصباح. ولِدَ في الكويت وأقام في البحرين إلى أن توفِّيَ والده سنة 1229هـ فعاد إلى الكويت وولِيَ إمارتها. وفي أيَّامِه استولت إحدى قبائل العراق على البصرة وطردت حاكِمَها، فلجأ إلى جابر الأول فأنجَدَه بعدة سفُنٍ مزوَّدة بالرجال والمدافع، فاستخلصها فكافأته الحكومةُ العثمانية بمقدارٍ كبيرٍ من التمر كان يُرسَلُ إليه كلَّ عامٍ، وحاولت حكومةُ لندن إقناعَه برفع الراية البريطانية على الكويتِ فأبى، وأرادوا البناءَ فيها فلم يأذَنْ لهم، واستمَرَّ في الحكم إلى أن مات فيها. وقد اشتُهِرَ بالكرم والحَزم، ولُقِّبَ بـجابر العيش من شِدَّةِ كَرَمِه، وكان كثير التصَدُّقِ على الفقراء."},{"id":4624,"title":"عودة الأمير عبد العزيز المحمد أبو العليان لإمارة بريدة .","date":["العام الهجري :1276","الشهر القمري : صفر","العام الميلادي :1859"],"text":"قام بنو عَمِّ عبد العزيز المحمد أبو العليان، وهم: حسن العبد المحسن، وأخوه عبد الله، ومحمد الغانم، وأخوه عبد الله، وقتلوا عبدَ الله بن عبد العزيز بن عدوان، أميرَ بُريدة من قِبَل الإمام فيصل، فلما بلغَ الإمامَ الخبَرُ جعل محمد الغانم أبو العليان أميرًا على بريدة، وبعد مدَّةٍ قليلة أطلق الإمامُ سراحَ عبد العزيز المحمد وأمره أن يرجِعَ أميرًا على بَلَدِه، وأبقى ابنَه عبد الله في الرياض كرهينةٍ؛ لأنَّ هذا الإطلاق لم يكُنْ عن رِضًا، ولكن رأى أنَّ البلد لا يستقيمُ فيها أميرٌ بسَبَبِ آل ابن عليان، وكان عبدُ الله الفيصل لا يرى رأيَ والده في عبد العزيز ويوَدُّ التخلُّصَ منه بأيِّ وجهٍ من الوجوه، ولكِن الإمامُ فيصل يغلِبُ عليه الحِلمُ والصَّفحُ."},{"id":4625,"title":"غزو عبد الله بن فيصل بن تركي جموع قبيلة العجمان وحلفائها .","date":["العام الهجري :1276","الشهر القمري : رمضان","العام الميلادي :1860"],"text":"تولَّى راكان بن فلاح بن حثلين زعامةَ العجمان بعد تنازُلِ عَمِّه حزام بن حثلين له عن رئاسةِ العجمان, وكان راكان شاعرًا وفارسًا مشهورًا تُروى حوله قِصَصٌ بطولية، واستمر سنواتٍ لا يصدُرُ منه ما يعكِّرُ صفو الأمن أو يثير مشكلاتٍ لحكومةِ الإمام فيصل، لكِنَّه في هذا العام أغار على إبِلٍ للإمام فيصل بن تركي نفسِه وأخذَها، ثم ارتحل إلى الصبيحية القريبة من الكويت، وقام بغاراتٍ على أطرافِ العراق، فجهز الإمام فيصل جيشًا جعل على رأسِه ابنَه عبد الله في شعبان من هذه السنة، وفي طريقِه إلى الصبيحية وجَدَ جماعة من العجمان عند ماء الوفراء، وهاجمهم وفَتَك بهم وكان زعيمُهم راكان قد توجَّه إلى الجهراء فتعَقَّبه عبد الله بن فيصل إلى هناك، حيث وقعت معركةٌ انتهت بهزيمةِ العجمان، وقُتِلَ حوالي سبعمائة رجل منهم، وفَرَّت بقاياهم إلى داخلِ بلدة الكويت واحتَمَت بها وتخلَّصَت البصرة والزبير من غاراتِ راكان وقومه."},{"id":4626,"title":"وفاة سليمان باشا الفرنساوي الكولونيل سيف القائد بالجيش المصري .","date":["العام الهجري :1276","الشهر القمري : شوال","العام الميلادي :1860"],"text":"هو سليمان باشا الفرنساوي، أو الكولونيل سيف، اسمه \"الكولونيل أوكتاف جوزيف انتلم سيف\" ولِدَ عام 1788م في مدينة ليون بفرنسا وهو ضابطٌ فرنسي جاء إلى مصر مع الحملةِ الفرنسية، وبقي بها واعتنق الإسلامَ، وهو من بقايا حروب نابليون. عندما فكر محمد علي في بناء جيشٍ مصريٍّ حديث يحافِظُ على إنجازاته عَهِدَ إليه بتكوينِ النواة الأولى من الضباط، واختار له أسوانَ حتى يبتَعِدَ الطلاب عن القاهرة ومؤثِّراتها والمؤامَرات التي كانت تحاكُ فيها. وقد لاقى \"الكولونيل سيف\" متاعبَ جمةً خلال تدريب طلابِ هذه المدرسة، خاصةً وأنهم لم يعتادوا الطاعةَ المُطلقةَ لرؤسائهم, كما لم يتعودوا أن يتعَلَّموا فنون الحرب الحديثة، وكان \"سليمان الفرنساوي\" شديدَ الإعجاب بالجندي المصري، ويُؤثَرُ في ذلك قوله: \"إن المصريين هم خيرُ من رأيتُهم من الجنود؛ فهم يجمعون بين النشاط والقناعة والجَلَد على المتاعب، مع انشراحِ النَّفسِ وتوطينها على احتمالِ صُنوف الحِرمان، وهم بقليلٍ مِن الخبز يسيرون طوالَ النهار يحدوهم الشَّدوُ والغناءُ. ولقد رأيتُهم في معركة \"قونية بالشام\" يبقون ساعاتٍ متوالية في خطِّ النار محتفظين بشجاعةٍ ورباطةِ جأشٍ تدعوان إلى الإعجابِ، دون أن تختلَّ صُفوفُهم، أو يسري إليهم المَلَل أو يبدو منهم تقصيرٌ في واجباتهم وحركاتهم الحربية\". وظل سليمان باشا في خدمةِ الجيش المصري بعد وفاة محمد علي حتى صار القائِدَ العام للجيش المصري في عهد الخديوي عباس، واستمَرَّ في عمله أيامَ عباس الأول وسعيد باشا، وعاش بين المصريين وقام بمصاهرتِهم، فتزوَّج إحدى بناتِه \"محمد شريف باشا\" الذي يُطلَق عليه المصريون أبو الدستور، وأنجب منها فتاةً تزوجت من \"عبد الرحيم صبري باشا\" وأثمر هذا الزواجُ فتاةً أصبحت ملكةً على مصر وهي \"الملكة نازلي\" أم الملك الراحل\" فاروق الأول\". وتقديرًا من المصريين أقاموا لسليمان الفرنساوي تمثالًا في ميدان أطلق عليه اسمه، كما أطلقوا اسمه على أحد شوارع القاهرة الرئيسية حتى قامت ثورة يوليو فأطاحت بالتمثال، وغيَّرَت اسم الميدان والشارع، وأطلقت عليهما اسم \"طلعت حرب\" رجل الاقتصاد المصري الشهير. ومع ذلك لا يزالُ المصريون يفَضِّلون استعمال اسم (شارع سليمان) ربما وفاء منهم لذكرى رجل كانت له اليدُ الطولى في بناءِ أوَّلِ جَيشٍ مصريٍّ حديثٍ."},{"id":4627,"title":"لالا فاطمة نسومر تقود القبائل في الجزائر في حرب ضد الفرنسيين .","date":["العام الهجري :1276","الشهر القمري : ذي القعدة","العام الميلادي :1860"],"text":"انضَمَّت لالا فاطمة إلى المقاومة، وشاركت بجانب الشريفِ بوبغلة في المقاومة والدفاع عن منطقةِ جرجرة، فقاومت لالا فاطمة نسومر الاستعمارَ الفرنسي مقاومةً عنيفةً أبدت خلالَها شجاعةً وبطولة متفرِّدتين حتى توفِّيَت في سبتمبر 1863م؛ فقد شاركت في صَدِّ هجمات الفرنسيين عن ولاية \"أربعاء ناث إيراثن\" التابعة لولاية تيزي وزو شرقي الجزائر، فقطعت عليهم طريقَ المواصلات؛ ولهذا انضَمَّ إليها عددٌ من قادة الأعراش وشيوخِ القرى، فراحت تناوِشُ جيوش الاحتلال وتهاجِمُها، ويقال إنها هي التي فتكت بالخائِنِ سي الجودي، وأظهرت في إحدى المعارك شجاعةً قوية، وأنقَذَت الشريف بوبغلة الموجود في قرية سومر إثرَ المواجهة الأولى التي وقعت في قرية تزروتس بين قوات الجنرال ميسات والسكان، إلا أن هؤلاء تراجعوا بعد مقاومةٍ عنيفة؛ لغياب تكافؤ القوى عُدَّةً وعَدَدًا، وكان على الجنرال أن يجتازَ نقطتين صعبتين؛ هما: ثشكيرت، وثيري بويران، وفي هذا المكان كانت لالا فاطمة نسومر تقودُ مجموعة من النساء واقفاتٍ على قمة قريبة من مكان المعركة، وهن يحمِّسن الرجال بالزغاريد والنداءات المختلفة؛ مما جعل الثوارَ يستميتون في القتال. شارك الشريف بوبغلة في هذه المعركة وجُرِحَ، فوجد الرعايةَ لدى لالا فاطمة. كما حقَّقت لالا فاطمة انتصاراتٍ أخرى ضد الفرنسيين بنواحي (إيللتي وتحليجت ناث وبورجة وتوريتت موسى، تيزي بوايبر) ممَّا أدى بالسلطات الفرنسية إلى تجنيدِ جَيشٍ معتبر مكوَّن من 45 ألف مقاتل بقيادة الماريشال راندون، وبمؤازرة الماريشال ماك ماهون الذي أتاه بالعتادِ مِن قسطنطينة ليقابِلَ جيش لالا فاطمة الذي لا يتعدى 7000 مقاتل، وعندما احتدمت الحربُ بين الطرفين اتَّبع الفرنسيون أسلوب الإبادة بقتل كل أفراد العائلات دون تمييزٍ ولا شفقةٍ، وفي 19 ذي القعدة 1273هـ / 11 جولاي 1857م ألقِيَ القبض على لالا فاطمة، فحُكِمَ عليها بالإقامة الجبرية بـ(تورثاثين) بمنطقة العيساوية."},{"id":4628,"title":"تشكيل لجنة أوروبية وعثمانية للتحقيق في حوادث الستين في لبنان .","date":["العام الهجري :1277","الشهر القمري : ربيع الأول","العام الميلادي :1860"],"text":"شُكِّلت لجنةٌ دوليةٌ تمثِّلُ الدول الأوروبية الكبرى: فرنسا وإنجلترا وروسيا والنمسا وبروسيا، برئاسة فؤاد باشا مندوبِ السلطانِ العثماني ووزيرِ خارجيته، مهمَّتُها التحقيقُ في حوادثِ الستين في لبنانِ، والحيلولةُ دون تجدُّدِها، ورأْبُ الصَّدعِ بين طوائفِ جبل لبنان، ووضع نظام جديد لحُكمه. وبعد أن عَقَدت اللجنةُ عِدَّةَ اجتماعات في بيروت والقسطنطينية ودرست خلالَها مختَلِفَ الشؤون، انتهت إلى عدة قرارات، كان أهمَّها: إلغاءُ نظام القائمقاميتين، ووضعُ نظامين لحكم جبل لبنان تألَّفَ أحدهما من 47 مادة، والثاني من 17 مادة، ثم رفعت اللجنة الأمرَ إلى الباب العالي وسُفَراء الدول الكبرى الخمس في الأستانة للدراسة وإقرار الأصلَحِ."},{"id":4629,"title":"وقعة الطبعة -سنة الطبعة- على العجمان .","date":["العام الهجري :1277","الشهر القمري : شعبان","العام الميلادي :1861"],"text":"جرت الوقعةُ الكبرى على العجمان، وذلك أنَّ العجمان بعد وقعةِ الصبيحة انتَزَحوا إلى الشمال ونزلوا إلى الجهراءِ في الكويت؛ وذلك ليبتعدوا عن عبدِ الله الفيصل الذي ما زال يطارِدُهم لإزالة شَرِّهم. وفي شهر شعبان خرج عبد الله من الرياض وانضَمَّ إليه سبيع ومطير وبنو هاجر، فحاصروهم في موقعٍ خطيرٍ قريبٍ مِن البحر في منطقة الجهراء فتراجعت قواتُهم تجاهَ البحرِ، فنشبت أرجُلُ جيادهم في الرَّملِ والطين وغرق بعضُها، فسُمِّيَت بوقعة الطبعة أو سنة الطبعة، فهلك منهم خلقٌ كثيرٌ غرقًا غيرَ مَن قُتِل منهم في المعركةِ."},{"id":4630,"title":"وفاة الأمير عبد العزيز المحمد أبو العليان أمير بريدة  .","date":["العام الهجري :1277","الشهر القمري : رمضان","العام الميلادي :1861"],"text":"هو الأمير عبد العزيز بن محمد بن عبد الله بن حسن آل أبو عليان، وينتمي إلى العناقر من بني سعدِ بنِ زيد مناة بن بني تميم، أميرُ برُيدة وكانت مدة إمارته 34 سنة من عام 1243هـ إلى 1277هـ، وقد اشتهر بالشجاعةِ والطموحِ الكبير، جَدُّه هو عبد الله بن حسن كان أميرًا على القصيم. عندما عَزَل الإمام تركي بن عبد الله الأميرَ محمد بن علي الشاعر عن إمارة بُرَيدة جعل مكانَه عبد العزيز المحمد أبو عليان، ثمَّ لَمَّا بلغ الإمام تركي ما يَريبُه من محمد بن علي الشاعر أرسل إليه وجعله عنده في الرياضِ ولم يأذن له بالعودةِ للقصيمِ حتى قَوِيَ أمر عبد العزيز بن محمد وقَوِيَت شوكته في بُريدة. وظل عبد العزيز المحمد أميرًا على بريدة كذلك في عهد فيصل، لكنه كثيرًا ما يخرجُ على طاعة الإمام ويتآمر مع خصوم الإمام، فعُزل أكثَرَ مِن مرة من إمارةِ بريدةَ، ثمَّ أعيدَ إليها إلى أن قُتِلَ هذه السنة عندما عزم عبد الله بن فيصل التخلصَ منه قَصَد بريدة يريد القبضَ عليه، فلما بلغه خبَرُ قدوم عبد الله هرب من بُرَيدة ومعه أولاده، فأرسل عبد الله خلْفَهم سريَّةً مع أخيه محمد، فلم يستطع اللَّحاقَ به؛ لأنَّ جيشه الذي أتى عليه قد كلَّ. وجاء مهنا الصالح الذي ينتظِرُ هذه الفرصة فأعطاهم جيشًا قويًّا، فركبوا خلف عبد العزيز، وأدركوه بالشقيقة فقَتَلوه وقتلوا معه أولاده حجيلان، وتركي، وعليًّا وخدَّامهم، ورجعوا. وكان عبد الله بن عبد العزيز المحمد مع عبد الله الفيصل في غزوته، فلما عَلِمَ بالسرية التي أُرسِلَت للقبض على أبيه هرب واختفى في أحد الجبال، فوجدوه وأرسلوه إلى القطيف، وهناك مات أو قُتِل، وأرسل عبد الله إلى أبيه يخبِرُه بمقتل عبد العزيز وأولاده ويطلُبُ أن يرسِلَ إلى بريدة أميرًا على نظَرِه، ثم قام عبد الله الفيصل وهدم بيوتَ عبد العزيز المحمد وأولاده وأعوانه. ثم أرسل الإمامُ فيصل عبدَ الرحمن بن إبراهيم أميرًا في بُريدة."},{"id":4631,"title":"تشكيل الدولة العثمانية لواء ذي استقلال ذاتي في جبال لبنان .","date":["العام الهجري :1277","الشهر القمري : ذي القعدة","العام الميلادي :1861"],"text":"شكَّلت الدولةُ العثمانية لواءً له استقلالٌ ذاتيٌّ في جبال لبنان، وكان مركزُه \"دير القمر\"، وبلغت مساحته 3100 كم2، وكان يقطنُه النصارى، وظَلَّ الاستقلال الذاتي لهذا اللواء لمدة 53 عامًا حتى سنة 1914م."},{"id":4632,"title":"وفاة السلطان العثماني عبد المجيد الأول وتولي أخيه عبد العزيز .","date":["العام الهجري :1277","الشهر القمري : ذي الحجة","العام الميلادي :1861"],"text":"هو الخليفةُ العثماني عبد المجيد الأول بن محمود الثاني بن عبد الحميد الأول بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني. كان السلطانُ عبد المجيد الأول ضعيفَ البنية شديدَ الذكاء، واقعيًّا ورحيمًا، وهو من أجلِّ سلاطين آل عثمان قدْرًا، تولَّى الحُكمَ بعد وفاة والِدِه السلطان محمود الثاني سنة 1839م، وكان عمرُه دون الثامنة عشرة، فكان صِغَرُ سِنِّه هذا فرصةً لبعض الوزراء التغريبيين لإكمال ما بدأه والدُه الراحل من إصلاحاتٍ على الطريقة الأوروبية، والتمادي في استحداثِ الوسائل الغربية، ومن هؤلاء الوزراء الذين ظهروا في ثيابِ المصلحين ومُسُوح الصادقين (مصطفى رشيد باشا) الذي كان سفيرًا للدولة في (لندن) و (باريس). أحب السلطان عبد المجيد الإصلاحَ فأدخل التنظيماتِ الحديثة، ورَغِب في تطبيقها في الحال، كما أدخل إصلاحاتٍ جمَّةً في الجيوش العثمانية. وترقَّت في أيامه العلومُ والمعارف، واتَّسَعت دائرةُ التجارة، وشُيِّدت الكثيرُ من المباني الفاخرة، ومُدَّت في عهده أسلاكُ الهاتف وقضبان السكك الحديدية, ويعتبر السلطانُ عبد المجيد أوَّلَ سلطان عثماني يُضفي على حركة تغريب الدولة العثمانية صِفةَ الرسمية؛ إذ إنَه أمر بتبني الدولة لهذه الحركةِ، وأمر بإصدار فرمانَي التنظيمات عامي 1854م، 1856م، وبهما بدأ في الدولة العثمانية ما سُمِّيَ بعهد التنظيمات، وهو اصطلاح يعني تنظيم شؤون الدولة وَفْقَ المنهج الغربي، وبهذين الفرمانينِ تم استبعادُ العمل بالشريعةِ الإسلامية، وبدأت الدولةُ في التقنين وإقامة المؤسسات، فكان السلطان عبد المجيد خاضِعًا لتأثير وزيره \"رشيد باشا\" الذي وجَدَ في الغرب مَثَله وفي الماسونية فلسفَتَه، ورشيد باشا هو الذي أعدَّ الجيلَ التالي له من الوزراءِ ورجال الدولة مثل مدحت باشا. توفِّيَ السلطان عبد المجيد في السابع عشر من ذي الحجة من هذا العام بعد أن دام في الحُكم اثنين وعشرين سنة ونصفًا تقريبًا، وتولى بعده أخوه عبد العزيز خلفًا له."},{"id":4633,"title":"وفاة أحمد الباي سلطان تونس .","date":["العام الهجري :1278","الشهر القمري : رمضان","العام الميلادي :1862"],"text":"هو أحمدُ الباي سلطان تونس، وكان قد حاول أن يقيمَ بتونس نهضةً إصلاحية محاولًا الاستفادةَ من تجربة محمد علي باشا بمصرَ."},{"id":4634,"title":"تأسيس أول بلدية عربية للقدس .","date":["العام الهجري :1279","العام الميلادي :1862"],"text":"تمَّ تأسيسُ أوَّلِ بلدية في القُدسِ بشَكلٍ شِبهِ منظَّم، وكانت عبارةً عن مجلسٍ محليٍّ ذي سلطة محدودة وميزانية لا تتعدى (500) جنيه ذهبي في السنة، ثم صدر قانون الأقاليم (1864) الذي يتضَمَّنُ أحكامًا محدودة عن تشكيلِ البلديات. وقد بَقِيَ الوضع على ما هو عليه حتى عام (1918) حين دخل الإنجليز المدينة، وأصبحت البلديةُ تدارُ من قِبَلِ أربعةِ أشخاص من العرب، واثنين من اليهود، وفي عام 1948م وبعد الاستيلاء الصهيوني على الشطرِ الغربي من المدينة أصبحت هناك أمانةُ القدس العربية مسؤولةً عن الشطر الشرقي للمدينة حتى عام 1967، حيث تم حينها الاستيلاءُ على كافة المدينة عَقِبَ حرب حزيران، فحُلَّ مجلِسُ أمانة القدس، وتم ضمُّ الجهاز البلدي إلى بلدية القدس الإسرائيلية، واستُبعِدَ أمين القدس المنتَخَب."},{"id":4635,"title":"وفاة الإمام محمد شامل الداغستاني  .","date":["العام الهجري :1279","العام الميلادي :1862"],"text":"هو الإمامُ محمد شامل الداغستاني قائدٌ سياسي في شمال القوقاز وأحدُ أشهر المقاومين للوجودِ الروسي في بلاد القوقاز، ولِدَ عام 1797م في قرية غيمري، الداغستانية, وهو ثالِثُ أئمة الشيشان وداغستان من 1834 – 1859 م لقِّبَ بأسد القفقاس، وصقر الجبال. قاد المقاومةَ ضِدَّ الروس خلالَ حروب القوقاز حين اختاره المريدون بعد وفاةِ حمزة بيه في عام 1834م، فأعاد شامِلٌ تنظيمَ جيش ِالمريدين على نمطِ أعدائه الكوزاك بشكلٍ أشبه إلى التنسيق الاتحادي الحديث، فاستمَرَّت المقاومة بقيادة شامل في مسلسلٍ متوالي الحلقات بأسلوبِ حَربِ العصابات والكَرِّ والفَرِّ، إلى أن أسَرَه الروس في وقتٍ كان قد تخطَّى من عمره الستين سنةً، فقد أسَروه في حربٍ خاطفة خطَّطَ لها القائدُ الروسي بارياتسكي، فنُقِلَ الإمام شامل في رحلةٍ طويلة إلى موسكو في موكبٍ بدا وكأنَّه استعراضٌ عسكريٌّ بالبطل الذي سقط أخيرًا، وظل شامِلٌ في موسكو إلى عام 1869 حين أخلِيَ سبيلُه بشروط أهمُّها الجلاءُ عن البلادِ. فذهب إلى مكَّةَ لأداء فريضة الحجِّ، حيث توفِّيَ في المدينة ودُفِن بالبقيع."},{"id":4636,"title":"محاولة الصلح بين أهل عنيزة وعبد الله بن فيصل .","date":["العام الهجري :1279","العام الميلادي :1862"],"text":"طالت الحربُ مع أهل عنيزة بعد قَتْلِ أميرهم عبد العزيز المحمد أبو العليان وأثناء حصارِ عُنيزة حاول الأميرُ طلال بن رشيد أن يعقِدَ صلحًا بين عبد الله وأهل عنيزة، فأرسل سرًّا إلى الأمير عبد الله اليحيى السليم وزامل العبد الله أنَّ الإمام لا يكره الصلحَ ووَقْفَ القتالِ إذا كان طلبُ الصلح منكم، فأنابوه عنهم وقالو له إنَّك مفوَّضٌ مِن قِبَلِنا، فعرض على عبد الله رغبةَ أهل عنيزة في الصلحِ، فقال: عبد الله إذا قَبِلوا بشروطنا قَبِلْنا منهم الطاعةَ، فحضر عنده زامل العبد الله وأغلظ له في القَولِ لكَثرةِ نقضِهم العهدَ، ثم فرض عليهم أموالًا وسلاحًا كثيرًا، فتوسط لهم الأمير طلال فأسقط عبد الله جزءًا منها، فقبل زامل فأحضر أهل عنيزة المالَ والسلاح وتمت البيعةُ، وضَمِنَ الأمير طلال الوفاءَ بالعهدِ."},{"id":4637,"title":"وفاة السلطان محمد بهادر آخر سلاطين الدولة الإسلامية بالهند .","date":["العام الهجري :1279","الشهر القمري : جمادى الأولى","العام الميلادي :1862"],"text":"هو السُّلطان أبو الظفر سِراجُ الدين محمد بهادر شاه الثاني، آخِرُ سلاطين الدولة الإسلامية في الهند، وقد أصبح إمبراطورًا عند وفاة والده سنة 1838هـ وشهِدَت فترةُ حكمه الثورةَ الهندية التي كادت تقضي على الإنجليز وتُخرِجُهم من الهند، وكان الهنودُ قد اختاروه قائدًا لهم على الرغم من كبر سنِّه، لكِنَّ الثورة لم تنجَحْ؛ حيث قبض الإنجليزُ على بهادر شاه، ونفوه خارج الهند. وبنفيه انتهى الحكمُ الإسلامي في الهند. كان  الحكم الإسلامي قد استقَرَّ في الهند ورسخت أقدامُه وقامت له دولةٌ منذ أن بدأ السلطانُ المجاهد محمود الغزنوي فتوحاتِه العظيمة في الهند سنة (392هـ - 1001م)، وامتدَّ لأكثر من ثمانية قرون، تعاقَبَت في أثنائها الدولُ والأسر الحاكمة، ونَعِم الناسُ بالأمن والسلام، والعدل والمساواة، وازدهرت الحضارةُ على النحو الذي لا تزالُ آثارُها الباقيةُ في الهند تخطفُ الأبصار وتبهر العقولَ والألبابَ، كانت إمبراطوريةُ المغول في الهند آخِرَ دولة حكمت الهند، ودام سلطانُها نحو ثلاثة قرون، منذ أن أسَّسَها ظهير الدين بابر في النصفِ الأول من القرن العاشر الهجري، وتوالى على حُكمِها عددٌ من السلاطين العِظامِ، يأتي في مقدِّمتِهم: السلطان \"جلال الدين أكبر\" الذي نهضَ بالدولة نهضةً عظيمة، ونجح في تنظيمِ حُكومةٍ أجمع المؤرخون على دقَّتِها وقوتها. والسلطانُ شاه جهان الذي اشتهر ببنائِه مقبرةَ تاج محل لزوجتِه ممتاز محل. والسلطانُ أورنك زيب الذي تمسَّك بالسُّنَّة وأشرف على الموسوعةِ المعروفة بالفتاوى الهندية أو العالمكيرية، نسبةً إلى \"عالمكير\" وهو اسمٌ اشتهر به في الهند."},{"id":4638,"title":"زيارة السلطان العثماني عبد العزيز لمصر .","date":["العام الهجري :1279","الشهر القمري : شوال","العام الميلادي :1863"],"text":"قام السلطان العثماني عبد العزيز بزيارة لمصر، وتعَدُّ زيارته هذه هي الزيارةَ الثانيةَ لسلاطين الدولة العثمانية لمصر؛ حيث كانت الأولى في عهد السلطان سليم الأول عند فتح مِصرَ، أي: قبل 345 عامًا."},{"id":4639,"title":"إعلان الميرزا حسين علي دعوته البهائية .","date":["العام الهجري :1279","الشهر القمري : ذي القعدة","العام الميلادي :1863"],"text":"أعلن الميرزا حسين علي دعوتَه البهائية، وأنَّه الوريثُ الحقيقي للباب علي بن محمد الشيرازي مؤسِّس فرقة البابية الضالة. وفي عكَّا بذل البهاءُ جُهدًا كبيرًا في نشر دعوتِه وكسْبِ الأنصار والأتباع، فأعلن حقيقةَ شَخصِه، وأبطل ما كان يدَّعيه \"الباب\" حتى انسلخ هو وأتباعُه من شريعة الباب، ولم يبقَ مِن كلامه إلا ما كان فيه إشارةٌ أو إيماءة تبشِّرُ بمَقدَم البهاء، ولم يكتفِ بادعاء النبوة، بل تجاوزها إلى ادِّعاء الألوهية، وأنه القيومُ الذي سيبقى ويخلد، وأنه روح الله، وهو الذي بعث الأنبياءَ والرسُل، وأوحى بالأديان، وزعم أنَّ الباب لم يكن إلا نبيًّا مهمته التبشير بظهوره. وجعل البهاء الصلاةَ ثلاث مرات: صبحًا وظهرًا ومساء، في كل مرة ثلاث ركعات، وأبطل الصلاةَ في جماعة إلا في الصلاة على الميت، وقصَر الوضوء على غَسلِ الوجه واليدين وتلاوة دعاءين قصيرين. وحدَّد شهر الصوم بتسعة عشر يومًا من كلِّ عام الذي هو عنده تسعة عشر شهرًا. ويكون الصوم في شهر \"العلاء\" (21:2 مارس)، وهذا الشهر هو آخر الشهور البهائية. وجعل الحجَّ إلى مقامه في \"عكا\"، وهو واجب على الرجال دون النساء، وليس له زمنٌ معين أو كيفية محدَّدة لأدائه، كما غيَّر في أحكام الزواج والمواريث، وبدَّل في أحكام العقوبات، وفرض نوعًا من الضرائب على أتباعِه لتنظيم شؤونهم تقَدَّر بنسبة (19%) من رأسِ المال وتُدفَعُ مرة واحدة فقط. وكان من تعاليم \"البهاء\" إسقاطُ تشريع الجهاد وتحريمُ الحرب تحريمًا تامًّا، ومصادرة الحُرِّيات إلا حرية الاستماع إلى تعاليم البهاء!!"},{"id":4640,"title":"حصول الخديوي إسماعيل على فرمان (قانون) مصر من الدولة العثمانية .","date":["العام الهجري :1279","الشهر القمري : ذي الحجة","العام الميلادي :1863"],"text":"نجح الخديوي إسماعيل في الحُصولِ على فرمان (قانون) من الدولةِ العثمانية عُرِفَ بـ\"فرمان مصر\" يقضي بانتقال ولاية مصرَ مِن الأبِ إلى الابنِ الأكبر، وهو ما مهَّد الطريق لمحمد توفيق باشا ابن إسماعيل لتولِّي الحُكم في مِصرَ."},{"id":4641,"title":"وفاة لالا فاطمة نسومر .","date":["العام الهجري :1280","العام الميلادي :1863"],"text":"هي لالا فاطمة نسومر، وتسمى أيضًا لالة فاطمة، واسمُها الحقيقي هو (فاطمة سيد أحمد محمد بن عيسى)، و\"لالة أو لالا\" هي لفظةُ توقير أمازيغية تعني \"السيدة\" وهي من أبرز وجوه المقاومة الشعبية الجزائرية في بدايات الغزو الفرنسي للجزائر. وُلِدَت لالا فاطمة نسومر بقريةِ ورجة قرب عين الحمام سنة 1246هـ /1830م في أسرةٍ تنتمي إلى الطريقة الرحمانية، وأبوها محمد بن عيسى مقدَّم زاوية الشيخ سيدي أحمد أومزيان شيخ الطريقة الرحمانية. وأمُّها لالا خديجة. نشأت لالا فاطمة نشأةً دينية وبعد وفاةِ أبيها وجدت نفسَها وحيدةً منعزلة عن الناس فتركت مسقَطَ رأسها وتوجَّهت إلى قرية سومر؛ حيث يقطنُ أخوها الأكبر سي الطاهر، وإلى هذه القريةِ نُسِبَت. قاومت الاستعمارَ الفرنسي مقاومةً عنيفة أبدت خلالَها شجاعةً وبطولة متفردتين، حتى تمكَّن الفرنسيونَ مِن إلقاء القبض عليها في وادي يسر، فحُكِمَ عليها بالإقامة الجبرية بـ(تورثاثين) بمنطقة العيساوية التي تبعد15 كم عن مدينة تابلاط التي تحتَضِنُ الزاوية العيساوية التي كان يديرها \"الباي محي الدين\" كسجن، فاختارت لالا فاطمة لنفسِها هذه الزاوية للتعبُّدِ والدراسة، حتى مرضت وانتقلت إلى جوار ربِّها دون أن يتجاوزَ عُمرُها 33 سنة, ويقال إنها ماتت مسمومة في فرنسا، ثم دُفِنَت في مقبرة سيدي عبد الله قبل أن يتمَّ نَقلُ رُفاتها إلى مربع الشهداء بمقبرة العالية سنة 1995م."},{"id":4642,"title":"ظهور التلمود مطبوعًا في وارسو ببولندا  .","date":["العام الهجري :1280","العام الميلادي :1863"],"text":"ينقَسِمُ التلمود إلى جزئين هامَّين: 1- المشناه Mishnah، وهو الأصل (المتن) 2- جمارا Gamara، وهو شرح المشناه. ومشناه أولُ لائحة قانونية وضعها اليهودُ لأنفسهم بعد التوراة، جمعها يهوذا هاناسي Judah Hanasi فيما بين 190 و200 م، أي: بعد قرن تقريبًا من تدميرِ تيطس الروماني الهيكل. أمَّا جمارا فاثنان: جمارا أورشليم (فلسطين). وجمارا بابل. جمارا أورشليم (أو فلسطين) هو سجِلٌّ للمناقشات التي أجراها حاخامات فلسطين (أو بالأخص علماء مدارس طبرية) لشرح المشناه. ومن الطبعات للمنشاه طبعة Romm التي نُشِرَت في فيلنه نشرت سنة 1927م في مجلَّدين من فرانكفورت، وترجم هربرت داوبي H.Dauby المشناه إلى الإنجليزية مع الحواشي، ونشره في أكسفورد سنة 1933م. وقد طُبِعَ تلمودُ أورشليم لأول مرة في البندقية (فينيسيا) في سنتي 1522 – 1523م، وظهرت الطبعة الثانية في كراكوو Cracom فيما بين 1602 – 1605م، مع بعض الحواشي والشروح. بسبب الاهتمام المتزايد بالتلمود في بولندا أُعيدَ طبع كراكوو في كروتوتشين krotoschin سنة 1886 م، ثم ظهرت طبعة زيتومير Zhitomir. في 1860 – 1867م، ثم طبعتا Piotrkew  سنة 1899 – 1900م) وروم Romm في فيلنا سنة 1922م. وقد طُبِعَت هذه الأخيرة مع بعض الحواشي سنة 1929 باسم تشلوم يروشلمي Tashlum Yerushalmi وظهرت طبعةٌ مصوَّرة لنسخة البندقية (1523) في ليبزيج سنة 1925، تبعته طبعة برلين سنة 1929م. وقد طُبِعَت بعض فصول تلمود بابل سنة 1484، إلا أنَّ الطبعة الكاملة نُشِرَت في البندقية فيما بين 1520 و1523م، أما نسخة بازل Basel فقد خضعت للرقابة الكَنَسية التي حذفت منها أشياءَ كثيرةً. وطبعة أمستردام 1644 – 1648م Romm المنشورة في فيلنا Vina سنة 1886م في عشرين مجلدًا، وهناك طبعة لتلمود بابل نشرها ستراك Strack سنة 1912م عن نسخة أُعِدَّت في ميونيخ في أواسط القرن الرابع عشر. وأول ترجمة كاملة لتلمود بابل نشرتها مطبعة سونكينوSoncino بلندن، وقد ترجم إبراهام كوهين كتابَ براخوت Berachoth إلى الإنجليزية سنة 1921م، وظهرت عدة كتب تتناول ملخص تلمود بابل باللغات الأخرى."},{"id":4643,"title":"صدور قانون التصفية بمصر .","date":["العام الهجري :1280","العام الميلادي :1863"],"text":"هو قانونٌ أصدرَتْه وزارة رياض باشا، في عهدِ الخديوي توفيق، ونصَّ على تخصيص أكثَرَ مِن نصف إيرادات مصر السنوية لتسديدِ الديون لصالح الدائنين الأجانب. وكانت نتائجُ قانون التصفية: (أ) زيادةُ التدخُّل الأجنبي (ب) سوءُ الأحوال الاقتصاديةِ في البلاد."},{"id":4644,"title":"تنازل الدولة العثمانية عن بناء القلاع والحصون بأراضي إمارة الجبل الأسود .","date":["العام الهجري :1280","الشهر القمري : رمضان","العام الميلادي :1864"],"text":"تنازلت الدولةُ العثمانية عن بناء القلاع بأراضي إمارة الجبَلِ الأسود الواقعة على شاطئ الأدرياتيكي إلى الشمالِ من ألبانيا، وكانت إمارةُ الجبل الأسود خاضعةً لحكم الدولة العثمانية، وأراد أميرُها الاستقلالَ بحُكمِها كما قام بمساعدة ثوَّار إقليم (الهرسك) ضِدَّ الدولة العثمانية التي ما لبث أن تمكَّنَت من القضاء تمامًا على جميع حركات التمَرُّد، وشرعت في بناء عِدَّةِ قلاع وحصون داخِلَ بلاد الجبل الأسود، فتدخَّلت الدولُ الأوربية لِثَنيِ الدولة العثمانية عن هذا الأمر، واضطرَّ السلطان العثماني إزاء ذلك إلى التخلِّي عن بناء هذه الحصونِ."},{"id":4645,"title":"بداية الفتنة بين ابناء الإمام فيصل بن تركي .","date":["العام الهجري :1282","العام الميلادي :1865"],"text":"لم تكن الفتنةُ بين عبد الله وسعود أبناء فيصل بن تركي وليدةَ الساعة بعد وفاة والدهما، بل كانت روحُ التنافس موجودة بينهما من أيام والدهما؛ ولذلك جعل فيصل سعودًا أميرًا على الخَرجِ والأفلاج ومناطق جنوب بلاد العارض، وما أن توفي فيصل حتى ثار سعودٌ على أخيه عبد الله ينازعه في الحكمِ، واتجه إلى عسير ونزل على حكامِها آل عايض يطلب العونَ والمساعدة في حربِه على أخيه بحجَّةِ أنه كان يهينُه ولم يَرْعَ حَقَّه، وحاول عبد الله أن يثني سعودًا عن غرضه، ووعده بأن يلبي له طلبه إذا عاد إلى الرياض، لكِنَّ سعودًا لم ينثنِ عن عزمِه، ولَمَّا لم يجد العون من آل عايض اتجه إلى نجران يستنصِرُ بصاحبها، وهو في الأصل عدو لدعوة الشيخ محمد بن عبد الوهاب، وكذلك عدو لبيت آل سعود، فوعده بالنصرة، كما وقف مع سعود بن فيصل ضِدَّ أخيه عددٌ من القبائل، منهم العجمان، ويعض قبائل بدو الدواسر، وبنو مرة، وبدو نجران وأميرها الذي ساعده بالمال. وقد حَذَّر علماءُ أئمة الدعوة من هذه الفتنةِ، وأصدروا الفتاوى وبيَّنوا للعامَّةِ والخاصة بغيَ سعود على أخيه عبد الله، ومنها ما كتبه الشيخ عبد الرحمن بن حسن آل الشيخ: \"بسم الله الرحمن الرحيم، من عبد الرحمن بن حسن إلى من يصل إليه من الإخوانِ، سلامٌ عليكم ورحمة الله وبركاته. وبعد: تفهمون أنَّ الجماعةَ فرضٌ على أهل الإسلام، وعلى من دان بالإسلامِ، كما قال تعالى: {وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا} [آل عمران: 103] ولا تحصل الجماعةُ إلا بالسمع والطاعة لِمَن ولاه الله أمرَ المسلمين، وفي الحديث الصحيح عن العِرباضِ بن ساريةَ، قال: وعَظَنا رسولُ الله صلى الله عليه وسلم موعظةً وَجِلَت منها القلوب، وذَرَفت منها العيونُ،.... الحديث، وقد جمع الله أوائِلَ الأمة على نبيه صلى الله عليه وسلم، وذلك بسبب الجهاد، وكذلك الخلفاء، رد الله بهم إلى الجماعةِ مَن خرج، وفتح الله لهم الفتوحَ، وجمع الله الناسَ عليهم، وتفهمون أنَّ الله سبحانه وتعالى جمعكم على إمامِكم عبد الله بن فيصل بعد وفاة والده فيصل، فالذي بايع بايعَ وهم الأكثرون، والذين لم يبايعوا بايعَ لهم كبارُهم، واجتمع عليه أهلُ نجدٍ باديهم وحاضِرُهم، وسمعوا وأطاعوا، ولا اختلف عليه أحدٌ منهم، حتى سعود بن فيصل، بايع أخاه وهو ما صار له مدخال في أمرِ المسلمين، لا في حياة والده ولا بعده، ولا التفت له أحدٌ من المسلمين. ونقَضَ البيعة، وتبيَّنَ لكم أمرُه أنه ساعٍ في شَقِّ العصا، واختلافِ المسلمين على إمامهم، وساعٍ في نقض بيعةِ الإمام، وقد قال تعالى: {وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ وَلا تَنْقُضُوا الْأَيْمَانَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ اللَّهَ يَعْلَمُ مَا تَفْعَلُونَ وَلا تَكُونُوا كَالَّتِي نَقَضَتْ غَزْلَهَا مِنْ بَعْدِ قُوَّةٍ أَنْكَاثًا تَتَّخِذُونَ أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ أَنْ تَكُونَ أُمَّةٌ هِيَ أَرْبَى مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ اللَّهُ بِهِ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ الْقِيَامَةِ مَا كُنْتُمْ فِيهِ تَخْتَلِفُونَ} [النحل: 91،92] وسعى سعودٌ في ثلاثة أمور كُلُّها مُنكَرة: نَقَض البيعةَ بنفسِه، وفارق الجماعةَ، ودعا الناس إلى نقضِ بيعة الإمام، فعلى هذا يجِبُ قتالُه وقِتالُ من أعانه\"."},{"id":4646,"title":"وفاة الإمام فيصل بن تركي بن عبد الله  .","date":["العام الهجري :1282","الشهر القمري : رجب","العام الميلادي :1865"],"text":"هو الإمامُ فيصل بن تركي بن عبد الله بن محمد بن سعود بن محمد بن مقرن، أحَدُ حكَّامِ الدولة السعودية الثانيةِ، وكان إمامًا شجاعًا حازمًا، عُرِف بحسن التدبير والعَدلِ في الرعيَّة، كان مِن ضمنِ مَن نفاهم إبراهيم باشا لمصر بعد تدميرِ الدرعية، وتمكَّن فيصل من مغادرة مصر والعودة إلى نجد عام 1242هـ وأصبح ساعِدَ والده الأيمنَ في توطيد دعائم الدولة وتوسيع رقعتها. ثم وليَ الحكم بعد مقتَلِ أبيه سنة 1249هـ، إلى أن نفِيَ إلى مصر مرة ثانية سنة 1254وبقي فيها إلى أن غادرها للمرَّة الثانية وعاد إلى نجدٍ، وتمكَّن من انتزاع الحُكمِ من عبد الله بن ثنيان عام 1259 واستطاع أن يُخضِعَ البلادَ التي كانت تحت حكم والده ويصِلَ إلى عمان وقطر والبحرين وأطراف الكويت، وفي عهده برزت مشكلةُ القصيم التي كان النزاعُ فيها بين أمراءِ القصيم على الحُكمِ مِن جهةٍ، واختلافِهم مع الإمامِ فيصل من جهة أخرى، وخروجهم عن طاعته أكثَرَ مِن مرة؛ ممَّا أدى إلى نشوبِ حَربٍ مستَمرَّة معهم معظمَ فترة حكم الإمام فيصل، وكان غالب من يقود الحربَ ضِدَّهم عبد الله بن فيصل الذي تولى معظَمَ مقاليد الحكم في آخر عهد والده، خاصةً بعد أن ضَعُف بصر والده. توفِّيَ الإمام فيصل في الرياض وترك أربعةً من الأبناء الذكور، هم: عبد الله وليُّ عهده، ومحمد، وسعود، وعبد الرحمن، فتولى بعد وفاتِه ابنه عبد الله, وبموتِ فيصل بدأ الصراعُ بين أولاده على السلطةِ، فنشبت بينهم حروبٌ دامية أضعفت الأسرةَ, وأدَّت إلى سقوط دولتِهم على يدِ ابنِ رشيد حاكِمِ حائل سنة 1309هـ."},{"id":4647,"title":"بريطانيا تسيطر على إمارات الخليج العربي .","date":["العام الهجري :1283","العام الميلادي :1866"],"text":"استطاعت بريطانيا أن تثبِّت قَدَمَها في الخليج العربي عمومًا، بل أصبحت تَعُدُّ نفسَها وصيةً على الخليج، فأصبحت تتدخَّلُ أيضًا في حل النزاعات القائمة بين الولايات في الخليج العربي، فلمَّا حصلت مشاكِلُ بين أتباع الشيخ محمد بن عبد الوهاب وبين ثُويني حاكم مسقط، وهاجم أتباعُ الشيخ محمد بن عبد الوهاب مسقَطَ طلَبَ ثويني المدافِعَ والمعونات المالية من الإنجليز، خرجت السفن الإنجليزية من الهند إلى مسقط، وكان أتباعُ الشيخ في البريمي منطقتهم الاستراتيجية التي ينطلِقونَ منها في هجومِهم على حكومةِ مَسقَط، وكان البريطانيون قد استطاعوا تدميرَ الحِصنِ في عجمان، ولَمَّا توفي الإمام فيصل بن تركي في هذه الفترة قامت السفينةُ البريطانية هاي فلاير بقَصفِ ميناء الدَّمَّام وقَصَفَت القلعةَ، ولكِنَّ العملية باءت بالفشل عمومًا، وحاولت بريطانيا إثارةَ المشيخات العربية على أتباعِ الشيخ محمد، وخاصةً المقيم البريطاني الذي كان يُرغم حاكِمَ مسقط على استئنافِ الصراعِ معهم، وطلب مساعدةَ حاكِمِ البحرين لمسقط في محاصرةِ القطيف."},{"id":4648,"title":"وفاة الأمير طلال ابن رشيد .","date":["العام الهجري :1283","العام الميلادي :1866"],"text":"هو الأميرُ طلال بن عبد الله العلي الرشيدي الشمري، ثاني حُكَّام إمارة حائِل، فقد خَلَف أباه بشكلٍ سلِسٍ وبموافقة عمِّه عبيد بن عبد الله الذي كان المرشَّحَ لخلافة أخيه عبد الله؛ إذ كان يُتوقَّعُ أن يتولى عبيد بن عبد الله أخو عبد الله وعمُّ طلال: حُكمَ حائل بعد وفاة الأمير عبد الله. فقد كان عُبيد المؤسِّسَ الثاني للدولة، ولكِنَّ عبيدًا رشَّح طلالًا للحكم بعد وفاة عبد الله، ووافق جماعةَ حائل مواطِنوها على تسلُّم طلالٍ للحكم، وفي عهده بدأت حائل تنعَمُ بفترة رخاءٍ؛ فقد أدخل كثيرًا من التحسينات على حُصون المدينة، وبنى المسجِدَ الجامع والسُّوقَ، وخطط الحدائِقَ الجميلة. وأراد أن ينهَضَ بالتجارة والصناعة، فاستحضر التجَّار من البصرة وواسط وغيرها من المدن، والصُّنَّاعَ من المدينة واليمن ومصر وتركيا، ومنحهم المحلاتِ والأراضيَ، ودخل في علاقاتٍ تجارية مع مدن أخرى من بلاد العرب وفارس، وسَيَّرَ قوافل من قوَّاتِه لحفظ أمن الطرق التجارية التي تمرُّ بمنطقته. أصيب بمرض مزمنٍ في آخر أيامِ حياته مات على أثرِه، وقيل إنَّه مات منتحرًا بعد أن حكم الجبل على مدى عقدين من الزمن، كانت فترة رخاء وسلام عامٍّ، ما جعله يحظى بمحبَّة شعبه بشكل كبير واستثنائي، وخلفه في حكمِ حائل أخوه متعب بن عبد الله."},{"id":4649,"title":"وفاة الشيخ عبد الله بن عبد الرحمن أبا بُطَيْن .","date":["العام الهجري :1283","العام الميلادي :1866"],"text":"هو الإمامُ العلَّامة الفقيه الشيخ عبد الله بن عبد الرحمن بن عبد العزيز بن عبد الرحمن بن عبد الله بن سلطان بن خميس، الملقَّب كأسلافه أبا بُطَيْن -بضم الباء وفتح الطاء وسكون الياء- من عوائل قحطان، العائذي نسبًا، الحنبلي مذهبًا، النجدي بلدًا، فقيه الديار النجديَّة في عصرِه، وإمامٌ من أئمة العلم في زمنه, ولِدَ الشيخ في بلدة الروضة من بلدان سدير، لعشر بقين من ذي القعدة سنة 1194هـ, ونشأ بها وقرأ على عالمها محمد بن الحاج عبد الله بن طراد الدوسري الحنبلي، فمَهَر في الفقه، ثم رحل إلى شقراء عاصمةِ الوشم بنجد واستوطنها، وقرأ على قاضيها الشيخ العلامة عبد العزيز بن عبد الله الحُصين تلميذِ شيخ الإسلام محمد بن عبد الوهاب، قرأ عليه في التفسير والحديث والفِقهِ وأصول الدين، حتى برع في ذلك كله، وأخذ عن العلَّامة أحمد بن حسن بن رشيد العفالق الأحسائي الحنبلي، وعن الشيخ العلامة حمد بن ناصر بن عثمان بن معمر التميمي. رحل إلى الشام، ثمَّ عاد في عهد الإمام سعود بن عبد العزيز بن محمد بن سعود، فولَّاه قضاء الطائفِ، وبقي فيها مدة ثم رجع إلى شقراء وصار قاضيًا لها ولجميع بلدان الوشم، ولَمَّا تولى الإمام فيصل الحكمَ رغب إليه أهلُ القصيم أن يبعَثَ إليهم الشيخ أبا بطين قاضيًا لهم ومدرسًا، فبعثه الإمام فيصل وبَقِيَ عندهم إلى سنة 1370هـ حين رجع من عنيزة إلى شقراء، ومكث فيها إلى أن توفي فيها سنة 1383هـ. له \"مجموعة رسائل وفتاوى\" و\"مختصر بدائع الفوائد\" و\"الانتصار للحنابلة\" و\"تأسيس التقديس في كشف شبهات ابن جرجيس\". وقد أخذ عنه العلمَ بالقصيم وشقراء كثيرٌ من طلبة العلم."},{"id":4650,"title":"معركة المعتلا بين أبناء الإمام فيصل .","date":["العام الهجري :1283","العام الميلادي :1866"],"text":"لَمَّا حشد سعودٌ حشوده في الجنوب خرج إلى الرياض، فالتقى مع قوات أخيه عبد الله التي كان يقودها أخوه محمد بن فيصل في معركة المعتلا، وهي أول معركة بين أبناء الإمام فيصل عبد الله وسعود، وقد قُتِلَ فيها عددٌ كبير من الطرفين، وخاصة أتباع سعود، وجُرِحَ فيها سعود جروحًا بليغة، وأصيب في إحدى يديه، فلجأ إلى آلِ مرة في شرق البلاد، وبقي عندها للتداوي حتى بَرِئت جراحُه."},{"id":4651,"title":"تولي الشيخ عبد الله الثاني بن صباح الثاني الحكم في الكويت .","date":["العام الهجري :1283","العام الميلادي :1866"],"text":"تولى الشيخُ عبد الله الثاني بن صباح الثاني بن جابر الأول -من آل صباح، خامس أمراء الكويت- إمارةَ الكويت بعد وفاة أبيه الشيخ صباح الثاني عام 1866، وقد استماله الترك العثمانيون فسَمَّوه قائم مقام في الكويت، وكان للكويت في عهده أسطولٌ من السفن الشراعية الكبيرة، وكانت أهمُّ الأحداث في عهده: (1) هو أول حاكم للكويت يسكُّ عملة كويتية عليها اسم الكويت عام 1866م. (2) في عام الهيلق 1867م تعرضت الكويت إلى مجاعة ففتح الشيخ عبد الله خزائنَه أمام الكويتيين ليرفع عنهم الضائقة. (3) مساعدتُه للدولة العثمانية للاستيلاء على الأحساء؛ حيث تولى الشيخ عبد الله قيادة ثمانين سفينة بحرية كويتية عام 1871م (نزلت بعد ذلك في رأس تنورة) بالإضافة إلى تسيير جيش من البر بقيادة أخيه الشيخ مبارك الصباح."},{"id":4652,"title":"صدور لائحة مجلس شورى النواب في عهد الخديوي إسماعيل .","date":["العام الهجري :1283","الشهر القمري : جمادى الآخرة","العام الميلادي :1866"],"text":"صدرت لائحةُ مجلس شورى النوَّاب في عهد الخديوي إسماعيل، وكان رئيسُ المجلس ووكيلُه هما اللذان يعيِّنُهما الخديوي دونَ أن يكونَ للمجلس رأيٌ في هذا، وكان عددُ أعضاء المجلس لا يزيدُ على خمسة وسبعين عضوًا, وجديرٌ بالذكر أنَّ هذا المجلس كان من بدايات الأخذِ بالنظام النيابي في مصرَ والعالم الإسلامي."},{"id":4653,"title":"سنة الهيلق (الهلاك) .","date":["العام الهجري :1284","العام الميلادي :1867"],"text":"سنة الهيلق، وهي مجاعةٌ حلَّت في الكويت في عهد الشيخ عبد الله الثاني بن صباح الثاني الصباح, والهيلق كَلِمةٌ تعني الهلاك أو الهلك. حيث تعرَّضت الأقاليم المجاورة لإمارة الكويت لجفافٍ هائلٍ لم يكن بالحسبان حتى اضطروا إلى أكلِ ذمامِ البهائم التي تُذبَح, وكانت الكويتُ محصَّنة ولديها إمكانيةٌ لمواجهة مثل هذا الجفاف. فأصبحت الكويتُ الوجهة الرئيسيَّةَ للمنكوبين. وكانت يدُ الخير تنتظِرُهم حيث أمدُّوهم بالمال والطعام والمأوى, وظلَّ بعضهم بالكويت لفترة زوال الجفاف التي دامت ثلاث سنوات، والبعضُ استقَرَّ بالكويت."},{"id":4654,"title":"افتتاح قناة السويس رسميًّا في حفلة حضرها ملوك ورؤساء .","date":["العام الهجري :1286","الشهر القمري : شعبان","العام الميلادي :1869"],"text":"افتُتِحت \"قناة السويس\" -التي تربط بين البحر الأبيض المتوسط والبحر الأحمر- أمامَ الملاحة الدولية، وقد بدأت أعمالُ الحفر في هذه القناة في 24 من إبريل 1859م، وشارك فيها 60 ألف فلاحٍ مصري، وبلغ طول القناة 162.5 كم, وقد دعا الخديوي إسماعيل حاكِمُ مصر أباطرةَ وملوك العالم وقريناتِهم لحضور حفلِ افتتاح قناة السويس، والذى تم في 16 نوفمبر 1869، وقد كان حفلًا أسطوريًّا، روعِيَ فيه الاهتمام بنظافة المدينة، وتمَّ حَثُّ التجار على توريد الخضرواتِ واللحوم والأسماك كبيرة الحجم لبورسعيد لمواجهةِ الطلبات المتزايدة، كما رُوعِيَ إحضار الثلج من القاهرة، كذلك جُهِّزَ عددٌ من السفن لإحضار المدعوين من الإسكندرية لبورسعيد. وكان الخديوي قد طلب من مديري الأقاليمِ أن يُحضُروا عددًا من الأهالي بنسائهم وأطفالهم لحضورِ حَفلِ الافتتاح، فانتشروا على خط القناة من فلاحين ونوبيين وعُربان بملابسهم التقليدية ومما زاد الأمر أبَّهةً اصطفاف الجيشِ والأسطول المصري في ميناء بورسعيد بالإضافة لفيالقه على ضفاف القناة، وأقيمت 3 منصَّات خضراء مكسوَّة بالحرير، خصِّصَت الكبرى للملوك والأمراء، والثانية يمين للعُلَماء والمشايخ، والثالثة يسار خُصِّصَت لرجال الدين النصارى، وقد بلغ عددُ المدعوين من الوجهاء زُهاءَ ستة آلاف مدعو."},{"id":4655,"title":"صدور مرسوم \"كريميو\" الذي يمنح الجنسية الفرنسية لليهود في الجزائر .","date":["العام الهجري :1287","الشهر القمري : رجب","العام الميلادي :1870"],"text":"صدر مرسومُ كريميو الفرنسي الذي يمنح اليهودَ في الجزائر الجنسيَّةَ الفرنسيَّةَ، ويتضمَّنُ في داخله هدفَ توطين العنصر الأوروبي في الجزائر، مع ما ترتَّـب على ذلك من امتيازات وظيفية واجتماعية لم يكن يتمتّـَعُ بها مواطِنوهم المسلمون في ظِلِّ الاحتلالِ الفرنسي."},{"id":4656,"title":"معركة بئر جودة .","date":["العام الهجري :1287","الشهر القمري : رمضان","العام الميلادي :1870"],"text":"بعد معركة المعتلا سنة 1283 عزل عبد الله بن فيصل أميرَ الأحساء محمد السديري بعد أن اتَّهَمه بالضعف في موقِفِه من بعض قبائل العجمان وبني مرة التي أيَّدت سعودًا وعيَّنَ خلفًا له ناصر بن جبر الخالدي، كما أرسل قواتٍ بقيادة أخيه الصغير عبد الرحمن لشرق البلاد لمراقبة تحُّركات سعود ومؤيديه، فانتقل سعود من البريمي إلى البحرين التي ساعده شيخُها بقوات ناوشت الحامية النجديَّةَ في قطر، ثم عزز سعودٌ قواتِه بمساعدة بني خالد والعجمان بعد استمالةِ زعيمِهم راكان بن حثلين، وكان سعود يطمَعُ في السيطرة على المنطقة الشرقيَّة بانتزاعها من يد أخيه عبد الله، فتوجهت قوات سعود إلى الأحساء وخرج لملاقاتهم أمير الأحساء ناصر بن جبر الخالدي المؤيِّد للإمام عبد الله، فالتقى الطرفان في الوجاج، ودارت الحربُ بينهما فكان النصر حليف سعود، وفرَّت قوات ناصر إلى داخل الأحساء، فحاصرها سعود لمدة أربعين يومًا، فأرسل عبد الله قوات من الرياض لِمساعدة حامية الأحساء قواته في الأحساء إلَّا أن هذه النجدات اشتبكت مع قوات سعود في بئر جودة، وكان النصر في المعركة حليفَ سعود، وأسَرَ أخاه محمدًا وسجنه في القطيف، وقُتِلَ فيها 500 جندي من الفريقين، وتمكن سعود من حكم الأحساء التي استسلم أهلُها له بدون عناءٍ، وأصبح سعود سيِّدَ المنطقة الشرقية. وتعتبَرُ معركة بئر جودة بدايةَ النهاية للدولة السعودية الثانية التي بدأت منذ هذه المعركة في الضَّعفِ حتى قضى عليها ابنُ رشيد سنة 1309هـ."},{"id":4657,"title":"حركة محمد المقراني الجهادية في الجزائر .","date":["العام الهجري :1287","الشهر القمري : ذي الحجة","العام الميلادي :1871"],"text":"في الجزائر انطلق محمد المقراني مجاهدًا في سبيل الله ثائرًا على المغتصبين الفرنسيين الصليبيين، مدافعًا عن حقوق العباد، فزحف على بلدة البرج في تاريخ 28 ذي الحجة 1287هـ / 16 آذار 1871م وفي الوقت نفسِه أمر أخاه بو مرزاق بالتحرُّك في منطقة سور الغزلان، وابنَ عمِّه وصهرَه السعيد بن داود بالتحرُّك في منطقة الحضنة وبلاد أولاد نائل، وابنَ عمه الثاني بوزيد بن عبد الرحمن بالزحف إلى البرج مع خمسة عشر ألف مقاتل لدعم الثورة، غير أنه فَشِل في دخول بلدة البرج بعد حصار دام عدة أيام، ثم انتشرت ثورةُ المقراني عبر العديدِ مِن مناطق الشرق الجزائري. إلى أن اغتاله الفرنسيون سنة 1288ه ومع أنَّ ثورته لم تدُمْ كثيرًا لكنها تعتبَرُ من أكبر حركات المقاومة الجزائرية ضِدَّ الفرنسيين؛ إذ تولى قيادتَها بعد مقتل المقراني أخوه أبو مزراق، واشترك فيها أكثر من مائتي ألف مجاهد، وخاضوا أكثر من ثلاثمائة وأربعين معركة، وعمل ضدهم ما يزيد على ثمانمائة ألف مقاتلٍ فرنسي."},{"id":4658,"title":"إنشاء كلية دار العلوم لإحياء اللغة العربية .","date":["العام الهجري :1288","العام الميلادي :1871"],"text":"أمر الخديوي إسماعيلُ باشا وزيرَ معارفه علي باشا مبارك بإنشاء دار العلوم عام 1872م لتصبحَ مؤسَّسةً تنويريَّةً حضارية، وقد أضيفت إلى جامعة القاهرة 1946م. وكانت كلية (دار العلوم) من قَبلُ تسمى (مدرسةَ دار العلوم)، وقد تطوَّرت (دار العلوم) إلى أن أصبحت إحدى المدارس العالية، وظلَّت كذلك إلى أن ضُمَّت لجامعة القاهرة، وأصبحت تسمى (كلية دار العلوم) محتفظةً باسمها التاريخي العزيز، وكلمة (علوم) التي يضمها اسمُ الكلية تَعني العلوم العربية والإسلامية، ودارُ العلوم كليةٌ تخرِّجُ متخصصين في اللغة العربية والأدب العربي والدراسات الإسلامية، ويستطيع المتخرجُ في كلية دار العلوم أن يعمَلَ في ميدان تدريس اللغة العربية والعلوم الإسلامية في مراحِلِ التعليم المختَلِفة، كما يمكِنُه العمل في مجالاتٍ أخرى، مثل الصحافة، والإذاعة المسموعة والمرئية والثقافية وغيرِها."},{"id":4659,"title":"أحوال الأحساء تحت الحكم العثماني .","date":["العام الهجري :1288","العام الميلادي :1871"],"text":"بدت علاماتُ تذمُّر الأهالي من الحُكم التركي؛ لكثرة الضرائب الباهظة التي فُرِضَت عليهم ممَّا جعلهم يفكرون كثيرًا في الثورة على العثمانيين بالإضافة إلى اضطراب الأمن وتدهور التجارة؛ بسبب كثرة الثورات القبلية في المنطقة الممتدَّة في شرق البلاد من الكويت إلى قطر، واعتدائهم على القوافل التجارية بالنَّهبِ والسلب كلما سنحت لهم الفرصُ، وعودة القرصنة في السواحل الشرقية؛ بسبب ضعف سيادة الدولة العثمانية في المنطقة لانشغالها بالحرب مع الروس."},{"id":4660,"title":"حملة عثمانية لضم قطر لحكمها .","date":["العام الهجري :1288","العام الميلادي :1871"],"text":"بعد دُخول العثمانيين الأحساءَ أشار قاسم بن ثاني على نافذ باشا أن يتقدَّم بقواته لاحتلال قطر؛ لأنه كان يخشى امتدادَ سلطة آل خليفة أعوان الإنجليز، فكان لا بدَّ أن يضع بلاده تحت حماية الترك بدلًا من ابتلاعها مِن آل خليفة، أو اللجوء إلى حماية الإنجليز. ومن الأحساء خرجت قوةٌ عسكرية احتلت قطر واتخذت الدوحة مركزًا لها."},{"id":4661,"title":"وفاة الشيخ محمد المقراني .","date":["العام الهجري :1288","الشهر القمري : صفر","العام الميلادي :1871"],"text":"الشيخُ محمد المقراني هو أحدُ قادة الثوراتِ الشعبيَّة الجزائرية بعد الغزو الفرنسيِّ للجزائر عام 1830م. ومحمد المقراني هو ابن أحمد المقراني أحد قواد منطقة مجانة الهضاب العليا، وبعد وفاة الأب عُيِّن مكانَه ابنه محمد المقراني، لكن بلقب منحَتْه إياه السلطات الفرنسية، والذي كان \"باشا آغا\" وامتيازاته أقَلُّ من امتيازات أبيه, تحدر من زعماء سلطنة بني عباس في القرن السادس عشر الميلاد من آخر سلطان حفصي في بجاية، أبو العباس عبد العزيز. وفي سنة 1281هـ قدَّم استقالتَه للسلطات الفرنسية، وفي نفس السنة ثار على الاحتلال الفرنسي، وقاد مقاومةً ضِدَّ الاحتلال الفرنسي، فزحف بجيشه إلى مدينة برج بو عريريج. قُتِل المقراني برصاص جيش الاحتلال الفرنسي؛ إذ باغتوه وهو يصلي برصاصةٍ توفي على إثرها أثناء إحدى المعارك عند وادي سَفلت بالقرب من سور الغزلان، ثم خلفه في قيادة الثورة أخوه أبو مرزاق."},{"id":4662,"title":"معركة \"البرة\" بين الأخوين سعود وعبد الله ابني فيصل بن تركي .","date":["العام الهجري :1288","الشهر القمري : جمادى الأولى","العام الميلادي :1871"],"text":"في محرَّم من هذه السنة بدأ سعود بن فيصل بالزَّحفِ من الأحساء نحو الرياض. وحينما عَلِمَ أخوه عبد الله بن فيصل باقترابه، غادر العاصمةَ متوجهًا إلى قحطان بوادي أعوانه؛ طلبًا للحماية. ودخل سعود بن فيصل الرياضَ بدون قتال، وحكَمَها للمرَّةِ الأولى، ونكل أتباعُه بسكَّانِها جزاءً لموقف أهلها العدائيِّ منه، وكثر الهرج والمرج في منطقة العارض. كتب سعودٌ إلى رؤساء البلدان، فقَدِمَت عليه وفود من مناطق نجد تعلِنُ له البيعةَ والطاعة والولاءَ، كعادتهم لكلِّ مَن دخل الرياضَ. وأمرهم بالتجهُّزِ لمحاربة أخيه عبد الله. تحرك سعود من الرياض في ربيع الأول من هذا العام نحوَ قحطان، وعندهم عبد الله بن فيصل، ثم انتقلوا إلى البرة، بالقُربِ مِن ضرما، حيث التقت قواتُ سعود وحلفاؤه بعبد الله بن فيصل وأتباعه من قحطان، في قتالٍ شديدٍ في السابع من جمادى الأولى من هذه السنة، ودارت الدائرة على عبد الله ومن معه، فانصرف إلى بلدة الرويضة. وقفل سعودٌ راجعًا إلى الرياض."},{"id":4663,"title":"وفاة محمد أمين عالي باشا رئيس الوزراء في الدولة العثمانية .","date":["العام الهجري :1288","الشهر القمري : جمادى الآخرة","العام الميلادي :1871"],"text":"هو محمد أمين عالي باشا، سياسي عثماني، وأحدُ السياسيين البارزين في الإصلاحات السياسية المعروفة باسم التنظيمات التي شهدتها الدولة العثمانية في منتصف القرن التاسع عشر، ولِدَ عالي باشا باسطنبول سنة 1815م، وتمكَّن بفضل إجادته للغة الفرنسية من الالتحاق بالسلك الدبلوماسي العثماني في صَدرِ شبابِه، فعُيِّنَ بدائرة الترجمة، ثم سكرتير السفارة العثمانية في فيينا، ثم منصب وزير الخارجية، ثمَّ عيِّنَ سفيرًا للدولة في لندن، ثم عاد إلى اسطنبول ليصبِحَ وزيرًا للخارجية، ثمَّ شغل منصب الصدر الأعظم خمسَ مرات، وكان عالِمًا ولغويًّا وندًّا قويًّا لمعاصريه من سفراء الدول الأوروبية العظمى آنذاك في الدفاع عن مصالح بلاده. وهو من دهاة الدبلوماسية التركية، وقد وصفته الصحافةُ الأوربية بأنَّه أعظم سياسي في أوروبا. كان عالي باشا سياسيًّا إصلاحيًّا رغم ما كان يتَّسِم به من استبداد بالسلطة، طمح إلى تحويل الدولة العثمانية إلى دولة عصرية، وسعى لذلك طولَ فترة صدارته لجلب التنظيمات الغربية، فقد كان المحرِّكَ الأساسي لفرمان الإصلاحات الذي صدر سنة 1856م، وفي عهده وقَّعَ معاهدةَ باريس -بصفته الصدر الأعظم- التي أنهت حرب القرم. توفِّي عالي باشا رئيس الوزراء في الدولة العثمانية عن عمر يناهز 56 عامًا."},{"id":4664,"title":"حملة عثمانية لضم الأحساء لحكمها  .","date":["العام الهجري :1288","الشهر القمري : رجب","العام الميلادي :1871"],"text":"بعد خروج عبد الله بن فيصل من الرياض وسيطرة أخيه سعود على الحكم فيها، توجه عبد الله لعدد من الجهات طلبًا للمساعدة ضِدَّ أخيه سعود، فاتصل بآل سليم في القصيم، وابن رشيد في حائل، ولَمَّا لم يجد منهم العون أرسل إلى العراق عبد العزيز أبا بُطين ومعه ثلاث رسائل، الأولى لمدحت باشا والي بغداد، والثانية إلى خليل بك والي البصرة، والثالثة إلى السيد محمد الرفاعي نقيب الأشراف، يطلب من الحكومة العثمانية المساعدةَ ضِدَّ أخيه سعود، فاستغل مدحت هذا العرضَ فشجَّع السلطان عبد العزيز بن محمود الثاني على المبادرة بدخول الأحساء قبل أن تدخُلَ تحت النفوذ البريطاني بطلب من سعود بن فيصل، فأذن له السلطان بذلك، فجهز حملة من 5000 جندي بقيادة نافذ باشا واستعان بناصر السعدون رئيس المنتفق وعبد الله بن صباح حاكم الكويت وبني خالد، وأشرَفَ مدحت باشا بنفسه على الحملة للاطمئنان على نجاحِها. أبحرت الحملةُ من البصرة في ربيع الأول من هذا العام بحُجَّة انتزاع الأحساء من سعود بن فيصل وتسليمها لأخيه عبد الله، فوصلت القطيف واحتلَّتها دون مقاومة تذكَرُ، ثم تقدمت إلى الأحساء واحتلتها الحملة في 18 رجب، وأطلق عليها ولاية نجد طمعًا في مد العثمانيين حكمَهم إلى الرياض. بعد أن استتب الوضع للعثمانيين في الأحساء أعلن نافذ باشا أن سياسة الدولة ترمي إلى احتلال الرياض من سعود وأنَّه سيعمل على إعادة عبد الله بن فيصل إلى الحكم برتبةِ (قائم مقام)، وأن الدولة ستعَيِّن القضاة والولاة على المقاطعات، وحَدَّدت الضرائب التي ستُأخذ من الرعايا بالزكاة الشرعية، كما أجرت تنظيماتٍ في القوة العسكرية، فوضعت في الأحساء 5000 جندي نظامي، وأعلن مدحت باشا نهايةَ حكم آل سعود على الأحساء وحنث بوعده لعبد الله بن فيصل!!"},{"id":4665,"title":"ثورة أهل الرياض على سعود بن فيصل وعودة أخيه عبد الله لحكم الرياض  .","date":["العام الهجري :1289","العام الميلادي :1872"],"text":"بعد استقرارِ سعود في الرياض تعرَّضت نجد لمجاعة شديدة، واحتل الأتراك الأحساء ولم يفُوا بوعدهم لعبد الله بن فيصل بتسليمه حكمَ الأحساء، فشجَّعَ هذا والمجاعة أهلَ الرياض في الثورة على سعود بن فيصل، فخرج من الرياض إلى الخرج والدلم، حيث يوجد عددٌ من القبائل المؤيِّدة له، وعيَّنَ أهلُ الرياض عمَّ سعود عبد الله بن تركي، ولَمَّا علم عبد الله بن فيصل بثورة الرياض على أخيه سعود ونما إلى علمه أيضًا أن الأتراك يعملون على نفيه إلى بغداد، خرج من الأحساء إلى الرياض ومعه أخوه محمد وابنه تركي فلمَّا قدم الرياض تنازل له عمُّه عبد الله عن الحكم."},{"id":4666,"title":"عودة سعود بن فيصل لحكم الرياض للمرة الثانية .","date":["العام الهجري :1290","العام الميلادي :1873"],"text":"لَمَّا استقرَّ عبد الله بن فيصل في الحكم في الرياض بعد ثورة أهل الرياض على أخيه سعود، بدأ سعود يحشد أعوانه من مناطق الجنوب الخرج والدلم والأفلاج ووادي الدواسر، وقرَّرَ محاربة أخيه عبد الله الذي أرسل جيشًا بقيادة أخيه محمد للاستيلاء على الخرج مركزِ تحرُّك سعود، لكنَّ قوات سعود تمكَّنَت من هزيمة قوات محمد، وأسرت عمَّ سعود عبد الله بن تركي الذي كان يرافِقُ الحملة، وسجنه حتى توفِّيَ في سجنه، ثم لاحقت قوات سعود فلولَ جيش محمد فحطمَتْها في وقعة الجزعة، وعلى إثر هذه الهزيمة سقطت الرياضُ بيد سعود، وفَرَّ منها عبد الله بن فيصل إلى الكويت وأقام في الصبيحية عند قبائل قحطان المؤيِّدة له، وتقاطرت الوفودُ على الرياض مرة ثانية لتقديم فروض الولاءِ والطاعة لسعود."},{"id":4667,"title":"محاولات سعود بن فيصل استعادة الأحساء من العثمانيين .","date":["العام الهجري :1290","العام الميلادي :1873"],"text":"كان سعود بن فيصل منذ اللحظة الأولى التي تسلَّم فيها حكم الرياض في المرة الأولى سنة 1288هـ قرَّر أن يعمل على استعادة إقليم الأحساء للدولة من العثمانيين، إما عن طريق القوة أو عن طريق السِّلم، فأرسل إلى بلي المقيم البريطاني في الخليج العربي رسالةً يذكُرُ فيها أنه الآن حاكم نجد ومسيطرٌ على الوضع تمامًا، وغرضه أن يحُلَّ السلام بين السكان بعد أن سيطر على ما بحوزة أخيه عبد الله الموالي للترك، وأنَّ علاقته بالحضر والبدو طيبة، وأنه يؤيد بريطانيا في كونها مسؤولةً وحاميةً لمنطقة الساحل، لكِنَّ الإنجليز رأوا ألَّا يتورطوا بين الأتراك والسعوديين؛ لذا بدأ سعود يتدخَّلُ بمفرده، فأرسل عدة إنذارات للترك يدعوهم فيها للانسحابِ مِن القطيف والمنطقة، ولم تلق إنذاراتُه أي تغيير في موقف مدحت باشا، بل على العكس أخذ يساعِدُ عبد الله بن فيصل نكايةً في سعود، ولَمَّا عُزِل مدحت باشا عن ولاية بغداد صادف اتفاقٌ جزئي بين الأخوين فعَمِلا معًا لاستعادة الأحساء، لكن محاولتهما باءت بالفشلِ؛ لعجزهم عن مواجهة القوات التركية لضعف قدراتِهم في تموين قواتِهم، كما أنَّ الخلافات القائمة لم تسمَحْ لهما بالاستمرار في محاربة الأتراك؛ لأنَّ كلًّا منهم يتربَّصُ بالآخر، على الرغم أنَّ القوات التركية لم تكن في وضعٍ حَسَن من حيث الإمكانات العسكرية, وقد تكبَّد الطرفان التركي والسعودي خسائِرَ، خاصَّةً الجيش التركي فتكَت به الأمراض المعدية؛ مِمَّا اضطره للرحيل إلى البصرة وبدأت مفاوضات بين الطرفين أرسل فيها سعود أخاه الصغير عبد الرحمن، لكن المحادثات لم تنجَح."},{"id":4668,"title":"وفاة رفاعة رافع الطهطاوي .","date":["العام الهجري :1290","الشهر القمري : ربيع الآخر","العام الميلادي :1873"],"text":"هو رفاعةُ رافع بن بدوي بن علي الطهطاوي، ولِدَ سنة 1216هـ - 1801م، بطهطا إحدى مدن محافظة سوهاج بصعيد مصر, وقصد القاهرةَ سنة 1223هـ - 1817م، فتعلم في الأزهر, وبعد تخرُّجه منه عام 1824م خدم كإمام في الجيشِ النظامي الجديد, ثم أرسلَته الحكومة المصرية سنة 1826م إمامًا للصلاة والوعظ مع بعثةٍ مِن الشبان أوفدتهم إلى فرنسا لتلقِّي العلوم الحديثة، فدرس الفرنسيَّةَ والجغرافية والتاريخ، وفُتِنَ بالحضارةِ الغربية، وانبهر بقوانين الفرنسيين وسلوكياتهم، فكان عاملًا من عوامل التغريبِ بما حمله من أفكارٍ بعيدة عن تعاليم الإسلامِ!! وقد عاش في باريس خمس سنوات من سنة 1826 إلى سنة 1831م، وهناك تعرَّف على طائفة من المستشرقين من أمثال جوبير Jaubert وجومار Jomard وسلفستر دي ساسي، وكوسان دي يرسيفال. وقد نشر وصف ما رأى وعَلِم من باريس في كتابه \"تخليص الأبريز في تلخيص باريز\"، ولَمَّا عاد إلى مصر ولِّيَ رئاسة الترجمة في المدرسة الطبية، وأنشأ جريدةَ (الوقائع المصرية) وألَّف وترجم عن الفرنسية كتبًا كثيرة، منها (قلائد المفاخر في غرائب عادات الأوائل والأواخر)، وأصله لدبنج Depping، و(المعادن النافعة لفيرارد Ferard، ومبادئ الهندسة، وأنوار توفيق الجليل في تاريخ مصر، وتعريب القانون المدني الفرنساوي، وتاريخ قدماء المصريين، وبداية القدماء وجغرافية ملطبرون Malte - Brun، وجغرافية بلاد الشام رسالة في 53 ورقة، والتعريفات الشافية لمريد الجغرافية، ونجح في إقناع محمد علي بإنشاء مدرسة للمترجمين سُمِّيَت مدرسة الترجمة ثم عُرِفَت فيما بعد بمدرسة الألسُن، ويعتبر الطهطاوي أوَّلَ من أنشأ متحفًا للآثار في تاريخ مصر، وتوفِّيَ بالقاهرةِ."},{"id":4669,"title":"وفاة الشيخ عثمان بن عبد الله بن بشر .","date":["العام الهجري :1290","الشهر القمري : جمادى الآخرة","العام الميلادي :1873"],"text":"هو الشيخُ عثمان بن عبد الله بن عثمان بن أحمد بن بشر, من الحراقيص من قبيلة بني زيد، النجدي مسكنًا، الحنبلي مذهبًا، السلفي اعتقادًا، من رؤساء بني زيد القبيلة المعروفة المشهورة أهل شقراء وغيرها، والمعروف باسم ابن بِشر، وهو مؤرخ وأديب عاصرَ الدولة السعودية الأولى والثانية، ودوَّن أحداثهما في كتابه: (عنوان المجد في تاريخ نجد). ولِدَ ابن بشر في جلاجل سنة 1194هـ ونشأ فيها يتيمًا، وتعلم القراءة والكتابة، وحفظ القرآن، وكان شغوفًا بالعلم محبًّا للعلماء، وتنقل في سدير والوشم والرياض؛ طلبًا للعلم، ثم انتقل إلى الدرعية عام 1224هـ، وفيها تلقى العلمَ عن علمائها، ثم عاد إلى جلاجل وتوفي فيها."},{"id":4670,"title":"توقيع المعاهدة الخاصة بتأسيس الاتحاد الدولي للبريد، في سويسرا .","date":["العام الهجري :1291","الشهر القمري : شعبان","العام الميلادي :1874"],"text":"تمَّ توقيع المعاهدة الخاصة بتأسيس الاتحاد الدولي للبريد، وذلك بعد اجتماعٍ عقدته 22 دولة في مدينة بيرن السويسرية، من بينها 20 دولة أوروبية، بالإضافة إلى الولايات المتحدة ومصر، وكان يسمَّى آنذاك \"الاتحاد العام للبريد\"."},{"id":4671,"title":"وفاة الأمير سعود بن فيصل بن تركي .","date":["العام الهجري :1291","الشهر القمري : ذي الحجة","العام الميلادي :1875"],"text":"هو الأمير سعود بن فيصل بن تركي بن عبد الله آل سعود، ثاني أبناء الإمام فيصل، لقِّبَ بـ (أبو هلا) لكرمِه وكثرة ترحيبِه بالضيف. وقد حكم في الدولة السعودية الثانية من 1288 إلى1291هـ (1871- 1875م) كان أبوه قد ولَّاه أميرًا على الخرج عام 1263هـ/ 1846م واستمرَّ في هذه الإمارة مدةً طويلة، وقد أكسبه ذلك قاعدةً شعبية في تلك المنطقة. أما أخوه عبد الله، الذي يكبرُه في السن، فقد كان أبوه قد عيَّنه وليًّا للعهد، وكان ساعِدَه الأيمن في قيادة المعارك وإدارة شؤون البلادِ، وفي أواخرِ حياة والده تسلَّمَ العبءَ الأكبر من السلطة؛ نتيجة مرض والده وكِبَر سِنِّه، وكان أخوه محمد بن فيصل يعاونُه في ذلك، أمَّا سعود فكان ينافِسُ أخاه دائمًا في حياةِ أبيهما، واستمَرَّ على هذا الحال حتى بعد وفاة والدهم الإمام فيصل. فعندما بويع عبدُ الله بن فيصل بعد وفاة والدِه في رجب 1282هـ/ نوفمبر 1865م خالفه سعود بعد عامٍ مِن توليه الحكمَ، وكان يرغَبُ في إزاحة أخيه وتولِّي الحكمِ بدلًا منه، وقد كان كثيرٌ من الحاضرة، وخاصةً علماء الدين، يقفون إلى جانب عبد الله؛ لأنَّه الوارِثُ الشرعي للإمامة سنًّا وعهدًا. وعلى الرغمِ مِن أن عبد الله يتمتَّعُ بشعبيةٍ كبيرة بين القبائل النجدية وتأييدِ العلماء له، فإن سعودًا تمكَّنَ مِن جمع أتباع له ومؤيدين، وكانت قبيلةُ العجمان، التي كان بينها وبين سعود صلة رحم، تكِنُّ لعبد الله العداءَ بسبب ضرباته الموجعة لهم في عهد أبيه، فاستغَلَّ سعود ذلك في حربه ضِدَّ أخيه، ونشبت بينهما بعضُ المعارك، واستفاد آلُ رشيد من تلك الفتنة الأهلية بين سعود وعبد الله فأخذوا يوسِّعون دائرة نفوذهم في البلدان النجدية. وبعد وفاة سعود بن فيصل، تولَّى بعده أخوه عبدالرحمن بن فيصل الحُكمَ، وكان سعود خلَّف أربعةً مِن الأبناء الذكور، وهم: محمد، وعبد الله، وسعد، وعبد العزيز، والثلاثة الأُوَل قتلهم ابن سبهان حاكِمُ الرياض من قِبَلِ محمد ابن رشيد، أما عبد العزيز فكان منفيًّا وقت قَتْلِهم، في حائلٍ مع عمِّه الإمام عبد الله، وعبد العزيز هذا هو والد سعود العرافة زوج نورة أخت الملك عبد العزيز، ويلقَّبُ أيضا بسعود الكبير، فيكون سعود بن فيصل هو جدُّ أبناء العرافة، رحمهم الله جميعا وغفر لهم."},{"id":4672,"title":"افتتاح المحاكم المختلطة في مصر -أي التي تشمل المصريين وغيرهم_ .","date":["العام الهجري :1292","العام الميلادي :1875"],"text":"تمَّ إنشاء المحاكِم المختَلطة في مصر بناءً على اتفاق بين مصر والدول التي كانت لرعاياها امتيازاتٌ تفوق امتيازاتِ المواطن المصري. وذلك للفصلِ في المنازعاتِ التي تنشأ بين المصريين والأجانب. أو بين الأجانبِ مختلفي الجنسية؛ حيث أرادت الدولة المصرية أن تخفِّفَ مِن استبداد نظام الامتيازات الذي كان يتمتَّعُ به الأجنبي."},{"id":4673,"title":"آل مهنا يثورون على آل عليان يستولون على حكم بريدة  .","date":["العام الهجري :1292","العام الميلادي :1875"],"text":"كان الإمام فيصل عيَّنَ مهنا الصالح أميرًا على بريدةَ ثمَّ عزَلَه عن الإمارة، وفي هذه السنة ثار مهنا الصالح على آل عليان أمراء بريدة، واغتصب منهم الإمارة وأجلاهم إلى عُنيزة، ولكِنَّ مهنا لم يلبث أن قتله آل عليان، ولكن أنصارَ مهنا وابنه حسن قتلوا القَتَلةَ من آل عليان وتولى حسن إمارةَ بُرَيدة بعد والدِه."},{"id":4674,"title":"حكم أولاد سعود بن فيصل للرياض ثم عودة عمهم عبد الله للحكم .","date":["العام الهجري :1293","العام الميلادي :1876"],"text":"لم تنته الفتنة بين أبناء فيصل بموت سعود، بل استمَرَّت إلى أبعَدَ من ذلك؛ ففي عام 1291 هـ تولى عبد الرحمن بن فيصل إمامةَ نجدٍ بعد وفاة أخيه سعود، ومضى في حكمِه على أتمِّ وجه حوالي السنة، وبعدها اضطربت الأوضاعُ بالنسبة لعبد الرحمن؛ إذ جاء أخوه عبد الله الإمامُ الشرعي ومعه أخوه محمد من بادية العجمان -حيث كانا لاجئينِ سياسيينِ هناك- إلى الرياض ومعهما قوات من بدوِ عتيبة ومِن حَضَرِ الوشم، والتقيا بقواتِ عبد الرحمن الذي رفض التنازلَ لأخيه الكبير في بلدة ثرمدا، ونشبت الحرب بين الطرفين لم يصِلْ أحدهما إلى نصرٍ حاسم، فتفاوضا ونتج عن هذا التفاوض صُلحٌ مؤقت تمركزت فيه قواتُ عبد الله في الشمالِ، وظلت قوات عبد الرحمن تسيطِرُ على الرياض والجنوب.أمَّا بالنسبة لأولاد سعود فقد وقفوا بجانبِ عَمِّهم عبد الرحمن؛ لأنه كان يؤيِّدُ والدهم سعودًا في آخر أيامه، ومع هذا فلم يهدأ الوضعُ المتأزِّم؛ إذ ثار أبناء سعود ضِدَّ عمهم عبد الرحمن وأخذوا يطالبونَه بالحكم، وانقلبوا عليه بعد أن كانوا يؤيِّدونَه. ولم يستطع عبد الرحمن الصمودَ أمام ثورتهم، بل اضطرَّ تحت ضغطهم أن يخرجَ مِن الرياض ويلتجئ عند أخيه عبد الله في بادية عتيبة، وعاهده أن يتعاونَ معه ضِدَّ أولاد سعود!! وهكذا انعكس الوضعُ السياسي في نجد، فأصبح الحكمُ بيَدِ أولاد سعود بدلًا من عَمَّيْهم الشَّرعِيَّينِ، وكان لا بدَّ للعمَّينِ أن يقاوما أولادَ أخيهما حتى يستردَّا السلطة، فجمع عبد الله قواتٍ اتَّجَهت من الشمال نحو الرياض، إلَّا أن أولاد سعود لَمَّا رأوا تصميم عمَّيهم على الحرب، وضَعْفَ قوتهم، تركوا الرياض واتجهوا إلى مركزهم الأول الخَرج، وهكذا استطاع عبد الله وأخوه دخولَ الرياض بدون قتال عام 1293ه / 1876م."},{"id":4675,"title":"ظهور الحركة المهدية ودروها في هزائم المستعمرين الإنجليز .","date":["العام الهجري :1293","العام الميلادي :1876"],"text":"تولى الخديوي إسماعيل الحُكمَ، وكانت الحركةُ الاستعماريةُ في عنفوانِها، فخاف أن يقَعَ السودان فريسةَ احتلال أوروبي، فوضع خطةً واسعةَ المدى لاستكشاف منابعِ النيل وحمايةِ الوطن السوداني، ولكِنَّه ارتكب خطأً فادحًا؛ إذ عَيَّنَ رجلًا إنجليزيًّا هو السير «صمويل بيكر» حاكمًا عامًّا على السودان؛ ذلك لأن صمويل بيكر هذا كان شخصيةً استعمارية صليبيةً شديدةَ الحقد على المسلمين، اتَّبَع سياسةً خبيثة ترمي لهدفين: الأول هو اقتطاعُ منطقة منابع النيلِ وجَعلُها مستعمرةً إنجليزية، والثاني الإساءة إلى أهل السودان وتأليبُهم على المصريين؛ وذلك للحَدِّ من انتشار الإسلام في جنوب السودان بعدما أصبح الشمالُ كلُّه مُسلِمًا خالصًا، بعد انتهاء ولاية صمويل بيكر خلفه رجلٌ لا يقِلُّ حقدًا وصليبية هو «تشارل جورج جوردون». سار جوردون على نفس السياسة؛ مِمَّا أدى لظهور الحركة المهدية بقيادة محمد بن عبد الله المهدي، وذلك سنة 1293هـ، وبدأت الثورةُ المهدية تكسِبُ أنصارًا يومًا بعد يومٍ حتى قويت شوكتها وبدأت في العمل والكفاح المسلَّح، وفي هذه الفترة احتلَّت إنجلترا مصر سنة 1299هـ فازدادت الحركة المهدية قوةً، خاصةً بعدما طلب الإنجليزُ من الجيش المصري الخروجَ من السودان سنة 1301هـ، وحقق المهديون عدةَ انتصاراتٍ باهرةٍ حتى دانت لهم معظمُ الولايات السودانية."},{"id":4676,"title":"موقف آل رشيد من نزاع أبناء فيصل بن تركي .","date":["العام الهجري :1293","العام الميلادي :1876"],"text":"يرجِعُ تأسيسُ إمارة آل رشيد في جبل شمر إلى عبد الله بن علي بن رشيد، الذي كان صديقًا حميمًا لفيصل بن تركي؛ حيث قام بدورٍ كبير في استعادة فيصل للحُكمِ بعد مقتَلِ والده تركي، فكافأه بأن عيَّنَه عام 1251 ه أميرًا على حائل وجبل شمر، على أن يكون الحُكمُ فيها وراثيًّا في أسرته من بَعدِه، مستقلًّا إداريًّا تحت حكم آل سعود. حكم عبد الله بن رشيد 12 سنة، واستمر حكمُ أسرته لجبل شمر 90 سنة، وقد قام آل رشيد بدورٍ خطير في أحداث نجد خلالَ فترة الحرب بين أبناء فيصل بن تركي، خاصة أثناء حكم محمد بن عبد الله بن رشيد، الذي حكم 25 سنة، وهو من أشهَرِ أمراءِ حائل من آل رشيد، وتوسعت إمارةُ ابن رشيد في عهده فشَمِلَت الجوفَ، وتدخَّلَ في شؤون القصيم مستغلًّا الخلاف بين أمرائها من جهةٍ، وتدخُّل عبد الله بن فيصل من جهةٍ أخرى، لصالحه، حتى تمكن من السيطرة على القصيمِ والمجمعة وسدير، وأخيرًا دخل الرياض واحتلَّها بحجة مساعدة الإمام الشرعي عبد الله بن فيصل زوجِ أختِه."},{"id":4677,"title":"ثورة البلغار على الدولة العثمانية .","date":["العام الهجري :1293","الشهر القمري : ربيع الآخر","العام الميلادي :1876"],"text":"قامت ثورةُ البلغار في نفس الوقت الذي قام فيه نصارى البوسنة والهرسك بثورتِهم بدعمٍ مِن النمسا والدول الأوروبية وخاصةً روسيا، فقد تأسَّسَت جمعياتٌ في بلاد البلغار؛ لنَشرِ النفوذ الروسي بين النصارى الأرثوذكس والصقالبة، وكانت تدعَمُها روسيا وتمدُّها بالسِّلاحِ، وتبذُلُ هذه الجمعياتُ بدورها جهدَها لإثارة سكَّان الصرب والبوسنة والهرسك، وتحَرِّضُهم على الثورة ضِدَّ العثمانيين. وعندما أنزلت الدولةُ العثمانية بعضَ الأُسَر الشركسية احتَجَّ البلغار على ذلك، فقاموا بثورة وساعدَتْهم روسيا والنمسا بالسلاح والأموال، فتمكَّنَت الدولةُ العثمانيةُ من القضاء على الثورة، فأخذت الدولُ الأوروبية تثير الشائعاتِ عن المجازِرِ التي ارتكَبَها العثمانيون ضِدَّ النصارى، والعكسُ هو الصحيحُ، وبهذه الشائعات أُثيرَ الرأي العام الأوروبي ضِدَّ الدولة العثمانية، وطالبت الحكوماتُ الأوروبية باتخاذ إجراءاتٍ صارمةٍ ضِدَّ العثمانيين، ومنها حصولُ البلغار على استقلالٍ ذاتيٍّ، وتعيينُ حاكم نصراني لهم، وقام الروس والألمان والنمساويون بدفعِ الصِّربِ والجبل الأسود للقيام بحربٍ ضدَّ العثمانيين، وكانت روسيا ترغَبُ في توسيعِ حدودِها مِن جهة بلغاريا، والنمسا تريد توسِعةَ حدودها من جهة البوسنة والهرسك، ووعدت هذه الدولُ أميرَ الصرب والجبل الأسود بالدعم. وشرع الجنودُ الروس بالتدفُّقِ سرًّا على بلاد الصرب، والجبل الأسود، وتمكَّنَت الدولة العثمانية من الانتصار على الصربِ وحلفائهم، فتدخَّلَت الدولُ الأوروبيَّةُ وطلبت وقفَ القتال، وإلَّا فالحرب الواسِعةُ، واجتمع مندوبو الدول الأوروبية في استانبول وقدَّموا اقتراحات للدولة، من أهمها: تقسيم بلاد البلغار إلى ولايتين، ويكون ولاتُها من النصارى، وأن تشكَّلَ لجنةٌ دولية لتنفيذ القرارات، وأن تُعطى هذه الامتيازاتُ لإماراتي البوسنة والهرسك أيضًا، وأن تتنازلَ الدولةُ عن بعض الأراضي للصربِ والجبل الأسود. ولكِنَّ الدولة العثمانية رفضت هذه القراراتِ، وعقدت صلحًا منفردًا مع الصرب سحَبَت نتيجته جيوشَها من بلاد الصرب، وأن يُرفَعَ العَلَمُ العثماني والصربي دليلًا على السيادةِ العثمانية. وطالب البعضُ -مِثلَ جلادستون زعيم المعارضةِ في البرلمان الإنجليزي- بطرد الدولة العثمانية من أوربا بحربٍ صليبيةٍ عامةٍ، لقد أدرك السلطانُ عبد الحميد الثاني لاحقًا أنَّ هدف الدول الغربية من هذه الإثارةِ هو السعيُ لإسقاطِ الدولة العثمانيةِ."},{"id":4678,"title":"خلع السلطان العثماني عبد العزيز وتولية ابن أخيه مراد الخامس .","date":["العام الهجري :1293","الشهر القمري : جمادى الأولى","العام الميلادي :1876"],"text":"ظنَّ السلطان عبد العزيز بن محمود الثاني أنَّه إذا تقرَّب إلى الروس فإن ذلك سيؤثِّرُ على الدول الأوربية الغربية لتقديمِ تساهلاتٍ أكثَرَ للدولة العثمانية، فخافت الدولُ الأوربية فأشاعت عنه التبذيرَ والإسرافَ، وتولى رئيسُ مجلس الشورى أحمد مدحت باشا فكرةَ عَزلِه، كما تواطأ معه شيخُ الإسلام حسن خير الله أفندي -المنتمي لحركة تركيا الفتاة- فأصدر فتوى شرعية تفيدُ بعَزلِه, فعُزِلَ السلطان عبد العزيز في هذا العام بعد أن أمضى في الحكم ست عشرة سنة وأربعة أشهر كان يسعى خلالها إلى تقويةِ الدولةِ، ثم قُتِلَ بعد ذلك وأُشيعَ أنَّه انتحر، وتولى الخلافةَ بعده ابنُ أخيه مراد الخامس بن عبد المجيد في اليوم السابع من هذا الشهر في هذه السنة."},{"id":4679,"title":"خلع السلطان العثماني مراد الخامس وتولية عبد الحميد الثاني .","date":["العام الهجري :1293","الشهر القمري : شعبان","العام الميلادي :1876"],"text":"لم يلبَث السلطانُ مراد الخامس بن عبد المجيد إلَّا ثلاثة وتسعين يومًا في الخلافةِ حتى قيل إنَّ جنونَ السلطانِ ظهر للناس بشكلٍ واضحٍ، فكان لا بدَّ من خلعِه، وأعلن ذلك من قِبَل شيخِ الإسلامِ عام 1876م وكان نص الفتوى: \"إذا جُنَّ إمامُ المسلمين جنونًا مُطبِقًا ففات المقصودُ من الإمامةِ، فهل يصِحُّ حلُّ الإمامة من عهدته؟ الجواب: يصِحُّ، والله أعلم. كتبه الفقير حسن خير الله أفندي، فتم عزلُه في العاشر من هذا الشهر وتم تولية أخيه عبد الحميد الثاني."},{"id":4680,"title":"ولايتا الصرب والجبل الأسود تشهران الحرب على العثمانيين .","date":["العام الهجري :1293","الشهر القمري : رمضان","العام الميلادي :1876"],"text":"اشتعلت الثَّوراتُ في الهرسك بتحريضٍ من الجبل الأسود ومِن الصرب، ولكنْ سرعانَ ما استطاعت الدولةُ العثمانيةُ إخمادَ الثورة، ولَمَّا رَغِبَ السلطانُ عبد الحميد الثاني في مَنْعِ الدول الأوربية من التدخُّلِ، أصدر مرسومًا بفصل القضاءِ عن السلطة التنفيذية، ويتم انتخابُ القُضاةِ عن طريق الأهالي، والمساواة في الضرائبِ بين المسلمين والنصارى، وكانت النمسا التي تريد ضَمَّ البوسنة والهرسك إليها عادت لتحَرِّضَ السكان من جديدٍ، فاندلعت الثورةُ مجَدِّدًا، لكنها أُخمدت أيضًا، فتدخلت الدولُ الأوربية: النمسا، وروسيا، وألمانيا، وفرنسا، وإنكلترا، وطلبت من السلطان إجراءَ إصلاحاتٍ، فقام بذلك لكِنَّ سكان الهرسك رفضوها بتحريضٍ مِن الدول النصرانية لهم بذلك؛ من أجل التدخُّل في الدولة العثمانية وشؤونِها الداخلية، وكانت روسيا وألمانيا والنمسا قد شجَّعت الصربَ والجبَلَ الأسودَ على إعلانِ الحرب على الدولة العثمانية على أن يمدُّوهم بالسلاحِ، وبدأت القواتُ الروسية تتسلَّلُ سِرًّا إلى الصرب والجبل الأسود، وأُعلِنت الحربُ بقيادة الأمير ميلاك، وكانت المعركةُ في الجبل الأسود لصالحِهم، أما في الصرب فقد استطاع العثمانيون أن يقمَعوهم ثم قمَعوا حلفاءَهم أيضًا، فتدخلت الدولُ الأوربية وفرَضَت إمَّا وقفَ القتالِ وإلَّا فالحربُ العامَّةُ."},{"id":4681,"title":"إعلان رئيس الوزراء العثماني الدستور المسمى \"المشروطية الأولى\" .","date":["العام الهجري :1293","الشهر القمري : ذي الحجة","العام الميلادي :1877"],"text":"كان رئيسُ الوزراء العثماني الشهير مدحت باشا قد أعلنَ المشروطيَّةَ الأولى في أيلول عام 1876م بعد تسلُّم السلطان عبد الحميد الثاني الحكمَ مباشرة، ويعتبر مدحت باشا من أشهَرِ الإصلاحيِّين العثمانيين الذين ارتبطوا بالحركةِ الماسونيةِ، والذين تبنَّوا فكرة الإصلاح على الطريقة الأوروبيةِ، ولُقِّبَ مدحت باشا بـ \"أبي الدستور\" و\"أبي الأحرار\" وتعني المشروطية الأولى: القانونَ الأساسيَّ للدولة العثمانية، أي -الدستور العثماني- وقد تضمَّن إنشاءُ الدستور الحصانةَ النيابيَّةَ، والتشريعَ، والميزانيةَ، والمحكمةَ العليا، ونظام اللامركزية الإدارية، وهو ينقسِمُ إلى 12 قسمًا، ضم 119 مادة. ولم يتِمَّ تنفيذ المشروطية الأولى فعليًّا، بل كانت جنينًا \"مات قبل ولادته\" كما يقال، فقد أُقيل أبو المشروطيَّةِ مدحت باشا من منصبِه في 5 شباط 1877م أي: بعد خمسة أشهر من إعلان المشروطية!"},{"id":4682,"title":"السلطان عبد الحميد الثاني يعزل أحمد باشا عن رئاسة الوزراء .","date":["العام الهجري :1294","الشهر القمري : محرم","العام الميلادي :1877"],"text":"عزل السلطانُ عبد الحميد الثاني رئيسَ الوزراءِ مدحت باشا أبو المشروطيَّة من منصبِه، وذلك بعد خمسة أشهر من إعلان المشروطيةِ التي لم يتِمَّ تنفيذها. فقد أقاله السلطان عبد الحميد الثاني من منصِبِ الصدرِ الأعظم لتوجُّهاته الغربيَّةِ والماسونيَّةِ, ثمَّ حاكمه السلطان بتهمة ضلوعِه في اغتيالِ عَمِّه السلطانِ عبد العزيز."},{"id":4683,"title":"بروتوكول لندن .","date":["العام الهجري :1294","الشهر القمري : ربيع الأول","العام الميلادي :1877"],"text":"وقَّعت الدولُ الأوربيَّةُ الكبرى \"بروتوكول لندن\" وهو الذي يَعرِضُ على الدولةِ العثمانيةِ تأمينَ حُدودِها مقابِلَ إجرائها إصلاحاتٍ في الإيالات (الولايات) البلقانية لصالح الرعايا النصارى، لكِنَّ الدولة العثمانية رفضت شروطَ هذا البروتوكول، وقامت بعقدِ صُلحٍ منفردٍ مع الصِّربِ، سحبت على إثرِه جيوشَها من بلاد الصرب، واشترطت أن يُرفَعَ العَلَمُ العثماني بجوار العلم الصربي، كدليل على استمرارِ السيادة العثمانية."},{"id":4684,"title":"انتصار العثمانيين على الروس في معركة زفيان .","date":["العام الهجري :1294","الشهر القمري : جمادى الآخرة","العام الميلادي :1877"],"text":"انتصر الجيش العثماني بقيادة قائده أحمد مختار باشا على الجيشِ الروسي في معركة \"زفيان\" Zvin في الأناضول."},{"id":4685,"title":"انتصار الجيش العثماني على الجيش الروسي في معركة \"بلونة الثانية\" .","date":["العام الهجري :1294","الشهر القمري : رجب","العام الميلادي :1877"],"text":"انتصر الجيش العثماني على الجيش الروسي في معركة \"بلونة الثانية\" في منطقة البلقان، وخَسِرَ الروس في هذه المعركة أكثر من 7300 قتيلٍ. وهذه المعركةُ إحدى معارك \"حرب 93\" بين روسيا والدولة العثمانية، والتي انتَهَت بانتصارِ الروس."},{"id":4686,"title":"انتصار الجيش العثماني على الجيش الروسي في معركة \"كدكلر\" .","date":["العام الهجري :1294","الشهر القمري : شعبان","العام الميلادي :1877"],"text":"لقي الجيشُ الروسي هزيمةً جديدة على أيدي الجيشِ العثماني، وذلك بقيادةِ القائد العثماني أحمد مختار باشا في معركة \"كدكلر\"، وحصل من السلطانِ العثماني \"عبد الحميد الثاني\" على لقب \"غازي\"؛ لانتصاراتِه المتعَدِّدة على الجيوشِ الروسية."},{"id":4687,"title":"انتصار الجيش العثماني على الجيش الروسي في معركة \"يخنيلر\" .","date":["العام الهجري :1294","الشهر القمري : رمضان","العام الميلادي :1877"],"text":"انتصر الجيشُ العثماني بقيادة القائدِ أحمد مختار باشا على الجيشِ الروسي في معركة \"يخنيلر\"، واستطاع إحرازَ هذا الانتصار بجيش قوامه 34 ألف جندي على الجيش الروسي المكوَّن من 740 ألف جندي، وخَسِرَ الروس في هذه المعركة 10 آلاف قتيل."},{"id":4688,"title":"انهزام الجيش العثماني على يد الجيش الروسي في معركة \"آلاجاداغ\" .","date":["العام الهجري :1294","الشهر القمري : شوال","العام الميلادي :1877"],"text":"تغَلَّب الجيشُ الروسي على الجيشِ العثماني الذي يقودُه أحمد مختار باشا في معركة \"آلاجاداغ\"، بعد عدة انتصاراتٍ لمختار باشا على الروسِ في جبهةِ الأناضول."},{"id":4689,"title":"تعطيل مجلس النواب ونهاية المشروطية الأولى في الدولة العثمانية .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"دامت المشروطيَّةُ الأولى -التي أصدرها مدحت باشا في نهاية عام 1293هـ- مدَّةَ سنة وشهر و21 يومًا، وقد ظلَّ المجلِسُ مفتوحًا خلال الأشهر 12 و25 يومًا الأخيرة. وإن كان الدستور لم يُعمَلْ به أصلًا؛ لأن مدحت باشا الذي أصدر الدستور عُزِلَ عن منصب الصدر الأعظم بعد إصداره للدستور بخمسة أشهر, وكان على رأسِ أحكامِ الدستور المجلِسُ الشعبي، فعُطِّلَ المجلسُ بقرار الحكومة الموشَّح بالإدارة السَّنية لأمدٍ غيرِ معلوم، وسوف يستَمِرُّ هذا التعطيل مدة 31 سنة، وهي دور الإرادة الشخصية للسلطان عبد الحميد الثاني، والتي أطلق عليه معارضوه دورَ الاستبدادِ."},{"id":4690,"title":"بدء انتشار الدعوة القومية والعلمانية وأبرزها جمعية تركيا الفتاة .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"بدأ التعصُّبُ القومي أو بالأحرى: الدعوة إلى العصبية، تظهَرُ بوضوحٍ في أيامِ عبد الحميد الثاني، وإن كانت قد برزت قبله، ولكن بدأ تأسيسُ الجمعيات ذات الأهدافِ السياسية المشبوهةِ، والمرتبطة بالدولِ الاستعمارية، وإن كانت تحمِلُ صِفاتٍ أدبيةً وعلميةً، وكانت مراكِزُها المهمَّةُ هي استانبول وبيروت، ولعب النصارى دورًا كبيرًا جدًّا في نشر هذه الجمعيات في بيروت، فظهرت جمعيةُ العلوم والفنون تحت رعاية الإرساليات التبشيرية الأمريكية، ومن مؤسِّسيها بطرس البستاني، وناصيف اليازجي، وهَدَفت لنشر العلوم الغربية والدعاية لدُولِ أوربا، وقام اليسوعيون بتأسيس الجمعية الشرقية بأعضاء نصارى وتدعَمُها الإرساليات الكاثوليكية، ثمَّ تأسست الجمعية العلمية العربية وضَمَّت نصارى ودروزًا وعربًا مسلمين، وأمَّا في استانبول فقد ضَمَّت الجمعيات مختلفَ الفئات، وإن كان معظَمُها من الأتراك إلا أنَّهم من الذين فُتِنوا بأوربا ويريدون تغيير الوضعِ، أو من اليهود وخاصةً يهود الدونمة، وأشهر هذه الجمعيات جمعية تركيا الفتاة، التي تأسَّست في باريس ولها فروع في برلين وسلانيك واستانبول، ورئيسها أحمد رضا بك المفتونُ بالثورة الفرنسية، ومقالاته الداعية دائمًا لتقليد الغرب، وكانت هذه الجمعيةُ تلقى ترحيبًا من المحافل الماسونية، وفيها تمَّ تنظيمُ الاتحاد والترقي الذي كان له الأثرُ الكبير في إنهاء الخلافةِ العثمانية، وكان من رجالها رجالٌ في الدولة مثلُ مدحت باشا الذي كانت له اليدُ الطولى في خلعِ السلطان عبد العزيز ومراد الخامس، وكانوا يطالبون بوضعِ دستور للدولة غير الدستور الإسلاميِّ، على نمط الأوربيِّين! وزاد نفوذُ يهود الدونمة الذين أظهر كثيرٌ منهم الإسلامَ، فنُسِيَ أصلُهم, وبدؤوا بالتخريبِ مِن الداخل."},{"id":4691,"title":"الحرب الأفغانية البريطانية الثانية .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"هي حربٌ وقعت بين إمارة أفغانستان وبريطانيا بين عامي 1878م و1880م وهي فترة حكم شير علي خان الذي ينتمي لعائلة البركزاية الحرب التي شنَّها الراج البريطاني لغزو أفغانستان، وقد انتهت الحرب بانتصار بريطاني ثم انسحابها من أفغانستان بعد معاهدة جاندماك؛ حيث احتفظ الأفغان بالسيادة في المناطق الداخلية لبلادهم في حين تخلَّوا للإنجليز عن المناطق الحدودية وإدارة العلاقات الخارجية للبلاد."},{"id":4692,"title":"انهزام العثمانيين أمام روسيا .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"وقَّعت روسيا اتفاقًا سريًّا مع الأفلاق والبغدان (رومانيا) وضَعَت رومانيا بموجِبِه جميع إمكانياتها تحت تصرُّف روسيا، ثم قطعت روسيا العلاقاتِ السياسية مع الدولةِ العثمانية، وأعلنت الحربَ عليها بناءً على رفضِ البابِ العالي للائحةِ لندن-البابُ العالي هو قصرٌ في استانبول يقيمُ فيه السلاطين العثمانيون- وأخبر الباب العالي دولَ أوربا ثانيةً عمَّا تصرَّفت به روسيا فلم يَلقَ أيَّ موقف إيجابي، وذلك عام 1294هـ رغم المعاهدة السابقة التي وُقِّعَت بعد حرب القرم، وكانت روسيا قد اختَرَقت حدودَ رومانيا وانتصَرَت على العثمانيين في عِدَّةِ مواقِعَ، ثم توقَّفَت بعد المقاومة التي اعترضتها، وانقلب وضعُ الجيوش العثمانية من مُدافَعةٍ إلى مُهاجَمةٍ، وبعد تقدُّمٍ بسيطٍ عاد النصرُ إلى جانب الروس، واضطر القائِدُ العثماني عثمان باشا إلى الاستسلامِ وهو جريحٌ، وتوقَّفَ القتال في الجبهة الأوربية، أمَّا في شرقيَّ الأناضولِ فقد حاصر الروسُ عِدَّةَ مدن وقلاعٍ، ومنها قارص وباطوم، إلا أنهم اضطروا لفكِّ الحصار عنها والتراجُعِ، بجهود أحمد مختار باشا، وإسماعيل حقي باشا، وانتصر العثمانيون على الروس في ستة وقائع، وقد طلب الروسُ إمداداتٍ فجاءتهم جيوشٌ جرَّارة، ولم يتمكَّن العثمانيون من إرسال الإمدادات إلى الجبهةِ، وجاء الهجوم الروسي الثاني فتراجعت الجيوشُ العثمانية؛ حيث انسحب أحمد مختار باشا، وبسقوطِ قارص في جبهة الأناضول وسقوط بلافنا بعدها بشهرٍ على الجبهة الأوربية استأسَدَ الصرب فأعلنوا الحربَ على الدولة العثمانية بعد لقاءٍ بين إمبراطور روسيا وأمير الصرب، كما تابع سكانُ الجبل الأسود قتالَهم للعثمانيين، فأصدر الباب العالي منشورًا يُعلِنُ عزل أمير الصرب عن إمارتِه ويوضِّحُ للسكان هذه الخيانةَ، فلم يُجْدِ ذلك نفعًا! وتقَدَّم الروس فاحتلوا صوفيا عاصمة بلغاريا اليوم، ومنها ساروا إلى أدرنة فدخلوها وانطلقوا منها نحو استانبول، ولم يبقَ بينهم وبينها سوى خمسين كَيلًا وعندما اقتربت الجيوشُ الروسية من أراضي البلغار انقَضَّ النصارى على المسلمين يفتِكون بهم ذبحًا وقتلًا، وفرَّت أعدادٌ كبيرة من المسلمين متَّجِهة نحو استانبول، وأرسل البابُ العالي وفدًا عسكريًّا من نامق باشا وسرور باشا لوقفِ القتال، فقابل الوفدَ الروسيَّ وتوقَّف القتالُ في مطلع هذا العام، وأعلن الباب العالي عن رفع الحصارِ عن سواحل البحر الأسود، ولما علمت إنكلترا أنَّ قوات روسيا أصبحت على مَقرُبة من استانبول أمرت قطعاتها البحرية بدخول مضيق البوسفور ولو بالقوةِ، وقد تم ذلك وأرادت روسيا مقابِلَ ذلك أن ترسِلَ قوات إلى استانبول بحجَّة حماية النصارى، ثم اتفقت الدولتان وهدأت الأوضاع."},{"id":4693,"title":"ملحمة بلافنا مع الروس  .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"عبَرَت جحافِلُ القوات الروسية ﺍلأﺭاضي العثمانية باتِّفاقٍ ومباركةٍ مِن فرنسا وبريطانيا، انضَمَّ إلى الروس قواتٌ رومانية وصربية وبلغارية، وعَبَروا نهر الدانوب، واستولوا علي بعض المدُنِ التابعة للعثمانيين، والمعابر المؤدية إلى البلقان، فقام السلطان عبد الحميد الثاني بتعيين عثمان باشا قائدًا للجيشِ العثماني لصَدِّ الغزو الروسي الذي حاول الاستيلاءَ على مدينة بلافنا، التي تقع في بلغاريا، وهي من أهم المعابر في البلقان، ولكنَّ القائد العثماني عثمان باشا أظهر مع قوَّاتِه بسالةً مُنقَطِعةَ النظير في الدفاع عن مدينة بلافنا، رغم أن جيشه الصغير لا يتعدى 50 ألف مقاتلٍ، فتحرَّك سريعًا ووصل المدينةَ قبل الروس الذين يُقَدَّرُ عددُهم بمئات الألوف، وفرض الحصارَ على ثلاثة خطوط، ومع ذلك فإن العثمانيين المحاصرين بقيادة عثمان باشا صَمَدوا صمودَ الأبطال ولم يكتفوا بالصمودِ, بل أعدُّوا خطة للهجومِ على خطوط العدو المحاصِرِ لهم، طالبين بذلك إما النصر وفكَّ الحصار، أو الشهادةَ، فقاد عثمان باشا قواتِه التي انحدرت على الأعداء وهم يُهلِّلون ويكَبِّرون, فقُتِلَ أعدادٌ منهم، ومع ذلك تمكنوا من تكبيدِ الأعداء خسائِرَ في الأرواح وغَنِموا عددًا من المدافعِ، وأصيب عثمان باشا ببعض الجِراحِ، فسَرَت إشاعةٌ قويَّةٌ بين جنده بقتلِه، ففَتَّ ذلك في عضدهم، وحاولوا الرجوعَ إلى مدينة, لكِنَّ الروس أصبحوا بداخلها, فاستسلموا للقواتِ الروسية. وقد سَلَّم عثمان باشا نفسه وهو جريحٌ إلى الروس الذين كانوا معجَبين به وبشجاعتِه."},{"id":4694,"title":"احتلال بريطانيا جزيرة قبرص وبقاءها في حكم العثمانيين اسمًا فقط .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"فتح العثمانيون جزيرةَ قُبرص سنة 979هـ وعَمِلوا على توطيدِ دَعائِمِ الإسلامِ بها وأسكَنوا فيها كثيرًا من المسلِمين حتى صار عددُ المسلمين فيها ثلاثةَ أضعاف النصارى، وهكذا غدت الجزيرة بلدًا إسلاميًّا خالصًا وجزءًا من أمَّةِ الإسلام.وعندما ضَعُفَت الدولةُ العثمانية وقَوِيَت أوروبا التي أخذت في التهامِ جَسَدِ الدولة قطعةً قِطعةً، وكان الإنجليزُ أعدى أعداء المسلمين ينظُرون لقبرص نظرةً خاصةً باعتبارِها قاعدةً هامةً في الطريقِ إلى الهندِ، فأكره رئيسُ وزراء إنجلترا دزرائيلي اليهوديُّ السلطانَ عبد الحميد الثاني على قَبولِ معاهدة دفاع مشترك سنة 1296هـ تكون قبرص بموجِبِها تحت الحماية الإنجليزية نظيرَ 92800 جنيه إسترليني. وعندما احتَلَّت إنجلترا قبرص كان أكثَرُ سُكَّانِها مسلمين، فعَمِلوا قبل كلِّ شيءٍ على إضعاف المُسلِمين بتشجيعِ هِجرةِ النصارى اليونان لقُبرص، وفي نفس الوقتِ ضَغَطت على المسلمين الأتراك للهجرةِ منها، واستمَرَّت إنجلترا على نفسِ السياسةِ حتى قيام الحربِ العالمية الأولى، عَمِلت إنجلترا بجانبِ خلخلة التركيبة السكانية وإضعافِ قوَّة المسلمين إلى نشرِ الفساد والانحلالِ داخِلَ الجزيرة، وعَهِدوا إلى اليهود بالكثيرِ مِن المناصب، والذين أنشؤوا بدورهم مراكِزَ تجارية كبيرة بالبلدِ، وجعلوها مقرًّا لعصابات الصهاينة، وعندما قامت دولةُ اليهود الخبيثة كانت قُبرص من أوائِلِ مَن اعتَرَف بها."},{"id":4695,"title":"مؤتمر برلين واحتلال النمسا للبوسنة والهرسك .","date":["العام الهجري :1295","العام الميلادي :1877"],"text":"رأى بسمارك مستشار ألمانيا عقدَ المؤتمر المزمَعِ عقدُه في برلين، وعُرِف بـ(مؤتمر برلين) وقَبِلت روسيا أن تعرِضَ شروط المعاهدة على المؤتمر؛ لأنها شعرت حينذاك بعُزلتها. وعُقِدَ المؤتمرُ في 13 يونيو 1878م في برلين، واستمر 31 يومًا، إذ انتهت أعماله في 13 يوليو. وقد حضره مندوبون عن بريطانيا وألمانيا والنمسا والمجر وفرنسا وإيطاليا وبوهيميا وروسيا، والدولة العثمانية. وفي هذا المؤتمر اتَّفَقت سياسة ألمانيا مع سياسة كلٍّ مِن النمسا وبريطانيا. وأيَّد بسمارك جميعَ المشروعات الإنجليزية التي كانت ترمي إلى تضييقِ الخناق على روسيا. وقد قرَّر المؤتَمِرون الآتي: أ. توضَعُ البوسنة والهرسك تحت حماية النمسا وإدارتها. أمَّا بلغاريا -التي امتدَّت حدودها بموجِبِ معاهدة سان ستفانو، طبقًا للسياسة الروسيَّةِ- فقد انكمشت إلى مساحةٍ أكثَرَ ملائمةً واعتدالًا. ب. تحصل روسيا على مقاطعة بسارابيا. ج. تحصل إنجلترا على قبرص ممَّا يحدُّ من أطماع الروس، ومع أن دولة النمسا والمجر استطاعت أن تكسِبَ أرضًا جديدة -البوسنة والهرسك- من دون أن تدخُلَ الحربَ؛ فإن ذلك الكَسبَ كان في الواقِعِ عبئًا جديدًا على عاتقِها؛ إذ إنَّ بسط السيادة النمساوية على ولايتَين سلافيتَين يزيد من نسبة عدد الجنسيات الأجنبية المختَلِفة في المملكة الثنائية (النمسا والمجر)، وذلك يُضعِفُ بناءها، كما اتضح فيما بعد، ويزيد أعباءَها، وقد كان الإمبراطور فرنسيس جوزيف نفسُه يرى هذا الرأيَ."},{"id":4696,"title":"معاهدة سان ستفانو وانسحاب تركيا من أوروبا  .","date":["العام الهجري :1295","الشهر القمري : صفر","العام الميلادي :1878"],"text":"بعد الحرب مع روسيا التقى مندوبو الدولةِ العُثمانيَّة ومندوبو روسيا في بلدة قرب استانبول على بحر مرمرة تُسمَّى سان ستفانو، وذلك بعد محادثات تقَدَّمَ فيها الروس قليلًا عن خطِّ وقف إطلاق النار الذي اتُّفِق عليه، ونُقِلَ أيضًا مركزُ المحادثات من أدرنة إلى هذه القريةِ، وقدَّمَ المندوبُ الروسي شروطًا مسبقةً وطلب التوقيعَ عليها مباشرةً، وإلا تتقَدَّم الجيوش الروسية وتحتل استانبول، ولم يكن للعثمانيين من خيارٍ سوى التوقيع، وتنص المعاهدةِ على: تعيينِ حُدودٍ جديدة للجبل الأسودِ لإنهاء النزاع، وتحصُلُ هذه على الاستقلالِ، وإذا حَدَثت خلافاتٌ جديدةٌ تحلُّها روسيا والنمسا، تستقِلُّ إمارة الصرب وتُضافُ لها أراضٍ جديدةٌ، وتحدَّدُ الحدود حسبَ الخريطةِ المرفقة، وبمساعدة الروس تأخذ بلغاريا استقلالًا إداريًّا وتدفع مبلغًا محدَّدًا إلى الدولة العثمانية، ويكون موظفو الدولة والجندُ من النصارى فقط، وتُعَيَّن الحدود بمعرفة العثمانيين والروس، ويُنتَخَب الأمير من قِبَل السكان، ويُخلِّي العثمانيون جنودَهم نهائيًّا من بلغاريا، ويحِقُّ للعثمانيِّين نقلُ جنودهم إلى ولايات أخرى ضِمنَ الأراضي البلغارية، تحصل دولةُ رومانيا على استقلالها التام، يتعهَّدُ الباب العالي بحماية الأرمن النصارى من الأكرادِ والشركس، يقومُ الباب العالي بإصلاح أوضاع النصارى في جزيرة كريت، تدفعُ الدولة العثمانية غرامةً مالية حربية قدرها 245.217.391 ليرة ذهبية، ويمكِنُ لروسيا أن تتسلم أراضيَ مقابل المبلغ، تبقى المضائِقُ البوسفور والدردنيل مفتوحةً للسفن الروسية في زمن السِّلمِ وزَمَن الحرب، يمكِنُ للمسلمين الذين يعيشون في الأراضي التي اقتُطِعَت من الدولة العثمانية أن يبيعوا أملاكَهم ويهاجروا إلى حيث يريدون من أجزاءِ الدولةِ العُثمانية."},{"id":4697,"title":"تولي السياسي الأرمني \"نوبار باشا\" رئاسة الوزراء في مصر .","date":["العام الهجري :1295","الشهر القمري : شعبان","العام الميلادي :1878"],"text":"تولَّى السياسيُّ النصرانيُّ الأرمني \" بوغوص نوبار باشا\" رئاسةَ الوزراء في مصر، وهو أول رئيس وزراء بمصرَ، وذلك في ظِلِّ تزايد النفوذ الأجنبي في مصرَ في عهد الخديوي إسماعيل، وعُرِفَت هذه الوزارة بالوزارة الأوروبيَّة، واستمَرَّت حتى 23 فبراير 1879م. شغل نوبار منصب رئيس الوزراء 3 مراتٍ، كان يُتقِنُ اللغات: الفرنسية، والإنجليزية، واليونانية، والتركية، ولم يُتقِنِ اللغةَ العربيَّةَ!"},{"id":4698,"title":"هجرة الشراكسة المسلمين من روسيا بسبب الاضطهاد الديني .","date":["العام الهجري :1296","العام الميلادي :1878"],"text":"الشَّراكسة أو الشركس (أو الجركس) واليونان هم أوَّلُ مَن أطلق عليهم هذا الاسمَ. وهذا الاسمُ لم يطلِقْه أيُّ شَعبٍ على نفسِه، ويُطلق حاليًّا على أعراقِ شمال القوقاز، مثل الأديغا، ويقطنون حاليًّا في شركيسيا والقبردي والأديغي والسواحل الشمالية الغربية للقوقاز على البحر الأسود، والأبخاز في جمهورية أبخازيا حاليًّا، والشيشان في جمهوريتي الشيشان وأنغوشيا والمناطق المجاورة، وبعض القبائل القليلة من الداغستان. هاجر الكثيرُ منهم إلى بلاد الشام وباقي أرجاءِ الدولة العثمانية هِجرةً قسريةً؛ نتيجةً للحرب التي استمَرَّت قرابة المائة وعشرين عامًا مع روسيا القيصرية، استقَرَّ معظم الشراكسة المهاجرين في تركيا حيثُ يبلغ عددهم اليوم فيها حوالي ثلاثة ملايين نسمة، بينما استقَرَّت مجموعات منهم في بعض بلاد الشام، مثل سوريا والأردن وفلسطين، في سوريا استقَرَّ معظم الشراكسة في هضبة الجولان وأنشؤوا قراهم هناك، والباقون سكنوا مدينة دمشق، أما في الأردن فاستقَرَّ معظمهم في عمان ووادي السير وناعور وصويلح والزرقاء وجرش، وقد بنوا أول البيوت الطينية في عمان في المنطقة التي لا تزال حتى الآن تُعرَف بالمهاجرين نسبةً إلى المهاجرين الشركس، وشارع الشابسوغ نسبةً إلى عشيرة الشابسوغ التي كانت أوَّلَ مَن سكن فيه، وفي فلسطين استقَرَّ الشراكسة في الشمال؛ حيث أنشؤوا قريتي كفركما والريحانية، وقد حافظ الشركس على مجتَمَعِهم ولغاتهم وتقاليدِهم في تركيا وسوريا والأردن وفلسطين؛ بسبب قلة اختلاطهم بالشعوب الأصلية في تلك المناطق، وبقاء الكثير منهم منعزلًا في قراهم التي هاجروا إليها، إلا ما يكون من اختلاطهم بالناس في التجارة وما إليها."},{"id":4699,"title":"تولية خير الدين التونسي رئاسة الوزراء في الدولة العثمانية .","date":["العام الهجري :1296","الشهر القمري : محرم","العام الميلادي :1879"],"text":"تولى خير الدين التونسي منصِبَ رئاسة الوزراء في الدولةِ العثمانيةِ. ولد خير الدين في القفقاس لعائلةِ تليش الأباظية الشركسية، حوالي عام 1820م. تعهَّده والي تونس الداي أحمد، وهيأ له فُرَصَ الاستزادة من العلوم، فأكَبَّ على دراسة الفنون العسكرية والسياسية، والتاريخ والعلوم الشرعية، وأتقن اللغاتِ العربيةَ والتركية والفرنسية. أصبح رئيسًا لمكتب العلوم الحربية بباردو عام 1840م، ثم أصبح رئيسًا لفرقة الفرسان في الجيش التونسي. وعيِّن مديرًا لِمَصرف الدراهم التونسي. وفي عام 1849م رقِّيَ إلى رتبة ومنصب أمير لواء الخيالة في تونس، وفي عام 1855م أنعَمَ عليه الباي المشير محمد باشا برتبة الفريق؛ لإنقاذه تونس من قرضٍ مالي ثقيل كاد الباي السابق أن يندفِعَ إليه. ثم عيَّنه وزيرًا للبحرية عام 1857‏م حيث أجرى عدَّةَ إصلاحات إدارية. وساهم في صياغةِ وإصدار قانون (عهد الأمان) التونسي عام 1857م. وشارك في وضع الدستور التونسي عام 1860‏م. وعند إنشاءِ مجلس الشورى التونسي المنتَخَب كان خير الدين باشا الرئيس الفعليَّ للمجلس من عام 1861‏م. اصطدم مع سياسة الباي الجديد محمد الصادق فقَدَّم استقالتَه من الوزارة ومِن رئاسة مجلس الشورى عام 1862م وفَرَض على نفسه العزلةَ السياسية لمدة تسع سنوات بين عامي 1862م و1869م. وكان من نتائج عزلته تلك تأليفُه الكتاب الشهير الذي أسماه ((أقوم المسالك في معرفة أحوال الممالك)) والذي تمَّ طبعُه في تونس عام 1867 ‏م. بعد ذلك شارك مندوبًا عن تونس في اللجنة المالية المختلطة المشكَّلة لتحصيل ديون الدُّول الأوروبية من تونس، فاستطاع الحدَّ من نفوذ اللجنة وتدخُّلِها في شؤون الدولة. ‏وفي أكتوبر 1873م عيِّنَ وزيرًا أكبر لتونس (أي رئيسًا للوزراء) فسَنَحَت له فرصةُ تحقيق برامجه الإصلاحية التي طرحَها في كتابه (أقوم المسالك) واستطاع نقل تونس من حالة الكرب والضيق والفوضى إلى حالةٍ مِن الأمنِ والرخاء والنظام. وتصدى بحزمٍ للمطامع الأجنبية في بلادِه، وخاصة المطامح الفرنسية والإيطالية المتنافسة. ولكِنَّه فوجئ بمعاتبة الباي له وغضبه من سياسته في التحمُّسِ لإعانة الدولة العثمانية في حَربِها ضِدَّ روسيا، فقَدَّم استقالته من رئاسة الوزارة في يوليو1877م. ‏وبعد استقالته ضَيَّق عليه الباي الخناقَ ومنعه من الاتصال بالناس، فكان معتقلًا في منزله. وقد سافر للعلاجِ ثم عاد إلى تونس وظَلَّ شِبهَ مُعتَقَل حتى استدعاه السلطانُ العثماني عبد الحميد الثاني فسافر إلى الأستانة في رمضان 1877م حيث استقبله السلطانُ وعَيَّنه وزير دولة بعد رفضِه منصب وزير العدل. ولكِنَّه فوجئ في صباح يوم 4 ‏ديسمبر 1878م بتعيينه رئيسًا لوزراء الدولة العثمانية. وكانت الدولةُ العثمانية وقتَها في ضيقٍ وحَرَجٍ كبير؛ فالجيش الروسي يقِفُ على عتبات العاصمة استانبول، والأسطول البريطاني في مضيق البوسفور، والاقتصادُ متدهور، وهناك المشكلةُ الأرمينية، ومشاكِلُ في قبرص والبوسنة! فسارع خير الدين باشا إلى عقد اتِّفاقٍ مع الروسِ يضمَنُ مصالح المسلمين في بلغاريا وروملي الشرقية،كما انسحب الأسطولُ البريطاني مِن مَضيقِ البوسفور، وسَوَّى الخلافات مع النمسا، وحُلَّت مشكلة الأرمن، واستبدل بالخديويِّ إسماعيل ابنَه توفيقًا في مصر. وقد اختلف كثيرًا مع السلطان عبد الحميد الثاني ورجالِ حاشيته إبَّانَ توليه رئاسة الوزراء، فكان أن عُزِلَ مِن منصبه في شعبان 1296 ‏هـ ( 1879 ‏م) وعاش بعدها بعيدًا عن السياسة حتى توفِّي بعد عشر سنوات في الأستانة عام 1889‏م ودفِنَ في جامع أيوب، إلا أن الحكومة التونسية بادرت في عام 1968‏م إلى نقل رُفاته ودفنه في تونس تقديرًا لخِدماتِه، وقد أطلق عليه الشَّعبُ التونسي لقب ((أبو النهضة التونسية))."},{"id":4700,"title":"عزل الخديوي إسماعيل ونفيه إلى إيطاليا واستخلاف ابنه توفيق .","date":["العام الهجري :1297","العام الميلادي :1879"],"text":"كان للخديوي إسماعيل خصومٌ في مصر وفي الأستانة، مع تزايُدِ التدخل الأوربي السافِرِ في شؤون مصر، فكانت القناصِلُ الأوربية يضغطون عليه ليُقيل نفسَه، وفي استانبول كان بعضُ السفراء يحثُّون السلطان على إصدار قرار العزلِ، ومن الأسباب التي اتخذتها الحكوماتُ الأوربية للمطالبة بعزلِه الانقلاب السياسي الذي قام به إسماعيل سنة 1879م (سنة عزله) وأنهى به عهدَ حُكمِ حملة السندات، باستقالة النظارة المصرية الإنجليزية الفرنسية، وتأليف نظارة مصرية صميمة، كما حَقَدت عليه فرنسا لبيعه أسهُمَ قناة السويس لإنكلترا دون أن يبيعَها لفرنسا، وأما بريطانيا فكان هدفُها من عزله هو تمهيدَ الطريق لها للانفرادِ باحتلال مصر عسكريًّا وبسط حماية مقنعة عليها، وباقي الدول كانت تتذرَّع بالديون التي لها عليه، ثم صدر المرسومُ السلطاني بعزل إسماعيل وتولَّى الصدر الأعظم خيرُ الدين التونسي إبلاغَ إسماعيل بالقرار في ضحى يوم 26 حزيران سنة 1879م وأبلغ بذلك أيضًا ولي العهد توفيق بن إسماعيل، وأمَّا القنصلان الفرنسي والبريطاني فطلبا من إسماعيل التنازُلَ قبل أن يَصِلَ الأمر التام من السلطان، وهَدَّده القنصل الفرنسي بالنفيِ دون أن يحمل معه شيئًا، وكان المرشَّح للجلوس مكانه هو حليم باشا عَمَّ إسماعيل، لكنَّ تحت الضغط البريطاني ألغي ترشيحَه، ثمَّ تم تعيين ابنه توفيق مكانه، ثم تحدَّد يوم الاثنين 30 حزيران 1879م موعدًا لمغادرة الخديوي إسماعيل عن مصر، ثم أبحرت به الباخرة المحروسة إلى إيطاليا التي امتنعت من استقبالِه، وظلَّ شهرًا في البحر هو وأهله ثم أُذِنَ لهم بعد ذلك بالنزول إلى البرِّ!"},{"id":4701,"title":"احتلال فرنسا تونس وتوقيع معاهدة \"باردو\"  .","date":["العام الهجري :1298","الشهر القمري : جمادى الأولى","العام الميلادي :1881"],"text":"بعد أن احتَلَّت فرنسا الجزائِرَ سنة 1246هـ عَزَمت على احتلالِ تونس وقامت مقابِلَ ذلك بالتنازُلِ لإنكلترا عن مصرَ، فبدأت بالتدخُّل أولًا في أمورِ الدولة بحجَّة الديون، ثمَّ قامت باستغلالِ خلافٍ افتعلَتْه على الحدودِ مع الجزائِرِ، واتَّهَمت تونس بإيواء المجاهدين الجزائريين في أراضيها، وأنَّها لا بدَّ لها من التدخُّل لقمع هؤلاء المجاهدين وجيوبهم، فقامت بحملةٍ عسكرية، ودخلت الأراضيَ التونسية، ثمَّ لم تلبَثْ أن وصَلَت إلى قصرِ باردو الذي كان فيه حاكِمُ تونس الباي محمد الصادق، وفَرَضت عليه معاهدة الحماية، فاجتمع الباي بكبار رجالِ دولته، وعرض عليهم الأمرَ، وكان الحاضِرون يميلون إلى رَفضِ الحماية وإعلان المقاوَمةِ والجهادِ وتعبئة الأمَّة لذلك، لكِنَّ ذلك لم يجِدْ آذانًا مُصغية أمام تهديد الفرنسيين بخلعِ الباي محمد الصادق عن العَرشِ وتنصيب أخيه \"الطيب باي\" مكانَه إذا رفضَ التوقيعَ على المعاهدة، وكان ممثِّلو الاحتلال الفرنسي ينتَظِرون في غرفةٍ مجاورة للحجرةِ التي اجتمع فيها السلطانُ برجاله، وبعد ساعتين من الاجتماع خرج باي تونس حاملًا نسخَتَي المعاهدة وقد وقَّع عليهما! وبذلك انتهى الاستقلالُ الفعلي لتونس بعد توقيع المعاهدة التي عُرِفَت بمعاهدة \"باردو\" وتضَمَّنت هذه المعاهدة تقييدَ سلطة الباي، ووضْعَه تحت حماية فرنسا، وسلَبَت تونسَ كُلَّ مقومات الدولة المستقِلَّة. وغدا المقيم العام الفرنسي في تونس الحاكِمَ الحقيقيَّ للبلاد! ثم لم تلبث أن زادت القواتُ الفرنسيَّةُ، وأصبحت تفرِضُ نفسَها كالاحتلالِ العسكريِّ تمامًا، فأصبحت تونس تحت النفوذِ الفرنسي واحتلالِه، ثم بدأت بفَرْنَسةِ تُونسَ، بتنفيذِ عِدَّة إجراءاتٍ ثقافية واقتصادية واجتماعية، ثم عَدَّلت معاهدةَ الحماية السابقة قسرًا سنة 1300هـ فصارت بذلك تونس تحت يد المقيم العام الفرنسي والحماية العسكرية الفرنسية!!"},{"id":4702,"title":"خيانة اليهود للمسلمين في مدينة صفاقس التونسية .","date":["العام الهجري :1298","الشهر القمري : جمادى الآخرة","العام الميلادي :1881"],"text":"خان اليهودُ في مدينة صفاقس الشعبَ التونسيَّ المسلِمَ، وذلك حين أخبروا البارجةَ الفرنسية \"ألكرسيكي\" باستعدادِ الأهالي من المسلمين لمقاومتهم، فأحجمت البارجةُ عن مهاجمة المدينة لحين التزوُّد، ثم هاجمتها بمعاونة 6 بوارج إضافيةٍ أخرى."},{"id":4703,"title":"جهاد التونسيين للمحتل الفرنسي  .","date":["العام الهجري :1298","الشهر القمري : شعبان","العام الميلادي :1881"],"text":"لم يرضَخِ الشعبُ التونسي لاحتلالِ فرنسا لبلادِه تحت عنوانٍ برَّاقٍ، وهو إعلانُ الحماية، والذي استهدفت فرنسا من اختيارِه عدمَ إثارة الدول الأوروبية، والتمويه على أبناء تونس بأنَّها لم تحتَلَّ بلدهم، وتُنزِلها منزلةَ المستعمرات، وحتى تُحمِّلَ الجانبَ الوطني نفقاتِ الاحتلال. واشتعلت الثورةُ في معظم أنحاءِ تونس، وعجزت فرنسا عن وقفِ العملياتِ الحربيَّة في تونس، واتَّضح أن القبائلَ التي تسكن شرقيَّ تونس وجنوبها أظهرت رفضَها وعداءَها للطريقة التي خضع بها الباي لطلبات الفرنسيين، وعَلَت الأصواتُ داعيةً إلى الجهاد والبذل والعطاء، وفي الوقت نفسِه اتصلت رسلُ السلطان العثماني عبد الحميد الثاني بالمجاهِدين تُعلِنُ رَفضَ السلطان للمعاهدة ووقوفَه إلى جانب الشعب، وتمكَّن المجاهدون من قَطعِ المواصلات، وفَرَّت معظم جنود الباي إليهم، وأعلن المسلِمون الجهادَ ضِدَّ الفرنسيين. وبعد أن كانت فرنسا تفكِّرُ في أنه يكفي أن يقومَ جيش صغير على استتباب الأمن في تونس، لكنَّها وجدت أنها تعاني مشكلةً كبيرة في السيطرة على البلاد، وتطلَّب ذلك تعاوُنَ الأسطول الفرنسي مع الجيش، وحَشْد قوات جديدة بلغت خمسًا وأربعين ألف جندي. وكان قد تزعَّم حركةَ المقاومة في مدينة قابس \"علي بن خليفة\" إلى جانب كثيرين قادوا الثورةَ في صفاقس والقيروان، وقد حاول علي بن خليفة أن يوحِّدَ القيادةَ في شخصه، واجتمع لهذا الغَرَضِ مع مجاهدي صفاقس والقيروان، لكِنَّ جهوده لم تُكَلَّل بالنجاح بعد أن أصَرَّ زعيمُ كل منطقة أن يتولى الأمر بنفسه، فاستطاعت فرنسا أن توقِعَ بهم واحدًا بعد الآخر. وكان من جرَّاء ذلك أن سقطت قابس في أيدي المحتلِّين الفرنسيين بعد مقاومة شديدة، في 28 شعبان من هذه السنة!"},{"id":4704,"title":"مقاومة أحمد عرابي استبداد الخديوي .","date":["العام الهجري :1299","العام الميلادي :1881"],"text":"في أوائل سنة 1298هـ استفحل أمرُ الشراكسة بمصر، وهمَّ ناظر الجهادية عثمان رفقي باشا الشركسي بتنحية فريقٍ مِن الوطنيين عن مراكزهم، فاجتمع عددٌ من هؤلاء وانتدبوا أحمد عرابي للمطالبة بموادَّ اتفقوا عليها، منها عزل رِفقي من نظارة الجهاديَّة، وتأليف مجلس نوَّاب. فرفع أحمد عرابي الأمرَ إلى رئيس النظار (رياض باشا) فأهمله إلى أن انعقد مجلسٌ برئاسة الخديوي، فقَرَّر محاكمة عرابي واثنين من أصحابه، فقُبِض عليهم، فهاج الضباطُ الوطنيون وأخرجوا المعتَقَلين عرابي ورفيقيه، وفَرَّ رفقي ورجالُه إلى قصر عابدين، ثم صدر الأمرُ بعزل عثمان رفقي من نظارةِ الجهاديَّة وتولية محمود سامي باشا البارودي، فأقام مدةً يسيرةً وعُزل. عاد عرابي وأصحابه إلى هياجهم، فانحلَّت وزارة رياض باشا، وتألَّفت ثانية برئاسة شريف باشا، أعيد فيها محمود سامي إلى نظارة الجهادية، وجُعل عرابي وكيلًا للجهاديَّة فيها، وأُنعِمَ عليه برتبة اللواء (باشا) وأجيبَ إخوانُه إلى بعض مطالبهم. وتتابعت الحوادِثُ فسقطت هذه الوَزارةُ وخَلَفتها وزارةٌ برئاسة محمود سامي باشا جُعِل عرابي ناظرًا للجهادية فيها، ثم استقالت. ولم يَرَ الخديوي مندوحةً عن إعادة عرابي إلى الجهاديَّة، فاستبقاه، وظَلَّت مصر بلا وزارةٍ إلى أن تألَّفَت وزارة راغب باشا، ووقعت المذبحة في الإسكندرية وضربها الإنجليز، واستولَوا على التل الكبير بعد معارِكَ ودخلوا القاهرةَ فحَلُّوا الجيشَ المصريَّ ونَفَوا أحمد عرابي باشا."},{"id":4705,"title":"ضم ابن رشيد المجمعة لحكمه .","date":["العام الهجري :1299","العام الميلادي :1881"],"text":"وقَّع محمد بن رشيد مع أهلِ المجمعة حِلفًا دفاعيًّا سريًّا ضد الإمام عبد الله بن فيصل الذي وقع في خلافٍ مع أهالي الوشم والمجمعة الذين ثاروا لتحقيق استقلالِهم عن الرياضِ، ولَمَّا تقدمت جيوشُ عبد الله المؤلَّفة من البوادي والحضر في وادي حنيفة، بادر محمَّد بن رشيد إلى نجدة المجمعة بجيشٍ مؤلَّف من بوادي شمر وقبائل حرب، ولَمَّا وصلت قواتُ ابن رشيد بُرَيدة انضَمَّ إليها أميرُ البلدة حسن آل مهنا أبو الخيل، ومعه جند القصيم، وزحفت قواتُ ابن رشيد إلى الزلفي، وكانت قواتُ عبد الله تعسكر في ضرماء، ولَمَّا عرف عبد الله استعدادَ ابن رشيد للقتال، وعرف أنَّ قواته لا تستطيع مجابهةَ قوَّات خصمه، انسحَب إلى الرياض، ودخل ابنُ رشيد المجمعة وعيَّنَ عليها سليمان بن سامي من أهالي حائل نائبًا عنه، وبذلك انضمت المجمعة إلى ابنِ رشيد وانفصلت نهائيًّا عن الرياضِ."},{"id":4706,"title":"ثورة المهدي في السودان  .","date":["العام الهجري :1299","العام الميلادي :1881"],"text":"كانت السودانُ خاضعةً لحكم محمد علي باشا من عام 1237هـ /1821 م. فقامت الحركةُ المهدية في الفترة من 1299 - 1317هـ /1881 - 1899 م؛ لتخليص السودانِ مِن ظلم الحكومة المصرية الواقِعِ على السودانيين؛ حيث أعلن محمد أحمد بن عبد الله أنَّه المهدي المنتَظَر لبعث الأمَّة، فتبعه كثيرون وسيطَرَ على أغلب البلاد، وكان محمد المهدي في سنة 1298 هـ (1881 م) تلقَّب بالمهديِّ المنتظَر، وكتب إلى فقهاء السودان يدعوهم لنصرته. وانبَثَّ أتباعه (ويُعرَفون بالأنصار أو الدراويش) بين القبائل يحضُّون على الجهاد. وسمع بالمهدي رؤوف باشا المصري (حاكم السودان العام) فاستدعاه إلى الخرطوم، فامتنع, فأرسل رؤوف قوَّةً تأتيه به فانقض عليها أتباعُه في الطريق وفتَكُوا بها. وساقت الحكومةُ المصرية جيشًا لقتاله بقيادةِ جيقلر باشا البافاري، فهاجمه نحو 50 ألف سوداني وهزموه. واستولى المهديُّ على مدينة (الأبيض) سنة 1300 هـ وهاجمه جيش مصري ثالث بقيادة هيكس باشا فأُبيدَ. وهاجم بعضُ أتباعه (الخرطوم) وفيها غوردون باشا فقَتَلوه وحملوا رأسَه على حربة سنة 1302 هـ وانقاد السودان كلُّه للمهدي، وكان فَطِنًا فصيحًا قَوِيَّ الحُجَّة، إذا خطَب خَلَب الأسماع, وأقام يجمَعُ الجموع ويجَنِّد الجنود لأجل التغلب على القواتِ المصرية، وأرسل إلى الخديوي والسلطان عبد الحميد وملكة إنكلترا يشعرهم بدولته ومقرِّ سلطنته، وضَرَب النقودَ, ولكِنَّه لم يلبث أن مات بالجدري، وظلَّت حركة المهدية إلى أن قُضي عليها بجيش مصري تحت قيادة إنجليزية سنة 1317 هـ/1899م."},{"id":4707,"title":"الفرنسيون يرتكبون حرب إبادة للجزائريين .","date":["العام الهجري :1299","العام الميلادي :1881"],"text":"اعتمد الجيشُ الفرنسي وقادتُه استراتيجيةَ الحَربِ الشاملة في تعامُلِهم مع الشعب الجزائري، وكان الهَدَفُ المنشود من وراء هذه الاستراتيجية الإسراعَ في القضاء على تلك المقاوَمةِ المُستَميتة التي أظهرَتْها مختلفُ فئات الشعب وعلى جميعِ الأصعدة للهيمنة الأجنبية، وكانت البدايةُ بمذبحةِ البليدة على عهدِ الجنرال كلوزيل، ثمَّ مذبحة العوفية إلى عهدِ الدوق دي ريفيقو، التي كشفت طبيعةَ الإبادة الجماعية، كأسلوبِ سياسةِ فرنسا في الجزائر. وكان أشهَرُ المذابح مذبحةَ غار الفراشيش على يد العقيد بليسييه، ناهيك عمَّا اقترفه المجرم كافينياك في حق قبائل الشلف، وحيث طبَّق طريقة تشبه القتل عن طريق الاختناق، فكانت مجزرةُ قبائل السبيعة. ولم تنحصر عمليةُ إبادة العنصر البشري على منطقةٍ محَدَّدة في الجزائر، بل أصبحت هوايةُ كُلِّ قائد عسكري فرنسي، أوكلت مهمَّة بسط نفوذ فرنسا ورسالتها الحضارية، ويعترف أحدُ القادة العسكريين الفرنسيين في واحدٍ مِن تقاريره، قائلًا: إنَّنا دمَّرنا تدميرًا كاملًا جميع القرى والأشجار والحقول، والخسائِرُ التي ألحقتها فِرقتنا بأولئك السكان لا تُقَدَّر، إذا تساءل البعضُ: هل كان عمَلُنا خيرًا أو شرًّا ؟ فإني أجيبهم بأنَّ هذه هي الطريقة الوحيدة لإخضاعِ السكَّان وحَملِهم على الرحيلِ!!"},{"id":4708,"title":"تأسيس مؤسسة الديون العمومية في الدولة العثمانية .","date":["العام الهجري :1299","الشهر القمري : محرم","العام الميلادي :1881"],"text":"أمرَ السلطان عبد الحميد الثاني بتأسيسِ مؤسسة الديون العمومية في الدولة العثمانية؛ لمعالجة مشكلة ديونِ الدولة، فوُضِعَت إيراداتُ الدولة الرئيسية تحت تصرُّفِ هذه المؤسسة لتسديدِ ديون الدولة التي بلغت 252 مليون قطعة ذهبية، فأسقطت المؤسَّسةُ من ديون الدولة 146 مليونًا. وقد لَعِبَت هذه المؤسسة دورًا في تسديد كثيرٍ مِن ديون الدولة أثناء عهدِ السلطان عبد الحميد الثاني."},{"id":4709,"title":"ضرب الإنجليز لمدينة الإسكندرية إبان الثورة العرابية .","date":["العام الهجري :1299","الشهر القمري : شعبان","العام الميلادي :1882"],"text":"قام الإنجليزُ بضرب مدينة الإسكندرية، وذلك إبَّان الثورة العُرابية حيث حاصر الأسطولُ الإنجليزي مدينةَ الإسكندرية واختلق ذرائِعَ لِضَربِها واحتلالها مساندةً للخديوي توفيق!"},{"id":4710,"title":"مؤتمر الأستانة والتمهيد لاحتلال بريطانيا لمصر .","date":["العام الهجري :1299","الشهر القمري : شعبان","العام الميلادي :1882"],"text":"دعا دي فريسينيه رئيس وزراء فرنسا الدولَ الأوربيةَ الكبرى إلى عقدِ مؤتمر للنظَرِ في المسألة المصرية، فلبَّى الدعوةَ كُلٌّ من إنجلترا وألمانيا وروسيا وإيطاليا والنمسا، وأمَّا تركيا فإنها رفَضَت الحضورَ واحتَجَّت على فكرةِ المؤتمر؛ لأنَّ فيه خَرقًا لسيادتها. عُقِدَ المؤتمر يوم 23 يونيو 1882م، وقرر المؤتمر في جِلسته الأولى إرسالَ مذكِّرة إلى الباب العالي يبلغُه نبأ اجتماعه، ويأسَفُ لعدم انعقاده برئاسةِ وزير الخارجية العثمانية، ويُعرِبُ عن أمله في اشتراك تركيا في اجتماعاته المقبلة. وفى الاجتماع الثاني يوم 25 يونيو 1882م وقبل البدء في المداولات أُبرِمَ العهدُ المشهور بميثاق النزاهة Protocole de Desinteressement وهذا نصه: تتعهَّدُ الحكومات التي يوقِّعُ مندوبوها على هذا القرار بأنَّها في كل اتفاق يحصُلُ بشأن تسوية المسألة المصرية لا تبحَثُ عن احتلالِ أيِّ جزءٍ مِن أراضي مصر، ولا الحصول على امتيازٍ خاصٍّ بها، ولا على نَيلِ امتيازٍ تجاريٍّ لرعاياها لا يخوِّلُ لرعايا الحكومات الأخرى، وقد وقَّعه أعضاء المؤتمر جميعًا. وقرَّر المؤتمر في جلسته الثالثة يوم 27 يونيو وقد انضَمَّت إليه تركيا وأضيف إلى نص الوثيقةِ: وجوبُ التدخُّل في مصر لإخماد الثورة، وأن يُعهَدَ إلى تركيا بهذه المهمَّة بأن تُرسِلَ إلى مصر قوةً كافية من الجند لإعادةِ الأمن والنظام إليها، وأخَذَ يتداول في الجلساتِ التالية في شروط هذا التدخُّل وحدوده، ووضع المؤتمَرُ في جلسته السابعة يوم 6 يوليه سنة 1882 قواعِدَ هذا التدخل وهي: أن يحترم الجيشُ الذي ترسِلُه تركيا مركزَ مِصرَ وامتيازاتها التي نالتها بموجِب الفرمانات السابقة والمعاهدات، وأن يخمد الثورة العسكرية ويعيد إلى الخديوي سُلطتَه، ثم يشرع في إصلاحِ النظم العسكرية في مصر، وأن تكونَ مدة إقامة الجيش التركي في مصر ثلاثة شهورٍ إلا إذا طلب الخديويُّ مَدَّها إلى المدة التي تتَّفِقُ عليها الحكومة المصرية مع تركيا والدول الأوروبية العظمى، ويعَيَّن قوَّادُ هذا الجيش بالاتفاق مع الخديوي، وتكون نفقاتُه على حساب مصر ويعَيَّن مقدارها، بالاتفاق مع مصر وتركيا والدول السِّتِّ العظمى الأوربية. وأقرَّت الدول الأوربية هذه القراراتِ ووافقت على تقديمها إلى الحكومة التركية، فأرسلت إليها ولكِنَّها لم تُقِرَّها."},{"id":4711,"title":"ثورة أحمد عرابي واحتلال الإنجليز لمصر .","date":["العام الهجري :1299","الشهر القمري : رمضان","العام الميلادي :1882"],"text":"كان ضُبَّاط الجيشِ قد نَظَّموا مظاهرة أيَّدها الشعب طالبوا الخديوي توفيق بتشكيلِ وَزارةٍ جديدة وتسَلُّم أحمد عُرابي في الوزارة الجديدة وزارةَ الحربية، واقترحت هذه الوَزارةُ مناقشةَ المجلس للميزانية باستثناءِ القِسمِ المخَصَّص لتسديد الديون للحيلولةِ دون التدخُّلِ الأجنبي، فوافق المجلِسُ واعتمد الخديوي الدستور عام 1299هـ فعارضت إنكلترا وفرنسا ذلك وعَمِلَتا على إثارة الفِتَنِ لإمكانية التدخُّلِ، وكان أحمد عرابي قد سَرَّح عددا من الضباط وأحال بعضَهم إلى المحاكمة، فوجدت إنكلترا البذورَ لزَرعِ الشِّقاقِ، فحَرَّضت الخديوي على رفض تصرُّف الوزارة، فانصاع وعاد الخلافُ وبدأت المناوراتُ الأجنبية؛ حيث جاء الأسطولان الفرنسي والإنجليزي إلى المياهِ المصرية قُربَ الإسكندرية وشجَّعا الخديوي على ضَربِ المتمَرِّدين، فأمر الخديوي بإبعاد أحمد عرابي فنُفِيَ ومَن معه إلى الريف، وفي نفس الوقتِ حَرَّكت إنجلترا أعوانَها من النصارى في الإسكندرية لإحداثِ فِتنةٍ دينيةٍ، فتدخَّلت إنجلترا بالقَصفِ المِدفعيِّ على المدينة، وأعلن أحمد عرابي الثورةَ على الخديوي الذي احتمى في الإسكندرية قريبًا من الإنجليز، وأسرع أحمد عرابي إلى الإسكندرية للدفاع عنها، لكِنَّ الإنجليز استطاعوا احتلالها فانسحب عرابي بجيشِه ونزلت القوات الإنجليزيةُ في الإسماعيلية، وأسرع عرابي لملاقاتِهم والتقى الطرفان عند التل الكبير في رمضان 1299هـ وهُزِمَ أحمد عرابي واحتَلَّ الإنجليز مصرَ، وحاكموا أحمد عرابي ورفاقَه وحُكِمَ عليهم بالقتل، ثم استُبدِلَ بالقتل النَّفيُ المؤَبَّد."},{"id":4712,"title":"دخول القوات البريطانية القاهرة بعد فشل الثورة العرابية .","date":["العام الهجري :1299","الشهر القمري : ذي القعدة","العام الميلادي :1882"],"text":"دخلت القواتُ البريطانيةُ القاهرةَ بعد فَشَلِ الثورة العرابية، وانتصار الإنجليز على القوَّات المصرية بقيادة عُرابي في معركة التل الكبير، وبعدها أقامت القواتُ البريطانية عرضًا عسكريًّا في ميدانِ عابدين، وكان ذلك إيذانًا ببَدءِ الاحتلال البريطاني الذي جَثَم على مصر أكثَرَ مِن سبعين عامًا."},{"id":4713,"title":"تولية الشيخ محمد المهدي العباسي مشيخة الأزهر .","date":["العام الهجري :1299","الشهر القمري : ذي القعدة","العام الميلادي :1882"],"text":"تولَّى الشيخُ محمد المهدي العباسي مشيخةَ الأزهر، وهو الشيخُ الحادي والعشرون في سلسلة مشايخ الأزهر، جمع بين منصبي الإفتاء ومشيخة الأزهر لأوَّلِ مَرَّة، وقد عُرِفَ بالشجاعة والجرأة في الحَقِّ. وهو أوَّلُ من تقلَّدَها من الحنفية، وهو الذي سَنَّ امتحانَ التدريس للعلماء، وجعَلَ لهم قانونًا في ذلك، واجتمع رأيُهم أن يكون المُمتَحِنون ستةً مِن أكابر العلماء، من أهل كلِّ مَذهَبٍ اثنان سوى مذهَبِ الإمام أحمد بن حنبل، وجُعِلَ الامتحان في أحد عشر علمًا: الحديث، والتفسير، والأصول، والفقه، والتوحيد، والنحو، والصرف، والمعاني، والبيان، والبديع، والمنطقوقد عُزِلَ عن المشيخة والإفتاء مرَّتين، ثم أُرجِعَ إليهما."},{"id":4714,"title":"الأسطول البريطاني يقصف الإسكندرية .","date":["العام الهجري :1300","العام الميلادي :1882"],"text":"لما كانت إنجلترا قد بيَّتَت أمرًا فقد أعلنت تشكُّكَها في قدرة الحكومة المصرية الجديدة على حِفظِ الأمن، وبدأت في اختلاقِ الأسباب للتحَرُّش بالحكومة الجديدة، ولم تعجِزْ في البحث عن وسيلةٍ لهدفها، فانتهزت فرصةَ تجديدِ قلاعِ الإسكندرية وتقويةِ استحكاماتها، وإمدادِها بالرِّجال والسلاح، وأرسلت إلى قائدِ حامية الإسكندرية إنذارًا في 24 شعبان 1299 هـ / 10 يوليو 1882 م بوَقفِ عملياتِ التحصين والتجديدِ، وإنزال المدافِعِ الموجودة بها، ولما رفض الخديوي ومجلِسُ وزرائه هذه التهديدات، قام الأسطولُ الإنجليزي في اليوم التالي بضربِ الإسكندرية وتدميرِ قلاعِها، وواصل الأسطولُ القَصفَ في اليوم التالي، فاضطرت المدينةُ إلى التسليم ورَفع الأعلام البيضاء، واضطرَّ أحمد عرابي وزيرُ الدفاع إلى التحَرُّك بقواته إلى كفر الدوَّار، وإعادة تنظيم جيشِه، وبدلًا من أن يقاوِمَ الخديوي المحتلِّين، استقبَلَ في قصر الرمل بالإسكندرية الأميرال بوشامب سيمور قائِدَ الأسطول البريطاني، وانحاز إلى الإنجليز، وجعل نفسَه وسلطته الحكوميَّةَ رهنَ تصَرُّفِهم حتى قبل أن يحتلُّوا الإسكندرية! فأثناء القتالِ أرسل الإنجليز ثُلَّةً من جنودهم ذوي الجاكتات الزرقاء لحماية الخديوي أثناء انتقالِه مِن قصر الرمل إلى قصرِ التين عبر شوارع الإسكندرية المشتَعِلة. ثم أرسل الخديوي إلى أحمد عرابي في كفر الدوار يأمُرُه بالكَفِّ عن الاستعداداتِ الحربيَّةِ، ويحمِّلُه تَبِعة ضَرْبِ الإسكندرية، ويأمُرُه بالمثول لديه في قصر رأس التين؛ ليتلقى منه تعليماتِه."},{"id":4715,"title":"محاكمة زعماء الثورة العرابية في مصر .","date":["العام الهجري :1300","الشهر القمري : محرم","العام الميلادي :1882"],"text":"تشكَّلت المحاكمُ العسكرية لمحاكَمةِ وزير الدفاعِ في الحكومة المصرية الجديدة أحمد عرابي وأنصارِه. وفي يوم 3 ديسمبر 1882م صدرَ الحُكمُ بإعدام عرابي، ومحمود سامي البارودي، وعلي فهمي، وعبد العال حلمي، وغيرهم. واستُبدِلَ بالحُكمِ النفيُ المؤبَّدُ إلى جزيرة سيلان (سيريلانكا حاليًّا) مع تجريدِهم مِن الرُّتَب العسكرية ومصادَرةِ أملاكهم. كما حُكِمَ على محمد عبده وغيرِه بالنَّفيِ خارج مصر، وسُجِنَ الكثير من المصريين. وبذلك انتهت الثورةُ العرابيةُ، وبدأ الاحتلالُ البريطانيُّ لمصر الذي استمر أكثَرَ من سبعين عامًا!"},{"id":4716,"title":"وفاة الأمير عبدالقادر الجزائري قائد حركة المقاومة ضد الفرنسيين .","date":["العام الهجري :1300","الشهر القمري : رجب","العام الميلادي :1883"],"text":"هو الأميرُ عبدُ القادر ناصِرُ الدين بن محيي الدين الحسني المعروف بعبد القادر الجزائري, اشتهرَ بمناهضته للاحتلالِ الفرنسيِّ للجزائر. وُلِدَ في 23 رجب 1222هـ / مايو 1807م، بقرية \"القيطنة\" بوادي الحمام من منطقة معسكر \"المغرب الأوسط\" بالجزائر، ثم انتقل والِدُه إلى مدينة وهران. كان لوالِدِه محيي الدين صِدامٌ مع الحاكِمِ العثماني لمدينة \"وهران\"، وأدَّى هذا إلى تحديدِ إقامة الوالد في بيته، فاختار أن يخرُجَ من الجزائر كلها في رحلةٍ طويلة. وكان الإذنُ له بالخروج لفريضةِ الحَجِّ عام 1241هـ/ 1825م، فخرج مصطحبًا ابنَه عبدالقادر معه، وفي رحلتِهم للحجِّ تعَرَّفوا على الطريقة الشاذلية والقادرية، فالتَقَوا في دمشق وبغداد ببعض شيوخِ الطريقتين وقرؤوا كتُبَهم، ثمَّ عادوا إلى الجزائِرِ عام 1244هـ/ 1828م، فلمَّا تعَرَّضت الجزائرُ لحَملةٍ عسكرية فرنسية شرسة، وتمكَّنَت من احتلال العاصمة. بحث أهالي وعلماء \"غريس\" عن زعيمٍ يأخذ اللواء ويبايعونه على الجهادِ تحت قيادته، استقَرَّ الرأيُ على \"محيي الدين الحسني\" والدِ عبد القادر، وعَرَضوا عليه الأمر، ولكِنَّ الرجل اعتذر عن الإمارة وقَبِلَ قيادة الجهاد، فأرسلوا إلى صاحبِ المغرب الأقصى ليكونوا تحت إمارته، فقَبِلَ السلطان \"عبد الرحمن بن هشام\" سلطان المغرب، وأرسل ابنَ عمه \"علي بن سليمان\" ليكونَ أميرًا على وهران، وقبل أن تستقِرَّ الأمور تدخَّلَت فرنسا مهَدِّدةً سلطان المغرب بالحرب، فانسحَبَ السلطان واستدعى ابنَ عَمِّه فعاد، ولَمَّا كان محيي الدين قد رضِيَ بمسؤولية القيادة العسكرية، والتفَّتْ حوله الجموعُ مِن جديد، وخاصةً أنَّه حقَّق عدَّةَ انتصاراتٍ على العدوِّ، وكان عبد القادر على رأس الجيشِ في كثير من هذه الانتصارات، اقترح الوالِدُ أن يتقدم \"عبد القادر\" لهذا المنصِبِ، فقَبِلَ الحاضرون، وقبل الشابُّ ذلك، وتمت البيعةُ، ولقبه والده بـ \"ناصر الدين\" واقترحوا عليه أن يكون \"سلطانًا\" ولكنه اختار لقب \"الأمير\"، وبذلك خرج إلى الوجود \"الأمير عبد القادر ناصر الدين بن محيي الدين الحسني\"، وكان ذلك في 13 رجب 1248هـ الموافق 20 نوفمبر 1832. فلمَّا بايعه الجزائريون وولَّوه القيامَ بأمرِ الجهاد، نهَضَ بهم، وقاتَلَ الفرنسيين خمسةَ عشر عامًا، ضرب في أثنائها نقودًا سَمَّاها \" المحمَّدية \" وأنشأ معامِلَ للأسلحة والأدوات الحربية وملابِسِ الجند. وعَقَدت فرنسا اتفاقيةَ هدنة معه، وهي اتفاقية \"دي ميشيل\" في عام 1834، وبهذه الاتفاقية اعترفت فرنسا بدولة الأميرِ عبد القادر، وبذلك بدأ الأميرُ يتَّجِهُ إلى أحوال البلاد وتنظيم شؤونها. وقبل أن يمُرَّ عام على الاتفاقية نقضَ القائد الفرنسي الهدنةَ، وناصره في هذه المرة بعضُ القبائل في مواجهةِ الأمير عبد القادر، ونادى الأميرُ في قومِه بالجهادِ ونَظَّم الجميعُ صُفوفَ القتال، حتى نجح في إحراز النصر؛ مما أجبر الفرنسيين على عقد معاهدةِ هُدنةٍ جديدة عُرفت باسم \"معاهد تافنة\" في عام 1837م. وعاد الأميرُ لإصلاح حال بلاده وترميم ما أحدَثَته المعارك بالحصون والقلاع، وتنظيم شؤون البلاد، ثمَّ كرر الفرنسيون نقضَ المعاهدة في عام 1839م، ورأى بعد حينٍ أنَّ من الصواب الجنوحَ للسِّلمِ، وشاور أعيانَ المجاهِدينَ في ذلك، لكِنَّ الفرنسيين أسَرُوه سنة 1263هـ/1847م وأنهَوا دورَه القياديَّ، توفي رحمه الله ليلة 19 رجب عام 1300هـ، 1883م عن عمر يناهز 76 عامًا."}]
